local P = LoreForeverPacks.Begin("LoreForever_Lang_itIT")
P.entries["item:stonetalon-sap"] = {n="Linfa di Petrartiglio",s="Vicino al Lago Mirkfallon e al Picco di Petrartiglio, le bestie della linfa trasportano la Linfa di Petrartiglio. Jin'Zil, il taumaturgo dei Puntascura, la cerca per un infuso destinato ai suoi prigionieri elfi della notte in gabbia.",h="Vicino al Lago Mirkfallon e al Picco di Petrartiglio, le bestie della linfa trasportano la Linfa di...",kw={"jin'zil","malaka'jin","lago mirkfallon","bestia della linfa","picco di petrartiglio","linfa di petrartiglio"},ang={["race:NightElf"]="Un taumaturgo dell'Orda avvelena prigionieri elfi della notte in gabbia con gli elementi naturali di Petrartiglio. È un oltraggio alla natura e a Elune.",["race:Troll"]="Il Taumaturgo Jin'zil mostra come i Puntascura possano trasformare l'ambiente amato da un nemico in un'arma vudù."},sec={{t="Un amaro raccolto",b="Le bestie della linfa vicino al Lago Mirkfallon e al Picco di Petrartiglio trasportano la Linfa di Petrartiglio. Jin'Zil di Malaka'jin la cerca per un infuso che chiama magia della foresta. Intende usarlo sui suoi prigionieri elfi della notte in gabbia, rivoltando contro di loro la natura selvaggia che amano."}},faq={{q="Quali creature portano la Linfa di Petrartiglio?",a="Le bestie della linfa vicino al Lago Mirkfallon e sui pendii verso il Picco di Petrartiglio trasportano la Linfa di Petrartiglio.",al={"dove trovare la linfa di petrartiglio","chi rilascia la linfa di petrartiglio","bestie della linfa"}},{q="Per cosa usa la linfa il Taumaturgo Jin'zil?",a="Jin'Zil mescola la linfa con occhi di corsiero, baffi del crepuscolo e una Scaglia di Drago Fatato per preparare un infuso tossico per i suoi prigionieri elfi della notte in gabbia.",al={"perché jin'zil vuole la linfa","ricetta magia della foresta di jin'zil"}},{q="Qual è il posto migliore per trovare le bestie della linfa?",a="Le bestie della linfa vivono nei boschetti intorno al Lago Mirkfallon e lungo i sentieri verso il Picco di Petrartiglio.",al={"posizione delle bestie della linfa","bestie della linfa del lago mirkfallon"}},{q="La linfa è magica di per sé?",a="La linfa racchiude la vitalità delle alture di Petrartiglio. A Jin'Zil servono mojo dei troll e reagenti specifici per renderla letale.",al={"la linfa di petrartiglio è magica","proprietà della linfa di petrartiglio"}}},fx={b24da591={q="Cos'è la Linfa di Petrartiglio?",a="La Linfa di Petrartiglio è una resina naturale e appiccicosa raccolta dalle bestie della linfa che vagano per le Vette di Petrartiglio, soprattutto nei pressi di luoghi come il Lago Mirkfallon e il Picco di Petrartiglio. È densa, viscosa e colma di essenza naturale grezza: un ingrediente ideale per intrugli e pozioni voodoo che attingono alla singolare magia della natura selvaggia locale.",al={"cos'è la linfa di petrartiglio","oggetto linfa di petrartiglio","informazioni sulla linfa di petrartiglio"}},["7615d27b"]={q="Da dove proviene la Linfa di Petrartiglio?",a="Questa linfa ambrata viene raccolta direttamente dalle bestie della linfa viventi che si aggirano per le foreste e lungo le rive dei laghi delle Vette di Petrartiglio. Non viene fabbricata né distillata da alcun artigiano mortale: è secreta naturalmente da queste bizzarre creature vegetali primordiali.",al={"provenienza della linfa di petrartiglio","dove trovare la linfa","origine della linfa di petrartiglio"}}},fp="14,172,16.241.1,36.94.0,47.141.1,43.96.0,30.123.0"}
P.entries["item:stormpike-banner"] = {n="Stendardo dei Piccatonante",s="Nella Valle d'Alterac, le reclute dell'Alleanza affrontano le arpie per ottenere lo Stendardo dei Piccatonante. La prova si svolge a sud-ovest di Dun Baldar, nella Caverna di Algidala.",h="Nella Valle d'Alterac, le reclute dell'Alleanza affrontano le arpie per ottenere lo Stendardo dei...",kw={"valle d'alterac","dun baldar","haggerdin","caverna di algidala","fregio","banco di prova","stendardo dei piccatonante"},ang={["faction:Alliance"]="Come recluta dell'Alleanza, riportare lo stendardo ti permette di entrare nella Guardia dei Piccatonante e di portarne il fregio in battaglia contro il Clan Lupi Bianchi.",["race:Dwarf"]="Come nano, vedi nello stendardo un simbolo delle rivendicazioni di Forgiardente e della missione del clan Piccatonante: scoprire reliquie del proprio passato in tutta la valle."},sec={{t="Un rito di iniziazione",b="Il Tenente Haggerdin invia i nuovi soldati dell'Alleanza nella Caverna di Algidala, a sud-ovest di Dun Baldar. Prima di affrontare gli orchi del Clan Lupi Bianchi, ogni recluta deve sfidare le arpie e impadronirsi dello Stendardo dei Piccatonante. Chi lo riporta ottiene il grado e il fregio di iniziato nella Guardia dei Piccatonante."}},faq={{q="Dove si trova lo Stendardo dei Piccatonante?",a="Lo Stendardo dei Piccatonante si trova nelle profondità della Caverna di Algidala, a sud-ovest di Dun Baldar, nella Valle d'Alterac.",al={"posizione dello stendardo","dove si trova lo stendardo dei piccatonante","come trovare lo stendardo"}},{q="Perché le reclute devono recuperare lo stendardo?",a="Il Tenente Haggerdin chiede alle reclute dell'Alleanza di dimostrare il proprio coraggio prima di unirsi alle linee di battaglia. Riportando lo stendardo, ottengono il loro primo Fregio dei Piccatonante.",al={"prova di iniziazione","perché prendere lo stendardo","missione di haggerdin"}},{q="Quali minacce proteggono lo stendardo all'interno della caverna?",a="Le feroci arpie del luogo sorvegliano la Caverna di Algidala e attaccano chiunque entri in cerca dello stendardo.",al={"mostri vicino allo stendardo","nemici della caverna di algidala"}},{q="A chi devo riportare lo stendardo una volta trovato?",a="Riporta lo stendardo al Tenente Haggerdin, l'ufficiale dell'Alleanza di stanza fuori dall'ingresso della caverna, nelle Montagne d'Alterac.",al={"consegnare lo stendardo","consegna dello stendardo"}}},fx={["27f01085"]={q="Cos'è lo Stendardo dei Piccatonante?",a="Lo Stendardo dei Piccatonante è un vessillo militare che rappresenta la Guardia dei Piccatonante, la spedizione nanica attualmente impegnata nella guerra in tutta la Valle d'Alterac. Piantato nel cuore delle pericolose Grotte di Ala Gelida, infestate dalle arpie, a sud-ovest di Dun Baldar, lo stendardo funge da prova. Le reclute devono avventurarsi nelle profondità ghiacciate, affrontare le bestie feroci che vi si annidano e recuperare i colori per dimostrare il proprio valore e meritare di indossare il fregio dei Piccatonante.",al={"cos'è lo stendardo dei piccatonante","storia dello stendardo dei piccatonante","informazioni sullo stendardo dei piccatonante"}}},fp="16,139,19.286.0,38.96.0,44.167.0,46.90.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="Richiesta dei Piccatonante",s="Da Loch Modan, il Montanaro Piccatonante invia a Furen Barbalunga un ordine per un pregiato scudo nanico.",h="Da Loch Modan, il Montanaro Piccatonante invia a Furen Barbalunga un ordine per un pregiato scudo nanico.",kw={"fabbro","dun morogh","distretto dei nani","furen barbalunga","richiesta","scudo","piccatonante","roccavento"},ang={["profession:Blacksmithing"]="La richiesta di Piccatonante mostra il prestigio dei maestri fabbricanti d'armature. Committenti di vari regni cercano abili fabbri nanici.",["race:Dwarf"]="In quanto nano, condividi un legame di clan e mestiere con i montanari che difendono Khaz Modan e gli artigiani che vivono all'estero nelle città umane."},sec={{t="Una commissione dal nord",b="Il Montanaro Piccatonante monta la guardia a Loch Modan, dove la frontiera nanica è piena di pericoli. Ha bisogno di uno scudo robusto e non affida un simile lavoro a un fabbro qualunque. Furen Barbalunga è il fabbricante d'armature di cui ammira la maestria. Furen ha lasciato Forgiardente e ora vive tra gli umani nel Distretto dei Nani di Roccavento. Piccatonante presume che una somma principesca lo abbia attirato a sud, così si affida ai viaggiatori per far giungere la sua richiesta attraverso i regni."},{t="Il lignaggio dei Piccatonante",b="Furen Barbalunga riceve la lettera di Piccatonante nel Distretto dei Nani di Roccavento e accetta di forgiare lo scudo. Il clan Piccatonante è fiero e affermato, noto in tutta Khaz Modan per il valore in battaglia e la ricchezza. Notizie e affari dalla sua terra natia nel nord sono benvenuti. Così Furen si mette al lavoro sull'ordine del montanaro."}},faq={{q="Cos'è Richiesta dei Piccatonante?",a="Da Loch Modan, il Montanaro Piccatonante chiede a Furen Barbalunga di forgiare per lui uno scudo pregiato.",al={"cos'è questa lettera","oggetto ordine dei piccatonante","richiesta dei piccatonante"}},{q="Chi ha scritto questa lettera?",a="Il Montanaro Piccatonante ha scritto la lettera. È una sentinella nanica che sorveglia i valichi di Loch Modan e ammira la maestria di Furen Barbalunga.",al={"chi ha inviato la richiesta dei piccatonante","chi l'ha scritta","montanaro piccatonante"}},{q="Dove deve andare questa lettera?",a="La lettera è indirizzata a Furen Barbalunga, presso la sua forgia nel Distretto dei Nani di Roccavento.",al={"dove portare la richiesta dei piccatonante","a chi è indirizzata questa lettera","consegnare la richiesta dei piccatonante"}},{q="Perché Piccatonante ingaggia un fabbro fino a Roccavento?",a="Piccatonante considera impareggiabile la maestria di Furen e non accetterà nessun altro fabbricante d'armature. Furen ha lasciato Forgiardente per lavorare tra gli umani nel sud.",al={"perché furen","perché non forgiare a forgiardente","perché inviare a roccavento"}}},fx={["181a24c8"]={q="Perché Furen Barbalunga vuole la Richiesta dei Piccatonante?",a="Questo ordine scritto commissiona uno scudo nanico finemente lavorato. Furen Barbalunga, un armaiolo che vive nel Distretto dei Nani di Roccavento, apprezza gli affari con il celebre clan dei Piccatonante. Sa che la famiglia è orgogliosa e stimata in tutto Khaz Modan, oltre che abbastanza ricca da pagare profumatamente per un lavoro di qualità eccezionale.",al={"perché furen lo vuole","perché vogliono la richiesta dei piccatonante","perché serve la richiesta dei piccatonante"}}},fp="19,100,21.422.0,18.312.0,28.87.0,22.131.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="Buono per un'Armatura di Roccavento",s="Al Campo di Taglio di Vallevante, Sara Timberlain accetta un Buono per un'Armatura di Roccavento da chi aiuta il regno. Il buono permette di ottenere equipaggiamento realizzato da artigiani incaricati da Roccavento.",h="Al Campo di Taglio di Vallevante, Sara Timberlain accetta un Buono per un'Armatura di Roccavento da chi aiuta...",kw={"buono per un'armatura","armature in stoffa e cuoio","campo di taglio di vallevante","foresta di elwynn","requisizione","sara timberlain","buono per un'armatura di roccavento"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come il Campo di Taglio di Vallevante collega gli insediamenti di frontiera al comando militare di Roccavento."},sec={{t="Requisizioni militari",b="I comandanti di Roccavento rilasciano buoni per armature a chi serve il regno. Mantenere l'ordine nella Foresta di Elwynn mette a dura prova le risorse di Roccavento. Per questo, a volte i comandanti usano questi tagliandi ufficiali al posto dell'equipaggiamento standard presso gli avamposti militari. Un buono attesta il servizio reso dal portatore e consente a un artigiano locale convenzionato di fornire un'armatura su misura."},{t="Approvvigionamento di Vallevante",b="Sara Timberlain e altri artigiani lavorano su commissione per l'Esercito di Roccavento al Campo di Taglio di Vallevante. Il campo si trova sulla frontiera orientale di Elwynn, dove usano materiali locali per realizzare indumenti protettivi di stoffa e cuoio. Presenta lì un buono per ricevere protezioni su misura con cui difendere i boschi circostanti."}},faq={{q="Qual è lo scopo del Buono per un'Armatura di Roccavento?",a="Il Buono per un'Armatura di Roccavento è un buono militare ufficiale destinato a chi aiuta le guardie di Roccavento. Attesta il servizio che hai reso e ti permette di ottenere un'armatura protettiva da un artigiano convenzionato con l'esercito.",al={"cos'è il buono per un'armatura","scopo del buono","uso del buono di roccavento"}},{q="Chi accetta il buono?",a="Sara Timberlain accetta il buono al Campo di Taglio di Vallevante, poco più a est, oltre il fiume, nella Foresta di Elwynn. Fornisce equipaggiamento su misura di stoffa e cuoio in base a un contratto con l'Esercito di Roccavento.",al={"chi accetta il buono","dove consegnare il buono","buono sara timberlain"}},{q="Perché Roccavento usa dei buoni invece di distribuire direttamente le armature?",a="Roccavento usa i buoni perché i suoi posti di guardia periferici possono mancare di magazzini, fucine o sartorie per equipaggiare le reclute sul posto. I comandanti sul campo possono inviare le reclute da artigiani locali come Sara Timberlain, che dispongono di laboratori dedicati.",al={"perché gettoni invece di armature","perché buoni dell'esercito","buoni militari elwynn"}},{q="Che tipo di equipaggiamento fornisce il buono?",a="Il buono permette al portatore di scegliere un pezzo d'armatura di stoffa o cuoio appena realizzato su ordinazione da un fornitore convenzionato con l'esercito.",al={"quale armatura ricevo","ricompense del buono","stoffa o cuoio"}}},fx={e5398b12={q="Cos'è il Buono per un'Armatura di Roccavento?",a="È un buono militare ufficiale emesso per conto dell'Esercito di Roccavento. Anziché trasportare ingombranti armature protettive attraverso la Foresta di Elwynn, i comandanti locali rilasciano questo gettone come garanzia di requisizione, che dà al portatore il diritto di ritirare un'armatura di stoffa o di cuoio appena realizzata presso un armaiolo autorizzato.",al={"cos'è il buono per un'armatura di roccavento","buono per un'armatura","cos'è il buono"}},["3e7f2980"]={q="Da dove proviene il Buono per un'Armatura di Roccavento e chi l'ha creato?",a="Il buono viene emesso per conto dell'Esercito di Roccavento dalla Guardia Thomas, presso il suo avamposto vicino al ponte orientale di Elwynn, e assegnato ai difensori che dimostrano astuzia e valore. È munito dell'autorità dell'esercito del regno e incarica gli artigiani locali di rifornire le reclute a spese della corona.",al={"chi ha creato il buono per l'armatura","da dove proviene il buono","chi rilascia il buono per l'armatura"}},["618263b5"]={q="Perché Sara Timberlain vuole il Buono per un'Armatura di Roccavento?",a="L'Esercito di Roccavento ha incaricato Sara Timberlain di equipaggiare le proprie reclute e i volontari con armature di stoffa e di cuoio. Prima di consegnare i suoi manufatti, esige il buono come prova ufficiale dell'autorizzazione, così da garantire che le scorte del regno vadano solo ai difensori riconosciuti.",al={"perché sara vuole il buono","perché portare il buono a vallenera","perché serve il buono per l'armatura"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Risposta di Mantoforte a Solomon",s="Da Guardiacolle, Gryan Stoutmantle fa sapere a Borgolago che non può inviare soldati alle Montagne Crestarossa.",h="Da Guardiacolle, Gryan Stoutmantle fa sapere a Borgolago che non può inviare soldati alle Montagne...",kw={"gryan","borgolago","lettera","magistrato solomon","messenger to westfall","the people's militia","crestarossa","solomon","stoutmantle","marche occidentali"},ang={["faction:Alliance"]="Per l'Alleanza, questa lettera mostra gli insediamenti periferici che si implorano a vicenda di prestare aiuto, mentre la capitale trattiene le proprie forze.",["race:Human"]="Come difensore umano, vedi le Marche Occidentali e Crestarossa lottare per sopravvivere senza le guardie reali di Roccavento."},sec={{t="Una Supplica Respinta",b="Il Magistrato Solomon di Borgolago chiede aiuto a Guardiacolle mentre gli orchi Roccianera e gli gnoll incalzano la sua cittadina. Gryan Stoutmantle risponde per iscritto e piange le perdite di Borgolago. Eppure le Marche Occidentali affrontano una guerra tutta loro. La People's Militia si è formata dopo che la Corona ha ritirato la sua guarnigione, e ora contadini e volontari combattono da soli la Fratellanza dei Defias. Le forze di Stoutmantle subiscono già gravi perdite e sono allo stremo, senza uomini da inviare su un'altra frontiera abbandonata."},{t="L'Abbandono del Regno",b="Crestarossa e le Marche Occidentali condividono una sorte cupa. La corte reale di Roccavento le ha abbandonate entrambe. Re Varian Wrynn è scomparso, e l'esercito permanente del regno viene misteriosamente tenuto lontano dai confini delle province. Le cittadine periferiche devono formare corpi di guardia volontari o perire. Solomon riceve la risposta sigillata e comprende che nessuna delle due cittadine può salvare l'altra. Il regno si sgretola mentre la capitale rimane in silenzio."}},faq={{q="Cosa c'è scritto nella risposta di Stoutmantle?",a="Gryan Stoutmantle scrive che le Marche Occidentali combattono una guerra brutale contro la Fratellanza dei Defias e hanno perso l'esercito di Roccavento, come Crestarossa. Piange i difensori caduti, ma respinge la richiesta di rinforzi del Magistrato Solomon.",al={"cosa dice la lettera","contenuto lettera stoutmantle","testo risposta a solomon"}},{q="Perché Solomon ha chiesto aiuto alle Marche Occidentali in primo luogo?",a="Borgolago subisce pesanti assalti da parte degli gnoll e degli orchi Roccianera. L'appello del Magistrato Solomon al Generale Marcus Jonathan a Roccavento non ha portato truppe, così chiede aiuto alla People's Militia, oltre Elwynn, anch'essa impegnata a difendere la frontiera.",al={"perché chiedere alle marche occidentali","solomon chiede a stoutmantle","perché borgolago ha chiesto della milizia"}},{q="Perché la People's Militia non può risparmiare truppe?",a="La People's Militia è un esercito di volontari che lotta per difendere Guardiacolle e le pianure circostanti dalla Fratellanza dei Defias. Le perdite aumentano ogni giorno e, senza il sostegno dell'esercito regolare, inviare combattenti a Borgolago lascerebbe le Marche Occidentali indifese.",al={"perché la milizia non aiuta","le marche occidentali possono aiutare crestarossa","perché rifiutare solomon"}},{q="Perché l'Esercito di Roccavento non protegge queste cittadine?",a="Nessuno nelle due cittadine sa perché l'esercito di Roccavento sia assente. Stoutmantle scrive che Roccavento ha ritirato le sue truppe e lasciato indifese le Marche Occidentali, mentre Solomon si chiede cosa possa tenere l'esercito lontano dalla sua gente. Entrambe le regioni si affidano ai volontari locali.",al={"dov'è l'esercito di roccavento","perché roccavento non aiuta","diserzione di roccavento"}}},fx={["399f6159"]={q="Cos'è la Risposta di Mantoforte a Solomon?",a="È un dispaccio ufficiale scritto da Gryan Stoutmantle, comandante della Milizia Popolare a Guardiacolle, e indirizzato al Magistrato Solomon a Crestarossa. La lettera comunica la cupa notizia che le Marche Occidentali sono travolte da una guerra disperata contro la Fratellanza dei Defias e non possono inviare soldati o risorse in aiuto a Borgolago.",al={"cos'è la risposta di mantoforte","lettera di mantoforte a solomon","risposta di gryan a borgolago"}},["945d8c3a"]={q="Da dove proviene la Risposta di Mantoforte a Solomon e chi l'ha scritta?",a="È stata scritta di persona da Gryan Stoutmantle a Guardiacolle, nelle Marche Occidentali. Dopo aver letto l'appello del Magistrato Solomon per ottenere rinforzi, Stoutmantle ha redatto la risposta e l'ha affidata a te, perché la portassi attraverso il regno fino alle Montagne Crestarossa.",al={"chi ha scritto la risposta di mantoforte","chi ha redatto la risposta di mantoforte a solomon","da dove proviene la risposta di mantoforte"}},c46920a1={q="Perché qualcuno vuole la Risposta di Mantoforte a Solomon?",a="Il Magistrato Solomon attende questa risposta a Borgolago, nella speranza di ottenere aiuti militari per respingere l'invasione degli orchi del clan Roccianera che minaccia le Montagne Crestarossa. Ha bisogno della risposta di Stoutmantle per sapere se la Milizia Popolare può accorrere in difesa di Borgolago o se la città dovrà affrontare i pericoli da sola.",al={"chi vuole la risposta di mantoforte","perché consegnare la lettera di mantoforte","perché portare la risposta a solomon"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="Polvere dall'Odore Strano",s="A Loch Modan, la Polvere dall'Odore Strano ha allarmato gli ingegneri che indagano su alcuni sabotaggi. Il Capo Ingegnere Hinderweir teme che sia esplosiva e cerca il parere di un esperto.",h="A Loch Modan, la Polvere dall'Odore Strano ha allarmato gli ingegneri che indagano su alcuni sabotaggi.",kw={"a dark threat looms","ashlan pietroscura","dun modr","hinderweir","loch modan","polvere dall'odore strano","viadotto di thandol"},ang={["profession:Engineering"]="In quanto ingegnere, potresti riconoscere l'odore sulfureo delle miscele esplosive instabili, diverse dalle formule standard usate negli avamposti minerari dell'Alleanza.",["race:Dwarf"]="In quanto nano, sai che proteggere le strutture in pietra e i bacini idrici di Loch Modan è di vitale importanza. Qualsiasi indizio della presenza di esplosivi nemici rappresenta una crisi immediata per il clan."},sec={{t="Una scoperta volatile",b="La Polvere dall'Odore Strano è stata trovata tra i segni di sabotaggio delle infrastrutture di Loch Modan. Il Capo Ingegnere Hinderweir teme che sia un esplosivo appositamente formulato, diverso dalla polvere solitamente usata nelle miniere. Non riesce a identificarne la miscela o l'origine e non intende maneggiarla personalmente. Anche una piccola scintilla potrebbe causare un disastro."},{t="La strada verso nord",b="Il Capo Ingegnere Hinderweir invia campioni attraverso la Porta di Algaz fino alle Paludi Grigie perché vengano esaminati. Ashlan Pietroscura, un esperto artificiere del reggimento di stanza a Dun Modr vicino al Viadotto di Thandol, dovrà esaminare i granelli e determinare quale tipo di esplosione stiano preparando i sabotatori."}},faq={{q="Cos'è la Polvere dall'Odore Strano?",a="La Polvere dall'Odore Strano è un residuo chimico sospetto trovato a Loch Modan durante un'indagine sui sabotaggi locali. Il suo forte odore e la sua composizione inducono gli ingegneri nanici a sospettare che sia esplosiva.",al={"cos'è la polvere dall'odore strano","cos'è questa polvere","polvere loch modan"}},{q="Perché il Capo Ingegnere Hinderweir vuole farla esaminare?",a="Il Capo Ingegnere Hinderweir sospetta che la polvere sia un esplosivo speciale. Ha bisogno di un esperto di demolizioni pesanti per comprendere la minaccia che incombe su Loch Modan.",al={"perché esaminare la polvere","hinderweir polvere","a chi serve questa polvere"}},{q="Chi può identificare la polvere?",a="Il Capo Ingegnere Hinderweir incarica i viaggiatori di portare il campione ad Ashlan Pietroscura, un esperto artificiere del reggimento di stanza a Dun Modr vicino al Viadotto di Thandol.",al={"chi identifica la polvere","dove porto la polvere","esperto di polvere"}},{q="Perché trasportare la polvere è pericoloso?",a="La polvere potrebbe essere instabile e trasportarla significa attraversare la Porta di Algaz e percorrere le strade paludose e ostili delle Paludi Grigie.",al={"la polvere è pericolosa","perché è pericolosa"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="Cassa con Marchio Strano",s="A Rivafosca, le rune della Cassa con Marchio Strano rimandano a carichi naga arenati su tartarughe di mare morte. La loro presenza suggerisce che le tartarughe non siano giunte a riva per caso.",h="A Rivafosca, le rune della Cassa con Marchio Strano rimandano a carichi naga arenati su tartarughe di mare...",kw={"auberdine","carro","rivafosca","greymist","gwennyth bly'leggonde","naga","tartaruga di mare","cassa con marchio strano"},ang={["class:Priest"]="Come sacerdote, aiuti gli studiosi del Temple of the Moon ad Auberdine a mettere al sicuro le reliquie del litorale mentre si adoperano per proteggere la costa dalla corruzione marina.",["race:NightElf"]="Le casse di rifornimenti naga legate alle tartarughe di mare autoctone lungo Rivafosca avvertono i kaldorei che i loro antichi consanguinei mutati stanno avanzando verso riva dal Great Sea."},sec={{t="Trofei degli Abissi",b="Tartarughe di mare morte e altre creature marine si arenano sulle spiagge di Rivafosca. Alcune hanno imbracature spezzate e carri legati ai gusci. Tra i rottami giacciono casse sigillate contrassegnate da rune estranee e sinuose. I murloc Greymist si rifugiano nelle gabbie toraciche vuote e nei carri sfasciati, nutrendosi delle carcasse e sorvegliando ciò che resta."},{t="Prove dell'Espansione dei Naga",b="Gwennyth Bly'leggonde, una ricercatrice del Temple of the Moon ad Auberdine, riconosce i marchi. La scrittura e i carri appartengono ai naga, che usano tartarughe giganti per trasportare rifornimenti ed equipaggiamento da guerra sulla terraferma. Le casse attestano la presenza dei naga lungo le coste settentrionali e suggeriscono che forse stiano conducendo le loro cavalcature a sud, verso Valtetra. Il sacerdozio di Auberdine invia le reliquie a Darnassus perché vengano studiate."}},faq={{q="Dove si trova la Cassa con Marchio Strano?",a="La cassa si trova in un carro abbandonato legato a una tartaruga di mare morta sulla costa di Rivafosca. I murloc Greymist si nutrono vicino alle carcasse e sorvegliano ciò che resta.",al={"dove trovare la cassa con marchio strano","posizione della cassa","cassa del carro su tartaruga"}},{q="Chi ha creato la Cassa con Marchio Strano?",a="I naga hanno realizzato la cassa e le sue iscrizioni. Legano carri a tartarughe di mare vive per trasportare provviste, armi ed equipaggiamento dalle profondità oceaniche alle coste di Kalimdor.",al={"chi ha creato la cassa","marchi sulla cassa","rune della cassa","cosa sono i marchi"}},{q="Chi vuole questa cassa ad Auberdine?",a="Gwennyth Bly'leggonde, una ricercatrice del Temple of the Moon ad Auberdine, raccoglie la cassa per studiare gli strani spiaggiamenti e la minaccia naga.",al={"a chi devo consegnarla","consegna della cassa","chi vuole la cassa"}},{q="Perché le tartarughe marine trasportavano queste casse?",a="I naga usano tartarughe di mare giganti per trasportare rifornimenti ed equipaggiamento da guerra sulla terraferma, con imbracature e carri legati al dorso. Gwennyth sospetta che una tartaruga sia stata uccisa mentre si dirigeva a sud, forse verso Valtetra.",al={"perché le tartarughe hanno casse","carri su tartarughe","perché le tartarughe sono imbragate"}},{q="Cosa succede alla cassa dopo averla consegnata a Gwennyth?",a="Gwennyth Bly'leggonde invia la cassa e i risultati delle ricognizioni costiere al Temple of the Moon a Darnassus, dove le autorità degli Elfi della Notte possono studiare l'estensione della presenza naga.",al={"dove va la cassa","cassa inviata a darnassus"}}},fx={["981461f5"]={q="Cos'è la Cassa con Marchio Strano?",a="È un carico rinvenuto in un carro sgangherato legato al guscio di una Beached Sea Turtle lungo la costa di Rivafosca. Decorata con rune insolite, la cassa è una prova tangibile del trasporto marittimo organizzato lungo la costa; è stata abbandonata dopo la morte della creatura che la trasportava e poi invasa dagli spazzini.",al={"cos'è la cassa marchiata","cos'è la cassa con marchio strano","oggetto cassa con marchio strano"}},b4ce745f={q="Perché Gwennyth Bly'leggonde vuole la Cassa con Marchio Strano?",a="Gwennyth Bly'leggonde cerca la cassa per conto del The Temple of the Moon, per indagare sul motivo per cui enormi creature marine si arenano sulle coste di Rivafosca. Decifrare i marchi conferma che le tartarughe venivano imbrigliate e usate come bestie da soma dai naga ostili, che trasportavano rifornimenti verso l'entroterra; Gwennyth invia direttamente agli studiosi di Darnassus gli indizi raccolti.",al={"perché gwennyth vuole la cassa","perché consegnare la cassa con marchio strano","a cosa serve la cassa marchiata"}}},fp="20,168,20.323.0,26.395.1,40.154.0,34.171.0,32.145.0,46.218.0,52.162.0"}
P.entries["item:strigid-owl-feather"] = {n="Piuma di Gufo Strigido",s="Tra i rami di Teldrassil, i gufi lasciano Piume di Gufo Strigido pronte da raccogliere. Zenn Empiazampa le cerca per i suoi traffici segreti.",h="Tra i rami di Teldrassil, i gufi lasciano Piume di Gufo Strigido pronte da raccogliere.",kw={"dolanaar","reagenti","strigid owl","piuma di gufo strigido","strigid screecher","teldrassil","zenn empiazampa"},ang={["class:Druid"]="Come druido, tieni in grande considerazione i cacciatori alati di Teldrassil. Vedere le loro piume raccolte con falsi pretesti per ricavarne reagenti sospetti può turbarti.",["race:NightElf"]="Come elfo della notte, sai che i gufi di Teldrassil sono creature di Elune. Lo sfruttamento che ne fa Zenn Empiazampa è un insulto al bosco sacro."},sec={{t="Piumaggio della foresta e loschi affari",b="Gufi strigidi e striditori cacciano in tutta Crown of the Earth, lasciando piume e piumino sul suolo della foresta. Fuori da Dolanaar, il satiro rinnegato Zenn Empiazampa manda viaggiatori inesperti lungo la strada da Vallombra. Chiede loro di raccogliere piume strigidi, Seta di Ragno e zanne di scattante notturno per i suoi loschi affari."}},faq={{q="Dove posso trovare le Strigid Owl Feather?",a="Gufi strigidi e striditori strigidi vivono nei boschi attorno a Dolanaar e in tutta Teldrassil. Puoi raccogliere le loro piume in quei luoghi.",al={"posizione delle piume","dove si trovano le strigid owl feathers","farm di piume di gufo"}},{q="Chi vuole le Strigid Owl Feather?",a="Zenn Empiazampa, un satiro lungo il sentiero che conduce a Dolanaar, ti chiede di raccogliere le piume insieme a webwood silk e zanne di scattante notturno.",al={"chi ha bisogno di piume di gufo","consegna delle piume di gufo","zenn piuma di gufo"}},{q="A cosa servono le piume a Zenn Empiazampa?",a="Zenn dice che le piume sono reagenti per i suoi affari segreti nella foresta. Si diverte anche a ingannare reclute ignare perché facciano il lavoro sporco per lui.",al={"perché zenn vuole le piume","scopo dei reagenti di zenn"}}},fx={c56fcaa2={q="Che cos'è la Piuma di Gufo Strigido?",a="La Piuma di Gufo Strigido è una penna raccolta dai rapaci gufi strigidi che vivono tra i rami di Teldrassil. In apparenza è una semplice piuma, ma costituisce un potente reagente naturale per chi si dedica all'artigianato, all'alchimia o a riti silvestri più oscuri.",al={"piuma di gufo strigido","cos'è la piuma di gufo strigido","piuma di gufo di teldrassil"}},["91562481"]={q="Da dove proviene la Piuma di Gufo Strigido?",a="Queste piume vengono raccolte direttamente dai gufi strigidi e dai gufi striduli che nidificano nelle foreste di Teldrassil, soprattutto nei dintorni di Dolanaar. Sono materiali biologici naturali, persi o sottratti ai predatori alati della foresta: crescono in natura e non sono create da mani mortali.",al={"da dove vengono le piume di gufo strigido","provenienza della piuma di gufo strigido","chi ha creato la piuma di gufo strigido"}}},fp="19,121,32.327.1,38.133.0,31.125.0,45.147.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Osso Robusto delle Fauci di Drago",s="All'Accampamento Zannarabbiosa, gli orchi rinnegati Fauce del Drago forniscono tibie robuste per le armature. A Sepulcra, Velora Nitely ne ha bisogno per creare la struttura dei gambali per i guerrieri.",h="All'Accampamento Zannarabbiosa, gli orchi rinnegati Fauce del Drago forniscono tibie robuste per le armature.",kw={"accampamento zannarabbiosa","osso delle fauci di drago","gambali","osso robusto delle fauci di drago","sepulcra","velora nitely","paludi grigie"},ang={["class:Warrior"]="Come guerriero, metti alla prova a mani nude le dense ossa degli orchi e raccogli pezzi per creare la struttura di un'armatura su misura. Il lavoro dimostra la tua forza fisica.",["race:Undead"]="Come non morto, vedi il pragmatismo dei Reietti nell'uso che Velora Nitely fa delle ossa nemiche per equipaggiare i campioni della Dark Lady."},sec={{t="Ossa per il telaio",b="Velora Nitely ha bisogno di ossa abbastanza forti da sopportare le sollecitazioni di gambali brutali. Gli orchi rinnegati Fauce del Drago dell'Accampamento Zannarabbiosa, nelle Paludi Grigie centrali, hanno un'ossatura massiccia, e le loro tibie possono rinforzare l'armatura. Ogni osso viene messo alla prova a mani nude. I guerrieri tengono solo quelli che resistono senza spezzarsi."}},faq={{q="Cosa rende questi stinchi robusti rispetto a quelli normali?",a="Gli orchi Fauce del Drago hanno un'ossatura massiccia, ma le fratture possono rendere un osso troppo fragile per un'armatura. Un guerriero piega ogni tibia a mani nude e tiene solo quelle che resistono senza spezzarsi.",al={"perché stinchi robusti","resistenza ossa fauce del drago","testare gli stinchi"}},{q="Chi vuole i Sturdy Dragonmaw Shinbones?",a="Velora Nitely, un'artigiana di armature di Sepulcra, vuole gli Sturdy Dragonmaw Shinbones. Li usa come montanti per la struttura di gambali brutali destinati ai guerrieri più promettenti dell'Orda.",al={"chi ha bisogno di stinchi","ossa di velora nitely","consegnare stinchi delle fauci di drago"}},{q="Dove vengono raccolte queste ossa?",a="Le ossa provengono dagli orchi rinnegati Fauce del Drago nelle Paludi Grigie, a sud degli Altopiani d'Arathi. Si trovano soprattutto all'Accampamento Zannarabbiosa, sulle colline a sud-ovest del Viadotto di Thandol.",al={"dove trovare stinchi delle fauci di drago","posizione stinco delle fauci di drago","ossa di zannarabbiosa"}},{q="Perché Velora Nitely usa ossa di orco per le armature?",a="I fabbri Reietti usano ossa, tendini e metallo per creare equipaggiamento da guerra resistente. Il clan Fauce del Drago è ostile all'Orda di Thrall, quindi i fabbri Reietti ne usano i resti come materiale resistente per le loro creazioni.",al={"perché ossa di orco","armature d'ossa dei reietti","creazione con ossa di velora"}}},fp="25,163,19.292.0,58.180.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Lettera di Sully Balloo",s="Sotto il Viadotto di Thandol, la Lettera di Sully Balloo reca l'addio di un soldato a Sara, a Forgiardente. Le sue parole custodiscono l'amore che provava per lei nei suoi ultimi giorni.",h="Sotto il Viadotto di Thandol, la Lettera di Sully Balloo reca l'addio di un soldato a Sara, a Forgiardente.",kw={"altopiani d'arathi","forgiardente","lettera","sara balloo","sully balloo","viadotto di thandol","busta fradicia","paludi grigie"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi portare gli ultimi pensieri di un soldato caduto alla sua vedova, affinché non vengano dimenticati sotto il ponte.",["race:Dwarf"]="Come nano, puoi vedere in questa lettera il sacrificio dei comuni montanari e soldati che sorvegliano gli alti ponti e i passi montani di Khaz Modan."},sec={{t="Un ultimo addio sotto le onde",b="Sotto il Viadotto di Thandol, la strada dalle Paludi Grigie prosegue verso gli Altopiani d'Arathi. Sotto le acque impetuose giacciono incastrati i resti scheletrici di un nano. Nella sua stretta riposa una fragile busta impregnata d'acqua. Al suo interno, la lettera inizia così: «Mia cara Sara...» La pergamena è stata danneggiata dall'acqua, ma l'inchiostro testimonia ancora la premura del difensore nanico nei suoi ultimi giorni o nelle sue ultime ore. Non fece mai ritorno a Forgiardente."},{t="Consegna a Forgiardente",b="A Forgiardente, Sara Balloo ha atteso senza sapere cosa fosse accaduto al marito dopo la sua partenza per la guerra. Gli ultimi pensieri di Sully le danno una triste certezza e confermano il timore che portava dentro: è morto lontano da casa, sotto le correnti del passaggio settentrionale. La sua devozione le giunge attraverso le sue stesse parole."}},faq={{q="Dove si trova la Lettera di Sully Balloo?",a="Trovi la lettera in una busta impregnata d'acqua, stretta nella mano di un nano scheletrico sotto le acque del Viadotto di Thandol, tra le Paludi Grigie e gli Altopiani d'Arathi.",al={"posizione della lettera","dove si trova la lettera di sully","dove trovare la lettera di sully balloo"}},{q="Chi era Sully Balloo?",a="Sully Balloo era un soldato nanico morto mentre difendeva il passaggio settentrionale vicino al Viadotto di Thandol. I suoi resti giacciono incastrati sotto le correnti del fiume.",al={"chi è sully balloo","storia di sully balloo","cosa è successo a sully"}},{q="A chi è indirizzata la lettera?",a="La lettera è indirizzata alla signora Sara Balloo, moglie di Sully, che vive a Forgiardente.",al={"a chi va la lettera","chi è sara balloo","dove consegnare la lettera di sully"}},{q="Cosa succede quando consegni la lettera a Sara Balloo?",a="Quando Sara Balloo legge la lettera, apprendere che suo marito è morto sotto le acque le spezza il cuore. Può ancora leggere le ultime parole che lui le scrisse con amore.",al={"reazione di sara balloo","consegna della lettera","completamento missione lettera di sully"}}},fx={efe638b9={q="Che cos'è la Lettera di Sully Balloo?",a="È una lettera tenera e straziata dalla guerra, scritta con grande cura da un soldato nano di nome Sully Balloo. Ritrovata intatta sotto le acque gelide del Viadotto di Thandol, contiene le ultime parole affettuose che scrisse alla moglie a Forgiardente prima di morire in battaglia.",al={"cos'è la lettera di sully","lettera di sully balloo","informazioni sulla lettera di sully balloo"}},b8624ec6={q="Da dove proviene la Lettera di Sully Balloo e chi l'ha scritta?",a="La lettera fu scritta da Sully Balloo, un soldato dell'Alleanza impegnato in prima linea al Viadotto di Thandol, tra le Paludi e gli Altopiani d'Arathi. È sopravvissuta sott'acqua, dentro una busta intrisa d'acqua stretta tra le mani dei suoi resti sommersi sotto il grande ponte.",al={"chi ha scritto la lettera di sully balloo","da dove viene la lettera di sully","autore della lettera di sully balloo"}},b54d6872={q="Perché qualcuno vuole la Lettera di Sully Balloo?",a="La destinataria, Sara Balloo, vive a Forgiardente senza sapere della tragica morte del marito. Consegnare la lettera esaudisce l'ultimo desiderio di un soldato caduto e offre una dolceamara conclusione a una vedova in lutto, in attesa di notizie del suo amato.",al={"perché consegnare la lettera di sully balloo","chi vuole la lettera di sully","perché portare la lettera a sara balloo"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sunscorched-shell"] = {n="Conchiglia Sbiancata dal Sole",s="Sotto Covoalto, il calore del deserto indurisce i gusci delle uova di viverna. L'armaiolo Mathiel, a Darnassus, li usa per creare una lacca per le maglie metalliche.",h="Sotto Covoalto, il calore del deserto indurisce i gusci delle uova di viverna.",kw={"darnassus","furen barbalunga","covoalto","armatura in maglia","mathiel","conchiglia sbiancata dal sole","millepicchi","viverna"},ang={["class:Warrior"]="Come guerriero in cerca della protezione di un'armatura di maglia, puoi aiutare Mathiel a raccogliere gusci d'uovo resistenti per creare armature rinforzate.",["profession:Blacksmithing"]="Come fabbro, puoi vedere come i fabbri esperti usano rivestimenti minerali naturali per creare una lacca protettiva per le armature di maglia."},sec={{t="Nidate del deserto",b="Le viverne di Covoalto depongono le uova sui pinnacoli degli altopiani del sud di Kalimdor. Sotto i loro posatoi, i gusci abbandonati cuociono al sole del deserto e ai venti roventi. I loro fragili resti conservano una resistenza naturale che attira l'attenzione degli artigiani esperti."},{t="La lacca di un artigiano",b="A Darnassus, l'armaiolo Mathiel studia metodi sperimentati per la prima volta dal suo collega, il fabbro nano Furen Barbalunga. Trasforma i gusci in una lacca pregiata per le armature di maglia. Il rivestimento rinforza le maglie metalliche senza appesantire chi le indossa."}},faq={{q="Dove si trovano i Sunscorched Shells?",a="Puoi trovarli sotto i nidi di viverna sparsi per Covoalto, un alto altopiano che si erge dal fondo del canyon nella parte occidentale di Millepicchi.",al={"posizione di conchiglia sbiancata dal sole","dove trovare le conchiglie","conchiglie di covoalto"}},{q="Da quale creatura provengono questi gusci?",a="Sono gusci d'uovo rotti delle viverne di Covoalto che nidificano in cima agli altopiani di Millepicchi.",al={"cosa ha deposto queste uova","uova di viverna","origine delle conchiglie"}},{q="Perché Mathiel vuole i Sunscorched Shells?",a="Mathiel vuole provare i metodi di forgiatura delle armature scoperti da Furen Barbalunga. Trasforma i gusci induriti in una lacca resistente che rinforza le maglie metalliche.",al={"conchiglie di mathiel","a cosa servono le conchiglie","lacca per armature"}},{q="Chi è Furen Barbalunga e come è coinvolto?",a="Furen Barbalunga è un collega di Mathiel nella lavorazione del ferro e opera nel Distretto dei Nani di Roccavento. I suoi esperimenti con reagenti insoliti e metodi di indurimento hanno spinto Mathiel a provare una lacca ricavata dai gusci di viverna.",al={"collegamento con furen","conchiglie di furen barbalunga"}}},fx={f589915a={q="Che cos'è la Conchiglia Sbiancata dal Sole?",a="La Conchiglia Sbiancata dal Sole è il guscio resistente e abbandonato di un uovo di viverna di Covoalto. Trovati cotti dal sole impietoso di Millepicchi, sotto gli alti nidi di queste creature, questi gusci possiedono una notevole robustezza naturale che li rende preziosi per gli abili armaioli.",al={"cos'è la conchiglia sbiancata dal sole","oggetto conchiglia sbiancata dal sole","guscio d'uovo sbiancato dal sole"}}},fp="17,131,15.237.0,21.234.0,35.126.0,40.102.0,41.153.0,46.211.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Progetti del Super Mietitore 6000",s="Nella Landa di Tagliavento, i rivali goblin bramano i Progetti del Super Mietitore 6000 della S.P.R. & Co. Mostrano come costruire il taglialegna meccanizzato impiegato nelle Vette di Petrartiglio, sotto la supervisione dell'ingegnere gnomo Gerenzo Wrenchwhistle.",h="Nella Landa di Tagliavento, i rivali goblin bramano i Progetti del Super Mietitore 6000 della S.P.R.",kw={"progetti","gerenzo","sputavalvole","petrartiglio","super reaper 6000","s.p.r. & co.","landa di tagliavento","ziz fizziks"},ang={["profession:Engineering"]="Come ingegnere, puoi vedere come i precisi schemi gnomeschi di Gerenzo lascino perplessi i comuni armeggiatori, mentre gli sgherri goblin della compagnia mettono in funzione i macchinari.",["race:Gnome"]="Come gnomo, puoi riconoscere l'ingegno di Gerenzo Wrenchwhistle nei progetti. Persino la S.P.R. & Co. si affida a un ingegnere gnomo per progettare i suoi complessi macchinari pesanti."},sec={{t="Spionaggio industriale nella Landa di Tagliavento",b="Gli operatori della S.P.R. & Co. trasportano i Progetti del Super Mietitore 6000 attraverso la Landa di Tagliavento. I progetti mostrano come costruire gli enormi mietitori di legname meccanizzati con cui la compagnia abbatte intere foreste. Gli ingegneri goblin mal sopportano che Gerenzo, uno gnomo, sia stato messo a capo della progettazione. Dopo che la compagnia ha estromesso l'ingegnere goblin Ziz Fizziks, Sputavalvole lo ha assunto per rubare i progetti. Eppure, decifrare le fitte ed eccentriche annotazioni di Gerenzo è difficile quasi quanto impadronirsi dei progetti con la forza."}},faq={{q="Cos'è il Super Reaper 6000?",a="Il Super Reaper 6000 è un enorme taglialegna meccanizzato costruito per il disboscamento a raso della S.P.R. & Co. nelle Vette di Petrartiglio.",al={"cos'è il super reaper","macchina super reaper"}},{q="Chi ha progettato il Super Reaper 6000?",a="Gerenzo Wrenchwhistle, un ingegnere gnomo, ha realizzato i progetti sotto la supervisione della S.P.R. & Co. dopo essere stato assunto per dirigere le attività meccaniche della compagnia nella Landa di Tagliavento. La sua nomina ha suscitato l'ira dei meccanici goblin locali.",al={"chi ha creato i progetti","chi ha progettato il super reaper"}},{q="Perché Ziz Fizziks vuole questi progetti?",a="Dopo che la S.P.R. & Co. ha estromesso Ziz Fizziks, Sputavalvole lo ha assunto per rubare i progetti. Ziz vuole dimostrare il proprio valore e il proprio genio meccanico al nuovo capo.",al={"perché ziz vuole i piani","chi vuole i progetti"}},{q="Chi possiede i progetti nella Landa di Tagliavento?",a="Gli operatori della Venture Co. portano con sé gli schemi su carta e supervisionano i macchinari e il disboscamento in tutta la Landa di Tagliavento.",al={"dove si trovano i progetti","chi rilascia i progetti"}}},fp="28,235,38.481.0,30.131.0,35.214.0,43.156.0,43.120.0"}
P.entries["item:supplies-for-sven"] = {n="Rifornimenti per Sven",s="Nel nord-ovest di Boscovespro, l'accampamento di Sven Yorgen dipende dalle provviste di Borgoscuro. La Carevin Family rifornisce la sua piccola banda mentre veglia contro le ombre.",h="Nel nord-ovest di Boscovespro, l'accampamento di Sven Yorgen dipende dalle provviste di Borgoscuro.",kw={"accampamento","carevin","borgoscuro","boscovespro","provviste","rifornimenti per sven","sven yorgen"},ang={["class:Paladin"]="Come paladino, puoi vedere nella resistenza di Sven all'oscurità di Boscovespro un'opera della Luce. Queste provviste sono destinate a un fratello nella fede.",["faction:Alliance"]="Con le forze della Night Watch impegnate allo stremo nella difesa di Borgoscuro, i viaggiatori dell'Alleanza portano spesso rifornimenti ad avamposti isolati come Sven's Camp."},sec={{t="Una ancora di salvezza per l'accampamento",b="Sven Yorgen e i suoi pochi seguaci sono accampati nelle terre selvagge a nord-ovest, lontano da Borgoscuro. Sono troppo pochi per lasciare la guardia e affrontare il viaggio fino in città. Così la Carevin Family invia cibo, bende e altri beni di prima necessità per aiutare la banda a mantenere la posizione."}},faq={{q="Chi ha inviato questi rifornimenti?",a="La Carevin Family di Borgoscuro invia questi rifornimenti. Organizza l'invio di provviste per Sven Yorgen e il suo accampamento nelle terre selvagge.",al={"chi ha inviato i rifornimenti per sven","chi ha preparato i rifornimenti di sven","rifornimenti della famiglia carevin"}},{q="Perché Sven non può recuperare i propri rifornimenti?",a="La banda di Sven conta troppo poche persone per lasciare l'accampamento. I suoi compagni superstiti lo difendono da bestie e non morti nel nord-ovest di Boscovespro, e nessuno può affrontare la pericolosa strada per Borgoscuro.",al={"perché sven non prende il cibo","perché consegnare a sven","perché servono rifornimenti"}},{q="Dove si trova l'accampamento di Sven?",a="Sven's Camp si trova lungo il confine nord-occidentale di Boscovespro, sulle colline oltre la protezione diretta della Night Watch.",al={"dove si trova sven yorgen","posizione di sven's camp","trova sven a boscovespro"}},{q="Chi è Sven Yorgen?",a="Sven Yorgen è un uomo di frontiera e un devoto seguace della Luce che un tempo coltivava la terra a Boscovespro. Dopo che una tragedia colpì la sua fattoria, fondò un accampamento armato sulla frontiera per contrattaccare le forze oscure che tormentavano la regione.",al={"chi è sven","storia di sven yorgen"}}},fx={["0c0166a3"]={q="Che cosa sono i Rifornimenti per Sven?",a="Sono un pacco di aiuti raccolto per sostenere Sven Yorgen e il suo piccolo gruppo di seguaci, che resistono a Boscovespro. La famiglia Carevin prepara regolarmente questi rifornimenti, affinché i devoti crociati possano continuare a compiere la volontà della Luce contro gli orrori che infestano la foresta oscura, senza abbandonare la loro missione.",al={"cosa sono i rifornimenti per sven","quali sono i rifornimenti di sven","oggetto rifornimenti per sven"}}},fp="17,177,23.274.0,24.125.0,38.195.0,29.114.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="Girocollo di Surena",s="A Roccavento, Gakin il Vincolaombre cerca il Girocollo con Sanguinite che donò alla sua ex apprendista, Surena Caledon. Lei fuggì con Erlan Drudgemoor per unirsi alla Fratellanza dei Defias, e ora Gakin invia aspiranti accoliti a riprenderlo con la forza.",h="A Roccavento, Gakin il Vincolaombre cerca il Girocollo con Sanguinite che donò alla sua ex apprendista...",kw={"girocollo con sanguinite","campo di zucche dei pozzonero","erlan drudgemoor","gakin il vincolaombre","slaughtered lamb","surena caledon","girocollo di surena"},ang={["class:Warlock"]="Se sei uno stregone umano o gnomo, recuperare il girocollo di Surena Caledon è una prima prova. Dimostra che i sentimenti non hanno posto nella ricerca del potere demoniaco."},sec={{t="L'investimento perduto di un maestro",b="Nei sotterranei dello Slaughtered Lamb a Roccavento, Gakin il Vincolaombre istruiva un tempo Surena Caledon nelle arti oscure. Scorgeva del potenziale nel suo fascino giovanile e nel suo talento magico, e le donò un prezioso Girocollo con Sanguinite per agevolarne gli studi. Ma Surena abbandonò l'addestramento e fuggì con Erlan Drudgemoor, un ladro affiliato alla Fratellanza dei Defias.\n\nGakin non permetterà che una traditrice tenga un manufatto tanto potente. Ora invia gli iniziati che cercano di padroneggiare il Vuoto a trovarla al Campo di Zucche dei Pozzonero e recuperare il girocollo con la forza. La loro impresa dimostrerà a chi sono leali."}},faq={{q="Perché Gakin il Vincolaombre vuole indietro il Girocollo di Surena?",a="Gakin donò a Surena il Girocollo con Sanguinite quando era sua apprendista. Lei abbandonò gli studi e fuggì con un membro della Fratellanza dei Defias. Gakin non permetterà che una traditrice tenga un prezioso manufatto di magia oscura.",al={"perché gakin vuole il girocollo","collana gakin surena","perché recuperare il girocollo"}},{q="Chi è Surena Caledon?",a="Surena Caledon è un'ex apprendista stregona che dimostrò un talento naturale sotto la guida di Gakin il Vincolaombre a Roccavento. Voltò le spalle al suo maestro e fuggì con Erlan Drudgemoor, nascondendosi tra i fuorilegge Defias nella Foresta di Elwynn.",al={"chi è surena","storia di surena caledon","chi possiede il girocollo"}},{q="Dove si può trovare il girocollo?",a="Surena Caledon porta con sé il girocollo al Campo di Zucche dei Pozzonero, nella parte orientale della Foresta di Elwynn, dove si nasconde tra i Banditi Defias.",al={"dove si trova surena","posizione del girocollo","dove si trova surena caledon"}},{q="A cosa serve il girocollo una volta recuperato?",a="Recuperare il girocollo dimostra la spietatezza di un accolito e la sua lealtà a Gakin il Vincolaombre. Non ha detto cosa ne farà. Si rammarica del talento sprecato di Surena e spera che il suo investimento in un nuovo allievo dia risultati diversi.",al={"cosa fa gakin con il girocollo","scopo del girocollo","perché gli stregoni hanno bisogno del girocollo"}}},fx={["195efbf9"]={q="Che cos'è il Girocollo di Surena?",a="È una collana ornata di pietre del sangue, appartenuta in origine a Gakin il Vincolaombre, il maestro stregone che risiede a The Slaughtered Lamb, a Roccavento. Gakin regalò il prezioso gioiello alla sua ex apprendista, Surena Caledon, quando era infatuato della sua giovinezza e bellezza, prima che lei lo tradisse.",al={"cos'è il girocollo di surena","girocollo di surena cos'è","girocollo con sanguinite"}},["7b9593ae"]={q="Da dove proviene il Girocollo di Surena e chi l'ha creato?",a="L'artigiano che creò il girocollo è sconosciuto, ma in origine era in possesso di Gakin il Vincolaombre. Gakin regalò la collana di pietre del sangue alla sua giovane allieva Surena Caledon durante il suo apprendistato, molto prima che lei fuggisse con un furfante dei Defias verso il campo di zucche di Elwynn.",al={"chi ha creato il girocollo di surena","origine del girocollo di surena","da dove viene il girocollo"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="Stomaco dell'Avvoltoio",s="In tutta Mulgore, gli avvoltoi cacciano su pianure e tavolati, e i rimedi popolari dei tauren impiegano i loro stomaci contro tossine letali.",h="In tutta Mulgore, gli avvoltoi cacciano su pianure e tavolati, e i rimedi popolari dei tauren impiegano i...",kw={"villaggio di zoccolo sanguinario","stomaco","maur invoca pioggia","mazzranache","mulgore","rimedio","avvoltoio"},ang={["race:Tauren"]="Come cacciatore o sciamano tauren, raccogliere queste parti onora la tradizione di usare la fauna di Mulgore per sostentare e curare la tribù."},sec={{t="Un raro ingrediente popolare",b="Gli avvoltoi cacciano sulle pianure e sui tavolati di Mulgore, scrutando con occhi acuti e cercando cibo tra le carogne. I tauren usano le loro piume e la loro carne nella vita quotidiana. Erboristi e guaritori ne apprezzano gli organi interni, soprattutto lo stomaco. Combinato con ossa di puma e cuori di lupo, aiuta a contrastare morsi velenosi e infezioni purulente."},{t="Un rimedio per il morso di Mazzranache",b="Al Villaggio di Zoccolo Sanguinario, Maur Invoca Pioggia cura la ferita che Mazzranache gli ha lasciato sulla spalla. Il veleno del leggendario zampalunga fa cadere Maur in preda al delirio mentre si diffonde nel suo corpo. Per preparare un impacco capace di espellere il veleno letale, a Maur servono uno Stomaco dell'Avvoltoio, un Cuore di Lupo della Prateria, un Femore di Puma delle Pianure e una Scaglia di Zampalunga delle Pianure."}},faq={{q="A cosa serve uno Stomaco dell'Avvoltoio?",a="Al Villaggio di Zoccolo Sanguinario, a Maur Invoca Pioggia serve uno Stomaco dell'Avvoltoio per un rimedio. Mescolato con altre tre parti animali, forma una cura per l'infezione velenosa causata da Mazzranache, il feroce zampalunga.",al={"uso dello stomaco dell'avvoltoio","perché serve lo stomaco dell'avvoltoio","scopo dell'organo di avvoltoio"}},{q="Da dove provengono gli Stomaci dell'Avvoltoio?",a="Gli stomaci degli avvoltoi si ricavano dagli avvoltoi che planano sulle pianure di Mulgore. Tra questi figurano gli avvoltoi comuni, i wiry swoops e i taloned swoops.",al={"dove trovare lo stomaco dell'avvoltoio","chi rilascia lo stomaco dell'avvoltoio","caccia agli avvoltoi"}},{q="Perché Maur Invoca Pioggia ha bisogno di questa parte specifica?",a="Mazzranache ha morso Maur, e il veleno di questo zampalunga insolitamente feroce provoca febbri violente e incubi. La medicina popolare dei tauren usa parti animali dalle potenti proprietà, tra cui uno stomaco, per contrastare le tossine nelle vene di Maur.",al={"rimedio di maur","perché uno stomaco","cura per mazzranache"}},{q="Lo stomaco viene utilizzato per qualcosa di diverso dalla cura di Maur?",a="No. A parte lo specifico rimedio popolare di Maur Invoca Pioggia al Villaggio di Zoccolo Sanguinario, gli stomaci degli avvoltoi non hanno impieghi comuni in cucina, nell'alchimia o nell'artigianato.",al={"altri usi per lo stomaco dell'avvoltoio","cucinare lo stomaco dell'avvoltoio","alchimia stomaco dell'avvoltoio"}}},fx={["8f6be1e3"]={q="Che cos'è lo Stomaco dell'Avvoltoio?",a="Lo Stomaco dell'Avvoltoio è un organo interno ricavato dagli uccelli predatori noti come avvoltoi, che sorvolano le pianure di Mulgore. Come molti organi digestivi degli uccelli, serve a elaborare prede coriacee. Nella medicina tradizionale tauren, queste parti animali, potenti e specializzate, sono apprezzate per le loro proprietà naturali e vengono usate come ingredienti in rimedi erboristici e preparati ricostituenti.",al={"cos'è lo stomaco dell'avvoltoio","oggetto stomaco dell'avvoltoio","che cos'è uno stomaco dell'avvoltoio"}}},fp="13,123,22.322.0,31.338.0,33.200.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:tablet-of-verga"] = {n="Tavoletta di Verga",s="A Roccia del Teschio, la Tavoletta di Verga resta nelle mani delle Lame Ardenti, mentre gli stregoni di Orgrimmar cercano le sue rune demoniache.",h="A Roccia del Teschio, la Tavoletta di Verga resta nelle mani delle Lame Ardenti, mentre gli stregoni di...",kw={"lame ardenti","spelonca delle ombre","durotar","gan'rul bloodeye","roccia del teschio","tavoletta di verga","emissario del vuoto"},ang={["class:Warlock"]="Come stregone in addestramento a Orgrimmar, recuperare la tavoletta è un passo per dimostrare il tuo valore all'Orda e imparare a vincolare un emissario del vuoto che ti serva e ti protegga.",["faction:Horde"]="Come membro dell'Orda, affronti le Lame Ardenti vicino alle porte di Orgrimmar. Sottrarre alla setta le reliquie rubate colpisce la sua influenza sulla giovane nazione di Thrall."},sec={{t="Una Reliquia Rubata",b="La Tavoletta di Verga reca rune rituali per evocare creature dal Nether e piegarle alla volontà di un padrone. Le Lame Ardenti hanno rubato la pietra e l'hanno nascosta in una cassa dentro Roccia del Teschio, appena a est di Orgrimmar.\n\nGli stregoni della Spelonca delle Ombre cercano la tavoletta per studiarne le incisioni e imparare a evocare un emissario del vuoto. Recuperarla impedisce anche alla setta di ottenere lo stesso vantaggio."}},faq={{q="Dove si trova la Tavoletta di Verga?",a="La Tavoletta di Verga si trova in un Burning Blade Stash dentro Roccia del Teschio, un complesso di caverne infestato da cultisti appena a est di Orgrimmar, a Durotar.",al={"posizione tavoletta di verga","dove trovare la tavoletta di verga","dove si trova la tavoletta di verga"}},{q="Chi vuole che la Tavoletta di Verga venga recuperata?",a="Gan'rul Bloodeye, un maestro stregone nella Spelonca delle Ombre sotto Orgrimmar, invia gli iniziati a recuperare la tavoletta per poter insegnare loro a evocare servitori più potenti.",al={"chi ha bisogno della tavoletta di verga","a chi portare la tavoletta di verga","tavoletta di gan'rul"}},{q="Quale potere contiene la tavoletta?",a="La pietra reca antiche rune necessarie per evocare e vincolare un emissario del vuoto, una creatura proveniente dalla Distorsione Fatua.",al={"cosa fa la tavoletta","storia della tavoletta di verga","rune della tavoletta di verga"}},{q="Perché le Lame Ardenti l'hanno rubata?",a="La setta delle Lame Ardenti cerca di destabilizzare l'Orda e accrescere il proprio potere demoniaco. Rubando la tavoletta, la setta priva i praticanti di Orgrimmar di conoscenze rituali fondamentali, tenendole per sé.",al={"perché le lame ardenti hanno la tavoletta","lame ardenti verga"}}},fx={["5fa1e5b5"]={q="Che cos'è la Tavoletta di Verga?",a="La Tavoletta di Verga è una reliquia incisa con conoscenze arcane degli stregoni, in particolare con le rune e i rituali necessari per evocare e vincolare un camminatore del Vuoto. Trafugata dai cultisti delle Lame Ardenti, custodisce segreti oscuri, ambiti dagli stregoni che vogliono accrescere la propria padronanza della Distorsione Fatua ed evocare servitori demoniaci da piegare al proprio volere.",al={"cos'è la tavoletta di verga","tavoletta di verga"}}},fp="15,117,14.387.0,37.143.0,40.162.0,35.112.0,35.197.0"}
P.entries["item:tainted-heart"] = {n="Cuore Corrotto",s="A Teldrassil, Denalan si prende cura di un cuore ancora corrotto. Il muschio nefasto è scomparso, ma la contaminazione persiste, e lui cerca di purificarlo con un terreno ricco di nutrienti.",h="A Teldrassil, Denalan si prende cura di un cuore ancora corrotto.",kw={"purificazione","corruzione","denalan","lago al'ameth","fioriera","cuore corrotto","teldrassil"},ang={["class:Druid"]="Come druido Cenarion, purificare il Cuore Corrotto ti permette di comprendere direttamente la corruzione dilagante che minaccia la salute del giovane Albero del Mondo.",["profession:Herbalism"]="Come erborista, puoi apprezzare l'abilità di Denalan nel mescolare terreni arricchiti che estraggono il marciume innaturale dai tessuti vegetali viventi."},sec={{t="Un nucleo corrotto",b="Un morbo turba l'equilibrio naturale di Teldrassil, deformandone piante e bestie. Una volta rimosso il muschio nefasto da una pianta malata, Denalan affida agli avventurieri il Cuore Corrotto al suo interno. L'oscurità si annida ancora nei suoi tessuti. Spera che una terra ricca di nutrienti, preparata appositamente, possa contrastare la contaminazione e risanare ciò che è stato corrotto."},{t="Il rimedio di Denalan",b="Il Cuore Corrotto mostra una strana vitalità nella fioriera incantata di Denalan. Si insinua nel terreno ricco e ne assorbe le sostanze nutritive curative. La terra brucia la corruzione. Il cuore emerge vivo, pulsante di energia pura e desideroso di difendere coloro che lo hanno guarito."}},faq={{q="Cos'è il Cuore Corrotto?",a="Il Cuore Corrotto è il nucleo interno di una pianta corrotta di Teldrassil. Il botanico Denalan ne ha rimosso il muschio nefasto, ma il cuore rimane corrotto finché non viene purificato.",al={"cos'è il cuore corrotto","oggetto cuore corrotto"}},{q="Chi purifica il Cuore Corrotto?",a="Denalan indica agli avventurieri di piantare il Cuore Corrotto nella sua fioriera preparata appositamente presso il Lago Al'ameth. Il terreno nutriente purifica il cuore e ne elimina la corruzione innaturale.",al={"chi lo purifica","come purificare il cuore corrotto"}},{q="Cosa succede dopo che è stato piantato?",a="Il cuore si insinua nel terreno della fioriera. Pochi istanti dopo, emerge purificato e pulsante di vitalità, pronto a legarsi a chi lo ha risanato.",al={"cosa succede al cuore","risultato del cuore piantato"}},{q="Perché il cuore è corrotto?",a="Uno strano morbo si diffonde sull'Albero del Mondo Teldrassil, corrompendo la flora autoctona, i timberlings e la fauna selvatica tra tutti i suoi rami.",al={"perché corrotto","cuore corruzione teldrassil"}}},fx={ae8829e0={q="Perché Denalan vuole che tu pianti il Cuore Corrotto?",a="Denalan è riuscito a rimuovere il muschio putrido che ricopriva il cuore, ma il suo nucleo è ancora profondamente corrotto. Spera che il terreno ricco di sostanze nutritive della fioriera che ha preparato appositamente possa curare l'afflizione, assorbire la corruzione e restituire vigore al seme vivente.",al={"perché piantare il cuore corrotto","a cosa serve il cuore corrotto","perché denalan vuole il cuore corrotto"}}},fp="13,150,16.325.0,16.267.1,26.165.0,31.186.0,33.144.1,46.132.0"}
P.entries["item:tainted-keg"] = {n="Barile Avvelenato",s="A Mulino di Tarren, il Barile Avvelenato contiene una bevanda letale creata dallo Speziale Lydon. La birra scura nanica rubata veicola il veleno, destinato a contadini umani imprigionati per mettere alla prova il lavoro della Società degli Speziali Reali.",h="A Mulino di Tarren, il Barile Avvelenato contiene una bevanda letale creata dallo Speziale Lydon.",kw={"speziale lydon","contadini catturati","dun garok","elixir of agony","shindigger stout","barile avvelenato","mulino di tarren"},ang={["race:Human"]="La birra avvelenata usata per uccidere i braccianti catturati mostra le tattiche spietate che minacciano ciò che resta dei vivi in tutta Colletorto.",["race:Undead"]="Per la Società degli Speziali Reali, la birra scura avvelenata segna un progresso verso armi biologiche capaci di sterminare l'umanità."},sec={{t="Un'annata mortale",b="I fucilieri nanici di Dun Garok subirono il furto di un barile di Shindigger Stout. Lo Speziale Lydon la mescolò con il suo Elixir of Agony appena perfezionato. I Reietti scelsero una bevanda comune per veicolare il veleno, sperando che nessuno sospettasse nulla. Una birra familiare divenne una rapida condanna a morte."},{t="Sperimentazione sui condannati",b="Diversi contadini umani erano tenuti prigionieri al piano superiore della locanda di Mulino di Tarren. La Gran Esecutrice Darthalia sospettava che uno stratega militare di Roccavento si nascondesse tra loro. Quando giunse notizia che lo stratega era morto altrove, i contadini non servivano più. Darthalia li consegnò a Lydon, che sistemò il barile avvelenato sul tappeto della loro stanza nell'ambito di una crudele celebrazione. Assetati e disperati, i prigionieri bevvero. L'elisir li uccise rapidamente, dimostrando la sua letale potenza."}},faq={{q="Cosa c'è dentro il Barile Avvelenato?",a="Il barile contiene Shindigger Stout, rubata a Dun Garok e mescolata con l'Elixir of Agony. Lo Speziale Lydon creò il veleno sperimentale a Mulino di Tarren.",al={"contenuto del barile avvelenato","quale veleno c'è nel barile","cosa c'è nel barile"}},{q="Da dove proveniva originariamente la birra?",a="La birra scura proveniva dai montanari e dai fucilieri nanici di Dun Garok, una fortezza pesantemente difesa nelle Alture di Colletorto sudorientali.",al={"chi ha preparato la birra","da dove è stata rubata la birra scura","fonte della shindigger stout"}},{q="Chi beve dal barile?",a="I contadini umani tenuti prigionieri al piano superiore della locanda di Mulino di Tarren bevono dal barile. La bevanda avvelenata li uccide quasi all'istante.",al={"chi la beve","vittime del barile avvelenato","contadini catturati"}},{q="Perché i contadini erano tenuti prigionieri?",a="La Gran Esecutrice Darthalia imprigionò i contadini perché sospettava che uno stratega militare di Roccavento si nascondesse tra loro. Quando giunse notizia che lo stratega era morto altrove, i contadini furono ritenuti inutili e consegnati agli speziali.",al={"perché i contadini prigionieri","perché darthalia ha catturato i contadini","perché i contadini sono a mulino di tarren"}}},fx={fd5e0197={q="Che cos'è il Barile Avvelenato?",a="Il Barile Avvelenato contiene Birra Scavabotte nanica rubata, adulterata con una mistura letale preparata dai Reietti. Lo Speziale Lydon ha creato questa birra avvelenata per usarla come prova pratica nell'ambito delle sue ricerche alchemiche in corso.",al={"cos'è il barile avvelenato","oggetto barile avvelenato","cos'è questo barile"}},["5c778a45"]={q="Perché lo Speziale Lydon vuole che venga usato il Barile Avvelenato?",a="Lo Speziale Lydon vuole che il barile venga consegnato per mettere alla prova l'efficacia del suo nuovo Elixir of Agony. L'Alta Esecutrice Darthalia gli ha affidato i contadini umani catturati; offrire loro birra avvelenata permette alla Società degli Speziali Reali di osservare comodamente gli effetti letali della tossina in prima persona.",al={"perché usare il barile avvelenato","perché lo speziale lydon vuole il barile avvelenato","scopo del barile avvelenato"}}},fp="11,201,16.276.0,24.458.1,31.151.0,39.136.0,24.115.1,41.243.0"}
P.entries["item:tainted-letter"] = {n="Lettera Corrotta",s="Vicino all'Abbazia della Contea del Nord, Drusilla La Salle invia agli iniziati stregoni umani una convocazione sigillata per impartire insegnamenti segreti, lontano da occhi vigili.",h="Vicino all'Abbazia della Contea del Nord, Drusilla La Salle invia agli iniziati stregoni umani una...",kw={"drusilla la salle","foresta di elwynn","abbazia della contea del nord","lettera corrotta","distorsione fatua","stregone"},ang={["class:Warlock"]="Come stregone, ricevi la Lettera Corrotta come introduzione alle arti oscure nel Regno di Roccavento. Il potere sul Nether richiede vigilanza e discrezione costanti.",["race:Human"]="Come umano, vivi in una società che sostiene ampiamente la Sacra Luce. I praticanti della magia oscura si addestrano in segreto ai margini di luoghi come l'Abbazia della Contea del Nord."},sec={{t="Una convocazione segreta",b="Gli iniziati di ritorno dai vicini accampamenti di coboldi portano la convocazione di Drusilla verso l'Abbazia della Contea del Nord. Sacerdoti, paladini e soldati si addestrano apertamente sui suoi prati, ma i praticanti della magia vile devono mantenere segreto il proprio cammino. Le guardie cittadine e i chierici potrebbero insospettirsi se gli stregoni novizi attirassero l'attenzione mentre cercano la propria mentore nei pressi dell'abbazia."},{t="Il prezzo dell'ambizione",b="Drusilla La Salle incontra i suoi allievi ai margini, dove è meno probabile che le sentinelle ficchino il naso. La gente comune di Elwynn diffida degli stregoni, e la lettera dà inizio a una lezione di disciplina. La magia arcana e quella del Nether comportano il rischio di corruzione. Chi comunica con gli abitanti della Distorsione Fatua deve temperare l'ambizione con un paziente autocontrollo."}},faq={{q="Chi ha inviato la Lettera Corrotta?",a="Drusilla La Salle, l'istruttrice degli stregoni vicino all'Abbazia della Contea del Nord, ha inviato la lettera.",al={"chi ha scritto la lettera corrotta","lettera di drusilla","mittente della lettera corrotta"}},{q="Perché la lettera è considerata corrotta?",a="Le insegne di Drusilla La Salle e le tracce di magia vile identificano la lettera come opera di una praticante delle arti demoniache.",al={"perché è corrotta","cosa rende la lettera corrotta","sigillo corrotto"}},{q="Perché le guardie della Contea del Nord sorvegliano Drusilla La Salle?",a="Le guardie e i sacerdoti della Contea del Nord diffidano della magia vile e delle evocazioni demoniache. Drusilla rimane ai margini dell'abbazia per sottrarsi alla loro stretta sorveglianza.",al={"guardie di drusilla","perché le guardie sospettano di drusilla","stregone nascosto nella contea del nord"}},{q="Quali consigli dà Drusilla alla lettura della lettera?",a="Drusilla avverte che trattare con entità della Distorsione Fatua porta tentazione e corruzione. Esorta i suoi allievi a esercitare autocontrollo e prudenza, senza rinunciare alla propria ambizione.",al={"consigli di drusilla","cosa dice drusilla","addestramento di drusilla"}}},fx={["63258adc"]={q="Che cos'è la Lettera Corrotta?",a="La Lettera Corrotta è un messaggio sigillato che ti viene lasciato al tuo ritorno all'Abbazia della Contea del Nord, contrassegnato dall'inconfondibile emblema personale di Drusilla La Salle. Rivolta agli aspiranti praticanti delle arti oscure, la lettera è un urgente invito a parlarle di persona. Reca una lieve traccia di corruzione vil, che la distingue nettamente dalle devote e ordinate pratiche della Sacra Luce entro le mura dell'abbazia.",al={"cos'è la lettera corrotta","identità della lettera corrotta","informazioni sulla lettera corrotta"}},["3c923280"]={q="Perché ti viene consegnata la Lettera Corrotta?",a="Ti viene consegnata per permetterti di contattare la tua addestratrice, Drusilla La Salle, non appena avrai completato i primi incarichi nei dintorni della Contea del Nord. Drusilla agisce in segreto ai margini dell'abbazia, tenendo d'occhio i nuovi stregoni. La lettera ti invita a cercarla prima che altre faccende dell'abbazia ti distraggano, così potrà metterti in guardia su autocontrollo, ambizione e natura corruttrice della Distorsione Fatua.",al={"perché mi serve la lettera corrotta","chi vuole la lettera corrotta","perché viene consegnata la lettera corrotta"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="Tainted Memorandum",s="Nella Valle Crestafredda, Alamar Grimm esorta gli gnomi stregoni novizi ad abbandonare le vecchie vie e a cercare potere nelle arti oscure.",h="Nella Valle Crestafredda, Alamar Grimm esorta gli gnomi stregoni novizi ad abbandonare le vecchie vie e a...",kw={"alamar grimm","forgiamara","valle crestafredda","gnomo stregone","gnomeregan","tainted memorandum"},ang={["class:Warlock"]="Come stregone, ti addestri sotto la guida di Alamar Grimm. Presenta le evocazioni oscure come una via verso il controllo e il potere.",["race:Gnome"]="Come gnomo, senti Grimm fare leva sul risentimento per la perdita di Gnomeregan e sulla percezione del tuo popolo come profughi dipendenti dai nani nelle loro terre."},sec={{t="Una convocazione discreta",b="A Forgiamara, pochi apprezzano chi pratica la magia vile e molti ne diffidano. Alamar Grimm consegna il Tainted Memorandum ai giovani gnomi che studiano le arti proibite. Rifiuta la Sacra Luce e le armi comuni. Per lui, la caduta di Gnomeregan dimostra che le vecchie vie e gli esperimenti meccanici hanno tradito il loro popolo.\n\nGrimm considera l'affidarsi alla carità dei nani un vicolo cieco. Esorta gli gnomi a conquistare un potere innegabile e a evocare servitori che obbediscano senza discutere. Solo allora, crede, potranno assicurarsi un futuro."}},faq={{q="Chi ha scritto il Tainted Memorandum?",a="Alamar Grimm, l'istruttore degli stregoni gnomi a Forgiamara, ha scritto il Tainted Memorandum.",al={"autore tainted memorandum","chi ha inviato tainted memorandum","nota di alamar grimm"}},{q="Perché il memorandum è considerato \"corrotto\"?",a="Il memorandum tratta della magia proibita degli stregoni. Il titolo riflette la diffidenza verso il potere demoniaco e vile a Dun Morogh, dove i nani che li ospitano tengono i praticanti a distanza.",al={"perché corrotto","storia lettera corrotta"}},{q="Cosa dice Alamar Grimm riguardo a Gnomeregan?",a="Alamar Grimm incolpa la magia arcana tradizionale e gli incauti esperimenti meccanici di aver portato gli gnomi sull'orlo dell'estinzione alla caduta di Gnomeregan. Crede che i nani considerino gli gnomi cittadini di seconda classe ed esorta gli stregoni a conquistare un proprio potere assoluto anziché attendere l'aiuto dell'Alleanza.",al={"alamar grimm gnomeregan","opinioni di alamar grimm"}}},fx={["0c729b68"]={q="Che cos'è il Tainted Memorandum?",a="Il Tainted Memorandum è un messaggio personale e riservato, destinato agli gnomi stregoni promettenti che hanno appena iniziato l'addestramento nella Valle Crestafredda. Recapitato in segreto da alleati in superficie, il biglietto è un invito a guardare oltre le tradizioni convenzionali della Sacra Luce o del combattimento fisico e a cercare altri praticanti aperti di vedute, dediti alle arti oscure.",al={"cos'è il tainted memorandum","promemoria corrotto","cos'è questo biglietto"}},e7be2e4a={q="Perché qualcuno vuole che tu abbia il Tainted Memorandum?",a="Il memorandum ti viene consegnato per reclutarti tra i praticanti delle arti degli stregoni. L'addestratore di stregoni Alamar Grimm lo invia per individuare gli incantatori alle prime armi che rifiutano i dogmi comuni di nani e gnomi, invitandoti a incontrarlo a Forgiamara per imparare a dominare alleati evocati e obbedienti e scoprire la vera fonte del potere demoniaco.",al={"perché mi è stato consegnato il memorandum","perché il tainted memorandum","chi vuole il tainted memorandum"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="Talismano della Corruzione",s="A Rivafosca, Xabraxxis usa il Talismano della Corruzione per aizzare i furbolg Blackwood contro i loro antichi alleati. Lo custodisce nella sua borsa personale, e la sua magia vincola la tribù alla follia vile.",h="A Rivafosca, Xabraxxis usa il Talismano della Corruzione per aizzare i furbolg Blackwood contro i loro...",kw={"auberdine","blackwood","rivafosca","furbolg","satiro","talismano della corruzione","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Come druido, consideri strumenti come il talismano una perversione dell'ordine naturale. Trasformano bestie sacre in pedine feroci dei servitori rimasti della Legione Infuocata.",["race:NightElf"]="Come Kaldorei di Auberdine, recuperare il talismano ti aiuta a liberare i tuoi ancestrali alleati furbolg dalla degradazione demoniaca e a risanare la terra."},sec={{t="Un condotto di follia",b="Ad Auberdine, gli elfi della notte cercano la causa della rivolta dei furbolg Blackwood contro i loro antichi alleati. Thundris Brigliavento ha scoperto che i satiri hanno causato la rovina della tribù. Talismani come questo diffondono una stregoneria corruttrice nelle terre selvagge. Contaminano il cibo e trasformano pacifici spiriti della foresta in bestie furiose. La loro magia vile soggioga le menti e le volontà delle tribù locali."},{t="Spezzare la presa",b="Per attirare Xabraxxis allo scoperto, purifichi campioni di cibo dei furbolg con acqua benedetta del pozzo lunare. La purificazione fa infuriare il sovrintendente. Una volta ucciso Xabraxxis, recuperi il talismano dalla sua sacca demoniaca. Lo porti a Thundris Brigliavento ad Auberdine, dove i Kaldorei possono neutralizzarne le nefaste emanazioni e studiare come annullare l'afflizione demoniaca nella foresta."}},faq={{q="Che cos'è il Talismano della Corruzione?",a="Xabraxxis usa il Talismano della Corruzione per incanalare magia malefica attraverso il cibo e le menti dei furbolg Blackwood a Rivafosca.",al={"cos'è il talismano della corruzione","scopo del talismano","cosa fa il talismano"}},{q="Chi trasporta il talismano?",a="Xabraxxis, il satiro che sorveglia l'accampamento settentrionale dei furbolg Blackwood vicino al Fiume Altafonte, porta il talismano nella sua sacca demoniaca.",al={"chi rilascia il talismano della corruzione","dove trovare il talismano della corruzione","come ottenere il talismano"}},{q="Come si attira allo scoperto il proprietario del talismano?",a="Raccogli frutta, cereali e noci dei furbolg, poi li mescoli con acqua del pozzo lunare in una ciotola purificatrice. Deponi l'offerta accanto al falò vicino al fiume. La purificazione fa infuriare Xabraxxis al punto da spingerlo ad attaccare.",al={"come evocare xabraxxis","come trovare xabraxxis","evocare satiro rivafosca"}},{q="Cosa succede al talismano dopo essere stato recuperato?",a="Porti il talismano a Thundris Brigliavento ad Auberdine. Lo mette al sicuro in attesa di disfarsene e studia come liberare definitivamente i furbolg dalla corruzione demoniaca.",al={"a chi consegno il talismano","consegnare talismano della corruzione","thundris windweaver talismano"}}},fp="22,194,20.379.0,17.350.1,35.126.0,25.134.0,46.205.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Smeraldo di Tallonkai",s="Su Teldrassil, il gioiello manca dal talismano druidico di Tallonkai. Ferocitas the Dream Eater tiene in gran conto lo smeraldo, necessario per riparare l'Acchiappasogni di Smeraldo.",h="Su Teldrassil, il gioiello manca dal talismano druidico di Tallonkai.",kw={"dolanaar","acchiappasogni di smeraldo","ferocitas the dream eater","mistici gnarlpine","brezzastella","tallonkai fontechiara","smeraldo di tallonkai"},ang={["class:Druid"]="Come druido, sai che lo smeraldo è in sintonia con il Sogno di Smeraldo. L'uso improprio che ne fanno i furbolg corrotti è un affronto all'equilibrio.",["race:NightElf"]="Come Elfo della Notte, aiuti a ristabilire l'ordine a Teldrassil sottraendo manufatti sacri agli Gnarlpine che avanzano."},sec={{t="Un Nucleo Rubato",b="Tallonkai Fontechiara ricevette l'Acchiappasogni di Smeraldo da Gaerolas Talvethen, custode dei druidi nell'Eremo di Ban'ethil. Il talismano è un potente catalizzatore che attinge energia dal Sogno di Smeraldo. Quando fu danneggiato, qualcuno ne estrasse a forza il radioso smeraldo centrale e lo portò nella parte orientale di Teldrassil.\n\nFerocitas the Dream Eater, uno Gnarlpine corrotto, prese il gioiello e ne fece una collana. La sua luce verde scintillava nell'oscurità della foresta, ma al furbolg non importava nulla della sua armonia con il Sogno di Smeraldo. Per Ferocitas era soltanto un trofeo, finché non fosse stato recuperato."}},faq={{q="Cos'è lo Smeraldo di Tallonkai?",a="Lo Smeraldo di Tallonkai è uno smeraldo incantato nel cuore dell'Acchiappasogni di Smeraldo, un catalizzatore druidico donato da Gaerolas Talvethren a Tallonkai Fontechiara di Dolanaar.",al={"cos'è il gioiello","storia smeraldo di tallonkai"}},{q="Chi ha rubato lo Smeraldo di Tallonkai?",a="Ferocitas the Dream Eater rubò il gioiello. Guida i mistici Gnarlpine corrotti che vivono a nord di Brezzastella.",al={"chi ha il gioiello","chi lo ha rubato","chi ha preso lo smeraldo di tallonkai"}},{q="I furbolg Gnarlpine possono usare il potere del gioiello?",a="No. Ferocitas indossava lo smeraldo come una collana luminosa, ma il suo potere druidico era inutile per il furbolg corrotto.",al={"ferocitas può usarlo","potere smeraldo pino distorto"}},{q="Dove va il gioiello dopo essere stato recuperato?",a="Il gioiello torna a Tallonkai Fontechiara, sul livello superiore di Dolanaar. Lì lo usa per riparare e ripristinare completamente l'Acchiappasogni di Smeraldo.",al={"cosa succede al gioiello","riparare acchiappasogni"}}},fx={["4dd99e12"]={q="Perché qualcuno vuole lo Smeraldo di Tallonkai?",a="Tallonkai Fontechiara ha un disperato bisogno che gli venga restituito questo smeraldo luminoso, così da poter riparare il suo Acchiappasogni di Smeraldo danneggiato. Il mistico furbolg dei Pinalunga corrotto, Ferocitas il Divoratore di Sogni, l'ha preso per indossarlo come una collana scintillante, attratto dal suo bagliore magico senza capire che il suo potere legato ai sogni è del tutto inutile nelle sue mani.",al={"perché si cerca lo smeraldo di tallonkai","perché tallonkai vuole lo smeraldo","perché rubare lo smeraldo di tallonkai"}}},fp="17,157,13.586.0,26.160.0,28.119.0,49.113.0,46.135.0"}
P.entries["item:taming-rod"] = {n="Bastone per Addomesticare",s="A Durotar, i Bastoni per Addomesticare aiutano i nuovi cacciatori a imparare a comandare le bestie. Gli addestratori li prestano agli allievi per fare pratica prima che stringano legami duraturi con i compagni animali.",h="A Durotar, i Bastoni per Addomesticare aiutano i nuovi cacciatori a imparare a comandare le bestie.",kw={"armored scorpid","dire mottled boar","famiglio del cacciatore","tranciacolle","bastone per addomesticare","taming the beast","thotar"},ang={["class:Hunter"]="Come cacciatore, usi un Bastone per Addomesticare per fare pratica prima di poter stringere legami duraturi con le bestie selvatiche.",["faction:Horde"]="A Durotar e Mulgore, addestratori come Thotar usano i Bastoni per Addomesticare per verificare se le giovani reclute hanno la disciplina necessaria a dominare la feroce fauna di Kalimdor."},sec={{t="Uno strumento di addestramento per guide",b="A Tranciacolle, addestratori come Thotar consegnano i Bastoni per Addomesticare ai cacciatori orchi e troll alle prime armi. L'incantamento li aiuta a fare pratica prima di poter stringere un legame definitivo con una creatura selvatica. Un bastone pacifica un predatore locale, come un dire mottled boar o un armored scorpid. Il cacciatore impara a impartire comandi e a combattere al fianco di un compagno animale, ma il legame dura solo per poco."},{t="Un passo verso la maestria",b="La magia di ogni Bastone per Addomesticare svanisce dopo poco tempo, e ciascun bastone è sintonizzato su determinati tipi di bestie selvatiche. I novizi affrontano prove con animali dai temperamenti diversi, dai docili raccoglitori agli aggressivi cacciatori velenosi. Quando un allievo dimostra di saper comandare queste bestie, il bastone torna all'addestratore. Poi l'addestratore gli insegna ad addomesticare, richiamare e congedare compagni per tutta la vita senza un manufatto."}},faq={{q="A cosa serve un Bastone per Addomesticare?",a="I cacciatori usano un Bastone per Addomesticare per esercitarsi a comandare una bestia in battaglia. Un addestratore lo presta a un giovane cacciatore, e la sua magia pacifica e ammalia brevemente la creatura.",al={"a cosa serve il bastone per addomesticare","uso del bastone per addomesticare","perché ho un bastone per addomesticare"}},{q="Posso tenere il famiglio addomesticato con il bastone?",a="No. Una bestia sotto l'influsso di un Bastone per Addomesticare serve solo per l'addestramento. Il legame termina quando la magia svanisce o restituisci il bastone, e dopo le prove impari ad addomesticare un compagno duraturo.",al={"il famiglio è permanente","posso tenere il cinghiale","posso tenere lo scorpide"}},{q="Posso usare qualsiasi Bastone per Addomesticare su qualsiasi animale?",a="No. Ogni Bastone per Addomesticare è sintonizzato su una specifica creatura bersaglio per quella fase dell'addestramento, come un dire mottled boar o un armored scorpid.",al={"il bastone funziona su qualsiasi cosa","bersagli del bastone per addomesticare"}},{q="Posso tenere il Bastone per Addomesticare dopo aver completato l'addestramento?",a="No. Restituisci il Bastone per Addomesticare al tuo addestratore dei cacciatori dopo l'incarico. Dopo la prova finale, l'addestratore ti insegna ad addomesticare, evocare e congedare le bestie autonomamente.",al={"tenere il bastone per addomesticare","posso conservare il bastone"}}},fx={c3dba9d3={q="Che cos'è un Bastone per Addomesticare?",a="Il Bastone per Addomesticare è uno strumento didattico affidato agli aspiranti cacciatori dai loro addestratori. Incantato per piegare temporaneamente al tuo volere una creatura selvaggia, serve come ausilio per l'addestramento. Usandolo, un aspirante cacciatore può sperimentare il delicato legame necessario per comandare gli animali selvatici in battaglia, senza stringere un vincolo permanente prima di aver padroneggiato le abilità fondamentali.",al={"cos'è un bastone per addomesticare","oggetto bastone per addomesticare","storia del bastone per addomesticare"}},da578f9f={q="Perché un cacciatore vuole un Bastone per Addomesticare?",a="I cacciatori novizi hanno bisogno del bastone per dimostrare la loro crescente padronanza della natura. Riuscendo a sottomettere bestie pericolose come cinghiali o scorpidi, dimostri la determinazione e la calma necessarie per controllare una mente selvaggia. Dopo aver mostrato al tuo addestratore di saper guidare queste creature in combattimento, ti verranno insegnate le vere e durature arti della compagnia delle bestie.",al={"perché serve il bastone per addomesticare","a cosa serve il bastone per addomesticare","perché usare il bastone per addomesticare"}}},fp="10,164,28.377.0,21.391.0,30.160.0,38.189.0,39.141.0,56.172.0"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Cuore di Taragaman il Famelico",s="Sotto Orgrimmar, Neeru Fireblade cerca il Cuore di Taragaman il Famelico come prova che la presenza demoniaca è scomparsa. Il trofeo proviene dalla vilguardia che domina le profondità del Baratro di Fiamma Furente.",h="Sotto Orgrimmar, Neeru Fireblade cerca il Cuore di Taragaman il Famelico come prova che la presenza demoniaca...",kw={"vilguardia","cuore","famelico","neeru fireblade","orgrimmar","baratro di fiamma furente","lama rovente","taragaman"},ang={["class:Warlock"]="Come stregone, conosci la delicata trama di ombre e inganni che si cela nella Spelonca delle Ombre. Trattare con Neeru Fireblade e maneggiare resti demoniaci sono attività che ti sono familiari.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere Orgrimmar dalla corruzione al suo interno. Il cuore strappato alla bestia testimonia la vigilanza dell'Orda."},sec={{t="Un trofeo di inganni",b="Il cuore di Taragaman il Famelico dimostra che la vilguardia è caduta. Neeru Fireblade dice a Thrall e agli impazienti avventurieri che Taragaman guida i cultisti della Lama Rovente nel Baratro di Fiamma Furente. Portare il cuore a Neeru sembra adempiere all'ordine del Capoguerra di proteggere Orgrimmar dalla corruzione demoniaca. Attribuire la guida del culto a una brutale vilguardia tiene anche nascoste le reti di mortali sotto la città."}},faq={{q="Chi vuole il Cuore di Taragaman il Famelico?",a="Neeru Fireblade, uno stregone orco nella Spelonca delle Ombre di Orgrimmar, ti chiede di portargli il cuore come prova che il demone è stato ucciso.",al={"chi prende il cuore di taragaman","consegna cuore di taragaman","chi vuole il cuore"}},{q="Dove posso ottenere questo cuore?",a="Prelevi il cuore dal cadavere di Taragaman il Famelico nelle camere magmatiche centrali del Baratro di Fiamma Furente, sotto Orgrimmar. L'imponente vilguardia dimora lì.",al={"come ottenere il cuore di taragaman","dove si trova il cuore di taragaman","posizione del cuore di taragaman"}},{q="Thrall vede mai il cuore?",a="No. Porti il cuore direttamente a Neeru Fireblade. Dice che si occuperà dei resti demoniaci e riferirà al Capoguerra Thrall della vittoria per conto tuo.",al={"thrall riceve il cuore","dare il cuore a thrall","thrall taragaman cuore"}},{q="Taragaman era davvero il capo della Lama Rovente?",a="Neeru Fireblade indica Taragaman il Famelico come capo della Lama Rovente. Dice che ucciderlo e riportare il suo cuore servirà a placare Thrall.",al={"taragaman è il capo","chi guida la lama rovente","vero boss taragaman"}}},fx={a71e3ad9={q="Che cos'è il Cuore di Taragaman il Famelico?",a="È il cuore strappato a Taragaman il Famelico, un enorme guardiavil di Vil che si annida nelle profondità infuocate del Baratro di Fiamma Furente, sotto Orgrimmar. Portato fuori dalle caverne dagli avventurieri, è la prova tangibile che il demone che Neeru Fireblade indica come capo della Lama Rovente è stato abbattuto.",al={"cos'è il cuore di taragaman","cuore di taragaman il famelico","storia del cuore di taragaman"}},d8388abb={q="Da dove proviene il Cuore di Taragaman il Famelico?",a="Il cuore è stato estratto dal petto di Taragaman il Famelico, un gigantesco guardiavil di Vil stanziato nelle profondità del Baratro di Fiamma Furente. Taragaman fu evocato e tenuto dai cultisti della Lama Rovente nei tunnel sotterranei sotto Orgrimmar, perciò il cuore è una reliquia organica della corruzione demoniaca che infesta le viscere della città.",al={"origine del cuore di taragaman","da dove viene il cuore","chi ha creato il cuore di taragaman"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="Manoscritto Cencioso",s="A Millepicchi, il Manoscritto Cencioso giace nascosto nel Covo di Zoccolo Spezzato. Le sue pagine strappate provengono dal Tome of the Cabal, e gli stregoni le cercano per imparare a evocare un cacciatore distorcente.",h="A Millepicchi, il Manoscritto Cencioso giace nascosto nel Covo di Zoccolo Spezzato.",kw={"cacciatore distorcente","jorah annison","krom braccioforte","tomo ammuffito","covo di zoccolo spezzato","manoscritto cencioso","millepicchi","tome of the cabal"},ang={["class:Warlock"]="Come stregone, cerchi il manoscritto per acquisire le conoscenze necessarie a comandare i cacciatori distorcenti."},sec={{t="Un grimorio vandalizzato",b="Un tempo, il Tome of the Cabal era un volume unico e integro, custodito nel regno caduto di Lordaeron. Uno sconosciuto profanatore strappò quasi metà delle sue pagine dalla rilegatura. Il dorso e le pagine rimaste divennero noti come il Tomo Ammuffito. Furono spediti a sud verso Khaz Modan, poi andarono perduti in mare. I fogli strappati attraversarono il Grande Mare fino a Kalimdor e finirono nelle mani dei centauri Galak all'interno del Covo di Zoccolo Spezzato."},{t="Recuperare le parole",b="Una cassa malconcia nelle profondità delle caverne del Covo di Zoccolo Spezzato custodisce il manoscritto. Lì ha resistito ai venti aridi di Millepicchi. Gli stregoni dell'Alleanza collaborano con Krom Braccioforte a Forgiardente, mentre i praticanti dell'Orda aiutano Jorah Annison a Sepulcra. Entrambi i gruppi affrontano gli aggressivi centauri per ricongiungere i fogli con il Tomo Ammuffito. Insieme, i libri custodiscono rituali oscuri per evocare e vincolare un cacciatore distorcente demoniaco."}},faq={{q="Cos'è il Manoscritto Cencioso?",a="Il Manoscritto Cencioso raccoglie pagine strappate che costituiscono circa metà dell'unico Tome of the Cabal, un grimorio sulla demonologia.",al={"storia del manoscritto cencioso","cos'è il manoscritto","pagine tome of the cabal"}},{q="Come sono finite queste pagine a Millepicchi?",a="Dopo che uno sconosciuto profanatore strappò il Tome of the Cabal a Lordaeron, le sue pagine attraversarono il mare. I centauri Galak le presero e le nascosero in una cassa all'interno del Covo di Zoccolo Spezzato.",al={"perché nel covo di zoccolo spezzato","tomo dei centauri","manoscritto di millepicchi"}},{q="A cosa serve il manoscritto?",a="Gli stregoni riuniscono il Manoscritto Cencioso al Tomo Ammuffito zuppo d'acqua per ricostituire il Tome of the Cabal. Il libro ricostituito insegna il rituale per evocare un cacciatore distorcente.",al={"perché serve il manoscritto","pagine missione del cacciatore distorcente"}},{q="Chi è stato il responsabile dello smembramento del libro originale?",a="Nessuno sa chi abbia fatto a pezzi il libro originale. Krom Braccioforte a Forgiardente e Jorah Annison a Sepulcra lamentano entrambi i danni arrecati a quest'opera di erudizione unica nel suo genere.",al={"chi ha strappato il tomo","chi ha vandalizzato tome of the cabal"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="Valigetta di Tazan",s="Vicino a Porto Paranco, Tazan affronta i pirati lungo la costa con una valigetta chiusa a chiave in mano. La Shattered Hand vuole le informazioni al suo interno.",h="Vicino a Porto Paranco, Tazan affronta i pirati lungo la costa con una valigetta chiusa a chiave in mano.",kw={"savane","spelonca delle ombre","gamon","porto paranco","the shattered hand","tazan","valigetta di tazan","therzok"},ang={["class:Rogue"]="Come ladro dell'Orda, devi recuperare la valigetta e sottrarne la chiave a Gamon per guadagnarti un posto nella Shattered Hand.",["faction:Horde"]="A Orgrimmar, la Shattered Hand cerca di ottenere un vantaggio agendo di nascosto, mentre il Capoguerra Thrall segue una linea più misurata."},sec={{t="Segreti delle Savane",b="Vicino a Porto Paranco, Tazan fa affari con i pirati accampati lungo la costa delle Savane. Therzok, un maestro di gilda della Shattered Hand nella Spelonca delle Ombre, sotto Orgrimmar, lo ha notato. La gilda cerca di accrescere il proprio potere in segreto, al di là della cauta diplomazia del Capoguerra Thrall. Ha deciso di eliminare Tazan per impadronirsi delle informazioni nella sua valigetta."},{t="Una serratura complessa",b="La serratura della valigetta è difficile da aprire sul campo. Tazan ha dato la chiave a Gamon, il suo socio, che beve in una taverna di Orgrimmar. I ladri in cerca della valigetta devono sfilare la chiave dalla tasca di Gamon senza dare l'allarme. Poi potranno leggere il diario di Tazan."}},faq={{q="A chi appartiene questa valigetta?",a="Tazan, un troll che fa affari con i pirati vicino a Porto Paranco, nelle Savane, porta con sé la valigetta.",al={"chi è tazan","proprietario tazan","proprietario valigetta"}},{q="Perché la Shattered Hand vuole la Valigetta di Tazan?",a="Therzok e la Shattered Hand cercano informazioni sugli affari di Tazan con i pirati della costa. Sperano di ampliare la propria rete e riconquistare il loro orgoglio guerriero agendo nell'ombra.",al={"perché therzok la vuole","valigetta shattered hand","perché rubare la valigetta"}},{q="Dov'è la chiave per aprire la valigetta?",a="Tazan ha lasciato la chiave al suo socio Gamon, un avventore ubriaco in una taverna di Orgrimmar.",al={"come aprire la valigetta","chiave di tazan","dov'è la chiave"}},{q="Cosa c'è dentro la Valigetta di Tazan?",a="Il diario di Tazan si trova nella valigetta chiusa a chiave. Descrive in dettaglio i suoi traffici segreti e i legami con i bucanieri della costa.",al={"contenuto della valigetta","cosa c'è nella borsa","diario di tazan"}}},fp="15,130,22.331.0,14.260.1,32.87.0,49.170.0,37.85.1,31.108.1"}
P.entries["item:tear-of-the-moons"] = {n="Lacrima delle Lune",s="A Bael Modan, nelle Savane Meridionali, gli scavatori nani hanno dissotterrato la Lacrima delle Lune. Il suo strano potere soggioga Feegly, e il Generale Twinbraid ne teme l'influenza.",h="A Bael Modan, nelle Savane Meridionali, gli scavatori nani hanno dissotterrato la Lacrima delle Lune.",kw={"bael modan","forte di bael'dun","savane","scavo","feegly","lacrima delle lune","trogg","twinbraid"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a recuperare la reliquia dal Forte di Bael'dun, ostacolando la presenza militare di Forgiardente che invade le terre ancestrali dei tauren.",["race:Dwarf"]="Per te che sei un nano, il destino di Feegly è un monito sul pericolo che la spedizione di Bael'dun rischia di risvegliare sotto Kalimdor."},sec={{t="Una reliquia dissotterrata",b="Gli scavatori nani trovarono la Lacrima delle Lune durante i primi scavi a Bael Modan. La sua strana luce affascinò i minatori, soprattutto Feegly. Diceva che gli donava una grande forza, ma presto divenne instabile e si rivoltò contro i suoi compagni.\n\nIl Generale Twinbraid, comandante della spedizione, temeva l'influenza della reliquia e la dichiarò maledetta. Prese il cristallo e lo rinchiuse nel suo forziere personale al Forte di Bael'dun. Poi esiliò Feegly nelle Savane."},{t="Il prezzo dell'ossessione",b="In esilio, Feegly non riesce a dominare la sua brama del potere del cristallo. Chiede ai viaggiatori dell'Orda di passaggio di aiutarlo a penetrare nella fortezza nanica e a sottrarlo al caveau di Twinbraid.\n\nQuando Feegly ottiene la Lacrima e la strofina, emette strani grugniti. Il cristallo gli cade dalle mani e si frantuma al suolo. Feegly si trasforma in un trogg e muore poco dopo."}},faq={{q="Da dove proviene la Lacrima delle Lune?",a="I prospettori e gli scavatori nani dissotterrarono la Lacrima delle Lune a Bael Modan, un sito di scavi archeologici nelle Savane Meridionali.",al={"origine della lacrima","dove è stata trovata la lacrima","storia della lacrima delle lune"}},{q="Perché il cristallo era rinchiuso dentro Forte di Bael'dun?",a="Il Generale Twinbraid temeva che il cristallo fosse maledetto dopo che Feegly ne era diventato ossessionato e si era rivoltato contro gli altri minatori. Lo rinchiuse nel suo forziere al Forte di Bael'dun per proteggere la spedizione.",al={"perché rinchiusa","cassaforte di twinbraid lacrima","perché twinbraid l'ha presa"}},{q="Cosa succede quando Feegly ottiene di nuovo la Lacrima?",a="Feegly strofina il cristallo, che gli cade dalle mani e si frantuma. Si trasforma in un trogg e muore poco dopo.",al={"feegly diventa trogg","cosa succede a feegly","trasformazione trogg feegly"}},{q="È possibile salvare o riparare la Lacrima delle Lune?",a="La Lacrima si frantuma quando Feegly la riottiene. Il resoconto non dice se qualcuno l'abbia riparata in seguito.",al={"si può tenere la lacrima","lacrima frantumata","riparare la lacrima delle lune"}}},fx={f703febe={q="Che cos'è la Lacrima delle Lune?",a="La Lacrima delle Lune è un misterioso cristallo luminoso riportato alla luce da scavatori nani durante la loro esplorazione di Bael Modan, nelle Savane Meridionali. Sebbene fosse celebrato come la prima grande scoperta del sito, l'artefatto si rivelò profondamente instabile: emanava un potere corruttore che alterò la mente del nano che lo possedeva e spinse i capi della spedizione a rinchiuderlo.",al={"lacrima delle lune","cos'è la lacrima delle lune","cos'è la lacrima"}}},fp="17,170,17.458.0,22.354.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="Lacrima di Tilloa",s="Vicino a Borgoscuro, la Lacrima di Tilloa attira chi cerca reagenti alchemici rari. Il fiore cresce nella tenuta Mistmantle a Boscovespro.",h="Vicino a Borgoscuro, la Lacrima di Tilloa attira chi cerca reagenti alchemici rari.",kw={"un infuso nobiliare","borgoscuro","mistmantle","stalvan","lacrima di tilloa","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Come stregone, potresti conoscere la Lacrima di Tilloa come reagente ricercato da agenti dell'occulto sotto la capitale. La usano in infusi destinati a far tacere i nobili che indagano.",["profession:Herbalism"]="Come erborista, potresti trovare la Lacrima di Tilloa nel terreno corrotto di Boscovespro, lontano dai consueti campi rigogliosi."},sec={{t="Un giardino nell'oscurità",b="Fuori Borgoscuro, la Lacrima di Tilloa cresce nella tenuta di Stalvan Mistmantle. Il suolo di Boscovespro è diventato ostile alla vegetazione sana, eppure il piccolo fiore bianco resiste tra le aiuole in ombra. Raro e appartato, attira chi cerca reagenti insoliti al di fuori dei mercati legali."},{t="Un infuso per i nobili",b="Sotto le strade di Roccavento, Zardeth Graffionero cerca la Lacrima di Tilloa per un infuso destinato a Lord Wishock. Membro della Casa dei Nobili, Wishock minaccia di indagare sulle losche operazioni condotte sotto la capitale. Zardeth unisce il fiore alla Radice Muschiata proveniente da sotto la Diga di Pietrasalda. L'infuso serve a distrarre e rendere inoffensivo Wishock prima che possa iniziare un'indagine ufficiale."}},faq={{q="Dove cresce la Lacrima di Tilloa?",a="Il fiore cresce nel giardino incolto della tenuta della famiglia Mistmantle, alla periferia di Borgoscuro, a Boscovespro.",al={"posizione lacrima di tilloa","dove si trova la lacrima di tilloa","punto tilloa"}},{q="Chi desidera la Lacrima di Tilloa?",a="Zardeth Graffionero cerca il fiore mentre opera di nascosto sotto Roccavento. Gli serve per un infuso speciale.",al={"chi ha bisogno della lacrima di tilloa","chi assegna la missione lacrima di tilloa","chi la vuole"}},{q="A cosa serve il fiore?",a="Il fiore viene unito alla Radice Muschiata in un infuso destinato a rendere inoffensivo Lord Wishock e a far tacere le sue richieste di indagare sui loschi affari sotto la capitale.",al={"scopo lacrima di tilloa","cosa fa la lacrima di tilloa","fiore infuso dei nobili"}},{q="Chi è Lord Wishock?",a="Lord Wishock è un nobile della Casa dei Nobili di Roccavento. Dopo aver appreso di operazioni sovversive sotto la città, ha iniziato a sollecitare il consiglio a indagare.",al={"wishock","chi è wishock","lord wishock"}}},fx={e7b72a0d={q="Che cos'è la Lacrima di Tilloa?",a="La Lacrima di Tilloa è un delicato e raro fiore bianco che sboccia a Boscovespro. Cresce in particolare nel trascurato Giardino di Stalvan, ai margini di Borgoscuro. Questa pianta discreta possiede proprietà potenti, ambite da chi pratica le arti oscure nei tunnel sotto Roccavento, molto lontano da lì.",al={"cos'è la lacrima di tilloa","fiore lacrima di tilloa","lacrima di tilloa"}},d8c5f010={q="Da dove proviene la Lacrima di Tilloa?",a="Il fiore cresce spontaneamente nel Giardino di Stalvan, invaso dalla vegetazione, appena oltre i confini sicuri di Borgoscuro, nella foresta ombrosa di Boscovespro. Non è stato creato da alcun artigiano mortale: fiorisce semplicemente indisturbato tra i terreni della tragica tenuta dell'antica dimora dei Mistmantle.",al={"da dove viene la lacrima di tilloa","chi ha creato la lacrima di tilloa","origine della lacrima di tilloa"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="Nucleo della Memoria di Techbot",s="A Gnomeregan, Tinkmaster Overspark cerca il Nucleo della Memoria di Techbot per studiare il comportamento corrotto dell'automa.",h="A Gnomeregan, Tinkmaster Overspark cerca il Nucleo della Memoria di Techbot per studiare il comportamento...",kw={"cervello","gnomeregan","nucleo della memoria","negatronico","overspark","positronico","techbot","tinker town"},ang={["profession:Engineering"]="Come ingegnere, puoi capire come un solo cortocircuito abbia polarizzato il cervello positronico di Techbot e ne abbia invertito la logica.",["race:Gnome"]="Per gli gnomi, Techbot è un'altra vittima della caduta di Gnomeregan. La rovina della città ha travolto brillanti opere d'ingegneria del tempo di pace."},sec={{t="Un Cervello Polarizzato",b="Prima della caduta di Gnomeregan, Techbot aiutava Tinkmaster Overspark e i suoi colleghi inventori con congegni e conoscenze. Durante la caduta della città, una scarica elettrica anomala colpì Techbot, portando il suo cervello positronico a uno stato negatronico ostile. Ora l'automa vaga per le sale contaminate di Gnomeregan e attacca chiunque veda. Overspark spera che il nucleo della memoria lo aiuti a comprendere il guasto e a riportare la sua creazione alla ragione."}},faq={{q="Cos'è il Nucleo della Memoria di Techbot?",a="Il Nucleo della Memoria di Techbot contiene i dati e le conoscenze di Techbot. Techbot è l'automa costruito da Tinkmaster Overspark, e il suo nucleo conserva la registrazione dell'alterazione elettrica che lo corruppe durante la caduta di Gnomeregan.",al={"nucleo della memoria di techbot","oggetto cervello di techbot","cose il nucleo di techbot"}},{q="Chi vuole il Nucleo della Memoria di Techbot?",a="Tinkmaster Overspark vuole il Nucleo della Memoria di Techbot. Ha trovato rifugio con altri gnomi esiliati a Tinker Town, a Forgiardente. Chiede agli avventurieri di entrare a Gnomeregan, disattivare Techbot e riportargli il nucleo affinché possa tentare di ripararlo.",al={"a chi serve il nucleo della memoria di techbot","a chi consegnare il nucleo di techbot","dove portare il nucleo di techbot"}},{q="Perché Techbot è impazzito?",a="Durante la caduta di Gnomeregan, una scintilla elettrica vagante colpì il cervello positronico di Techbot. La scarica lo polarizzò in uno stato negatronico, trasformando la sua personalità e i suoi protocolli da servizievoli a violenti e frenetici.",al={"perche techbot e ostile","cosa e successo a techbot","techbot impazzito"}},{q="Dove si ottiene il nucleo?",a="Il nucleo si recupera da Techbot, che vaga nei corridoi meccanici superiori e negli ingressi di Gnomeregan, a Dun Morogh.",al={"dove trovare il nucleo della memoria di techbot","posizione di techbot","come ottenere il cervello di techbot"}}},fx={a503508b={q="Da dove proviene il Nucleo della Memoria di Techbot e chi l'ha creato?",a="Il nucleo della memoria proviene da Techbot, un complesso costrutto meccanico costruito da Tinkmaster Overspark a Gnomeregan. Overspark progettò la macchina perché aiutasse lui e i suoi compagni inventori, fornendo loro una riserva inesauribile di dati e congegni. Tuttavia, quando Gnomeregan cadde in mano ai trogg, una scarica elettrica anomala colpì Techbot e polarizzò il suo cervello positronico trasformandolo in uno stato negatronico, rendendo la macchina folle.",al={"chi ha creato il nucleo della memoria di techbot","origine di techbot","chi ha costruito techbot"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="Lenti Telescopiche",s="Sopra il porto di Porto Paranco, Sparachiodi attende le Lenti Telescopiche per completare il telescopio del suo osservatorio. I pirati dei Mari del Sud hanno sottratto la lente a una nave, e si trova ancora nel loro accampamento a sud della città.",h="Sopra il porto di Porto Paranco, Sparachiodi attende le Lenti Telescopiche per completare il telescopio del...",kw={"cassa","sparachiodi","osservatorio","porto paranco","filibustieri dei mari del sud","stolen booty","lenti telescopiche"},ang={["profession:Engineering"]="Da ingegnere, puoi riconoscere la raffinata lavorazione ottica di questa lente. Mette a fuoco i meccanismi di osservazione a lunga distanza senza aberrazione sferica.",["race:Gnome"]="Da gnomo, potresti deridere la tecnologia missilistica dei goblin. Eppure la dedizione di Sparachiodi all'astronomia ottica dimostra che la Goblin Engineering non si occupa soltanto di esplosivi ad alto potenziale."},sec={{t="Occhi al Cielo",b="Porto Paranco è noto per il commercio spietato, ma Sparachiodi, il suo sovrintendente e capo ingegnere, nutre ambizioni meccaniche più grandi. Il suo osservatorio svetta sul porto, costruito per osservare il traffico marittimo e le stelle. La lente più grande è arrivata sana e salva via terra da Durotar. La lente più piccola, di vitale importanza, ha viaggiato via mare, dove i filibustieri dei Mari del Sud depredano le rotte mercantili al largo delle Savane."},{t="Bottino Pirata",b="Quando i filibustieri dei Mari del Sud hanno assaltato la nave da trasporto, hanno preso tutto ciò che aveva valore, comprese le delicate ottiche. La lente potrebbe trovarsi tra il disordine del loro accampamento sulla spiaggia a sud di Porto Paranco. I pirati potrebbero non apprezzarne la fattura, o non sapere come ricettarla. Sparachiodi ha bisogno che il vetro gli venga restituito intatto, così da poter mettere a fuoco dalla sua piattaforma di osservazione."}},faq={{q="Perché Sparachiodi ha bisogno di questa lente?",a="Sparachiodi ha bisogno delle Lenti Telescopiche per completare il telescopio dell'osservatorio di Porto Paranco. La lente più grande è arrivata via terra da Durotar, ma quella più piccola è andata perduta in mare.",al={"lente di sparachiodi","a cosa serve la lente","perché la lente del telescopio"}},{q="Chi ha rubato le Lenti Telescopiche?",a="I filibustieri dei Mari del Sud hanno rubato le Lenti Telescopiche. Questi pirati umani e goblin depredano le navi mercantili nei pressi della Costa dei Mercanti. Custodiscono la lente in una cassa contrassegnata nel loro accampamento costiero a sud di Porto Paranco.",al={"chi ha preso la lente","chi ha la lente","posizione lenti telescopiche"}},{q="Da dove proveniva originariamente la lente?",a="Le Lenti Telescopiche hanno viaggiato via mare fino a Porto Paranco, mentre l'altra lente è arrivata via terra da Durotar. Le navi che arrivano al porto provengono spesso dall'altra parte del Great Sea o dai possedimenti goblin meridionali, come Baia del Bottino.",al={"dove è stata fatta la lente","origine della lente","dove ha ordinato la lente sparachiodi"}},{q="La lente è intatta nonostante sia stata rubata?",a="La lente è rimasta intatta. Una cassa con la scritta “Fragile - Non far cadere” ha protetto il vetro di precisione dai modi bruschi dei pirati.",al={"la lente è rotta","cassa fragile non far cadere"}}},fx={ddcd39c0={q="Che cosa sono le Lenti Telescopiche?",a="Sono lenti ottiche di precisione progettate per il telescopio di un osservatorio. Sparachiodi commissionò due lenti speciali per completare il telescopio sulla cima della sua torre a Porto Paranco. Questo pezzo secondario, più piccolo, fu spedito oltremare prima di essere intercettato dai Bucanieri dei Mari del Sud.",al={"cosa sono le lenti telescopiche","oggetto lenti telescopiche","cosa sono queste lenti"}}},fp="15,186,15.371.0,14.346.0,32.171.0,30.203.0,40.213.0,43.136.0"}
P.entries["item:teronis-journal"] = {n="Diario di Teronis",s="A Valtetra, il Diario di Teronis racconta la ricerca di una gemma legata a una verga che sperava potesse rallentare gli attacchi dei furbolg.",h="A Valtetra, il Diario di Teronis racconta la ricerca di una gemma legata a una verga che sperava potesse...",kw={"valtetra","astranaar","gemma luminosa","raene braccalupo","raene's cleansing","sentinelle","teronis","diario di teronis"},ang={["faction:Alliance"]="Riportare gli appunti sul campo di Teronis ad Astranaar aiuta la guarnigione a coordinare i soccorsi e a recuperare i resti del proprio esploratore caduto.",["race:NightElf"]="Come Elfo della Notte, puoi leggere il Diario di Teronis per ricordare i pericoli che gli esploratori affrontano proteggendo le antiche foreste di Valtetra dalla corruzione dilagante."},sec={{t="L'ultimo resoconto di un esploratore",b="Teronis era un amico di lunga data di Raene Braccalupo e aiutava le Sentinelle. Cercava a Valtetra una gemma che riteneva appartenesse a una verga capace di rallentare gli attacchi dei furbolg contro il suo popolo. Vicino alla riva, alcune creature aggressive posero fine al suo viaggio.\n\nIl diario fu recuperato tra i suoi effetti personali in condizioni straordinariamente buone. Le sue scoperte su una gemma radiosa che un tempo faceva parte della verga offrono ai difensori di Astranaar una pista per proseguire la sua ricerca incompiuta."}},faq={{q="A chi apparteneva questo diario?",a="Teronis, un Elfo della Notte e amico di lunga data di Raene Braccalupo, era il proprietario del diario. Cercava a Valtetra una gemma legata a una verga che credeva potesse rallentare gli attacchi dei furbolg, ma morì nelle terre selvagge prima di tornare con le sue scoperte.",al={"chi ha scritto il diario","chi è teronis","storia di teronis"}},{q="Dove si trova il diario?",a="Il diario fu trovato tra gli averi di Teronis dopo che fu rinvenuto ucciso nelle terre selvagge di Valtetra. Si trovava vicino alla riva dove vivono i murloc della zona.",al={"dove trovare il diario","posizione del diario di teronis","come ottenere il diario"}},{q="Qual è lo scopo di portare il diario ad Astranaar?",a="Riportare il diario a Raene Braccalupo informa Astranaar della morte di Teronis. I suoi appunti offrono anche alle Sentinelle un modo per proseguire la ricerca della verga che sperava potesse rallentare gli attacchi dei furbolg.",al={"perché portare il diario a raene","a chi consegnare il diario","consegna del diario"}},{q="Quale oggetto stava cercando Teronis secondo la sua missione?",a="Teronis cercava una Gemma Luminosa, un pezzo di una verga creata dal defunto mago Dartol. La sua indagine lasciava supporre che i murloc nelle vicinanze avessero recuperato l'artefatto.",al={"cosa stava cercando teronis","a quale gemma dava la caccia","gemma di teronis"}}},fx={["5fb93f8f"]={q="Che cos'è il Diario di Teronis?",a="Il Diario di Teronis è un taccuino personale tenuto dall'esploratore elfo della Notte Teronis. Ritrovato tra i suoi effetti accanto al suo corpo a Valtetra, descrive la sua missione e i primi tentativi di ricerca di una strana gemma che gli era stato mandato a trovare, prima della sua prematura scomparsa.",al={"cos'è il diario di teronis","oggetto diario di teronis","informazioni sul diario di teronis"}}},fp="16,115,22.463.0,31.224.0,27.158.0,57.192.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="Testa di Tharil'zun",s="A Borgolago, la Testa di Tharil'zun prova che il comandante che terrorizzava Crestarossa è morto. Guidava i Battistrada Roccianera che occupavano Guardamasso.",h="A Borgolago, la Testa di Tharil'zun prova che il comandante che terrorizzava Crestarossa è morto.",kw={"battistrada roccianera","borgolago","maresciallo marris","guardamasso","mastio di guardamasso","tharil'zun","testa di tharil'zun"},ang={["faction:Alliance"]="Ogni capoclan Roccianera ucciso allevia la pressione su Borgolago, una cittadina sotto assedio che lotta per sopravvivere senza rinforzi ufficiali da Roccavento."},sec={{t="Trofeo di Guardamasso",b="Gli orchi Roccianera del Mastio di Guardamasso hanno razziato le fattorie di Borgolago e teso imboscate ai viaggiatori sulle strade. Tharil'zun guidava i Battistrada Roccianera responsabili di quegli attacchi.\n\nIl Maresciallo Marris non intende rischiare agendo sulla base di voci o vittorie parziali. Esige una prova della morte di Tharil'zun, e la testa mozzata gliela fornisce. Le imboscate coordinate dai Battistrada a partire dal mastio hanno subito un duro colpo."}},faq={{q="Chi era Tharil'zun?",a="Tharil'zun era un astuto e feroce comandante degli orchi Roccianera al Mastio di Guardamasso. Guidava i Battistrada Roccianera in incessanti imboscate insieme ai Renegades tra Borgolago e il mastio.",al={"storia di tharil'zun","chi è tharil'zun","leader tharil'zun"}},{q="Perché il Maresciallo Marris vuole la sua testa?",a="Roccavento non concede ingenti aiuti militari a Crestarossa, così il Maresciallo Marris e la guardia di Borgolago si affidano ai mercenari per colpire le principali minacce. Marris ha bisogno di una prova della morte di Tharil'zun per sapere che il comando dei Battistrada è davvero spezzato.",al={"perché la testa di tharil'zun","marris prova testa","taglia di marris"}},{q="Dove si trova Tharil'zun?",a="Tharil'zun controlla il Mastio di Guardamasso sulle colline orientali delle Montagne Crestarossa. Orchi Roccianera e gnoll circondano il mastio.",al={"posizione di tharil'zun","dove si trova tharil'zun","trovare tharil'zun"}},{q="Prendere la testa di Tharil'zun pone fine alla minaccia dei Roccianera?",a="No. La morte di Tharil'zun scompagina le imboscate dei Battistrada, ma il clan Roccianera mantiene un'imponente forza asserragliata nel Mastio di Guardamasso e in tutte le Montagne Crestarossa.",al={"gli orchi se ne sono andati","abbiamo salvato crestarossa","dopo tharil'zun"}}},fx={a015b31b={q="Che cos'è la Testa di Tharil'zun?",a="Questa testa mozzata è la prova tangibile che Tharil'zun, il comandante che dirige le imboscate degli orchi Ferroscuro nei dintorni del Mastio di Guardamasso, è stato ucciso. Riportata a Borgolago, mostra alle guardie cittadine sotto assedio che uno dei più pericolosi comandanti sul campo del clan Ferroscuro nelle Montagne Crestarossa non terrorizzerà più le strade.",al={"oggetto testa di tharil'zun","storia della testa di tharil'zun"}},f673cecf={q="Da dove proviene la Testa di Tharil'zun?",a="È stata prelevata direttamente dal cadavere di Tharil'zun, un importante capo orco Ferroscuro che operava dalle rovine del Mastio di Guardamasso. Dopo che tu o i difensori di Borgolago lo avete sconfitto in battaglia, la testa viene presa come trofeo inconfutabile e macabra prova della sua morte.",al={"chi ha preso la testa di tharil'zun","origine della testa di tharil'zun","da dove viene la testa di tharil'zun"}}},fp="17,139,20.381.0,19.185.0,38.234.0,26.121.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="Speranza di Tharnariun",s="A Rivafosca, Tharnariun Lieveramo cerca una cura per i thistle bear malati. La sua trappola li calma abbastanza a lungo da portarli al suo accampamento.",h="A Rivafosca, Tharnariun Lieveramo cerca una cura per i thistle bear malati.",kw={"rivafosca","plagued lands","rabid thistle bear","tharnariun","speranza di tharnariun","thistle bear","trappola"},ang={["class:Druid"]="Come druido, puoi vedere nella trappola di Tharnariun la scelta di preservare le bestie corrotte finché esiste ancora una possibilità di redimerle.",["race:NightElf"]="Come Elfo della Notte, sai che i thistle bear sono molto amati a Rivafosca. Il loro male rende la trappola di Tharnariun un segno di compassione disperata."},sec={{t="Una trappola delicata",b="Tharnariun Lieveramo ha creato una trappola per calmare i thistle bear malati. Un male misterioso li ha resi sempre più frenetici e violenti in tutta Rivafosca. Spera di curarli invece di vederli uccisi. Posata a terra, la Speranza di Tharnariun emana una luce lenitiva. Un thistle bear rabbioso che la attraversa si calma per un po' e può seguire un viaggiatore fino all'accampamento di Tharnariun per ricevere cure."},{t="Il rimedio sfuggente",b="La magia curativa di Tharnariun Lieveramo non riesce a salvare un orso catturato. La trappola calma l'animale impazzito senza ferirlo, ma la corruzione è più feroce di quanto si aspettasse. Quando incanala il suo potere curativo nell'orso, la sua magia si scontra con l'infezione. L'animale crolla e muore. Sebbene il suo primo tentativo si concluda con un dolore straziante, Tharnariun resta determinato a scoprire la vera natura del male della foresta."}},faq={{q="Cosa fa la Speranza di Tharnariun?",a="La Speranza di Tharnariun calma un thistle bear rabbioso per un po'. Posata sul terreno della foresta, proietta un campo di luce che permette a un viaggiatore di ricondurre pacificamente l'orso da Tharnariun Lieveramo.",al={"uso della speranza di tharnariun","come funziona la trappola","cos'è questa trappola"}},{q="Perché Tharnariun vuole catturare un orso vivo?",a="Tharnariun crede che il male che affligge la fauna di Rivafosca possa essere curato, anziché affrontato con un massacro. Gli serve un orso vivo per mettere alla prova i suoi rimedi purificanti.",al={"perché catturare l'orso cardo","perché catturare un orso rabbioso","cosa vuole tharnariun"}},{q="È possibile ottenere un'altra trappola se viene persa?",a="Sì. Tharnariun dice che la sua speranza è eterna. Se la trappola scatta a vuoto o viene smarrita nelle terre selvagge, torna da lui per averne un'altra.",al={"speranza di tharnariun persa","trappola fallita","trappola scomparsa"}},{q="Cosa succede all'orso una volta riportato indietro?",a="Quando l'orso raggiunge Tharnariun, lui lancia una magia curativa per purificarlo dalla corruzione. Il male sopraffà la bestia, che muore nel giro di pochi istanti.",al={"l'orso sopravvive","tharnariun può curare l'orso","l'orso muore da tharnariun"}}},fx={["820181a1"]={q="Che cos'è la Speranza di Tharnariun?",a="La Speranza di Tharnariun è una trappola incantata ideata da Tharnariun Lieveramo. Quando viene posata a terra, emana una luce calmante capace di placare temporaneamente i ferocissimi orsi cardospino malati che vagano per Rivafosca. L'incantesimo lenitivo rende docile una bestia furiosa e disposta a seguirti fino ad Auberdine.",al={"cos'è la speranza di tharnariun","oggetto speranza di tharnariun","trappola di tharnariun"}},["88ba9e19"]={q="Da dove proviene la Speranza di Tharnariun e chi l'ha creata?",a="La trappola è stata costruita e incantata da Tharnariun Lieveramo, un naturalista elfo della Notte stanziato a Rivafosca. Inorridito dalla misteriosa malattia che spingeva la fauna della foresta alla follia, ha realizzato questo congegno ricorrendo a una magia gentile per sottomettere le bestie infette senza ferirle ulteriormente.",al={"chi ha creato la speranza di tharnariun","origine della speranza di tharnariun","creatore della trappola di tharnariun"}},c80e933b={q="Perché qualcuno vuole la Speranza di Tharnariun?",a="Tharnariun ha bisogno che la trappola venga usata per catturare un orso cardospino rabbioso ancora vivo, così da poter studiare la corruzione che devasta Rivafosca. Una normale battuta di caccia ucciderebbe la bestia, ma questa trappola la placa abbastanza a lungo da permetterti di condurla al sicuro da Tharnariun, nella speranza di trovare una cura.",al={"perché usare la speranza di tharnariun","perché serve la trappola di tharnariun","a cosa serve la speranza di tharnariun"}}},fp="17,135,14.402.0,18.413.1,31.184.0,46.168.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="Libro di Ur",s="A Forte di Zannascura, il Libro di Ur attira l'interesse degli studiosi Reietti. L'Arcimago Arugal lo prese dopo la morte di Ur. Il mago di Dalaran scrisse di strani esseri provenienti da altri piani.",h="A Forte di Zannascura, il Libro di Ur attira l'interesse degli studiosi Reietti.",kw={"apothecarium","arugal","libro di ur","dalaran","protettore bel'dugur","forte di zannascura","selva pinargento","ur"},ang={["class:Mage"]="Per un mago, gli scritti di Ur mostrano quanto gli studiosi di Dalaran avessero approfondito lo studio di altri reami e il prezzo mortale dell'uso improprio che Arugal fece di quelle conoscenze proibite.",["race:Undead"]="Per un non morto, recuperare il lavoro di Ur aiuta gli studiosi della Dark Lady nell'Apothecarium. Le ricerche di un prudente mago umano potrebbero diventare una fonte di potere concreto per i Reietti."},sec={{t="Il Mago di Dalaran",b="Ur era un mago di Dalaran che studiava altri piani e le loro creature. Prima dell'arrivo del Flagello, il Kirin Tor conosceva bene il suo lavoro. Desiderava comprendere la magia oltre questo mondo, ma annotava le sue scoperte anziché squarciare incautamente il velo. Cautela e moderazione guidavano le sue ricerche. Quando il Flagello attaccò Dalaran, né la sua magia né la sua prudenza poterono salvarlo."},{t="L'ambizione dei Reietti",b="Il Libro di Ur contiene gli scritti che l'Arcimago Arugal prese dopo la morte di Ur. Arugal li usò per evocare i worgen nella Selva Pinargento. Ora il libro si trova su uno scaffale a Forte di Zannascura. Il Protettore Bel'dugur dell'Apothecarium di Sepulcra ne ha sentito parlare e vuole il lavoro di Ur. I Reietti non hanno alcuna moderazione di Ur. Useranno una magia pericolosa per sopravvivere e conquistare."}},faq={{q="Chi era Ur?",a="Ur era un mago umano di Dalaran, noto prima della Terza Guerra per i suoi studi su altre dimensioni e sulle loro creature. Si rifiutava di evocarle, temendo il pericolo che rappresentavano.",al={"chi ha scritto il libro di ur","ur mago di dalaran"}},{q="Dove si trova il Libro di Ur?",a="Il Libro di Ur si trova su uno scaffale a Forte di Zannascura, nella Selva Pinargento, nella stanza dove vive la grande bestia Fenrus.",al={"posizione del libro di ur","dove si trova il libro di ur"}},{q="Perché il Protettore Bel'dugur vuole il libro?",a="Il Protettore Bel'dugur raccoglie gli scritti di Ur per alcuni interessati a Sepulcra. I Reietti credono che la coscienza di Ur ne frenasse il potere e cercano di usare le sue ricerche senza limiti etici per rafforzarsi.",al={"protettore bel'dugur libro di ur","perché sepulcra vuole il libro"}},{q="Come è finito il libro a Forte di Zannascura?",a="Dopo la morte di Ur durante la caduta di Dalaran, l'Arcimago Arugal entrò in possesso delle sue ricerche. Cercando un modo per difendersi dal Flagello, Arugal portò gli appunti nella Selva Pinargento e usò le teorie di Ur per evocare i worgen su Azeroth.",al={"arugal e il libro di ur","come ha ottenuto il libro arugal"}}},fx={["62a01830"]={q="Che cos'è il Libro di Ur?",a="Il Libro di Ur è un tomo erudito che contiene le ricerche esoteriche di Ur, un abile mago di Dalaran. Descrive i suoi vasti studi su altri mondi e pericolosi fenomeni arcani: conoscenze tanto potenti che in seguito l'Arcimago Arugal usò gli scritti di Ur per evocare i mostruosi worgen nella Selva Pinargento.",al={"cos'è il libro di ur","storia del libro di ur"}},["905bb2c4"]={q="Da dove proviene il Libro di Ur e chi l'ha scritto?",a="Il libro fu scritto nel regno magico di Dalaran dal mago Ur, prima che la città venisse distrutta dal Flagello. Ur annotò le sue teorie arcane e le esplorazioni di altre dimensioni, ma il suo lavoro fu abbandonato dopo la sua morte durante la caduta di Dalaran.",al={"chi ha scritto il libro di ur","origine del libro di ur","da dove viene il libro di ur"}}},fp="14,174,19.378.0,17.359.1,11.167.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="Programma del Collezionista",s="Vicino al Campo di Zucche dei Pozzonero, il Programma del Collezionista documenta il passaggio di carichi d'oro illeciti attraverso la Foresta di Elwynn. Gli gnoll portano con sé questo itinerario scritto a mano, e il Maresciallo Dughan riconosce il nome che vi compare.",h="Vicino al Campo di Zucche dei Pozzonero, il Programma del Collezionista documenta il passaggio di carichi...",kw={"pozzonero","collezionista","dughan","elwynn","oro","borgodoro","miniere","programma"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere quanto poco controllo Roccavento abbia sul proprio territorio quando squadre non autorizzate ne prelevano le risorse vicino alla capitale.",["profession:Mining"]="Come minatore, puoi vedere che le miniere di Elwynn non sono inattive. I ricchi filoni d'oro vengono svuotati e il minerale portato via."},sec={{t="Oro rubato e carichi segreti",b="L'oro continua a lasciare le miniere di Elwynn a orari prestabiliti, anche se Roccavento non le sfrutta ufficialmente da mesi. Il banditismo e le incursioni delle creature hanno scacciato i minatori. L'itinerario indica i giorni e gli orari in cui una figura chiamata il Collezionista riceve ciascun carico.\n\nLa pista conduce a un accampamento vicino al Campo di Zucche dei Pozzonero, nella parte orientale della Foresta di Elwynn. Il Maresciallo Dughan riconosce il nome del Collezionista quando vede il programma. Chi paghi per l'oro rubato rimane ignoto."}},faq={{q="Che cos'è il Programma del Collezionista?",a="Il Programma del Collezionista indica quando i carichi d'oro lasciano le miniere abbandonate della Foresta di Elwynn, diretti a un agente chiamato il Collezionista.",al={"cos'è questa nota","oggetto programma del collezionista","programma dell'oro"}},{q="Da dove proviene il programma?",a="Gli gnoll portano con sé il programma lungo le rive dei fiumi e i pendii della Foresta di Elwynn. Potrebbero averlo sottratto a un corriere oppure essere coinvolti nel trasporto dell'oro.",al={"chi rilascia il programma","dove trovare il programma"}},{q="Chi è il Collezionista?",a="Il Collezionista è un agente di stanza vicino al Campo di Zucche dei Pozzonero, nella parte orientale della Foresta di Elwynn. Il Maresciallo Dughan riconosce il nome, ma non sa chi serva l'agente.",al={"chi è il collezionista","identità del collezionista"}},{q="Perché il Maresciallo Dughan è allarmato da questo programma?",a="Il Maresciallo Dughan è allarmato perché Roccavento non ha minatori ufficiali nelle miniere di Elwynn da mesi, eppure ne escono ancora ingenti carichi d'oro. Questi carichi indicano un'attività estrattiva illecita e organizzata all'interno del regno.",al={"perché dughan si preoccupa","oro miniere di elwynn"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="Cuore dell'Imbalsamatore",s="A Boscovespro, il cadavere sepolto di Eliza custodisce ancora un cuore pulsante. L'Imbalsamatore mise il proprio cuore nel corpo della moglie morta tramite la magia oscura, e questo divenne il fulcro del suo potere.",h="A Boscovespro, il cadavere sepolto di Eliza custodisce ancora un cuore pulsante.",kw={"bride of the embalmer","borgoscuro","boscovespro","eliza","ello ebonlocke","cuore dell'imbalsamatore","l'imbalsamatore"},ang={["class:Warlock"]="Come stregone, puoi riconoscere come il cuore sostenga la non-morte necromantica attraverso la manipolazione della carne e il vincolo di un'anima.",["race:Human"]="Come umano, senti gli abitanti tormentati di Boscovespro sussurrare della tragica caduta del gentile alchimista."},sec={{t="Un amore che sfidò la morte",b="Borgoscuro ricorda l'Imbalsamatore come un alchimista gentile. Quando sua moglie Eliza morì, il dolore gli spezzò la mente. Ricorse a un'empia stregoneria, si strappò il cuore e lo collocò nel petto senza vita della moglie. La magia risvegliò il suo cadavere alla non-morte. Ma Eliza tornò come una creatura famelica, affamata di carne umana vivente. Inorridito da ciò che aveva fatto, l'alchimista la seppellì di nuovo."},{t="Uno scudo per Borgoscuro",b="Il cuore dell'Imbalsamatore batte ancora nella tomba di Eliza e sostiene il suo potere oscuro. Il sindaco Ello Ebonlocke crede che Borgoscuro possa indebolire la stregoneria dell'Imbalsamatore distruggendo la sua sposa rianimata e recuperando il cuore. Se riusciranno a impossessarsene mentre batte ancora, i capi della cittadina sperano di rivolgerne l'essenza contro il negromante. Sperano che diventi una barriera contro i suoi terrori."}},faq={{q="Perché Eliza possiede il cuore dell'Imbalsamatore?",a="Il dolore spinse l'Imbalsamatore a collocare il proprio cuore pulsante nel cadavere di Eliza tramite una magia proibita. Il rituale la riportò alla non-morte, ma la lasciò affamata di carne umana.",al={"perché eliza ha il cuore","cuore dell'imbalsamatore in eliza","chi ha messo il cuore in eliza"}},{q="Perché il Sindaco Ebonlocke vuole che il cuore sia riportato a Borgoscuro?",a="Il sindaco Ello Ebonlocke spera che la magia oscura del cuore indebolisca l'Imbalsamatore e diventi una barriera che protegga Borgoscuro.",al={"perché ello vuole il cuore","piano di ebonlocke per il cuore","cosa fa borgoscuro con il cuore"}},{q="Come sopravvive l'Imbalsamatore senza il suo cuore?",a="L'Imbalsamatore legò la propria forza vitale e il proprio potere al cuore tramite la stregoneria oscura. Il cuore batte ancora nei resti sepolti della moglie, mentre lui continua a vivere senza.",al={"l'imbalsamatore è vivo","come fa l'imbalsamatore a essere vivo senza cuore"}},{q="Dove si trova il cuore?",a="Il cuore si trova nel corpo di Eliza, sepolta in una tomba nascosta a Boscovespro. È possibile recuperarlo solo affrontando e sconfiggendo la sposa famelica, tornata alla non-morte.",al={"dove si trova il cuore dell'imbalsamatore","posizione tomba di eliza","come ottenere il cuore dell'imbalsamatore"}}},fx={cac9cdef={q="Che cos'è il Cuore dell'Imbalsamatore?",a="È il cuore letterale e magicamente mantenuto in vita dell'alchimista rinnegato noto come l'Imbalsamatore. Impazzito dal dolore per la morte della moglie Eliza, si strappò il cuore e lo pose nel cadavere di lei per riportarla in vita. Anche separato dal suo petto, il cuore funge da ricettacolo e canale del suo potere necromantico, mantenendo sia lo stato di non morta maledetta di Eliza sia la sua stessa vitalità empia.",al={"cos'è il cuore dell'imbalsamatore","storia del cuore dell'imbalsamatore","il cuore dell'imbalsamatore"}}},fp="20,173,24.367.0,22.376.1,41.169.0,66.117.0,48.156.0,29.163.0"}
P.entries["item:the-general-s-response"] = {n="Risposta del Generale",s="Da Roccavento, il Generale Marcus Jonathan risponde alla richiesta d'aiuto di Borgolago mentre Redridge è in pericolo. Il suo dispaccio prende atto dell'appello del Magistrato Solomon contro gli orchi Roccianera e gli gnoll, ma non invia rinforzi immediati da Roccavento.",h="Da Roccavento, il Generale Marcus Jonathan risponde alla richiesta d'aiuto di Borgolago mentre Redridge è in...",kw={"generale marcus jonathan","borgolago","magistrato solomon","messenger to stormwind","redridge","roccavento","risposta del generale"},ang={["faction:Alliance"]="La risposta di Roccavento mostra le tensioni che gravano sulla Grand Alliance. Borgolago versa sangue mentre la corte sembra stranamente insensibile alla sua difficile situazione.",["race:Human"]="Per gli umani dei regni meridionali, la risposta tardiva rivela una frattura crescente tra chi lotta per sopravvivere nelle province e la nobiltà isolata nel Forte di Roccavento."},sec={{t="Una situazione di stallo diplomatico",b="Il Magistrato Solomon chiede a Roccavento truppe per difendere Redridge dai clan di orchi Roccianera e dalle bande da guerra di gnoll che si stanno radunando. Il Generale Marcus Jonathan risponde di aver inoltrato la richiesta al trono, ma per ora non arriveranno soldati. Ordina che la lettera venga riportata a Borgolago. Solomon è turbato dal ritardo e sospetta che qualcosa non vada tra i governanti di Roccavento."}},faq={{q="Cosa c'è scritto nella Risposta del Generale?",a="Il Generale Marcus Jonathan piange i caduti e dice che informerà il Re della difficile situazione di Borgolago. Spera di portare rinforzi e confida che Sua Maestà si fa vedere di rado e si comporta in modo strano.",al={"contenuto della lettera","cosa dice la lettera","lettera del generale"}},{q="Perché il Generale Marcus Jonathan non può inviare truppe a Borgolago?",a="Il Generale Marcus Jonathan attende la risposta del Re prima di promettere rinforzi. In confidenza, dice a Solomon che Sua Maestà si fa vedere di rado e si comporta in modo strano.",al={"perché nessun rinforzo","perché roccavento non aiuta borgolago","perché nessun aiuto"}},{q="Come reagisce il Magistrato Solomon alla lettera?",a="Il Magistrato Solomon è profondamente turbato dal dispaccio. Il ritardo di Roccavento non ha senso mentre Borgolago affronta un simile pericolo, e teme che questa incuria indichi problemi peggiori nel regno.",al={"reazione di solomon","cosa pensa solomon","risposta di solomon"}}},fx={["3ebc4cbb"]={q="Che cos'è la Risposta del Generale?",a="È un dispaccio ufficiale sigillato, scritto dal Generale Marcus Jonathan, comandante della Guardia cittadina di Roccavento, e indirizzato al Magistrato Solomon a Crestarossa. Trasportata dai messaggeri tra la capitale e Borgolago, la missiva comunica la risposta formale dell'alto comando alla disperata richiesta di rinforzi reali da parte di Crestarossa.",al={"cos'è la risposta del generale","oggetto risposta del generale","cos'è questa lettera"}},["174955dc"]={q="Da dove proviene la Risposta del Generale e chi l'ha scritta?",a="La lettera è stata scritta direttamente dal Generale Marcus Jonathan a Roccavento. Dopo aver ricevuto l'urgente richiesta del Magistrato Solomon nella Valle degli Eroi, Jonathan prepara questa risposta formale mentre attende notizie dalla corte reale e affida a te il compito di riportarla al magistrato a Borgolago.",al={"chi ha scritto la risposta del generale","da dove viene la risposta del generale","chi ha inviato la risposta del generale"}},d0ef00e9={q="Perché qualcuno vuole la Risposta del Generale?",a="Il Magistrato Solomon attende con ansia questo dispaccio per sapere se Roccavento invierà soldati a salvare Borgolago dagli orchi Ferroscuro e dai gnoll. Consegnandolo, darai ai capi della città assediata una risposta chiara sugli aiuti che il regno può, o non può, fornire.",al={"perché solomon vuole la lettera","chi vuole la risposta del generale","perché consegnare la risposta del generale"}}},fp="22,247,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-lich-s-spellbook"] = {n="Grimorio del Lich",s="Sull'isola del Lago di Acqualucente, Bethor Scheggiafredda cerca un grimorio custodito da un lich dotato di libero arbitrio. Spera che le sue pagine rivelino l'abilità del lich e chi fosse in vita.",h="Sull'isola del Lago di Acqualucente, Bethor Scheggiafredda cerca un grimorio custodito da un lich dotato di...",kw={"bethor scheggiafredda","lago di acqualucente","gunther arcanus","lich","negromanzia","grimorio","radure di tirisfal","sepulcra"},ang={["class:Mage"]="Come mago, puoi vedere come il grimorio unisca la magia di Dalaran all'oscura negromanzia. Il suo autore ha perfezionato enormemente la propria arte dopo essere diventato un non morto.",["race:Undead"]="Come non morto, sai che alcuni di coloro che sfuggirono al controllo del Re dei Lich non si unirono subito ai Reietti. I non morti indipendenti sopravvissuti sparsi per Tirisfal diffidano ancora gli uni degli altri."},sec={{t="I tomi di un maestro recluso",b="Un lich dotato di libero arbitrio sorveglia un'isola nel Lago di Acqualucente con i suoi servitori scheletrici. Diffida del mondo esterno e scambia gli altri non morti per schiavi del Flagello. Così ordina ai suoi guardiani di uccidere chiunque si avvicini.\n\nBethor Scheggiafredda cerca abili negromanti per i Reietti al servizio della regina Sylvanas Ventolesto. Invia un emissario nell'accampamento sull'isola per prendere il grimorio del lich. Bethor spera che le sue pagine rivelino il potere del maestro e la sua identità prima che la morte travolgesse Lordaeron."},{t="Smascherare Gunther Arcanus",b="Il grimorio recuperato identifica il lich solitario come Gunther Arcanus, vecchio amico e compagno d'armi di Bethor Scheggiafredda da prima della Terza Guerra. In vita, Gunther era un prodigio della negromanzia. I suoi scritti mostrano che il suo potere è cresciuto nella non morte.\n\nBethor sa che Gunther potrebbe diventare un prezioso maestro delle arti oscure per i Reietti. Prima, qualcuno deve convincere il lich sospettoso che i Reietti sono liberi dalla morsa del Re dei Lich."}},faq={{q="Dove si trova il Grimorio del Lich?",a="Il grimorio si trova in un contenitore chiamato Gunther's Books, nell'accampamento sull'isola centrale del Lago di Acqualucente, nelle Radure di Tirisfal settentrionali.",al={"dove si trova il libro","posizione del grimorio","gunther's books"}},{q="A chi appartiene questo grimorio?",a="Il libro appartiene a un lich solitario dotato di libero arbitrio, sull'isola del Lago di Acqualucente. Bethor Scheggiafredda spera che le sue pagine rivelino l'identità e l'abilità del lich.",al={"di chi è questo libro","identità del lich","chi ha scritto il grimorio"}},{q="Perché Bethor Scheggiafredda vuole il libro?",a="Bethor Scheggiafredda vuole scoprire l'identità del lich e valutare la sua abilità nella negromanzia. Spera di reclutarlo per Dama Sylvanas e i Reietti.",al={"perché recuperare il libro","motivo della missione di bethor","perché undercity lo vuole"}},{q="Perché il lich attacca i visitatori della sua isola?",a="Il lich crede che gli altri non morti nelle vicinanze siano ancora schiavi del Flagello sotto controllo mentale. Ordina ai suoi servitori di attaccare chiunque si avvicini al suo rifugio sull'isola.",al={"perché gunther è ostile","perché i servitori attaccano","lago di acqualucente ostile"}},{q="Cosa spera di scoprire Bethor sull'autore?",a="Bethor spera di scoprire chi fosse in vita il lich isolato e se le sue conoscenze negromantiche possano aiutare i Reietti.",al={"cosa scoprirà bethor","studio dell'autore lich","studio del grimorio di bethor"}}},fx={["44ee6981"]={q="Da dove viene il Grimorio del Lich e chi l'ha scritto?",a="Il grimorio appartiene al lich solitario e dotato di libero arbitrio che dimora sull'isola nel Lago di Acqualucente. Ha scritto e aggiornato il tomo di persona, riempiendone le pagine luminose con le sue arti necromantiche sia in vita sia dopo la trasformazione in lich. Bethor Scheggiafredda lo vuole per scoprire chi fosse il lich.",al={"chi ha scritto il grimorio del lich","origine del grimorio del lich","da dove viene il grimorio del lich"}}},fp="20,161,26.483.0,25.432.1,36.140.0,24.154.1,39.145.0,48.149.0,48.117.1"}
P.entries["item:the-state-of-lakeshire"] = {n="Relazione su Borgolago",s="I difensori di Borgolago subiscono attacchi e il Magistrato Solomon chiede aiuto a Roccavento. Il suo rapporto esorta il Generale Marcus Jonathan a inviare rinforzi reali per affrontare la crisi a Crestarossa.",h="I difensori di Borgolago subiscono attacchi e il Magistrato Solomon chiede aiuto a Roccavento.",kw={"dispaccio","magistrato solomon","marcus jonathan","crestarossa","rinforzi","rapporto","relazione su borgolago","roccavento"},ang={["faction:Alliance"]="Per l'Alleanza, il rapporto mostra quanto siano esposti gli insediamenti periferici e come i ritardi politici nella capitale rallentino gli aiuti militari.",["race:Human"]="Come umano del regno, portando questo rapporto scopri come la gente comune di Crestarossa stia perdendo i legami con la lontana corona di Roccavento."},sec={{t="Un grido d'aiuto",b="Il Magistrato Solomon scrive che gli attacchi minacciano Borgolago. Gli orchi Roccianera e gli gnoll incalzano la cittadina, e i suoi difensori non possono presidiare i confini per sempre. I corrieri portano il suo dispaccio a ovest, lungo la strada verso la Foresta di Elwynn. Solomon chiede all'esercito di Roccavento di proteggere i territori orientali del regno."},{t="Burocrazia e stallo",b="Alle porte di Roccavento, il Generale Marcus Jonathan riceve il rapporto di Solomon. Rispetta l'autorità del magistrato e comprende il pericolo, ma non può mobilitare l'esercito da solo. Lo schieramento delle truppe richiede il consenso della corona. La supplica di Borgolago deve quindi attendere un consiglio con il giovane Re e il reggente Bolvar Fordragon."}},faq={{q="Cos'è Relazione su Borgolago?",a="Il dispaccio ufficiale del Magistrato Solomon descrive il pericolo militare che minaccia Borgolago e chiede a Roccavento rinforzi.",al={"documento relazione su borgolago","cos'è questo rapporto","messaggio di solomon"}},{q="Chi dovrebbe ricevere questo dispaccio?",a="Il Generale Marcus Jonathan è il destinatario del dispaccio. Comanda la guardia cittadina di Roccavento e le forze reali ed è di stanza alle porte di Roccavento.",al={"chi riceve il rapporto","a chi consegnare","rapporto per marcus jonathan"}},{q="Perché Borgolago ha bisogno dei rinforzi reali?",a="Gli orchi Roccianera, gli gnoll Shadowhide e i murloc locali continuano ad assediare Borgolago, sopraffacendo la guardia cittadina. L'insediamento ha bisogno di rinforzi reali.",al={"perché borgolago è in pericolo","cosa minaccia crestarossa"}},{q="Il Generale Marcus Jonathan invia subito aiuto?",a="No. Il Generale Marcus Jonathan riconosce la gravità della crisi, ma ha bisogno dell'approvazione formale del Re per schierare l'esercito. La richiesta deve prima essere esaminata dalla corona.",al={"roccavento aiuta","jonathan invia truppe"}}},fx={["629511cc"]={q="Da dove viene la Relazione su Borgolago e chi l'ha scritta?",a="Il Magistrato Solomon, leader civico e giudice di Borgolago, ha redatto questa relazione cruciale. Sottoposto alla pressione incessante delle forze ostili che circondano la città, Solomon ha scritto personalmente il dispaccio per descrivere formalmente la pericolosa situazione di Redridge e chiedere ai vertici di Roccavento aiuti militari immediati.",al={"chi ha scritto la relazione su borgolago","chi ha redatto la relazione su borgolago","autore della relazione su borgolago"}},["09d61feb"]={q="Perché la Relazione su Borgolago è così urgente?",a="Borgolago è sotto assedio costante e il Magistrato Solomon sa che la città non può resistere da sola senza rinforzi reali. Il Generale Marcus Jonathan ha bisogno di questa relazione ufficiale per giustificare l'invio di unità dell'Esercito di Roccavento e presentare la disperata situazione di Borgolago direttamente al Re e al Gran Signore Bolvar Domadraghi.",al={"perché serve la relazione su borgolago","perché consegnare la relazione su borgolago","perché marcus jonathan vuole la relazione su borgolago"}}},fp="22,188,13.289.0,24.301.0,31.130.0,41.150.0,45.150.0,51.161.0"}
P.entries["item:theramore-medal"] = {n="Medaglia di Theramore",s="Alla Fortezza dei Custodi del Nord, la Medaglia di Theramore attesta il servizio dei marine e degli ufficiali che difendono l'avamposto sulla Costa dei Mercanti. Il suo marchio identifica la guarnigione dell'Alleanza.",h="Alla Fortezza dei Custodi del Nord, la Medaglia di Theramore attesta il servizio dei marine e degli ufficiali...",kw={"savane","capitano fairmount","costa dei mercanti","fortezza dei custodi del nord","thalo'thas chiarosole","medaglia di theramore"},ang={["faction:Alliance"]="Per i fedeli all'Alleanza, le medaglie di Theramore raccolte come taglie di sangue mostrano quanto la Fortezza dei Custodi del Nord sia diventata isolata e aggressiva sulla frontiera di Kalimdor.",["faction:Horde"]="Per gli avventurieri dell'Orda, queste medaglie sono la prova della crescente presenza militare dell'Alleanza sulle coste delle Savane."},sec={{t="Simboli dei Custodi del Nord",b="Marine, tiratori, incursori e ufficiali in servizio presso la Fortezza dei Custodi del Nord portano medaglie con impresso il marchio di Theramore. Sono fedeli al regno di Dama Jaina Marefiero. Per le truppe umane sulle scogliere che dominano le Savane, le medaglie dimostrano che il loro servizio è legittimo e la loro autorità proviene da Theramore.\n\nAltri vedono queste insegne come trofei di una guarnigione straniera fin troppo zelante. La Fortezza dei Custodi del Nord considera ogni imbarcazione che si avvicina alla costa una minaccia mortale."},{t="Vendetta pirata",b="Le batterie di cannoni della Fortezza dei Custodi del Nord minacciano le navi lungo la Costa dei Mercanti, bombardando spesso sia corsari che mercantili. Dopo aver perso alcune navi sotto il fuoco di quei cannoni, il Capitano Thalo'thas Chiarosole, corsaro di Porto Paranco, cerca le medaglie.\n\nVuole la prova che i soldati dal grilletto facile della Fortezza dei Custodi del Nord abbiano pagato col sangue per aver affondato le sue navi, e che i responsabili siano stati uccisi per vendetta."}},faq={{q="Che cos'è una Medaglia di Theramore?",a="Il marchio di Theramore sulla medaglia identifica chi la porta come marine, marinaio o ufficiale in servizio nella guarnigione dell'Alleanza alla Fortezza dei Custodi del Nord, nelle Savane.",al={"medaglia di theramore","cosa sono le medaglie di theramore","medaglia dei custodi del nord"}},{q="Chi porta queste medaglie?",a="Marine, tiratori scelti, marinai di coperta, incursori, cannonieri veterani e ufficiali in servizio alla Fortezza dei Custodi del Nord portano queste medaglie lungo la Costa dei Mercanti.",al={"chi possiede le medaglie di theramore","chi rilascia le medaglie di theramore","da dove provengono le medaglie di theramore"}},{q="Perché il Capitano Thalo'thas Chiarosole le vuole?",a="L'artiglieria della Fortezza dei Custodi del Nord ha bombardato le navi di passaggio, comprese quelle della flotta del Capitano Thalo'thas Chiarosole. Il capitano esige le medaglie come prova che i soldati responsabili siano stati uccisi per vendetta.",al={"perché porto paranco vuole le medaglie","medaglie di chiarosole","perché raccogliere le medaglie di theramore"}},{q="Perché la Fortezza dei Custodi del Nord attacca le navi di passaggio?",a="La guarnigione della Fortezza dei Custodi del Nord vive nella paranoia ai margini del territorio dell'Orda. I suoi cannonieri sono diventati avventati e dal grilletto facile, e sparano su quasi ogni imbarcazione che si avvicina alla loro enclave costiera.",al={"perché la fortezza dei custodi del nord spara alle navi","aggressività della fortezza dei custodi del nord","perché la fortezza dei custodi del nord attacca porto paranco"}}},fp="15,169,20.455.0,16.386.0,26.153.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="Pelliccia d'Orso Folta",s="A Dun Morogh, la Pelliccia d'Orso Folta aiuta viaggiatori e soldati a resistere al freddo montano. Gli orsi vagano per le distese innevate e le loro pelli servono a confezionare abiti e giacigli isolanti.",h="A Dun Morogh, la Pelliccia d'Orso Folta aiuta viaggiatori e soldati a resistere al freddo montano.",kw={"gridapietra","dun morogh","tana selvaggia","ice claw bear","jetsteam","scalo di grigliafredda","pelliccia d'orso folta"},ang={["class:Hunter"]="Come cacciatore, impari a muoverti nella fredda boscaglia di Dun Morogh, a seguire furtivamente pericolose bestie montane e a raccogliere materiali resistenti nella natura selvaggia.",["race:Gnome"]="Come gnomo, sai che piloti come Gridapietra allo Scalo di Grigliafredda si affidano alla caccia nelle terre dei nani per rendere vivibili le loro macchine durante le lunghe missioni alpine."},sec={{t="Calore contro il Gelo Montano",b="Gli orsi percorrono i crinali di Dun Morogh, attraversando alcune delle distese innevate più inospitali dei Regni Orientali. Il loro folto manto li protegge dalle bufere di neve e gli abitanti del posto e i viaggiatori ne utilizzano le pelli. I cacciatori le raccolgono per foderare abiti, isolare avamposti pieni di spifferi e imbottire freddi giacigli da campo."},{t="Giacigli per la Siege Brigade",b="Il Pilota Gridapietra equipaggiò il suo carro d'assedio, Jetsteam, allo Scalo di Grigliafredda per trascorrere un mese sul campo in una lunga missione per la Siege Brigade. Il ferro freddo offriva poco conforto tra gli alti cumuli di neve, così assoldò esploratori locali per raccogliere folte pellicce d'orso nelle distese innevate a sud della Tana Selvaggia. Le pelli sarebbero servite a preparare un caldo giaciglio nei suoi alloggi in cabina."}},faq={{q="Da dove proviene la Pelliccia d'Orso Folta?",a="La Pelliccia d'Orso Folta si ricava dagli orsi di Dun Morogh, tra cui Young Black Bears e Ice Claw Bears. Cacciano nella tundra innevata e nelle pinete a sud della Tana Selvaggia.",al={"dove trovare pelliccia d'orso folta","chi rilascia pelliccia d'orso folta","posizione pelliccia d'orso"}},{q="Perché il Pilota Gridapietra ha bisogno di questa pelliccia?",a="Al Pilota Gridapietra servono folte pellicce d'orso per preparare un caldo giaciglio all'interno del suo carro armato, Jetsteam. Lo sta equipaggiando per una missione di un mese con la Siege Brigade e il giaciglio lo aiuterà a resistere alle fredde notti montane.",al={"pelliccia gridapietra","perché gridapietra ha bisogno di pelliccia","rifornire jetsteam di pellicce"}},{q="Quali creature di Dun Morogh forniscono questa pelle?",a="Young Black Bears e Ice Claw Bears forniscono Pelliccia d'Orso Folta. Entrambi vagano tra le nevi delle alture di Dun Morogh e la loro folta pelliccia viene usata per preparare giacigli invernali e fornire isolamento termico.",al={"quali orsi rilasciano pellicce","tipi di orsi di dun morogh"}}},fx={a2edc513={q="Che cos'è la Pelliccia d'Orso Folta?",a="La Pelliccia d'Orso Folta è la pesante pelliccia isolante ricavata dagli orsi selvatici che vagano tra le gelide rupi e i cumuli di neve di Dun Morogh. Adattata per sopravvivere a bufere pungenti con temperature sotto zero, questa folta pelle offre calore e protezione essenziali contro il freddo alpino implacabile di Khaz Modan.",al={"pelliccia d'orso folta","che cos'è questa pelliccia","pelliccia d'orso di dun morogh"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Distintivo dei Cardosecco",s="Nelle Miniere della Morte, il Distintivo dei Cardosecco è tutto ciò che resta dopo il crollo di una galleria.",h="Nelle Miniere della Morte, il Distintivo dei Cardosecco è tutto ciò che resta dopo il crollo di una galleria.",kw={"miniere della morte","lega degli esploratori","rivoluna","oh fratello","cardosecco","distintivo dei cardosecco","marche occidentali","wilder"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi dare pace a un nano in lutto nel Distretto dei Nani di Roccavento.",["race:Dwarf"]="Come nano, sai che il Caposquadra Cardosecco portò il distintivo della Lega degli Esploratori nelle Marche Occidentali. Recuperarlo impedisce che un figlio caduto di Forgiardente venga dimenticato."},sec={{t="La Lega degli Esploratori nelle Miniere della Morte",b="Prima che la Fratellanza dei Defias sigillasse Rivoluna e le gallerie sottostanti, i prospettori della Lega degli Esploratori di Forgiardente lavoravano nelle vecchie miniere d'oro delle Marche Occidentali. Il Caposquadra Cardosecco e la sua squadra erano nelle profondità quando una galleria crollò, separandoli. Suo fratello Wilder fuggì a Roccavento, ma il caposquadra e diversi operai rimasero intrappolati sottoterra."},{t="Una triste conferma",b="Il Caposquadra Cardosecco morì nelle gallerie non sigillate e risorse come non morto privo di senno tra i pozzi crollati all'esterno della fonderia principale. Il suo distintivo della Lega degli Esploratori rimase con lui. Wilder, suo fratello in lutto, riceve il distintivo, che dimostra la morte del caposquadra."}},faq={{q="A chi appartiene questo distintivo?",a="Il distintivo apparteneva al Caposquadra Cardosecco, un minatore nano e membro della Lega degli Esploratori. Il crollo di una galleria lo intrappolò nelle profondità delle Marche Occidentali.",al={"chi possedeva il distintivo dei cardosecco","proprietario distintivo dei cardosecco"}},{q="Dove si trova il distintivo?",a="Il Caposquadra Cardosecco porta con sé il distintivo nei corridoi superiori delle Miniere della Morte, infestati di mostri, fuori dall'ingresso principale della roccaforte dei Defias.",al={"posizione distintivo","come ottenere il distintivo dei cardosecco","dove trovare cardosecco"}},{q="Chi vuole il Distintivo dei Cardosecco?",a="Wilder Cardosecco vuole il distintivo. Il fratello del caposquadra vive nel Distretto dei Nani di Roccavento e attende notizie sulla sorte del suo congiunto.",al={"chi riceve il distintivo dei cardosecco","a chi si consegna oh fratello","posizione di wilder cardosecco"}},{q="Perché i fratelli Cardosecco si trovavano nelle Miniere della Morte?",a="I fratelli esplorarono e cercarono giacimenti nelle caverne ricche di minerali sotto Rivoluna per conto della Lega degli Esploratori. Ladri ostili e crolli nelle gallerie rovinarono la loro spedizione.",al={"perché i nani erano nelle miniere della morte","missione di cardosecco miniere della morte"}}},fp="21,84,38.365.0,19.261.1,30.162.0,25.143.0,32.137.0,53.168.0"}
P.entries["item:thresher-eye"] = {n="Occhio di Plesiosauro",s="A Rivafosca, Bigbang Ruotacric ha bisogno di Occhi di Plesiosauro per i suoi Buzzbox. Li usa per riparare il Buzzbox 411, un apparecchio di comunicazione sulla spiaggia a nord di Auberdine.",h="A Rivafosca, Bigbang Ruotacric ha bisogno di Occhi di Plesiosauro per i suoi Buzzbox.",kw={"auberdine","buzzbox 411","rivafosca","darkshore thresher","occhio di plesiosauro","bigbang ruotacric"},ang={["profession:Engineering"]="L'uso di parti animali per riparare relè meccanici da parte di Bigbang è un insolito esempio di ingegneria gnomica.",["race:Gnome"]="Come gnomo, puoi scorgere in Bigbang Ruotacric un lato più selvaggio dell'ingegno gnomico. Armeggia con i macchinari da campo nelle terre selvagge di Kalimdor, tra una coppa di crawler wine e l'altra."},sec={{t="Campioni ecologici per congegni gnomeschi",b="I Darkshore Threshers cacciano tra la risacca e i bassi fondali più esterni al largo di Rivafosca. Minacciano i pescatori e i viaggiatori locali, e i loro grandi occhi hanno attirato l'interesse di Bigbang Ruotacric. L'ingegnere gnomo è di stanza nelle vicinanze ed è un appassionato di crawler wine. Gli servono gli occhi per riparare il Buzzbox 411, un apparecchio di comunicazione sulla spiaggia a nord di Auberdine."},{t="Lo scopo degli occhi",b="Bigbang non spiega come degli occhi viscidi possano riparare macchinari delicati. Potrebbero fungere da lenti rudimentali, agenti chimici o ingranaggi biologici. Qualunque sia il metodo, tre occhi inseriti nello sportello di manutenzione del Buzzbox 411 ne ripristinano il collegamento di comunicazione. Bigbang invia poi provviste attraverso trasmissioni soffocate dalle interferenze."}},faq={{q="Da dove provengono gli Occhi di Plesiosauro?",a="Gli Occhi di Plesiosauro si ricavano dai Darkshore Threshers e dagli Elder Darkshore Threshers nell'oceano al largo di Rivafosca, soprattutto vicino ad Auberdine.",al={"dove si trovano gli occhi di plesiosauro","come ottenere occhio di plesiosauro","fonte occhio di plesiosauro"}},{q="Perché Bigbang Ruotacric vuole gli Occhi di Plesiosauro?",a="Bigbang vuole Occhi di Plesiosauro per i suoi Buzzbox. Li usa per riparare il Buzzbox 411, un apparecchio di comunicazione gnomico sulla costa a nord di Auberdine. Inserendo gli occhi nel suo sportello si ripristinano i sistemi dell'apparecchio.",al={"perché servono occhi di plesiosauro","occhi buzzbox 411","a cosa servono gli occhi di plesiosauro"}},{q="In che modo un occhio può riparare una macchina?",a="Bigbang Ruotacric non spiega come un occhio possa riparare una macchina. Il Buzzbox 411 accetta gli occhi e si riaccende, ma resta poco chiaro se usi le loro retine per la messa a fuoco o costruisca con le loro parti organiche.",al={"perché occhi per una macchina","parti biologiche macchina gnomo"}},{q="Cos'è il Buzzbox 411?",a="Il Buzzbox 411 è uno dei vari dispositivi di comunicazione e monitoraggio che Bigbang Ruotacric ha collocato in tutta Rivafosca. Una volta caricato con i materiali richiesti, gli permette di comunicare a distanza e distribuire provviste.",al={"scopo buzzbox 411","chi ha costruito buzzbox 411"}}},fx={eb2ee385={q="Che cos'è un Occhio di Plesiosauro?",a="L'Occhio di Plesiosauro è l'organo visivo ricavato dai plesiosauri predatori che nuotano nelle acque costiere al largo di Darkshore. Per la maggior parte si tratta di semplice materiale biologico, ma l'eccentrico inventore Bigbang Ruotacric ne trova strani impieghi meccanici o chimici per riparare i suoi ronzatori a lunga distanza.",al={"che cos'è l'occhio di plesiosauro","occhi di plesiosauro"}}},fp="12,168,38.344.0,23.314.0,33.128.0,48.213.0,30.217.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="Testa di Thule",s="A Mausolea, il Gran Esecutore Hadrec cerca la prova che Thule Ravenclaw sia morto. La sua testa mozzata conferma che il comandante del Flagello sull'Isola di Fenris è caduto e aiuta i Reietti a mantenere il controllo della Selva Pinargento.",h="A Mausolea, il Gran Esecutore Hadrec cerca la prova che Thule Ravenclaw sia morto.",kw={"fenris","hadrec","negromante","ravenclaw","flagello","mausolea","thule"},ang={["faction:Horde"]="La morte di Thule Ravenclaw mette al sicuro i confini orientali della Selva Pinargento e protegge il territorio appena conquistato dall'Orda dagli attacchi del Flagello.",["race:Undead"]="Per i Reietti, mozzare la testa di Thule è una vittoria militare e una vendetta personale contro il dominio del Re dei Lich su Lordaeron."},sec={{t="Trofeo dell'Isola di Fenris",b="L'Isola di Fenris è la principale roccaforte del Flagello del Re dei Lich nella Selva Pinargento. Da Forte Fenris, il negromante Thule Ravenclaw comanda rot hide e servitori non morti che minacciano gli avamposti dei Reietti, tra cui Mausolea. Il Gran Esecutore Hadrec non accetta alcuna notizia della morte di Thule senza la sua testa mozzata.\n\nQuando Thule muore, la magia oscura si propaga nei boschi. La sua testa fornisce a Hadrec la prova necessaria per dichiarare espugnata l'Isola di Fenris."}},faq={{q="Chi vuole la Testa di Thule?",a="Il Gran Esecutore Hadrec comanda le forze dei Reietti da Mausolea, nella Selva Pinargento. Esige la Testa di Thule come prova della morte del capo del Flagello.",al={"chi ha bisogno della testa di thule","a chi consegnare la testa di thule","chi prende la testa di thule"}},{q="Chi era Thule Ravenclaw?",a="Thule Ravenclaw è un potente negromante che comanda il Flagello sull'Isola di Fenris. Da Forte Fenris, dirige gli attacchi contro i Reietti e ricorre a incantesimi come Hex of the Ravenclaw.",al={"storia di thule","chi è thule","origini di thule ravenclaw"}},{q="Perché i Reietti esigono proprio la sua testa?",a="I Reietti non possono lasciare Silverpine sotto la minaccia del Flagello. I negromanti sono noti per i loro inganni e le oscure resurrezioni, perciò il Gran Esecutore Hadrec esige una prova tangibile della distruzione di Thule.",al={"perché la testa di thule","perché vogliono la sua testa"}},{q="Cosa succede quando Thule Ravenclaw viene ucciso?",a="Quando Thule Ravenclaw viene ucciso, un'esplosione di energia necrotica si propaga in tutta la regione. Gli studiosi e gli speziali dei Reietti a Mausolea avvertono l'onda d'urto magica da lontano.",al={"cosa succede dopo la morte di thule","energia rilasciata thule"}}},fx={["3fe7e40b"]={q="Da dove viene la Testa di Thule?",a="Questa testa mozzata è stata presa direttamente dal negromante Thule Ravenclaw, tra le sale del Forte Fenris. Thule guidava le forze del Flagello che conquistarono l'Isola di Fenris, nella parte settentrionale della Selva Pinargento, trasformando la roccaforte in un baluardo dei non morti finché non l'hai abbattuto.",al={"origine della testa di thule","dove si trova la testa di thule","provenienza della testa di thule"}}},fp="12,201,21.432.1,23.152.0,24.198.0,49.193.0,43.163.1"}
P.entries["item:thunder-lizard-blood"] = {n="Sangue di Sauro del Tuono",s="I cacciatori tornano dalle Savane Meridionali con il Sangue di Sauro del Tuono. Proviene dalle grandi bestie che vagano per le pianure.",h="I cacciatori tornano dalle Savane Meridionali con il Sangue di Sauro del Tuono.",kw={"savane","camp taurajo","jorn skyseer","stormhide","stormsnout","sangue di sauro del tuono","thunderhead"},ang={["class:Hunter"]="Come cacciatore, hai bisogno di un passo saldo e di agilità per sconfiggere un sauro del tuono. Prelevare il suo sangue dimostra la tua padronanza nella caccia alle bestie più grandi della savana.",["race:Tauren"]="Come cacciatore tauren di Camp Taurajo, affronti i sauri del tuono in una tradizionale prova di sopravvivenza tra i formidabili giganti della tua terra."},sec={{t="Trofeo della Caccia",b="Stormsnout, Stormhide e Thunderhead sono i nomi dati ai sauri del tuono nelle pianure. I loro passi pesanti scuotono la terra e il loro peso schiacciante può appiattire un cacciatore incauto. Riportare il loro sangue dimostra l'abilità necessaria per cacciarli e la forza per sopravvivere sotto i loro piedi tonanti."}},faq={{q="Quali creature forniscono questo sangue?",a="Stormsnout, Stormhide e Thunderhead forniscono il sangue. Questi sauri del tuono adulti vagano per la savana intorno a Camp Taurajo, nelle Savane Meridionali.",al={"chi rilascia sangue di sauro del tuono","dove ottenere sangue di sauro del tuono","quali sauri del tuono"}},{q="Perché il Sangue di Sauro del Tuono è ricercato?",a="Jorn Skyseer a Camp Taurajo chiede ai cacciatori di raccogliere il sangue nell'ambito di prove nelle Savane. Riportarlo integro dimostra che un cacciatore sa affrontare le più grandi bestie di Kalimdor dal passo tonante.",al={"chi vuole sangue di sauro del tuono","a cosa serve il sangue di sauro del tuono"}},{q="Dove si trovano di solito questi sauri del tuono?",a="I sauri dell'Eco della Tempesta vagano per le praterie a nord, est e sud di Camp Taurajo. Lì pascolano accanto agli altri grandi animali delle Savane Meridionali.",al={"posizioni dei sauri del tuono","dove sono i stormsnout"}}},fx={["25735f1e"]={q="Che cos'è il Sangue di Sauro del Tuono?",a="Il Sangue di Sauro del Tuono è un fluido vitale ricavato dagli enormi sauri del tuono che vagano per le Savane Meridionali. Queste bestie colossali fanno tremare le pianure a ogni passo; il loro sangue dimostra in modo inconfutabile che un cacciatore possedeva l'abilità e la resistenza necessarie per abbattere creature tanto formidabili senza essere schiacciato sotto i loro piedi.",al={"che cos'è il sangue di sauro del tuono","oggetto sangue di sauro del tuono","informazioni sul sangue di sauro del tuono"}},d2820178={q="Da dove viene il Sangue di Sauro del Tuono e chi lo produce?",a="Questo sangue proviene naturalmente dai possenti sauri del tuono che abitano le Savane Meridionali, in particolare dalle specie note come Musi Tempestosi, Pelli Tempestose e Teste del Tuono. Non è fabbricato né lavorato da mani mortali, ma viene prelevato direttamente da queste bestie colossali dai cacciatori che osano affrontarne gli zoccoli travolgenti nella savana.",al={"da dove viene il sangue di sauro del tuono","chi produce il sangue di sauro del tuono","origine del sangue di sauro del tuono"}}},fp="20,118,18.304.0,34.152.0,41.186.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="Corno di Sauro del Tuono",s="Nelle Savane, Mastro Birraio Drohn cerca un Corno di Sauro del Tuono per la leggendaria bevanda di Chen Birra Triplo Malto.",h="Nelle Savane, Mastro Birraio Drohn cerca un Corno di Sauro del Tuono per la leggendaria bevanda di Chen Birra...",kw={"savane","mastro birraio drohn","chen birra triplo malto","owatanka","porto paranco","stormsnout","birra triplo malto","corno di sauro del tuono","thunderhead"},ang={["class:Hunter"]="Come cacciatore, fai attenzione quando segui le tracce dei sauri dell'Eco della Tempesta nella savana aperta. I loro fulmini li rendono più letali dei comuni kodo o plainstrider delle Savane.",["profession:Cooking"]="Come cuoco, potresti trovare insolita la ricetta di Drohn. Combina organi di plainstrider, zanne di predatori e il corno di una bestia in una bevanda inebriante."},sec={{t="Un potente reagente per la birrificazione",b="I sauri dell'Eco della Tempesta vagano per le Savane, con i corpi crestati che crepitano di fulmini. A Porto Paranco, Mastro Birraio Drohn apprezza i loro corni per la Birra Triplo Malto. Il suo mentore apprese la ricetta dal Mastro Birraio pandaren errante Chen Birra Triplo Malto e la tramandò a Drohn. Il corno conferisce alla bevanda la sua potente sferzata."}},faq={{q="A cosa serve il corno?",a="Mastro Birraio Drohn a Porto Paranco usa il corno nella bevanda resa famosa da Chen Birra Triplo Malto.",al={"uso del corno di sauro del tuono","cosa richiede il corno di sauro del tuono","a cosa serve il corno di sauro del tuono"}},{q="Da quali bestie si può ottenere un corno di sauro del tuono?",a="Thunderheads, stormsnouts, thunderstomps, stormhides e l'elusivo Owatanka possono fornire un corno di sauro del tuono.",al={"dove ottenere il corno di sauro del tuono","chi rilascia il corno di sauro del tuono","fonti del corno di sauro del tuono"}},{q="Chi è Mastro Birraio Drohn?",a="Mastro Birraio Drohn produce birra a Porto Paranco. Il suo vecchio mentore apprese la ricetta della Birra Triplo Malto da Chen Birra Triplo Malto e gliela tramandò.",al={"chi è drohn","storia di mastro birraio drohn","drohn porto paranco"}},{q="È pericoloso cacciare i sauri dell'Eco della Tempesta per i loro corni?",a="I sauri dell'Eco della Tempesta possono scaricare fulmini e scatenare fragorose pestate quando vengono provocati. Cacciarli da soli è pericoloso.",al={"quanto sono forti i sauri dell'eco della tempesta","caccia ai sauri dell'eco della tempesta"}}},fx={["6ace69b3"]={q="Che cos'è un Corno di Sauro del Tuono?",a="Un corno di sauro del tuono è un robusto trofeo naturale ricavato dai grandi sauri del tuono che vagano per le pianure di The Barrens. Questi imponenti rettili, legati alle tempeste, incanalano energia elettrica nei loro enormi corpi; i loro corni sono quindi componenti naturali potenti, ricercati da rari artigiani per ricette fuori dal comune.",al={"che cos'è il corno di sauro del tuono","informazioni sul corno di sauro del tuono","sul corno di sauro del tuono"}},["1dc3a738"]={q="Da dove viene un Corno di Sauro del Tuono?",a="Non è un prodotto artificiale, ma un corno prelevato direttamente dai formidabili sauri del tuono di The Barrens, tra cui creature come Musi Tempestosi, Teste del Tuono e il sfuggente Owatanka. Uccidendone uno puoi recuperare il corno intatto.",al={"da dove vengono i corni di sauro del tuono","chi produce il corno di sauro del tuono","provenienza del corno di sauro del tuono"}}},fp="19,98,24.297.0,26.82.0,41.111.0,24.130.0,54.117.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="Ghiandola di Saliva di Falco del Tuono",s="I greater thunderhawk delle Savane forniscono la ghiandola che serve al Mastro Birraio Drohn per ricreare l'ardente Birra dei Trogg di Chen Birra Triplo Malto.",h="I greater thunderhawk delle Savane forniscono la ghiandola che serve al Mastro Birraio Drohn per ricreare...",kw={"savane","drohn","ghiandola","barilotto","porto paranco","saliva","falco del tuono","birra dei trogg"},ang={["faction:Horde"]="Come membro dell'Orda, puoi dimostrare il tuo valore cacciando feroci falchi del tuono nelle Savane durante i tuoi viaggi attraverso Kalimdor.",["profession:Cooking"]="Come cuoco, potresti esitare a usare ghiandole salivari, ma i mastri birrai più ingegnosi apprezzano le strane essenze animali per il loro brio e la loro potenza."},sec={{t="Un ingrediente selvaggio",b="I greater thunderhawk cacciano nelle aride savane delle Savane. Questi serpenti alati dominano le tempeste, e gli esemplari più anziani e pericolosi producono una ghiandola salivare ricca di potenza naturale. I viaggiatori si tengono alla larga da queste bestie letali. I mastri birrai apprezzano la ghiandola come rara base per bevande esotiche."},{t="Le ricette segrete di Chen",b="Il Mastro Birraio Drohn si stabilì fuori Porto Paranco dopo il passaggio di Chen Birra Triplo Malto attraverso Kalimdor. Drohn studia i metodi di fermentazione del mastro birraio errante. Per produrre la Birra dei Trogg, gli servono una Ghiandola di Saliva di Falco del Tuono fresca, stormhide lightning gland e Fegato di Kodo. L'ardente liquore ha un effetto deciso ed è pensato per rinvigorire gli avventurieri più resistenti."}},faq={{q="Dove si trova una Ghiandola di Saliva di Falco del Tuono?",a="I greater thunderhawk cacciano nelle savane aperte delle Savane, dove è possibile prelevare le loro ghiandole salivari.",al={"bottino ghiandola di saliva di falco del tuono","dove trovare la ghiandola di saliva","posizione ghiandola di falco del tuono"}},{q="A cosa serve la ghiandola salivare?",a="Al Mastro Birraio Drohn, fuori Porto Paranco, serve la ghiandola per produrre la Birra dei Trogg, una potente ricetta lasciata da Chen Birra Triplo Malto.",al={"uso della ghiandola di saliva","a cosa serve la ghiandola di saliva di falco del tuono","uso saliva di falco del tuono"}},{q="Chi è Mastro Birraio Drohn?",a="Il Mastro Birraio Drohn vive vicino al porto di Porto Paranco. Il viaggiatore errante Chen Birra Triplo Malto gli insegnò a produrre birre esotiche, e Drohn offre birre potenti agli avventurieri che affrontano la fauna locale per procurargli ingredienti.",al={"drohn porto paranco","chi è drohn","storia di mastro birraio drohn"}},{q="Cos'è la Birra dei Trogg?",a="Chen Birra Triplo Malto concepì la Birra dei Trogg come una bevanda estremamente potente. Il Mastro Birraio Drohn la prepara con la ghiandola salivare di un greater thunderhawk, ghiandole del fulmine e Fegato di Kodo.",al={"storia della birra dei trogg","cos'è la birra dei trogg","birra dei trogg di chen"}}},fx={bfe8bf39={q="Che cos'è una Ghiandola di Saliva di Falco del Tuono?",a="È un organo ricavato dai falchi del tuono superiori adulti e predatori che volteggiano sopra le aride pianure di The Barrens. Imbevuta delle energie naturali e dei fluidi velenosi tipici di questi esseri alati, la ghiandola produce una secrezione pungente e volatile, ricercata dai birrai audaci in cerca di intrugli inconsueti dal gusto inconfondibile.",al={"che cos'è la ghiandola di saliva di falco del tuono","storia della ghiandola di saliva di falco del tuono","informazioni sulla ghiandola di saliva di falco del tuono"}},dda65d1e={q="Da dove viene una Ghiandola di Saliva di Falco del Tuono?",a="Non è un prodotto fabbricato, ma un organo biologico prelevato dai falchi del tuono superiori che vagano nei cieli aperti e tra le rupi di The Barrens. I cacciatori devono rintracciare questi potenti predatori alati ed estrarre con cura la ghiandola intatta dalle loro carcasse.",al={"origine della ghiandola di saliva di falco del tuono","da dove vengono le ghiandole di saliva di falco del tuono","chi produce la ghiandola di saliva di falco del tuono"}}},fp="24,125,17.286.0,21.332.0,45.104.0,34.112.0,24.197.0,18.166.0"}
P.entries["item:thunderhawk-wings"] = {n="Ali di Falco del Tuono",s="I cacciatori portano le Ali di Falco del Tuono a Camp Taurajo, dove Jorn Skyseer le riceve come prova della loro forza, astuzia e resistenza.",h="I cacciatori portano le Ali di Falco del Tuono a Camp Taurajo, dove Jorn Skyseer le riceve come prova della...",kw={"savane","camp taurajo","jorn skyseer","sergra darkthorn","falco del tuono","serpente del vento","ali"},ang={["class:Hunter"]="Come cacciatore, conquistare le ali di un falco del tuono in volo segna un rito di passaggio. Mette alla prova la tua capacità di seguire le tracce, la tua pazienza e la tua mira contro agili bestie alate.",["race:Tauren"]="Come tauren, onori lo spirito della savana raccogliendo queste ali e mostrando rispetto per le feroci creature dell'Earthmother."},sec={{t="Trofeo della Caccia",b="A Camp Taurajo, i cacciatori apprezzano un paio di Ali di Falco del Tuono intatte. I serpenti del vento, chiamati falchi del tuono dai cacciatori locali, colpiscono rapidamente dall'alto. Seguirne le tracce nelle pianure aperte e prenderne le ali mette alla prova l'abilità di un cacciatore. Per un iniziato, tornare con le ali dimostra di essere pronto a percorrere per tutta la vita il cammino di un cacciatore provetto."}},faq={{q="Dove si trovano le Ali di Falco del Tuono?",a="Le Ali di Falco del Tuono provengono dai falchi del tuono che sorvolano i crinali e le pianure delle Savane centrali e meridionali, soprattutto intorno a Camp Taurajo.",al={"dove trovare le ali","posizione delle ali di falco del tuono","come ottenere le ali di falco del tuono"}},{q="Chi richiede queste ali?",a="Jorn Skyseer, un esperto cacciatore tauren di Camp Taurajo, chiede le ali come prova che un iniziato padroneggi i riti di caccia della savana.",al={"chi accetta le ali di falco del tuono","consegnare le ali di falco del tuono","jorn skyseer ali"}},{q="Cosa rappresenta ottenere le ali?",a="Portare le ali a Jorn Skyseer completa un impegnativo rito di passaggio. Dimostra che il cacciatore ha la forza, il coraggio e la pazienza per affrontare feroci predatori alati.",al={"perché cacciare il falco del tuono","scopo delle ali","significato della caccia al falco del tuono"}}},fx={["1074baa7"]={q="Che cosa sono le Ali di Falco del Tuono?",a="Queste ali vengono ricavate dai falchi del tuono, maestosi serpenti del vento piumati che volteggiano sopra le pianure delle Savane Meridionali. Predatori feroci e fieri, sono venerati dai tauren come simboli di forza e selvaggia maestosità. Prenderne le ali non è cosa da poco: sono una prova concreta dell'abilità, del coraggio e del rispetto dimostrati da un cacciatore nell'affrontare una delle bestie più formidabili del cielo.",al={"che cosa sono le ali di falco del tuono","storia delle ali di falco del tuono","ali di falco del tuono"}},dd263964={q="Da dove vengono le Ali di Falco del Tuono?",a="Le ali vengono prelevate direttamente dai falchi del tuono abbattuti che vagano nei cieli aperti intorno a Camp Taurajo. Dotati per natura di fulmini e agilità, questi serpenti alati sono predatori aerei originari di The Barrens; le loro ali sono quindi trofei del tutto naturali, conquistati al culmine di una caccia impegnativa.",al={"da dove vengono le ali di falco del tuono","provenienza delle ali di falco del tuono","chi lascia cadere le ali di falco del tuono"}}},fp="17,133,18.340.0,34.144.0,22.144.0,37.168.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="Totem Purificatore dei Corno Tonante",s="Al Villaggio di Zoccolo Sanguinario, Mull Corno Tonante prepara un totem per il Pozzo dei Corno Tonante contaminato. La magia ancestrale che racchiude serve a purificare l'acqua.",h="Al Villaggio di Zoccolo Sanguinario, Mull Corno Tonante prepara un totem per il Pozzo dei Corno Tonante...",kw={"zoccolo sanguinario","purificazione","mulgore","mull","rituale","cornotonante","totem","pozzo d'acqua"},ang={["class:Shaman"]="Come sciamano, sai che i totem purificatori possono placare gli spiriti inquieti della natura e ristabilire l'equilibrio dove le energie elementali si sono inasprite.",["race:Tauren"]="Come tauren, hai il sacro dovere di purificare i pozzi ancestrali per la Earth Mother e gli antenati dei clan che vegliano su Mulgore."},sec={{t="Purificare il Thunderhorn Well",b="Mull Corno Tonante affida un totem preparato ai viaggiatori nel Villaggio di Zoccolo Sanguinario. Lo portano a nord, alla sorgente sacra del clan Cornotonante, dove agenti maligni hanno contaminato l'acqua.\n\nI pozzi ancestrali delle tribù tauren nutrono le loro mandrie e i loro territori di caccia. Attraverso un'invocazione rituale, il totem placa gli spiriti turbati dell'acqua e purifica la sorgente."}},faq={{q="A cosa serve il Totem Purificatore dei Corno Tonante?",a="Mull Corno Tonante prepara il totem per purificare il Pozzo dei Corno Tonante corrotto, a nord del Villaggio di Zoccolo Sanguinario. Il suo utilizzo scaccia l'influenza maligna che avvelena il pozzo e compiace gli spiriti ancestrali che lo custodiscono.",al={"cosa fa il totem","perché usare thunderhorn totem","scopo del totem della purificazione"}},{q="Chi ha fabbricato il totem?",a="Mull Corno Tonante crea e dona il totem. L'anziano vive nel Villaggio di Zoccolo Sanguinario, veglia sulla salute della terra e comunica con gli antenati.",al={"chi ha creato questo totem","chi dà thunderhorn totem","totem di mull corno tonante"}},{q="Dove deve essere utilizzato il totem?",a="Usa il totem al Pozzo dei Corno Tonante, a nord del Villaggio di Zoccolo Sanguinario, nella parte centrale di Mulgore.",al={"dove si usa il totem","posizione del totem","dove si trova thunderhorn well"}},{q="Cosa accade dopo aver compiuto il rituale?",a="Purificare il pozzo dona pace agli spiriti ancestrali del clan Cornotonante. Mull Corno Tonante sogna la loro gratitudine, le loro lodi e i doni ancestrali per chi ha purificato le loro terre.",al={"dopo aver purificato il pozzo","esito del rituale","reazione degli antenati"}}},fx={["0770e0ea"]={q="Che cos'è il Totem Purificatore dei Corno Tonante?",a="Il Totem Purificatore dei Corno Tonante è uno strumento rituale consacrato, creato appositamente per purificare la corruzione che contamina il Pozzo dei Corno Tonante a Mulgore. Infuso di magia ancestrale ed elementale, funge da sacro tramite che canalizza le energie spirituali direttamente nella sorgente contaminata, ripristinando le acque pure e vitali da cui dipendono i tauren del luogo.",al={"che cos'è il totem purificatore dei corno tonante","che cos'è il totem dei corno tonante","storia del totem purificatore dei corno tonante"}},d3c4386d={q="Perché serve il Totem Purificatore dei Corno Tonante?",a="Il pozzo ancestrale del clan Corno Tonante è stato vittima di una corruzione innaturale che minaccia la terra e le bestie che ne bevono l'acqua. I rimedi comuni non possono eliminare una simile piaga; Mull Corno Tonante ha preparato questo totem incantato perché un emissario possa compiere il solenne rituale necessario a bandire la corruzione e placare gli spiriti ancestrali che vegliano sul pozzo.",al={"perché serve il totem dei corno tonante","perché mi serve il totem della purificazione","scopo del totem purificatore dei corno tonante"}}},fp="27,151,30.355.0,55.217.0,22.153.0,29.91.0,43.188.1"}
P.entries["item:thurman-s-remains"] = {n="Resti di Thurman",s="Ai Mulini degli Agamand, i Resti di Thurman giacciono tra le rovine della fallita resistenza della famiglia contro il Flagello. Il proprietario dei mulini, un tempo facoltoso, soccombette alla Piaga e ora vaga per la sua tenuta in rovina come un servo non morto.",h="Ai Mulini degli Agamand, i Resti di Thurman giacciono tra le rovine della fallita resistenza della famiglia...",kw={"agamand","mulini degli agamand","coleman farthing","deaths in the family","thurman agamand","resti di thurman","radure di tirisfal"},ang={["race:Undead"]="Come Reietto, recuperi questi resti per regolare i conti con i padroni aristocratici la cui superbia spinse i lavoratori nelle grinfie del Flagello."},sec={{t="Un'eredità di rovina",b="Prima della Terza Guerra, gli Agamand erano i proprietari terrieri più ricchi delle Radure di Tirisfal. Possedevano vasti mulini e davano lavoro a decine di abitanti del luogo. Quando il Flagello travolse Lordaeron, Thurman Agamand e i suoi congiunti fortificarono la tenuta invece di fuggire. Convinti che la loro ricchezza e i solidi mulini potessero resistere all'attacco, persuasero i loro fedeli lavoratori a combattere al loro fianco.\n\nLa difesa fallì. Gli Agamand e i loro lavoratori furono massacrati e trasformati in servitori privi di volontà del Lich King. Coleman Farthing, un ex lavoratore risorto come Reietto, ora esige la distruzione dei suoi antichi padroni. Cerca i Resti di Thurman come prova che lo stolto patriarca abbia pagato per aver condannato la sua famiglia."}},faq={{q="Chi era Thurman Agamand?",a="Thurman Agamand apparteneva alla ricca dinastia degli Agamand, proprietaria dei Mulini degli Agamand nelle Radure di Tirisfal settentrionali. Quando il Flagello colpì Lordaeron, l'orgoglio lo spinse a convincere i lavoratori a restare e combattere. Tutti coloro che si trovavano nella tenuta furono massacrati e riportati in vita.",al={"thurman agamand","chi è thurman","chi era thurman"}},{q="Perché Coleman Farthing vuole i resti di Thurman?",a="Coleman Farthing era un lavoratore dei mulini che si fidò degli Agamand e morì difendendo la loro tenuta. Ora è uno dei Reietti e cerca i Resti di Thurman per vendicarsi dei padroni che condannarono i loro lavoratori alla non morte.",al={"perché coleman vuole i resti","movente di coleman farthing","perché uccidere thurman"}},{q="Thurman aveva libero arbitrio quando fu distrutto?",a="No. Dopo la morte, Thurman Agamand rimase sotto il dominio mentale del Flagello, a differenza dei Reietti di Sepulcra. Servì come un seguace privo di volontà finché non fu distrutto ai mulini.",al={"thurman aveva libero arbitrio","thurman era del flagello","thurman è un reietto"}},{q="Chi altro della famiglia Agamand è preso di mira?",a="Coleman Farthing vuole anche che Gregor Agamand e Nissa Agamand vengano distrutti e che i loro resti siano recuperati, insieme ai Resti di Thurman, per porre fine alla stirpe che un tempo dominava i mulini.",al={"altri agamand","membri della famiglia agamand","bersagli di deaths in the family"}}},fx={["559ae8e6"]={q="Che cosa sono i Resti di Thurman?",a="Sono i resti materiali di Thurman Agamand, recuperati dopo aver abbattuto la sua forma non morta e inquieta ai Mulini degli Agamand. Un tempo faceva parte della prospera dinastia degli Agamand, proprietaria dei mulini circostanti. Thurman cadde vittima della Piaga dei Non Morti e rimase come schiavo senza intelletto del Flagello finché non venne infine abbattuto.",al={"che cosa sono i resti di thurman","oggetto resti di thurman","chi è thurman dei resti"}},["0ea47aa9"]={q="Da dove vengono i Resti di Thurman?",a="Sono stati prelevati direttamente dal cadavere distrutto di Thurman Agamand, ai Mulini degli Agamand nella parte settentrionale delle Radure di Tirisfal. Quando il Flagello si abbatté sulla regione, Thurman e i suoi familiari fortificarono la loro tenuta e convinsero i lavoratori a resistere. La difesa fallì e la famiglia si trasformò in abomini del Flagello, finché i loro corpi non vennero distrutti.",al={"dove si trovano i resti di thurman","origine dei resti di thurman","come si ottengono i resti di thurman"}}},fp="17,207,16.697.0,24.260.0,49.216.0,49.188.0,51.171.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="Strumenti da Cucito di Thurman",s="Presso Larson Clothiers, gli Strumenti da Cucito di Thurman servono per il lavoro di sartoria della giornata. Il giovane apprendista Thurman Schneider li ha lasciati nella casa di famiglia presso i Canali, sperando di trascorrere la giornata in ozio.",h="Presso Larson Clothiers, gli Strumenti da Cucito di Thurman servono per il lavoro di sartoria della giornata.",kw={"larson clothiers","quartiere dei maghi","rema schneider","strumenti da cucito","canali di roccavento","thurman schneider","strumenti da cucito di thurman"},ang={["profession:Tailoring"]="Ogni sarto conosce la fatica dei primi tempi di apprendistato. Pochi arrivano al punto di fare come il giovane Thurman Schneider e lasciare a casa le proprie cesoie."},sec={{t="Gli Strumenti di un Apprendista Riluttante",b="Gli Strumenti da Cucito di Thurman comprendono gli aghi, le cesoie e il filo che gli servono per il lavoro di sartoria. Il giovane Thurman studia presso Larson Clothiers, nel cuore del Quartiere dei Maghi di Roccavento, vicino alla Torre del Mago. Sua madre, Rema Schneider, sa che non può lavorare senza quegli strumenti. Così chiede ai passanti lungo i Canali di portarli alla bottega. Quando Thurman riceve i suoi attrezzi, la sua reazione rivela che li aveva lasciati a casa di proposito. Sperava di sostituire una giornata passata a cucire abiti con una di ozio."}},faq={{q="Cosa c'è all'interno degli Strumenti da Cucito di Thurman?",a="Gli strumenti comprendono aghi, cesoie e filo per il lavoro di sartoria di Thurman Schneider presso Larson Clothiers.",al={"cosa c'è nel kit","contenuto degli strumenti da cucito","cesoie di thurman"}},{q="A chi appartengono questi strumenti da cucito?",a="Gli Strumenti da Cucito di Thurman appartengono a Thurman Schneider, un giovane apprendista che lavora alle dipendenze dei Larsons nel Quartiere dei Maghi di Roccavento.",al={"a chi appartiene il kit","thurman proprietario","chi è thurman"}},{q="Perché il kit è stato lasciato a casa di Thurman?",a="Rema pensava che Thurman fosse uscito di fretta e avesse dimenticato gli strumenti. Lui li aveva lasciati a casa di proposito, sperando di evitare una giornata di lavoro presso Larson Clothiers.",al={"perché thurman ha dimenticato il suo kit","thurman l'ha dimenticato di proposito","perché lasciare gli strumenti da cucito"}},{q="Dove deve essere consegnato questo kit?",a="Porta gli strumenti a Larson Clothiers, nel Quartiere dei Maghi di Roccavento, vicino alla Torre del Mago.",al={"dove porto il kit","posizione di larson clothiers","posizione di thurman"}}},fx={["128c9147"]={q="Perché Rema Schneider vuole che vengano consegnati gli Strumenti da Cucito di Thurman?",a="Thurman è un apprendista sarto presso Larson Clothiers nel Quartiere dei Maghi. Sua madre, Rema Schneider, ti chiede di consegnargli il kit perché possa svolgere le sue mansioni quotidiane di sartoria. Thurman, però, ha lasciato gli strumenti indietro di proposito, sperando di evitare i suoi doveri e scansare il lavoro per un giorno.",al={"perché consegnare gli strumenti da cucito di thurman","perché thurman ha bisogno dei suoi strumenti da cucito","perché vuole il kit da cucito"}}},fp="20,191,30.450.0,36.101.0,35.124.0,46.139.0,41.87.0"}
P.entries["item:timberling-seed"] = {n="Seme di Alberiano",s="In tutta Teldrassil, il Seme di Alberiano viene raccolto dagli spiriti vegetali divenuti ostili. Naturalisti e druidi studiano i semi per capire perché le piante della foresta siano diventate aggressive.",h="In tutta Teldrassil, il Seme di Alberiano viene raccolto dagli spiriti vegetali divenuti ostili.",kw={"corruzione","darnassus","denalan","lago al'ameth","rellian greenspyre","teldrassil","alberiano","seme di alberiano"},ang={["class:Druid"]="Come druido, puoi leggere nei semi contaminati un primo segnale di corruzione innaturale tra gli elementali vegetali di Teldrassil, motivo di grave preoccupazione per i protettori dell'Enclave Cenariana.",["profession:Herbalism"]="Come erborista, puoi studiare i semi per capire come le condizioni del terreno e la corruzione ambientale influenzino la flora selvatica."},sec={{t="Semi di una Foresta Inquieta",b="Gli alberiani sono elementali della natura di Teldrassil e il loro temperamento riflette l'equilibrio dell'Albero del Mondo. Ultimamente sono diventati furiosi e ostili, preoccupando gli elfi della notte che si prendono cura delle fronde. Erboristi come Denalan, presso il Lago Al'ameth, sospettano che il problema sia nel terreno. Raccolgono semi dagli alberiani selvatici, sperando che un terreno purificato e curato con attenzione possa far germogliare una prole docile."},{t="Una Corruzione Radicata",b="I semi degli alberiani selvatici portano la contaminazione dei loro genitori corrotti. Studiosi cenariani come Rellian Greenspyre a Darnassus scoprono che il problema va oltre una crescita stentata. La corruzione ha attecchito tra gli spiriti vegetali di Teldrassil e in tutto l'ecosistema del Grande Albero."}},faq={{q="Che cos'è un seme di alberiano?",a="Un seme di alberiano è il nucleo riproduttivo di un alberiano, un elementale della natura dalle sembianze vegetali diffuso in tutta Teldrassil. I naturalisti raccolgono i semi per studiare la crescita e l'ecologia degli alberiani.",al={"semi di alberiano","cosa sono i semi di alberiano"}},{q="Dove si raccolgono questi semi?",a="Questi semi si ricavano dagli alberiani selvatici e dalle bestie delle paludi lungo le rive e nelle acque basse del Lago Al'ameth.",al={"dove trovare i semi","bottino seme di alberiano","chi rilascia il seme di alberiano"}},{q="Perché Denalan vuole i semi di alberiano?",a="Denalan sospetta che un terreno povero stia facendo infuriare gli alberiani. Spera che un terreno preparato appositamente permetta ai semi selvatici di germogliare in alberiani docili e incontaminati.",al={"scopo di denalan","perché raccogliere semi","il piano di denalan"}},{q="Cosa scopre Rellian Greenspyre sui semi?",a="Rellian scopre che i semi portano la contaminazione dei loro genitori corrotti. La corruzione va oltre le sue capacità di porvi rimedio, lasciando ogni speranza agli esperimenti di orticoltura di Denalan.",al={"studio dei semi di rellian","cosa ha scoperto rellian","i semi sono corrotti"}}},fp="15,176,26.377.0,19.278.1,26.185.0,31.97.0,39.156.0,54.168.1"}
P.entries["item:timberling-sprout"] = {n="Germoglio di Alberiano",s="Lungo il Lago Al'ameth, i Germogli di Alberiano spuntano corrotti e i custodi elfi della notte li estirpano prima che diventino alberiani aggressivi.",h="Lungo il Lago Al'ameth, i Germogli di Alberiano spuntano corrotti e i custodi elfi della notte li estirpano...",kw={"aldrassil","corruzione","lago al'ameth","vallombra","teldrassil","alberiano","germoglio di alberiano"},ang={["class:Druid"]="Come druido in sintonia con la vita vegetale e gli elementali di Kalimdor, potresti vedere negli spiriti silvani che nascono corrotti un tetro presagio per il futuro di Teldrassil.",["race:NightElf"]="Come giovane elfo della notte che si addestra a Vallombra, hai il compito di rimuovere i germogli per proteggere la tua nuova dimora silvana."},sec={{t="Piantine Corrotte",b="Gli alberiani sono spiriti vegetali legati alla vitalità naturale di Teldrassil. Lungo il Lago Al'ameth, alcune piantine germogliano corrotte e aggressive anziché sane e in armonia con la natura. I giovani germogli sembrano impossibili da purificare o guarire naturalmente, così i custodi li raccolgono e li distruggono. Sperano di impedire che gli alberiani ostili si diffondano tra i fragili rami dell'Albero del Mondo appena piantato."}},faq={{q="Dove si trovano i Germogli di Alberiano?",a="I Germogli di Alberiano crescono vicino alla riva del Lago Al'ameth, a sud di Dolanaar, a Teldrassil.",al={"posizione dei germogli","dove si trovano i germogli di alberiano","trovare i germogli"}},{q="Perché gli elfi della notte estirpano i Germogli di Alberiano dal terreno?",a="I germogli spuntano già corrotti. Se lasciati indisturbati, diventano alberiani violenti che minacciano la sicurezza e l'equilibrio di Teldrassil. I custodi li considerano irrecuperabili e li estirpano quando sono ancora piccoli.",al={"perché uccidere i germogli","scopo dei germogli di alberiano","perché distruggere i germogli"}},{q="Cosa causa la corruzione dei germogli?",a="Una misteriosa malattia colpisce la fauna e gli elementali vegetali di Teldrassil. Il botanico Denalan non ne conosce l'origine, ma essa corrompe i giovani alberiani fin dal momento in cui mettono radici.",al={"perché gli alberiani sono corrotti","cosa li sta corrompendo","malattia dei germogli"}},{q="Chi richiede di raccogliere i Germogli di Alberiano?",a="Denalan, il botanico che si prende cura del Lago Al'ameth, chiede agli avventurieri di raccogliere i germogli e rimuoverli dalle rive per mantenere pura la terra.",al={"chi vuole i germogli","chi assegna la missione dei germogli","consegna dei germogli di alberiano"}}},fx={f13cc7b7={q="Che cos'è un Germoglio di Alberiano?",a="Un Germoglio di Alberiano è la forma giovanile di un alberiano, un piccolo essere elementale simile a una pianta che mette radici lungo le umide rive del Lago Al'ameth. Se lasciati indisturbati, questi germogli cresceranno fino a diventare alberiani adulti. Purtroppo, quelli che spuntano intorno al lago sono contaminati e aggressivi; per questo il botanico Denalan, presso il Lago Al'ameth, vuole che vengano sradicati prima che diventino una minaccia.",al={"che cos'è il germoglio di alberiano","che cosa sono i germogli di alberiano","informazioni sul germoglio di alberiano"}}},fp="17,136,18.399.0,35.99.0,63.206.0,46.180.0,48.139.0"}
P.entries["item:tirisfal-pumpkin"] = {n="Zucca di Tirisfal",s="Alla Cascina dei Solliden, gli umani viventi coltivano ancora zucche nella contaminata Tirisfal. I Reietti si impadroniscono del raccolto per le miscele della Società degli Speziali Reali.",h="Alla Cascina dei Solliden, gli umani viventi coltivano ancora zucche nella contaminata Tirisfal.",kw={"speziale johaan","brill","guardiamorte simmer","fields of grief","zucca","reagente","cascina dei solliden","zucca di tirisfal"},ang={["faction:Alliance"]="Come membro dell'Alleanza, vedi nelle zucche della Cascina dei Solliden il tentativo dei superstiti di Lordaeron di nutrirsi tra le incursioni dei Reietti.",["race:Undead"]="Come non morto, compi incursioni alla Cascina dei Solliden per privare i vivi del cibo e portare allo Speziale Johaan materiali per le ricerche dei Reietti."},sec={{t="Raccolto in una terra devastata",b="A ovest di Brill, le colture crescono ancora nonostante la corruzione che si diffonde su Lordaeron. Alla Cascina dei Solliden, contadini umani viventi coltivano grandi zucche arancioni sotto lo sguardo della vicina Crociata Scarlatta. Il raccolto nutre i contadini. Per i Reietti di Brill, le zucche sono bersagli da sabotare e materie prime per lo Speziale Johaan."},{t="Reagenti per speziali",b="Il Guardiamorte Simmer invia giovani Reietti nei campi contesi per rubare le zucche ai contadini. Questi ortaggi non nutrono i morti. Finiscono nei calderoni della Società degli Speziali Reali, dove gli speziali studiano come le piante reagiscono alle pestilenze e alle miscele sperimentali. Le colture rimaste a Lordaeron diventano strumenti contro i vivi."}},faq={{q="Dove si possono trovare le Tirisfal Pumpkin?",a="Crescono alla Cascina dei Solliden, a ovest di Brill e poco a nord di Albamorta, nelle Radure di Tirisfal.",al={"posizione delle zucche","dove sono le zucche","zucche della cascina dei solliden"}},{q="Perché i Reietti vogliono queste zucche?",a="Il Guardiamorte Simmer ordina di rubare le zucche per privarne gli umani superstiti e la Crociata Scarlatta. Le invia allo Speziale Johaan a Brill come materie prime per le ricerche degli speziali.",al={"perché rubare le zucche","zucca di johaan","a cosa servono le zucche"}},{q="I giocatori possono mangiare o cucinare con le Tirisfal Pumpkin?",a="No. La Società degli Speziali Reali le raccoglie per le sue miscele e gli avventurieri non le usano per cucinare.",al={"si possono mangiare le zucche di tirisfal","ingrediente culinario zucca"}},{q="Chi le coltiva attualmente?",a="Contadini umani viventi coltivano la terra alla Cascina dei Solliden, con una blanda protezione della Crociata Scarlatta da una vicina torre di guardia.",al={"a chi appartiene la fattoria","contadini dei solliden"}}},fx={dab4ae64={q="Che cos'è una Zucca di Tirisfal?",a="Una Zucca di Tirisfal è una zucca resistente coltivata dai contadini umani sopravvissuti alla Cascina dei Solliden, nelle Radure di Tirisfal. In un regno devastato dove la vegetazione fatica a sopravvivere, queste zucche sono un prezioso sostentamento per i viventi e reagenti alchemici essenziali per i Reietti.",al={"cos'è la zucca di tirisfal","zucca di tirisfal","cosa sono le zucche di tirisfal"}}},fp="16,155,26.337.0,19.344.0,37.95.0,42.188.0,47.108.0,30.128.0"}
P.entries["item:token-of-thievery"] = {n="Emblema del Ladro",s="Alla Segheria di Alther, Lucius sottopone gli aspiranti ladri a una prova pericolosa. Devono recuperare l'Emblema del Ladro da un bauletto chiuso a chiave tra le rovine.",h="Alla Segheria di Alther, Lucius sottopone gli aspiranti ladri a una prova pericolosa.",kw={"segheria di alther","attestato di ladro","borgolago","scassinamento","lucius","crestarossa","arnesi da scasso","emblema del ladro"},ang={["class:Rogue"]="Come ladro, dimostri la tua abilità nello scassinamento recuperando l'Emblema del Ladro dalle rovine minacciate dagli orchi Roccianera."},sec={{t="Una prova di finezza",b="Da Borgolago, Lucius mette alla prova sul campo i ladri promettenti. Tra le rovine della Segheria di Alther, nasconde l'Emblema del Ladro in un bauletto chiuso a chiave. Gli orchi Roccianera minacciano la zona, rendendo ogni tentativo una prova di scassinamento sotto la minaccia di un pericolo mortale. Chi riesce ottiene un Attestato di Ladro."}},faq={{q="Cos'è l'Emblema del Ladro?",a="Alla Segheria di Alther, Lucius chiude a chiave l'Emblema del Ladro in un bauletto. Gli aspiranti ladri devono scassinarne la serratura in una situazione di pericolo per dimostrare la propria abilità.",al={"uso dell'emblema del ladro","cos'è l'emblema del ladro","emblema di lucius"}},{q="Chi mette l'emblema nella cassetta di sicurezza?",a="Lucius, un esperto istruttore di ladri a Borgolago, mette l'emblema nel bauletto per addestrare i giovani ladri.",al={"a chi appartiene l'emblema","proprietario della cassetta di lucius","chi ha nascosto l'emblema"}},{q="Perché il forziere si trova alla Segheria di Alther?",a="La Segheria di Alther si trova lungo la strada che sale da Borgolago, dove si aggirano gli orchi Roccianera. Lucius vi manda gli apprendisti a scassinare serrature rapidamente e in silenzio, in territorio ostile.",al={"perché alla segheria di alther","motivo della cassetta alla segheria","pericolo alla segheria"}},{q="Cosa si riceve in cambio dell'emblema?",a="Riporta l'emblema a Lucius e otterrai un Attestato di Ladro che riconosce il tuo addestramento di base nello scassinamento.",al={"ricompensa dell'emblema","cosa ti dà lucius","attestato di ladro"}}},fp="17,148,17.285.0,30.136.0,34.105.0,41.158.0,46.122.0"}
P.entries["item:tome-of-the-cabal-quest-item"] = {n="Tomo della Cabala",s="A Porto Paranco, Strahad Farsan consegna agli stregoni il Tome of the Cabal dopo che hanno raccolto componenti pericolosi. Le sue pagine insegnano loro ad attirare un felhunter attraverso la Distorsione Fatua e a vincolarlo.",h="A Porto Paranco, Strahad Farsan consegna agli stregoni il Tome of the Cabal dopo che hanno raccolto...",kw={"felhunter","porto paranco","strahad farsan","cerchio di evocazione","the binding","tome of the cabal"},ang={["class:Warlock"]="Come stregone, devi padroneggiare questo tomo per ottenere un felhunter come compagno e acquisire il dominio sulla magia demoniaca."},sec={{t="Un varco verso la Distorsione",b="Un felhunter è una bestia feroce proveniente dalla caotica Distorsione Fatua, temuta perché divora il mana. Soggiogarne uno è una prova per stregoni esperti. Il Tome of the Cabal contiene i riti per aprire un varco verso il demone. Strahad Farsan, un esperto evocatore di Porto Paranco, lo consegna a un aspirante dopo che questi ha raccolto i componenti rari e pericolosi richiesti dalla sua magia."},{t="Il rituale di evocazione",b="Strahad Farsan traccia il cerchio di evocazione primario nel suo santuario. I suoi accoliti usano verghe di incanalamento per creare una barriera protettiva maggiore. Lo stregone recita le esatte formule del tomo e trascina il felhunter nel nostro mondo. Il demone deve poi essere affrontato e soggiogato immediatamente, vincolato alla volontà dello stregone."}},faq={{q="A cosa serve il Tome of the Cabal?",a="Il Tome of the Cabal contiene le formule per evocare un felhunter dalla Distorsione Fatua in un cerchio preparato a Porto Paranco. Lì, uno stregone può affrontare il demone e vincolarlo.",al={"a cosa serve tome of the cabal","scopo del tome of the cabal","tomo felhunter"}},{q="Chi fornisce il Tome of the Cabal?",a="Strahad Farsan, un mentore degli stregoni che vive sulle colline sopra Porto Paranco, nelle Savane, fornisce il tomo dopo che un praticante ha completato gli ardui preparativi.",al={"chi dà tome of the cabal","dove ottenere tome of the cabal","libro di strahad"}},{q="Si tiene il tomo dopo aver completato il rituale?",a="No. Dopo aver sconfitto il felhunter evocato e dimostrato la tua maestria, restituisci il Tome of the Cabal a Strahad Farsan come prova del tuo successo.",al={"si tiene il libro","ricompensa tome of the cabal","tenere il tome of the cabal"}},{q="È possibile evocare il felhunter in qualsiasi luogo del mondo?",a="No. Devi leggere le formule nel santuario di Strahad Farsan sopra Porto Paranco. Lui e i suoi accoliti mantengono i cerchi di evocazione maggiore e minore necessari a contenere la bestia in arrivo.",al={"evocare il felhunter ovunque","dove leggere il tomo","luogo del rituale del tomo"}}},fx={["42bf8406"]={q="Che cos'è il Tome of the Cabal?",a="Il Tome of the Cabal è un grimorio esoterico che contiene rituali e formule demoniache specifiche. Affidato agli stregoni esperti da Strahad Farsan, sopra Porto Paranco, il libro descrive i pericolosi riti necessari per aprire un varco nel Regno Ultraterreno e costringere un feroce vilsegugio a obbedirti.",al={"cos'è il tome of the cabal","storia del tome of the cabal","informazioni sul tome of the cabal"}},a251072b={q="Da dove proviene il Tome of the Cabal e chi lo ha scritto?",a="Il tomo fu scritto dal primo gruppo di stregoni riuscito a evocare un vilsegugio senza aiuto. Un tempo custodito a Lordaeron, fu vandalizzato e diviso in un Tomo Ammuffito e un Manoscritto Cencioso. Uno stregone recupera queste parti sulla costa di Colletorto e dai centauri di Millepicchi, poi porta il volume ricomposto a Strahad Farsan.",al={"chi ha scritto il tome of the cabal","da dove proviene il tome of the cabal","autore del tome of the cabal"}},["03fa6157"]={q="Perché qualcuno vuole il Tome of the Cabal?",a="Gli aspiranti stregoni cercano il Tome of the Cabal perché contiene la formula esatta necessaria per evocare un vilsegugio in un cerchio preparato. Senza le parole precise del tomo, sottomettere uno di questi pericolosi demoni divoratori di mana sarebbe praticamente impossibile.",al={"perché volere il tome of the cabal","perché gli stregoni vogliono il tome of the cabal","scopo del tome of the cabal"}}},fp="30,185,23.358.0,20.311.0,39.176.0,35.157.0,49.145.0,51.187.0"}
P.entries["item:top-of-gelkak-s-key"] = {n="Frammento Superiore della Chiave di Gelkak",s="Un giant foreststrider porta il Frammento Superiore della Chiave di Gelkak nei boschi vicino a Rivafosca. Il frammento si è staccato da una chiave meccanica appartenente allo gnomo naufrago Gelkak Giralbero.",h="Un giant foreststrider porta il Frammento Superiore della Chiave di Gelkak nei boschi vicino a Rivafosca.",kw={"rivafosca","primo ufficiale","falcatore della foresta","gelkak","giralbero","chiave","pirata","recupero"},ang={["profession:Engineering"]="La chiave carica e attiva un automa a orologeria. La sua struttura robusta dimostra l'ingegnosità degli inventori gnomi.",["race:Gnome"]="Come gnomo, potresti trovare familiare e tenero un altro gnomo che sopravvive a un naufragio grazie all'eccentricità e ai congegni a orologeria."},sec={{t="Un meccanismo frantumato",b="I threshadon hanno attaccato la nave di Gelkak Giralbero al largo di Rivafosca e l'hanno trascinata sotto le onde. Gelkak è stato sospinto a riva con la chiave di carica del suo primo ufficiale meccanico. Gli scogli costieri hanno spezzato la chiave in tre pezzi.\n\nPrima che lo stordito pirata potesse riprendersi, le bestie hanno rovistato tra i rottami. Un giant foreststrider ha portato nei boschi il decorato frammento superiore."},{t="Ripristinare il primo ufficiale",b="A Gelkak Giralbero serve la chiave per caricare e attivare il suo primo ufficiale meccanico. Intende usare il costrutto contro la fauna locale. I murloc della riva hanno preso il frammento centrale, mentre i reef crawler hanno preso quello inferiore. Con tutti e tre i frammenti, Giralbero può riparare la chiave e dare vita al suo costrutto."}},faq={{q="A cosa serve il Frammento Superiore della Chiave di Gelkak?",a="Il Frammento Superiore della Chiave di Gelkak è uno dei tre pezzi che servono a Gelkak Giralbero per riparare la sua chiave di carica meccanica. Una volta ricomposta, la chiave può riattivare il suo primo ufficiale meccanico.",al={"a cosa serve la chiave di gelkak","uso del frammento superiore della chiave di gelkak","scopo della chiave di gelkak"}},{q="Come ha ottenuto questo pezzo della chiave un foreststrider?",a="Quando Gelkak ha fatto naufragio al largo di Rivafosca, la chiave si è spezzata contro gli scogli. Le bestie hanno rovistato tra i rottami, e un giant foreststrider ha portato il frammento superiore d'ottone nei boschi a nord-est della riva.",al={"perché gli struzzi hanno la chiave","chi ha preso la parte superiore della chiave di gelkak","come ha fatto il falcatore della foresta a prendere la chiave"}},{q="Dove sono gli altri pezzi della chiave?",a="I murloc Greymist vicino al relitto hanno preso la sezione centrale. I granchi che perlustravano la battigia hanno portato via la sezione inferiore.",al={"dove sono le altre parti della chiave","parte centrale e inferiore della chiave di gelkak","frammenti della chiave di gelkak"}},{q="Chi è Gelkak Giralbero?",a="Gelkak Giralbero è un pirata gnomo rimasto bloccato a Rivafosca dopo che i threshadon hanno distrutto la sua nave. Isolato e furioso, trama vendetta contro le creature della costa.",al={"chi è gelkak","storia di gelkak giralbero"}}},fx={["7697c1f6"]={q="Che cos'è il Frammento Superiore della Chiave di Gelkak?",a="È uno dei tre frammenti di una chiave speciale appartenuta allo gnomo naufragato Gelkak Giralbero. Quando la sua nave affondò al largo di Rivafosca, la chiave si frantumò sulla costa rocciosa. Questo particolare segmento superiore fu raccolto dai giganti camminatori dei boschi che si aggirano nei boschi vicini.",al={"frammento superiore della chiave di gelkak","cos'è la parte superiore della chiave di gelkak","frammento della chiave di gelkak"}}},fp="19,175,21.361.0,24.296.1,41.179.0,50.201.0,38.120.0,23.163.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="Torcia della Fiamma Sopita",s="Al Santuario della Fiamma Sopita, uno sciamano è pronto ad accendere la Torcia della Fiamma Sopita. Il suo fuoco attende una brace conquistata in cima a una montagna di Durotar.",h="Al Santuario della Fiamma Sopita, uno sciamano è pronto ad accendere la Torcia della Fiamma Sopita.",kw={"call of fire","durotar","sapta di fuoco","sciamano","santuario della fiamma sopita","telf joolam","torcia della fiamma sopita"},ang={["class:Shaman"]="Come sciamano, inizi con una torcia ancora da mettere alla prova. Sconfiggi una manifestazione vivente della fiamma per accenderla e ottenere il diritto di evocare un Fire Totem."},sec={{t="Ricettacolo del Risveglio",b="Uno sciamano porta la Torcia della Fiamma Sopita spenta sulle vette sopra Durotar, cercando il favore del fuoco. Grazie al Sapta di Fuoco, lo sciamano vede una Minor Manifestation of Fire in cima alla montagna e la sfida. Quando lo spirito cade, la sua Brace Luminosa viene posta nel braciere logoro del Santuario della Fiamma Sopita. Poi lo sciamano accosta la testa della torcia al fuoco incandescente, e il legno si risveglia come emblema ardente del dominio sugli elementi."}},faq={{q="Qual è lo scopo della Torcia della Fiamma Sopita?",a="Gli sciamani che affrontano la prova Call of Fire ricevono la torcia cerimoniale spenta. Dopo la sconfitta di una manifestazione del fuoco, la sua brace viene posta nel braciere del santuario. Lo sciamano immerge la torcia nelle fiamme incandescenti, accendendola con il potere degli elementi.",al={"cos'è la torcia della fiamma sopita","perché ho questa torcia spenta","cosa fa la torcia"}},{q="Dove viene accesa questa torcia?",a="La torcia viene accesa in cima alla montagna vicino a Telf Joolam, a Durotar. Dopo aver sconfitto la Minor Manifestation of Fire, lo sciamano la accende al braciere del Santuario della Fiamma Sopita.",al={"dove accendere la torcia della fiamma sopita","torcia del santuario della fiamma sopita","come accendere la torcia sopita"}},{q="Chi fornisce la torcia spenta?",a="Kranal Fiss, lo sciamano che vive a nord di Crocevia, dà agli iniziati la torcia spenta e li manda da Telf Joolam, custode del Santuario della Fiamma Sopita. Telf Joolam la riconosce come il segno di chi cerca di domare il fuoco.",al={"chi dà la torcia della fiamma sopita","fonte torcia sopita","chi dà la torcia di call of fire"}}},fx={["5b4644ae"]={q="Che cos'è la Torcia della Fiamma Sopita?",a="È una torcia cerimoniale spenta, realizzata per la prova di uno sciamano durante Call of Fire. Progettata per accogliere l'essenza selvaggia del fuoco elementale, rimane completamente fredda e sopita finché non viene immersa nel braciere consacrato in cima al Santuario della Fiamma Sopita, dove prende fuoco grazie all'essenza di una manifestazione del fuoco sconfitta.",al={"torcia della fiamma sopita","cos'è la torcia sopita"}},c6982489={q="Perché Telf Joolam ha bisogno della Torcia della Fiamma Sopita?",a="La torcia è il recipiente con cui catturare il fuoco e dimostrare la propria padronanza su di esso. Accendendone la punta sopita nel braciere sacro con la brace di una manifestazione sconfitta, imprigioni la scintilla elementale in una fiamma trasportabile. Riportare la torcia appena accesa completa la tua comunione spirituale con l'elemento del fuoco.",al={"perché serve la torcia della fiamma sopita","perché volere la torcia sopita","scopo della torcia della fiamma sopita"}}},fp="26,158,19.443.0,54.249.0,30.187.0,29.231.0"}
P.entries["item:torn-fin-eye"] = {n="Occhio di Pinnalacera",s="Lungo la costa di Colletorto, gli Occhi di Pinnalacera attirano la Società dei Farmacisti Reali. I Reietti li cercano per le ricerche alchemiche su nuove piaghe.",h="Lungo la costa di Colletorto, gli Occhi di Pinnalacera attirano la Società dei Farmacisti Reali.",kw={"speziale lydon","elixir of agony","alture di colletorto","murloc","società dei farmacisti reali","pinnalacera","occhio di pinnalacera","sepulcra"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci al suo sforzo bellico nelle Alture di Colletorto raccogliendo reagenti costieri e rafforzando la presenza dei Reietti contro l'avanzata dell'Alleanza da Riva del Sud.",["race:Undead"]="In quanto Undead, raccogliendo catalizzatori organici come gli Occhi di Pinnalacera contribuisci all'obiettivo della Società dei Farmacisti Reali di perfezionare una piaga che distruggerà sia il Flagello sia i viventi."},sec={{t="Un reagente per la rovina",b="La Società dei Farmacisti Reali usa rare parti biologiche nelle sue ricerche sulla Nuova Piaga dei Reietti. Gli Occhi di Pinnalacera provengono dai murloc lungo la Riva Occidentale delle Alture di Colletorto. Le loro proprietà organiche aiutano ad attivare composti alchemici volatili. Mescolati con scaglie di naga Daggerspine, elisir rigeneranti dei troll e melma ricavata dagli gnoll, gli occhi aiutano a stabilizzare e innescare miscele tossiche destinate a diffondere la morte nelle terre nemiche."},{t="Distillare l'agonia",b="Nell'Apothecarium di Sepulcra, i maestri alchimisti hanno scoperto che i colloidi in decomposizione aggiunti ai composti di Grugnobrago richiedono catalizzatori della costa di Colletorto. Lo Speziale Lydon al Mulino di Tarren usa gli occhi raccolti per catalizzare il suo Elixir of Agony. La pozione contribuisce agli sforzi dei Reietti per creare devastanti armi biologiche vicino agli insediamenti umani."}},faq={{q="A cosa serve un Occhio di Pinnalacera?",a="La Società dei Farmacisti Reali cerca gli Occhi di Pinnalacera come catalizzatore alchemico. Al Mulino di Tarren, lo Speziale Lydon li combina con Daggerspine Scales e un Elisir Forte del Sangue di Troll per attivare i contaminanti in una Mistura di Grugnobrago volatile e portare avanti le sue ricerche su piaghe letali.",al={"uso dell'occhio di pinnalacera","perché ottenere occhi di pinnalacera","scopo dell'occhio di pinnalacera"}},{q="Dove si trovano gli Occhi di Pinnalacera?",a="Puoi ricavare gli Occhi di Pinnalacera dai murloc Pinnalacera sulla Riva Occidentale delle Alture di Colletorto, lungo la costa a ovest di Riva del Sud.",al={"dove trovare occhi di pinnalacera","posizione dell'occhio di pinnalacera","chi rilascia l'occhio di pinnalacera"}},{q="Chi ordina la raccolta di questi occhi?",a="Ai ricercatori dei Reietti a Sepulcra e allo Speziale Lydon al Mulino di Tarren servono gli occhi per completare l'Elixir of Agony.",al={"a chi servono gli occhi di pinnalacera","assegnatario della missione dell'occhio di pinnalacera"}},{q="Perché la Società dei Farmacisti Reali ha bisogno di parti di murloc?",a="La Società dei Farmacisti Reali studia le creature locali alla ricerca di composti che attivino o potenzino i contaminanti tossici. Gli umori oculari dei murloc Pinnalacera possono catalizzare prototipi di piaghe volatili.",al={"perché occhi di murloc","murloc degli speziali"}}},fx={edd43501={q="Che cos'è un Occhio di Pinnalacera?",a="Un Occhio di Pinnalacera è un reagente alchemico ricavato dai murloc costieri che infestano le rive delle Alture di Colletorto. Viscosi e saturi di umori anfibi, questi occhi sono usati dagli alchimisti Reietti che necessitano di catalizzatori biologici per attivare agenti contaminanti volatili nelle loro miscele sperimentali.",al={"cos'è l'occhio di pinnalacera","informazioni sull'occhio di pinnalacera","informazioni sugli occhi di pinnalacera"}},["3427cbae"]={q="Da dove provengono gli Occhi di Pinnalacera?",a="Questi reagenti organici sono estratti dai murloc della tribù Pinnalacera, che vive sulla Riva Occidentale lungo la costa meridionale delle Alture di Colletorto, appena a ovest dell'insediamento umano di Riva del Sud. Sono parti biologiche naturali ricavate direttamente dai murloc uccisi, non oggetti fabbricati.",al={"origine dell'occhio di pinnalacera","dove trovare gli occhi di pinnalacera","chi lascia cadere l'occhio di pinnalacera"}}},fp="12,144,18.431.0,13.332.1,32.276.0,32.133.0,39.120.0,56.184.0"}
P.entries["item:torn-murloc-fin"] = {n="Pinna di Murloc Strappata",s="Lungo i corsi d'acqua dell'Elwynn orientale, i murloc affollano le rive e la taglia dell'esercito di Roccavento attira cacciatori.",h="Lungo i corsi d'acqua dell'Elwynn orientale, i murloc affollano le rive e la taglia dell'esercito di...",kw={"taglia sui murloc","murloc elwynn","guardia thomas","pinna di murloc","murloc forager","murloc lurker","lago del memoriale","pinna di murloc strappata"},ang={["faction:Alliance"]="Per l'Alleanza, liberare i corsi d'acqua dell'Elwynn orientale significa proteggere le vie di collegamento vitali tra Borgodoro, Borgolago e Roccavento.",["race:Human"]="Come umano, sai che le autorità locali si affidano sempre più ai mercenari per proteggere fattorie e rive dei fiumi dagli insediamenti aggressivi dei murloc."},sec={{t="Una minaccia con taglia",b="I murloc sono diventati numerosi lungo i ruscelli e i laghi dell'Elwynn orientale. Per questo l'esercito di Roccavento offre una taglia per ridurne il numero. La Guardia Thomas sorveglia il ponte sul fiume orientale e raccoglie pinne recise come prova. Con i soldati impegnati tra disordini interni e minacce vicine, le autorità locali si affidano ai viaggiatori perché dimostrino di aver sgomberato gli accampamenti dei murloc."}},faq={{q="Chi compra o raccoglie le Torn Murloc Fin?",a="Al ponte orientale della Foresta di Elwynn, la Guardia Thomas raccoglie Pinne di Murloc Strappate per il Maresciallo Dughan e l'esercito di Roccavento.",al={"chi vuole le pinne","consegna pinne","pinne guardia thomas"}},{q="Dove si trovano i murloc con queste pinne?",a="Le pinne provengono dai murloc forager e lurker attorno al Lago del Memoriale, a nord, e alla biforcazione meridionale del ruscello vicino al confine orientale di Elwynn.",al={"dove trovare pinne","posizioni pinne di murloc","bottino pinne"}},{q="Perché Roccavento richiede le pinne come prova?",a="Le pinne sono inconfondibili e facili da trasportare. Forniscono all'esercito di Roccavento la prova dell'uccisione dei murloc prima che paghi i cacciatori di taglie.",al={"perché le pinne","prova uccisione murloc","prova della taglia"}},{q="Perché l'esercito di Roccavento paga per i murloc morti?",a="I villaggi dei murloc si sono diffusi rapidamente lungo i corsi d'acqua, minacciando viaggiatori, pescatori e infrastrutture locali. Le forze dell'esercito di Roccavento sono impegnate altrove.",al={"perché taglia sui murloc","problema murloc elwynn"}}},fx={afa68c63={q="Che cos'è una Pinna di Murloc Strappata?",a="Una Pinna di Murloc Strappata è un trofeo fisico reciso dalla pelle dei murloc che infestano la parte orientale della Foresta di Elwynn. Non è un gingillo ornamentale né un ingrediente alchemico, ma la prova tangibile che un predone anfibio è stato ucciso, una verifica affidabile per le autorità locali che offrono taglie.",al={"cos'è una pinna di murloc strappata","storia dei pinnalacera","informazioni sulla pinna di murloc"}},["5ee7d3aa"]={q="Da dove provengono le Pinne di Murloc Strappate?",a="Queste pinne vengono ricavate direttamente dai corpi dei murloc foraggiatori e predatori che abitano le acque basse della Foresta di Elwynn. In particolare, tribù aggressive hanno stabilito accampamenti lungo le rive del Lago del Memoriale e il ramo meridionale dei fiumi orientali, minacciando viaggiatori e fattorie locali.",al={"origine della pinna di murloc strappata","da dove provengono le pinne di murloc"}}},fp="15,108,17.368.0,38.116.0,50.142.0,41.127.0,50.168.0"}
P.entries["item:totem-of-hawkwind"] = {n="Totem dei Vento Agile",s="A Campo Narache, i giovani tauren ricevono il Totem dei Vento Agile prima di partire per il Villaggio di Zoccolo Sanguinario. Lo presentano a Baine Zoccolo Sanguinario come prova di aver superato le prime prove e di poter proseguire i Rites of the Earthmother.",h="A Campo Narache, i giovani tauren ricevono il Totem dei Vento Agile prima di partire per il Villaggio di...",kw={"baine zoccolo sanguinario","villaggio di zoccolo sanguinario","campo narache","capo vento agile","vento agile","rites of the earthmother","totem"},ang={["race:Tauren"]="Per te che sei un tauren, portare questo totem segna il passaggio dall'infanzia sulla Mesa Nuvola Rossa alle più vaste terre tribali di Mulgore."},sec={{t="L'approvazione di un capovillaggio",b="Capo Vento Agile intaglia il Totem dei Vento Agile in cima alla Mesa Nuvola Rossa per i giovani tauren che raggiungono la maturità. Il pegno presenta chi lo porta e ne attesta il passaggio. I tauren ricorrono di rado a documenti formali; un manufatto tribale familiare può trasmettere le intenzioni di un capo.\n\nQuando un giovane completa le prime prove a Campo Narache, Vento Agile lo manda con il totem lungo la strada che si addentra a Mulgore. Le sue incisioni caratteristiche identificano il portatore agli occhi di Baine Zoccolo Sanguinario e ne dimostrano lo spirito e la forza per le prove successive. La strada conduce verso la benedizione di Picco del Tuono."}},faq={{q="A cosa serve il Totem dei Vento Agile?",a="I giovani tauren portano il Totem dei Vento Agile da Campo Narache al Villaggio di Zoccolo Sanguinario come pegno del loro passaggio. Lo presentano a Baine Zoccolo Sanguinario come prova che Capo Vento Agile li ha giudicati pronti a proseguire i Rites of the Earthmother.",al={"a cosa serve il totem dei vento agile","scopo del totem dei vento agile","perché ho questo totem"}},{q="Chi ha creato il totem?",a="Capo Vento Agile intaglia il totem sulla Mesa Nuvola Rossa. I capi alleati di tutta Mulgore ne riconoscono le incisioni caratteristiche.",al={"chi ha intagliato il totem","creatore del totem","origini del totem dei vento agile"}},{q="Chi riceve il Totem dei Vento Agile?",a="Il totem viene consegnato a Baine Zoccolo Sanguinario, figlio di Cairne Zoccolo Sanguinario. Egli guida il Villaggio di Zoccolo Sanguinario, a est della Mesa Nuvola Rossa.",al={"a chi consegno il totem","destinatario del totem","dove va il totem"}},{q="Perché usare un totem invece di una lettera?",a="I tauren si affidano alla tradizione orale, all'arte dei manufatti e ai simboli ancestrali. Un totem intagliato racchiude il tocco personale e lo spirito del suo artefice, e i capi tribali gli attribuiscono più peso dell'inchiostro sulla pergamena.",al={"perché non una lettera","tradizioni dei pegni tauren"}}},fx={["0f3f23e4"]={q="Che cos'è il Totem dei Vento Agile?",a="Il Totem dei Vento Agile è un pegno d'introduzione intagliato e affidato ai giovani tauren promettenti che hanno superato le prove iniziali sulla Mesa Nuvola Rossa. Recando i segni distintivi del Capo Vento Agile, dimostra che sei pronto a lasciare Campo Narache e ad affrontare gli ulteriori Rites of the Earthmother.",al={"identità del totem dei vento agile","cos'è questo totem","totem dei vento agile"}},bb2bdc29={q="Perché Baine Zoccolo Sanguinario vuole il Totem dei Vento Agile?",a="Baine Zoccolo Sanguinario cerca il totem come segno inequivocabile della tua preparazione e del tuo carattere. Intagliato dal Capo Vento Agile, i suoi motivi mostrano a Baine che un giovane aspirante ha meritato la raccomandazione personale di Vento Agile per proseguire le prove spirituali e cercare l'accettazione degli anziani di Picco del Tuono.",al={"perché baine vuole il totem","perché dare il totem a baine","totem di baine zoccolo sanguinario"}}},fp="17,228,25.528.0,39.225.0,19.116.0,35.114.0,36.196.0"}
P.entries["item:tough-wolf-meat"] = {n="Carne Tigliosa di Lupo",s="A Contea del Nord e a Coldridge, i lupi si aggirano per le valli e forniscono carne agli abitanti affamati. La Carne Tigliosa di Lupo è dura e fibrosa. La gente della Foresta di Elwynn la mangia, e gli approvvigionatori nani di Dun Morogh la usano per rifornire le proprie scorte.",h="A Contea del Nord e a Coldridge, i lupi si aggirano per le valli e forniscono carne agli abitanti affamati.",kw={"dun morogh","eagan peltskinner","foresta di elwynn","abbazia della contea del nord","lupo dei boschi","carne tigliosa di lupo","giovane lupo"},ang={["race:Dwarf"]="Come nano nella Valle Crestafredda, puoi abbattere i lupi dei boschi spelacchiati per rifornire di carne gli approvvigionatori locali prima di avventurarti per Dun Morogh.",["race:Human"]="Come recluta umana nella Valle della Contea del Nord, puoi raccogliere carne di lupo per Eagan Peltskinner fuori dall'abbazia. È uno dei primi incarichi di sopravvivenza oltre i suoi tranquilli chiostri."},sec={{t="Razioni di frontiera",b="I lupi si aggirano nei pressi della Valle della Contea del Nord e di Dun Morogh. Minacciano gli insediamenti vicini, ma la loro carne offre una fonte di cibo conquistata a fatica. Dura, fibrosa e difficile da masticare, è apprezzata dai pionieri a corto di risorse.\n\nFuori dall'Abbazia della Contea del Nord, Eagan Peltskinner odia quelle bestie feroci, ma ne cucina la carne in bistecche. Offre provviste ed equipaggiamento di base in cambio a chi sfoltisce i branchi."}},faq={{q="Da dove proviene la Carne Tigliosa di Lupo?",a="I giovani lupi e i lupi dei boschi della Valle della Contea del Nord, nella Foresta di Elwynn, forniscono Carne Tigliosa di Lupo. Anche i lupi spelacchiati della Valle Crestafredda, a Dun Morogh, la forniscono.",al={"fonte di carne tigliosa di lupo","come ottenere carne tigliosa di lupo","dove trovare carne tigliosa di lupo"}},{q="Chi vuole raccogliere questa carne nella Foresta di Elwynn?",a="Eagan Peltskinner, fuori dall'Abbazia della Contea del Nord, raccoglie la carne. Odia i lupi, ma ne cucina la carne in bistecche e offre equipaggiamento in più alle nuove reclute che gli portano otto tagli di carne.",al={"chi ha bisogno di carne di lupo","carne per eagan peltskinner","consegna carne di lupo"}},{q="Questa carne è utile al di fuori delle terre degli umani?",a="Sì. Gli approvvigionatori nani della gelida Dun Morogh accettano carne dei lupi spelacchiati della Valle Crestafredda per mantenere le proprie scorte ben fornite.",al={"carne di lupo dun morogh","carne di lupo nani","carne per dwarven outfitters"}},{q="La Carne Tigliosa di Lupo viene usata nelle normali ricette di cucina?",a="No. I pionieri locali, come Eagan Peltskinner, e gli approvvigionatori di Coldridge richiedono Carne Tigliosa di Lupo in cambio di una ricompensa. Non è un ingrediente delle normali ricette di cucina da campo.",al={"si può cucinare la carne tigliosa di lupo","ricette carne tigliosa di lupo"}}},fx={["877dd280"]={q="Che cos'è la Carne Tigliosa di Lupo?",a="È carne fibrosa e magra ricavata dai lupi selvatici che si aggirano nelle terre selvagge di Contea del Nord e Dun Morogh. Sebbene coriacea e tutt'altro che tenera, è un alimento sostanzioso per i cacciatori di pellicce locali e gli affamati pionieri che sanno cucinarla in bistecche nutrienti.",al={"cos'è la carne tigliosa di lupo","storia della carne tigliosa di lupo","carne tigliosa di lupo"}}},fp="15,231,16.376.0,37.157.0,48.186.0,43.127.0,50.165.0"}
P.entries["item:tourmaline-phial"] = {n="Fiala di Tormalina",s="Alle Pozze di Arlithrien, i viaggiatori raccolgono acqua benedetta del pozzo lunare nella Fiala di Tormalina per i rituali di Teldrassil.",h="Alle Pozze di Arlithrien, i viaggiatori raccolgono acqua benedetta del pozzo lunare nella Fiala di Tormalina...",kw={"corithras lunafuria","crown of the earth","dolanaar","pozzo lunare","pozze di arlithrien","teldrassil","fiala di tormalina"},ang={["class:Druid"]="In quanto druido, porti con te una fiala di pietra preziosa per raccogliere acqua dai pozzi lunari. È un dovere cerimoniale che svolgi mentre impari a prenderti cura del fragile ecosistema di Teldrassil.",["race:NightElf"]="In quanto Elfo della Notte, sai che l'acqua dei pozzi lunari riflette quanto il tuo popolo dipenda dalla grazia di Elune e dalla vigilanza druidica. Teldrassil lotta contro la corruzione."},sec={{t="Recipiente di Arlithrien",b="Corithras Lunafuria affida ai viaggiatori la Fiala di Tormalina per i rituali dedicati alla cura dell'Albero del Mondo. I druidi di Dolanaar usano fiale di pietra preziosa per raccogliere acqua pura dai pozzi lunari di tutta Teldrassil. Questa fiala è destinata al pozzo lunare accanto alle Pozze di Arlithrien, a sud-est della strada per Darnassus. Gli ostili furbolg di Gnarlpine stanno causando sempre più problemi in quella zona."}},faq={{q="A cosa serve la Fiala di Tormalina?",a="La Fiala di Tormalina serve a raccogliere acqua sacra dal pozzo lunare presso le Pozze di Arlithrien. Una volta riempita, la riporti a Corithras Lunafuria a Dolanaar per i rituali di Crown of the Earth.",al={"cosa fa la fiala di tormalina","scopo della fiala di tormalina","usare fiala di tormalina"}},{q="Chi fornisce la Fiala di Tormalina?",a="Corithras Lunafuria, un druido Elfo della Notte di Dolanaar, affida ai viaggiatori la fiala vuota.",al={"chi consegna la fiala di tormalina","dove trovare la fiala di tormalina"}},{q="Dov'è il pozzo lunare per questa fiala?",a="Il pozzo lunare si trova accanto alle Pozze di Arlithrien, a sud-est dell'ingresso principale di Darnassus.",al={"pozzo lunare delle pozze di arlithrien","dove riempire la fiala di tormalina"}}},fx={["6b01991a"]={q="Che cos'è la Fiala di Tormalina?",a="La Fiala di Tormalina è un recipiente cerimoniale vuoto, realizzato per attingere e trasportare le acque sacre dei pozzi lunari di Teldrassil. Affidata a te da Corithras Lunafuria a Dolanaar, è destinata appositamente a raccogliere l'acqua del pozzo lunare appartato vicino alle Pozze di Arlithrien.",al={"cos'è la fiala di tormalina","storia della fiala di tormalina","fiala di tormalina"}},["001b9aba"]={q="Perché Corithras Lunafuria vuole che la Fiala di Tormalina sia riempita?",a="Corithras Lunafuria ha bisogno dell'acqua di ciascun pozzo lunare di Teldrassil per studiare e valutare la salute dell'Albero del Mondo e dei suoi santuari. Attingere dal pozzo lunare vicino alle Pozze di Arlithrien è diventato pericoloso a causa dell'attività violenta dei furbolg Zannaspina, perciò si affida a viaggiatori capaci per recuperare un campione in sicurezza.",al={"perché riempire la fiala di tormalina","scopo della fiala di tormalina","perché corithras vuole la fiala"}}},fp="16,117,20.342.0,38.188.0,34.83.0,37.93.0"}
P.entries["item:toxic-fogger"] = {n="Nebulizzatore Tossico",s="A Petrartiglio, il Nebulizzatore Tossico è destinato alle rotte aeree della S.P.R. & Co. La Società dei Farmacisti Reale dei Reietti lo ha riempito di veleno letale per contaminare i voli della compagnia.",h="A Petrartiglio, il Nebulizzatore Tossico è destinato alle rotte aeree della S.P.R.",kw={"apothecary zamah","piattaforma per elicotteri","lago di altarupe","spazioporto","vette di petrartiglio","nebulizzatore tossico","s.p.r. & co."},ang={["race:Tauren"]="Come tauren, potresti trovare i vapori letali in contrasto con i codici d'onore tradizionali. I danni inflitti alla terra dalla S.P.R. & Co. spingono molti a Picco del Tuono a tollerare le dure misure di Zamah.",["race:Undead"]="Come non morto, vedi all'opera la strategia sul campo della Società dei Farmacisti Reale: ostacolare i rifornimenti nemici con tossine disperse nell'aria e mostrare agli alleati che i metodi oscuri possono dare risultati."},sec={{t="Una soluzione dei Reietti",b="Apothecary Zamah invia il Nebulizzatore Tossico contro le attività minerarie della S.P.R. & Co. Lo Speziale Lydon ne ha preparato la tossina al Mulino di Tarren, e Zamah lo ha spedito da Picco del Tuono. Sospetta che i goblin trasportino messaggi e carichi leggeri tra Petrartiglio e il loro quartier generale con una macchina volante da corriere.\n\nZamah intende rilasciare il veleno dove quelle macchine atterrano e fanno rifornimento. I Reietti intendono colpire la via di rifornimento della compagnia anziché affrontare le sue squadre di mercenari in schermaglie prolungate."},{t="Sabotaggio al Lago di Altarupe",b="Il Nebulizzatore Tossico è destinato alla piattaforma per elicotteri della S.P.R. & Co. vicino al Lago di Altarupe. Il sito d'atterraggio isolato sovrasta le colline disboscate e collega le squadre lontane con gli snodi esterni. Il suo vapore tossico si diffonderà nell'area di raduno e coglierà alla sprovvista i piloti di ritorno.\n\nAlcuni membri dell'Orda potrebbero esitare di fronte al veleno, ma Zamah dice ai suoi agenti di accantonare i sensi di colpa. Crede che nessun metodo sia troppo oscuro se porta alla vittoria sugli sfruttatori."}},faq={{q="A cosa serve il Nebulizzatore Tossico?",a="Il Nebulizzatore Tossico serve ad avvelenare lo scalo aereo della S.P.R. & Co. presso il Lago di Altarupe, nelle Vette di Petrartiglio. Il suo vapore contamina i carichi leggeri e i corrieri diretti al quartier generale della compagnia.",al={"cosa fa il nebulizzatore tossico","scopo del nebulizzatore","perché usare il nebulizzatore tossico"}},{q="Chi ha creato il Nebulizzatore Tossico?",a="Lo Speziale Lydon ha preparato la tossina al Mulino di Tarren con il sangue di innocenti. Apothecary Zamah, emissaria della Società dei Farmacisti Reale nelle Pozze delle Visioni sotto Picco del Tuono, l'ha spedita perché fosse consegnata.",al={"chi ha creato il nebulizzatore","creatore del nebulizzatore tossico","veleno di apothecary zamah"}},{q="Dove deve essere posizionato il Nebulizzatore Tossico?",a="Posiziona il Nebulizzatore Tossico sulla piattaforma sopraelevata per elicotteri della S.P.R. & Co. vicino al Lago di Altarupe, nelle Vette di Petrartiglio, a sud della grande ruota idraulica.",al={"dove metto il nebulizzatore","posizione della piattaforma per elicotteri","posizione dello spazioporto"}},{q="Perché l'Orda ricorre al veleno contro la S.P.R. & Co.?",a="Il disboscamento e le attività minerarie della S.P.R. & Co. devastano Petrartiglio. Apothecary Zamah ritiene troppo lento il combattimento ordinario e crede che l'Orda debba usare metodi spietati per distruggere i goblin prima che causino danni irreparabili.",al={"perché avvelenare i goblin","il veleno è consentito nell'orda","metodi dei reietti a petrartiglio"}}},fx={["3a36a6bd"]={q="Che cos'è il Nebulizzatore Tossico?",a="Il Nebulizzatore Tossico è un dispositivo di dispersione speciale riempito con una mistura letale preparata dai Reietti. Progettato per rilasciare una nube nociva all'attivazione, è uno strumento di sabotaggio volto a contaminare la rete logistica della S.P.R. & Co. e a intralciarne le operazioni a Lungavista.",al={"cos'è il nebulizzatore tossico","oggetto nebulizzatore tossico","dispositivo nebulizzatore tossico"}},bbff0049={q="Perché Apothecary Zamah vuole che il Nebulizzatore Tossico venga attivato?",a="Apothecary Zamah intende colpire direttamente la catena di approvvigionamento della S.P.R. & Co. Attivando il nebulizzatore nel loro piccolo porto aereo, il tossico può ricoprire i velivoli e i carichi in partenza, trasportando il veleno fino al quartier generale dei goblin e infliggendo una dura ritorsione per il loro sfruttamento incontrollato.",al={"perché usare il nebulizzatore tossico","perché volere il nebulizzatore tossico","perché serve il nebulizzatore tossico"}}},fp="12,179,19.487.0,25.430.1,34.196.0,29.204.0,46.146.0,70.220.0"}
P.entries["item:translated-letter"] = {n="Lettera Tradotta",s="A Borgoscuro, Sirra Von'indi traduce la lettera di Abercrombie per il sindaco Ello Ebonlocke. Il messaggio fa luce sui rapporti dell'eremita con la città.",h="A Borgoscuro, Sirra Von'indi traduce la lettera di Abercrombie per il sindaco Ello Ebonlocke.",kw={"abercrombie","borgoscuro","lettera per ello","ser ello serranero","sirra von'indi","lettera tradotta"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza a Boscovespro, scopri come le buone intenzioni possano essere rivolte contro i vulnerabili difensori di Borgoscuro."},sec={{t="Un'atroce rivelazione",b="Le commissioni iniziarono come atti di carità per un eremita apparentemente indifeso a Collecorvo. L'oscuro messaggio di Abercrombie al sindaco Ello Serranero rimase un mistero finché Sirra Von'indi non lo tradusse. Le parole rivelano che l'eremita è l'Imbalsamatore. Usò i rifornimenti che gli erano stati portati per costruire Stitches, una mostruosa abominazione, poi scatenò la colossale creatura sugli abitanti di Borgoscuro per calpestarli e massacrarli."},{t="Il prezzo delle buone intenzioni",b="Quando il messaggio tradotto viene presentato a Ser Ello Serranero, il volto del sindaco sbianca. Il viaggiatore aveva offerto il suo aiuto in buona fede, ma Abercrombie sfruttò quel lavoro per costruire uno strumento di massacro. Mentre il consiglio cittadino si affretta a mobilitare la Night Watch, la lettera rivela come la carità possa essere distorta e trasformata in devastazione lungo le strade infestate di Boscovespro."}},faq={{q="Cosa dice la Lettera Tradotta?",a="La lettera contiene un messaggio allarmante di Abercrombie per Ser Ello Serranero. Il suo contenuto completo viene rivelato quando gli consegni il messaggio tradotto a Borgoscuro.",al={"testo della lettera","cosa ha scritto abercrombie","cosa c'è scritto"}},{q="Chi traduce la lettera?",a="Sirra Von'indi, una studiosa di Borgoscuro, decifra la criptica grafia di Abercrombie e ti esorta a tornare in fretta da Ser Ello con le allarmanti notizie.",al={"chi la traduce","chi ha decifrato la lettera","lettera di sirra von'indi"}},{q="Cosa succede quando Ello legge la lettera?",a="Ello è profondamente allarmato dalla traduzione. Portagli la lettera per scoprire cosa significa per Borgoscuro.",al={"reazione di ello","consegnare la lettera tradotta","cosa succede dopo la traduzione"}},{q="Posso gettare via la Lettera Tradotta dopo la missione?",a="Sì. Dopo che Ser Ello ha esaminato la pergamena e predisposto le difese della città, la lettera rimane nel tuo zaino come ricordo e non ha altri usi.",al={"è sicuro eliminare la lettera tradotta","posso distruggere la lettera tradotta","conservare la lettera tradotta"}}},fx={ad927ea8={q="Che cos'è la Lettera Tradotta?",a="La Lettera Tradotta è un'inquietante missiva scritta dall'eremita Abercrombie e decifrata da Sirra Von'indi. Rivela le orribili conseguenze dei loschi piani di Abercrombie a Collecorvo e funge da avvertimento diretto dell'imminente rovina che minaccia gli abitanti di Borgoscuro.",al={"lettera tradotta","cos'è la lettera tradotta","informazioni sulla lettera tradotta"}},["7688c5ef"]={q="Perché Ser Ello Serranero ha bisogno della Lettera Tradotta?",a="Ser Ello Serranero, il sindaco di Borgoscuro, deve leggere il contenuto decifrato per comprendere il grave pericolo che minaccia la sua città. La lettera svela la natura orribile dell'opera di Abercrombie e avverte in anticipo gli abitanti che una mostruosa abominazione avanza barcollando dritta verso i loro cancelli.",al={"perché portare la lettera tradotta a ello","perché ello vuole la lettera tradotta","chi ha bisogno della lettera tradotta"}}},fp="17,150,21.409.1,28.357.1,36.168.1,26.149.0,40.104.1,55.145.1"}
P.entries["item:treshala-s-pendant"] = {n="Pendente di Treshala",s="Nelle Gallerie di Lamaspina, il pendente di Heralath testimonia il legame che lo unisce a Treshala. Lo portò dalla loro casa a Darnassus fino al sud di Kalimdor, dove i verrospino glielo strapparono mentre giaceva morente.",h="Nelle Gallerie di Lamaspina, il pendente di Heralath testimonia il legame che lo unisce a Treshala.",kw={"darnassus","heralath rivobrado","mortality wanes","verrospino","gallerie di lamaspina","treshala rivobrado","pendente di treshala"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi portare il pegno a Darnassus e dare conforto a una vedova che piange il suo esploratore caduto.",["race:NightElf"]="Come Elfo della Notte, puoi onorare un altro kaldorei morto lontano dal rifugio di Teldrassil recuperando il pendente."},sec={{t="Pegno di Devozione",b="Durante i pericolosi viaggi lontano da Teldrassil, Heralath Rivobrado teneva il pendente sempre con sé. Gli ricordava la sua casa, la sua amata moglie, Treshala, e la devozione che li univa."},{t="Perduto tra i Rovi",b="Heralath entrò nelle Gallerie di Lamaspina con il suo gruppo, dove i selvaggi verrospino li assalirono. Mentre giaceva morente, uno dei difensori zannuti gli strappò il pendente. Heralath chiese a un avventuriero di passaggio di sottrarre il ricordo ai suoi uccisori e riportarlo a casa, a Treshala a Darnassus, con notizie della sua sorte."}},faq={{q="Che cos'è il Pendente di Treshala?",a="Treshala Rivobrado è la proprietaria del pendente. Suo marito Heralath lo portava con sé come ricordo della loro unione prima di morire nelle Gallerie di Lamaspina.",al={"cos'è questo oggetto","pendente di legame","chi possiede il pendente"}},{q="Come è finito il pendente nelle Gallerie di Lamaspina?",a="Heralath Rivobrado portò il pendente durante una spedizione nelle Gallerie di Lamaspina. Dopo che i verrospino gli tesero un'imboscata e lo ferirono mortalmente, uno di loro gli sottrasse la collana.",al={"perché si trova a rfk","come è andato perduto"}},{q="Chi chiede di recuperare il pendente?",a="Mentre giace morente nelle Gallerie di Lamaspina, Heralath Rivobrado supplica gli avventurieri di passaggio di recuperare il pendente e restituirlo a sua moglie a Darnassus, portandole la notizia della sua morte.",al={"chi assegna la missione","chi rivuole il pendente"}},{q="Chi riceve il pendente una volta recuperato?",a="Treshala Rivobrado riceve il pendente recuperato. La vedova di Heralath vive a Darnassus, la capitale degli Elfi della Notte in cima a Teldrassil.",al={"dove porto il pendente","chi è treshala"}}},fx={["1ac8940a"]={q="Perché cercano il Pendente di Treshala?",a="Mentre l'elfo della notte Heralath Rivobrado esala i suoi ultimi respiri nelle Gallerie di Lamaspina, il suo ultimo desiderio è che venga recuperato questo ricordo che gli è stato rubato. È un pendente di unione che gli aveva donato sua moglie, Treshala. Prima di morire solo nella roccaforte dei quilboar, spera che tu lo recuperi dai bruti che l'hanno preso e consegni a sua moglie a Darnassus sia il pendente sia la triste notizia della sua morte.",al={"perché cercare il pendente di treshala","perché heralath vuole il pendente","a cosa serve il pendente di treshala"}}},fp="18,197,17.180.0,18.295.1,27.133.0,45.160.0,41.167.0,46.128.0"}
P.entries["item:trogg-stone-tooth"] = {n="Dente Roccioso di Trogg",s="Sulle colline di Loch Modan, i trogg Stonesplinter lasciano denti robusti e mineralizzati. I difensori nanici usano ogni dente come prova che si sta dando la caccia ai trogg lungo la frontiera meridionale.",h="Sulle colline di Loch Modan, i trogg Stonesplinter lasciano denti robusti e mineralizzati.",kw={"loch modan","rugelfuss","stonesplinter","the trogg threat","trogg","dente roccioso di trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, rispondendo all'appello del Capitano Granchiasso allevi la pressione sulle vie commerciali che collegano i regni nanici al resto dell'Alleanza.",["race:Dwarf"]="Come nano, con ogni dente recuperato contribuisci a rendere più sicura Khaz Modan, mentre gran parte dell'esercito di Forgiardente presta servizio all'estero con l'Alleanza."},sec={{t="Taglia del Cancello Meridionale",b="Il Capitano Granchiasso cerca volontari per dare la caccia ai trogg Stonesplinter vicino al cancello meridionale di Loch Modan. Con la Riserva di Forgiardente impegnata sul Fronte dell'Alleanza, le guarnigioni naniche locali sono a corto di uomini in tutta Khaz Modan. Granchiasso non può distogliere i soldati della torre di guardia del cancello meridionale per pattugliare le colline vicine. Così i volontari danno la caccia ai trogg in agguato e riportano Denti Rocciosi di Trogg come prova grezza e innegabile di ogni bestia uccisa."}},faq={{q="Chi vuole questi denti rocciosi di trogg?",a="Alla torre di guardia meridionale di Loch Modan, il Capitano Granchiasso raccoglie i denti come prova che i viaggiatori stanno dando la caccia ai trogg Stonesplinter.",al={"chi accetta i denti rocciosi di trogg","denti rugelfuss","chi ha bisogno di denti di pietra"}},{q="Perché i denti sono fatti di pietra?",a="I trogg hanno una natura terrigna e sotterranea legata ad antiche origini nella pietra. Le loro zanne e i loro denti sono pesanti e mineralizzati, come roccia grezza.",al={"perché dente di pietra","anatomia denti trogg","i denti dei trogg sono rocce"}},{q="Perché il presidio nanico non dà la caccia ai trogg da solo?",a="La Riserva di Forgiardente si è unita allo sforzo bellico generale dell'Alleanza, lasciando gli avamposti locali a corto di uomini. Il reggimento del Capitano Granchiasso deve sorvegliare il cancello meridionale e non può lasciare sguarnita la propria fortificazione.",al={"perché rugelfuss ha bisogno di aiuto","perché i nani non combattono i trogg","riserva di forgiardente"}},{q="Quali trogg portano questi denti?",a="I denti provengono dai trogg Stonesplinter delle colline e degli scavi di Loch Modan. Tra loro ci sono comuni scavatori, esploratori, guerrieri che spezzano le ossa e geomanti.",al={"dove trovare i denti rocciosi di trogg","chi rilascia denti di pietra"}}},fx={d6a17ab5={q="Che cos'è un Dente Roccioso di Trogg?",a="Un Dente Roccioso di Trogg è letteralmente un dente duro come la pietra, strappato alle fauci dei trogg Scheggiapietra che infestano le rupi di Loch Modan. Riflettendo la bizzarra natura terragna dei trogg, questi denti induriti fungono da inconfutabile prova tangibile per i difensori nani del luogo che un trogg predone è stato eliminato definitivamente.",al={"che cos'è il dente roccioso di trogg","informazioni sul dente roccioso di trogg","dente roccioso trogg"}}},fp="17,187,27.438.0,34.132.0,32.137.0,58.202.0,31.155.0"}
P.entries["item:troll-charm"] = {n="Talismano Troll",s="A Valtetra, alcuni Talismani Troll sono stati rubati a viaggiatori Puntascura. I furbolg Mantocardo hanno preso i sacri amuleti dopo aver teso un'imboscata al gruppo diretto all'Avamposto di Zoram'gar.",h="A Valtetra, alcuni Talismani Troll sono stati rubati a viaggiatori Puntascura.",kw={"valtetra","puntascura","mitsuwa","rifugio dei mantocardo","villaggio dei mantocardo","talismano troll","avamposto di zoram'gar"},ang={["faction:Horde"]="Come membro dell'Orda, recuperando i talismani rubati indebolisci l'aggressiva tribù dei Mantocardo e vendichi i viaggiatori dell'Orda uccisi lungo gli insidiosi sentieri di Valtetra.",["race:Troll"]="Come troll Puntascura, lasciare i sacri talismani nelle mani di selvaggi furbolg è un insulto intollerabile ai tuoi fratelli caduti."},sec={{t="Sacri monili dei Puntascura",b="I troll Puntascura indossano talismani spirituali come simboli di dignità. L'esploratore Mitsuwa dice che un troll senza talismano è sminuito quanto un orco senza cicatrici di battaglia. Un gruppo di fratelli Puntascura viaggiava sotto le fronde di Valtetra verso l'Avamposto di Zoram'gar. I furbolg Mantocardo corrotti hanno teso loro un'imboscata e li hanno massacrati. I loro spiriti sono stati affidati all'aldilà, mentre i furbolg hanno preso i talismani come trofei e li hanno nascosti in forzieri nelle profondità del Rifugio dei Mantocardo."}},faq={{q="A cosa servono i Talismani Troll?",a="I troll Puntascura portano i Talismani Troll come sacre protezioni spirituali e simboli di dignità personale.",al={"scopo del talismano troll","storia del talismano troll","perché i troll portano talismani"}},{q="Dove si trovano questi talismani?",a="I talismani sono chiusi in forzieri nel Rifugio dei Mantocardo, un complesso di caverne dietro il Villaggio dei Mantocardo, nella parte settentrionale di Valtetra.",al={"dove si trovano i talismani troll","come trovare il talismano troll","posizione del forziere dei troll"}},{q="Perché i furbolg possiedono questi talismani?",a="I furbolg Mantocardo hanno teso un'imboscata a viaggiatori Puntascura diretti all'Avamposto di Zoram'gar e li hanno uccisi. Hanno saccheggiato i loro averi e tenuto i talismani.",al={"perché i furbolg li hanno","chi ha rubato i talismani"}},{q="Chi rivuole indietro i talismani?",a="Mitsuwa, un troll Puntascura di stanza all'Avamposto di Zoram'gar sulla Spiaggia di Zoram, cerca i talismani per restituire onore ai suoi fratelli uccisi.",al={"chi prende i talismani","missione di mitsuwa"}}},fx={["5fe70fe7"]={q="Che cos'è un Talismano Troll?",a="Un Talismano Troll è un sacro amuleto tribale portato dai troll Lanciascura. Questi talismani hanno un profondo significato personale e spirituale per i troll e sono considerati simboli essenziali della loro identità e del loro prestigio, tanto che un troll privo del proprio talismano è ritenuto dai suoi simili alla stregua di un orco senza cicatrici di battaglia.",al={"che cos'è un talismano troll","oggetto talismano troll","talismano sacro troll"}},["6d34290e"]={q="Da dove provengono i Talismani Troll e chi li ha creati?",a="Questi talismani sono stati realizzati e portati dai troll Lanciascura in viaggio attraverso Valtetra verso l'Avamposto di Zoram'gar. Purtroppo, i viaggiatori sono stati assaliti e uccisi lungo la strada dai furbolg Mantocardo ostili, che hanno saccheggiato gli oggetti sacri e li hanno rinchiusi in casse nelle profondità del Rifugio dei Mantocardo.",al={"origine dei talismani troll","chi ha creato i talismani troll","da dove provengono i talismani troll"}},["77137dd7"]={q="Perché Mitsuwa vuole che vengano restituiti i Talismani Troll?",a="Mitsuwa, all'Avamposto di Zoram'gar, piange i viaggiatori caduti, ma accetta che si riuniranno nell'aldilà. Tuttavia, lasciare che dei furbolg rozzi e ostili conservino simili reliquie sacre è considerato un insulto intollerabile all'eredità dei troll. Recuperarle rende onore alla memoria degli uccisi.",al={"perché recuperare i talismani troll","perché mitsuwa vuole i talismani","perché cercano i talismani troll"}}},fp="11,176,32.441.0,31.92.0,29.120.0,38.141.0,26.130.0"}
P.entries["item:trophy-swoop-quill"] = {n="Penna Trofeo d'Avvoltoio",s="In tutta Mulgore, gli swoop volteggiano alti sulle pianure e le loro penne attestano l'abilità di un cacciatore. I tauren portano le piume a Harken Totem Fulgido al Villaggio di Zoccolo Sanguinario.",h="In tutta Mulgore, gli swoop volteggiano alti sulle pianure e le loro penne attestano l'abilità di un...",kw={"villaggio di zoccolo sanguinario","harken totem fulgido","mulgore","caccia agli swoop","penna d'avvoltoio","taloned swoop","penna trofeo d'avvoltoio","wiryswoop"},ang={["class:Hunter"]="Come cacciatore, inseguire prede in volo attraverso pianure aperte mette alla prova la tua capacità di seguirne le tracce, la tua pazienza e la tua mira.",["race:Tauren"]="Come tauren, cacciare gli swoop e riportare a casa le loro penne mette alla prova la tua pazienza e astuzia nelle terre di Mulgore. Rende onore a te e al tuo clan."},sec={{t="Pegno della Caccia",b="Gli swoop volteggiano alti sopra le praterie di Mulgore, dove è difficile seguirne le tracce. I giovani cacciatori tauren e i viaggiatori del Villaggio di Zoccolo Sanguinario cercano una penna trofeo per dimostrare la propria astuzia e determinazione. Portarne una ad anziani come Harken Totem Fulgido rende onore al clan del cacciatore e dimostra i sensi acuti necessari per prosperare nelle pianure."}},faq={{q="A cosa serve una Penna Trofeo d'Avvoltoio?",a="Porta una Penna Trofeo d'Avvoltoio a Harken Totem Fulgido al Villaggio di Zoccolo Sanguinario per dimostrare il tuo valore nella caccia. La piuma dimostra determinazione e un acuto spirito di osservazione, e dà lustro alla tua posizione tra i tauren del luogo.",al={"a cosa servono le penne d'avvoltoio","chi vuole le penne d'avvoltoio","uso penna d'avvoltoio"}},{q="Da dove provengono le Penne Trofeo d'Avvoltoio?",a="Le Penne Trofeo d'Avvoltoio provengono dagli swoop comuni, esili e artigliati che sorvolano la Piana Ondulata di Mulgore.",al={"dove trovare le penne d'avvoltoio","chi rilascia la penna trofeo d'avvoltoio","posizioni degli swoop"}},{q="Perché gli swoop sono considerati difficili da cacciare?",a="Harken Totem Fulgido descrive gli swoop come uccelli astuti che volteggiano alti sopra l'erba e si spostano rapidamente sul territorio. Una vista acuta ti aiuta ad avvistarli, mentre gambe veloci ti aiutano a raggiungerli.",al={"perché cacciare gli swoop","gli swoop sono difficili da uccidere"}}},fx={["91a49961"]={q="Che cos'è una Penna Trofeo d'Avvoltoio?",a="La Penna Trofeo d'Avvoltoio è una piuma pregiata strappata agli avvoltoi predatori che sorvolano Mulgore. Poiché sono creature elusive e dotate di una vista acuta, raccoglierne le piume richiede sensi affinati e passo svelto. Tra i tauren, portare queste penne è un segno d'astuzia e determinazione, che dimostra la pazienza e l'abilità necessarie a seguire e sopraffare una preda scaltra.",al={"penna trofeo d'avvoltoio","che cos'è una penna d'avvoltoio","storia delle penne d'avvoltoio"}},["62601276"]={q="Perché Harken Totem Fulgido vuole le Penne Trofeo d'Avvoltoio?",a="Harken Totem Fulgido, al Villaggio di Zoccolo Sanguinario, chiede queste penne come prova di abilità e carattere. Cacciare gli avvoltoi non è facile e tornare con una raccolta delle loro piume migliori dimostra il tuo valore al villaggio. Consegnarle mostra che possiedi la pazienza e la determinazione richieste a un vero cacciatore, portando onore a te e al tuo clan.",al={"perché raccogliere penne d'avvoltoio","perché harken vuole le penne d'avvoltoio","scopo della caccia agli avvoltoi"}}},fp="18,161,17.325.0,38.200.0,39.119.0,44.194.0"}
P.entries["item:twilight-pendant"] = {n="Pendente del Crepuscolo",s="Negli Abissi di Fondocupo, i Pendenti del Crepuscolo identificano i cultisti del Martello del Crepuscolo che si radunano con i naga. L'Alba d'Argento cerca i pendenti come prova delle attività del culto lungo la costa di Valtetra.",h="Negli Abissi di Fondocupo, i Pendenti del Crepuscolo identificano i cultisti del Martello del Crepuscolo che...",kw={"guardia d'argento manados","valtetra","abissi di fondocupo","antichi dei","twilight falls","pendente del crepuscolo","martello del crepuscolo"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi portare questi trofei alla Guardia d'Argento Manados a Darnassus. Dimostrano il sostegno dell'Alleanza alla campagna dell'Alba d'Argento contro i mali nascosti nel nord di Kalimdor.",["race:NightElf"]="Come Elfo della Notte, sai che gli Abissi di Fondocupo un tempo ospitavano un pozzo lunare venerato e potente. Recuperare i simboli della sua corruzione è una questione profondamente sacra per i kaldorei."},sec={{t="Simboli degli Antichi Dei",b="Sotto gli Abissi di Fondocupo, il Martello del Crepuscolo si raduna con i naga per onorare i caotici Antichi Dei. Maghi dell'ombra, acquamanti, predoni e cercatori di conoscenza indossano Pendenti del Crepuscolo per mostrare devozione ai loro oscuri patroni. Il culto rimane tra le rovine di quello che un tempo era un tempio degli Elfi della Notte. I pendenti offrono quindi agli estranei uno dei pochi modi per scoprire quanti cultisti vi si radunano e ostacolare i loro piani."},{t="Le veglie dell'Alba d'Argento",b="A Darnassus, la Guardia d'Argento Manados cerca Pendenti del Crepuscolo come prova che l'oscurità crescente viene respinta. Gli Abissi di Fondocupo un tempo ospitavano un pozzo lunare incontaminato, e gli adoratori del vuoto lo hanno profanato. Questo minaccia Kalimdor. Raccogliere i pendenti dimostra che la testa di ponte del Martello del Crepuscolo a Valtetra viene smantellata prima che i suoi patroni scatenino un terrore maggiore."}},faq={{q="Cos'è un Pendente del Crepuscolo?",a="I Pendenti del Crepuscolo sono amuleti identificativi indossati dai membri del Martello del Crepuscolo negli Abissi di Fondocupo. Mostrano la devozione dei cultisti agli Antichi Dei e ai loro riti.",al={"informazioni sul pendente del crepuscolo","cosa sono i pendenti del crepuscolo"}},{q="Perché la Guardia d'Argento Manados vuole questi pendenti?",a="A Darnassus, la Guardia d'Argento Manados cerca Pendenti del Crepuscolo come prova che il Martello del Crepuscolo negli Abissi di Fondocupo viene abbattuto prima che i suoi piani possano compiersi.",al={"chi vuole il pendente del crepuscolo","perché raccogliere i pendenti del crepuscolo"}},{q="Chi indossa questi pendenti?",a="Twilight Acolytes, acquamanti, maghi dell'ombra, cercatori di conoscenza, Elementalists e predoni indossano questi pendenti all'interno degli Abissi di Fondocupo.",al={"chi lascia il pendente del crepuscolo","da dove provengono i pendenti del crepuscolo"}},{q="Quale minaccia rappresenta il Martello del Crepuscolo negli Abissi di Fondocupo?",a="Negli Abissi di Fondocupo, il Martello del Crepuscolo si allea con i naga per ravvivare il culto degli Antichi Dei. I suoi riti profanano un antico pozzo lunare degli Elfi della Notte e potrebbero diffondere il terrore in tutta Kalimdor.",al={"cosa fa il martello del crepuscolo a bfd","perché i cultisti sono a valtetra"}}},fp="16,189,22.391.0,24.368.0,27.159.0,50.165.0,25.130.0,65.190.0"}
P.entries["item:twilight-whisker"] = {n="Baffo del Crepuscolo",s="A Malaka'jin, il Taumaturgo Jin'zil raccoglie Baffi del Crepuscolo per la sua pozione. I corridori del crepuscolo portano questi baffi sulle alture settentrionali delle Vette di Petrartiglio.",h="A Malaka'jin, il Taumaturgo Jin'zil raccoglie Baffi del Crepuscolo per la sua pozione.",kw={"magia della foresta","malaka'jin","vette di petrartiglio","picco di petrartiglio","corridore del crepuscolo","baffo del crepuscolo","taumaturgo jin'zil"},ang={["race:NightElf"]="Come Elfo della Notte, vedi creature sacre dei boschi, come i corridori del crepuscolo e i draghi fatati, profanate per avvelenare gli Elfi della Notte prigionieri nelle foreste di Kalimdor.",["race:Troll"]="Come troll, vedi Jin'zil usare le bestie locali come reagenti nel vudù dei Puntascura, rivolgendo l'essenza naturale della foresta contro i suoi nemici."},sec={{t="Un reagente per il taumaturgo",b="I corridori del crepuscolo si aggirano sugli alti dirupi vicino al Picco di Petrartiglio. I cacciatori ne apprezzano le pellicce, mentre il Taumaturgo Jin'zil di Malaka'jin cerca i loro rigidi baffi per uno scopo più oscuro. Vuole vendicarsi degli Elfi della Notte catturati dopo aver difeso questi boschi. Per schernire e avvelenare i suoi prigionieri, Jin'zil raccoglie linfa resinosa, innumerevoli occhi, Scaglie di Drago Fatato e Baffi del Crepuscolo per una pozione letale che chiama magia della foresta."}},faq={{q="Dove si trovano i Baffi del Crepuscolo?",a="I corridori del crepuscolo sui pendii attorno al Picco di Petrartiglio, nelle Vette di Petrartiglio settentrionali, portano Baffi del Crepuscolo.",al={"posizione baffo del crepuscolo","chi rilascia baffi del crepuscolo","dove ottenere baffi del crepuscolo"}},{q="Perché il Taumaturgo Jin'zil li vuole?",a="Il Taumaturgo Jin'zil combina Baffi del Crepuscolo con linfa, occhi di corsiero e una Scaglia di Drago Fatato per preparare un intruglio mortale destinato agli Elfi della Notte suoi prigionieri a Malaka'jin.",al={"baffi jinzil","perché jin'zil vuole i baffi del crepuscolo","ingredienti magia della foresta jin'zil"}},{q="Cosa succede dopo che Jin'zil riceve i baffi?",a="Dopo aver ricevuto gli ingredienti, Jin'zil sprigiona la sua pozione nella caverna. Questa uccide rapidamente gli Elfi della Notte imprigionati nelle gabbie, i cui spiriti emergono sotto forma di fuochi fatui e si allontanano fluttuando.",al={"esito magia della foresta","cosa succede ai prigionieri"}}},fx={["15466f07"]={q="Che cos'è un Baffo del Crepuscolo?",a="Il Baffo del Crepuscolo è un rigido pelo del muso ricavato dai corridori crepuscolari che si aggirano sulle alture delle Vette di Petrartiglio. Per molti è solo una scoria animale, ma per chi pratica il vudù e l'alchimia è un potente reagente che racchiude l'essenza selvaggia dei predatori locali.",al={"che cos'è un baffo del crepuscolo","informazioni sul baffo del crepuscolo","che cosa sono i baffi del crepuscolo"}},["8f61da64"]={q="Da dove proviene un Baffo del Crepuscolo?",a="I Baffi del Crepuscolo vengono strappati ai corridori crepuscolari, felini predatori originari delle Vette di Petrartiglio. Non sono fabbricati da mani mortali, ma prelevati direttamente dalle bestie che vagano nei pressi del Picco di Petrartiglio.",al={"origine del baffo del crepuscolo","dove trovare il baffo del crepuscolo","chi lascia cadere il baffo del crepuscolo"}}},fp="16,168,24.419.0,34.114.0,40.163.0,49.166.1"}
P.entries["item:twitching-antenna"] = {n="Antenna Ronzante",s="Nelle Savane Meridionali, le Antenne Ronzanti segnano una caccia che mette alla prova la rapidità e l'abilità di un giovane guerriero. Ruga Totem Rabbioso a Camp Taurajo le cerca prima che i loro nervi smettano di fremere.",h="Nelle Savane Meridionali, le Antenne Ronzanti segnano una caccia che mette alla prova la rapidità e l'abilità...",kw={"antenne","savane","camp taurajo","field of giants","ruga totem rabbioso","silitidi","antenna ronzante"},ang={["class:Hunter"]="Come cacciatore, segui le tracce dei silitidi e li uccidi, poi raccogli le loro antenne mentre fremono ancora. La prova mette alla prova la tua rapidità, la tua capacità di seguire le tracce e la tua abilità sul campo.",["race:Tauren"]="Come tauren, sai che i cacciatori di Camp Taurajo vedono l'improvviso arrivo dei silitidi come un turbamento dell'equilibrio naturale delle pianure. I giovani prodi devono restare vigili."},sec={{t="Prova della Caccia",b="Le larve, gli sciamatori e i mietitori silitidi, insieme ai Creepers, hanno antenne che continuano a fremere dopo essere state recise dalla testa. Gli spasmi svaniscono poco dopo la morte degli insetti. Un giovane guerriero deve cacciare i silitidi nelle distese meridionali, poi affrettarsi a tornare attraverso la boscaglia mentre le antenne fremono ancora. La prova mette alla prova rapidità e abilità e segna un rito di passaggio per i guerrieri dell'Orda."},{t="La Minaccia a Sud",b="Le antenne dei silitidi indicano un pericolo che preoccupa i cacciatori di Camp Taurajo. Queste creature non sono originarie delle Savane, e i nuovi cumuli che scavano a Field of Giants inquietano l'accampamento. Ruga Totem Rabbioso vuole i campioni per studiare il pericolo e preparare i guerrieri dell'Orda alla minaccia aliena che avanza nelle pianure."}},faq={{q="Quali creature rilasciano le Antenne Ronzanti?",a="Le larve, i mietitori e gli sciamatori silitidi, insieme ai Creepers, nei dintorni di Field of Giants nelle Savane Meridionali hanno queste antenne.",al={"dove si trovano le antenne ronzanti","chi rilascia antenna ronzante","fonte antenne di silitide"}},{q="Perché le antenne devono ronzare?",a="Il fremito indica che le antenne sono state recise da poco. Ruga Totem Rabbioso valuta la rapidità e l'abilità in combattimento di un aspirante in base a quanto presto smettono di fremere durante la corsa su terreni selvaggi.",al={"perché ronzante","perché la fretta per le antenne","tempo trial at the field of giants"}},{q="Chi è alla ricerca di queste antenne?",a="Ruga Totem Rabbioso, un guerriero tauren a Camp Taurajo nelle Savane Meridionali, cerca le antenne per Trial at the Field of Giants.",al={"chi vuole l'antenna ronzante","a chi consegnare le antenne"}},{q="Dove si trova Field of Giants?",a="Field of Giants si trova a sud di Camp Taurajo, nelle Savane. Enormi resti scheletrici si ergono dal terreno, circondati da alveari di silitidi.",al={"dove si trova field of giants","posizione di field of giants"}}},fx={["47f6f8c0"]={q="Che cos'è un'Antenna Ronzante?",a="Un'Antenna Ronzante è un organo sensoriale appena reciso, ricavato da uno dei silitidi che infestano la parte meridionale delle Savane. Queste bizzarre appendici insettoidi continuano a contorcersi e contrarsi per l'energia nervosa ancora per un breve periodo dopo essere state recise da larve, sciami e mietitori.",al={"che cos'è un'antenna ronzante","storia dell'antenna ronzante","antenna dei silitidi"}},["057f3d5d"]={q="Da dove proviene un'Antenna Ronzante?",a="Queste antenne provengono dal bizzarro sciame di silitidi apparso di recente nei pressi del Field of Giants, nella parte meridionale delle Savane. Recise direttamente da creature come larve, sciami, striscianti e mietitori, sono materia biologica organica, non strumenti fabbricati.",al={"da dove provengono le antenne ronzanti","chi lascia cadere l'antenna ronzante","parti dei silitidi"}}},fp="17,173,17.366.0,23.314.0,39.121.0,41.176.0,34.130.0,29.144.0"}
P.entries["item:ukor-s-burden"] = {n="Fardello di Ukor",s="Nella Valle delle Sfide, Ukor ha bisogno di aiuto per riportare a Tranciacolle le provviste rifiutate.",h="Nella Valle delle Sfide, Ukor ha bisogno di aiuto per riportare a Tranciacolle le provviste rifiutate.",kw={"durotar","grosk","peone","razioni","tranciacolle","ukor","valle delle sfide"},ang={["faction:Horde"]="Come membro dell'Orda, vedi come le dure prove di Durotar plasmano i nuovi soldati. Anche un'offerta gentile deve cedere alle esigenze del loro addestramento."},sec={{t="Un errore a fin di bene",b="Ukor, un peone orco, agisce raramente di propria iniziativa. Eppure ha portato provviste dalla locanda di Tranciacolle per sfamare le giovani reclute nella Valle delle Sfide. Il viaggio lo ha condotto tra la polvere rossa e la pericolosa fauna selvatica di Durotar.\n\nI sorveglianti e gli istruttori hanno rifiutato il cibo, convinti che le privazioni e la fame formino veri guerrieri. Ora Ukor aspetta fuori dall'imboccatura del canyon, spaventato dalle bestie lungo il sentiero del ritorno. Ha affidato il sacco ai viandanti di passaggio e chiede loro di riportarlo al Locandiere Grosk."}},faq={{q="Cosa c'è dentro il Fardello di Ukor?",a="Il Fardello di Ukor contiene cibo e provviste della locanda di Tranciacolle. Ukor sperava di sfamare i giovani orchi e troll in addestramento, ma la Valle delle Sfide rifiuta provviste dall'esterno.",al={"cosa c'è nel sacco","contenuto del fardello di ukor","che cibo è"}},{q="Perché la Valle delle Sfide ha rifiutato il cibo?",a="I sorveglianti della Valle delle Sfide credono che le privazioni e la fame temprano il carattere dei giovani guerrieri. Il Locandiere Grosk dice che la fame dà grinta alle reclute, perciò rifiutano la carità esterna.",al={"perché la valle delle sfide ha rifiutato il cibo","perché non volevano il cibo","perché il cibo non serviva"}},{q="Dove deve essere portato il fardello?",a="Riporta il sacco al Locandiere Grosk nella locanda di Tranciacolle. Rimetterà le provviste sugli scaffali e offrirà da bere a chiunque le riporti a casa.",al={"dove porto il fardello di ukor","chi vuole il fardello di ukor","consegna del fardello di ukor"}}},fx={["97aa3ffc"]={q="Che cos'è il Fardello di Ukor?",a="Il Fardello di Ukor è un pesante carico di provviste e viveri raccolti originariamente dalla locanda di Tranciacolle. Un solerte peone di nome Ukor ha preparato da sé il fagotto, con l'intenzione di portare aiuto ai giovani guerrieri che si addestrano nelle aspre rupi della Valle delle Sfide.",al={"che cos'è il fardello di ukor","fardello di ukor","oggetto fardello di ukor"}},["1b425e9c"]={q="Da dove proviene il Fardello di Ukor e chi l'ha preparato?",a="Il fardello proviene dalla locanda di Tranciacolle, affidata alle cure del Locandiere Grosk. Ukor, un orco peone benintenzionato, ha trasportato il carico per tutta la strada, oltre pericolosi scorpioni e ragni, fino alla zona di addestramento, solo per scoprire che nessuno voleva il suo aiuto.",al={"da dove proveniva il fardello di ukor","chi ha preparato il fardello di ukor","origine del fardello di ukor"}},["32c1e657"]={q="Perché qualcuno vuole il Fardello di Ukor?",a="Dopo che gli istruttori della Valle delle Sfide hanno rifiutato le provviste, il Locandiere Grosk ha bisogno che il cibo venga riportato a Tranciacolle per rimetterlo sugli scaffali. Terrorizzato dalle bestie selvagge che si aggirano nelle terre selvagge di Durotar, Ukor si affida ai viaggiatori di passaggio perché lo riportino a casa sano e salvo.",al={"perché grosk vuole il fardello di ukor","perché restituire il fardello di ukor","chi vuole il fardello di ukor"}}},fp="13,110,26.495.0,29.175.0,45.183.0,33.157.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="Zoccolo di Satiro Unito",s="A Valtetra, gli Zoccoli di Satiro Uniti racchiudono il potere che i satiri rubano all'antica foresta. Ula'elek usa quel potere per forgiare armature al Villaggio di Sen'jin.",h="A Valtetra, gli Zoccoli di Satiro Uniti racchiudono il potere che i satiri rubano all'antica foresta.",kw={"valtetra","durotar","manopole","zoccolo","satiro","sen'jin","ula'elek","unito"},ang={["class:Warrior"]="Da giovane guerriero in cerca di fama, puoi dimostrare la tua abilità marziale cacciando i satiri di Valtetra e commissionando armature specializzate agli istruttori dell'Orda nel Villaggio di Sen'jin.",["race:Troll"]="Come troll, condividi l'abilità degli artigiani Puntascura nel trasformare energie oscure o ostili in equipaggiamento utile. Ula'elek sottrae il potere ai nemici demoniaci invece di lasciarlo andare sprecato."},sec={{t="Potere Sottratto",b="I satiri infestano i boschetti corrotti di Valtetra nordorientale, nutrendosi della magia dell'antica foresta. Più ne consumano, più la corruzione deforma i loro corpi demoniaci. I loro zoccoli si gonfiano e perdono la fenditura, diventando densi ricettacoli dell'energia che hanno assorbito. Sciamani e conciatori esperti possono estrarre quel potere instabile."},{t="Forgiare la Brutal Armor",b="Al Villaggio di Sen'jin, sulla costa di Durotar, Ula'elek trasforma la corruzione demoniaca in forza per i campioni dell'Orda. L'armoriere troll prende gli zoccoli dei satiri che si sono nutriti della foresta e ne estrae la magia intrappolata. Poi incanala quel potere rubato nei Brutal Gauntlets, un'armatura per i giovani guerrieri che affrontano le dure prove di Kalimdor."}},faq={{q="Perché questi zoccoli di satiro sono uniti?",a="I satiri di Valtetra si nutrono della magia sacra della foresta e la corrompono mentre ne prosciugano il potere. Quelli che se ne rimpinzano di più sviluppano zoccoli gonfi che perdono la fenditura e trattengono al loro interno la densa energia rubata.",al={"perché non sono fessi","significato zoccolo unito","zoccoli gonfi"}},{q="Dove si possono trovare gli Zoccoli di Satiro Uniti?",a="I satiri tra le rovine corrotte e i boschetti contaminati di Valtetra nordorientale possiedono questi zoccoli, compresi quelli nei pressi di Satirnaar e Jorxian.",al={"dove trovare gli zoccoli","posizione zoccoli di satiro","quali satiri rilasciano zoccoli"}},{q="Chi vuole questi zoccoli a Durotar?",a="Ula'elek, un armoriere del Villaggio di Sen'jin sulla costa meridionale di Durotar, chiede sette zoccoli per poterne estrarre la magia accumulata.",al={"chi ha bisogno di zoccoli di satiro","assegnatore missione zoccoli di satiro","cosa fare con gli zoccoli"}},{q="Cosa si crea con questi zoccoli?",a="Ula'elek estrae dagli zoccoli il potere corrotto della foresta per forgiare un paio di robusti Brutal Gauntlets infusi di magia.",al={"a cosa servono","ricompensa creazione zoccoli","materiali per brutal gauntlets"}}},fx={["81ca4f2a"]={q="Da dove provengono gli Zoccoli di Satiro Unito?",a="Questi zoccoli vengono prelevati direttamente dai satiri che si nascondono nel nord-est di Valtetra. Non sono manufatti, ma parti del corpo naturali deformate da una voracità oscura. I satiri della foresta si rimpinzano delle pure energie naturali di Valtetra, e i demoni che assorbono la maggior quantità di questa magia rubata sviluppano distintivi zoccoli gonfi e non fessi.",al={"da dove provengono gli zoccoli di satiro uniti","chi ha creato lo zoccolo di satiro unito","origine degli zoccoli di satiro"}}},fp="19,148,13.338.0,25.329.0,36.215.0,41.140.0,34.131.0,34.110.0"}
P.entries["item:underbelly-whelp-scale"] = {n="Scaglia di Draghetto dei Sotterranei",s="A sud del Lago Placido, gli artigiani delle Montagne Crestarossa commerciano la Scaglia di Draghetto dei Sotterranei. I draghetti neri forniscono queste scaglie flessibili, apprezzate dagli artigiani locali quando le monete scarseggiano.",h="A sud del Lago Placido, gli artigiani delle Montagne Crestarossa commerciano la Scaglia di Draghetto dei...",kw={"argus","cucciolo di drago nero","borgolago","crestarossa","snarlflare","underbelly scales","scaglia di draghetto dei sotterranei","verner osgood"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, sai che gli isolati difensori di Borgolago dipendono dal baratto con la Foresta di Elwynn per mantenersi equipaggiati. Le risorse locali pericolose da procurare, come le scaglie di drago, contribuiscono a mantenere le scorte della cittadina.",["profession:Blacksmithing"]="Argus e altri artigiani apprezzano queste scaglie per la loro resistenza. Si possono lavorare per ricavarne fodere, impugnature e componenti protettivi specializzati, più resistenti del normale cuoio bovino."},sec={{t="Una rara merce di scambio",b="I draghi neri hanno scaglie resistenti, ma una persona comune non può affrontare un esemplare adulto senza correre pericoli. A sud del Lago Placido, i draghetti neri nidificano tra i dirupi. Le loro placche dorsali possono essere fragili o ruvide, mentre le scaglie più morbide sotto il ventre si piegano più facilmente e offrono comunque protezione. Per questo la Scaglia di Draghetto dei Sotterranei ha valore nel commercio locale. Gli artigiani la apprezzano e i creditori possono accettarla al posto delle monete."},{t="Il debito di Verner",b="Quando le monete scarseggiano o le rotte commerciali sono in difficoltà, gli artigiani di Borgolago ricorrono talvolta al baratto. Verner Osgood, il fabbro locale, ha un grosso debito con Argus, un fabbro di Borgodoro. Il debito risale a una spedizione di scarpe giunta da Borgodoro. Argus predilige le merci rare, quindi Verner si affida ai viaggiatori per raccogliere scaglie dal ventre dei draghetti. Possono aiutarlo a saldare il debito e a mantenere la buona reputazione della sua bottega."}},faq={{q="Da dove provengono le Underbelly Whelp Scales?",a="I draghetti neri forniscono la Scaglia di Draghetto dei Sotterranei. Dimorano sulle rupi e sulle colline rocciose a sud di Borgolago, nelle Montagne Crestarossa. Le scaglie si possono raccogliere anche dai draghetti più sviluppati, come Snarlflare.",al={"chi rilascia le underbelly whelp scales","dove trovare le scaglie di cucciolo di drago","come trovare le scaglie di cucciolo di drago"}},{q="Perché Verner Osgood vuole queste scaglie?",a="Verner Osgood ha un debito con Argus, il fabbro di Borgodoro, per una spedizione di ferri di cavallo importati. Argus accetta scaglie di drago come pagamento, e quelle in più forniscono a Verner il materiale per realizzare equipaggiamento protettivo resistente.",al={"perché verner ha bisogno delle scaglie","verner osgood underbelly scales"}},{q="Perché le scaglie del ventre sono preferite alle normali scaglie di drago?",a="Le scaglie del ventre dei giovani draghi sono abbastanza flessibili da poter essere tagliate, modellate e cucite per realizzare armature funzionali o equipaggiamento rinforzato. Le scaglie dorsali sono spesso troppo rigide, spesse o deformate per le normali tecniche di lavorazione del cuoio e di forgiatura.",al={"perché del ventre","cosa rende speciali le underbelly scales"}},{q="Perché ci sono cuccioli di drago nero a Crestarossa?",a="Lo Stormo dei Draghi Neri ha mantenuto una presenza tra le vette ardenti e i dirupi lungo i confini delle Steppe Ardenti e delle Montagne Crestarossa. I suoi draghetti nidificano e crescono sulle alte rupi difficili da raggiungere.",al={"perché ci sono draghi a crestarossa","cuccioli neri crestarossa"}}},fx={["4599dc10"]={q="Che cos'è una Scaglia di Draghetto dei Sotterranei?",a="Sono scaglie morbide ricavate dal ventre dei cuccioli di drago nero che si aggirano nelle regioni meridionali di Altomaglio. A differenza delle piastre rigide e impenetrabili che ricoprono il dorso di un drago adulto, le scaglie del ventre di un giovane draghetto sono straordinariamente resistenti e abbastanza flessibili da poter essere lavorate da artigiani esperti, il che le rende un materiale molto ricercato.",al={"che cosa sono le scaglie dei draghetti dei sotterranei","oggetto scaglia di draghetto dei sotterranei","storia delle scaglie dei draghetti"}}},fp="22,168,22.404.0,13.408.0,43.205.0,41.205.0,63.226.0,47.189.0"}
P.entries["item:unidentified-ore"] = {n="Minerale Sconosciuto",s="Nella Landa di Tagliavento, il Minerale Sconosciuto ha attirato l'attenzione della S.P.R. & Co. Piznik ne ha recuperato un campione e lo ha consegnato a Ziz Fizziks perché fosse studiato a Undermine.",h="Nella Landa di Tagliavento, il Minerale Sconosciuto ha attirato l'attenzione della S.P.R.",kw={"piznik","vetta di petrartiglio","undermine","minerale sconosciuto","s.p.r. & co.","landa di tagliavento","ziz fizziks"},ang={["profession:Engineering"]="La tecnologia goblin ricerca composti grezzi dalle proprietà reattive uniche. I minerali non classificati provenienti da dirupi selvaggi offrono agli inventori più innovativi materiale da studiare.",["profession:Mining"]="I minatori trovano filoni comuni in tutta la Landa di Tagliavento, ma questo campione sfugge alle conoscenze consuete del mestiere. Persino i migliori periti di Undermine ne sono incuriositi."},sec={{t="Un curioso filone a Tagliavento",b="La S.P.R. & Co. ha portato alla luce insoliti strati minerali nelle Vette di Petrartiglio con il disboscamento e l'estrazione a cielo aperto nella Landa di Tagliavento. Il suo nuovo capo, Gerenzo Wrenchwhistle, ha ordinato di estrarre grandi quantità di uno strano minerale verde-oro.\n\nIl lavoratore goblin Piznik, retrocesso di grado, è rimasto fedele al suo ex capo licenziato, Ziz Fizziks. Si è procurato un campione mentre pianificava la fuga dalla compagnia, poi lo ha consegnato a un viaggiatore diretto alla cresta occidentale della landa. Ziz intende inviare la maggior parte del minerale a Undermine perché venga studiato e tenerne una piccola parte per sé."}},faq={{q="Cos'è il Minerale Sconosciuto?",a="I minatori della S.P.R. & Co. hanno estratto il Minerale Sconosciuto nella Landa di Tagliavento. La sua composizione interessa Ziz Fizziks e gli ingegneri minerari di Undermine.",al={"cos'è questo minerale","storia del minerale sconosciuto","che roccia è questa"}},{q="Chi ha trovato il minerale?",a="Piznik, un goblin della S.P.R. & Co. di stanza nella Landa di Tagliavento, ha recuperato il campione. Dopo alcuni recenti incidenti, temeva una punizione da parte dei supervisori della compagnia e ha visto un'occasione per fuggire e trovare un nuovo lavoro.",al={"chi lo ha dissotterrato","chi consegna il minerale","minerale di piznik"}},{q="Chi sta cercando di studiare questo campione?",a="Ziz Fizziks, un goblin accampato lungo il margine occidentale della Landa di Tagliavento, ha ricevuto il minerale. Intende inviarne la maggior parte agli ingegneri di Undermine e tenerne una piccola porzione per sé.",al={"chi vuole il minerale","chi lo analizza","minerale di ziz fizziks"}},{q="Perché questa pietra interessa a Undermine?",a="I goblin cercano nuovi materiali esplosivi, metallurgici o combustibili. Uno strano minerale proveniente dalle antiche montagne di Kalimdor potrebbe avere un valore industriale e commerciale per i cartelli mercantili.",al={"interesse di undermine","perché i goblin lo vogliono"}}},fx={["4673b3b7"]={q="Da dove proviene il Minerale Sconosciuto?",a="Il campione proviene dalla miniera della S.P.R. & Co. sulla Landa di Tagliavento, nelle Vette di Petrartiglio, dove il nuovo capo del sito, Gerenzo Wrenchwhistle, ha ordinato di estrarre grandi quantità di uno strano minerale verde-oro. Piznik, ancora fedele al suo ex capo Ziz Fizziks, licenziato di recente, ha estratto di nascosto un campione perché potesse essere portato a Ziz.",al={"origine del minerale sconosciuto","dove è stato trovato il minerale sconosciuto","da dove proveniva il minerale"}}},fp="16,155,29.531.0,29.142.0,18.194.0,35.184.0,41.192.0"}
P.entries["item:unrefined-ore-sample"] = {n="Campione di Minerale Grezzo",s="A Millepicchi, l'Orda cerca un campione di minerale insolito. Tatternack Forgiacciaio vuole scoprire se può rafforzare gli eserciti del Capoguerra Thrall.",h="A Millepicchi, l'Orda cerca un campione di minerale insolito.",kw={"camp taurajo","gibblesnik","gravelsnout","coboldo","minerale","tatternack forgiacciaio","millepicchi","campione di minerale grezzo"},ang={["faction:Horde"]="Come membro dell'Orda, sai che ogni nuovo filone minerario nel Kalimdor meridionale potrebbe aiutare la giovane nazione di Thrall a produrre le proprie armi mentre mette al sicuro i suoi confini.",["profession:Blacksmithing"]="Come fabbro, puoi capire la frustrazione di Tatternack. Mettere alla prova la resistenza e la durevolezza di un nuovo minerale aiuta i fabbri a equipaggiare i guerrieri con lame che non si spezzeranno in combattimento."},sec={{t="Estratto dai parassiti",b="A sud delle Savane, i coboldi Gravelsnout scavano sotto le pareti dei canyon di Millepicchi. Alcuni viaggiatori di ritorno a nord hanno trovato un minerale curioso tra i parassiti uccisi. Era diverso da quelli dei consueti filoni di Kalimdor. Si sono rifiutati di cedere la loro scoperta all'Orda. I coboldi che scavano ed esplorano le profondità trasportano blocchi grezzi provenienti dai loro scavi."},{t="Forgiare per il Capoguerra",b="A Camp Taurajo, il forgiatore d'armi Tatternack Forgiacciaio lavora agli ordini del Capoguerra Thrall per migliorare gli armamenti dell'Orda. I viaggiatori che conoscevano il giacimento lo hanno fatto infuriare rifiutandosi di condividerne il minerale. Ha visto il loro rifiuto come un insulto allo sforzo bellico dell'Orda. Con un campione grezzo, Tatternack intende mettere alla prova la resistenza e la tempra del minerale. Poi lo fonderà e forgerà una lama prototipo da sottoporre all'approvazione di Orgrimmar."}},faq={{q="Da dove proviene questo minerale grezzo?",a="I coboldi Gravelsnout trasportano il minerale dalle profondità dei canyon di Millepicchi, a sud delle Savane. I loro scavatori, i loro periti e il loro capo Gibblesnik vivono lì.",al={"posizione del minerale","dove trovare il campione di minerale grezzo","chi rilascia il minerale grezzo"}},{q="Perché Tatternack Forgiacciaio vuole un campione?",a="Tatternack lavora agli ordini del Capoguerra per migliorare le armi dell'Orda. Vuole esaminare e fondere il minerale per scoprire se può essere forgiato in armi più resistenti.",al={"perché tatternack vuole il minerale","scopo minerale taurajo","a cosa serve il minerale"}},{q="Perché i viaggiatori erano riluttanti a separarsene?",a="Alcuni viaggiatori dell'Orda provenienti da Millepicchi hanno trovato il minerale su un coboldo e lo hanno tenuto come trofeo o curiosità. Si sono rifiutati di venderlo, anche quando è stato chiesto loro di contribuire al lavoro dei fabbri dell'Orda.",al={"chi erano i viaggiatori","viaggiatori minerale savane"}},{q="Questo minerale si trova da qualche parte nelle Savane?",a="No. Camp Taurajo si trova nelle Savane Meridionali, ma il minerale va recuperato dai coboldi più a sud, a Millepicchi.",al={"minerale nelle savane","si può estrarre nelle savane"}}},fx={["5c1fb5e1"]={q="Che cos'è un Campione di Minerale Grezzo?",a="È un pezzo di minerale insolito e grezzo, estratto dalla terra dai koboldi di Millepicchi. A differenza dei filoni comuni lavorati in tutte le Savane, questo minerale sconosciuto attira l'attenzione dei fabbri per la sua potenziale resistenza, anche se prima di poter giudicare se sia adatto alla forgiatura deve essere fuso e studiato a dovere.",al={"che cos'è un campione di minerale grezzo","campione di minerale grezzo","che cos'è il campione di minerale"}}},fp="20,150,19.333.0,24.399.0,40.159.0,45.162.0,49.189.0,42.124.0"}
P.entries["item:ur-s-treatise-on-shadow-magic"] = {n="Trattato di Ur sull'Ombra",s="Un tempo i maghi di Roccavento custodivano il Trattato di Ur sull'Ombra, temendo ciò che le sue pagine avrebbero potuto scatenare. Ora il tomo giace nascosto nella Torre di Ilgalar, rubato da Morganth.",h="Un tempo i maghi di Roccavento custodivano il Trattato di Ur sull'Ombra, temendo ciò che le sue pagine...",kw={"andromath","dalaran","ilgalar","morganth","crestarossa","santuario","shadow magic","tomo","trattato","ur"},ang={["class:Mage"]="Come mago di Roccavento, contribuisci a tenere al sicuro il trattato e a preservare la sicurezza del Santuario dopo che uno dei suoi membri ha ceduto a oscure tentazioni.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, sai che la presenza di Morganth a Redridge minaccia la frontiera orientale del regno. Recuperare il potente artefatto è importante per la sicurezza di Roccavento."},sec={{t="Una pericolosa eredità",b="Ur di Dalaran scrisse della Shadow Magic e della sua natura subdola e corruttrice. I maghi del Santuario della Magia di Roccavento temevano che queste arti potessero condannare gli incauti, così sigillarono il volume per impedirne la lettura. Dopo essersi abbandonato alle arti oscure ed essere stato esiliato dal circolo magico di Roccavento, Morganth portò il tomo a est, nelle Montagne Crestarossa. Lì stabilì la propria roccaforte nella Torre di Ilgalar."},{t="I segreti protetti dai sigilli",b="High Sorcerer Andromath temeva che Morganth potesse padroneggiare le oscure conoscenze contenute nell'opera di Ur. Inviò degli avventurieri nella Torre di Ilgalar per recuperarla. Morganth era sprofondato nella magia proibita, eppure i sigilli protettivi posti dal circolo di Roccavento resistevano saldamente. Il libro rimase chiuso fino al suo recupero."}},faq={{q="Chi era Ur?",a="Ur era uno stimato mago e studioso di Dalaran. Studiava le creature extraplanari, le arti oscure e la magia esoterica, comprese le arti dell'ombra.",al={"chi ha scritto questo libro","ur di dalaran","chi è ur"}},{q="Perché il trattato è così pericoloso?",a="La Shadow Magic può corrompere chi la pratica senza un'adeguata preparazione e portare sventura e rovina. High Sorcerer Andromath mette in guardia dall'esplorarne le profondità proibite.",al={"perché il libro è pericoloso","cosa fa il libro","pericolo shadow magic"}},{q="Chi ha rubato il Trattato di Ur sull'Ombra?",a="Morganth rubò il tomo dopo che l'ordine dei maghi di Roccavento lo ebbe bandito per aver ceduto alla magia oscura. Fuggì a est, verso la Torre di Ilgalar a Redridge.",al={"chi ha rubato il libro","morganth libro rubato","chi ha preso il trattato"}},{q="Morganth è riuscito a leggere il trattato?",a="No. I maghi di Roccavento sigillarono il tomo e le loro protezioni ressero. Morganth non riuscì ad aprirlo prima che venisse recuperato.",al={"morganth lo ha letto","i sigilli hanno retto","il libro è stato aperto"}},{q="Si tratta della stessa opera di Il Libro di Ur?",a="Entrambe le opere sono di Ur e sono strettamente collegate. Il Libro di Ur è un grimorio più ampio, custodito tra le rovine del Forte di Zannascura. Il Treatise on Shadow Magic sembra essere un estratto o un volume specialistico dedicato alle arti dell'ombra.",al={"differenza libro di ur","libro di ur zannascura","è questo il libro di ur"}}},fx={["9d095b57"]={q="Perché qualcuno vuole il Trattato di Ur sull'Ombra?",a="Gli adepti sedotti dai poteri oscuri cercano il trattato per i suoi formidabili segreti arcani e dell'Ombra. Il mago rinnegato Morganth lo ha rubato per accrescere il proprio potere occulto, mentre High Sorcerer Andromath e i maghi di Roccavento ne reclamano con urgenza la restituzione, affinché i sigilli restino intatti e i suoi pericoli al sicuro.",al={"perché vogliono il trattato","perché i maghi vogliono il trattato di ur","perché morganth vuole il trattato"}},["9052da59"]={q="Che cos'è il Trattato di Ur sull'Ombra?",a="È un tomo potente e sorvegliato che descrive i misteri proibiti della magia dell'ombra. Custodito sotto incantesimi protettivi dai maghi del Santuario della Magia a Roccavento, il libro contiene potenti conoscenze occulte che, se liberate, potrebbero portare sventura e rovina su chiunque fosse così avventato da studiarlo.",al={"che cos'è il trattato di ur","trattato di ur sull'ombra","che cos'è il trattato sull'ombra"}},["0481e4cc"]={q="Da dove proviene il Trattato di Ur sull'Ombra e chi l'ha scritto?",a="Il libro è stato scritto dal talentuoso mago del Kirin Tor Ur di Dalaran, uno studioso che si è dedicato allo studio delle arti oscure, delle entità ultraterrene e della magia dell'ombra. I suoi pericolosi scritti sono infine giunti a Roccavento, dove i maghi della città hanno sigillato il trattato per tenere i suoi segreti lontani dagli inesperti.",al={"chi ha scritto il trattato di ur","da dove proveniva il trattato di ur","origine del trattato di ur sull'ombra"}}},fp="29,167,18.397.0,18.299.1,11.140.0,33.143.0,40.147.0,41.113.1,40.218.0"}
P.entries["item:urgent-message"] = {n="Messaggio Urgente",s="Il Guerriero Corno Lunare avverte il Presidio di Ventolibero che le incursioni dei centauri aumentano in tutta Millepicchi. I viaggiatori e le strade sono in pericolo.",h="Il Guerriero Corno Lunare avverte il Presidio di Ventolibero che le incursioni dei centauri aumentano in...",kw={"guerriero corno lunare","centauro","cliffwatcher longhorn","presidio di ventolibero","grande ascensore","totem truce","millepicchi","messaggio urgente"},ang={["faction:Horde"]="Il Messaggio Urgente mostra quanto siano fragili le linee di rifornimento dell'Orda attraverso Kalimdor meridionale. Gli avamposti isolati si affidano a messaggeri e guerrieri per attraversare terre ostili.",["race:Tauren"]="Per i tauren, la lettera richiama l'antica faida di sangue con i centauri e la crescente inquietudine nei confronti dei loro consanguinei Totem Truce."},sec={{t="Un avvertimento dall'alto",b="Nei pressi del Grande Ascensore che dalle Savane conduce a Millepicchi, il Guerriero Corno Lunare scrive il Messaggio Urgente. Da lì, Corno Lunare sorveglia i canyon frastagliati sottostanti, mentre le tribù di centauri riprendono le incursioni contro i viaggiatori dell'Orda.\n\nLa lettera è destinata a Cliffwatcher Longhorn, in cima al Presidio di Ventolibero. Corno Lunare avverte che gli assalitori si sono fatti più audaci e colpiscono vicino a strade importanti. La guarnigione deve prepararsi ad altri scontri e tenere d'occhio l'imprevedibile clan Totem Truce."},{t="Spargimento di sangue sul fondo del canyon",b="Al Presidio di Ventolibero, il Messaggio Urgente conferma i timori di Cliffwatcher Longhorn. I predoni centauri hanno teso un'imboscata a una carovana di rifornimenti che attraversava il fondo del canyon e massacrato tutti i suoi membri. Non si tratta soltanto di una scaramuccia di confine.\n\nI capi tauren rispondono con contrattacchi organizzati contro le tribù. Cercano di fermare le incursioni prima che il Presidio di Ventolibero venga isolato dal resto di Kalimdor."}},faq={{q="Cosa c'è scritto nel Messaggio Urgente?",a="Il Messaggio Urgente avverte che le incursioni dei centauri aumentano rapidamente in tutta Millepicchi. I viaggiatori e le strade sono in pericolo immediato, e il Presidio di Ventolibero deve prepararsi alla guerra.",al={"cosa dice la lettera","contenuto del messaggio urgente","di cosa parla il messaggio"}},{q="Chi ha scritto questo messaggio e chi lo riceve?",a="Il Guerriero Corno Lunare scrisse il Messaggio Urgente vicino al Grande Ascensore provenendo dalle Savane e lo indirizzò a Cliffwatcher Longhorn, comandante del Presidio di Ventolibero.",al={"chi ha scritto il messaggio urgente","mittente del messaggio urgente","chi riceve il messaggio urgente"}},{q="Perché i centauri attaccano le carovane di rifornimenti?",a="Le tribù di centauri si contendono da tempo con i tauren le terre aride di Kalimdor centrale. Assaltano le carovane sul fondo del canyon per impadronirsi delle provviste e impedire all'Orda di attraversare Millepicchi in sicurezza.",al={"perché i centauri attaccano","motivo centauri millepicchi","perché i centauri compiono incursioni"}},{q="Quale avvertimento dà l'esploratore riguardo ai Totem Truce?",a="Il Guerriero Corno Lunare avverte il corriere di evitare il vicino clan Totem Truce. I suoi guerrieri sono diventati distaccati e diffidenti nei confronti degli altri tauren.",al={"avvertimento sui totem truce","perché evitare i totem truce","totem truce si comportano in modo strano"}}},fx={d8ee5ef2={q="Cos'è il Messaggio Urgente?",a="Il Messaggio Urgente è una missiva sigillata scritta da Guerriero Corno Lunare vicino al confine dei Millepicchi. Riferisce di un allarmante aumento dell'aggressività dei centauri sul fondo del canyon, mettendo in guardia le autorità tauren dal pericolo crescente che minaccia viaggiatori e linee di rifornimento nella regione.",al={"cos'è il messaggio urgente","oggetto messaggio urgente","missiva urgente"}},["1e5b60e5"]={q="Perché il Messaggio Urgente serve al Presidio di Ventolibero?",a="Cliffwatcher Longhorn sovrintende alla difesa del Presidio di Ventolibero e ha bisogno di informazioni immediate sui movimenti nemici. La missiva lo avverte che i predoni centauri hanno intensificato le incursioni, consentendogli di agire con decisione prima che altre carovane di rifornimenti e pattuglie vengano tese in imboscata e massacrate.",al={"perché consegnare il messaggio urgente","chi ha bisogno del messaggio urgente","messaggio per cliffwatcher longhorn"}}},fp="14,129,26.447.0,29.376.1,38.166.0,43.143.0,46.207.0,57.134.0"}
P.entries["item:valdred-s-hands"] = {n="Mani di Valdred",s="Nel sud di Selva Pinargento, le mani recise di Valdred Moray sono ricercate come prova di vendetta. Raleigh Andrean le vuole come macabro trofeo per l'omicidio di sua moglie.",h="Nel sud di Selva Pinargento, le mani recise di Valdred Moray sono ricercate come prova di vendetta.",kw={"a husband's revenge","deliah","muro dei mantogrigio","raleigh andrean","selva pinargento","valdred","valdred moray","mani di valdred"},ang={["race:Undead"]="Essendo uno dei Reietti, Raleigh non può vivere un vero lutto, eppure cerca ancora vendetta per Deliah."},sec={{t="Un Macabro Trofeo di Tradimento",b="La piaga pose fine all'amicizia tra Valdred Moray e Raleigh Andrean. Valdred aveva ucciso Deliah, la moglie di Raleigh. Raleigh morì e risorse come uno dei Reietti, credendo di non poter più vivere un vero lutto. Eppure la vendetta contava ancora per lui. Quando Valdred fuggì a sud oltre il Muro dei Mantogrigio verso Gilneas, Raleigh mandò un emissario sulle tracce del suo ex amico. Pretese le mani recise di Valdred come prova che l'atto fosse stato compiuto."},{t="Un Amaro Ricordo",b="Raleigh Andrean rinuncia all'Anello Inciso di Deliah quando riceve le mani di Valdred, definendo l'anello privo di significato. Deliah è morta per lui da così tanto tempo che i ricordi non gli danno conforto. Conserva le mani come un freddo ricordo del tradimento e della vendetta."}},faq={{q="Chi era Valdred Moray?",a="Valdred Moray era un tempo un caro amico di Raleigh Andrean. Tradì quell'amicizia uccidendo Deliah, la moglie di Raleigh, poi tentò di fuggire a sud verso Gilneas.",al={"chi è valdred","storia di valdred moray","storia di valdred"}},{q="Perché Raleigh Andrean vuole specificamente le mani di Valdred?",a="Raleigh vuole le mani di Valdred perché furono gli strumenti che strangolarono o colpirono a morte sua moglie. Le conserva come trofeo tangibile del tradimento del suo amico e della vendetta che si è preso.",al={"perché le mani","perché le mani di valdred","trofeo mani raleigh"}},{q="Dove si trova Valdred Moray?",a="Valdred si trova nel sud di Selva Pinargento, vicino al Muro dei Mantogrigio, e cerca di fuggire a Gilneas.",al={"dove si trova valdred","posizione di valdred","generazione di valdred moray"}},{q="Che ne è delle mani dopo averle portate a Sepulcra?",a="Raleigh conserva le mani a Sepulcra come ricordo duraturo della sua vendetta. Si disfa anche dell'Anello Inciso di Deliah, considerandolo privo di significato.",al={"cosa fa raleigh con le mani","consegnare mani di valdred"}}},fx={["1f1d5250"]={q="Cosa sono le Mani di Valdred?",a="Sono le mani mozzate di Valdred Moray, prese come prova della sua morte e come macabro trofeo di vendetta. Un tempo Valdred era un fidato amico di Raleigh Andrean, prima di tradirlo e assassinare sua moglie, Deliah. Ora le estremità mozzate rappresentano il compimento tangibile della tormentata ricerca di vendetta di Raleigh.",al={"oggetto mani di valdred","cosa sono le mani di valdred","mani di valdred"}},ba2ecc3a={q="Da dove provengono le Mani di Valdred?",a="Sono state mozzate direttamente dal corpo di Valdred Moray. Nel disperato tentativo di fuggire dagli Abbandonati e sottrarsi alla punizione per i suoi crimini, Valdred si è ritirato a sud attraverso la Selva Pinargento, verso il Muro dei Mantogrigio, sperando di riuscire a entrare nel regno murato di Gilneas prima che il suo cacciatore lo raggiungesse.",al={"origine delle mani di valdred","chi ha le mani di valdred","da dove provengono le mani di valdred"}}},fp="15,165,29.426.0,20.251.1,22.165.0,59.192.0,29.95.0,59.138.1"}
P.entries["item:velinde-s-journal"] = {n="Diario di Velinde",s="A Darnassus, il diario di Velinde Starsong documenta i suoi doveri e il mistero della sua partenza. Il diario della sacerdotessa di razza Elfo della Notte è custodito nell'alloggio delle Sentinelle.",h="A Darnassus, il diario di Velinde Starsong documenta i suoi doveri e il mistero della sua partenza.",kw={"darnassus","sentinelle","thyn'tel plasmalame","terrazza dei mercanti","velinde starsong","diario di velinde","chiave di velinde","baule di velinde"},ang={["class:Priest"]="Come sacerdote, potresti vedere nel dovere segreto e nella scomparsa di Velinde i segni di prove inquietanti per la Sisterhood of Elune.",["race:NightElf"]="In quanto Elfo della Notte, la misteriosa partenza di Velinde preoccupa i vertici di Darnassus. Le Sentinelle che sorvegliano la capitale dei Kaldorei sono turbate."},sec={{t="La cronaca di una sacerdotessa",b="Quando la sacerdotessa di razza Elfo della Notte Velinde Starsong lasciò Darnassus, le Sentinelle chiusero i suoi averi in un baule nel loro alloggio sulla Terrazza dei Mercanti. Tra questi c'era il suo diario personale, che documentava le sue responsabilità e i suoi doveri. Le Sentinelle rispettavano Velinde e credevano che fosse partita per occuparsi di questioni private. Ma le sue parole suggeriscono che la sua assenza le preoccupi più di quanto avessero inizialmente pensato."}},faq={{q="Dove si trova il Diario di Velinde?",a="Il Diario di Velinde si trova nel suo baule nell'alloggio delle Sentinelle, sulla Terrazza dei Mercanti di Darnassus. Attraversa il ponte superiore collegato al negozio di armature di maglia per raggiungere l'edificio.",al={"posizione del diario","dove si trova il diario di velinde","posizione del baule di velinde"}},{q="Chi era Velinde Starsong?",a="Velinde Starsong era una stimata sacerdotessa di razza Elfo della Notte di cui le Sentinelle si fidavano profondamente. Lasciò Darnassus all'improvviso e senza clamore, lasciando lì il suo baule e i suoi averi.",al={"chi è velinde","storia di velinde"}},{q="Perché le Sentinelle si interessano al suo diario?",a="Le Sentinelle credevano che Velinde avesse lasciato Darnassus per validi motivi personali e si aspettavano il suo ritorno. I suoi scritti suggeriscono risvolti più oscuri dietro la sua scomparsa, e le Sentinelle devono indagare più a fondo.",al={"perché le sentinelle vogliono il diario","cosa c'è nel diario"}},{q="Chi ti chiede di recuperare il diario?",a="La Sentinella Thyn'tel Plasmalame a Darnassus ti concede il permesso e ti dà la chiave del baule di Velinde. Prima, presentati con le conoscenze apprese dal Tome of Mel'Thandris.",al={"chi dà la missione","chi è thyn'tel plasmalame"}}},fx={["654b265d"]={q="Cos'è il Diario di Velinde?",a="Il Diario di Velinde è un resoconto dei doveri e delle vicende personali tenuto dalla sacerdotessa elfa della notte Velinde Starsong. Dopo la sua improvvisa partenza, è stato custodito tra i suoi effetti personali nella caserma delle Sentinelle a Darnassus e contiene l'unica testimonianza superstite delle sue attività prima della scomparsa.",al={"cos'è il diario di velinde","diario di velinde","chi ha scritto il diario"}},["07b3d22b"]={q="Da dove proviene il Diario di Velinde e chi l'ha scritto?",a="Il diario è stato scritto dalla stessa sacerdotessa Velinde Starsong durante il suo servizio presso gli elfi della notte. Dopo la sua misteriosa assenza, i suoi effetti personali sono stati raccolti e chiusi in un forziere negli alloggi delle Sentinelle a Darnassus, in attesa di qualsiasi indizio che potesse spiegare la sua partenza.",al={"chi ha scritto il diario di velinde","origine del diario di velinde","da dove proviene il diario di velinde"}}},fp="17,160,20.402.0,33.179.0,25.172.0,44.215.0,37.172.0"}
P.entries["item:velinde-s-key"] = {n="Chiave di Velinde",s="A Darnassus, Thyn'tel Plasmalame custodisce la Chiave di Velinde per chi cerca di scoprire il destino della sacerdotessa scomparsa. Tiene al sicuro i suoi scritti e i suoi averi.",h="A Darnassus, Thyn'tel Plasmalame custodisce la Chiave di Velinde per chi cerca di scoprire il destino della...",kw={"darnassus","armadietto","caserma delle sentinelle","thyn'tel plasmalame","velinde starsong","velinde's effects","diario di velinde","chiave di velinde"},ang={["class:Priest"]="Come sacerdote, segui le tracce di una devota sorella di Elune il cui cammino prese una svolta solitaria e inquietante.",["race:NightElf"]="Come Elfo della Notte, maneggi gli averi di una rispettata sacerdotessa la cui lealtà a Elune e al suo popolo era indiscussa."},sec={{t="Un pegno di fiducia",b="Thyn'tel Plasmalame custodisce la Chiave di Velinde a Darnassus. La semplice chiave apre un baule contenente gli effetti personali della Sacerdotessa Velinde Starsong. Si trova nella caserma delle Sentinelle sopra la Terrazza dei Mercanti. Velinde lasciò le terre degli Elfi della Notte senza preavviso, così i suoi averi furono messi da parte. Plasmalame presta la chiave solo a chi dimostra un sincero interesse per il suo destino, per esempio attraverso le rivelazioni del Tome of Mel'Thandris."},{t="Aprire il passato",b="La chiave di Velinde Starsong apre il suo baule, dove il diario riporta i suoi doveri e i suoi pensieri tormentati. Le Sentinelle credettero a lungo che fosse partita per questioni personali e che un giorno sarebbe tornata. I suoi scritti iniziano a svelare un mistero più oscuro attorno alla spedizione che la portò lontano."}},faq={{q="Cosa apre la Chiave di Velinde?",a="La Chiave di Velinde apre Velinde's Locker, un baule nella caserma delle Sentinelle a Darnassus. Si trova al piano superiore, oltre un ponte nella Terrazza dei Mercanti.",al={"dove usare la chiave di velinde","armadietto di velinde","quale baule apre questa chiave"}},{q="Chi ti dà la chiave?",a="Thyn'tel Plasmalame, una Sentinella di Darnassus, ti affida la chiave mentre indaghi sulla scomparsa di Velinde.",al={"chi ha la chiave di velinde","dove ottenere la chiave di velinde"}},{q="Chi è Velinde Starsong?",a="Velinde Starsong era una rispettata sacerdotessa degli Elfi della Notte che godeva della fiducia delle Sentinelle. Partì all'improvviso per questioni personali e lasciò i suoi averi a Darnassus.",al={"chi è velinde","storia di velinde"}},{q="Cosa si trova all'interno del suo baule chiuso a chiave?",a="Il Diario di Velinde si trova all'interno del baule. Riporta i suoi doveri e fa luce su ciò che la spinse a lasciare le terre degli Elfi della Notte.",al={"cosa c'è nell'armadietto di velinde","contenuto dell'armadietto di velinde"}}},fx={["7f8c7b68"]={q="Cos'è la Chiave di Velinde?",a="La Chiave di Velinde apre il baule che custodisce gli effetti personali della sacerdotessa Velinde Starsong. Affidata alle Sentinelle di Darnassus dopo la sua improvvisa partenza, è custodita da Thyn'tel Plasmalame per proteggere gli averi privati della sacerdotessa scomparsa nella caserma delle Sentinelle.",al={"chiave di velinde","cos'è la chiave di velinde","chiave del baule di velinde"}},["927d5f5e"]={q="Perché serve la Chiave di Velinde?",a="Ti serve la chiave per aprire il baule di Velinde nella caserma delle Sentinelle. Dopo aver appreso di lei dal Tomo di Mel'Thandris, esaminare i suoi effetti personali, in particolare il suo diario, offre le migliori possibilità di scoprire perché la venerata sacerdotessa sia scomparsa e dove l'abbiano condotta i suoi doveri.",al={"perché mi serve la chiave di velinde","perché vogliono la chiave di velinde","scopo della chiave di velinde"}}},fp="13,143,15.439.0,18.280.1,29.155.0,22.116.0,24.161.0,38.128.0"}
P.entries["item:venomtail-antidote"] = {n="Antidoto ai Codavenefica",s="A Durotar, Rhinag giace colpito dal veleno di uno scorpide, e il tempo stringe. Kor'ghan prepara l'antidoto a Orgrimmar per l'esploratore vicino al confine nord-occidentale.",h="A Durotar, Rhinag giace colpito dal veleno di uno scorpide, e il tempo stringe.",kw={"antidoto","spelonca delle ombre","cura","durotar","kor'ghan","orgrimmar","rhinag","scorpide","codavenefica"},ang={["faction:Horde"]="Come membro dell'Orda, affronti lo spietato deserto di Durotar. Salvare Rhinag richiede un rapido coordinamento tra gli esploratori delle terre selvagge e gli speziali della città.",["race:Troll"]="Come troll, sai quanto sia radicato l'orgoglio. Rhinag preferirebbe rischiare di morire solo nelle terre desolate piuttosto che subire aperte derisioni al Villaggio di Sen'jin per essere stato sconfitto da uno scorpide."},sec={{t="Una corsa contro il veleno",b="Una puntura profonda degli scorpidi codavenefica di Durotar può uccidere un guerriero nel giro di un'ora. Rhinag, un esploratore troll, è stato avvelenato vicino al confine nord-occidentale, lontano da ogni aiuto. La sua unica speranza è un rimedio di Kor'ghan, uno speziale nella Spelonca delle Ombre di Orgrimmar."},{t="La cura di Kor'ghan",b="Kor'ghan lavora sotto Orgrimmar, dove conosce le tossine del deserto e i rimedi drastici. Prepara una fiala per eliminare il veleno prima che diventi letale. La pozione neutralizza il veleno e risparmia a Rhinag una morte umiliante nelle terre selvagge. Ciononostante, Kor'ghan esige che l'esploratore affronti altre prove e battute di caccia per espiare la sua imprudenza."}},faq={{q="A cosa serve l'Antidoto ai Codavenefica?",a="L'Antidoto ai Codavenefica contrasta il veleno mortale degli scorpidi codavenefica. Rhinag, un troll avvelenato vicino al confine nord-occidentale di Durotar, ne ha bisogno prima che il veleno lo uccida.",al={"scopo dell'antidoto","chi ha bisogno dell'antidoto ai codavenefica","cosa fa l'antidoto ai codavenefica"}},{q="Chi prepara l'Antidoto ai Codavenefica?",a="Kor'ghan prepara l'antidoto nella Spelonca delle Ombre, sotto Orgrimmar. Conosce le tossine degli scorpidi di Durotar e sa come contrastare gli effetti delle loro punture.",al={"chi crea l'antidoto","dove trovare l'antidoto ai codavenefica","antidoto di kor'ghan"}},{q="Perché il tempo è così fondamentale per ottenere l'antidoto?",a="Il veleno dei codavenefica può uccidere Rhinag entro un'ora dalla puntura. Devi procurarti l'antidoto e attraversare in fretta Durotar per riportarglielo e salvargli la vita.",al={"perché affrettarsi con l'antidoto","quanto tempo ha rhinag","tempo del veleno di codavenefica"}},{q="Perché Rhinag esita a cercare aiuto al Villaggio di Sen'jin?",a="Rhinag si vergogna di essere stato sopraffatto da un comune scorpide. Teme che la sua gente al Villaggio di Sen'jin derida la sua imprudenza e stupidità se torna indebolito.",al={"perché non andare a sen'jin","orgoglio di rhinag","perché nascondersi a durotar"}}},fx={ba1b91bb={q="Cos'è l'Antidoto ai Codavenefica?",a="L'Antidoto ai Codavenefica è una mistura specifica creata per neutralizzare il veleno letale degli scorpidi codavenefica di Durotar. Senza di esso, chiunque venga punto a fondo da queste bestie aggressive va incontro a una morte rapida e agonizzante, mentre la tossina si diffonde nel sangue.",al={"cos'è l'antidoto ai codavenefica","informazioni sull'antidoto ai codavenefica","cura per i codavenefica"}}},fp="18,162,24.249.0,15.326.0,40.168.0,33.136.0,52.140.0,55.158.0"}
P.entries["item:venomtail-poison-sac"] = {n="Sacca di Veleno di Codavenefica",s="A Durotar, il veleno di uno scorpione può ridurre un cacciatore in fin di vita, e la sua sacca velenifera contiene ciò che serve agli alchimisti per una cura.",h="A Durotar, il veleno di uno scorpione può ridurre un cacciatore in fin di vita, e la sua sacca velenifera...",kw={"antidoto","durotar","kor'ghan","veleno","rhinag","sacca","scorpione","codavenefica"},ang={["class:Hunter"]="Come cacciatore, prendi la sventura di Rhinag come un monito. Inseguire bestie pericolose senza conoscerne il veleno o portare con sé un rimedio può costarti la vita.",["faction:Horde"]="Come giovane avventuriero dell'Orda a Durotar, impari che le tossine locali possono uccidere chi si precipita impreparato nelle rosse distese desolate."},sec={{t="Una tossina letale e il suo rimedio",b="Gli scorpidi si aggirano tra i Massi Rossi di Durotar. I Venomtail Scorpids, i Corrupted Scorpids e il Death Flayer hanno tutti sacche piene di veleno ad azione rapida. Senza cure, il veleno può sopraffare persino i guerrieri più esperti. Eppure quelle stesse sacche contengono i composti principali necessari agli alchimisti per un antidoto.\n\nQuando uno scorpione punse il cacciatore Rhinag fuori da Orgrimmar, agli alchimisti locali servirono quattro sacche velenifere fresche. Le avrebbero usate per preparare un rimedio e neutralizzare il veleno nelle sue vene."}},faq={{q="Quali creature trasportano queste sacche di veleno?",a="Gli scorpidi di Durotar possiedono queste sacche velenifere, soprattutto i Venomtail Scorpids nei pressi di Orgrimmar. Anche i Corrupted Scorpids e il raro Death Flayer le possiedono.",al={"chi rilascia sacca di veleno di codavenefica","dove trovare sacca di veleno di codavenefica","quali scorpioni hanno sacche di veleno"}},{q="A cosa serve la sacca di veleno?",a="Kor'ghan, a Orgrimmar, usa le sacche per distillare un antidoto specifico. Rhinag ne ha bisogno dopo essere stato punto e avvelenato mentre cacciava senza essersi preparato a dovere.",al={"uso sacca codavenefica","perché serve sacca di veleno di codavenefica"}},{q="Chi può preparare l'antidoto da queste sacche?",a="Kor'ghan, a Orgrimmar, può raffinare il veleno grezzo di quattro sacche intatte per ricavarne una pozione curativa. Deve farlo prima che il veleno risulti fatale.",al={"chi prepara l'antidoto","dove consegnare le sacche di codavenefica","kor'ghan codavenefica"}}},fx={["7ee9d5ba"]={q="Cos'è una Sacca di Veleno di Codavenefica?",a="La Sacca di Veleno di Codavenefica è l'organo che produce il veleno, estratto dagli scorpidi pericolosi che infestano Durotar, soprattutto da quelli codavenefica in agguato vicino alle Gates of Orgrimmar. Il fluido al suo interno contiene una tossina eccezionalmente potente e rapida, che rende queste creature una minaccia mortale per i cacciatori imprudenti che si avventurano nelle aride distese rosse.",al={"cos'è la sacca di veleno di codavenefica","storia della sacca di veleno di codavenefica","informazioni sulla sacca di codavenefica"}},c7932c21={q="Da dove proviene una Sacca di Veleno di Codavenefica?",a="Queste sacche vengono estratte direttamente dagli scorpidi nativi delle aspre pianure di Durotar, tra cui gli scorpidi codavenefica, gli scorpidi corrotti e gli sventratori della morte. Sono organi anatomici naturali delle bestie, riserve biologiche sviluppate dagli scorpidi per sopraffare le prede e difendersi dai predatori nella desolata landa inospitale.",al={"da dove provengono le sacche di veleno di codavenefica","chi lascia cadere la sacca di codavenefica","origine della sacca di veleno di codavenefica"}}},fp="20,119,29.470.0,39.152.0,32.159.0,42.137.0"}
P.entries["item:venture-co-documents"] = {n="Documenti della S.P.R. & Co.",s="Nel Mulgore orientale, i Documenti della S.P.R. & Co. svelano le attività minerarie illegali della compagnia nelle terre dei tauren. Recuperati da una cassa in una carovana distrutta, ne documentano le operazioni.",h="Nel Mulgore orientale, i Documenti della S.P.R.",kw={"morin bracca nubi","estrazione mineraria a mulgore","carovana depredata","documenti della s.p.r. & co.","s.p.r. & co."},ang={["profession:Mining"]="Come minatore, puoi capire perché i campioni di minerale grezzo imballati accanto ai documenti siano importanti. Mostrano che ai piedi delle colline si trovano ricchi filoni ancora intatti, pronti per l'estrazione.",["race:Tauren"]="Come tauren, sai che i macchinari goblin profanano la terra sacra di Earth Mother. Questi documenti aiutano gli anziani a confermare l'entità della profanazione e a sferrare attacchi di rappresaglia."},sec={{t="Prove di sfruttamento",b="I Documenti della S.P.R. & Co. giacevano sopra del minerale estratto, in un carro saccheggiato. I registri mostrano che il cartello guidato dai goblin ha allestito avamposti di trivellazione ed estrazione ai piedi delle colline orientali di Mulgore. In tutta Kalimdor, la S.P.R. & Co. è nota per la deforestazione spietata e gli scavi incontrollati. Morin Bracca Nubi e gli Outrunners tauren studiano i registri sequestrati per valutare la minaccia alle loro sacre pianure ancestrali e radunare cacciatori contro gli intrusi."}},faq={{q="Cosa contengono i Documenti della S.P.R. & Co.?",a="I documenti descrivono in dettaglio le attività minerarie ed estrattive della S.P.R. & Co. nel Mulgore orientale. Mostrano come l'impresa goblin estragga e porti via le ricchezze minerarie della regione.",al={"contenuto documenti s.p.r. & co.","cosa sono i documenti della s.p.r. & co.","cosa c'e scritto nei documenti"}},{q="Dove sono stati scoperti questi documenti?",a="I documenti sono stati trovati in una cassa sigillata della S.P.R. & Co. tra i resti di un carro saccheggiato presso la Carovana Depredata, a est del Villaggio di Zoccolo Sanguinario.",al={"dove trovare i documenti","posizione documenti s.p.r. & co.","cassa della carovana depredata"}},{q="Chi ha bisogno di vedere questi documenti?",a="Porta i documenti a Morin Bracca Nubi, un cacciatore tauren di stanza lungo il sentiero principale a est del Villaggio di Zoccolo Sanguinario. Veglia sulla sicurezza di Mulgore.",al={"a chi portare i documenti","consegna documenti s.p.r. & co.","documenti di morin bracca nubi"}},{q="Perche la S.P.R. & Co. scava a Mulgore?",a="La S.P.R. & Co. estrae minerali per profitto, cercando ricchi filoni minerari e territori selvaggi da spogliare di minerali preziosi. Non ha alcun riguardo per i trattati con i nativi, le usanze spirituali o l'ambiente.",al={"perche i goblin sono a mulgore","obiettivo s.p.r. & co. a mulgore","perche la s.p.r. & co. scava"}}},fx={["33362eae"]={q="Da dove provengono i Documenti della S.P.R. & Co. e chi li ha scritti?",a="Queste carte riguardano le operazioni minerarie clandestine della S.P.R. & Co. nelle pendici orientali di Mulgore. Indirizzati al supervisore Fizsprocket per conto del consiglio consultivo della compagnia e del presidente Razdunk, i documenti erano stati sistemati sopra una cassa di minerale grezzo e minerali trovata vicino a una carovana saccheggiata, pronti per essere spediti insieme alle ricchezze rubate delle pianure.",al={"origine dei documenti della s.p.r. & co.","chi ha realizzato i documenti della s.p.r. & co.","da dove provengono i documenti della s.p.r. & co."}},f91b68fc={q="Perché Morin Bracca Nubi vuole i Documenti della S.P.R. & Co.?",a="I battipista tauren che proteggono Mulgore hanno bisogno di prove inconfutabili della presenza sempre più invadente della S.P.R. & Co. Morin Bracca Nubi ha bisogno di questi documenti per confermare la portata esatta dei piani minerari dei goblin e fornire ai difensori del Villaggio di Zoccolo Sanguinario le informazioni essenziali per fermare lo sfruttamento e il saccheggio delle loro terre ancestrali.",al={"perché morin vuole i documenti della s.p.r. & co.","perché conservare i documenti della s.p.r. & co.","chi vuole i documenti della s.p.r. & co."}}},fp="21,172,24.448.0,42.171.0,38.151.0,30.149.0,46.191.0"}
P.entries["item:venture-co-engineering-plans"] = {n="Piani di Ingegneria della S.P.R. & Co.",s="Nella Landa di Tagliavento, gli agenti dell'Alleanza cercano i Piani di Ingegneria della S.P.R. & Co. nella segheria dei goblin. Gli schemi mostrano come sono costruite le macchine da disboscamento.",h="Nella Landa di Tagliavento, gli agenti dell'Alleanza cercano i Piani di Ingegneria della S.P.R.",kw={"covert ops","lago di altarupe","piani di ingegneria","gaxim scoppiarame","vette di petrartiglio","s.p.r. & co.","landa di tagliavento"},ang={["profession:Engineering"]="Come ingegnere, puoi studiare le brutali macchine della S.P.R. & Co., voraci di risorse, per approfondire le tue conoscenze sui macchinari industriali pesanti.",["race:Gnome"]="Come inventore gnomo, impadronirti degli schemi dei goblin rivali offre una vittoria intellettuale e idee industriali da adattare."},sec={{t="Segreti industriali",b="A sud del Lago di Altarupe, nella segheria, i Piani di Ingegneria della S.P.R. & Co. rivelano come sono costruite le macchine per il legname. Mostrano i punti di forza e i difetti delle macchine. La S.P.R. & Co. le usa per spogliare le foreste di Petrartiglio, mentre il fumo incombe sulla Landa di Tagliavento."},{t="Spionaggio gnomesco",b="L'ingegnere gnomo Gaxim Scoppiarame dirige un'operazione segreta contro le attività di disboscamento della S.P.R. & Co. e cerca i piani. Gli esplosivi possono interrompere subito le attività della segheria. Gli schemi permettono anche agli artigiani dell'Alleanza di sfruttare i punti deboli dell'equipaggiamento dei goblin e adattarne i progetti per le opere dell'Alleanza."}},faq={{q="Dove si trovano i Piani di Ingegneria della S.P.R. & Co.?",a="I Piani di Ingegneria della S.P.R. & Co. si trovano nella segheria principale della S.P.R. & Co. nella Landa di Tagliavento, a sud del Lago di Altarupe, nelle Vette di Petrartiglio.",al={"dove trovare i piani di ingegneria","posizione piani vette di petrartiglio","dove sono i piani"}},{q="Chi vuole questi piani di ingegneria?",a="Gaxim Scoppiarame, uno gnomo dell'Alleanza che coordina azioni segrete nelle Vette di Petrartiglio, invia agenti a recuperare i piani.",al={"a chi servono i piani","a chi consegnare i piani di ingegneria","gaxim scoppiarame piani"}},{q="Perché questi schemi sono importanti per l'Alleanza?",a="Gli schemi rivelano i difetti dei macchinari da disboscamento della S.P.R. & Co., aiutando gli agenti a smantellarli. Forniscono inoltre agli gnomi dell'Alleanza progetti industriali da adattare alle loro invenzioni.",al={"perché rubare i piani","a cosa servono i piani"}},{q="Quale operazione è legata al furto di questi piani?",a="Recuperare i piani è l'obiettivo principale di Covert Ops - Alpha. Gli agenti piazzano anche detonatori in tutto il sito, e tornare con gli schemi segna il successo dell'operazione.",al={"obiettivo covert ops alpha","per quale missione serve"}}},fx={["605bae91"]={q="Cosa sono i Piani di Ingegneria della S.P.R. & Co.?",a="Questi documenti contengono schemi tecnici dettagliati e progetti realizzati dagli ingegneri della S.P.R. & Co. nelle Vette di Petrartiglio. Custoditi nella loro segheria vicino al Lago di Altarupe, illustrano la costruzione, il cablaggio e il funzionamento dei macchinari per la deforestazione e dei congegni industriali usati dalla compagnia per disboscare la Landa di Tagliavento.",al={"cosa sono i piani di ingegneria della s.p.r. & co.","piani di ingegneria della s.p.r. & co.","piani della s.p.r. & co."}},a84a85f7={q="Da dove provengono i Piani di Ingegneria della S.P.R. & Co.?",a="I piani provengono dalle attività industriali della S.P.R. & Co. nella Landa di Tagliavento. Elaborati dai loro stessi ingegneri e operatori per sovrintendere al disboscamento e alla costruzione dei macchinari, erano custoditi nella segheria principale appena a sud del Lago di Altarupe, prima di finire nel mirino degli agenti segreti dell'Alleanza.",al={"da dove provengono i piani di ingegneria","chi ha realizzato i piani di ingegneria della s.p.r. & co.","origine dei piani della s.p.r. & co."}}},fp="29,157,18.275.0,17.294.1,52.157.0,34.127.0,51.185.0,47.175.0"}
P.entries["item:venture-co-letters"] = {n="Lettere della S.P.R. & Co.",s="Alla Miniera di Tagliavento, le Lettere della S.P.R. & Co. riportano notizie sulle attività del cartello nelle Vette di Petrartiglio. Recuperate durante un'operazione segreta, forniscono alle Sentinelle degli Elfi della Notte informazioni sulle operazioni dei goblin.",h="Alla Miniera di Tagliavento, le Lettere della S.P.R.",kw={"kaela freccianera","sentinelle","vette di petrartiglio","s.p.r. & co.","lettere della s.p.r. & co.","landa di tagliavento","miniera di tagliavento"},ang={["faction:Alliance"]="Gli esploratori dell'Alleanza conducono operazioni segrete contro la S.P.R. & Co. per proteggere dallo sfruttamento industriale i possedimenti degli Elfi della Notte a Petrartiglio.",["race:NightElf"]="I macchinari dei goblin per il taglio del legname profanano le terre selvagge di Petrartiglio. Le informazioni sulle macchinazioni della S.P.R. & Co. sono di grande importanza per le Sentinelle."},sec={{t="Informazioni industriali",b="I macchinari della S.P.R. & Co. abbattono alberi e scavano miniere a cielo aperto nell'antico bosco attorno alla Landa di Tagliavento. Gli agenti dell'Alleanza compiono sabotaggi segreti per distrarre i lavoratori ed entrare nella Miniera di Tagliavento. Lì recuperano lettere contenenti messaggi privati e registri logistici delle attività locali della compagnia. I comandanti delle Sentinelle possono usarle per scoprire come i profanatori organizzano la propria forza lavoro e le linee di rifornimento."},{t="Consegna alle Sentinelle",b="Le lettere giungono dalle profondità della Miniera di Tagliavento a Kaela Freccianera, comandante delle Sentinelle. I profanatori goblin e le incursioni dell'Orda mettono sotto pressione le Sentinelle in tutta Petrartiglio. La corrispondenza rubata le aiuta ad anticipare le prossime mosse della S.P.R. & Co. e a proteggere ciò che resta delle montagne sacre."}},faq={{q="Cosa sono le Lettere della S.P.R. & Co.?",a="Le Lettere della S.P.R. & Co. sono corrispondenza interna e registri operativi custoditi dalla S.P.R. & Co. nella Miniera di Tagliavento, nelle Vette di Petrartiglio.",al={"lettere della s.p.r. & co.","cosa sono le lettere","lettere delle vette di petrartiglio"}},{q="Dove si trovano le lettere?",a="Le lettere si trovano tra i Documenti della S.P.R. & Co. all'interno della Miniera di Tagliavento, all'estremità orientale della Landa di Tagliavento.",al={"dove si trovano le lettere","posizione delle lettere","lettere della miniera di tagliavento"}},{q="Chi vuole queste lettere?",a="L'agente gnomo Gaxim Scoppiarame sovrintende all'operazione per rubare le lettere. Queste vengono consegnate a Kaela Freccianera, a capo delle Sentinelle degli Elfi della Notte della zona.",al={"chi riceve le lettere","chi le vuole","consegna delle lettere"}},{q="Perché le Sentinelle hanno bisogno di questa corrispondenza?",a="Le Sentinelle combattono per fermare la deforestazione e gli scavi a Petrartiglio. Le lettere rivelano i piani e le priorità della S.P.R. & Co., aiutando i difensori a pianificare le contromosse.",al={"perché le sentinelle vogliono le lettere","interesse delle sentinelle"}}},fx={["52f3029e"]={q="Da dove provengono le Lettere della S.P.R. & Co. e chi le ha scritte?",a="Questi documenti provengono dall'attività mineraria della S.P.R. & Co. presso la Miniera di Tagliavento, all'estremità orientale della Landa di Tagliavento. Si tratta di corrispondenza aziendale interna, custodita tra i documenti sul posto e scritta dagli operatori e dai supervisori regionali della compagnia per coordinare le aggressive attività di estrazione e disboscamento nelle Vette di Petrartiglio.",al={"origine delle lettere della s.p.r. & co.","chi ha scritto le lettere della s.p.r. & co.","da dove provengono le lettere"}}},fp="19,203,23.390.0,25.299.1,33.146.0,28.104.0,24.156.0,46.169.0"}
P.entries["item:verdant-note"] = {n="Nota Verdastra",s="A Campo Narache, la Nota Verdastra chiama i giovani druidi tauren all'addestramento. Inviata per conto di Gart Cavalca Nebbia, li guida verso i Rites of the Earthmother.",h="A Campo Narache, la Nota Verdastra chiama i giovani druidi tauren all'addestramento.",kw={"campo narache","druido","madre terra","gart cavalca nebbia","mulgore","mesa nuvola rossa","nota verdastra"},ang={["class:Druid"]="Per te che sei un druido, la Nota Verdastra segna l'ammissione agli studi druidici dei tauren e l'inizio della tua comunione permanente con la Madre Terra.",["race:Tauren"]="In quanto Shu'halo, il tuo druidismo è una vocazione ancestrale legata al ripristino dell'equilibrio dei tuoi sacri territori di caccia a Mulgore."},sec={{t="Una chiamata al sentiero",b="I giovani tauren dotati di un'affinità con la natura ricevono la Nota Verdastra poco dopo l'inizio delle loro prove a Mesa Nuvola Rossa. Un messaggero porta la breve convocazione di Gart Cavalca Nebbia a Campo Narache, dove ogni iniziato deve presentarsi al mentore. Spiriti irrequieti ed elementi mutevoli turbano Mulgore. Gli anziani hanno bisogno che nuovi druidi vengano addestrati in fretta."},{t="Insegnamenti della Madre Terra",b="A Campo Narache, Gart Cavalca Nebbia insegna agli iniziati a entrare in comunione con la natura. Li avverte che gli elfi della notte condividono un legame con la natura selvaggia, ma un antico orgoglio li tiene lontani dai tauren. Il druidismo dei tauren si fonda sulla venerazione della Madre Terra. Gli iniziati imparano ad ascoltare le irrequiete voci ancestrali della terra e a servire come suoi strumenti viventi."}},faq={{q="Cos'è la Nota Verdastra?",a="La Nota Verdastra chiama i druidi tauren alle prime armi a Campo Narache. Dice loro di cercare Gart Cavalca Nebbia e iniziare l'addestramento spirituale.",al={"oggetto nota verdastra","cos'è questa nota"}},{q="Chi invia la Nota Verdastra?",a="Un messaggero reca la Nota Verdastra per conto di Gart Cavalca Nebbia. Gart addestra i druidi a Campo Narache, a Mesa Nuvola Rossa.",al={"chi ha inviato la nota verdastra","chi ha scritto la nota verdastra"}},{q="Perché Gart Cavalca Nebbia chiama a sé gli iniziati druidi?",a="Spiriti ancestrali irrequieti turbano Mulgore e le regioni vicine. Gart ha bisogno che nuovi druidi vengano addestrati in fretta per comunicare con gli spiriti selvaggi e risanare la terra tormentata.",al={"perché gart mi vuole","motivo gart cavalca nebbia"}},{q="Cosa dice Gart ai druidi riguardo agli elfi della notte?",a="Gart avverte che gli elfi della notte condividono un legame sacro con la natura, ma il loro orgoglio rende improbabile che accolgano i tauren nei loro circoli. Esorta gli iniziati a seguire gli insegnamenti della Madre Terra.",al={"elfi della notte e tauren druidi","cosa riguarda gli elfi della notte"}}},fx={["59de7025"]={q="Perché Gart Cavalca Nebbia vuole che tu riceva la Nota Verdastra?",a="Gart Cavalca Nebbia ti invia la Nota Verdastra per convocarti al tuo addestramento da druido al Campo Narache. Spiriti inquieti si sono destati in tutta Mulgore e nelle terre circostanti, e Gart ha bisogno che nuovi iniziati imparino ad ascoltare la Madre Terra e gli spiriti della natura. La nota è un'urgente convocazione a farti avanti e ad abbracciare i tuoi doveri di incarnazione del mondo naturale.",al={"perché la nota verdastra","perché gart invia la nota","scopo della nota verdastra"}}},fp="12,152,18.314.0,28.334.0,25.133.0,27.115.0,51.162.0,53.197.0"}
P.entries["item:verdant-sigil"] = {n="Sigillo Verdastro",s="A Vallombra, Conservator Ilthalaine avvia i giovani druidi Elfi della Notte al loro addestramento con il Sigillo Verdastro.",h="A Vallombra, Conservator Ilthalaine avvia i giovani druidi Elfi della Notte al loro addestramento con il...",kw={"aldrassil","druido","sogno di smeraldo","ilthalaine","mardant aspraquercia","vallombra","teldrassil","sigillo verdastro"},ang={["class:Druid"]="Per te, giovane druido Elfo della Notte, il Sigillo Verdastro segna il primo rito di passaggio dalla semplice cura della foresta ai rigorosi insegnamenti Cenariani.",["race:NightElf"]="Sotto le fronde di Aldrassil, il sigillo rispecchia la tradizione kaldorei di sintonizzare il tuo spirito con il mondo naturale e i guardiani di Teldrassil."},sec={{t="Una Convocazione al Cammino",b="I giovani Elfi della Notte di Vallombra ricevono il Sigillo Verdastro quando sentono il Richiamo Selvaggio. Conservator Ilthalaine lo consegna loro con un messaggio di Mardant Aspraquercia, il loro istruttore dei druidi. Il messaggio invita i novizi a salire tra i rami di Aldrassil e a dedicarsi a studi approfonditi. Lì si lasciano alle spalle le mansioni di base per apprendere la comunione con gli spiriti della natura e i misteri del Sogno di Smeraldo."},{t="Il Primo Passo nel Sogno",b="Presentare il Sigillo Verdastro a Mardant Aspraquercia dà inizio all'arte che un giovane druido coltiverà per tutta la vita. I novizi non possono ancora percorrere la trance del sonno del Sogno di Smeraldo, ma il sigillo segna l'inizio del loro apprendistato. Sotto la guida di Mardant, imparano a interpretare i sussurri della natura selvaggia. Praticano anche le prime arti di mutaforma e di guarigione al servizio di Teldrassil."}},faq={{q="Qual è lo scopo del Sigillo Verdastro?",a="Il Sigillo Verdastro invita i druidi Elfi della Notte novizi di Vallombra a trovare Mardant Aspraquercia ad Aldrassil e iniziare l'addestramento formale.",al={"a cosa serve il sigillo verdastro","perché ho il sigillo verdastro","uso del sigillo verdastro"}},{q="Chi consegna il Sigillo Verdastro?",a="Conservator Ilthalaine consegna il Sigillo Verdastro agli aspiranti druidi di Vallombra con un messaggio di Mardant Aspraquercia.",al={"chi consegna il sigillo verdastro","dove si ottiene il sigillo verdastro"}},{q="Dove devo portare il sigillo una volta ricevuto?",a="Porti il Sigillo Verdastro a Mardant Aspraquercia, l'istruttore dei druidi nelle sale centrali di Aldrassil, nel cuore di Vallombra.",al={"dove portare il sigillo verdastro","chi accetta il sigillo verdastro","consegna del sigillo verdastro"}},{q="Cosa succede dopo aver presentato il sigillo a Mardant Aspraquercia?",a="Mardant accetta il Sigillo Verdastro e ti accoglie come suo allievo. Ti insegna la comunione con la natura e ti prepara ai misteri del Sogno di Smeraldo man mano che la tua forza cresce.",al={"cosa fa mardant con il sigillo","dopo il sigillo verdastro"}}},fx={e7925638={q="Cos'è il Sigillo Verdastro?",a="Il Sigillo Verdastro è un pegno inciso inviato dal maestro druido Mardant Aspraquercia ai giovani iniziati elfi della notte di Vallombra. Portato da un messaggero al conservatore Ilthalaine, serve da convocazione ufficiale e da segno di presentazione, invitando i novizi promettenti a salire sui rami di Aldrassil e iniziare l'istruzione nelle vie della natura e del Sogno di Smeraldo.",al={"cos'è il sigillo verdastro","oggetto sigillo verdastro","storia del sigillo verdastro"}},["1efc6d6b"]={q="Da dove proviene il Sigillo Verdastro e chi l'ha realizzato?",a="Il sigillo proviene da Mardant Aspraquercia, l'istruttore dei druidi stanziato tra i grandi rami di Aldrassil a Vallombra. Alla ricerca di novizi pronti a entrare in sintonia con la natura, Mardant ha inviato il pegno tramite un corriere al conservatore Ilthalaine, affinché raggiungesse i giovani druidi promettenti ai loro primi passi su Teldrassil.",al={"chi ha realizzato il sigillo verdastro","da dove proviene il sigillo verdastro","origine del sigillo verdastro"}},fa84d5c5={q="Perché qualcuno dovrebbe volere il Sigillo Verdastro?",a="Mardant Aspraquercia ti chiede di portargli il sigillo come prova della tua preparazione e della tua volontà di imparare. Accettando la convocazione e riportandolo al mentore, stabilisci con lui un legame formale e dimostri di essere pronto a studiare gli spiriti, padroneggiare la mutaforma ed esplorare i misteri del Sogno di Smeraldo.",al={"perché si vuole il sigillo verdastro","perché mardant vuole il sigillo verdastro","chi vuole il sigillo verdastro"}}},fp="13,125,21.397.0,29.362.0,41.129.0,32.117.0,44.127.0,61.183.0"}
P.entries["item:verna-s-westfall-stew-recipe"] = {n="Ricetta per lo Stufato delle Marche Occidentali di Verna",s="Mentre i Ciglioarcuato si preparano a lasciare la loro fattoria nelle Marche Occidentali, Verna manda la sua ricetta dello stufato a Salma Saldean. Il suo conforto familiare potrebbe restare per chi rimane.",h="Mentre i Ciglioarcuato si preparano a lasciare la loro fattoria nelle Marche Occidentali, Verna manda la sua...",kw={"cucina","ciglioarcuato","ricetta","fattoria dei saldean","salma saldean","verna ciglioarcuato","stufato delle marche occidentali"},ang={["faction:Alliance"]="Per l'Alleanza, la ricetta racconta di coloni fedeli scacciati dalle loro terre dal dilagare dell'illegalità, mentre Roccavento fatica a far valere la propria autorità.",["profession:Cooking"]="Per i cuochi, la ricetta manoscritta di Verna preserva il sapere locale mentre le fattorie delle Marche Occidentali cadono in rovina."},sec={{t="Un regalo d'addio",b="Verna e il Contadino Ciglioarcuato vivono nelle Marche Occidentali da anni. Ora la Fratellanza dei Defias e i golem mietitori fuori controllo imperversano nelle campagne. I Ciglioarcuato aspettano che il loro carro venga riparato per poter fuggire verso Roccavento.\n\nNell'attesa, Verna mette per iscritto la sua amata ricetta dello Stufato delle Marche Occidentali. La affida a viaggiatori diretti dalla sua amica e vicina, Salma Saldean. Così, chi resta potrà ancora trovare il conforto familiare dello stufato."}},faq={{q="Perché Verna sta donando la sua ricetta dello stufato?",a="Verna e il Contadino Ciglioarcuato fuggono dalle Marche Occidentali perché banditi e macchine fuori controllo hanno invaso i loro campi. Mentre lasciano la fattoria, Verna spera che la sua amica Salma Saldean continui a preparare lo stufato per chi rimane.",al={"perché verna dona la ricetta","perché la ricetta dello stufato delle marche occidentali","scopo della ricetta di verna"}},{q="A chi è destinata la ricetta?",a="La ricetta di Verna è destinata a Salma Saldean, che vive poco oltre il bivio, alla Saldean Farm.",al={"a chi va la ricetta","a chi porto la ricetta","dove va la ricetta dello stufato"}},{q="Dove hanno intenzione di andare i Ciglioarcuato?",a="I Ciglioarcuato aspettano che il loro carro venga riparato per poter fuggire a Roccavento. Cercano riparo dal caos e dal brigantaggio che minacciano le campagne.",al={"dove vanno i ciglioarcuato","dove va verna","destinazione dei ciglioarcuato"}},{q="Cosa rende lo Stufato delle Marche Occidentali una specialità della regione?",a="Lo Stufato delle Marche Occidentali è un alimento tipico della regione, preparato con i prodotti dell'agricoltura e la selvaggina locali. Con il cibo che scarseggia e le fattorie abbandonate, le sue sostanziose ricette aiutano le famiglie contadine rimaste a resistere.",al={"cos'è lo stufato delle marche occidentali","perché lo stufato delle marche occidentali è importante","storia dello stufato delle marche occidentali"}}},fx={["39bb19d7"]={q="Cos'è la Ricetta per lo Stufato delle Marche Occidentali di Verna?",a="È una guida culinaria scritta a mano da Verna Ciglioarcuato, che descrive gli ingredienti e la preparazione necessari per realizzare un sostanzioso Westfall Stew. Per evitare che il suo piatto tipico locale vada perduto quando abbandona la sua pericolosa terra natale, Verna annota le istruzioni su una pergamena, così che il suo vicino possa continuare a sfamare viaggiatori e abitanti del luogo.",al={"ricetta dello stufato di verna","cos'è la ricetta per lo stufato delle marche occidentali di verna","oggetto ricetta per lo stufato delle marche occidentali di verna"}},b68c02b6={q="Da dove viene la Ricetta per lo Stufato delle Marche Occidentali di Verna e chi l'ha scritta?",a="La ricetta è stata annotata da Verna Ciglioarcuato proprio nella fattoria dei Ciglioarcuato, nel nord delle Marche Occidentali. Di fronte ai continui attacchi dei Banditi Defias e delle bestie in cerca di cibo, l'ha scritta di suo pugno poco prima di caricare il carro della famiglia per fuggire dalla campagna.",al={"chi ha scritto la ricetta dello stufato di verna","origine della ricetta di verna","da dove viene la ricetta dello stufato di verna"}}},fp="28,152,15.463.0,41.219.0,28.106.0,39.167.0,47.172.0"}
P.entries["item:verner-s-note"] = {n="Nota di Verner",s="A Crestarossa, Verner Osgood invia una richiesta scritta a ovest, al Fabbro Argus di Borgodoro. Segnala la carenza di ferro di Borgolago e chiede ferri di cavallo da Elwynn.",h="A Crestarossa, Verner Osgood invia una richiesta scritta a ovest, al Fabbro Argus di Borgodoro.",kw={"borgodoro","ferri di cavallo","borgolago","montagne crestarossa","fabbro argus","the price of shoes","verner osgood","nota di verner"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere le difficoltà degli insediamenti rurali di Roccavento. Borgolago deve collaborare con i villaggi dell'entroterra per mantenere attive le proprie linee di rifornimento.",["profession:Blacksmithing"]="Come fabbro, puoi vedere come la guerra di frontiera consumi le scorte. Con ogni lingotto destinato ad armi e armature, Borgolago deve procurarsi il necessario per ferrare i cavalli da insediamenti più sicuri come Borgodoro."},sec={{t="Una richiesta di ferro",b="La difesa di Borgolago ha consumato quasi tutto il ferro di Verner Osgood. Il fabbro della città ha speso le sue riserve per armare e corazzare la Guardia di Roccavento, messa a dura prova dagli gnoll invasori e dai pericoli locali. Nel frattempo, le stalle sono state trascurate e le loro cavalcature mancano persino dei più semplici ferri di cavallo. Verner chiede al Fabbro Argus di Borgodoro di inviare da Elwynn ferri già pronti, così che Borgolago possa ferrare i propri cavalli."}},faq={{q="Cosa c'è scritto nella Nota di Verner?",a="La Nota di Verner informa il Fabbro Argus che Verner ha speso quasi tutte le sue riserve di ferro per armare e corazzare la Guardia di Roccavento a Borgolago. Non avendo più ferro per i ferri di cavallo, chiede ad Argus di inviarli da Borgodoro.",al={"contenuto della nota di verner","cosa dice la nota","messaggio della nota di verner"}},{q="Chi è Verner Osgood?",a="Verner Osgood è il fabbro che lavora a Borgolago, nelle Montagne Crestarossa. Equipaggia i difensori della città, mantiene in efficienza gli attrezzi da lavoro e ferra gli animali.",al={"chi e verner","verner osgood crestarossa"}},{q="Chi riceve questa nota?",a="La nota viaggia verso ovest lungo la strada fino al Fabbro Argus, il fabbro fuori dalla fucina di Borgodoro, nella Foresta di Elwynn.",al={"chi riceve la nota di verner","dove portare la nota","chi e il fabbro argus"}},{q="Perché Verner non può fabbricare i ferri da solo?",a="Verner ha usato le sue riserve di ferro per forgiare armi ed effettuare riparazioni per la Guardia di Roccavento, che affronta gnoll e altri pericoli locali. Non resta quindi ferro per i ferri di cavallo.",al={"perche borgolago ha bisogno di ferri","perche mandare a borgodoro per i ferri"}}},fx={["486dfee9"]={q="Cos'è la Nota di Verner?",a="È una lettera scritta a mano dal fabbro locale di Borgolago, Verner Osgood, e destinata al Fabbro Argus a Borgodoro. Nella lettera si spiega che la forgia di Borgolago ha esaurito le riserve di ferro per equipaggiare le Guardie di Roccavento locali contro le crescenti minacce della regione, e che non resta ferro per fabbricare ferri per i cavalli della stalla cittadina. È una richiesta ufficiale affinché Argus invii una cassa di ferri di cavallo in aiuto.",al={"nota di verner","cos'è questa nota","scopo della nota di verner"}},b8effef9={q="Da dove viene la Nota di Verner e chi l'ha scritta?",a="La nota è stata scritta direttamente da Verner Osgood nella sua fucina a Borgolago, nelle Montagne Crestarossa. Messo a dura prova dalle continue richieste di armare le guardie della città, assediata dagli gnoll e dagli orchi circostanti, Verner ha redatto la lettera per organizzare una spedizione urgente di rifornimenti dal suo collega fabbro nella Foresta di Elwynn.",al={"chi ha scritto la nota di verner","da dove viene la nota di verner","origine della nota di verner"}},c0af4e8d={q="Perché qualcuno dovrebbe volere la Nota di Verner?",a="Nella nota Verner Osgood spiega al Fabbro Argus di essere a corto di ferro e gli chiede di prestargli cinquanta paia di ferri di cavallo finché non arriverà la prossima spedizione di ferro. Consegnandola, permetti ad Argus di aiutare le stalle di Borgolago.",al={"perché argus vuole la nota di verner","chi ha bisogno della nota di verner","perché consegnare la nota di verner"}}},fp="13,162,15.401.0,33.213.0,21.151.0,23.114.0,45.164.0"}
P.entries["item:verog-s-head"] = {n="Testa di Verog",s="Regthar Deathgate cerca la Testa di Verog come prova della caduta del capo Kolkar. Verog comanda le forze attorno all'Oasi Stagnante, e la sua sconfitta mira a indebolire le tribù che minacciano le Savane.",h="Regthar Deathgate cerca la Testa di Verog come prova della caduta del capo Kolkar.",kw={"savane","centauro","kolkar","regthar deathgate","oasi stagnante","verog","verog il derviscio","testa di verog"},ang={["faction:Horde"]="Sconfiggere Verog e prendere la sua testa contribuisce a proteggere dalle incursioni dei centauri le vie dell'Orda tra il Crocevia e le Savane meridionali.",["race:Tauren"]="Come tauren, conosci il peso della sconfitta dei Kolkar. Il tuo popolo ha sopportato generazioni di guerre brutali contro le tribù di centauri di Kalimdor."},sec={{t="Un trofeo dell'oasi",b="I Kolkar minacciano i viaggiatori dell'Orda e le vie di rifornimento nelle Savane settentrionali. Verog the Dervish vaga per l'arida boscaglia, lasciando vulnerabile la sua tenda di comando all'Oasi Stagnante. Gli agenti dell'Orda attaccano le sue forze attorno al padiglione finché non risuona un allarme.\n\nVerog accorre per difendere il suo accampamento, dove viene ucciso e decapitato. Regthar Deathgate riceve la sua testa come prova della caduta di un altro pericoloso capotribù Kolkar. La testa di Barak Kodobane è già esposta accanto alla sua."}},faq={{q="Chi era Verog the Dervish?",a="Verog the Dervish era un signore della guerra dei centauri Kolkar di stanza all'Oasi Stagnante, nelle Savane. Vagava per le aride pianure e comandava le forze ostili attorno alla tenda dell'oasi.",al={"chi è verog","storia di verog","verog il derviscio"}},{q="Chi vuole la testa di Verog?",a="Regthar Deathgate, un orco veterano in un accampamento a ovest del Crocevia, vuole la testa di Verog. Raccoglie trofei dai signori della guerra Kolkar uccisi per indebolire le loro bande da guerra e minarne il morale.",al={"chi prende la testa di verog","regthar deathgate verog","consegnare la testa di verog"}},{q="Dove si trova Verog?",a="L'accampamento e la tenda di comando di Verog si trovano all'Oasi Stagnante, a sud-est del Crocevia. Torna a difendere la sua postazione quando le guardie centaure vengono uccise e viene dato l'allarme.",al={"dove si trova verog","posizione di verog","tenda dell oasi stagnante"}},{q="Cosa succede alla testa dopo che è stata consegnata?",a="Regthar Deathgate colloca la testa di Verog accanto a quella di Barak Kodobane. Le teste segnano la campagna dell'Orda contro i capi Kolkar.",al={"cosa fa regthar con la testa","esposizione teste di centauro"}}},fx={f5f2a432={q="Cos'è la Testa di Verog?",a="È la testa mozzata di Verog il Derviscio, uno dei più importanti capi centauri Kolkar che operano dall'Oasi Stagnante. È una macabra prova fisica della sua morte, portata alla guarnigione dell'Orda a ovest del Crocevia per rassicurarla che la minaccia rappresentata da questo sfuggente comandante è stata eliminata una volta per tutte.",al={"oggetto testa di verog","cos'è la testa di verog"}},["7da1755c"]={q="Da dove viene la Testa di Verog?",a="La testa viene presa direttamente da Verog il Derviscio. Il nomade capo dei Kolkar vaga per le pianure di The Barrens, ma quando il suo accampamento all'Oasi Stagnante viene attaccato, torna a difendere la sua tenda di comando, permettendoti di ucciderlo e prendere la sua testa come trofeo.",al={"da dove viene la testa di verog","chi lascia cadere la testa di verog"}}},fp="12,199,21.488.0,26.172.0,23.179.0,21.175.0,47.122.0"}
P.entries["item:vial-of-innocent-blood"] = {n="Fiala di Sangue Innocente",s="Tra le rovine di Forte Durnholde, i maghi dell'ombra della Lega dei Tagliagole raccolgono la Fiala di Sangue Innocente. La Società degli Speziali Reali a Mulino di Tarren la cerca come catalizzatore per tossine sperimentali.",h="Tra le rovine di Forte Durnholde, i maghi dell'ombra della Lega dei Tagliagole raccolgono la Fiala di Sangue...",kw={"speziale lydon","forte durnholde","alture di colletorto","sangue innocente","mago dell'ombra della lega dei tagliagole","mulino di tarren","fiala di sangue innocente"},ang={["faction:Horde"]="Come membro dell'Orda, procurandoti questo reagente contribuisci ai suoi sforzi contro il disboscamento della S.P.R. & Co. a Stonetalon.",["race:Undead"]="Come non morto, sai che la Società degli Speziali Reali usa ingredienti moralmente discutibili, raccogliendoli dai fuorilegge umani per far progredire la propria alchimia."},sec={{t="Un reagente raccapricciante",b="I maghi dell'ombra della Lega dei Tagliagole raccolgono sangue innocente tra le rovine di Forte Durnholde. I nobili umani decaduti della Lega dei Tagliagole praticano arti oscure tra le mura diroccate. A Mulino di Tarren, lo Speziale Lydon cerca sangue incontaminato per un agente pacificatore sperimentale. Intende usarlo contro la S.P.R. & Co. nelle Vette di Petrartiglio, e le scorte della Lega dei Tagliagole offrono una comoda fonte."}},faq={{q="A cosa serve la Fiala di Sangue Innocente?",a="Lo Speziale Lydon a Mulino di Tarren usa il sangue per preparare una tossina destinata a sopprimere l'aggressività degli operatori della S.P.R. & Co. che creano problemi all'Orda nelle Vette di Petrartiglio.",al={"uso del sangue innocente","a cosa serve la fiala di sangue innocente","uso del sangue degli innocenti"}},{q="Chi trasporta queste fiale?",a="I maghi dell'ombra della Lega dei Tagliagole trasportano le fiale attraverso la fortezza in rovina di Forte Durnholde, nella parte sudorientale delle Alture di Colletorto.",al={"chi rilascia la fiala di sangue innocente","dove trovare il sangue innocente","maghi dell'ombra della lega dei tagliagole"}},{q="Perché i maghi dell'ombra della Lega dei Tagliagole hanno sangue innocente?",a="I briganti umani e i nobili decaduti della Lega dei Tagliagole impiegano incantatori dell'ombra per raccogliere e conservare sangue innocente destinato a oscuri esperimenti magici.",al={"perché la lega dei tagliagole ha del sangue","rituali di sangue della lega dei tagliagole"}},{q="Perché lo Speziale Lydon ha bisogno di sangue di innocenti?",a="Lydon afferma che il sangue innocente possiede rare proprietà necessarie a creare un preparato che priva le vittime della loro violenza e le rende docili.",al={"perché il sangue innocente","sangue speziale lydon"}}},fx={["21111c2c"]={q="Cos'è la Fiala di Sangue Innocente?",a="È una piccola fiala che contiene sangue prelevato da vittime innocenti, molto apprezzato come potente reagente da incantatori oscuri e alchimisti. Invece di raccoglierlo con mezzi onorevoli o ordinari, viene sottratto appositamente per alimentare rituali insidiosi e potenti preparati chimici.",al={"cos'è la fiala di sangue innocente","storia della fiala di sangue innocente","cos'è questo sangue"}}},fp="22,177,18.379.0,44.168.0,24.125.0,50.139.0,52.135.0"}
P.entries["item:vial-of-phlogiston"] = {n="Fiala di Flogisto",s="Alle Gallerie di Lamaspina, il flogisto attira i fabbri dell'Alleanza e dell'Orda. I maestri armaioli lo usano per temprare cotte di maglia destinate a guerrieri promettenti, mentre i verrospino lo custodiscono nella loro roccaforte.",h="Alle Gallerie di Lamaspina, il flogisto attira i fabbri dell'Alleanza e dell'Orda.",kw={"brutal armor","fire hardened mail","furen barbalunga","flogisto","gallerie di lamaspina","roogug","thun'grim firegaze","fiala di flogisto"},ang={["class:Warrior"]="Come guerriero, recuperare il flogisto è un passo essenziale per ottenere un'iconica armatura temprata. Dimostra che sei in grado di penetrare nelle Gallerie di Lamaspina.",["profession:Blacksmithing"]="Come fabbro, conosci il flogisto come un fondente essenziale per la metallurgia specializzata, usato per temprare leggendarie maglie a piastre."},sec={{t="Essenza della Forgia",b="Il flogisto racchiude un fuoco volatile e trova impiego nella metallurgia esoterica. Furen Barbalunga, un fabbro nano di Roccavento, ne ha bisogno, così come Thun'grim Firegaze, un armaiolo orco quasi cieco delle Savane. Entrambi lo usano per indurire le armature dei guerrieri oltre i normali limiti fisici. Senza questo agente alchemico, nessuno dei due può completare la forgiatura specializzata della Fire Hardened Mail o della Brutal Armor dell'Orda."},{t="Recuperata dai Rovi",b="Una fiala di flogisto si trova nelle profondità delle Gallerie di Lamaspina, tra i grovigli di rovi all'estremità meridionale delle Savane. Il geomante Roogug la custodisce nella ridotta irta di spine. Che sia destinata a Furen a Roccavento o all'incudine di Thun'grim oltre le distese polverose, raggiungerla significa affrontare una pericolosa discesa nel territorio ostile dei verrospino."}},faq={{q="A cosa serve il flogisto?",a="I maestri fabbri usano il flogisto come catalizzatore alchemico per la tempra. Il suo calore concentrato tempra maglie grezze e ferro, trasformandoli in armature da guerriero eccezionalmente resistenti.",al={"uso fiala di flogisto","cosa fa il flogisto","perché serve il flogisto"}},{q="Chi custodisce la Fiala di Flogisto?",a="Roogug, un geomante verrospino, porta con sé la fiala nelle profondità dei cunicoli spinosi delle Gallerie di Lamaspina, nella parte meridionale delle Savane.",al={"chi rilascia la fiala di flogisto","bottino fiala di flogisto","dove trovare la fiala di flogisto"}},{q="Quali fabbri richiedono questo materiale?",a="Furen Barbalunga a Roccavento e Thun'grim Firegaze nelle Savane hanno entrambi bisogno del flogisto per forgiare armature temprate uniche per guerrieri esperti.",al={"chi vuole la fiala di flogisto","missione flogisto","quali missioni richiedono il flogisto"}}},fx={["3ab06e7f"]={q="Cos'è la Fiala di Flogisto?",a="La Fiala di Flogisto contiene una sostanza alchemica eccezionalmente rara, rinomata tra i maestri armaioli per il suo calore intenso e le sue proprietà di tempra. Molto ricercata da fabbri specializzati sia dell'Alleanza che dell'Orda, questa essenza infuocata è un catalizzatore fondamentale per forgiare armature di maglia resistenti e temprate, adatte a guerrieri esperti.",al={"cos'è la fiala di flogisto","storia del flogisto","oggetto fiala di flogisto"}}},fp="18,178,20.391.0,27.322.0,28.155.0,35.121.0,35.148.0"}
P.entries["item:vial-of-purest-water"] = {n="Fiala d'Acqua Purissima",s="Nelle Savane Meridionali, Brine benedice acqua pura per un iniziato sciamano. A Islen Scruta Lagune serve per preparare un sapta dell'acqua che permette all'iniziato di vedere gli spiriti elementali.",h="Nelle Savane Meridionali, Brine benedice acqua pura per un iniziato sciamano.",kw={"savane","brine","call of water","islen scruta lagune","selva pinargento","fiala d'acqua purissima","sapta dell'acqua"},ang={["class:Shaman"]="Come sciamano, consegnare quest'acqua purificata ti porta attraverso gli ultimi passi per comunicare con gli spiriti dell'acqua e ottenere il tuo Water Totem.",["faction:Horde"]="Come sciamano dell'Orda, attraversi Kalimdor e i Regni Orientali durante le prove legate alla fiala, rafforzando il tuo legame con gli elementi."},sec={{t="Un'offerta purificata",b="Brine guida l'iniziato attraverso prove di pazienza e purificazione, poi sigilla l'acqua nella fiala. La sua purezza è intatta, priva di corruzione. Portala attraverso le Savane fino a Islen Scruta Lagune, che veglia su una riva solitaria. Le serve per preparare un sapta dell'acqua, perché solo un'acqua tanto pura permette a uno sciamano di comunicare con i guardiani spirituali lontano dalle pianure arse dal sole."},{t="La via per il Totem dell'Acqua",b="Islen Scruta Lagune usa l'acqua benedetta per mettere alla prova la dedizione dell'iniziato e aprire i suoi sensi agli elementi nascosti. Ne mescola una parte in un sapta, che rivela gli spiriti presso un lontano santuario nella Selva Pinargento. Conserva le gocce rimanenti per affrontare e purificare una manifestazione ribelle altrove. Con la fiala, l'iniziato si lascia alle spalle le umili mansioni e affronta direttamente le realtà elementali."}},faq={{q="A cosa serve la Fiala d'Acqua Purissima?",a="La fiala contiene acqua purificata e benedetta per un iniziato sciamano. Islen Scruta Lagune la usa per preparare un sapta dell'acqua, che dona la vista spirituale necessaria a percepire gli elementali dell'acqua. Usa l'acqua anche in ulteriori prove rituali necessarie per ottenere il Water Totem.",al={"scopo della fiala d'acqua purissima","cosa fa la fiala","uso dell'acqua purissima"}},{q="Chi prepara l'acqua all'interno della fiala?",a="Lo sciamano raccoglie l'acqua sotto la guida di Brine. Brine è una sciamana orca che vive da eremita nel cuore delle Savane Meridionali. Dopo le prove dell'iniziato, Brine benedice l'acqua purificata e la sigilla nella fiala per il trasporto.",al={"chi ha creato la fiala","chi riempie la fiala","acqua di brine"}},{q="Dove deve essere portata la fiala?",a="Porta la fiala a Islen Scruta Lagune sulla costa orientale delle Savane, poco a sud di Porto Paranco, affacciata sul Great Sea.",al={"a chi do la fiala","dove consegnare la fiala","consegnare l'acqua purissima"}},{q="Dove conduce il rituale dopo la consegna della fiala?",a="Dopo aver ricevuto la fiala e preparato il sapta, Islen Scruta Lagune manda lo sciamano al di là del mare, nei Regni Orientali. Il santuario si trova nella Selva Pinargento, a sud di Sepulcra.",al={"dove vado adesso","passo successivo dopo la fiala","santuario dell'acqua di selva pinargento"}}},fx={["3774bd18"]={q="Cos'è la Fiala d'Acqua Purissima?",a="La Fiala d'Acqua Purissima è un recipiente sacro che contiene liquido incontaminato, benedetto e preparato dall'oracolo delle acque Brine. Affidata agli sciamani in formazione, contiene acqua raccolta da fonti pure in tutta la regione e purificata tramite un rituale per sintonizzarti con gli spiriti dell'acqua.",al={"fiala d'acqua purissima","cos'è la fiala d'acqua purissima"}},["273b8475"]={q="Perché Islen Scruta Lagune vuole la Fiala d'Acqua Purissima?",a="Islen Scruta Lagune ha bisogno dell'acqua benedetta contenuta nella fiala per preparare una Water Sapta per te. Bere questa pozione speciale ti conferisce la vista spirituale e ti permette di comunicare direttamente con i Water Elementals presso il loro santuario nella Selva Pinargento.",al={"perché islen vuole la fiala","perché serve la fiala d'acqua purissima","scopo della fiala d'acqua purissima"}}},fp="20,168,19.366.0,23.393.1,42.260.0,39.216.0,37.119.0,53.182.0"}
P.entries["item:vial-of-spider-venom"] = {n="Fiala di Veleno di Ragno",s="A Boscovespro, Dama Eva raccoglie il veleno dei ragni per creare una protezione contro gli aggressori. Le serve insieme a resti di non morti per un Totem del Castigo.",h="A Boscovespro, Dama Eva raccoglie il veleno dei ragni per creare una protezione contro gli aggressori.",kw={"borgoscuro","boscovespro","dama eva","naraxis","recluse","veleno di ragno","totem del castigo","fiala di veleno di ragno"},ang={["class:Rogue"]="Come ladro, puoi preparare veleni e applicarli alle lame. Questo veleno di ragno grezzo è destinato alla protezione mistica anziché all'assassinio diretto.",["faction:Alliance"]="Come avventuriero dell'Alleanza sulle strade ombrose di Boscovespro, puoi aiutare Dama Eva a creare totem protettivi per i viaggiatori che affrontano gli orrori dei boschi."},sec={{t="La minaccia velenosa di Boscovespro",b="I boschetti di Boscovespro ospitano ragni velenosi, dai pygmy venom webs e green recluses fino alle vedove nere e a Naraxis. Le loro zanne contengono un veleno abbastanza potente da paralizzare i viaggiatori e decomporre la carne. Chi uccide i ragni può estrarre il liquido e raccoglierlo in fiale intatte."},{t="Creare il Totem del Castigo",b="A Borgoscuro, la chiromante Dama Eva scorge presagi sinistri per i viaggiatori che si avventurano nel mondo oscuro. Le servono cinque fiale di veleno di ragno, zanne di ghoul e dita di scheletro per creare una protezione punitiva. La sua arte rivolge la natura corrosiva del veleno contro gli aggressori. Il Totem del Castigo ritorce il danno contro chiunque colpisca il suo portatore."}},faq={{q="Da dove proviene questo veleno di ragno?",a="I ragni predatori di Boscovespro contengono questo veleno. Tra loro ci sono Venom Web Spiders, Carrion Recluses, Green Recluses, Black Widow Hatchlings e la mostruosa madre della covata Naraxis.",al={"fonte del veleno di ragno","chi rilascia il veleno di ragno","dove trovare il veleno di ragno a boscovespro"}},{q="Chi vuole le Fiale di Veleno di Ragno?",a="A Borgoscuro, Dama Eva chiede cinque fiale di veleno di ragno, dita di scheletro e zanne di ghoul per creare una protezione magica.",al={"chi ha bisogno del veleno di ragno","consegna veleno di ragno boscovespro","veleno dama eva"}},{q="Per creare cosa viene usato il veleno?",a="Dama Eva combina il veleno con resti di non morti per incantare un Totem del Castigo. Il talismano difensivo infligge danni magici agli aggressori.",al={"cosa crea eva","materiali per totem del castigo","perché raccogliere il veleno di ragno"}},{q="Perché Dama Eva ha bisogno di un veleno pericoloso per un talismano protettivo?",a="Dama Eva sfrutta le proprietà letali e vendicative dei predatori della foresta e dei non morti per creare un amuleto che ritorce la violenza contro l'aggressore.",al={"perché il veleno per il talismano protettivo","storia ingredienti totem di eva"}}},fx={cd5271e6={q="Cos'è una Fiala di Veleno di Ragno?",a="È una piccola fiala che contiene il potente e corrosivo veleno estratto dagli aracnidi mostruosi che infestano Boscovespro. Sebbene sia naturalmente letale al contatto, queste sostanze oscure e virulente sono apprezzate dai mistici locali e dalle streghe dei boschi, che intessono maledizioni o incantano talismani capaci di rivolgere contro un aggressore la sua stessa malvagità.",al={"cos'è il veleno di ragno","storia della fiala di veleno di ragno","cos'è la fiala di veleno di ragno"}}},fp="20,155,26.258.0,32.346.0,39.176.0,32.119.0,32.133.0,63.143.0"}
P.entries["item:vicious-night-web-spider-venom"] = {n="Veleno di Ragno Telanotte Malvagio",s="A Tirisfal orientale, il Veleno di Ragno Telanotte Malvagio conserva un antico contagio. La Società degli Speziali Reali lo apprezza per i ceppi patogeni che contiene e lo studia per sviluppare la Nuova Piaga dei Reietti.",h="A Tirisfal orientale, il Veleno di Ragno Telanotte Malvagio conserva un antico contagio.",kw={"speziale johaan","brill","the new plague","veleno di ragno","radure di tirisfal","valle tela venefica","telanotte malvagio"},ang={["class:Rogue"]="Come Ladro esperto di neurotossine naturali, puoi vedere come la Società degli Speziali Reali trasformi i pericolosi veleni presenti in natura in armi progettate appositamente.",["race:Undead"]="Come Reietto, raccogliendo questo veleno aiuti Lady Sylvanas a portare avanti il suo incarico: sviluppare una piaga abbastanza potente da abbattere Arthas e il suo Flagello."},sec={{t="Un contagio preservato",b="Lo Speziale Johaan a Brill studia antichi testi su una piaga che uccise migliaia di persone. Il contagio responsabile di quell'epidemia è sopravvissuto per secoli nel veleno dei ragni Night Web locali. Gli speziali cacciano la varietà malvagia nella Valle Tela Venefica, a sud del Monastero Scarlatto, poi estraggono il contagio preservato per i loro esperimenti alchemici."},{t="Alimentare la New Plague",b="I Reietti cercano un'arma contro il Flagello e i viventi. Johaan aggiunge il veleno come ultimo componente della sua mistura sperimentale. Spera che il contagio preservato funzioni con la miscela."}},faq={{q="Cosa rende questo veleno unico rispetto al normale veleno di ragno?",a="Antichi testi studiati dalla Società degli Speziali Reali descrivono un antico agente patogeno della piaga conservato nelle ghiandole velenifere della stirpe dei ragni Night Web. Il loro veleno custodisce quel contagio.",al={"perché questo veleno","storia del veleno telanotte","peste veleno di ragno"}},{q="Dove si possono trovare i ragni portatori di questo veleno?",a="I ragni Night Web malvagi vivono soprattutto nella Valle Tela Venefica, nelle Radure di Tirisfal orientali, a sud del Monastero Scarlatto.",al={"dove trovare veleno di ragno","posizione ragno telanotte malvagio","ragni valle tela venefica"}},{q="Chi desidera questo veleno a Brill?",a="Lo Speziale Johaan a Brill vuole diversi campioni per proseguire le sue ricerche su un nuovo agente infettivo per i Reietti.",al={"chi ha bisogno del veleno di ragno","veleno speziale johaan","chi usa il veleno"}},{q="Qual è il ruolo del veleno nelle ricerche dei Reietti?",a="A Johaan serve il veleno come ultimo componente del suo esperimento. Antichi testi descrivono un'antica piaga conservata nel veleno dei ragni Night Web, e lui vuole scoprire se il contagio funzionerà con la sua mistura.",al={"ricerca dello speziale veleno","componente nuova piaga","veleno di ragno dei reietti"}}},fx={["901a886f"]={q="Cos'è il Veleno di Ragno Telanotte Malvagio?",a="È una tossina potente e letale estratta direttamente dai ragni telanotte malvagi che infestano la parte orientale delle Radure di Tirisfal. Oltre a essere un veleno predatorio comune, possiede una rara proprietà conservante, che mantiene la virulenza di un antico contagio mortale nelle zanne dei ragni.",al={"cos'è il veleno di ragno telanotte malvagio","veleno di ragno telanotte malvagio","veleno di ragno a tirisfal"}},["8bf9d73e"]={q="Da dove viene il Veleno di Ragno Telanotte Malvagio e chi l'ha prodotto?",a="È prodotto naturalmente dai ragni telanotte malvagi che vivono nelle Radure di Tirisfal, in particolare nella Valle Tela Venefica, a sud del Monastero Scarlatto. Secondo antichi testi scoperti dalla Società dello Speziale Reale, i ragni hanno assorbito e conservato un contagio virulento che in epoche lontane sterminò migliaia di persone, e ancora oggi portano quell'antica pestilenza nel loro veleno.",al={"chi ha prodotto il veleno di ragno telanotte malvagio","da dove viene il veleno di ragno telanotte malvagio","origine del veleno telanotte"}}},fp="30,214,21.338.0,22.200.1,63.182.0,51.114.0,30.120.0,52.213.0"}
P.entries["item:vile-familiar-head"] = {n="Testa di Famiglio Vile",s="Vicino al Covo delle Lame Ardenti, le Teste di Famiglio Vile mettono alla prova i giovani stregoni dell'Orda. Sotto la guida di Ruzan, i novizi raccolgono sei macabri trofei per dimostrare di essere pronti a vincolare i loro primi servitori demoniaci. La prova richiede disciplina e rispetto per la pericolosità degli esseri che intendono evocare.",h="Vicino al Covo delle Lame Ardenti, le Teste di Famiglio Vile mettono alla prova i giovani stregoni dell'Orda.",kw={"covo delle lame ardenti","durotar","imp","ruzan","valle delle sfide","vile familiar","testa di famiglio vile","missione dello stregone"},ang={["class:Warlock"]="Per uno stregone, raccogliere queste teste è uno dei primi passi verso il dominio sul Nether e il diritto di evocare e vincolare un folletto al proprio servizio.",["faction:Horde"]="Persino nel Cortile d'Addestramento di Durotar, gli stregoni praticano ai margini, consapevoli del persistente sospetto con cui l'Orda osserva le loro attività demoniache."},sec={{t="Una macabra lezione di demonologia",b="Nella Valle delle Sfide, Ruzan chiede ai novizi che vogliono imparare l'evocazione di portargli sei Teste di Famiglio Vile. Gli ardenti folletti chiamati Vile Familiars si annidano all'esterno del Covo delle Lame Ardenti. La loro astuzia elementale li rende nemici pericolosi. Per superare la prova, i novizi devono affrontarli e sconfiggerli, dimostrando di poter dominare la vita demoniaca anziché esserne sopraffatti.\n\nGli stregoni sono a malapena tollerati nell'Orda di Thrall, quindi il loro addestramento richiede cautela. Un novizio ucciso da una creatura evocata aggraverebbe il disonore e il sospetto che gravano su chi pratica le arti oscure."}},faq={{q="A cosa servono le Teste di Famiglio Vile?",a="Le teste dimostrano che un novizio stregone è pronto nella Valle delle Sfide. Ruzan ne richiede sei prima di insegnare a un apprendista a evocare il suo primo folletto servitore.",al={"scopo testa di famiglio vile","a cosa servono queste teste","oggetto di missione di ruzan"}},{q="Da dove provengono i Vile Familiars?",a="I Vile Familiars si radunano all'imboccatura e all'interno di una caverna a nord-est nella Valle delle Sfide. La caverna ospita il riservato e malevolo Covo delle Lame Ardenti.",al={"posizione vile familiars","dove trovare i vile familiars","caverna del covo delle lame ardenti"}},{q="Perché Ruzan fa raccogliere queste teste ai giovani stregoni?",a="Ruzan si aspetta che uno stregone sappia sopraffare una creatura prima di evocarla. I folletti ingannano i nemici e scagliano fiamme instabili, quindi sconfiggerli faccia a faccia insegna agli apprendisti quanto siano pericolosi i demoni che intendono comandare.",al={"perché raccogliere teste","movente di ruzan","perché uccidere prima i famigli"}},{q="Come vede l'Orda gli stregoni che raccolgono simili trofei?",a="L'Orda moderna tollera gli stregoni senza accoglierli pienamente. I tradimenti legati alla magia vile hanno lasciato una profonda diffidenza, quindi Ruzan e gli altri istruttori esigono che gli apprendisti studino con disciplina e discrezione.",al={"gli stregoni sono accettati","reputazione degli stregoni dell'orda","stregoni malvisti"}}},fx={["07ac30a7"]={q="Cos'è la Testa di Famiglio Vile?",a="È la testa mozzata di un famiglio vile, uno dei demoni minori simili a folletti che si aggirano fuori dal Covo delle Lame Ardenti, nella Valle delle Sfide. Per uno stregone novizio che studia a Durotar, portare questi macabri trofei dimostra di aver sconfitto un imp in combattimento diretto.",al={"cos'è la testa di famiglio vile","oggetto testa di famiglio vile","trofeo di famiglio vile"}}},fp="18,291,31.555.0,38.148.0,34.156.0,55.214.0,59.192.0"}
P.entries["item:vile-fin-scale"] = {n="Scaglia di Pinnainfame",s="Lungo le coste settentrionali e i corsi d'acqua di Tirisfal, la Scaglia di Pinnainfame proviene dalle tribù di murloc. A Brill, la Società dello Speziale Reale studia questi campioni mentre cerca una piaga che colpisca i viventi e il Flagello.",h="Lungo le coste settentrionali e i corsi d'acqua di Tirisfal, la Scaglia di Pinnainfame proviene dalle tribù...",kw={"a new plague","speziale johaan","brill","murloc","lo speziale reale society","radure di tirisfal","scaglia di pinnainfame"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a rendere sicure le zone periferiche delle Radure di Tirisfal per messaggeri e viaggiatori quando sgomberi gli insediamenti costieri di murloc aggressivi.",["race:Undead"]="Come non morto, ogni scaglia di Pinnainfame che raccogli aiuta la Società dello Speziale Reale nel suo compito di sviluppare un'arma per la sopravvivenza dei Reietti contro i viventi e il Flagello."},sec={{t="Reagenti per speziali",b="La Società dello Speziale Reale cerca una piaga che possa diffondersi tra i viventi e il Flagello. Le tossine semplici sono facili da preparare, ma una malattia infettiva deve passare da una popolazione all'altra. A Brill, lo Speziale Johaan studia le scaglie di Pinnainfame per la loro resistenza naturale e i loro rivestimenti mucosi. Spera che queste proprietà stabilizzino i suoi contagi sperimentali e li aiutino a diffondersi."},{t="La minaccia della costa",b="La tribù dei Pinnainfame vive lungo le rive settentrionali e nelle acque basse occidentali delle Radure di Tirisfal. I suoi membri minacciano i viaggiatori e si spingono nel territorio dei Reietti. Raccogliere le loro scaglie aiuta a tenere sotto controllo la popolazione di murloc selvaggi e fornisce al laboratorio di Johaan materiale organico fresco per esperimenti di guerra biologica."}},faq={{q="Perché lo Speziale Johaan vuole queste scaglie?",a="Lo Speziale Johaan studia le scaglie di Pinnainfame per le ricerche della Società dello Speziale Reale su una nuova piaga. I comuni veleni non si diffondono, quindi studia le proprietà naturali delle scaglie per aiutare i suoi esperimenti a passare da una popolazione all'altra.",al={"cosa fa johaan con le scaglie","perché scaglie di pinnainfame","johaan piaga scaglia"}},{q="Dove si possono trovare i murloc Pinnainfame?",a="I murloc Pinnainfame abitano le coste delle Radure di Tirisfal, soprattutto il litorale settentrionale e le acque occidentali accanto al Lago di Acqualucente e al mare.",al={"dove si trovano i pinnainfame","posizione murloc tirisfal","dove trovare scaglie"}},{q="Cosa rende il progetto New Plague importante per i Reietti?",a="I Reietti cercano un'arma contro i loro acerrimi rivali, il Flagello privo di volontà e le razze viventi che li vedono come mostri. Il lavoro di Johaan a Brill è uno dei primi sforzi verso questo obiettivo condiviso dall'intero regno.",al={"perché the new plague","obiettivo della piaga dei reietti","cosa ricerca lo speziale johaan"}},{q="Quali creature specifiche possiedono queste scaglie?",a="I Vile Fin Minor Oracles, i Muckdwellers e i Puddlejumpers della tribù dei Pinnainfame a Tirisfal portano queste scaglie.",al={"chi rilascia scaglia di pinnainfame","quali murloc rilasciano scaglie"}}},fx={cceccf47={q="Cos'è una Scaglia di Pinnainfame?",a="Una Scaglia di Pinnainfame è una dura scaglia acquatica estratta dalla pelle della tribù di murloc Pinnainfame, che vive lungo le coste e i corsi d'acqua delle Radure di Tirisfal. Naturalmente scivolose e resistenti alle acque costiere settentrionali, queste scaglie sono un materiale biologico insolitamente durevole.",al={"cosa sono le scaglie di pinnainfame","storia della scaglia di pinnainfame","scaglia di murloc"}},["3252dae7"]={q="Da dove vengono le Scaglie di Pinnainfame?",a="Queste scaglie sono resti biologici estratti direttamente dai membri della tribù locale di murloc Pinnainfame, come saltapozze, abitatori del fango e oracoli minori che si aggirano lungo le coste settentrionali e occidentali delle Radure di Tirisfal. Sono formazioni naturali, non manufatti.",al={"chi ha prodotto la scaglia di pinnainfame","dove trovare le scaglie di pinnainfame","origine della scaglia di pinnainfame"}}},fp="14,216,19.381.0,20.304.0,45.245.0,36.141.0,60.197.0,44.109.0"}
P.entries["item:voodoo-charm"] = {n="Talismano Vudù",s="Nei tumuli di Teldrassil, il corpo di Oben Malartiglio resta vincolato dall'incantesimo dei Gnarlpine. Il Talismano Vudù può spezzare quel vincolo.",h="Nei tumuli di Teldrassil, il corpo di Oben Malartiglio resta vincolato dall'incantesimo dei Gnarlpine.",kw={"druido dell'unghia","gnarlpine","oben malartiglio","teldrassil","il druido addormentato","talismano vudù"},ang={["class:Druid"]="Come druido che si addestra a Teldrassil, vedi la tragedia di lasciare il proprio involucro fisico mentre si viaggia nel Sogno di Smeraldo. Usare il talismano per dare una morte pietosa a un confratello Druid of the Claw e liberarlo mostra quella vulnerabilità.",["race:NightElf"]="Come Elfo della Notte, vedi quanto profondamente siano degenerati i furbolg Gnarlpine. Hanno trasformato le sacre tane nei tumuli kaldorei in luoghi di grottesca prigionia spirituale."},sec={{t="La rottura dei legami oscuri",b="Lo spirito di Oben Malartiglio è separato dalla sua carne nelle tane dei Gnarlpine, nei tumuli di Teldrassil. I furbolg hanno usato una magia maligna per controllare i corpi dormienti dei sacri protettori kaldorei, e il corpo di Oben resta soggiogato dalla loro stregoneria. Oben esamina il talismano e scopre che le preghiere tradizionali non possono spezzarne il legame oscuro.\n\nUna volta abbattuto il suo corpo senz'anima, occorre incanalare il potere del talismano sulle spoglie per dissolvere il controllo dei furbolg. Allora lo spirito errante di Oben potrà partire per sempre alla volta del Sogno di Smeraldo."}},faq={{q="Qual è lo scopo del Talismano Vudù?",a="Il Talismano Vudù spezza il controllo magico dei furbolg Gnarlpine su Oben Malartiglio. Dopo aver abbattuto il suo corpo senz'anima e soggiogato, usa il talismano sulle sue spoglie per spezzare l'incantesimo e liberare la sua anima.",al={"cosa fa il talismano vudù","uso del talismano vudù","come usare il talismano vudù"}},{q="Chi ti dà il Talismano Vudù?",a="Lo spirito di Oben Malartiglio ti consegna il Talismano Vudù durante Druid of the Claw. Lo esamina e spiega come possa liberarlo dalla stregoneria della tribù Gnarlpine.",al={"dove trovare il talismano vudù","chi dà il talismano","talismano di oben"}},{q="Perché viene chiamato Talismano Vudù nelle terre degli elfi della notte?",a="Il nome riflette la magia occulta estranea o distorta dei furbolg Gnarlpine. Hanno ceduto alla corruzione e alla bizzarra magia tribale mentre questa si infiltrava nel Grande Albero. Il talismano racchiude la magia usata per intrappolare e manovrare come fantocci i corpi dei druidi a riposo.",al={"perché vudù a teldrassil","è vudù dei troll"}},{q="Cosa succede dopo che l'amuleto viene usato?",a="Quando il talismano spezza l'incantesimo sul corpo di Oben Malartiglio, lui viene liberato dalla morsa della tribù Gnarlpine. Il suo involucro fisico trova riposo, e il suo spirito lascia Teldrassil alla volta del Sogno di Smeraldo.",al={"cosa succede a oben","oben sopravvive"}}},fx={b324ca48={q="Cos'è il Talismano Vudù?",a="Il Talismano Vudù è un talismano magico legato alla magia corrotta che attanaglia i furbolg Zampaferrea di Teldrassil. Lo spirito di Oben Malartiglio lo esamina per scoprire come i furbolg abbiano intrappolato il suo corpo, capendo che solo grazie al talismano è possibile spezzare una volta per tutte il vile incantesimo che tiene vincolato il suo corpo senz'anima.",al={"cos'è il talismano vudù","talismano vudù a teldrassil","talismano vudù di oben"}},["75919bea"]={q="Perché Oben Malartiglio vuole che si usi il Talismano Vudù?",a="Oben Malartiglio ha bisogno del talismano per spezzare il controllo dei furbolg Zampaferrea su di lui. Dopo aver sconfitto in battaglia il suo corpo senz'anima, usare il talismano sui suoi resti a terra dissolve l'incantesimo oscuro e libera il suo spirito intrappolato, permettendogli finalmente di riposare in pace nel Sogno di Smeraldo.",al={"perché usare il talismano vudù","perché oben vuole il talismano","scopo del talismano vudù"}}},fp="12,127,24.506.1,40.210.0,31.166.0,51.263.0,37.205.1"}
P.entries["item:wailing-essence"] = {n="Essenza Lamentosa",s="Nella Caverna dei Lamenti, l'Essenza Lamentosa si raccoglie negli ectoplasmi che vagano al suo interno. Gli alchimisti ne ricercano le potenti proprietà, mentre i druidi dei dintorni temono le mutazioni che si diffondono nelle Savane.",h="Nella Caverna dei Lamenti, l'Essenza Lamentosa si raccoglie negli ectoplasmi che vagano al suo interno.",kw={"ectoplasma","mebok ghignofolle","porto paranco","smart drinks","caverna dei lamenti","essenza lamentosa"},ang={["class:Druid"]="Come druido, puoi interpretare l'Essenza Lamentosa come un segno della corruzione nelle profondità della Caverna dei Lamenti e dell'urgente necessità di purificare la contaminazione del Dream."},sec={{t="Un intruglio volatile",b="Sotto le Savane centrali, un'energia innaturale deforma le bestie e genera ectoplasmi gelatinosi. Al loro interno si trova una sostanza viscosa chiamata Essenza Lamentosa. I druidi dei dintorni osservano le acque con crescente timore, mentre i mercanti goblin intravedono un'occasione di profitto.\n\nA Porto Paranco, Mebok Ghignofolle crede che l'essenza sia l'ingrediente mancante per una redditizia linea di “Smart Drinks” destinate ad affinare la mente. L'eccentrico alchimista si cura poco della corruzione che potrebbero veicolare."}},faq={{q="Da dove proviene l'Essenza Lamentosa?",a="L'Essenza Lamentosa proviene dalle melme ectoplasmatiche della Caverna dei Lamenti. Gli ectoplasmi divoratori, gli ectoplasmi in evoluzione e gli ectoplasmi dell'incubo la contengono tutti.",al={"bottino essenza lamentosa","dove trovare essenza lamentosa","cosa rilascia essenza lamentosa"}},{q="Chi vuole questa essenza?",a="Mebok Ghignofolle, uno sperimentatore goblin di Porto Paranco, vuole l'essenza per una nuova formula delle sue “Smart Drinks” che potenziano l'intelletto.",al={"a chi serve essenza lamentosa","chi compra essenza lamentosa","consegna essenza lamentosa"}},{q="Quali effetti si sospetta che l'essenza abbia sulle Savane?",a="Mebok sospetta che l'essenza faccia mutare rapidamente la fauna e diffonda una crescita vegetale innaturale nelle Savane.",al={"cosa fa essenza lamentosa","essenza lamentosa è pericolosa","storia essenza lamentosa"}},{q="Bere l'Essenza Lamentosa è davvero sicuro?",a="Bere l'Essenza Lamentosa è un gesto sconsiderato. Proviene da ectoplasmi corrotti e contaminati dall'incubo nelle profondità di una caverna maledetta, eppure Mebok intende usarla in una bevanda da vendere.",al={"si può bere l'essenza lamentosa","le smart drink sono sicure"}}},fx={["387b8d38"]={q="Che cos'è l'Essenza Lamentosa?",a="L'Essenza Lamentosa è una sostanza strana e potente che si trova nelle profondità della Caverna dei Lamenti. Si accumula negli ectoplasmi erranti e nelle melme della caverna. Gli osservatori del luogo sospettano che sia il catalizzatore innaturale delle bizzarre mutazioni che alterano piante e fauna in tutto il territorio circostante di The Barrens.",al={"cos'è l'essenza lamentosa","info sull'essenza lamentosa","informazioni sull'essenza lamentosa"}}},fp="15,184,21.484.0,37.150.0,23.131.0,54.110.0,42.163.0"}
P.entries["item:warsong-axe-shipment"] = {n="Spedizione d'Asce dei Cantaguerra",s="A Baia del Bottino, la Spedizione d'Asce dei Cantaguerra attende di attraversare il Grande Mare verso Valtetra. Le asce appena forgiate sono destinate ai Predoni Cantaguerra e al lavoro nel loro campo di taglio.",h="A Baia del Bottino, la Spedizione d'Asce dei Cantaguerra attende di attraversare il Grande Mare verso...",kw={"valtetra","asce","baia del bottino","locke okarr","avamposto di troncorotto","spedizione d'asce dei cantaguerra","warsong supplies","capitano del porto malattracco"},ang={["faction:Horde"]="Per l'Orda, questa cassa contribuisce a mantenere il Campo di Taglio dei Cantaguerra rifornito e produttivo sotto la costante pressione delle forze ostili a Valtetra.",["race:Orc"]="Per il clan Cantaguerra, asce affilate significano più legname per le crescenti fondamenta di Orgrimmar e Durotar."},sec={{t="Un lungo viaggio attraverso i mari",b="Le asce per il Campo di Taglio dei Cantaguerra attendono a Baia del Bottino. I taglialegna del campo hanno bisogno di attrezzi resistenti, e non tutti possono essere forgiati in prima linea. Così i loro ordini attraversano il Grande Mare fino a questo porto neutrale dei goblin, dove la cassa si trova vicino al Capitano del Porto Malattracco. Le asce affilate sono destinate all'Avamposto di Troncorotto, da dove possono poi proseguire verso il campo. Rifornire i lontani campi di frontiera richiede un lungo viaggio."}},faq={{q="Dove si trova la Spedizione d'Asce dei Cantaguerra?",a="La cassa si trova sulle banchine di Baia del Bottino, all'estremità meridionale della Valle di Rovotorto.",al={"posizione della spedizione d'asce","dove si trova la spedizione d'asce","cassa d'asce della baia del bottino"}},{q="Perché una spedizione per Valtetra si trova così a sud, a Baia del Bottino?",a="I Blackwater Raiders e il Cartello degli Spargifumo trasportano carichi mercantili attraverso il Grande Mare. Baia del Bottino collega terre lontane, perciò gli attrezzi dell'Orda passano per il suo porto.",al={"perché baia del bottino","perché si trova a rovetorto","asce dei cantaguerra alla baia del bottino"}},{q="A chi servono queste asce?",a="Locke Okarr, un predone dell'Avamposto di Troncorotto a Valtetra, ha bisogno delle asce per reintegrare le scorte ormai scarse del Campo di Taglio dei Cantaguerra.",al={"a chi servono le asce","per chi è la spedizione","asce di locke okarr"}},{q="Chi supervisiona la consegna a Baia del Bottino?",a="Il Capitano del Porto Malattracco sovrintende ai carichi marittimi a Baia del Bottino. La spedizione attende lì di essere trasportata a Kalimdor.",al={"chi ha la spedizione","capitano del porto malattracco","capitano del porto della baia del bottino"}}},fx={["445f7bbf"]={q="Che cos'è la Spedizione d'Asce dei Cantaguerra?",a="È una consegna in casse di pesanti asce da disboscamento diretta alle operazioni forestali del clan dei Cantaguerra a Valtetra. I taglialegna orchi consumano continuamente gli attrezzi mentre abbattono le antiche foreste di Kalimdor, perciò le spedizioni regolari di lame appena forgiate sono essenziali per rifornire appieno segherie e squadre di taglio.",al={"cos'è la spedizione d'asce dei cantaguerra","cassa di asce a valtetra"}}},fp="20,175,29.410.0,42.83.0,62.165.0,21.133.0,39.108.0"}
P.entries["item:warsong-oil"] = {n="Olio dei Cantaguerra",s="Al Campo di Taglio dei Cantaguerra, l'Olio dei Cantaguerra mantiene in funzione i macchinari. I satiri hanno portato un carico nelle loro enclavi corrotte.",h="Al Campo di Taglio dei Cantaguerra, l'Olio dei Cantaguerra mantiene in funzione i macchinari.",kw={"valtetra","locke okarr","jorxian","satirnaar","avamposto di troncorotto","olio dei cantaguerra","warsong supplies","xavian"},ang={["faction:Horde"]="Per l'Orda, il legname di Valtetra contribuisce a sostenere le sue basi a Durotar e nelle Savane. Quando i satiri adoratori dei demoni rubano l'olio per i macchinari, i lavori di costruzione in quei giovani insediamenti ne risentono.",["profession:Engineering"]="Come ingegnere, sai che le giunture dei segatronchi e le seghe circolari progettati dai goblin richiedono una lubrificazione costante. Senza, si bruciano nel giro di poche ore di taglio del legname."},sec={{t="Carburante per Macchinari Rubato",b="L'Olio dei Cantaguerra mantiene in funzione i macchinari del Clan Cantaguerra per il taglio del legname a Valtetra. I segatronchi progettati dai goblin e le grandi segherie dipendono da un rifornimento costante. Senza il lubrificante, il taglio del legname potrebbe fermarsi. Rallenterebbe così la fornitura del legname necessario per costruire Orgrimmar e rafforzare gli insediamenti dell'Orda a Durotar e nelle Savane."},{t="Rituali dei Satiri",b="I satiri hanno assaltato un carico di Olio dei Cantaguerra prima che potesse raggiungere l'Avamposto di Troncorotto e i campi di taglio. Hanno trasportato i contenitori nelle enclavi corrotte, tra cui Jorxian, Satirnaar e Xavian. Lì, i satiri usano il lubrificante infiammabile nei loro rituali."}},faq={{q="A cosa serve l'Olio dei Cantaguerra?",a="L'Olio dei Cantaguerra mantiene in funzione i pesanti segatronchi, le seghe e i macchinari per il taglio del legname al Campo di Taglio dei Cantaguerra.",al={"scopo dell'olio dei cantaguerra","perché serve l'olio","a cosa serve"}},{q="Perché i satiri hanno l'olio?",a="I satiri hanno teso un'imboscata sulle strade di Valtetra a un convoglio di rifornimenti diretto all'Avamposto di Troncorotto. Hanno preso l'olio per usarlo nei rituali celebrati negli insediamenti in rovina.",al={"chi ha rubato l'olio","perché i satiri lo possiedono","dove è finito l'olio"}},{q="Dove si può trovare l'Olio dei Cantaguerra?",a="I luoghi controllati dai satiri a Valtetra custodiscono Olio dei Cantaguerra, soprattutto Jorxian, Satirnaar e Xavian.",al={"posizione dell'olio dei cantaguerra","dove trovare l'olio dei cantaguerra","posizioni dell'olio"}},{q="Chi ha bisogno che l'olio venga recuperato?",a="Locke Okarr, all'Avamposto di Troncorotto, ha bisogno di Olio dei Cantaguerra, lame per seghe, corda e asce per rifornire le attività di taglio del legname dei Cantaguerra in difficoltà.",al={"chi vuole l'olio","chi assegna la missione dell'olio dei cantaguerra"}}},fx={["7f00f21d"]={q="Che cos'è l'Olio dei Cantaguerra?",a="L'Olio dei Cantaguerra è un lubrificante industriale fondamentale e una provvista di carburante destinata ai macchinari da disboscamento dell'Orda a Valtetra. Serve a far funzionare senza intoppi i macchinari pesanti e le lame seghettate al Campo di Taglio dei Cantaguerra ed è una risorsa indispensabile per mantenere operative le attività forestali del clan nonostante la dura usura causata dalla natura selvaggia.",al={"cos'è l'olio dei cantaguerra","cos'è l'olio","info sull'olio dei cantaguerra"}}},fp="11,128,21.322.0,20.265.0,29.109.0,31.136.0,31.98.0,28.131.0"}
P.entries["item:warsong-outrider-update"] = {n="Aggiornamenti dal Predone Cantaguerra",s="Lungo il confine orientale di Valtetra, un Predone Cantaguerra prepara gli Aggiornamenti dal Predone Cantaguerra. Di stanza sul posto, il predone raccoglie informazioni dalla prima linea che i corrieri dell'Orda trasporteranno. I rapporti aiutano a rendere sicuro il passaggio verso Azshara e a rafforzare la presenza degli orchi contro la resistenza degli Elfi della Notte.",h="Lungo il confine orientale di Valtetra, un Predone Cantaguerra prepara gli Aggiornamenti dal Predone...",kw={"valtetra","azshara","savane","kadrak","avamposto di troncorotto","predone cantaguerra","aggiornamenti dal predone cantaguerra"},ang={["faction:Horde"]="Come membro dell'Orda, dipendi dai rapporti dalla prima linea per proteggere le vie di rifornimento tra le Savane e Valtetra. Lungo queste vie viene trasportato il legname necessario per espandere Orgrimmar.",["race:Orc"]="Come orco, fai affidamento su esploratori vigili e corrieri rapidi per difendere l'onore dei Warsong e mantenere il controllo del territorio contro le sentinelle degli Elfi della Notte che contestano i diritti del tuo clan sullo sfruttamento delle foreste."},sec={{t="Informazioni dalla Frontiera",b="Oltre l'Avamposto di Troncorotto, la strada orientale attraversa gli instabili territori di confine di Valtetra verso le antiche rovine di Azshara. Le avanguardie degli orchi a cavallo pattugliano questa frontiera e annotano avvistamenti tattici, movimenti delle pattuglie e valutazioni delle risorse.\n\nInviano le loro note dal campo a Kadrak presso la torre di guardia settentrionale, che sorveglia il confine delle Savane. I rapporti offrono ai comandanti dell'Orda un quadro chiaro delle concentrazioni di truppe nemiche e delle minacce territoriali sotto la volta della foresta."}},faq={{q="Qual è lo scopo di questo aggiornamento?",a="Gli aggiornamenti riferiscono delle attività degli Elfi della Notte e delle condizioni lungo la strada orientale di Valtetra verso Azshara. Kadrak usa queste informazioni per coordinare lo schieramento delle truppe dell'Orda e rafforzare le difese lungo il confine settentrionale delle Savane.",al={"scopo aggiornamenti dal predone cantaguerra","perché aggiornamenti dal predone","cos'è questo rapporto"}},{q="Chi trasporta e consegna questo dispaccio?",a="Un Predone Cantaguerra di pattuglia sulla strada tra l'Avamposto di Troncorotto e il confine di Azshara porta con sé il dispaccio. Il predone lo consegna a Kadrak e riceve nuovi ordini strategici.",al={"chi scrive aggiornamenti dal predone","da dove provengono gli aggiornamenti dal predone"}},{q="Dove deve andare questo rapporto?",a="Porta gli aggiornamenti direttamente a Kadrak presso la torre di guardia settentrionale. La torre sorveglia il confine delle Savane e l'ingresso meridionale di Valtetra.",al={"dove porto gli aggiornamenti dal predone","chi vuole gli aggiornamenti dal predone"}},{q="Perché i Cantaguerra sono così interessati a Valtetra?",a="Il Warsong Clan abbatte alberi nelle antiche foreste di Valtetra per ricavare legname e materiali da costruzione necessari a Orgrimmar. Questa raccolta lo porta in conflitto con gli Elfi della Notte che difendono le foreste e con le Sentinelle Alargentea.",al={"perché gli orchi sono a valtetra","interesse dei cantaguerra per valtetra"}}},fx={["0cc42a69"]={q="Che cosa sono gli Aggiornamenti dal Predone Cantaguerra?",a="È un rapporto sul campo redatto da un Predone Cantaguerra che pattuglia le strade della parte orientale di Valtetra, in direzione del confine con Azshara. Documenta ricognizioni locali, movimenti delle truppe e osservazioni fondamentali per mantenere la posizione dell'Orda nella foresta contesa.",al={"cosa sono gli aggiornamenti dal predone cantaguerra","oggetto aggiornamenti dal predone cantaguerra","cos'è il rapporto del predone"}},["2fb6b9e4"]={q="Da dove provengono gli Aggiornamenti dal Predone Cantaguerra e chi li ha redatti?",a="Sono scritti e consegnati da un Predone Cantaguerra di stanza lungo la strada forestale tra l'Avamposto di Troncorotto e il confine con Azshara. Il Predone redige questi aggiornamenti sul campo in risposta ai nuovi ordini recapitati dal nord di The Barrens.",al={"chi ha scritto gli aggiornamenti dal predone cantaguerra","da dove provengono gli aggiornamenti dal predone cantaguerra","chi ha consegnato gli aggiornamenti del predone"}},aa3bba6b={q="Perché Kadrak vuole gli Aggiornamenti dal Predone Cantaguerra?",a="Kadrak coordina la presenza dell'Orda alla frontiera dalla torre di guardia settentrionale al confine di The Barrens. Gli servono le osservazioni in prima linea del Predone, insieme ai dispacci degli altri esploratori, per valutare la forza nemica e pianificare strategicamente le prossime mosse del clan dei Cantaguerra nelle profondità di Valtetra.",al={"perché kadrak ha bisogno degli aggiornamenti del predone","perché servono gli aggiornamenti dal predone cantaguerra","perché raccogliere gli aggiornamenti del predone"}}},fp="23,299,21.471.0,35.230.0,39.187.0,34.139.0,45.209.0"}
P.entries["item:warsong-runner-update"] = {n="Aggiornamenti dal Messaggero dei Cantaguerra",s="All'Avamposto di Zoram'gar, gli Aggiornamenti dal Messaggero dei Cantaguerra portano a Kadrak notizie da Valtetra occidentale.",h="All'Avamposto di Zoram'gar, gli Aggiornamenti dal Messaggero dei Cantaguerra portano a Kadrak notizie da...",kw={"valtetra","kadrak","le savane","i rapporti dei cantaguerra","clan cantaguerra","aggiornamenti dal messaggero dei cantaguerra","spiaggia di zoram","avamposto di zoram'gar"},ang={["faction:Horde"]="Il rapporto mostra quanto sia difficile mantenere avamposti lontani nel territorio ostile degli Elfi della Notte. I corrieri mantengono aperte le comunicazioni tra Valtetra e le Savane.",["race:Orc"]="Come orco, sai che gli esploratori e i corrieri dei Cantaguerra rischiano la vita nelle fitte foreste per portare rapporti tattici a Kadrak e sostenere le rivendicazioni territoriali del clan."},sec={{t="Occhi sul fronte occidentale",b="All'Avamposto di Zoram'gar, il Messaggero Cantaguerra sorveglia la costa e le minacce nei dintorni di Valtetra occidentale. Gli esploratori raccolgono osservazioni sul posto e il dispaccio riporta ciò che vedono. Raggiunge la torre di guardia di Kadrak al confine delle Savane. Il rapporto aiuta i capi dell'Orda a rafforzare la propria posizione e a pianificare gli spostamenti nei boschi ancestrali degli elfi."}},faq={{q="Cosa sono gli Aggiornamenti dal Messaggero dei Cantaguerra?",a="Gli Aggiornamenti dal Messaggero dei Cantaguerra portano le osservazioni dal fronte del Messaggero Cantaguerra all'Avamposto di Zoram'gar ai capi dell'Orda al confine delle Savane.",al={"aggiornamenti dal messaggero","cos'è aggiornamenti dal messaggero dei cantaguerra","rapporto dei cantaguerra zoram"}},{q="Da dove proviene questo dispaccio?",a="Il dispaccio proviene dal Messaggero Cantaguerra all'Avamposto di Zoram'gar, sulla costa più occidentale di Valtetra, vicino alla Spiaggia di Zoram.",al={"posizione del messaggero","dove si trova il messaggero cantaguerra","chi fornisce aggiornamenti dal messaggero"}},{q="Chi riceve questo aggiornamento?",a="Kadrak, il comandante dei Cantaguerra nella torre di guardia lungo il confine settentrionale delle Savane, riceve l'aggiornamento.",al={"a chi devo consegnarlo","aggiornamento di kadrak","consegna aggiornamenti dal messaggero"}},{q="Perché Kadrak ha bisogno di questo dispaccio?",a="Kadrak coordina gli spostamenti militari del clan Cantaguerra verso l'interno di Valtetra. I dispacci dagli avamposti come Zoram'gar lo informano sulla resistenza nemica, sulle vie d'accesso dal mare e sul controllo del territorio locale.",al={"perché aggiornamenti dal messaggero","scopo dei rapporti dei cantaguerra"}}},fp="21,90,25.339.0,34.137.0,35.120.0,25.103.0,35.198.0"}
P.entries["item:warsong-saw-blades"] = {n="Lame Seghettate dei Cantaguerra",s="Al Campo di Taglio dei Cantaguerra, le lame mantengono in funzione i macchinari dell'Orda per il taglio del legname a Valtetra. Il Clan Cantaguerra dipende da macchinari di fabbricazione goblin per raccogliere legname in tutta la foresta.",h="Al Campo di Taglio dei Cantaguerra, le lame mantengono in funzione i macchinari dell'Orda per il taglio del...",kw={"disboscamento a valtetra","locke okarr","pixel","avamposto di troncorotto","campo di taglio dei cantaguerra","lame seghettate dei cantaguerra"},ang={["faction:Horde"]="L'espansione dell'Orda nel Kalimdor centrale dipende dal legname di Valtetra. Mantenere in buono stato i macchinari delle segherie dei Cantaguerra è una priorità strategica.",["race:NightElf"]="Come Elfo della Notte, vedi ogni cassa di lame per seghe forgiate dai goblin come un altro assalto all'antica volta arborea di Valtetra e ai suoi sacri spiriti silvestri."},sec={{t="Silvicoltura industriale",b="A Valtetra, il Clan Cantaguerra dipende da macchinari pesanti forniti e mantenuti dagli ingegneri goblin. Le asce non bastano a soddisfare la richiesta dell'Orda di legname di Kalimdor, così motori a vapore e seghe circolari tagliano i tronchi. Il legno duro degli antichi alberi di Valtetra smussa e spezza rapidamente le lame comuni. Per mantenere in funzione le segherie del Campo di Taglio dei Cantaguerra, devono arrivare nuove lame."},{t="Proteggere la spedizione",b="I pezzi di ricambio devono attraversare territori contesi, dove furbolg e satiri ostili intercettano spesso i rifornimenti per il taglio del legname. Contatti goblin come Pixel all'Avamposto di Troncorotto gestiscono le spedizioni di lame per seghe. Il mastro taglialegna Locke Okarr raccoglie lame insieme a corde, olio e asce, mantenendo operativo il campo nonostante i sabotaggi dei difensori di Valtetra."}},faq={{q="A cosa servono le Lame Seghettate dei Cantaguerra?",a="Le lame sostituiscono i pezzi delle seghe circolari e dei macchinari pesanti per il taglio del legname al Campo di Taglio dei Cantaguerra, nel sud-est di Valtetra.",al={"scopo delle lame seghettate","uso delle lame seghettate","a cosa servono"}},{q="Chi fornisce queste lame per seghe all'Orda?",a="Mercanti e addetti alla logistica goblin gestiscono le lame. Pixel, un goblin all'Avamposto di Troncorotto, ne supervisiona l'arrivo per i Predoni Cantaguerra.",al={"chi ha fabbricato le lame seghettate","da dove provengono le lame","fornitore delle lame seghettate"}},{q="Perché all'Orda servono così tante lame per seghe?",a="Gli alberi secolari dal legno compatto di Valtetra consumano rapidamente i bordi taglienti. All'Orda servono grandi quantità di legname per costruire insediamenti nelle pianure aride di Durotar e delle Savane. Il taglio incessante del legname logora i macchinari più in fretta di quanto i fabbri locali riescano a riforgiarli.",al={"perché così tante lame","richiesta di legname dei cantaguerra","perché servono le seghe"}},{q="Chi sta raccogliendo i rifornimenti per il disboscamento?",a="Locke Okarr, un orco che supervisiona le spedizioni di rifornimenti dall'Avamposto di Troncorotto, organizza la raccolta di lame per seghe, olio, corde e asce da consegnare al campo di taglio.",al={"chi vuole le lame seghettate","chi prende le lame seghettate","missione di locke okarr"}}},fx={["12f75673"]={q="Che cosa sono le Lame Seghettate dei Cantaguerra?",a="Queste lame metalliche per impieghi gravosi sono componenti meccanici essenziali, realizzati per i macchinari industriali da disboscamento dei Predoni Cantaguerra. Gli orchi fanno ampio affidamento sul disboscamento meccanizzato per raccogliere il legname antico e fitto di Valtetra, ma gli alberi massicci consumano rapidamente le dentature. Senza una fornitura costante di lame affilate e resistenti, le attività forestali dei Cantaguerra si fermano.",al={"cosa sono le lame seghettate dei cantaguerra","oggetto lame seghettate dei cantaguerra","cosa sono le lame seghettate"}}},fp="18,181,19.368.0,21.326.0,41.126.0,43.140.0,43.258.0,39.162.0"}
P.entries["item:warsong-scout-update"] = {n="Aggiornamenti dall'Esploratore dei Cantaguerra",s="All'Avamposto di Troncorotto, gli esploratori dei Cantaguerra inviano all'Orda notizie su Valtetra.",h="All'Avamposto di Troncorotto, gli esploratori dei Cantaguerra inviano all'Orda notizie su Valtetra.",kw={"valtetra","savane","kadrak","rapporto","esploratrice","troncorotto","aggiornamenti","cantaguerra"},ang={["faction:Horde"]="I dispacci dei Cantaguerra mantengono gli accampamenti avanzati dell'Orda a Valtetra in contatto con le basi di rifornimento nelle Savane mentre l'Orda si espande nella foresta.",["race:Orc"]="Da orco, sai che il clan Cantaguerra sostiene il peso maggiore della campagna di disboscamento a Valtetra. Rapidi esploratori aiutano a mantenere il controllo dei suoi avamposti nella foresta."},sec={{t="Occhi nell'Antica Foresta",b="Gli esploratori dei Cantaguerra sorvegliano i boschi mentre l'Orda cerca legname e vie di rifornimento attraverso Valtetra. Dall'Avamposto di Troncorotto fortificato, seguono le sentinelle degli Elfi della Notte e i movimenti nel territorio. Le loro osservazioni raggiungono Kadrak al confine tra le Savane e Valtetra insieme agli ordini di routine. Le usa per valutare la prontezza delle truppe e coordinare i rifornimenti e gli spostamenti attraverso i boschi contesi."}},faq={{q="Cosa sono gli Aggiornamenti dall'Esploratore dei Cantaguerra?",a="Gli Aggiornamenti dall'Esploratore dei Cantaguerra trasmettono le osservazioni di un esploratore dall'Avamposto di Troncorotto, nella parte orientale di Valtetra, ai comandanti sul confine.",al={"aggiornamenti dell'esploratore","rapporto dell'esploratore","dispaccio dell'esploratrice cantaguerra"}},{q="Chi richiede questi aggiornamenti?",a="Kadrak ha bisogno degli aggiornamenti. L'ufficiale dell'Orda sorveglia il confine tra le Savane settentrionali e Valtetra da una torre di guardia, poi usa il rapporto per pianificare le manovre militari.",al={"chi lo richiede","rapporto per kadrak","chi riceve gli aggiornamenti"}},{q="Dove si trova l'Esploratrice Cantaguerra?",a="L'esploratore è di stanza all'interno dell'Avamposto di Troncorotto, la roccaforte dell'Orda lungo la strada principale che attraversa la parte orientale di Valtetra.",al={"dov'è l'esploratrice","posizione dell'esploratrice","trova esploratrice cantaguerra"}},{q="Perché questi dispacci sono così importanti per l'Orda?",a="Gli Elfi della Notte difendono strenuamente Valtetra. I rapporti degli esploratori avvertono i capi dell'Orda di imboscate e movimenti di truppe, contribuendo alla sicurezza delle vie di rifornimento e degli accampamenti di taglialegna.",al={"perché è importante","logistica dei cantaguerra","informazioni su valtetra"}}},fx={ed4a3567={q="Da dove provengono gli Aggiornamenti dall'Esploratore dei Cantaguerra e chi li ha redatti?",a="Questo rapporto scritto è redatto da un'esploratrice Cantaguerra di stanza a Valtetra, con base all'Avamposto di Troncorotto a nord. Incaricata di osservare i movimenti nemici e perlustrare la foresta contesa, l'esploratrice registra informazioni vitali sul campo e le consegna in cambio di nuovi ordini inviati dal confine di The Barrens.",al={"chi ha scritto gli aggiornamenti dall'esploratore dei cantaguerra","fonte degli aggiornamenti dall'esploratore dei cantaguerra","chi ha redatto gli aggiornamenti dell'esploratrice"}}},fp="20,70,26.383.0,33.130.0,25.172.0,35.116.0,51.157.0"}
P.entries["item:water-of-the-seers"] = {n="Acqua dei Veggenti",s="Al Villaggio di Zoccolo Sanguinario, i giovani tauren bevono la sacra Acqua dei Veggenti prima delle prove tribali. La pozione apre le loro menti al mondo degli spiriti e richiama una Plains Vision che li guidi.",h="Al Villaggio di Zoccolo Sanguinario, i giovani tauren bevono la sacra Acqua dei Veggenti prima delle prove...",kw={"villaggio di zoccolo sanguinario","visione delle pianure","rite of vision","veggente passo saggio","fuoco tribale","acqua dei veggenti"},ang={["class:Shaman"]="Se sei uno sciamano, l'Acqua dei Veggenti ti offre un primo assaggio della comunione con il mondo degli spiriti.",["race:Tauren"]="Come tauren, bevi l'Acqua dei Veggenti nel passaggio all'età adulta e prendi parte alle sacre tradizioni del tuo popolo."},sec={{t="Un ricettacolo per lo spirito",b="I giovani tauren bevono l'Acqua dei Veggenti davanti al fuoco tribale nel Villaggio di Zoccolo Sanguinario. I mistici tribali preparano la pozione per l'antico Rite of Vision. Essa dischiude la vista spirituale di chi la beve. Poi la Plains Vision si leva dalle braci e indica la via verso il Veggente Passo Saggio."}},faq={{q="Cosa succede dopo aver bevuto l'Acqua dei Veggenti?",a="Bere l'Acqua dei Veggenti accanto al fuoco tribale risveglia i tuoi sensi spirituali. La Plains Vision appare tra le fiamme e ti guida attraverso Mulgore.",al={"cosa fa l'acqua dei veggenti","bere l'acqua dei veggenti","acqua della visione delle pianure"}},{q="Dove dovrebbe essere consumata l'acqua?",a="Bevi l'Acqua dei Veggenti davanti al grande fuoco tribale nel Villaggio di Zoccolo Sanguinario, poco a nord degli anziani sciamani.",al={"dove bere l'acqua dei veggenti","posizione dell'acqua dei veggenti","posizione del fuoco tribale"}},{q="Verso chi ti guida la visione?",a="La Plains Vision ti guida a nord-ovest, tra le colline ai piedi dei monti di Mulgore. Lì, in una caverna, il Veggente Passo Saggio attende di interpretare il tuo viaggio.",al={"dove va il lupo","destinazione della visione delle pianure","chi è il veggente"}}},fx={["6b2d8d4a"]={q="Che cos'è l'Acqua dei Veggenti?",a="L'Acqua dei Veggenti è una bevanda sacra e benedetta preparata dai mistici tauren per gli iniziati che affrontano i tradizionali riti di passaggio. Bere queste acque benedette apre i tuoi sensi spirituali e ti permette di percepire i presagi e di scorgere gli spiriti guida che restano invisibili agli occhi comuni.",al={"cos'è l'acqua dei veggenti","storia dell'acqua dei veggenti","che tipo di oggetto è l'acqua dei veggenti"}},["6ddc8851"]={q="Da dove proviene l'Acqua dei Veggenti e chi l'ha preparata?",a="L'acqua viene preparata ritualmente e donata da Zarlman Due Lune nel Villaggio di Zoccolo Sanguinario. La distilla usando pietre di pozzo e granoturco d'ambra raccolti per tutto Mulgore, infondendole potere spirituale per i giovani tauren che affrontano i Rites of the Earthmother.",al={"chi ha preparato l'acqua dei veggenti","origine dell'acqua dei veggenti","da dove proviene l'acqua dei veggenti"}},bc18f3dc={q="Perché qualcuno vuole l'Acqua dei Veggenti?",a="Ti serve l'Acqua dei Veggenti per completare il Rite of Vision, una prova spirituale essenziale per i tauren. Bere la bevanda presso il fuoco tribale evoca la Visione delle Pianure, uno spirito guida destinato a condurti attraverso Mulgore verso il tuo cammino predestinato e gli anziani consiglieri.",al={"perché bere l'acqua dei veggenti","scopo dell'acqua dei veggenti","perché mi serve l'acqua dei veggenti"}}},fp="18,189,23.279.0,51.156.0,35.114.0,33.134.0"}
P.entries["item:water-pitcher"] = {n="Brocca d'Acqua",s="Sulla Mesa Nuvola Rossa, la Brocca d'Acqua trasporta acqua fresca di pozzo a Campo Narache. Madre Anziana Vento Agile chiede ai giovani tauren di riportarla e imparare l'umiltà, lo spirito di servizio e il rispetto per gli anziani della tribù.",h="Sulla Mesa Nuvola Rossa, la Brocca d'Acqua trasporta acqua fresca di pozzo a Campo Narache.",kw={"a humble task","campo narache","capo vento agile","madre anziana vento agile","pozzo di mulgore","mesa nuvola rossa","brocca d'acqua"},ang={["race:Tauren"]="Mentre raggiungi l'età adulta sulla Mesa Nuvola Rossa, portare la Brocca d'Acqua ti insegna, da giovane tauren, a onorare gli anziani e aiutare la tua comunità. Entrambi sono fondamenti della forza."},sec={{t="Una lezione di umiltà",b="La Brocca d'Acqua si trova accanto al pozzo a sud-est di Campo Narache. Madre Anziana Vento Agile chiede a un novizio di riempirla e portarla a Capo Vento Agile. Questa incombenza mette alla prova il suo carattere e insegna ai giovani valorosi che nessun compito è indegno di un protettore della tribù. Provvedere ai bisogni quotidiani della propria gente conta quanto impugnare un'arma durante la caccia."}},faq={{q="A cosa serve la brocca d'acqua?",a="La Brocca d'Acqua trasporta acqua fresca dal pozzo a Campo Narache. Portarla attraverso le pianure mette alla prova la disponibilità di un giovane viaggiatore a svolgere il lavoro quotidiano per la tribù.",al={"scopo della brocca","perché trasportare la brocca d'acqua","compito umile brocca"}},{q="Dove si trova la brocca d'acqua?",a="Trovi la Brocca d'Acqua accanto al pozzo a sud-est di Campo Narache, sulla Mesa Nuvola Rossa. Madre Anziana Vento Agile si occupa delle sue faccende nelle vicinanze.",al={"posizione della brocca","dove si trova la brocca d'acqua","trova brocca mulgore"}},{q="Chi ti chiede di recuperare la brocca d'acqua?",a="Madre Anziana Vento Agile chiede ai giovani viaggiatori di raccogliere la Brocca d'Acqua. Le sue gambe ormai anziane rendono difficile il tragitto, così chiede ai giovani volenterosi di mettere alla prova la propria vitalità e umiltà.",al={"chi assegna la missione della brocca","madre anziana brocca"}},{q="Chi riceve la brocca d'acqua una volta riempita?",a="Porti la brocca piena a Capo Vento Agile, a Campo Narache. Per lui, questo gesto dimostra che chi la porta ha il cuore e la dedizione necessari per servire la tribù.",al={"chi riceve la brocca","consegna brocca d'acqua","porta la brocca a"}}},fx={d76860be={q="Che cos'è la Brocca d'Acqua?",a="La Brocca d'Acqua è un semplice recipiente di terracotta custodito presso il pozzo d'acqua dolce nelle pianure a sud-est del Campo Narache. Riempita con acqua fresca del pozzo, è una provvista essenziale per i giovani cacciatori, i valorosi guerrieri e gli anziani che vivono nell'accampamento sulla Mesa Nuvola Rossa.",al={"cos'è la brocca d'acqua","info sulla brocca d'acqua","brocca d'acqua a mulgore"}},a1f72ee9={q="Perché Capo Vento Agile ha bisogno della Brocca d'Acqua?",a="Raccogliere acqua fresca dal pozzo delle pianure è un'attività quotidiana essenziale per la sopravvivenza del Campo Narache. Sua madre, Madre Anziana Vento Agile, affida ai giovani avventurieri il compito di portare la brocca al capo, così da aiutare la tribù e dimostrare di essere disposti a svolgere anche le mansioni più umili per la propria gente.",al={"perché serve la brocca d'acqua","perché portare la brocca d'acqua","capo vento agile e la brocca d'acqua"}}},fp="13,190,20.330.0,35.168.0,36.131.0,40.169.0,49.154.0"}
P.entries["item:webwood-egg"] = {n="Uovo di Telalegno",s="Nella Caverna Telabuia, a Vallombra, le Uova di Telalegno giacciono nei nidi. I naturalisti cercano uova vitali per poter studiare i giovani ragni in laboratori sicuri.",h="Nella Caverna Telabuia, a Vallombra, le Uova di Telalegno giacciono nei nidi.",kw={"aldrassil","gilshalan","vallombra","caverna telabuia","uovo di ragno","teldrassil","uovo di telalegno"},ang={["class:Druid"]="Come druido, puoi scoprire come si riproducono e si comportano i ragni Telalegno corrotti. Questo offre indizi su come ristabilire l'equilibrio naturale alterato di Teldrassil.",["race:NightElf"]="Come giovane kaldorei che difende i sacri rami di Teldrassil, aiuti gli studiosi a indagare sulla corruzione innaturale che si diffonde nella fauna nativa dell'Albero del Mondo recuperando queste uova."},sec={{t="Un esemplare contenuto",b="Un ragno Telalegno adulto è velenoso e troppo pericoloso perché un solo ricercatore possa addomesticarlo o sottometterlo. Per questo studiosi come Gilshalan Calcavento raccolgono uova non schiuse dalle covate nascoste nella Caverna Telabuia. Le uova possono essere trasportate in sicurezza e i ragnetti tenuti al chiuso quando nascono. I naturalisti possono studiarli senza affrontare le zanne letali dei ragni adulti."},{t="Destinato a Darnassus",b="La fauna nativa di Teldrassil è diventata innaturalmente aggressiva e corrotta, allarmando gli studiosi di tutti i rami. Le uova e i veleni raccolti, messi al sicuro ad Aldrassil, sono destinati a Darnassus. I ricercatori sperano che allevare ed esaminare i ragni in ambienti controllati riveli di più sull'oscura piaga che si diffonde tra i rami dell'Albero del Mondo."}},faq={{q="Dove si trovano le Uova di Telalegno?",a="Le Uova di Telalegno si trovano in covate nelle profondità dei cunicoli della Caverna Telabuia, nella parte nordoccidentale di Vallombra.",al={"posizione uovo di telalegno","dove si trova l'uovo di telalegno","trovare uovo di telalegno"}},{q="Chi vuole l'Uovo di Telalegno?",a="Gilshalan Calcavento, un ricercatore di Aldrassil, vuole l'uovo per studiare gli aracnidi aggressivi che affliggono Vallombra.",al={"chi ha bisogno dell'uovo di telalegno","consegna uovo","uovo di gilshalan"}},{q="Perché raccogliere un uovo invece di catturare un ragno?",a="Un ragno Telalegno adulto è pericoloso e troppo massiccio per essere catturato e tenuto al chiuso facilmente. Un uovo non schiuso può essere trasportato in sicurezza e collocato in un recinto sicuro prima che si schiuda.",al={"perché un uovo","perché non catturare un ragno vivo"}},{q="Cosa succede all'uovo dopo essere stato raccolto?",a="Gilshalan organizza la consegna dell'uovo e dei veleni estratti dai ragni a Darnassus. Lì gli studiosi possono esaminare le creature lontano dai pericoli delle terre selvagge.",al={"dove va l'uovo","destinazione dell'uovo"}}},fx={["0a629fbc"]={q="Che cos'è un Uovo di Telalegno?",a="Un Uovo di Telalegno è un uovo di ragno non schiuso deposto dai giganteschi ragni Telalegno che nidificano a Vallombra. Contiene esemplari vivi prima che emergano, permettendo ai ricercatori di studiare gli aggressivi aracnidi senza rischiare un pericolo immediato.",al={"cos'è l'uovo di telalegno","storia dell'uovo di telalegno"}},fd568742={q="Da dove proviene l'Uovo di Telalegno?",a="Queste uova sono deposte naturalmente dai giganteschi ragni Telalegno che infestano la Caverna Telabuia, nel nord-ovest di Vallombra. Nei recessi oscuri e coperti di ragnatele della caverna, i ragni mantengono nidi in cui la loro prole si sviluppa prima della schiusa.",al={"origine dell'uovo di telalegno","da dove provengono le uova di telalegno","chi ha prodotto l'uovo di telalegno"}}},fp="11,151,20.355.0,22.353.0,29.104.0,26.118.0,49.178.0,46.163.0"}
P.entries["item:webwood-ichor"] = {n="Icore di Telalegno",s="A Vallombra, l'Icore di Telalegno serve a salvare Iverron dal veleno dei ragni. Dirania Lumargento ne ha bisogno insieme a funghi giacinto e gigli petalo di luna per preparare un antidoto.",h="A Vallombra, l'Icore di Telalegno serve a salvare Iverron dal veleno dei ragni.",kw={"antidoto","dirania lumargento","iverron","vallombra","caverna telabuia","teldrassil","icore di telalegno","ragno telalegno"},ang={["race:NightElf"]="Nei panni di un giovane Elfo della Notte che difende Aldrassil, raccogli l'Icore di Telalegno e scopri che i veleni più letali di Teldrassil possono racchiudere le proprie cure."},sec={{t="Una cura tossica",b="I ragni Telalegno di Vallombra sono portatori di un veleno che ha fatto ammalare gravemente Iverron. Dirania Lumargento chiede il loro icore, funghi giacinto e gigli petalo di luna per preparare un antidoto."}},faq={{q="A cosa serve l'Icore di Telalegno?",a="A Vallombra, Dirania Lumargento ha bisogno di Icore di Telalegno, funghi giacinto e gigli petalo di luna per un antidoto. Serve a salvare Iverron, l'Elfo della Notte avvelenato.",al={"uso dell'icore di telalegno","a cosa serve l'icore di telalegno","perché raccogliere l'icore"}},{q="Da dove proviene l'Icore di Telalegno?",a="L'Icore di Telalegno si ricava dai ragni Telalegno nella parte nordoccidentale di Vallombra, soprattutto quelli intorno e all'interno della Caverna Telabuia.",al={"dove trovare l'icore di telalegno","come ottenere l'icore di telalegno","bottino icore di telalegno"}},{q="Perché usare il fluido di ragno per curare il morso di un ragno?",a="Dirania richiede l'Icore di Telalegno come ingrediente dell'antidoto per Iverron. Non spiega come agisca l'icore nella miscela.",al={"cura per il veleno di ragno","perché il veleno per l'antidoto"}}},fx={dbd415b9={q="Che cos'è l'Icore di Telalegno?",a="L'Icore di Telalegno è un fluido raccolto dai ragni Telalegno di Vallombra. Dirania Lumargento lo richiede come uno degli ingredienti per un antidoto che aiuti Iverron.",al={"icore di telalegno","cos'è l'icore di telalegno","icore di ragno"}},["789dead2"]={q="Da dove proviene l'Icore di Telalegno e chi l'ha prodotto?",a="Non viene creato né fabbricato, ma raccolto direttamente dai ragni Telalegno che infestano le zone nord-occidentali di Vallombra nei pressi della Caverna Telabuia. I ragni producono il fluido naturalmente, come parte della loro biologia.",al={"provenienza dell'icore di telalegno","da dove proviene l'icore di telalegno","chi ha prodotto l'icore di telalegno"}},["15a9db63"]={q="Perché qualcuno vuole l'Icore di Telalegno?",a="Dirania Lumargento ha bisogno dell'Icore di Telalegno per preparare un antidoto urgente per Iverron, gravemente malato a causa del veleno dei ragni. Unito ai funghi giacinto e ai gigli lunari locali, l'icore è fondamentale per contrastare il veleno che lo ha colpito.",al={"perché raccogliere l'icore di telalegno","perché serve l'icore di telalegno","chi ha bisogno dell'icore di telalegno"}}},fp="13,168,12.180.0,31.166.0,35.122.0,43.128.0"}
P.entries["item:webwood-spider-silk"] = {n="Seta di Ragno Telalegno",s="Tra i rami di Teldrassil, la Seta di Ragno Telalegno attira l'interesse di figure sospette. I Webwood Lurkers la tessono nei boschi, e gli artigiani impiegano la Seta di Ragno in molti modi.",h="Tra i rami di Teldrassil, la Seta di Ragno Telalegno attira l'interesse di figure sospette.",kw={"dolanaar","seta di ragno","teldrassil","webwood lurker","seta di ragno telalegno","zenn empiazampa","volere di zenn"},ang={["profession:Tailoring"]="Come sarto, potresti cercare filo di ragno, ma questi campioni sono legati a oscuri patti con un satiro anziché al normale lavoro al telaio.",["race:NightElf"]="Come giovane Elfo della Notte che lascia Vallombra, bada alle creature che cacci, soprattutto quando un satiro solitario vicino alle tue terre d'origine ti chiede di raccoglierle."},sec={{t="Un reagente dubbio",b="I Webwood Lurkers vicino a Dolanaar tessono un filo sottile e resistente, pericoloso da raccogliere. Zenn Empiazampa, un satiro lungo la strada della foresta, chiede ai giovani avventurieri la seta, zanne di fiera della notte e piume di gufo strigide. Sostiene che questi rari reagenti servano ai suoi affari nella foresta. I nuovi arrivati li raccolgono senza interrogarsi sulla sua natura corrotta o sui suoi veri motivi."}},faq={{q="Dove si può trovare la Seta di Ragno Telalegno?",a="La Seta di Ragno Telalegno proviene dai Webwood Lurkers e da ragni affini nelle terre selvagge di Teldrassil, soprattutto vicino a Dolanaar.",al={"posizione seta di ragno telalegno","chi rilascia seta di ragno telalegno","dove trovare seta di ragno telalegno"}},{q="Chi desidera questa seta?",a="Zenn Empiazampa vuole la seta. Il satiro nasconde i suoi traffici poco a nord del sentiero tra Vallombra e Dolanaar, e la richiede insieme a piume di gufo e zanne di predatori.",al={"a chi serve la seta telalegno","chi assegna la missione della seta telalegno","seta zenn empiazampa"}},{q="Perché Zenn Empiazampa vuole la Seta di Ragno Telalegno?",a="Zenn dice che la seta gli serve come reagente per i suoi affari nella foresta, ma tiene i dettagli per sé.",al={"motivo zenn empiazampa","perché zenn vuole la seta"}},{q="I giocatori possono usare la Seta di Ragno Telalegno per la sartoria?",a="No. Pur essendo autentica Seta di Ragno, questo filo raccolto è un reagente per un incarico, non un normale tessuto da sartoria.",al={"la seta telalegno è un materiale di sartoria","creare con seta telalegno"}}},fx={["9ba9fe8b"]={q="Che cos'è la Seta di Ragno Telalegno?",a="La Seta di Ragno Telalegno è filo grezzo filato e raccolto dai giganteschi aracnidi che infestano le foreste di Teldrassil. Fine ma resistente, questa seta naturale è apprezzata da vari artigiani tra le fronde, ma raccoglierla richiede di affrontare direttamente i velenosi ragni Telalegno nelle loro tane ombrose.",al={"cos'è la seta di ragno telalegno","seta telalegno","seta di ragno a teldrassil"}},["9736af76"]={q="Da dove proviene la Seta di Ragno Telalegno?",a="La seta è prodotta naturalmente dai ragni Telalegno, come i predatori Telalegno che si nascondono nei boschetti aggrovigliati intorno a Dolanaar. Questi aracnidi aggressivi tessono ragnatele spesse tra le grandi radici e le cavità di Teldrassil, creando fili resistenti che gli avventurieri devono raccogliere direttamente dalle creature.",al={"origine della seta telalegno","chi produce la seta telalegno","da dove proviene la seta telalegno"}}},fp="19,171,17.347.0,39.117.0,20.171.0,48.99.1,50.114.0"}
P.entries["item:webwood-venom-sac"] = {n="Sacca di Veleno di Ragno Telalegno",s="A Vallombra, i naturalisti studiano le Sacche di Veleno di Ragno Telalegno per capire come la crescita di Teldrassil abbia cambiato la fauna locale. Le sacche provengono da ragni cresciuti a dismisura, e il loro veleno potrebbe offrire indizi.",h="A Vallombra, i naturalisti studiano le Sacche di Veleno di Ragno Telalegno per capire come la crescita di...",kw={"aldrassil","gilshalan calcavento","vallombra","caverna telabuia","teldrassil","veleno","ragno telalegno","sacca di veleno di ragno telalegno"},ang={["class:Druid"]="Per un druido in sintonia con l'equilibrio della natura, la potenza di queste sacche di veleno è una prova inquietante che qualcosa non va tra i rami di Teldrassil.",["race:NightElf"]="Nei panni di un giovane avventuriero elfo della notte a Vallombra, raccogli questi campioni per aiutare gli studiosi a comprendere la strana ecologia della tua terra natale tra i rami."},sec={{t="Un sintomo della crescita di Teldrassil",b="I ragni telalegno infestano la Caverna Telabuia e il terreno circostante. Sono cugini di una specie molto più piccola che si trova altrove. La loro crescita improvvisa e l'aggressività predatoria preoccupano i ricercatori elfi della notte. Naturalisti come Gilshalan Calcavento studiano la potenza e la composizione del veleno, sperando di capire come la crescita rapida e non benedetta di Teldrassil stia cambiando le creature che vivono sui suoi rami."}},faq={{q="Dove si trovano le Sacche di Veleno di Ragno Telalegno?",a="Le Sacche di Veleno di Ragno Telalegno provengono dai ragni della parte settentrionale di Vallombra, soprattutto intorno e all'interno della Caverna Telabuia.",al={"dove si trovano questi oggetti","posizione sacca di veleno di ragno telalegno","posizione veleno di ragno"}},{q="Chi cerca queste sacche di veleno?",a="Gilshalan Calcavento, un ricercatore elfo della notte presso Aldrassil, a Vallombra, raccoglie le sacche per studiare la biologia dei ragni prima di tornare a Darnassus.",al={"chi ha bisogno di sacche di veleno","missione gilshalan calcavento"}},{q="Perché i ragni telalegno sono così grandi?",a="I ricercatori ritengono che la comparsa e la rapida crescita di Teldrassil abbiano cambiato la fauna locale, trasformando ragni comuni in predatori enormi e aggressivi.",al={"perché i ragni sono grandi","dimensione ragno telalegno"}},{q="Questo veleno viene utilizzato per creare un antidoto?",a="Gilshalan raccoglie le sacche per confrontarle e studiarle. Il veleno dei ragni della regione è pericoloso, e rimedi come l'antidoto di Iverron sono necessari per salvare chi viene morso nei boschi.",al={"serve per una cura","ingrediente antidoto"}}},fx={bab81581={q="Che cos'è la Sacca di Veleno di Ragno Telalegno?",a="Una Sacca di Veleno di Ragno Telalegno è una ghiandola intatta estratta dai ragni Telalegno che nidificano dentro e nei dintorni della Caverna Telabuia. Questi aracnidi innaturali producono un veleno potente che i ricercatori desiderano analizzare, soprattutto considerando quanto siano mutati rispetto ai loro simili più piccoli.",al={"cos'è la sacca di veleno di ragno telalegno","oggetto sacca di veleno di ragno telalegno","sacca di veleno"}},["64d32b3b"]={q="Da dove proviene una Sacca di Veleno di Ragno Telalegno?",a="Queste sacche vengono estratte direttamente dai corpi dei ragni Telalegno che infestano la parte settentrionale di Vallombra. Sono organi biologici prodotti naturalmente dagli aracnidi, la cui crescita allarmante e la cui potenza velenosa sembrano essere influenzate dalla presenza stessa di Teldrassil.",al={"da dove provengono le sacche di veleno di ragno telalegno","origine della sacca di veleno di ragno telalegno","chi ha creato la sacca di veleno di ragno telalegno"}}},fp="17,183,32.382.0,35.108.0,27.151.0,37.149.0,39.180.0"}
P.entries["item:well-stone"] = {n="Pietra del Pozzo",s="In tutta Mulgore, le Pietre del Pozzo giacciono accanto ai pozzi d'acqua. La loro magia della terra e dell'acqua aiuta a preparare l'Acqua dei Veggenti per i riti di passaggio dei tauren.",h="In tutta Mulgore, le Pietre del Pozzo giacciono accanto ai pozzi d'acqua.",kw={"ambercorn","villaggio di zoccolo sanguinario","mulgore","rite of vision","acqua dei veggenti","pietra del pozzo","zarlman due lune"},ang={["class:Shaman"]="Gli sciamani conoscono le Pietre del Pozzo come punti di ancoraggio naturali per la magia della terra e dell'acqua. I loro spiriti latenti si uniscono in una miscela cerimoniale capace di indurre una trasformazione.",["race:Tauren"]="Per i giovani tauren, raccogliere le Pietre del Pozzo è un passo essenziale per dimostrare la propria comunione con la terra. Insegna come gli elementi fisici della terra contribuiscano all'illuminazione spirituale."},sec={{t="Ricettacolo di Energie della Terra",b="Accanto ai pozzi di Mulgore, le Pietre del Pozzo giacciono nella terra soffice. Assorbono la risonanza spirituale delle pianure e delle acque sottostanti. Sciamani e veggenti come Zarlman Due Lune sanno che racchiudono una magia vitale. Sono più che comuni ciottoli di fiume.\n\nInsieme all'Ambercorn raccolta sotto gli imponenti alberi delle pianure, i minerali delle pietre temprano un infuso. Risveglia stati di trance visionaria nei giovani tauren durante il sacro Rite of Vision."}},faq={{q="A cosa servono le Pietre del Pozzo?",a="Le Pietre del Pozzo e l'Ambercorn vengono combinate per preparare l'Acqua dei Veggenti. Gli iniziati la bevono davanti al fuoco tribale, e questa concede una visione guida a chi cerca di dimostrare la propria maturità spirituale.",al={"scopo della pietra del pozzo","a cosa serve la pietra del pozzo","perché raccogliere pietre del pozzo"}},{q="Dove si trovano le Pietre del Pozzo?",a="Le Pietre del Pozzo giacciono sul terreno attorno ai pozzi d'acqua comunitari sparsi per Mulgore. Lì, l'umidità che dà vita alle pianure incontra il suolo.",al={"dove trovare la pietra del pozzo","posizioni pietra del pozzo","pietra del pozzo mulgore"}},{q="Chi richiede queste pietre?",a="Zarlman Due Lune, un mistico rispettato nel Villaggio di Zoccolo Sanguinario, incarica gli iniziati di raccogliere le Pietre del Pozzo per il Rite of Vision.",al={"chi ha bisogno delle pietre del pozzo","zarlman pietre del pozzo","pietre per rite of vision"}}},fx={["0148a630"]={q="Che cos'è una Pietra del Pozzo?",a="Una Pietra del Pozzo è una pietra naturale intrisa di elementi magici, raccolta dalla terra che circonda i sacri pozzi d'acqua di Mulgore. I mistici tauren tengono queste pietre in grande considerazione per l'alchimia rituale, poiché il loro legame con le acque pure della terra le rende potenti reagenti catalizzatori.",al={"cosa sono le pietre del pozzo","pietra del pozzo di mulgore","storia della pietra del pozzo"}},a4e2d25c={q="Da dove provengono le Pietre del Pozzo?",a="Le Pietre del Pozzo non sono create da mani mortali: vengono estratte direttamente dal suolo e dai sedimenti che circondano i pozzi d'acqua di Mulgore. Modellati e toccati per generazioni dalle sacre sorgenti che alimentano le pianure, questi minerali assorbono naturalmente l'energia spirituale ed elementale che permea la terra.",al={"da dove provengono le pietre del pozzo","chi ha creato le pietre del pozzo","origine della pietra del pozzo"}},["461b83d8"]={q="Perché Zarlman Due Lune vuole le Pietre del Pozzo?",a="Zarlman Due Lune ha bisogno delle Pietre del Pozzo per preparare l'Acqua dei Veggenti per i giovani tauren che affrontano il Rite of Vision. Polverizzati e lasciati in infusione insieme al Cornambra, gli elementi magici contenuti nelle pietre danno vita a una potente bevanda sacra che risveglia la tua vista spirituale, rivelando guide ancestrali che illumineranno il tuo cammino.",al={"perché raccogliere le pietre del pozzo","perché zarlman vuole le pietre del pozzo","pietra del pozzo e rite of vision"}}},fp="10,150,26.433.0,30.196.0,28.141.0,26.123.0"}
P.entries["item:wendigo-mane"] = {n="Manto dei Wendigo",s="In tutta Dun Morogh, i wendigo vagano tra i dirupi gelati e le loro criniere li proteggono dal freddo montano. Il Pilota Grancingolo sa come usarle.",h="In tutta Dun Morogh, i wendigo vagano tra i dirupi gelati e le loro criniere li proteggono dal freddo montano.",kw={"dun morogh","pelliccia","tana selvaggia","kharanos","criniera","pelle","grancingolo","trollplow","wendigo"},ang={["profession:Engineering"]="Le macchine naniche di Dun Morogh hanno abitacoli di metallo gelido. Le pellicce di wendigo sono utili come rivestimenti isolanti.",["race:Dwarf"]="I giovani nani cacciano i wendigo della Tana Selvaggia per dimostrare la propria tempra ai veterani di Kharanos."},sec={{t="Calore per le Fonderie",b="I wendigo vagano tra i cumuli di neve di Dun Morogh, protetti dalle correnti gelide grazie alla loro ruvida pelliccia. Fuori Kharanos, il Pilota Grancingolo invia gli avventurieri alla Tana Selvaggia per raccogliere le loro pesanti criniere. Intende usarle per tessere un tappeto isolante per il ponte interno di Trollplow, la sua preziosa macchina d'assedio nanica."}},faq={{q="Quali creature forniscono un Manto dei Wendigo?",a="Le criniere di wendigo provengono dai wendigo che vivono tra le nevi di Dun Morogh. Tra questi vi sono Young Wendigos, Wendigos adulti e bestie alfa come Vagash, Edan the Howler e Old Icebeard.",al={"dove trovare manto dei wendigo","chi rilascia manto dei wendigo","fonti manto dei wendigo"}},{q="Perché il Pilota Grancingolo vuole queste criniere?",a="Il Pilota Grancingolo vuole le criniere per un tappeto isolante da stendere sul ponte interno di Trollplow, la sua macchina d'assedio. La folta pelliccia contribuirà a tenere al caldo la sua postazione mentre la macchina attraversa i terreni gelati.",al={"perché grancingolo vuole le criniere","tappeto pilota grancingolo","a cosa servono le criniere"}},{q="Qual è il posto migliore per trovare i wendigo per le loro criniere?",a="Il Pilota Grancingolo consiglia la Tana Selvaggia, un complesso di caverne tra le montagne subito a ovest di Kharanos. I wendigo popolano la caverna e i pendii circostanti.",al={"posizione tana selvaggia","dove cacciare i wendigo","caverna dei wendigo dun morogh"}},{q="I wendigo sono pericolosi da cacciare?",a="Sì. I wendigo sono predatori selvaggi e territoriali, dotati di grande forza e di una pelle spessa. Gli istruttori nanici considerano affrontarli nelle loro tane una prima prova del coraggio e della tenacia in combattimento di un montanaro.",al={"i wendigo sono difficili da uccidere","combattere i wendigo"}}},fx={["9c5452b4"]={q="Che cos'è un Manto dei Wendigo?",a="Un Manto dei Wendigo è una folta e ispida chiazza di pelliccia ruvida, ricavata dai feroci wendigo che si aggirano tra le creste innevate di Dun Morogh. Questa resistente pelle, nota per proteggere le bestie selvagge dalle sferzanti bufere di montagna, è robusta, calda e molto apprezzata per i lavori artigianali più grezzi.",al={"cos'è il manto dei wendigo","oggetto manto dei wendigo","pelliccia di wendigo"}},e05af805={q="Da dove proviene un Manto dei Wendigo?",a="Questi manti vengono ricavati direttamente dai wendigo selvatici che vagano per Dun Morogh, soprattutto nei pressi di tane come la Tana Selvaggia, a ovest di Kharanos. Sono pelli naturali di bestia, ottenute da cacciatori disposti ad affrontare artigli e zanne delle creature montane.",al={"da dove provengono i manti dei wendigo","chi rilascia il manto dei wendigo","origine del manto dei wendigo"}}},fp="12,133,24.300.0,36.170.0,42.199.0,57.151.0,31.198.0"}
P.entries["item:whitestone-oak-lumber"] = {n="Catasta di Legname di Quercia Scorzasecca",s="Sotto Rivoluna, i Defias lavorano la Catasta di Legname di Quercia Scorzasecca per la loro flotta. La sua resistenza attira anche i fabbri dell'Alleanza in cerca di un manico per un'arma sacra.",h="Sotto Rivoluna, i Defias lavorano la Catasta di Legname di Quercia Scorzasecca per la loro flotta.",kw={"miniere della morte","goblin woodcarver","jordan stilwell","martello da paladino","test of righteousness","catasta di legname di quercia scorzasecca"},ang={["class:Paladin"]="Come paladino, devi procurarti questo legname dalle banchine sotterranee dei Defias per il Test of Righteousness di Jordan Stilwell. Lo usa per creare un martello sacro per i difensori della Luce.",["profession:Blacksmithing"]="La Quercia Scorzasecca, il minerale raffinato e una gemma si uniscono nei progetti dell'arma di Stilwell. Insieme, equilibrano peso, resistenza e risonanza metafisica."},sec={{t="Un'asta sacra",b="Jordan Stilwell, fuori da Forgiardente, ha bisogno della Catasta di Legname di Quercia Scorzasecca per un'arma degna di un campione della Luce. La unisce a una Gemma Kor Purificata e a metalli raffinati per creare un manico equilibrato e inflessibile. Il manico deve sopportare le energie sacre incanalate durante il Test of Righteousness."},{t="Legname dei bacini sotterranei",b="Nelle profondità delle Miniere della Morte sotto Rivoluna, i Goblin Woodcarvers lavorano la Quercia Scorzasecca per la flotta da guerra nascosta della Fratellanza dei Defias. Le sue venature fitte resistono alle sollecitazioni e ai colpi violenti. Gli armaioli la usano quando serve legname più resistente del comune frassino o pino per lavori cerimoniali e bellici."}},faq={{q="Dove si trova la Catasta di Legname di Quercia Scorzasecca?",a="I Goblin Woodcarvers lavorano la Catasta di Legname di Quercia Scorzasecca nelle profondità delle Miniere della Morte sotto Rivoluna, nelle Marche Occidentali. Lì, la Fratellanza dei Defias costruisce la sua imponente nave da guerra nascosta.",al={"dove trovare la quercia scorzasecca","posizione quercia scorzasecca","chi rilascia la catasta di legname di quercia scorzasecca"}},{q="Chi usa questo legname?",a="Jordan Stilwell, un fabbro vicino alle porte di Forgiardente a Dun Morogh, ha bisogno del legname per creare un'arma speciale per i paladini emergenti.",al={"a chi serve la quercia scorzasecca","consegna quercia scorzasecca"}},{q="Cosa viene fabbricato con questo legno?",a="Jordan Stilwell trasforma il resistente legname nel manico di un martello sacro a due mani. Lo forgia per chi completa il Test of Righteousness.",al={"uso quercia scorzasecca","cosa forgia jordan stilwell"}},{q="Perché il legname dei goblin è adatto a un'arma sacra?",a="La Fratellanza dei Defias usa legname compatto, abbastanza resistente per le navi da guerra. Jordan Stilwell riconosce che questo legno può sopportare la forza del potere divino.",al={"perché il legno dei goblin","perché il legname delle miniere della morte"}}},fx={["3fba151d"]={q="Che cos'è la Catasta di Legname di Quercia Scorzasecca?",a="La Catasta di Legname di Quercia Scorzasecca è un legname pregiato e particolare, ricercato dagli artigiani più esperti. Apprezzato per la sua robustezza e qualità, è essenziale per realizzare l'asta o l'impugnatura di un'arma magistrale della Luce Sacra.",al={"cos'è la catasta di legname di quercia scorzasecca","catasta di legname di quercia scorzasecca","cos'è il legname di quercia scorzasecca"}},["9364a134"]={q="Da dove proviene la Catasta di Legname di Quercia Scorzasecca e chi l'ha preparata?",a="Il legname viene tagliato e preparato nel cuore delle Miniere della Morte, nelle Marche Occidentali. A lavorarlo sono gli intagliatori goblin al servizio della Fratellanza dei Defias, che lo segano e lo modellano durante i loro illeciti progetti di costruzione sotterranei.",al={"da dove proviene la quercia scorzasecca","provenienza della catasta di legname di quercia scorzasecca","chi ha preparato la catasta di legname di quercia scorzasecca"}},e7d39b03={q="Perché Jordan Stilwell vuole la Catasta di Legname di Quercia Scorzasecca?",a="Il fabbro Jordan Stilwell ha bisogno di questo legno specifico per forgiare una grande arma degna di un paladino sacro. Abbinata a minerale raffinato, a una Gemma Kor Purificata e al martello di suo padre, la quercia resistente costituisce la base di quella che considera la sua opera migliore.",al={"perché serve la catasta di legname di quercia scorzasecca","perché jordan ha bisogno della quercia scorzasecca","uso della catasta di legname di quercia scorzasecca"}}},fp="21,150,13.284.1,25.279.1,37.158.1,21.134.0,30.148.0,48.145.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="Totem Purificatore dei Manto Selvaggio",s="Al Pozzo dei Manto Selvaggio di Mulgore resta un'ultima purificazione da compiere. Dopo la purificazione dei pozzi di Winterhoof e di Cornotonante, Mull Corno Tonante prepara un totem per il pozzo a nord di Picco del Tuono.",h="Al Pozzo dei Manto Selvaggio di Mulgore resta un'ultima purificazione da compiere.",kw={"villaggio di zoccolo sanguinario","veleni goblin","mulgore","mull corno tonante","tauren","totem purificatore dei manto selvaggio","pozzo dei manto selvaggio"},ang={["class:Shaman"]="Come sciamano, incanali la purificazione spirituale attraverso totem intagliati. Questo aiuta a risanare gli spiriti dell'acqua feriti da attività industriali sconsiderate.",["race:Tauren"]="Come tauren, risani il pozzo dei Manto Selvaggio per assolvere il tuo dovere verso Earth Mother. Proteggi la tua terra ancestrale dalle sostanze tossiche delle industrie straniere."},sec={{t="Purificare i Pozzi Sacri",b="Il Pozzo dei Manto Selvaggio deve ancora essere purificato. Le attività dei goblin hanno avvelenato la terra e contaminato le scarse acque di Mulgore. Così i tauren ricorrono a un rituale sacro contro la piaga.\n\nDopo la purificazione dei pozzi di Winterhoof e di Cornotonante, Mull Corno Tonante crea un ultimo totem per il pozzo a nord di Picco del Tuono. Gli spiriti della natura lo pervadono, e il totem purifica l'acqua fetida affinché la vita possa tornare a nutrire le pianure."}},faq={{q="Qual è lo scopo del Totem Purificatore dei Manto Selvaggio?",a="I tauren usano il totem in un rituale di purificazione al Pozzo dei Manto Selvaggio, a nord di Picco del Tuono. Il totem elimina i veleni e gli scarichi contaminati presenti nel pozzo.",al={"a cosa serve il totem","uso del wildmane totem","perché purificare il pozzo"}},{q="Chi crea il Totem Purificatore dei Manto Selvaggio?",a="Mull Corno Tonante crea il totem dopo che hai raccolto i componenti necessari e purificato gli altri pozzi contaminati di Mulgore.",al={"chi mi ha dato questo totem","totem di mull corno tonante","dove trovo il totem della purificazione"}},{q="Perché i pozzi di Mulgore sono avvelenati?",a="Le attività dei goblin hanno riversato veleni e scarichi industriali nelle acque di Mulgore. Questi minacciano le tribù dei tauren e l'equilibrio naturale delle pianure.",al={"chi ha avvelenato i pozzi","perché il pozzo è velenoso","veleni goblin mulgore"}},{q="Dove deve essere utilizzato questo totem?",a="Usa il totem al Pozzo dei Manto Selvaggio, a nord di Picco del Tuono.",al={"posizione del pozzo dei manto selvaggio","dove si trova il pozzo dei manto selvaggio","dove porto il totem"}}},fx={["6c54f1c7"]={q="Che cos'è il Totem Purificatore dei Manto Selvaggio?",a="È uno strumento rituale sacro preparato dallo sciamano Mull Corno Tonante nel Villaggio di Zoccolo Sanguinario. Infuso del favore degli spiriti dopo che hai purificato i pozzi degli Zoccolo Artico e dei Cornotonante, questo totem possiede il potere necessario per compiere il rituale di purificazione presso l'ultimo pozzo d'acqua corrotto, a nord di Picco del Tuono.",al={"cos'è il totem purificatore dei manto selvaggio","wildmane totem","totem della purificazione dei manto selvaggio"}}},fp="24,191,26.406.0,52.143.0,41.118.0,44.150.0,38.64.0"}
P.entries["item:wiley-s-note"] = {n="Nota di Wiley",s="A Borgolago, Wiley lo Scuro scrive una nota riservata per Gryan Stoutmantle per saldare un debito. Il suo contenuto rivela alleanze strette dalla Fratellanza dei Defias, coinvolgendo i servizi segreti di Roccavento nell'indagine.",h="A Borgolago, Wiley lo Scuro scrive una nota riservata per Gryan Stoutmantle per saldare un debito.",kw={"fratellanza dei defias","gryan stoutmantle","mathias shaw","guardiacolle","si:7","stonemasons","wiley lo scuro","nota di wiley"},ang={["class:Rogue"]="Come ladro, vedi Wiley lo Scuro e il Maestro Mathias Shaw, capo dell'SI:7, occuparsi della missiva.",["faction:Alliance"]="Come membro dell'Alleanza, vedi il banditismo locale nelle Marche Occidentali riconosciuto come una minaccia organizzata alla stabilità di Roccavento."},sec={{t="Un registro pericoloso",b="Wiley lo Scuro, un ladro di Borgolago, scrive il dispaccio a Redridge. Lo consegna a Gryan Stoutmantle per ricambiare un vecchio favore. Nella nota, Wiley racconta ciò che sa dei piani della Fratellanza dei Defias. La Fratellanza ha alleati tra gli gnoll, i coboldi e gli agenti goblin della regione."},{t="Il legame con gli Stonemason",b="La nota di Wiley collega la Fratellanza dei Defias alla Stonemasons Guild, che ricostruì Roccavento dopo la Seconda Guerra. Intuendo il peso politico di quel legame, Gryan Stoutmantle invia la nota al Maestro Mathias Shaw, capo delle spie dell'SI:7. Così i servizi segreti di Roccavento si uniscono all'indagine."}},faq={{q="Chi ha scritto la Nota di Wiley?",a="Wiley lo Scuro, un ladro di Borgolago, scrisse la nota. La consegnò a Gryan Stoutmantle della People's Militia per ricambiare un favore ancora in sospeso.",al={"autore della nota di wiley","chi è wiley","nota di wiley lo scuro"}},{q="Quali informazioni contiene la nota?",a="La nota avverte che la Fratellanza dei Defias sta tramando qualcosa di enorme e ha alleati tra gnoll, coboldi e goblin. Gryan Stoutmantle cerca consiglio sui suoi contenuti più delicati.",al={"contenuto della nota di wiley","cosa dice la nota","info nota defias"}},{q="Dove deve essere consegnata la nota?",a="Gryan Stoutmantle riceve la nota a Guardiacolle, nelle Marche Occidentali. Dopo averla letta, ordina che venga consegnata al Maestro Mathias Shaw presso il quartier generale dell'SI:7 a Roccavento.",al={"chi riceve la nota di wiley","consegna nota di wiley","dove porto la nota"}},{q="Perché Gryan Stoutmantle invia la nota al SI:7?",a="Gryan Stoutmantle sospetta che la nota indichi una cospirazione più profonda del semplice banditismo. La invia a Mathias Shaw, capo dei servizi segreti di Roccavento, perché indaghi.",al={"perché mostrare a mathias shaw","perché dare la nota a shaw","si:7 nota di wiley"}}},fp="12,218,18.283.0,25.292.1,23.141.0,39.183.0,41.169.0,49.160.0"}
P.entries["item:william-s-shipment"] = {n="Carico di William",s="A Borgodoro, il Carico di William è destinato a suo fratello Morgan a Roccavento e contiene candele dei coboldi di Elwynn.",h="A Borgodoro, il Carico di William è destinato a suo fratello Morgan a Roccavento e contiene candele dei...",kw={"candele","borgodoro","candele dei coboldi","morgan pestel","spezieria di pestel","roccavento","distretto commerciale","william pestel","carico di william"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a proteggere le miniere di Elwynn dai coboldi e a rifornire le botteghe della capitale di materie prime alchemiche.",["race:Human"]="Come umano, puoi vedere come il commercio di Borgodoro collega i borghi rurali alla capitale, Roccavento."},sec={{t="Un commercio di famiglia",b="William Pestel mantiene attivi i commerci tra Borgodoro e la capitale. Raccoglie merci nella Foresta di Elwynn, mentre suo fratello Morgan gestisce la Spezieria di Pestel nel Distretto Commerciale di Roccavento. William non può abbandonare i suoi doveri per viaggiare verso nord, così i corrieri portano la cera e le candele in città."},{t="Cera di coboldo",b="Il carico di William è pieno di candele dei coboldi provenienti dalle miniere di Elwynn. Raccoglie le candele grandi per la loro cera e le imballa per Morgan alla Spezieria di Pestel. Quella cera si aggiunge alle scorte usate nel commercio alchemico della capitale."}},faq={{q="Cosa c'è dentro il Carico di William?",a="Il carico contiene candele recuperate dai coboldi nelle miniere della Foresta di Elwynn. William le raccoglie dai viaggiatori di passaggio e le imballa come materie prime per la bottega alchemica di famiglia.",al={"contenuto della spedizione","cosa c'è nella scatola","cosa invia william"}},{q="A chi sta inviando questo pacco William?",a="William invia il pacco a suo fratello, Morgan Pestel, che gestisce la Spezieria di Pestel nel Distretto Commerciale di Roccavento.",al={"chi riceve la spedizione","per chi è la consegna","destinazione della spedizione"}},{q="Perché uno speziale ha bisogno di così tante candele?",a="William dice che a lui e a suo fratello servono le candele grandi per la loro cera. Non dice per quali preparati verrà usata.",al={"perché candele per l'alchimia","cosa fa pestel con le candele","uso delle candele"}},{q="Perché William non consegna il pacco di persona?",a="William è impegnato a gestire i suoi affari e a raccogliere merci a Borgodoro, senza tempo per il viaggio via terra fino a Roccavento. Ingaggia viaggiatori diretti alla capitale per trasportare il pacco.",al={"perché william non può andare","perché william ha bisogno di un corriere"}}},fx={bf7eefd8={q="Che cos'è il Carico di William?",a="Il Carico di William è un pacco ben sigillato contenente grandi candele di cera, preparato da William Pestel a Borgodoro. Le candele sono state sottratte ai kobold nelle miniere della Foresta di Elwynn e imballate per essere consegnate a Morgan Pestel a Roccavento.",al={"cos'è il carico di william","pacco del carico di william","consegna di william"}},["2b07f2a7"]={q="Da dove proviene il Carico di William e chi l'ha preparato?",a="Il carico proviene direttamente da William Pestel, un alchimista che risiede alla Locanda del Fiero Leone di Borgodoro. William ha preparato personalmente le casse usando grandi candele di cera sottratte ai kobold che infestano le vicine miniere di Fargodeep e Jasperlode.",al={"chi ha preparato il carico di william","da dove proviene il carico di william","origine del carico di william"}}},fp="18,118,16.286.0,10.217.0,34.192.0,39.121.0,44.117.0,48.185.0"}
P.entries["item:wine-ticket"] = {n="Buono per il Vino",s="A Roccavento, Renato Gallina attira clienti nel negozio di famiglia con i Buoni per il Vino. Presentane uno a Susetta Gallina per ricevere una bottiglia omaggio di Pinot Noir.",h="A Roccavento, Renato Gallina attira clienti nel negozio di famiglia con i Buoni per il Vino.",kw={"gallina winery","pinot noir","renato gallina","canali di roccavento","susetta gallina","distretto commerciale","buono per il vino"},ang={["profession:Cooking"]="Il Pinot Noir ottenuto con questo buono si abbina bene a carni sostanziose e formaggi raccolti in tutti i Regni Orientali."},sec={{t="Promuovere l'annata di famiglia",b="Vicino al Distretto Commerciale di Roccavento, Renato Gallina distribuisce buoni stampati per promuovere la Gallina Winery. L'enoteca di vini d'annata si trova lungo i vicini Canali. Ogni buono offre un assaggio omaggio di Pinot Noir, attirando passanti curiosi e avventurieri appena arrivati nell'attività di famiglia, nella speranza che diventino clienti fedeli."}},faq={{q="Cosa faccio con il Buono per il Vino?",a="Porta il Buono per il Vino a Susetta Gallina presso la Gallina Winery, lungo i Canali nel Distretto Commerciale di Roccavento. Lei lo accetterà in cambio di una bottiglia omaggio di Pinot Noir.",al={"uso del buono per il vino","come usare il buono per il vino","dove portare il buono per il vino"}},{q="Chi distribuisce questi biglietti?",a="Renato Gallina distribuisce Buoni per il Vino vicino al Distretto Commerciale per attirare clienti nell'enoteca di famiglia.",al={"chi dà il buono per il vino","dove trovare il buono per il vino"}},{q="Che tipo di vino si riceve con il biglietto?",a="Presenta il buono per ricevere una bottiglia di Pinot Noir, uno dei vini più pregiati che la famiglia Gallina vende nel regno.",al={"ricompensa del buono per il vino","quale vino si ottiene"}}},fx={eb06e870={q="Che cos'è il Buono per il Vino?",a="Il Buono per il Vino è un tagliando promozionale e un opuscolo pubblicitario distribuito per le strade di Roccavento. È un invito alla Cantina Gallina e dà a chiunque lo possieda diritto a un assaggio gratuito dei migliori vini della famiglia Gallina.",al={"cos'è il buono per il vino","oggetto buono per il vino","buono pubblicitario della cantina"}},["38c548d0"]={q="Perché Susetta Gallina vuole il Buono per il Vino?",a="Susetta Gallina raccoglie il buono per confermare che hai ricevuto la promozione su strada della cantina da suo fratello, Renato Gallina. Consegnare il tagliando onora la loro offerta promozionale e dà il benvenuto ai nuovi clienti nel loro negozio sul canale, con una bottiglia gratuita di Pinot Nero.",al={"perché susetta vuole il buono","perché consegnare il buono per il vino","perché serve il buono per il vino"}}},fp="11,157,28.333.0,34.170.0,28.106.0,41.111.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="Totem Purificatore degli Zoccolo Artico",s="Al Pozzo degli Zoccolo Artico, l'acqua avvelenata minaccia le mandrie e le tribù di Mulgore. Mull Corno Tonante prepara un totem per purificare il pozzo.",h="Al Pozzo degli Zoccolo Artico, l'acqua avvelenata minaccia le mandrie e le tribù di Mulgore.",kw={"villaggio di zoccolo sanguinario","purificazione","mulgore","mull corno tonante","totem","s.p.r. & co.","pozzo d'acqua","zoccolo artico"},ang={["class:Shaman"]="Come sciamano, invochi l'armonia della terra e dell'acqua per scacciare la corruzione artificiale. Il rito segue i principi sciamanici.",["race:Tauren"]="Per i tauren, la profanazione dell'acqua dolce ferisce il loro legame con la Madre Terra. Il rito del totem aiuta a difendere la loro terra."},sec={{t="Purificare la Sorgente",b="Mull Corno Tonante crea il Totem Purificatore degli Zoccolo Artico nel Villaggio di Zoccolo Sanguinario. I goblin della S.P.R. & Co. hanno contaminato le acque sotterranee di Mulgore con le loro attività. Incanta il legno intagliato per eliminare quei veleni estranei.\n\nIl totem deve essere portato oltre le guardie goblin ostili fino al Pozzo degli Zoccolo Artico. Lì, un rituale mirato disperde la contaminazione. Le mandrie erranti e le tribù native delle pianure tornano ad avere acqua potabile pura."}},faq={{q="A cosa serve il Totem Purificatore degli Zoccolo Artico?",a="Porti il totem al Pozzo degli Zoccolo Artico, a sud-est del Villaggio di Zoccolo Sanguinario, e compi un rituale per purificare la falda acquifera.",al={"scopo del totem della purificazione","uso del totem degli zoccolo artico","cosa fa il totem"}},{q="Chi ha fabbricato questo totem?",a="Mull Corno Tonante, un rispettato tauren del Villaggio di Zoccolo Sanguinario, intaglia e prepara il totem per rimediare ai danni al Pozzo degli Zoccolo Artico.",al={"chi ha creato il totem degli zoccolo artico","creatore del totem della purificazione","totem di mull"}},{q="Perché il Pozzo degli Zoccolo Artico è stato inquinato?",a="La S.P.R. & Co. allestisce un accampamento attorno alla sorgente. Acque di scolo, rifiuti e fanghi chimici dei suoi macchinari per il taglio del legname e l'estrazione mineraria inquinano la pozza naturale.",al={"chi ha avvelenato il pozzo degli zoccolo artico","causa inquinamento del pozzo","perché il pozzo è sporco"}},{q="Cosa accade una volta completato il rituale di purificazione?",a="Dopo il rituale, l'acqua torbida torna pulita e salubre. La fauna locale e le mandrie migratorie dei tauren possono bere dal pozzo senza pericolo.",al={"dopo aver usato il totem","risultato purificazione del pozzo","il pozzo viene risanato"}}},fx={["25396a0d"]={q="Che cos'è il Totem Purificatore degli Zoccolo Artico?",a="È un totem rituale sacro scolpito da Mull Corno Tonante a Mulgore. Infuso degli spiriti della natura, il totem è stato creato appositamente per compiere un rito di purificazione sul Pozzo degli Zoccolo Artico avvelenato, eliminando gli agenti inquinanti industriali introdotti dalla S.P.R. & Co.",al={"totem purificatore degli zoccolo artico","cos'è il totem degli zoccolo artico","informazioni sul totem purificatore degli zoccolo artico"}},b2bc5f58={q="Perché Mull Corno Tonante ha bisogno che venga usato il Totem Purificatore degli Zoccolo Artico?",a="I tauren fanno affidamento sui pozzi d'acqua di Mulgore per dissetare sé stessi e le bestie selvagge delle pianure. Poiché i goblin della S.P.R. & Co. hanno contaminato il Pozzo degli Zoccolo Artico, Mull Corno Tonante ha bisogno di un avventuriero che porti il totem in territorio ostile e purifichi l'acqua prima che la contaminazione rovini la terra per sempre.",al={"perché usare il totem purificatore degli zoccolo artico","perché purificare il pozzo degli zoccolo artico","scopo del totem degli zoccolo artico"}}},fp="26,138,20.441.0,48.139.0,23.131.0,43.167.0,51.137.0"}
P.entries["item:witchwing-talon"] = {n="Artiglio di Alastrega",s="Nelle Savane nordoccidentali, gli Artigli di Alastrega testimoniano la caduta delle arpie predatrici. A Crocevia, gli esploratori dell'Orda li cercano come prova mentre lavorano per rendere sicure le rotte vitali delle carovane.",h="Nelle Savane nordoccidentali, gli Artigli di Alastrega testimoniano la caduta delle arpie predatrici.",kw={"savane","carovane","crocevia","darsok dagalesta","arpia","artiglio","alastrega"},ang={["class:Rogue"]="Darsok Dagalesta apprezza gli attacchi silenziosi e precisi. Per lui, questi artigli affilati testimoniano l'opera di un abile uccisore contro i predatori dei cieli.",["faction:Horde"]="Le carovane collegano gli avamposti dell'Orda sparsi per Kalimdor. Sgomberare i nidi delle arpie aiuta a rendere sicura la frontiera."},sec={{t="Trofei dai posatoi",b="Le arpie Alastrega razziano le carovane di rifornimenti dell'Orda dai nidi a nordovest di Crocevia. L'esploratore Darsok Dagalesta coordina gli attacchi contro la gerarchia dello stormo. Esige una prova che ogni spazzina sia stata uccisa, e gli artigli la forniscono. Con la prova della loro caduta, gli esploratori possono sfoltire lo stormo prima di colpirne i vertici."}},faq={{q="Chi vuole gli Artigli di Alastrega e perché?",a="Darsok Dagalesta, un esploratore orco a Crocevia, raccoglie gli Artigli di Alastrega. Progetta una campagna contro la nidiata Alastrega e ne richiede otto come prova dell'uccisione delle sue razziatrici in prima linea.",al={"chi ha bisogno di artigli","chi assegna la missione artiglio di alastrega","darsok dagalesta artigli"}},{q="Quali arpie possiedono questi artigli?",a="Le arpie delle Savane nordoccidentali portano con sé gli Artigli di Alastrega. Tra queste ci sono arpie comuni e Witchwing Roguefeathers, che nidificano lungo le pareti rocciose e le creste aride.",al={"cosa rilascia gli artigli di alastrega","quali arpie hanno gli artigli"}},{q="Perché le arpie Alastrega vengono prese di mira?",a="Lo stormo Alastrega si è fatto sempre più audace, attaccando le linee di rifornimento dell'Orda e le carovane mercantili in tutte le Savane. Darsok mira a sfoltirne i ranghi inferiori prima di colpire le sue luogotenenti e la matriarca.",al={"perché uccidere le arpie alastrega","scopo dei predoni arpie"}}},fx={["5a3e0f86"]={q="Che cos'è un Artiglio di Alastrega?",a="Un Artiglio di Alastrega è un artiglio affilato, strappato direttamente dalle zampe aviarie delle arpie Alastrega che infestano le regioni nordoccidentali di The Barrens. Per gli esploratori dell'Orda di stanza a Crocevia, questi artigli recisi sono una prova concreta e inconfutabile della morte dei predoni.",al={"artiglio di alastrega","cosa sono gli artigli di alastrega"}},["98111910"]={q="Da dove provengono gli Artigli di Alastrega?",a="Questi artigli crescono naturalmente sulle arpie Alastrega che abitano i canyon del nordovest di The Barrens. Vengono prelevati dai corpi delle comuni arpie Alastrega e delle Alapiuma da cacciatori incaricati di ridurre il numero dello stormo.",al={"origine dell'artiglio di alastrega","da dove provengono gli artigli di alastrega","chi rilascia gli artigli di alastrega"}}},fp="15,169,24.338.0,35.198.0,33.160.0,45.199.0"}
P.entries["item:wolf-heart-sample"] = {n="Campione di Cuore di Lupo",s="Nelle Savane, il Campione di Cuore di Lupo porta tessuti di lupi malati da Lordaeron al Crocevia. La Royal Apothecary Society studia gli effetti delle tossine settentrionali sulle bestie autoctone di Kalimdor.",h="Nelle Savane, il Campione di Cuore di Lupo porta tessuti di lupi malati da Lordaeron al Crocevia.",kw={"speziale helbrim","speziale renferrel","savane","crocevia","lordaeron","royal apothecary society","tossine","campione di cuore di lupo"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a trasportare reagenti di ricerca attraverso il mare, collegando Sepulcra agli avamposti dell'Orda nelle Savane.",["race:Undead"]="Come non morto, porti la ricerca della Royal Apothecary Society a Kalimdor, dove la società mette alla prova gli intrugli settentrionali su una fauna sconosciuta."},sec={{t="Un'esportazione tossica",b="I lupi appestati tra le rovine di Lordaeron hanno fornito allo Speziale Renferrel i cuori racchiusi nel Campione di Cuore di Lupo. Hanno attraversato il Grande Mare per la Royal Apothecary Society dei Reietti, che studia veleni, morbi e reagenti biologici. Un corriere li porta al Crocevia, collegando gli esperimenti di Sepulcra nei martoriati Regni Orientali agli avamposti di frontiera di Kalimdor."},{t="Ricerca di Helbrim",b="Al Crocevia, lo Speziale Helbrim riceve il Campione di Cuore di Lupo. Studia come le tossine delle terre di Lordaeron devastate dal Flagello influiscono sulla fauna autoctona di Kalimdor. La tossicità preservata nei cuori potrebbe rivelare proprietà utili a migliorare i veleni e gli elisir dei Reietti lontano da casa."}},faq={{q="Che cos'è il Campione di Cuore di Lupo?",a="Il Campione di Cuore di Lupo contiene tessuti conservati di lupi infetti di Lordaeron. La tossicità persistente delle pestilenze settentrionali fornisce alla Royal Apothecary Society materiale per studiare veleni virulenti.",al={"campione di cuore di lupo","cos'è il campione","cosa c'è nel pacco"}},{q="Chi ha inviato questo campione nelle Savane?",a="La Speziale Zinge ha inviato il campione da Sepulcra, usando cuori di lupo che lo Speziale Renferrel le aveva mandato dalla Selva Pinargento.",al={"chi ha inviato il cuore di lupo","chi mi ha dato questo","origine del campione di cuore di lupo"}},{q="Perché lo Speziale Helbrim lo vuole?",a="Lo Speziale Helbrim studia gli effetti delle tossine di Lordaeron sulle bestie autoctone di Kalimdor. Intende esaminare le proprietà velenose del campione per perfezionare i composti alchemici e i veleni dei Reietti.",al={"perché helbrim lo vuole","ricerca di helbrim","scopo del cuore di lupo"}},{q="Dove deve essere consegnato il campione?",a="Porta il Campione di Cuore di Lupo allo Speziale Helbrim al Crocevia, un importante insediamento dell'Orda nel cuore delle Savane.",al={"dove portare il cuore di lupo","dov'è helbrim","luogo di consegna"}}},fp="17,188,14.376.0,18.277.0,30.195.0,36.124.0,36.196.0,43.118.0"}
P.entries["item:wolf-heart-samples"] = {n="Campioni di Cuore di Lupo",s="A Selva Pinargento, i cuori dei lupi contengono un veleno che i loro ospiti viventi tollerano. Lo Speziale Renferrel invia campioni alla Società degli Speziali Reali perché vengano studiati.",h="A Selva Pinargento, i cuori dei lupi contengono un veleno che i loro ospiti viventi tollerano.",kw={"speziale renferrel","speziale zinge","società degli speziali reali","selva pinargento","tossina","sepulcra","campioni di cuore di lupo"},ang={["race:Undead"]="Come non morto, dipendi dalla ricerca di reagenti letali della Società degli Speziali Reali per difendere i Reietti dai nemici viventi e non morti."},sec={{t="Un paradosso tossico",b="Esaminando le carcasse a Selva Pinargento, lo Speziale Renferrel ha scoperto un composto letale in alcuni cuori di lupo. Il veleno impregna i loro tessuti a una concentrazione che dovrebbe ucciderli, eppure i lupi vivono. Renferrel ha messo da parte campioni di tessuto da inviare a Sepulcra. I Reietti studiano creature che tollerano le tossine mentre cercano di padroneggiare la guerra biologica e preparano nuovi reagenti."},{t="Spedizione a Sepulcra",b="I corrieri portano i campioni sotto le Rovine di Lordaeron allo Speziale Zinge. Lavora presso la sede della Società degli Speziali Reali, nell'Apothecarium. Zinge e i suoi colleghi apprezzano le nuove tossine. Sezionano e analizzano il tessuto contaminato per isolarne i composti virulenti e scoprire come le bestie riescano a sopravvivere. Sperano di usare queste conoscenze nel loro lavoro alchemico."}},faq={{q="Perché questi cuori di lupo sono importanti per i Reietti?",a="I cuori di lupo presentano un'intensa tossicità di origine sconosciuta, che avrebbe dovuto uccidere i loro ospiti. La Società degli Speziali Reali cerca di comprendere il veleno e come i lupi riescano a sopravvivere.",al={"perché i cuori di lupo sono importanti","cosa rende speciali i cuori","perché gli speziali vogliono i cuori di lupo"}},{q="Chi richiede questi campioni?",a="Lo Speziale Renferrel ha raccolto i campioni dopo aver studiato i lupi a Selva Pinargento. Ha incaricato un corriere di portarli alla sua collega, lo Speziale Zinge, presso la sede della Società a Sepulcra.",al={"chi vuole i cuori di lupo","chi ha inviato i campioni","chi riceve i campioni"}},{q="Cosa farà lo Speziale Zinge con essi?",a="Lo Speziale Zinge seziona e analizza i campioni. La Società degli Speziali Reali cataloga nuove tossine e le trasforma in armi per sviluppare piaghe e intrugli per la regina Sylvanas.",al={"cosa fa zinge con i cuori","esperimenti di zinge","ricerche dello speziale zinge"}},{q="Da dove provengono i lupi?",a="I lupi provenivano da Selva Pinargento, dove la magia oscura, il decadimento e una strana corruzione affliggono le terre selvagge e alterano la fauna locale.",al={"da dove provengono i lupi","lupi di selva pinargento","posizione dei lupi"}}},fx={["61543e32"]={q="Che cosa sono i Campioni di Cuore di Lupo?",a="Sono campioni di tessuto prelevati e conservati da lupi corrotti. A differenza dei resti di bestie comuni, questi cuori mostrano un'eccezionale tossicità interna: una qualità velenosa talmente estrema che, a rigore, avrebbe dovuto uccidere le bestie mentre erano ancora vive.",al={"cosa sono i campioni di cuore di lupo","oggetto campioni di cuore di lupo","campioni di cuore di lupo"}},["33618b83"]={q="Da dove provengono i Campioni di Cuore di Lupo?",a="Sono stati preparati e suddivisi dallo Speziale Renferrel a partire dai cuori di lupo contaminati che hai raccolto per le sue ricerche. Riconoscendone le proprietà insolite, Renferrel ha messo da parte questi campioni specifici affinché fossero portati direttamente ai suoi colleghi nella Città Sotterranea.",al={"da dove provengono i campioni di cuore di lupo","chi ha creato i campioni di cuore di lupo","origine dei campioni di cuore di lupo"}},["6a0e6447"]={q="Perché qualcuno vuole i Campioni di Cuore di Lupo?",a="Lo Speziale Zinge e la Società degli Speziali Reali li cercano per studiare nuove forme di veleno. Il venefico innaturale che scorre negli esemplari offre nuove informazioni sugli agenti virulenti, che gli speziali vogliono isolare, analizzare e adattare alle loro letali miscele.",al={"perché vogliono i campioni di cuore di lupo","chi vuole i campioni di cuore di lupo","perché zinge vuole i campioni di cuore di lupo"}}},fp="18,153,15.383.0,24.371.0,54.194.0,27.205.0,40.167.0,31.132.0"}
P.entries["item:wood-pulp"] = {n="Pasta di Legno",s="A Bael Modan, la Pasta di Legno aiuta le forze naniche a preparare le cariche esplosive. La trasportano come base assorbente per stabilizzare gli esplosivi liquidi.",h="A Bael Modan, la Pasta di Legno aiuta le forze naniche a preparare le cariche esplosive.",kw={"bael modan","bael'dun","savane","gann spira dura","nitroglicerina","revenge of gann","nitrato di sodio","pasta di legno"},ang={["profession:Engineering"]="Come ingegnere, sai che la Pasta di Legno può assorbire nitroglicerina e un ossidante a base di nitrati. Insieme, stabilizzano il liquido volatile in una dinamite resistente.",["race:Tauren"]="Come tauren della tribù Stonespire, vedi le munizioni degli invasori rivolte contro Bael Modan. È giustizia per la distruzione della tua dimora ancestrale."},sec={{t="Una ricetta volatile",b="A Bael Modan, i nani di Forgiardente usano macchinari per il movimento terra ed esplosivi chimici per scavare nei terreni di caccia ancestrali dei tauren. La nitroglicerina liquida è instabile da sola, quindi gli ingegneri la fanno assorbire dalla porosa Pasta di Legno insieme al Nitrato di Sodio. La miscela permette di ottenere cariche stabili per gli scavi e il combattimento. Fucilieri, soldati e ufficiali ne trasportano fasci per le operazioni di mina e le munizioni da campo."},{t="Rivolto contro la fortezza",b="Dopo la caduta di Prospector Khazgorm, Gann Spira Dura ha recuperato gli schemi delle cariche esplosive dei nani. Il guerriero tauren, scacciato dalla sua terra, rivolge quelle pratiche contro gli invasori che avanzano nelle terre della sua tribù. Dalla guarnigione di Bael'dun, Gann raccoglie Pasta di Legno, nitroglicerina e nitrati per una carica destinata a distruggere la Macchina Volante dei nani a Bael Modan."}},faq={{q="A cosa serve la pasta di legno a Bael Modan?",a="A Bael Modan, gli ingegneri nanici usano la Pasta di Legno per assorbire la nitroglicerina liquida. La miscela rende le cariche da demolizione più sicure da trasportare e maneggiare per i genieri.",al={"perché i nani hanno la pasta di legno","scopo della pasta di legno","a cosa serve la pasta di legno"}},{q="Chi trasporta la Pasta di Legno nelle Savane?",a="Le forze naniche di stanza a Bael Modan, nelle Savane Meridionali, trasportano Pasta di Legno. Tra loro ci sono soldati, fucilieri e ufficiali di Bael'dun, oltre al loro comandante, il signore Cyrik Blackforge.",al={"dove trovare la pasta di legno","chi rilascia la pasta di legno","posizione della pasta di legno"}},{q="Perché Gann Spira Dura ha bisogno di questa pasta di legno?",a="Gann Spira Dura usa la Pasta di Legno per rivolgere i metodi distruttivi dei nani contro di loro. Seguendo i loro schemi di demolizione, la combina con nitroglicerina recuperata e Nitrato di Sodio per creare una carica destinata a distruggere la Macchina Volante dei nani a Bael Modan.",al={"chi vuole la pasta di legno","gann spira dura pasta di legno","perché raccogliere la pasta di legno"}},{q="La pasta di legno esplode da sola?",a="No. La Pasta di Legno grezza è fibra di legno sminuzzata. Diventa pericolosa quando viene combinata con sostanze chimiche volatili come la nitroglicerina e un ossidante come il Nitrato di Sodio.",al={"la pasta di legno è esplosiva","la pasta di legno può esplodere"}}},fx={["1f614fe2"]={q="Che cos'è la Pasta di Legno?",a="La pasta di legno è una fibra vegetale lavorata che i nani di Bael Modan tengono presso il loro sito di scavo. Di per sé è innocua, ma funge da stabilizzante poroso e assorbente quando viene mescolata a liquidi volatili come la nitroglicerina, trasformando sostanze chimiche pericolose in esplosivi solidi e maneggevoli.",al={"che cos'è la pasta di legno","oggetto pasta di legno","descrizione della pasta di legno"}},["1f0d889e"]={q="Da dove proviene la Pasta di Legno e chi l'ha prodotta?",a="Questa pasta viene prodotta e conservata dai nani di Forgiardente dello scavo di Bael'dun. I soldati, i fucilieri e gli ufficiali di stanza a Bael Modan ne trasportano fasci per la fortezza, rifornendo le operazioni di demolizione e le postazioni d'artiglieria.",al={"da dove proviene la pasta di legno","chi ha prodotto la pasta di legno","origine della pasta di legno"}}},fp="9,147,17.373.0,23.350.1,41.154.0,37.166.0,45.264.0,33.162.0"}
P.entries["item:wooden-key"] = {n="Chiave di Legno",s="A nord del Rifugio di Legnovivo, la Chiave di Legno passa tra le mani di antichi impazziti vicino a Vilbosco. Apre un baule nascosto che contiene un pezzo della Verga di Dartol.",h="A nord del Rifugio di Legnovivo, la Chiave di Legno passa tra le mani di antichi impazziti vicino a Vilbosco.",kw={"valtetra","crazed ancient","verga di dartol","vilbosco","impugnatura di ferro","shael'dryn","withered ancient","chiave di legno"},ang={["class:Druid"]="Come druido, puoi vedere quanto la piaga demoniaca sia penetrata nei boschetti Cenarion tra Valtetra e Vilbosco.",["race:NightElf"]="Come figlio delle stelle, potresti soffrire nel vedere gli amati antichi di Kalimdor ridotti alla follia, stretti a reliquie perdute lungo la strada per Vilbosco."},sec={{t="Una chiave in mani folli",b="I Crazed Ancient e i Withered Ancient portano la Chiave di Legno lungo i sentieri ombrosi a nord del Rifugio di Legnovivo. Shael'dryn conosceva un tempo i treant del luogo, ma ora dice che la corruzione li ha stravolti. Uno degli antichi porta la chiave di un baule che contiene un pezzo della Verga di Dartol."},{t="Sbloccare la verga",b="Shael'dryn manda gli avventurieri a trovare la chiave e ad aprire un logoro baule nascosto in una piccola radura a ovest della strada per Vilbosco. Al suo interno si trova l'Impugnatura di Ferro, uno dei pezzi necessari per ricostruire la Verga di Dartol. La verga serve a combattere la corruzione che avvelena le foreste sacre."}},faq={{q="Cosa apre la Chiave di Legno?",a="La Chiave di Legno apre un logoro baule in una piccola radura a ovest della strada principale che conduce a nord, verso Vilbosco. Al suo interno si trova l'Impugnatura di Ferro, necessaria per ricostruire la Verga di Dartol.",al={"cosa apre la chiave di legno","baule della chiave di legno","dove usare la chiave di legno"}},{q="Chi trasporta la Chiave di Legno?",a="I Crazed Ancient e i Withered Ancient portano la chiave nei boschi a nord del Rifugio di Legnovivo, vicino al confine con Vilbosco.",al={"chi rilascia la chiave di legno","dove trovare la chiave di legno","rilascio chiave di legno"}},{q="Perché gli antichi hanno questa chiave?",a="Shael'dryn dice che uno dei treant corrotti vicino a Vilbosco porta la chiave. Non spiega come sia finita in possesso del treant.",al={"perché i treant hanno la chiave","storia della chiave degli antichi"}},{q="Chi ti manda a recuperare la Chiave di Legno?",a="Shael'dryn si prende cura del Pozzo Lunare della Purezza a Valtetra. Incarica gli avventurieri di recuperare la chiave per contribuire alla ricostruzione della Verga di Dartol.",al={"assegnatore missione chiave di legno","chi vuole la chiave di legno"}}},fx={ebbbe3a2={q="Che cos'è la Chiave di Legno?",a="La Chiave di Legno è una semplice chiave intagliata portata dagli alberi corrotti che vagano nel nord di Valtetra, vicino a Vilbosco. È stata creata per chiudere un forziere nascosto che contiene una reliquia del defunto elfo della notte Dartol.",al={"informazioni sulla chiave di legno","che cos'è la chiave di legno"}},a6fc69e1={q="Perché Shael'dryn vuole la Chiave di Legno?",a="Shael'dryn ha bisogno della chiave affinché tu possa aprire il forziere consunto nascosto in una radura vicino al confine con Vilbosco. Al suo interno si trova un'Impugnatura di Ferro, un frammento essenziale per ricomporre la Verga di Dartol e purificare la terra.",al={"perché serve la chiave di legno","perché recuperare la chiave di legno","perché vogliono la chiave di legno"}}},fp="10,156,18.256.0,17.259.1,32.160.0,27.122.0,34.137.0,41.143.0"}
P.entries["item:worn-parchment"] = {n="Cartapecora Consunta",s="Alla Torre di Althalaxx, nel nord di Rivafosca, i cultisti si radunano e custodiscono frammenti di cartapecora consunta tra i loro averi.",h="Alla Torre di Althalaxx, nel nord di Rivafosca, i cultisti si radunano e custodiscono frammenti di...",kw={"althalaxx","balthule ombrafuria","dark strand","rivafosca","fanatici","cartapecora consunta"},ang={["class:Warlock"]="Come stregone, leggi della congrega organizzata dei Dark Strand che opera in segreto nelle terre degli Elfi della Notte. I suoi membri brandiscono la magia vile e l'ombra lontano dallo sguardo sia dell'Alleanza sia dell'Orda.",["race:NightElf"]="Come Elfo della Notte, sai che gli incantatori oscuri e la corruzione demoniaca presso antiche rovine come Althalaxx profanano la natura sacra di Rivafosca."},sec={{t="Frammenti di un Sinistro Complotto",b="A nord, lungo la costa di Rivafosca avvolta dalla nebbia, oscuri incantatori e i loro seguaci hanno occupato la diroccata Torre di Althalaxx. I Dark Strand Fanatics pattugliano l'area e portano frammenti di cartapecora consunta tra i loro averi. Un singolo frammento contiene solo scritte sparse e strani simboli. Riuniti, i frammenti rivelano un'organizzazione chiamata Cult of the Dark Strand."},{t="Smascherare la Setta",b="Da un vicino punto d'osservazione, l'esploratore Balthule Ombrafuria sorveglia la torre. Usa le cartapecore raccolte per valutare la minaccia per conto di Delgren the Purifier e delle sentinelle di Auberdine. I testi confermano che gli stregoni sono organizzati in una setta e non sono reietti indipendenti. I piani della setta rimangono sconosciuti."}},faq={{q="Chi trasporta queste cartepecore consunte?",a="I Dark Strand Fanatics portano le cartapecore tra i loro averi. Sono fanti della setta accampati lungo il perimetro della Torre di Althalaxx, nel nord di Rivafosca.",al={"chi rilascia la cartapecora consunta","dove trovare la cartapecora consunta","fonte della cartapecora consunta"}},{q="Cosa c'è scritto sulle cartepecore?",a="Ogni cartapecora contiene frammenti criptici di appunti rituali e ordini. Raccolti e decifrati da Balthule Ombrafuria, rivelano il nome e l'esistenza del Cult of the Dark Strand.",al={"cosa dice la cartapecora consunta","testo della cartapecora consunta","significato della cartapecora"}},{q="Perché Balthule Ombrafuria le sta raccogliendo?",a="Delgren the Purifier ha incaricato Balthule di sorvegliare la Torre di Althalaxx. A Balthule servono gli scritti per scoprire perché gli stregoni si sono radunati alle rovine, valutare il pericolo per Rivafosca e fare rapporto.",al={"chi vuole la cartapecora consunta","missione di balthule","perché raccogliere le cartepecore"}},{q="Cos'è il Cult of the Dark Strand?",a="Il Cult of the Dark Strand è un gruppo riservato di cultisti e stregoni che ha sede tra le rovine di Althalaxx. Persino esploratori esperti come Balthule Ombrafuria non si erano mai imbattuti nell'ordine prima di trovare questi scritti.",al={"setta dark strand","chi sono i dark strand","cult of the dark strand"}}},fx={["83151644"]={q="Che cos'è la Cartapecora Consunta?",a="Queste cartapecore consunte sono appunti e pergamene portati dai cultisti di Dark Strand accampati intorno alla Torre di Althalaxx, nel nord di Darkshore. Ricomponendone i frammenti, il loro contenuto rivela gli intrighi oscuri e la presenza di una setta di stregoni nota come Cult of the Dark Strand.",al={"che cos'è la cartapecora consunta","storia della cartapecora consunta","informazioni sulla cartapecora consunta"}},["4385c03d"]={q="Da dove proviene la Cartapecora Consunta e chi l'ha scritta?",a="Le pergamene provengono dai fanatici e dagli stregoni di Dark Strand che si sono radunati intorno alle rovine della Torre di Althalaxx. I cultisti portano questi appunti scritti come parte delle loro comunicazioni e dei loro riti misteriosi, anche se l'autore preciso di ciascuna pergamena rimane sconosciuto.",al={"da dove proviene la cartapecora consunta","chi ha scritto la cartapecora consunta"}}},fp="14,120,28.378.0,18.307.1,34.175.0,34.183.0,45.201.0,36.221.0"}
P.entries["item:worn-stone-token"] = {n="Emblema di Pietra Consunto",s="In tutte le Montagne d'Alterac, gli Emblemi di Pietra Consunti recano ancora gli incantamenti sbiaditi creati da Dalaran per comandare gli elementali. Restano nelle mani della gente di Dalaran, dai maghi ai manovali.",h="In tutte le Montagne d'Alterac, gli Emblemi di Pietra Consunti recano ancora gli incantamenti sbiaditi creati...",kw={"montagne d'alterac","dalaran","elementali","protettore bel'varil","magus voidglare","stone tokens","mulino di tarren","emblema di pietra consunto"},ang={["class:Mage"]="Come mago, riconosci questi emblemi come pratici catalizzatori che il Kirin Tor usa per mantenere stabili e obbedienti gli elementali evocati sul campo.",["faction:Horde"]="Come membro dell'Orda, puoi aiutare i Reietti a Mulino di Tarren a studiare le difese e le pratiche arcane delle forze ostili del Kirin Tor presenti ad Alterac."},sec={{t="Emblemi della Maestria Elementale",b="I maghi di Dalaran usano talismani per piegare al proprio volere gli elementali di altri reami. Gli Emblemi di Pietra Consunti sono esemplari esauriti di questi strumenti. Li portano teurghi ed evocatori, insieme ai manovali e alle guardie di Dalaran stanziati attorno alle rovine e ai campi d'internamento di Alterac. Il vincolo elementale permea il lavoro quotidiano di Dalaran."},{t="La curiosità dei Reietti",b="A Mulino di Tarren, i Reietti sorvegliano i maghi vicini. Magus Voidglare vuole gli Emblemi di Pietra Consunti per studiare come Dalaran asservisce gli elementali. Il Protettore Bel'varil incarica gli agenti di raccogliere prima emblemi consunti e inerti. Questi permettono a Magus di esaminare in sicurezza le tecniche di base dell'incantamento prima di provare condotti più potenti e instabili."}},faq={{q="A cosa servivano questi emblemi?",a="I maghi di Dalaran usano emblemi di pietra per vincolare e comandare gli elementali evocati da altri reami. Impiegano gli elementali come manovali, guardie e difensori.",al={"scopo dell'emblema di pietra consunto","cosa sono gli stone tokens","perché dalaran porta gli emblemi"}},{q="Perché gli emblemi sono descritti come consunti?",a="Gli incantamenti attivi degli emblemi si sono affievoliti con il tempo e l'uso intenso. Il Protettore Bel'varil considera gli esemplari inerti più sicuri per il primo studio di Magus Voidglare sui rituali di vincolo di Dalaran.",al={"perché consunto","gli emblemi sono magici","emblemi inerti"}},{q="Chi trasporta questi emblemi?",a="Li porta il personale di Dalaran nelle Montagne d'Alterac meridionali, dagli evocatori e teurghi di alto rango ai comuni manovali, alle guardie con scudo e a Warden Belamoore al campo d'internamento.",al={"chi rilascia gli emblemi di pietra consunti","dove trovare gli emblemi","bottino emblemi dalaran"}},{q="Perché i Reietti li vogliono?",a="Magus Voidglare vuole studiare il controllo arcano di Dalaran sugli elementali e svelarne le arti di evocazione e sottomissione.",al={"perché bel'varil vuole gli emblemi","emblemi del magus voidglare"}}},fx={["4cdbd814"]={q="Che cos'è un Emblema di Pietra Consunto?",a="Un Emblema di Pietra Consunto è un artefatto magico sbiadito, creato dai maghi di Dalaran. Queste pietre incantate fungono da strumenti arcani per vincolare, comandare e controllare servitori elementali evocati da altre dimensioni. Con il tempo o l'uso prolungato, la loro magia innata si è affievolita fino a renderle inerti, ma conservano ancora i segreti costruttivi dell'arte elementale di Dalaran.",al={"che cos'è l'emblema di pietra consunto","emblema di pietra consunto","stone tokens"}},["2e06b1f4"]={q="Da dove provengono gli Emblemi di Pietra Consunti e chi li ha creati?",a="Gli emblemi sono creati dai maghi e dagli artefici di Dalaran, una magocrazia rinomata per la padronanza della magia extradimensionale. Li troverai addosso alle forze di Dalaran stanziate in tutte le Montagne di Alterac, tra cui evocatori, teurghi, guardie con scudo, lavoratori e la Custode Belamoore nei vicini campi di internamento.",al={"chi ha creato l'emblema di pietra consunto","origine degli emblemi di pietra","da dove provengono gli emblemi di pietra"}}},fp="16,187,27.327.0,18.301.0,32.161.0,37.180.0,25.188.0,32.120.0"}
P.entries["item:woven-wand"] = {n="Bacchetta Intrecciata"}
P.entries["item:xavian-water-sample"] = {n="Campione d'Acqua di Xavian",s="I maghi dell'Orda a Orgrimmar cercano a Xavian acque ricche di potere arcano. Sperano di svelare la magia latente custodita nei luoghi sacri più antichi di Valtetra.",h="I maghi dell'Orda a Orgrimmar cercano a Xavian acque ricche di potere arcano.",kw={"valtetra","deino","orgrimmar","satiro","troncorotto","campione d'acqua","xavian"},ang={["class:Mage"]="Come mago dell'Orda, recuperare il campione mette alla prova la tua abilità con il potere arcano naturale e la tua capacità di attraversare un territorio ostile, contaminato dai demoni.",["faction:Horde"]="Come membro dell'Orda, puoi vedere come raccogliere le antiche risorse arcane di Xavian aiuti gli studiosi di Orgrimmar mentre l'Orda rafforza la propria presenza attorno all'Avamposto di Troncorotto, a Valtetra."},sec={{t="Acque dell'Antica Città",b="Xavian era un tempo una leggendaria città elfica dell'antichità, e i sapienti ne conoscono ancora l'antica saggezza. Sebbene la città giaccia in rovina, si dice che le sue acque custodiscano un grande potere magico. Deino, un'istruttrice di magia arcana a Orgrimmar, invia i maghi emergenti nel cuore di Valtetra per attingere acqua fresca dalla pozza sotto la cascata più alta di Xavian. Devono attraversare un territorio pericoloso, dove satiri corrotti ora sorvegliano ferocemente le rovine e si oppongono agli incantatori che vi si intromettono."}},faq={{q="Dove viene raccolto il campione d'acqua?",a="Riempi la Fiasca di Deino nella pozza sotto la cascata più alta tra le rovine di Xavian. Il luogo si trova nella parte nordorientale di Valtetra, a nord, oltre i laghi al di là dell'Avamposto di Troncorotto e di Satirnaar.",al={"dove trovare l'acqua di xavian","posizione della cascata di xavian","come ottenere il campione d'acqua di xavian"}},{q="Perché Deino vuole quest'acqua?",a="Deino insegna ai giovani praticanti dell'Orda nella Valle degli Spiriti di Orgrimmar. Vuole l'acqua per i suoi studi su forme di magia potenti e insolite, alla ricerca dell'antica essenza magica custodita nelle acque indisturbate di Xavian.",al={"chi vuole l'acqua di xavian","perché raccogliere l'acqua da xavian","scopo di deino"}},{q="Quali minacce sorvegliano le acque di Xavian?",a="I satiri abitano le antiche rovine elfiche e difendono ferocemente il loro territorio dai maghi curiosi. Bestie aggressive, tra cui i crocolischi di fiume, vivono anche nei corsi d'acqua circostanti.",al={"quali nemici si trovano a xavian","chi vive a xavian","pericoli di xavian"}},{q="Cosa succede una volta riportato il campione a Orgrimmar?",a="Quando il campione giunge a Orgrimmar, Deino inizia subito a studiarne le proprietà arcane. Usa la magia raccolta per portare avanti le sue ricerche e contribuire alla formazione e all'istruzione dei maghi dell'Orda.",al={"consegnare l'acqua di xavian","a cosa serve l'acqua"}}},fx={ff7d6737={q="Che cos'è il Campione d'Acqua di Xavian?",a="È una fiaschetta riempita con l'acqua raccolta direttamente alla base della cascata più alta della città in rovina di Xavian. Si dice che le acque di questo antico insediamento degli elfi della notte possiedano grandi poteri magici, suscitando l'intensa curiosità degli studiosi dell'Orda.",al={"che cos'è il campione d'acqua di xavian","campione d'acqua di xavian","fiaschetta d'acqua di xavian"}},["27a4db96"]={q="Da dove proviene il Campione d'Acqua di Xavian e chi l'ha raccolto?",a="L'acqua viene attinta dalla cascata naturale nel cuore di Xavian, un'antica città elfica immersa nelle profondità della parte orientale di Valtetra. Nessun artigiano mortale l'ha creata: le acque incontaminate scorrono tra rovine intrise dell'antica magia degli elfi della notte e della corruzione persistente dei satiri che ora dominano quei luoghi.",al={"da dove proviene l'acqua di xavian","chi ha raccolto il campione d'acqua di xavian","origine dell'acqua di xavian"}}},fp="19,153,26.443.0,36.181.0,31.211.0,40.178.0,54.183.0"}
P.entries["item:young-crocolisk-skin"] = {n="Pelle di Crocolisco Giovane",s="Nelle Paludi Grigie, i giovani crocolischi forniscono pelli per i commerci di Porto di Menethil. James Halloran concia le loro pelli più morbide e le spedisce verso porti lontani.",h="Nelle Paludi Grigie, i giovani crocolischi forniscono pelli per i commerci di Porto di Menethil.",kw={"crocolisco","james halloran","cuoio","porto di menethil","pelle","concia","paludi grigie"},ang={["class:Hunter"]="Come cacciatore, puoi battere i margini fangosi delle Paludi Grigie in cerca di pelli di crocolisco e rifornire il commercio di cuoio di Porto di Menethil."},sec={{t="Concia e Commercio nelle Paludi",b="Porto di Menethil esporta merci delle paludi dalla costa occidentale di Khaz Modan. Le pelli sono tra le esportazioni più redditizie e vengono conciate dal conciatore della cittadina, James Halloran. I crocolischi adulti hanno scaglie spesse e resistenti, mentre i giovani forniscono un cuoio più morbido e più facile da lavorare.\n\nQueste pelli delicate sono molto richieste. Halloran dipende dai cacciatori locali e dai viaggiatori di passaggio per perlustrare gli acquitrini appena fuori città e tenere riforniti i suoi telai da concia."}},faq={{q="Perché James Halloran vuole specificamente pelli di crocolischi giovani?",a="I giovani crocolischi hanno pelli più morbide, più facili da lavorare e conciare rispetto alle scaglie spesse e resistenti dei crocolischi adulti. Il loro cuoio è molto richiesto lungo le rotte commerciali marittime.",al={"perché pelle di crocolisco giovane","pelli di halloran","perché pelli morbide"}},{q="Dove si possono trovare i giovani crocolischi?",a="I Young Wetlands Crocolisks vivono nei corsi d'acqua, negli acquitrini e nelle paludi appena fuori Porto di Menethil, nelle Paludi Grigie occidentali.",al={"posizione crocolisco giovane","dove trovare giovani crocolischi","crocolischi delle paludi grigie"}},{q="Chi altro caccia questi crocolischi per il porto?",a="Einar, un cacciatore locale, porta regolarmente pelli di crocolisco alla bottega di lavorazione del cuoio di James Halloran. Un solo battitore non riesce sempre a soddisfare la domanda.",al={"chi caccia i crocolischi","cacciatore einar","cacciatori conciatore menethil"}},{q="Dove vengono spedite queste pelli conciate?",a="I prodotti finiti di James Halloran lasciano Porto di Menethil a bordo di navi mercantili dirette ai principali porti e mercati dei Regni Orientali e oltre.",al={"commercio cuoio di crocolisco","esportazioni pelli menethil","dove vanno le pelli"}}},fx={["2363e64c"]={q="Che cos'è la Pelle di Crocolisco Giovane?",a="È la pelle grezza e morbida ricavata dai crocolischi giovani che si aggirano nelle paludi delle Paludi Grigie. Poiché le bestie giovani non hanno ancora sviluppato le spesse e rigide scaglie degli adulti, le loro pelli sono molto più flessibili e apprezzate dai conciatori locali.",al={"che cos'è la pelle di crocolisco giovane","oggetto pelle di crocolisco giovane","significato della pelle di crocolisco"}},a9554702={q="Da dove proviene la Pelle di Crocolisco Giovane?",a="Queste pelli provengono direttamente dai crocolischi giovani che vivono nelle paludi acquitrinose intorno al Porto di Menethil. Non sono oggetti fabbricati, ma pelli naturali ricavate dagli animali cacciati, prima di essere conciate e trasformate in cuoio pregiato.",al={"origine della pelle di crocolisco giovane","dove trovare la pelle di crocolisco giovane","chi ha prodotto la pelle di crocolisco giovane"}}},fp="20,151,32.458.0,70.174.0,36.120.0,47.141.0,36.153.0"}
P.entries["item:yowler-s-paw"] = {n="Zampa di Ghignolungo",s="A Borgolago, Verner Osgood riceve la Zampa di Ghignolungo come prova della morte del temuto capo gnoll. Ghignolungo guida i branchi che minacciano le colline sopra la cittadina.",h="A Borgolago, Verner Osgood riceve la Zampa di Ghignolungo come prova della morte del temuto capo gnoll.",kw={"capobranco gnoll","howling in the hills","borgolago","gnoll di crestarossa","montagne crestarossa","verner osgood","ghignolungo","zampa di ghignolungo"},ang={["class:Hunter"]="Come cacciatore, seguire le tracce del capobranco degli gnoll di Crestarossa e prenderne la zampa mette alla prova la tua abilità nel seguire tracce e affrontare bestie contro un predatore pericoloso.",["faction:Alliance"]="Sconfiggere Ghignolungo e recuperarne la zampa aiuta a stabilizzare le Montagne Crestarossa mentre le forze di Roccavento sono troppo disperse per proteggere la propria frontiera orientale."},sec={{t="Trofeo del Capobranco",b="Ghignolungo guida gli gnoll di Crestarossa che terrorizzano le alture attorno al Lago Placido. I loro ululati raggiungono Borgolago. Temuto più di ogni altro, Ghignolungo è uno spietato capobranco che spinge i branchi a espandersi. Verner Osgood chiede la sua zampa come prova per riscuotere una taglia, secondo l'usanza diffusa nei territori umani. Il trofeo segna la morte di un predatore insolitamente astuto e colpisce il comando dei suoi disorganizzati seguaci."},{t="Una Cittadina Lasciata a Se Stessa",b="Borgolago affronta il pericolo con scarso aiuto da Roccavento. L'Esercito di Roccavento è assorbito dalla minaccia degli orchi Roccianera asserragliati attorno al Mastio di Guardamasso. Le autorità civili e gli abitanti devono ingaggiare mercenari di passaggio per difendersi. Senza guarnigioni reali regolari, i coloni come Verner Osgood si affidano a prove che le minacce siano state eliminate, mantenendo le strade locali appena sicure per il commercio e i viaggi."}},faq={{q="Chi chiede la Zampa di Ghignolungo?",a="Verner Osgood, un importante artigiano residente a Borgolago, chiede la Zampa di Ghignolungo. Vuole la prova che il pericoloso capobranco gnoll che terrorizza le colline sia stato eliminato definitivamente.",al={"chi vuole la zampa di ghignolungo","missione zampa verner osgood","consegnare zampa di ghignolungo"}},{q="Chi è Ghignolungo?",a="Ghignolungo guida i branchi di gnoll di Crestarossa. La sua forza bruta e la sua astuzia gli permettono di radunare più branchi, rendendolo una minaccia urgente per gli abitanti dei dintorni.",al={"chi è ghignolungo","storia di ghignolungo","capobranco gnoll di crestarossa"}},{q="Perché Borgolago si affida alle taglie invece che ai soldati di Roccavento?",a="L'Esercito di Roccavento è sopraffatto dagli orchi Roccianera fortificati al Mastio di Guardamasso, nella parte orientale di Crestarossa. Senza rinforzi disponibili, gli abitanti come Verner Osgood si affidano ad avventurieri indipendenti per dare la caccia a minacce come Ghignolungo.",al={"perché nessuna guardia di roccavento","dov'è l'esercito di roccavento","perché verner assolda mercenari"}},{q="Cosa succede una volta ucciso Ghignolungo?",a="Uccidere Ghignolungo spezza il comando che tiene uniti gli aggressivi gnoll. Il suo branco si disperde nelle terre selvagge, dando agli abitanti di Borgolago una tregua temporanea.",al={"cosa succede dopo la morte di ghignolungo","gnoll dopo ghignolungo","finale di howling in the hills"}}},fx={["5e9f7255"]={q="Che cos'è la Zampa di Ghignolungo?",a="La Zampa di Ghignolungo è la zampa mozzata del capo del branco di gnoll di Redridge, presa come prova tangibile della sua morte. Verner Osgood a Borgolago chiede agli avventurieri di dare la caccia al feroce alfa e recuperarla per verificare che la bestia sia stata uccisa.",al={"che cos'è la zampa di ghignolungo","oggetto zampa di ghignolungo","zampa di ghignolungo"}},c7fb7fcc={q="Da dove proviene la Zampa di Ghignolungo?",a="Non è un oggetto fabbricato, ma l'arto mozzato dello stesso Ghignolungo. Ghignolungo guida gli gnoll aggressivi che si aggirano sulle colline sopra Borgolago ed è molto più feroce e astuto dei normali bastardi che minacciano le Montagne Crestarossa.",al={"dove trovare la zampa di ghignolungo","chi ha creato la zampa di ghignolungo","origine della zampa di ghignolungo"}},["034bdc4c"]={q="Perché Verner Osgood vuole la Zampa di Ghignolungo?",a="Verner Osgood pretende la zampa come prova inconfutabile della morte del temibile capo degli gnoll. Con l'esercito di Roccavento impegnato su troppi fronti contro gli orchi dei Blackrock, Borgolago dipende dagli avventurieri di passaggio per abbattere i predatori locali, e Verner vuole una prova prima di ricompensarti.",al={"perché vogliono la zampa di ghignolungo","perché verner vuole la zampa di ghignolungo","taglia per la zampa di ghignolungo"}}},fp="12,157,25.399.0,22.397.0,26.181.0,14.148.0,66.225.0,35.170.0"}
P.entries["item:zalazane-s-head"] = {n="Testa di Zalazane",s="Il Maestro Gadrin cerca una prova della caduta di Zalazane. I Puntascura desiderano una tregua dal medico delle ombre che li scacciò dalle Isole dell'Eco.",h="Il Maestro Gadrin cerca una prova della caduta di Zalazane.",kw={"puntascura","isole dell'eco","gadrin","troll ammaliato","villaggio di sen'jin","troll voodoo","zalazane","testa di zalazane"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere la costa meridionale di Durotar eliminando Zalazane e impedendo alla sua magia oscura di minare i territori appena fondati da Thrall.",["race:Troll"]="Come troll Puntascura, prendere la testa di Zalazane è un atto di vendetta e giustizia contro il traditore che esiliò il tuo popolo e schiavizzò i tuoi fratelli."},sec={{t="Prova della fine del traditore",b="Il Maestro Gadrin ti chiede di dimostrare che Zalazane è morto. Il medico delle ombre tradì i Puntascura e si impadronì della loro dimora insulare con malefici che soggiogavano le menti. La sua magia spinse il popolo di Vol'jin sulle coste di Durotar.\n\nDalle Isole dell'Eco, Zalazane invia ancora schiavi stregati attraverso il mare per catturare altre vittime. Il Villaggio di Sen'jin ha bisogno di una prova che il suo dominio sia finito. La sua testa mozzata ne conferma la sconfitta e dona un po' di pace alla tribù esiliata, con la speranza di riconquistare un giorno le isole sottratte."}},faq={{q="Chi richiede la Testa di Zalazane?",a="Il Maestro Gadrin chiede la Testa di Zalazane come prova che Zalazane è stato ucciso. È un medico delle ombre del Villaggio di Sen'jin, sulla costa meridionale di Durotar.",al={"chi vuole la testa di zalazane","chi assegna la missione di zalazane","gadrin zalazane"}},{q="Perché Zalazane è stato preso di mira?",a="Zalazane era un tempo uno stregone rispettato tra i Puntascura. La sua sete di potere lo portò a soggiogare i suoi simili con magie di controllo mentale, scacciare la tribù dalle Isole dell'Eco e razziare la terraferma per ridurre in schiavitù altri Puntascura.",al={"perché uccidere zalazane","cosa ha fatto zalazane","storia di zalazane"}},{q="Dove si trova Zalazane?",a="Zalazane vive sulla più grande delle Isole dell'Eco, al largo della costa sudorientale di Durotar. Lo circondano troll stregati e troll voodoo vincolati al suo servizio.",al={"dove si trova zalazane","posizione di zalazane","isole dell'eco zalazane"}},{q="Portare la testa permette di riconquistare le Isole dell'Eco?",a="Uccidere Zalazane pone fine alla minaccia immediata delle sue incursioni e porta sollievo al Villaggio di Sen'jin. Eppure le Isole dell'Eco rimangono pericolose e popolate da schiavi ancora soggiogati dal voodoo, e i Puntascura continuano a risiedere soprattutto sulla terraferma.",al={"i troll riconquistano le isole dell'eco","le isole dell'eco vengono riconquistate","isole dell'eco sicure"}}},fx={c704c705={q="Da dove proviene la Testa di Zalazane?",a="Proviene direttamente dal traditore stregone Zalazane: la ottieni dopo averlo sconfitto nel suo accampamento sulla più grande delle Isole dell'Eco. Non è stata creata, ma presa con la forza per porre fine alla sua schiavitù dei troll Lanciascura.",al={"chi ha creato la testa di zalazane","dove si ottiene la testa di zalazane","origine della testa di zalazane"}},a9dad833={q="Che cos'è la Testa di Zalazane?",a="È la testa mozzata dello stregone Zalazane, presa dopo averlo abbattuto sulle Isole dell'Eco. Più che un macabro trofeo, è la prova inconfutabile che il mago rinnegato che ha tradito la tribù dei Lanciascura e l'ha cacciata dalla sua isola è stato finalmente ucciso.",al={"che cos'è la testa di zalazane","oggetto testa di zalazane"}}},fp="15,139,26.493.0,29.146.0,26.232.0,24.141.0,46.227.0"}
P.entries["item:zamah-s-note"] = {n="Appunto di Zamah",s="A Picco del Tuono, Zamah invia un appello urgente a Mulino di Tarren. Chiede allo Speziale Lydon un modo alchemico per scacciare la S.P.R. & Co. da Petrartiglio senza spargimenti di sangue.",h="A Picco del Tuono, Zamah invia un appello urgente a Mulino di Tarren.",kw={"alture di colletorto","lydon","vette di petrartiglio","mulino di tarren","picco del tuono","sepulcra","s.p.r. & co.","zamah"},ang={["faction:Horde"]="La consegna dell'appunto mostra come le lontane capitali dell'Orda, tra Kalimdor e i Regni Orientali, condividano rotte e risorse.",["race:Undead"]="Come non morto, appartieni a un popolo la cui Società degli Speziali Reali offre conoscenze chimiche specialistiche agli alleati che affrontano crisi difficili."},sec={{t="Un appello attraverso il Grande Mare",b="La S.P.R. & Co. ha scavato a fondo nelle Vette di Petrartiglio. I suoi goblin abbattono alberi e devastano la terra sacra, così Zamah cerca un modo per scacciarli senza compiere un massacro. Si rivolge alla Società degli Speziali Reali dei Reietti per chiedere aiuto. Il suo appunto avverte il collega Speziale Lydon del pericolo a Petrartiglio. Lydon si trova lontano, a Mulino di Tarren, nelle Alture di Colletorto di Lordaeron."},{t="Connessioni tra speziali",b="L'appunto sigillato deve attraversare i continenti per raggiungere Lydon. I viaggiatori provenienti da Kalimdor prendono uno zeppelin per Sepulcra, poi proseguono verso sud attraverso la Selva Pinargento fino a Colletorto. Le notizie da oltreoceano incuriosiscono Lydon, che prepara una risposta alchemica al problema dei goblin."}},faq={{q="Cos'è l'Appunto di Zamah?",a="L'Appunto di Zamah è una lettera sigillata inviata da Picco del Tuono allo Speziale Lydon a Mulino di Tarren. Chiede una formula alchemica per allontanare la S.P.R. & Co. da Petrartiglio.",al={"cos'è questo oggetto","appunto di zamah","lettera a lydon"}},{q="Perché Zamah ha bisogno di aiuto da Mulino di Tarren?",a="Zamah vuole scacciare i goblin da Petrartiglio senza spargimenti di sangue. Cerca l'aiuto dello Speziale Lydon perché gli alchimisti dei Reietti preparano intrugli specifici per provocare disordini in modo discreto.",al={"perché inviare a colletorto","perché contattare lydon","perché mulino di tarren"}},{q="Dove deve essere consegnato l'appunto?",a="L'appunto deve raggiungere lo Speziale Lydon a Mulino di Tarren, nelle Alture di Colletorto di Lordaeron.",al={"chi riceve l'appunto","consegna appunto di zamah","dove porto l'appunto"}},{q="Chi è la S.P.R. & Co. menzionata nell'appunto?",a="La S.P.R. & Co. è un consorzio minerario e forestale gestito dai goblin. Rade al suolo le foreste, sfrutta le risorse naturali e inquina le terre di Kalimdor, comprese le cime sacre delle Vette di Petrartiglio.",al={"s.p.r. & co. vette di petrartiglio","chi è la s.p.r. & co.","s.p.r. & co."}}},fx={c24d4d7f={q="Da dove proviene l'Appunto di Zamah e chi l'ha scritto?",a="L'appunto è stato scritto da Zamah, una Reietta che vive a Picco del Tuono. Preoccupata per lo sfruttamento e la distruzione che la S.P.R. & Co. continua a causare nelle Vette di Petrartiglio, ha redatto la lettera per raggiungere, oltre il mare, una fidata collega a Lordaeron.",al={"chi ha scritto l'appunto di zamah","da dove viene l'appunto di zamah","chi ha creato l'appunto di zamah"}},["6846e14b"]={q="Perché lo Speziale Lydon vuole l'Appunto di Zamah?",a="Lo Speziale Lydon ha bisogno dell'appunto perché descrive la richiesta specifica di Zamah per una soluzione alchemica contro la S.P.R. & Co. Zamah cerca un metodo drastico e incruento per cacciare i Profanatori dalle Vette di Petrartiglio; l'appunto precisa i requisiti, così Lydon può preparare la mistura adatta.",al={"perché lydon vuole l'appunto","perché vogliono l'appunto di zamah","scopo dell'appunto di zamah"}}},fp="12,172,27.380.0,22.271.0,21.172.0,42.188.0,41.93.0,49.208.0"}
P.entries["item:zargh-s-meats"] = {n="Zargh's Meats",s="Al Crocevia, Zargh prepara carne fresca per Gryshka a Orgrimmar. Il pacco dà ai giovani viaggiatori dell'Orda un motivo per conoscere la rotta dei Wind Rider.",h="Al Crocevia, Zargh prepara carne fresca per Gryshka a Orgrimmar.",kw={"crocevia","devrak","gryshka","carni","orgrimmar","valle della forza","wind rider","zargh"},ang={["profession:Cooking"]="Gryshka apprezza questi tagli freschi. Mostrano la predilezione degli orchi per la carne al sangue, appena cotta e ricavata direttamente dalle bestie selvatiche delle Savane.",["race:Orc"]="Come orco, portare i tagli di Zargh a Gryshka ti fa conoscere la Valle della Forza, cuore della tua capitale, e la necessità di viaggiare in volo sulle viverne."},sec={{t="Il carico di un corriere",b="Zargh caccia e macella al Crocevia, nelle Savane, preparando tagli freschi per Gryshka, la locandiera della Valle della Forza a Orgrimmar. Il caldo della savana può far andare a male rapidamente la selvaggina, così i corrieri portano il pacco al nido del Crocevia. Lì, il Maestro dei Wind Rider Devrak organizza un volo in viverna fino alla Skytower di Orgrimmar. Il volo risparmia ai viaggiatori il lungo viaggio via terra attraverso Durotar."},{t="La via per il cuore",b="Con la sua consegna, Zargh invia più che semplici provviste. Quando Gryshka riceve la carne, riconosce il suo talento nel conquistare il favore di una dama con selvaggina di qualità. Non vede l'ora di preparare i tagli per gli avventori e gli ospiti della locanda. Per i viaggiatori orchi e troll appena arrivati, la consegna offre un motivo per conoscere i voli a lunga distanza tra gli insediamenti dell'Orda di Kalimdor."}},faq={{q="Chi ha preparato Zargh's Meats?",a="Zargh, un orco macellaio e cacciatore al Crocevia, nelle Savane, prepara e confeziona la carne.",al={"chi ha preparato zargh's meats","chi è zargh","da dove viene la carne"}},{q="Chi è il destinatario delle carni?",a="Gryshka, la locandiera della Valle della Forza a Orgrimmar, riceve i tagli.",al={"a chi va la carne","chi è gryshka","dove consegno zargh's meats"}},{q="Perché la carne deve essere trasportata con un wind rider?",a="La carne fresca va a male rapidamente nel caldo delle Savane e di Durotar. Zargh manda i corrieri da Devrak al nido del Crocevia, dove una viverna può trasportare il pacco a Orgrimmar prima che vada a male.",al={"perché trasportare la carne in volo","devrak wind rider carne"}},{q="Perché solo certe razze possono consegnare questo pacco?",a="I viaggiatori orchi e troll portano il pacco di Zargh a Orgrimmar. Gli avventurieri tauren portano pelli di animali a Picco del Tuono, mentre i corrieri Reietti riportano provviste a Mausolea.",al={"perché i tauren non possono ricevere questa missione","non morti zargh's meats","chi può consegnare zargh's meats"}}},fx={a104b0f9={q="Che cos'è Zargh's Meats?",a="Zargh's Meats è un pacco di tagli pregiati di carne cruda, preparato a Crocevia. Non si tratta di normali scarti di macelleria: questi tagli pregiati vengono inviati in dono a Gryshka, la locandiera della Valle della Forza di Orgrimmar.",al={"che cos'è zargh's meats","oggetto zargh's meats","pacco di carne di zargh"}}},fp="13,149,17.389.0,18.360.0,27.95.0,34.76.0,41.188.0,48.175.0"}
P.entries["item:zhevra-hooves"] = {n="Zoccolo di Zevra",s="Nelle Savane, le zevra pascolano nelle distese aperte, prede veloci dal calcio potente. I loro zoccoli dimostrano che un cacciatore sa affrontarle.",h="Nelle Savane, le zevra pascolano nelle distese aperte, prede veloci dal calcio potente.",kw={"savane","crocevia","darkthorn","zoccoli","caccia","corridore","sergra","zevra"},ang={["class:Hunter"]="Come cacciatore, impari a seguire le tracce di veloci animali da branco nella savana e ad affrontare i loro potenti calci.",["faction:Horde"]="Come nuova recluta dell'Orda giunta nelle Savane, puoi dimostrare di essere in grado di difendere Crocevia raccogliendo zoccoli per Sergra Darkthorn."},sec={{t="Trofei della Caccia",b="Le zevra vagano per le Savane su zampe compatte e muscolose, capaci di colpire con forza. Sergra Darkthorn, la sciamana orca responsabile di Crocevia, invia i nuovi esploratori dell'Orda a raccogliere gli zoccoli dei corridori zevra. La caccia mette alla prova l'istinto e la resistenza di un giovane cacciatore. Un corridore in preda al panico può atterrare persino un robusto tauren.\n\nGli zoccoli intatti dimostrano che un cacciatore sa affrontare prede veloci che scalciano, prima di misurarsi con i predatori più letali di Kalimdor."}},faq={{q="Chi vuole gli Zoccoli di Zevra?",a="Sergra Darkthorn, una sciamana orca di Crocevia nelle Savane, chiede ai cacciatori quattro Zoccoli di Zevra come prova che sono pronti per prede più impegnative.",al={"chi ha bisogno di zoccoli","chi accetta zoccolo di zevra","zoccoli sergra"}},{q="Da dove provengono gli Zoccoli di Zevra?",a="Gli Zoccoli di Zevra provengono dai corridori zevra che pascolano nelle distese aperte a nord e a sud di Crocevia.",al={"dove trovare zoccoli","posizione zevra corridore","trovare zevra"}},{q="Perché le zevra sono pericolose da cacciare?",a="Le zevra possono colpire con forza con le zampe posteriori. Una zevra in corsa può atterrare un tauren adulto, anche se le zevra sono meno aggressive dei raptor o dei prowler.",al={"le zevra sono forti","forza del calcio della zevra","pericolo zevra"}},{q="Perché Sergra fa rintracciare ai cacciatori le zevra anziché bestie più feroci?",a="Sergra considera le zevra una sfida superiore ai plainstrider. Offrono ai nuovi arrivati un addestramento impegnativo ma sicuro, prima che affrontino creature davvero letali.",al={"perché cacciare le zevra","scopo dell'addestramento di sergra"}}},fx={["51f26e7e"]={q="Che cosa sono gli Zoccoli di Zevra?",a="Gli zoccoli di zevra sono robusti piedi solidi ricavati dagli equini selvatici striati che galoppano nelle savane di The Barrens. Sprigionano una forza enorme: un solo calcio può far barcollare un tauren adulto. Sono la prova tangibile della crescente abilità e resistenza di un cacciatore sotto il sole impietoso.",al={"che cosa sono gli zoccoli di zevra","zoccolo di zevra","informazioni sugli zoccoli di zevra"}}},fp="13,132,20.416.0,24.152.0,33.106.0,33.167.0,69.135.0"}
P.entries["npc:abercrombie"] = {n="Abercrombie",s="Vicino al Cimitero di Collecorvo, Abercrombie chiede ai viaggiatori di portargli provviste da Borgoscuro. Nella parte occidentale di Boscovespro, il vecchio eremita sembra logorato e tormentato dalla foresta.",h="Vicino al Cimitero di Collecorvo, Abercrombie chiede ai viaggiatori di portargli provviste da Borgoscuro.",kw={"abercrombie","abominio","borgoscuro","boscovespro","eliza","ghoulish effigy","collecorvo","the hermit"},ang={["class:Paladin"]="Come paladino, puoi vedere in Abercrombie come la sinistra corruzione della negromanzia si celi dietro le sembianze di un comune cittadino in cerca di carità.",["class:Warlock"]="Come stregone, puoi vedere nel sacrificio del cuore di Abercrombie fino a quali estremi autodistruttivi i mortali siano disposti a spingersi per esercitare la magia oscura.",["faction:Alliance"]="Gli eroi dell'Alleanza che aiutano il misero eremita forniscono inconsapevolmente i materiali per un assalto a Borgoscuro."},sec={{t="Il recluso di Collecorvo",b="Abercrombie vive in una baracca diroccata vicino al Cimitero di Collecorvo. Il declino di Boscovespro lo ha ridotto all'aspetto di un vecchio distrutto. Dice di cercare di sopravvivere ai terrori della foresta e chiede ai viaggiatori di portargli provviste, erbe e filo da Borgoscuro. A chi non conosce la storia della regione, sembra un'altra anima sfortunata abbandonata mentre la provincia cadeva in rovina."},{t="La follia dell'imbalsamatore",b="Abercrombie viveva un tempo a Collecorvo, dove era un alchimista rispettato e gentile. Quando la sua amata moglie, Eliza, morì, il dolore gli fece perdere il senno. Ricorse alle arti negromantiche proibite, si strappò il cuore e lo collocò nel petto senza vita di Eliza per riportarla in vita. Il rituale la trasformò in un mostro dalla fame insaziabile di carne vivente, e Abercrombie la tenne sepolta nel cimitero."},{t="Un inganno mostruoso",b="Abercrombie, noto nel folklore oscuro come l'Imbalsamatore, nutre un profondo rancore psicotico contro Borgoscuro e i suoi capi. Manda i viaggiatori disponibili a procurargli costole di ghoul, filo speciale e infusi caustici. Queste provviste sono gli ultimi componenti necessari per assemblare Stitches, un colossale abominio di carne cucita, creato per massacrare i Night Watch e devastare la cittadina."}},faq={{q="Chi è Abercrombie?",a="Abercrombie è un eremita che vive vicino al Cimitero di Collecorvo, a Boscovespro. Un tempo abile alchimista, perse il senno dopo la morte della moglie e divenne la figura negromantica nota come l'Imbalsamatore.",al={"chi è the hermit","storia di abercrombie","chi è abercrombie"}},{q="Perché Abercrombie vuole provviste da Borgoscuro?",a="Abercrombie dice di aver bisogno di provviste domestiche e filo per sopravvivere nelle terre selvagge. In realtà, inganna i viaggiatori affinché raccolgano i componenti necessari per assemblare Stitches, un mostruoso abominio.",al={"perché abercrombie ha bisogno di filo","provviste di abercrombie","cosa sta costruendo abercrombie"}},{q="Chi era Eliza?",a="Eliza era la moglie di Abercrombie. Dopo la sua morte, lui cercò di resuscitarla con la magia oscura, collocando il proprio cuore nel suo cadavere. Tornò come un famelico mostro non morto, e Abercrombie la tenne sepolta nel Cimitero di Collecorvo.",al={"eliza abercrombie","moglie di abercrombie","bride of the embalmer"}},{q="Cosa succede quando consegni la Note to the Mayor?",a="Lord Ello non riesce a leggere la Note, scritta in una lingua antica, così chiede a Sirra Von'indi di tradurla. La traduzione rivela che Abercrombie ha fatto qualcosa di indicibile. Dopo che Ello l'ha letta, il mostruoso Stitches avanza pesantemente lungo la strada da Collecorvo verso Borgoscuro.",al={"note to the mayor","cosa dice la nota","lettera di abercrombie"}},{q="Perché Abercrombie odia Borgoscuro?",a="Abercrombie non spiega mai il suo odio per Borgoscuro. Il dolore e la magia oscura lo fecero impazzire dopo la morte della moglie, e chiama beffardamente il sindaco Ello Ebonlocke un vecchio amico mentre manda la sua mostruosa creazione lungo la strada a distruggere la cittadina.",al={"perché abercrombie attacca borgoscuro","movente dell'imbalsamatore","vendetta di abercrombie"}},{q="Abercrombie è alleato del Flagello?",a="No. Abercrombie è un eremita solitario senza alcun legame con le armate del Re dei Lich.",al={"abercrombie è alleato del flagello","per chi lavora abercrombie"}}},fx={["5abf44f4"]={q="Perché Abercrombie vive vicino al Cimitero di Collecorvo?",a="Abercrombie vive in una baracca isolata poco a nord-est del Cimitero di Collecorvo, nella parte occidentale di Boscovespro, lontano da Borgoscuro. Si presenta come un innocuo eremita eccentrico e chiede ai viandanti di passaggio di procurargli provviste in città.",al={"perché abercrombie si trova qui","perché abercrombie è a collecorvo","motivo della posizione di abercrombie"}},a3c5130f={q="Perché Abercrombie è temuto in tutto Boscovespro?",a="Sebbene si finga un innocuo eremita, Abercrombie è in realtà la temibile figura nota come l'Imbalsamatore. I racconti locali e le storie per bambini narrano la sua discesa nella necromanzia folle: si strappò il cuore per rianimare la moglie defunta e trasformarla in un ghoul avido di carne. Il suo nome evoca l'orrore di mostruosità cucite proibite, scatenate contro i vivi.",al={"perché abercrombie è temuto","reputazione di abercrombie l'imbalsamatore","l'imbalsamatore di boscovespro"}}},fp="11,160,25.380.0,22.376.2,21.366.1,19.181.2,50.193.1,14.227.1,52.283.2,36.238.1,39.72.0"}
P.entries["npc:aelthalyste"] = {n="Aelthalyste",s="Nel War Quarter di Sepulcra, Aelthalyste insegna ai sacerdoti Reietti il potere dell'Ombra. Guida la loro disciplina e invia gli accoliti troll dai loro anziani a Orgrimmar.",h="Nel War Quarter di Sepulcra, Aelthalyste insegna ai sacerdoti Reietti il potere dell'Ombra.",kw={"aelthalyste","banshee","devouring plague","sacerdote","ombra","sepulcra","ur'kyo","war quarter"},ang={["class:Priest"]="Come sacerdote Reietto, trovi in Aelthalyste una maestra della tua dottrina, degli incantesimi oscuri e delle vie dell'Ombra.",["faction:Horde"]="Come membro dell'Orda, puoi vedere come il rispetto di Aelthalyste per gli insegnamenti di Ur'kyo aiuti a superare le divisioni culturali della coalizione.",["race:Troll"]="Come troll, Aelthalyste ti indirizza da Ur'kyo a Orgrimmar per apprendere i riti dei Puntascura.",["race:Undead"]="Come non morto, condividi la scelta dei Reietti di abbandonare la Sacra Luce delle vite passate per volgersi al potere concreto dell'Ombra."},sec={{t="Voce dell'Ombra Dimenticata",b="Aelthalyste addestra i sacerdoti Reietti al potere dell'Ombra. Molti sacerdoti di Azeroth venerano la Sacra Luce, ma i suoi allievi se ne sono allontanati. È risorta come banshee incorporea e condivide l'agonia spettrale e l'implacabile determinazione dei seguaci di Sylvanas Ventolesto. Dalla sua camera nel War Quarter di Sepulcra, chiama gli aspiranti sacerdoti da avamposti lontani affinché padroneggino le loro arti più oscure. Insegna loro a brandire la sofferenza come un'arma."},{t="Legami con l'Orda",b="Aelthalyste rispetta le tradizioni spirituali degli altri praticanti dell'Orda. Allontana gli iniziati troll dai suoi insegnamenti dell'Ombra e li invia oltre il mare da Ur'kyo a Orgrimmar, dove possono apprendere lo spiritualismo dei Puntascura. La sua deferenza permette agli incantatori dell'Orda di crescere nelle proprie tradizioni e rafforza i legami tra Kalimdor e Lordaeron."}},faq={{q="Chi è Aelthalyste?",a="Aelthalyste è una banshee e un'insegnante di spicco del clero dei Reietti. Nel War Quarter di Sepulcra, addestra i praticanti Reietti all'uso di Shadow Magic.",al={"storia di aelthalyste","chi è il sacerdote banshee","png aelthalyste"}},{q="Dove posso trovare Aelthalyste?",a="Aelthalyste si trova nel War Quarter sotto le rovine di Capital City, a Sepulcra. Altri istruttori Reietti si trovano nelle vicinanze.",al={"posizione di aelthalyste","dove si trova aelthalyste","trova aelthalyste"}},{q="In cosa credono i sacerdoti Reietti?",a="Molti sacerdoti Reietti credono che la Sacra Luce li abbia abbandonati nella non morte. Si sono allontanati dalla Luce che veneravano in vita per volgersi all'ombra, abbracciando l'oscurità, la forza di volontà e la disciplina personale.",al={"ombre dimenticate","religione dei sacerdoti reietti","culto delle ombre dimenticate"}},{q="Perché Aelthalyste manda i sacerdoti troll a Orgrimmar?",a="Aelthalyste invia i sacerdoti troll a Orgrimmar perché i loro legami con gli spiriti e l'ombra differiscono dalla dottrina dei Reietti. Rispetta questa differenza e manda gli accoliti troll ad addestrarsi con Ur'kyo, l'istruttore dei sacerdoti Puntascura nella Valle degli Spiriti.",al={"ur'kyo aelthalyste","perché allontanare i troll","missione troll aelthalyste"}},{q="Cosa insegna Aelthalyste?",a="Aelthalyste impartisce ai personaggi Reietti gli insegnamenti fondamentali dei sacerdoti e guida gli accoliti più esperti nei riti dei non morti. I suoi insegnamenti includono incantesimi come Touch of Weakness e Dark Sacrifice.",al={"addestramento sacerdoti aelthalyste","quali incantesimi insegna aelthalyste","abilità di aelthalyste"}},{q="Aelthalyste è fedele a Sylvanas?",a="Sì. Aelthalyste è una banshee di Sepulcra al servizio di Sylvanas Ventolesto. Si adopera per rafforzare i Reietti attraverso la padronanza della magia oscura.",al={"fazione di aelthalyste","è leale a sepulcra","lealtà della banshee"}}},fx={["71b5fa08"]={q="Perché Aelthalyste si trova a Sepulcra?",a="Aelthalyste risiede nel Quartiere della Guerra di Sepulcra per istruire e guidare chi pratica la magia dell'ombra. In qualità di sacerdotessa a capo del sacerdozio dei Reietti, supervisiona l'addestramento dei sacerdoti Reietti e convoca da lontano i discepoli più promettenti affinché possano padroneggiare i riti più oscuri della loro fede.",al={"perché aelthalyste si trova qui","scopo di aelthalyste a sepulcra","perché aelthalyste è nel quartiere della guerra"}},["84a14853"]={q="Che cosa vuole Aelthalyste?",a="Aelthalyste mira a rafforzare il sacerdozio dei Reietti e a renderlo più disciplinato. Si dedica a coltivare la magia dell'ombra tra i Reietti, richiamando i sacerdoti iniziati a Sepulcra per affinare i loro poteri oscuri e assicurandosi che gli alleati, come i sacerdoti troll, ricevano un addestramento adeguato dai propri anziani.",al={"obiettivi di aelthalyste","qual è l'obiettivo di aelthalyste","motivazione di aelthalyste"}},["61183540"]={q="Con chi è alleata Aelthalyste?",a="Aelthalyste serve i Reietti ed è una figura di spicco del loro sacerdozio. Mantiene stretti rapporti di collaborazione con gli addestratori di sacerdoti nelle terre dell'Orda e nutre rispetto reciproco per anziani dei Lanciascura come Ur'kyo, assicurandosi che gli studenti troll tornino dai propri maestri spirituali a Orgrimmar.",al={"legami di aelthalyste","con chi lavora aelthalyste","alleati di aelthalyste"}}},fp="11,176,29.448.0,19.344.0,19.157.0,29.136.0,33.195.0,53.247.0,28.182.0,33.146.0"}
P.entries["npc:agathelos-the-raging"] = {n="Agathelos il Rabbioso",s="Nelle profondità delle Gallerie di Lamaspina, Agathelos il Rabbioso è rinchiuso tra i tunnel spinosi. I verri spinosi venerano Agamaggan come loro dio e progenitore, e la grande stazza di Agathelos ha un significato spirituale. La sua corazza e la sua furia lo rendono una delle bestie più pericolose sotto le Savane Meridionali.",h="Nelle profondità delle Gallerie di Lamaspina, Agathelos il Rabbioso è rinchiuso tra i tunnel spinosi.",kw={"agamaggan","agathelos","cinghiale","death's head","verro spinoso","rabbioso","gallerie di lamaspina"},ang={["class:Druid"]="Come druido, tieni Agamaggan in grande considerazione come uno dei grandi Antichi caduti durante la Guerra degli Antichi. Vedere uno dei suoi colossali simili rinchiuso e furioso nelle Gallerie è desolante.",["class:Hunter"]="Come cacciatore, puoi ammirare la mole predatoria di Agathelos. La sua rabbia inesauribile lo rende una bestia da abbattere anziché domare.",["race:Tauren"]="Come tauren in sintonia con la terra, conosci le leggende di Agamaggan. La corruzione che i verri spinosi infliggono alle bestie della sua stirpe rivela il marciume che si diffonde nelle Savane."},sec={{t="Avatar del Grande Cinghiale",b="Agamaggan, il titanico cinghiale, è il dio e progenitore dei verri spinosi. Perciò, tra le tribù di Lamaspina, una bestia grande quanto Agathelos riveste un profondo significato spirituale. È alto circa il doppio di una lucertola del tuono delle Savane."},{t="Tenuto in Catene",b="I verri spinosi impediscono ad Agathelos di vagare liberamente per le Gallerie. Diverse guardie mantengono un campo davanti al breve tunnel cieco in cui è rinchiuso. Gli intrusi che superano quella barriera affrontano una bestia rabbiosa, resa ancora più temibile dalla sua furia."}},faq={{q="Perché Agathelos è così enorme?",a="Agathelos è un cinghiale corazzato colossale per natura, grande circa il doppio di una comune lucertola del tuono. La rabbia lo fa sembrare ancora più grande. I verri spinosi venerano Agamaggan come loro titanico dio cinghiale e progenitore, quindi una bestia della stazza di Agathelos riveste un grande significato spirituale.",al={"perché agathelos è grande","dimensioni di agathelos","cinghiale gigante savane"}},{q="Perché i verri spinosi lo tengono rinchiuso dietro una barriera?",a="I verri spinosi rinchiudono Agathelos in un breve tunnel dietro un campo mantenuto da diverse guardie. La barriera impedisce al mostruoso cinghiale rabbioso di vagare liberamente per le Gallerie.",al={"barriera di agathelos","perché agathelos è in gabbia","campo di forza agathelos"}},{q="Qual è il suo legame con Agamaggan?",a="Agamaggan è il grande Antico cinghiale e progenitore dei verri spinosi. La sua stirpe conferisce a un cinghiale gigantesco come Agathelos un grande significato spirituale per i verri spinosi.",al={"agathelos agamaggan","agathelos è un dio","figlio di agamaggan"}},{q="Quale tribù ha creato Agathelos?",a="Agathelos è una bestia, non una creatura artificiale. I verri spinosi Death's Head delle Gallerie di Lamaspina lo tengono in un tunnel sorvegliato nelle profondità dei rovi.",al={"chi ha creato agathelos","chi nutre agathelos","tribù di agathelos"}},{q="I cacciatori possono addomesticare Agathelos?",a="No. Agathelos è un mostro élite dalla pesante corazza, troppo pericoloso perché un cacciatore possa tenerlo sotto controllo.",al={"addomesticare agathelos","posso addomesticare agathelos","cacciatore agathelos"}}},fx={a8df9e57={q="Chi è Agathelos il Rabbioso?",a="Agathelos il Rabbioso è un colossale cinghiale corazzato custodito nelle profondità delle Gallerie di Lamaspina. Per i quilboar, il cui dio e progenitore Agamaggan era un cinghiale titanico, ha una notevole importanza spirituale. È alto all'incirca il doppio di un comune lucertolone del tuono e diventa ancora più mostruoso in battaglia.",al={"chi è agathelos","identità di agathelos","che cos'è agathelos il rabbioso"}},["28c36899"]={q="Da che parte sta Agathelos il Rabbioso?",a="Agathelos è una bestia, non un cospiratore. È tenuto dai quilboar delle Gallerie di Lamaspina, rinchiuso in un tunnel sorvegliato, e attacca chiunque si introduca nel suo recinto.",al={"fazione di agathelos","chi serve agathelos","da che parte sta agathelos"}},["38ca6f4f"]={q="Che cosa vuole Agathelos il Rabbioso?",a="Agathelos non ha grandi ambizioni né trame astute. È consumato da una furia puramente bestiale e vuole soltanto schiacciare, incornare e calpestare tutto ciò che entra nel suo recinto.",al={"che cosa vuole agathelos","motivazioni di agathelos","obiettivi di agathelos"}},be737a36={q="Perché Agathelos il Rabbioso è temuto?",a="Agathelos è temuto per la sua mole imponente e terrificante e per la sua furia incontrollabile. Già corazzato e massiccio per natura, quando si infuria diventa ancora più grande e feroce, tanto da poter schiacciare intere squadre d'incursori sotto i suoi zoccoli.",al={"perché agathelos è temuto","quanto è pericoloso agathelos","reputazione di agathelos"}}},fp="20,289,25.220.0,14.252.0,25.269.0,53.165.0,36.158.0,29.134.0,27.102.0"}
P.entries["npc:aggem-thorncurse"] = {n="Aggem Malaspina",s="Nelle Gallerie di Lamaspina, Aggem Malaspina porta il titolo di Death's Head Prophet. Quando viene minacciato, chiama in suo aiuto uno spirito di cinghiale.",h="Nelle Gallerie di Lamaspina, Aggem Malaspina porta il titolo di Death's Head Prophet.",kw={"aggem","kraul","verrospino","lamaspina","malaspina"},ang={["class:Priest"]="Come sacerdote, senti attribuire ad Aggem il titolo di profeta, un riflesso delle tradizioni spirituali dei verrospini.",["class:Shaman"]="Come sciamano, vedi Aggem evocare uno spirito di cinghiale in suo aiuto, un segno dello sciamanesimo dei verrospini.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere Durotar e Mulgore abbattendo difensori tenaci come Aggem Malaspina. I verrospini minacciano le Savane."},sec={{t="Il Death's Head Prophet",b="Aggem sorveglia una parte delle Gallerie di Lamaspina, dove dimora la tribù Death's Head. Il suo potere sciamanico gli permette di evocare uno spirito di cinghiale in battaglia. Lo spirito riflette la venerazione dei verrospini per Agamaggan."}},faq={{q="Chi è Aggem Malaspina?",a="Aggem è uno sciamano verrospino e Death's Head Prophet nelle Gallerie di Lamaspina.",al={"aggem malaspina","chi è aggem","aggem gallerie di lamaspina"}},{q="Dove si può trovare Aggem Malaspina?",a="Aggem si trova all'interno delle Gallerie di Lamaspina, nelle Savane Meridionali.",al={"posizione di aggem","dove si trova aggem","dove trovare aggem malaspina"}},{q="Quale spirito invoca Aggem?",a="Aggem evoca uno spirito di cinghiale perché combatta al suo fianco.",al={"spirito di aggem","spirito di cinghiale di aggem"}},{q="Come combatte Aggem in combattimento?",a="Aggem combatte con la magia sciamanica ed evoca uno spirito di cinghiale perché combatta al suo fianco.",al={"abilità di aggem","come combatte aggem"}},{q="Aggem Malaspina è affiliato a una specifica tribù di verrospini?",a="Aggem appartiene alla tribù Death's Head.",al={"tribù di aggem","a quale tribù appartiene aggem","verrospino di lamaspina"}}},fx={["0a149290"]={q="Perché Aggem Malaspina si trova qui?",a="Aggem si trova tra i quilboar della Zanna della Morte nelle Gallerie di Lamaspina, a difesa del territorio della sua tribù.",al={"perché aggem malaspina è nelle gallerie di lamaspina","perché aggem malaspina si trova lì"}},["32004356"]={q="A chi è legato Aggem Malaspina?",a="Appartiene alla tribù della Zanna della Morte e segue le tradizioni sciamaniche dei quilboar.",al={"legami di aggem malaspina","con chi è alleato aggem malaspina"}}},fp="16,125,24.193.0,24.70.0,36.61.0,33.46.0,31.77.0,62.40.0"}
P.entries["npc:ahanu"] = {n="Ahanu",s="Da Hewa's Armory, Ahanu aiuta i corrieri in arrivo a Picco del Tuono. Fabbrica e vende armature di cuoio per viaggiatori e giovani guerrieri in partenza attraverso Mulgore e le vaste pianure, e indica ai nuovi corrieri come orientarsi tra le alture.",h="Da Hewa's Armory, Ahanu aiuta i corrieri in arrivo a Picco del Tuono.",kw={"ahanu","hewa's armory","jahan pelle fine","armature in pelle","mulgore","picco del tuono"},ang={["race:Tauren"]="Se sei un giovane guerriero tauren in arrivo da Crocevia a bordo di un Wind Rider, da Ahanu trovi un'accoglienza familiare e pelli per il viaggio."},sec={{t="Mercante di Hewa's Armory",b="Ahanu fabbrica equipaggiamento di cuoio da Hewa's Armory, sull'altura inferiore di Picco del Tuono. Il suo amico Jahan Pelle Fine gli manda pelli da Crocevia, che lui trasforma in armature resistenti per i viaggiatori delle praterie di Kalimdor. I viaggiatori in arrivo da Crocevia a bordo di un Wind Rider possono trovarlo tra gli artigiani della città. Riceve le loro consegne e indirizza i messaggeri verso i punti di volo locali."}},faq={{q="Chi è Ahanu?",a="Ahanu è un mercante tauren che lavora da Hewa's Armory, sull'altura inferiore di Picco del Tuono. Vende armature di cuoio e aiuta i corrieri in arrivo da Crocevia.",al={"png ahanu","storia di ahanu","chi è ahanu"}},{q="Cosa vende Ahanu?",a="Ahanu vende armature di cuoio semplici, tra cui giubbe, cinture, stivali e bracciali. Cacciatori, ladri e giovani avventurieri possono usare questo equipaggiamento.",al={"merci di ahanu","oggetti di ahanu","mercante ahanu"}},{q="Dove posso trovarlo a Picco del Tuono?",a="Ahanu lavora all'interno di Hewa's Armory, sull'altura inferiore di Picco del Tuono. Altri armaioli, conciatori e fabbri d'armi lavorano nelle vicinanze.",al={"posizione di ahanu","dove si trova ahanu","mappa ahanu"}},{q="Quali missioni coinvolgono Ahanu?",a="In 'Ride to Picco del Tuono', i giovani avventurieri tauren portano merci ad Ahanu a bordo di un Wind Rider. Poi lui li rimanda da Tal, il maestro dei Wind Rider della città.",al={"missioni di ahanu","viaggio a picco del tuono ahanu"}}},fx={f9ab69c3={q="Da che parte sta Ahanu?",a="Ahanu è un membro leale dell'Orda e un fiero cittadino di Picco del Tuono. Opera alla luce del sole sotto il vessillo del Gran Capo Cairne Zoccolo Sanguinario, equipaggiando i cacciatori tauren, i druidi e i viaggiatori dell'Orda di passaggio in città.",al={"fazione di ahanu","ahanu fa parte dell'orda","chi serve ahanu"}},b68e223b={q="Perché Ahanu si trova qui?",a="Ahanu gestisce un negozio nell'Armeria di Hewa, sul rilievo inferiore di Picco del Tuono. È l'armaiolo del posto e fornisce robusto equipaggiamento di cuoio conciato a cacciatori e viandanti che esplorano le pianure di Mulgore e il resto del continente.",al={"perché ahanu è a picco del tuono","scopo di ahanu a picco del tuono","che cosa ha portato ahanu qui"}},c2a07e44={q="Che cosa vuole Ahanu?",a="Ahanu è soddisfatto del suo mestiere di mercante di cuoio e non desidera molto altro oltre a buoni affari e compagnia. Si dedica a fornire ai viaggiatori armature resistenti e si gode la compagnia degli altri abitanti della città.",al={"di che cosa ha bisogno ahanu","obiettivo di ahanu","motivazione di ahanu"}},b04a3d48={q="A chi è legato Ahanu?",a="Tra gli amici di Ahanu c'è Jahan Pelle Fine, un altro mercante tauren che si trova a Crocevia, a The Barrens. Jahan gli invia fasci di pelli fresche, che Ahanu lavora per ricavarne articoli di cuoio a Picco del Tuono.",al={"amici di ahanu","chi conosce ahanu","compagni di ahanu"}}},fp="5,230,25.392.0,13.146.0,21.135.0,38.126.0,26.150.0"}
P.entries["npc:aku-mai"] = {n="Aku'mai",s="Negli Abissi di Fondocupo, Aku'mai infesta il Tempio di Elune sommerso lungo la Spiaggia di Zoram. La corruzione di un Dio Antico ne contaminò il sacro Pozzo della Luna, e Aku'mai emerse dalle acque come servitrice del Dio Antico. Il Martello del Crepuscolo sacrifica innocenti ad Aku'mai in cambio di potere.",h="Negli Abissi di Fondocupo, Aku'mai infesta il Tempio di Elune sommerso lungo la Spiaggia di Zoram.",kw={"aku'mai","akumai","fondocupo","abissi","idra","kelris","dio antico","zoram"},ang={["class:Druid"]="Come druido, vedi la corruzione innaturale di Aku'mai alterare le acque costiere di Valtetra. Devono essere purificate per ripristinare l'equilibrio naturale.",["class:Priest"]="Come sacerdote, vedi in Aku'mai e nel Martello del Crepuscolo l'incarnazione della corruzione degli Dei Antichi, contrapposta agli insegnamenti della Sacra Luce e di Elune.",["race:NightElf"]="Come Elfo della Notte, vedi Aku'mai profanare il santuario più interno di un tempio in rovina, un tempo consacrato a Elune. Un luogo sacro è diventato un covo di corruzione."},sec={{t="Il Flagello della Spiaggia di Zoram",b="Gli Abissi di Fondocupo un tempo erano un grande Tempio di Elune. Poi la corruzione di un Dio Antico ne contaminò il sacro Pozzo della Luna, e Aku'mai emerse dalle acque. La gigantesca idra serve il Dio Antico. Ora Aku'mai dimora nelle rovine sommerse del tempio degli elfi della notte, avvelenando con la sua malvagità le acque lungo la Spiaggia di Zoram."},{t="Servitore dell'Oscurità Primordiale",b="La presenza di Aku'mai attirò il Martello del Crepuscolo nelle caverne sotterranee. Il Signore del Crepuscolo Kelris guida i cultisti, che si sono alleati con i naga per occupare il tempio sommerso. Lì sacrificano innocenti ad Aku'mai in cambio di potere."}},faq={{q="Cos'è Aku'mai?",a="Aku'mai è un'antica idra a tre teste al servizio di un Dio Antico. Emerse dalle acque contaminate degli Abissi di Fondocupo e dimora nelle sale sommerse del tempio.",al={"chi è akumai","storia di akumai","che tipo di mostro è akumai"}},{q="Dove vive Aku'mai?",a="Aku'mai vive nelle grotte sommerse degli Abissi di Fondocupo, un Tempio di Elune in rovina lungo la Spiaggia di Zoram, nella parte nordoccidentale di Valtetra.",al={"posizione di akumai","dove si trova akumai","dove posso trovare akumai"}},{q="Perché il Martello del Crepuscolo nutre Aku'mai?",a="Il Martello del Crepuscolo venera Aku'mai come servitrice degli Dei Antichi. Guidati dal Signore del Crepuscolo Kelris, i cultisti sacrificano innocenti ad Aku'mai in cambio di potere oscuro.",al={"perché i cultisti nutrono akumai","kelris akumai","martello del crepuscolo akumai"}},{q="Quali poteri possiede Aku'mai?",a="Aku'mai è immensa, con molteplici teste che azzannano, e gode dell'oscuro favore degli Dei Antichi. In battaglia, si infuria e avvolge chi le sta vicino in nubi di veleno.",al={"poteri di akumai","akumai è magico","idra del vuoto"}},{q="Aku'mai è un Dio Antico?",a="No. Aku'mai è un'idra primordiale al servizio di un Dio Antico. La sua presenza malvagia attirò il Martello del Crepuscolo, che si radunò attorno a lei per venerarla.",al={"akumai è un dio antico","akumai è un dio"}},{q="Perché gli avventurieri si addentrano negli abissi per ucciderla?",a="Se lasciate senza freno, la ferocia di Aku'mai e la devozione della setta minacciano di scatenare un male catastrofico su Valtetra e Kalimdor. Le autorità dell'Alleanza e dell'Orda cercano di porre fine al Martello del Crepuscolo e uccidere l'orrore nel cuore del tempio.",al={"perché uccidere akumai","blackfathom villainy akumai","minaccia di akumai"}}},fx={["055a774d"]={q="Da che parte sta Aku'mai?",a="Aku'mai serve un Dio Antico e non è fedele alle razze mortali. Il culto del Martello del Crepuscolo adora la bestia e le sacrifica innocenti in cambio di potere oscuro.",al={"fazione di aku'mai","chi serve aku'mai","fedeltà di aku'mai"}},["7b9e18bb"]={q="Che cosa vuole Aku'mai?",a="Aku'mai è una bestia feroce, non un cospiratore. Servo di un Dio Antico, si aggira nelle acque contaminate degli Abissi di Fondocupo, e i cultisti del Martello del Crepuscolo che gli sacrificano innocenti sperano di riportare l'epoca in cui gli Dei Antichi dominavano il mondo.",al={"obiettivo di aku'mai","che cosa desidera aku'mai","scopo di aku'mai"}},["6cae52d5"]={q="Perché Aku'mai si trova qui, negli Abissi di Fondocupo?",a="Aku'mai emerse dalle acque del tempio sommerso quando la corruzione di un Dio Antico risalì dalle profondità della terra e contaminò il suo Pozzo Lunare sacro. Le sale sommerse degli Abissi di Fondocupo offrono ora al culto del Martello del Crepuscolo un rifugio oscuro e acquatico, dove può nascondersi e adorare la bestia in segreto.",al={"perché aku'mai è a fondocupo","come è arrivato aku'mai","aku'mai spiaggia di zoram"}},ba41fb22={q="A chi è legato Aku'mai?",a="Aku'mai è al servizio di un Dio Antico. Negli Abissi di Fondocupo, il Martello del Crepuscolo, guidato dal Signore del Crepuscolo Kelris, adora la bestia e le sacrifica innocenti in cambio di potere.",al={"legami di aku'mai","chi controlla aku'mai","aku'mai e kelris"}},["989c4b42"]={q="Perché Aku'mai è tanto temuto?",a="Aku'mai è un'idra gigantesca a tre teste, al servizio di un Dio Antico, emersa dalle acque contaminate della Spiaggia di Zoram. I racconti della sua ferocia e dell'adorazione oscura che ispira nel Martello del Crepuscolo ne fanno uno dei mali più temuti che si aggirano lungo la costa di Valtetra.",al={"perché aku'mai è temuto","reputazione di aku'mai","aku'mai è pericoloso"}}},fp="7,265,27.313.0,34.231.1,16.161.0,24.136.0,45.156.0,33.157.0,22.124.0,53.241.0"}
P.entries["npc:alamar-grimm"] = {n="Alamar Grimm",s="A Forgiamara, nella Valle Crestafredda, Alamar Grimm insegna ai giovani gnomi a usare la magia vile. Dalla caduta di Gnomeregan, nutre rancore verso i forestieri e intende insegnare ai suoi allievi a evocare un demonietto.",h="A Forgiamara, nella Valle Crestafredda, Alamar Grimm insegna ai giovani gnomi a usare la magia vile.",kw={"alamar","forgiamara","crestafredda","gnomeregan","grimm","demonietto","istruttore","stregone"},ang={["class:Warlock"]="Come stregone gnomo che muove i primi passi nella Valle Crestafredda, impari i tuoi primi incantesimi da Alamar Grimm. Devi dimostrare il tuo valore per ottenere il tuo primo demonietto.",["race:Gnome"]="Come gnomo, potresti condividere l'amarezza degli esuli che si sentono abbandonati dai loro alleati mentre Gnomeregan resta nelle mani dei trogg."},sec={{t="Un amaro esilio",b="A Forgiamara, Alamar Grimm prova ancora rancore per la caduta di Gnomeregan. Mentre gli altri gnomi della Valle Crestafredda si dedicano alla ripresa e all'ingegneria, lui diffida dei comuni avventurieri e persino dei nani di Forgiardente che ospitano il suo popolo. Borbotta che i loro alleati si preoccupano più della diplomazia con gli umani che di riconquistare la città caduta. Alamar cerca chi condivide la sua convinzione che il suo popolo possa aver bisogno di un potere spietato."},{t="Maestro delle arti oscure",b="Alamar Grimm guida i giovani gnomi che si avvicinano alla magia vile. Un Tainted Memorandum vale una rara accoglienza calorosa, e lui comincia a insegnare gli incantesimi di base. Prima di condividere le pericolose conoscenze necessarie per vincolare un demonietto, esige una prova della resistenza magica e fisica di ogni novizio. Li manda a recuperare gli strani amuleti di piume portati dai novizi troll Frostmane della zona."}},faq={{q="Chi è Alamar Grimm?",a="Alamar Grimm addestra gli stregoni gnomi a Forgiamara, nella Valle Crestafredda. Insegna ai nuovi allievi le basi della magia vile e come evocare il loro primo demonietto.",al={"alamar grimm","chi è alamar","istruttore degli stregoni gnomo forgiamara"}},{q="Perché Alamar Grimm ce l'ha con i nani?",a="Alamar nutre rancore verso i nani di Forgiardente perché crede che per loro riconquistare Gnomeregan conti meno dell'alleanza con gli umani. Sebbene ospitino gli gnomi sfollati, ritiene che non diano la priorità alla patria del suo popolo.",al={"perché alamar odia i nani","opinione di alamar sui nani","perché è arrabbiato"}},{q="Cosa chiede di fare Alamar Grimm ai nuovi stregoni?",a="Alamar Grimm chiede agli stregoni novizi di raccogliere amuleti di piume dai novizi troll Frostmane della zona. Usa gli amuleti per mettere alla prova la loro resistenza e abilità magica prima di insegnare loro a evocare un demonietto.",al={"missione di alamar grimm per il demonietto","missione degli amuleti di piume","amuleti dei crin fredda stregone"}}},fx={["04c944ae"]={q="Da che parte sta Alamar Grimm?",a="Alamar Grimm è fermamente dalla parte degli gnomi esiliati, anche se nutre un forte rancore nei confronti dei loro attuali alleati. Mentre i nani accolgono gli gnomi sfollati a Dun Morogh, Alamar serba risentimento verso i capi di Forgiardente, convinto che diano la precedenza ai legami con gli umani lontani rispetto alla riconquista di Gnomeregan. Opera nell'Alleanza solo per ricostruire la forza degli gnomi alle proprie condizioni.",al={"fazione di alamar grimm","fedeltà di alamar grimm","per chi combatte alamar grimm"}},["949ab41a"]={q="Che cosa vuole Alamar Grimm?",a="Alamar vuole nientemeno che riconquistare Gnomeregan e rendere il suo popolo più forte attraverso le arti magiche oscure. Considera gli avventurieri comuni dei fallimenti inefficaci, incapaci di impedire la caduta della città, e cerca di formare stregoni disciplinati e capaci, dotati della vera forza magica e fisica necessaria a riprendersi la loro patria.",al={"obiettivi di alamar grimm","che cosa vuole alamar","motivazioni di alamar grimm"}},["1846448c"]={q="Perché Alamar Grimm si trova nella Valle Crestafredda?",a="Dopo la tragica caduta di Gnomeregan, Alamar cercò rifugio con gli altri sopravvissuti nella sicurezza della Valle Crestafredda. Di stanza nei pressi di Forgiamara, fa da mentore e addestratore agli gnomi appena arrivati che si sentono attratti dalla magia vile: mette alla prova il loro potenziale e li prepara con gli incantesimi oscuri necessari per affrontare il difficile cammino che li attende.",al={"perché alamar grimm è qui","perché alamar è a forgiamara","scopo di alamar grimm qui"}}},fp="12,196,14.402.0,23.366.0,20.142.0,41.228.0,46.194.0"}
P.entries["npc:alanndarian-nightsong"] = {n="Alanndarian Cantanotte",s="Ad Auberdine, Alanndarian Cantanotte si prende cura della fauna malata di Rivafosca. Collabora con i viaggiatori per alleviare i mali che si diffondono nella regione, soprattutto tra i cervi.",h="Ad Auberdine, Alanndarian Cantanotte si prende cura della fauna malata di Rivafosca.",kw={"alanndarian","auberdine","cura","rivafosca","kaldorei","cantanotte","strider","fauna selvatica"},ang={["class:Druid"]="Come druido, condividi con Alanndarian la ricerca di contaminazioni nelle acque e l'impegno a curare le creature avvelenate in tutta Rivafosca.",["class:Hunter"]="Come cacciatore, puoi aiutare Alanndarian a rintracciare le zampalunghe selvatiche e la selvaggina sofferente interpretando le tracce degli animali.",["faction:Alliance"]="Ai viaggiatori dell'Alleanza che arrivano ad Auberdine, Alanndarian aiuta a comprendere lo stato precario della natura selvaggia del Kalimdor settentrionale.",["race:NightElf"]="Per te che sei un Elfo della Notte, la cura di Alanndarian per la foresta e la sua fauna corrotta riflette gli ideali di preservazione dei kaldorei."},sec={{t="Una custode ad Auberdine",b="Dall'insediamento costiero di Auberdine, Alanndarian Cantanotte veglia sulla fauna di Rivafosca. La contaminazione del suolo e delle acque ha reso le creature degli antichi boschi malate e stranamente aggressive. Cerca modi per alleviare le loro sofferenze e restituire loro le forze."},{t="Curare i colpiti e i malati",b="Alanndarian Cantanotte cerca ciò che fa ammalare gli animali di Rivafosca. Raccoglie piante e studia le fonti d'acqua della regione, poi prepara unguenti e pozioni curative. I viaggiatori la aiutano a somministrare queste cure alle creature malate, nella speranza di impedire che la corruzione sopraffaccia la fauna."}},faq={{q="Chi è Alanndarian Cantanotte?",a="Da Auberdine, Alanndarian Cantanotte si prende cura della fauna sofferente di Rivafosca. Cerca rimedi a base di erbe contro la malattia innaturale che si diffonde lungo la costa.",al={"alanndarian","chi è alanndarian cantanotte","storia di alanndarian cantanotte"}},{q="Dove si trova Alanndarian Cantanotte?",a="Alanndarian Cantanotte vive ad Auberdine, il principale insediamento degli Elfi della Notte sulla costa nebbiosa di Rivafosca.",al={"posizione di alanndarian","dove si trova alanndarian","trovare alanndarian cantanotte"}},{q="Quali compiti chiede di svolgere agli avventurieri?",a="Alanndarian chiede ai viaggiatori di individuare le fonti della malattia, raccogliere ingredienti curativi e somministrare rimedi agli animali malati, come i cervi sofferenti.",al={"missioni di alanndarian","missioni animali malati auberdine","cosa vuole alanndarian"}},{q="È imparentata con altri Cantanotte?",a="Altri Elfi della Notte portano il nome Cantanotte, ma nessun legame noto conferma che Alanndarian sia loro parente. Dedica le sue giornate alla natura selvaggia di Rivafosca.",al={"famiglia cantanotte","relazione mastro cantanotte","falara cantanotte"}},{q="Perché le creature di Rivafosca sono malate?",a="L'acqua inquinata delle Cascate di Altafonte, principale fonte d'acqua potabile di Rivafosca, ha fatto ammalare i cervi in tutta la regione. Alanndarian sospetta che sia all'opera anche una contaminazione più profonda.",al={"perché gli animali di rivafosca sono malati","zampalunghe corrotte rivafosca","piaga di rivafosca"}},{q="Può addestrare famigli zampelunghe?",a="Sebbene le voci le attribuiscano una grande conoscenza delle zampalunghe, Alanndarian non addestra gli animali addomesticati dai cacciatori. La sua attenzione resta rivolta alle popolazioni selvatiche.",al={"addestratore di zampelunghe","addestramento strider auberdine","addestrare il mio strider"}}},fx={["04324614"]={q="Da che parte sta Alanndarian Cantanotte?",a="È fermamente dalla parte degli elfi della Notte di Darnassus e dell'Alleanza in generale. Di stanza ad Auberdine, lavora direttamente per proteggere la fauna selvatica di Darkshore e aiuta i viaggiatori fedeli alla causa dei Kaldorei.",al={"fazione di alanndarian cantanotte","alanndarian cantanotte è dell'alleanza o dell'orda"}},d3838107={q="Che cosa vuole Alanndarian Cantanotte?",a="Alanndarian si dedica a comprendere e a porre rimedio agli strani malanni che affliggono la fauna locale. Cerca aiuto per scoprirne l'origine e raccogliere gli ingredienti necessari a preparare rimedi che guariscano le creature corrotte di Darkshore.",al={"obiettivo di alanndarian cantanotte","che cosa cerca di fare alanndarian"}},["209c0886"]={q="Perché Alanndarian Cantanotte si trova a Darkshore?",a="Ha scelto come dimora la città portuale di Auberdine per vegliare sulle terre selvagge di Darkshore. Da qui tiene d'occhio la corruzione dilagante che turba la fauna della regione e coordina gli sforzi per ristabilire l'equilibrio della terra.",al={"perché alanndarian è ad auberdine","motivo di alanndarian a darkshore"}}},fp="21,181,24.266.0,29.294.0,29.155.0,41.99.0,47.144.0,35.149.0,40.172.0,31.149.0"}
P.entries["npc:althea-ebonlocke"] = {n="Althea Ebonlocke",s="A Borgoscuro, Althea Ebonlocke guida la Night Watch contro gli orrori di Boscovespro. Parente del borgomastro Ello Ebonlocke, protegge una regione isolata rimasta senza le truppe regolari di Roccavento.",h="A Borgoscuro, Althea Ebonlocke guida la Night Watch contro gli orrori di Boscovespro.",kw={"althea","comandante","borgoscuro","boscovespro","ebonlocke","milizia","mor'ladim","the night watch","stitches"},ang={["class:Paladin"]="Come paladino, puoi aiutare Althea a dare pace alle anime inquiete sulle cupe strade di Boscovespro, alleviando parte dell'angoscia spirituale che grava sulla sua milizia.",["class:Warrior"]="Come guerriero, potresti apprezzare il comando severo e pragmatico di Althea. Dà valore alla disciplina e ai combattenti disposti a mantenere la posizione contro forze soverchianti.",["faction:Alliance"]="Althea incarna la cupa determinazione dell'Alleanza sulle frontiere dimenticate, tenendo unito il regno dove gli eserciti della corona si sono ritirati."},sec={{t="Comandante dei Watch",b="Althea Ebonlocke dirige la difesa di Borgoscuro mentre il borgomastro Ello Ebonlocke, suo parente, governa dal Municipio. Roccavento non ha inviato truppe reali a proteggere Boscovespro, così gli abitanti hanno formato la Night Watch. Sotto il saldo comando di Althea, i suoi volontari pattugliano le strade nebbiose e impediscono a scheletri non morti, lupi feroci e ragni di invadere i margini della cittadina."},{t="Una cittadina sull'orlo del baratro",b="Althea sa che la sua milizia non può affrontare i pericoli da sola. Le reclute scarseggiano e la Watch continua a perderne, così ingaggia mercenari e viaggiatori di passaggio per ridurre le minacce vicino a Borgoscuro. Dirige le operazioni contro ghoul e scheletri nei quieti e desolati cimiteri della foresta. Nel frattempo, presta attenzione alle voci più oscure provenienti dalle profondità dei boschi."},{t="Tragedie della foresta",b="Althea coordina la ricerca delle più grandi piaghe di Boscovespro e gli sforzi per distruggerle. Aiuta a svelare il cupo destino di Stalvan Mistmantle e cerca risposte all'irrequieto vagare di Mor'Ladim, il cavaliere caduto Morgan Ladimore.\n\nQuando Abercrombie manda la mostruosa abominazione Stitches lungo la strada principale, la Night Watch di Althea si schiera sulla strada per affrontarla."}},faq={{q="Chi è Althea Ebonlocke?",a="Althea Ebonlocke comanda la Night Watch, la milizia di Borgoscuro a Boscovespro. Organizza la difesa della regione contro i non morti e le bestie in agguato nell'ombra.",al={"chi è althea","comandante serranero","chi è il comandante dei the night watch"}},{q="Cos'è la The Night Watch?",a="La Night Watch è una milizia volontaria formata dai cittadini di Borgoscuro. Con un sostegno militare quasi nullo da Roccavento, gli abitanti pattugliano le strade sotto il comando di Althea e combattono gli orrori nei boschi.",al={"cos'è la the night watch","chi sono i the night watch","milizia di borgoscuro"}},{q="Qual è il legame di parentela tra Althea e il borgomastro Ello Ebonlocke?",a="Althea è parente del borgomastro Ello Ebonlocke, che governa Borgoscuro dal Municipio. Lei comanda la milizia sul campo.",al={"parente di ello ebonlocke","althea è la figlia di ello","famiglia althea"}},{q="Perché Roccavento non aiuta Althea a difendere Borgoscuro?",a="Le risorse di Roccavento sono sotto pressione e, con re Varian Wrynn scomparso, la House of Nobles ha in gran parte trascurato i territori periferici del regno. Borgoscuro non riceve quasi né soldati né aiuti, così Althea si affida a volontari locali e avventurieri indipendenti.",al={"perché niente guardie di roccavento","supporto di roccavento a boscovespro","dove sono i soldati"}},{q="Quali missioni offre il Comandante Althea?",a="Althea invia gli avventurieri a caccia di lupi, mostri scheletrici e ghoul in tutta Boscovespro. Aiuta anche a indagare sulla Legend of Stalvan e ad affrontare il terrore errante Mor'Ladim.",al={"missioni di althea","serie di missioni the night watch"}},{q="Cosa fa Althea quando Stitches attacca Borgoscuro?",a="Quando Stitches, l'abominazione cucita da Abercrombie, avanza pesantemente lungo la strada verso Borgoscuro, le guardie della Night Watch di Althea si schierano per affrontarla. Senza l'aiuto degli avventurieri, il mostro può travolgerle.",al={"althea stitches","chi combatte stitches","borgoscuro sotto attacco"}}},fx={["4a666294"]={q="Da che parte sta la Comandante Althea Serranero?",a="La Comandante Althea è fermamente dalla parte degli abitanti di Borgoscuro e dell'Alleanza. Roccavento ha in gran parte abbandonato Boscovespro al suo destino ombroso, ma Althea si rifiuta di abbandonare la sua casa. Guida The Night Watch, una milizia locale allo stremo, votata a tenere a bada le bestie feroci, i morti inquieti e gli orrori incombenti che minacciano di cancellare la città dalla mappa.",al={"fazione di althea ebonlocke","per chi combatte althea","althea è dell'alleanza"}},["37e849b9"]={q="Che cosa vuole la Comandante Althea Serranero?",a="Il suo obiettivo principale è la sopravvivenza di Borgoscuro. In assenza di regolari rinforzi dell'esercito, Althea si adopera senza sosta per tenere a bada le terre selvagge che avanzano. Guida The Night Watch contro gli orrori scheletrici in agguato, i lupi rabbiosi e i ragni, e cerca attivamente avventurieri coraggiosi che eliminino le minacce mortali nascoste tra le ombre dei boschi prima che facciano strage degli abitanti, già allo stremo.",al={"che cosa vuole althea","obiettivo di althea ebonlocke","missione di althea a boscovespro"}},["288c0322"]={q="Perché la Comandante Althea Serranero si trova a Borgoscuro?",a="Boscovespro è la sua casa e il suo dovere. Parente del sindaco Ser Ello Serranero, resta nella piazza cittadina per guidare The Night Watch dal cuore dell'insediamento. Invece di fuggire al sicuro a Roccavento, Althea rimane in prima linea per coordinare le pattuglie e radunare ogni viaggiatore capace di difendere i confini.",al={"perché althea è a borgoscuro","perché la comandante althea è qui","luogo in cui si trova althea ebonlocke"}}},fp="16,191,22.368.0,19.358.0,21.381.1,24.164.0,24.214.0,46.126.0,53.263.0,40.179.0,52.215.1"}
P.entries["npc:altsoba-ragetotem"] = {n="Altsoba Totem Rabbioso",s="All'Accampamento di Sanguemarcio, Altsoba Totem Rabbioso equipaggia i viaggiatori dell'Orda per i boschi contaminati di Vilbosco. Il fabbro d'armi tauren offre mazze, bastoni e asce.",h="All'Accampamento di Sanguemarcio, Altsoba Totem Rabbioso equipaggia i viaggiatori dell'Orda per i boschi...",kw={"altsoba","accampamento di sanguemarcio","vilbosco","totem rabbioso","tauren","mercante","fabbro d'armi"},ang={["faction:Horde"]="Come agente dell'Orda, puoi contare su Altsoba per i rifornimenti bellici mentre mantieni la posizione in una delle regioni più corrotte di Kalimdor.",["race:Tauren"]="Come tauren, condividi con Altsoba il retaggio dei Totem Rabbioso e la fermezza che il suo popolo porta in una terra afflitta dalla contaminazione demoniaca."},sec={{t="Armaiolo dell'Accampamento di Sanguemarcio",b="Dall'Accampamento di Sanguemarcio, Altsoba Totem Rabbioso equipaggia esploratori e viaggiatori dell'Orda diretti verso i boschi corrotti di Vilbosco. L'avamposto sorge nel cuore della foresta, tra corruzione demoniaca e fauna contaminata. Mantenere il flusso dei rifornimenti fin lì è una dura necessità. Altsoba offre robuste asce a mezzaluna e pesanti magli da guerra, affinché i guerrieri che si addentrano nei boschi corrotti abbiano armi a disposizione."}},faq={{q="Chi è Altsoba Totem Rabbioso?",a="Altsoba Totem Rabbioso è un mercante tauren all'Accampamento di Sanguemarcio, l'accampamento dell'Orda a Vilbosco. Fornisce armi pesanti di base ai viaggiatori e ai difensori che affrontano la valle contaminata.",al={"chi è altsoba","altsoba totem rabbioso","tauren all'accampamento di sanguemarcio"}},{q="Cosa vende Altsoba?",a="Altsoba vende comuni armi da mischia, tra cui bastoni da battaglia, mazze ferrate, magli da guerra e asce. Offrono acciaio affidabile a chi si avventura nelle profondità di Vilbosco.",al={"merci di altsoba","oggetti del mercante altsoba","quali armi vende altsoba"}},{q="Dove posso trovare Altsoba Totem Rabbioso?",a="Altsoba Totem Rabbioso si trova all'Accampamento di Sanguemarcio, lungo le rupi che dominano le acque malsane e le radure contaminate di Vilbosco.",al={"posizione di altsoba","dove si trova altsoba","posizione del mercante dell'accampamento di sanguemarcio"}}},fp="17,150,26.379.0,25.177.0,23.164.0,35.123.0"}
P.entries["npc:alyissia"] = {n="Alyissia",s="Ad Aldrassil, Alyissia insegna ai giovani Elfi della Notte a combattere con forza e disciplina. Le sue lezioni preparano i guerrieri a difendere il giovane Albero del Mondo.",h="Ad Aldrassil, Alyissia insegna ai giovani Elfi della Notte a combattere con forza e disciplina.",kw={"aldrassil","alyissia","elfo della notte","vallombra","teldrassil","istruttore dei guerrieri"},ang={["class:Warrior"]="Se sei un guerriero Elfo della Notte, Alyissia è la tua prima mentore. Ti insegna i primi assetti e la disciplina marziale prima che tu ti avventuri più lontano nelle terre selvagge di Teldrassil.",["race:NightElf"]="Come Elfo della Notte, puoi imparare da Alyissia la disciplina marziale dei kaldorei in prima linea. I suoi insegnamenti ti preparano a difendere le radici di Aldrassil dalla corruzione."},sec={{t="Mentore Marziale di Vallombra",b="All'interno di Aldrassil, Alyissia addestra i giovani Elfi della Notte a combattere con acciaio e scudo. Imparano a seguire un percorso distinto dalla magia della natura e dal sacerdozio. Le forze kaldorei sono note per le Sentinelle e i furtivi arcieri, ma i pericoli di Kalimdor richiedono anche guerrieri capaci di tenere la prima linea. Creature selvagge e grell corrotti si addentrano a Vallombra, dove Alyissia insegna la furia in battaglia, gli assetti e la resistenza."}},faq={{q="Chi è Alyissia?",a="Alyissia addestra i nuovi guerrieri Elfi della Notte ad Aldrassil, nel cuore di Vallombra. Impartisce loro le prime lezioni e semplici esercizi marziali mentre iniziano l'addestramento a Teldrassil.",al={"chi è alyissia","alyissia png","cosa fa alyissia"}},{q="Dove posso trovare Alyissia?",a="Alyissia si trova al piano terra, all'interno del grande tronco cavo di Aldrassil, nel cuore di Vallombra a Teldrassil.",al={"posizione di alyissia","dove si trova alyissia","trova alyissia"}},{q="Quali missioni offre Alyissia?",a="Alyissia riceve il Sigillo Semplice portato dai nuovi guerrieri Elfi della Notte. Il sigillo li presenta alla loro istruttrice dei guerrieri ad Aldrassil.",al={"missioni di alyissia","missioni da alyissia"}}},fx={ce80cb6f={q="Da che parte sta Alyissia?",a="Alyissia è fermamente dalla parte degli elfi della Notte di Darnassus e dell'Alleanza in generale. Di stanza ad Aldrassil, nel cuore di Vallombra, serve il suo popolo insegnando i fondamenti del combattimento e del dovere ai giovani guerrieri elfi della Notte più promettenti, contribuendo così a proteggere Teldrassil dalle minacce circostanti.",al={"fazione di alyissia","chi serve alyissia","alyissia è dell'alleanza"}},["6cc138aa"]={q="Perché Alyissia si trova qui?",a="Alyissia è di stanza ad Aldrassil per guidare i guerrieri elfi della Notte appena risvegliati e aspiranti che muovono i primi passi a Vallombra. Si assicura che chi impugna le armi possieda la disciplina, le tecniche di combattimento e la determinazione necessarie a difendere il proprio appartato rifugio boschivo.",al={"perché alyissia è ad aldrassil","scopo di alyissia a vallombra","che cosa fa qui alyissia"}},["8fbe341c"]={q="Che cosa vuole Alyissia?",a="Alyissia cerca reclute capaci che possano apprendere le arti del combattimento marziale e dimostrare il proprio valore. Vuole che i guerrieri in arrivo affinino la disciplina e le abilità marziali, così da proteggere la loro dimora boschiva e aiutare i loro simili in tutta Teldrassil.",al={"obiettivi di alyissia","di che cosa ha bisogno alyissia","motivazioni di alyissia"}}},fp="8,148,28.406.0,16.182.0,26.112.0,32.127.0"}
P.entries["npc:amber-kearnen"] = {n="Amber Kearnen",s="Nelle Marche Occidentali, Amber Kearnen sorveglia la Fratellanza dei Defias per conto dell'SI:7. Dal suo nascondiglio, ne segue le attività illecite per conto del Maestro Mathias Shaw.",h="Nelle Marche Occidentali, Amber Kearnen sorveglia la Fratellanza dei Defias per conto dell'SI:7.",kw={"amber","defias","kearnen","klaven mortwake","klaven's tower","mathias shaw","ladro","si:7","marche occidentali"},ang={["class:Rogue"]="Come ladro dell'Alleanza, puoi contare sull'Agente Kearnen come contatto sul campo mentre pianifichi la tua infiltrazione a Klaven's Tower.",["faction:Alliance"]="Come membro dell'Alleanza, puoi rivolgerti a Kearnen in qualità di agente sotto copertura di Roccavento nelle Marche Occidentali. Agisce contro la Fratellanza dei Defias senza allarmare la popolazione."},sec={{t="Occhi sulla torre",b="Lontano dal Forte di Roccavento, Amber Kearnen svolge ricognizioni per l'SI:7 nelle Marche Occidentali. Sorveglia una torre abbandonata occupata dalla Fratellanza dei Defias. Il Maestro Mathias Shaw dirige il suo lavoro. Kearnen istruisce gli agenti sotto copertura inviati a sventare le minacce dei Defias e raccogliere informazioni nelle campagne contese."},{t="Un incarico mortale",b="Amber Kearnen sorveglia Klaven Mortwake, un Defias rifugiatosi nella torre a sud-est di Guardiacolle. Dopo settimane di appostamenti, informa i ladri incaricati di infiltrarsi sulle strane guardie disumane arrivate con un carico da Boscovespro. Li manda a rubare la Chiave della Torre, entrare nella torre e scoprire cosa contiene il forziere di Boscovespro, incluso il diario di Klaven. La sua pazienza e i suoi appunti accurati aiutano le operazioni segrete della Corona contro i Defias."}},faq={{q="Chi è Amber Kearnen?",a="Amber Kearnen lavora per l'SI:7, la divisione d'élite dei servizi segreti di Roccavento. Come agente sul campo e ricognitrice, segue le attività dei Defias nelle Marche Occidentali.",al={"amber kearnen","chi è kearnen","agente kearnen"}},{q="Dove si trova Amber Kearnen?",a="Amber Kearnen vigila nelle terre selvagge delle Marche Occidentali, vicino alla torre di guardia abbandonata dell'Alleanza occupata dalla Fratellanza dei Defias.",al={"posizione amber kearnen","dove si trova kearnen","dove si trova amber kearnen"}},{q="Qual è il suo legame con Mathias Shaw?",a="Amber Kearnen risponde direttamente al Maestro Mathias Shaw, il capo dell'SI:7. Shaw le invia altri agenti nelle Marche Occidentali per scoprire cosa sa delle attività dei Defias nella regione.",al={"kearnen mathias shaw","per chi lavora kearnen"}},{q="Che ruolo svolge in Klaven's Tower?",a="Amber Kearnen sorveglia la torre occupata da Klaven Mortwake. Istruisce i ladri dell'Alleanza inviati dall'SI:7 su come intrufolarsi, eludere le guardie dei Defias e recuperare il diario di Klaven.",al={"klaven's tower","amber kearnen klaven's tower","cosa fa alla torre"}}},fx={b2881d9a={q="Da che parte sta Amber Kearnen?",a="Amber Kearnen è un'agente fedele dell'Alleanza e presta servizio nella principale agenzia di intelligence di Roccavento, SI:7. Risponde direttamente ai vertici di SI:7 e opera sul campo in segreto per proteggere il regno dalla sovversione interna e dalle fazioni ostili.",al={"fazione di amber kearnen","per chi lavora amber kearnen","amber kearnen è dell'alleanza"}},e7eadf92={q="Che cosa vuole Amber Kearnen?",a="Il suo obiettivo principale è sorvegliare la Fratellanza dei Defias e neutralizzarne le operazioni nelle Marche Occidentali. Si concentra sulla raccolta di informazioni su Klaven Mortwake e aiuta gli agenti sul campo incaricati di infiltrarsi nella sua torre per recuperare importanti documenti dei Defias.",al={"obiettivo di amber kearnen","che cosa cerca di fare amber kearnen","missione di amber kearnen"}},e7dcbc70={q="Perché Amber Kearnen è di stanza nelle Marche Occidentali?",a="SI:7 l'ha inviata nelle Marche Occidentali per tenere sotto costante sorveglianza una torre di guardia dell'Alleanza abbandonata, occupata dalla Fratellanza dei Defias. Nascosta nelle vicinanze, osserva i movimenti nemici e fornisce supporto segreto agli agenti mandati a infiltrarsi nella roccaforte.",al={"perché amber kearnen è qui","perché amber kearnen è nelle marche occidentali","perché l'agente kearnen è nelle marche occidentali"}}},fp="13,139,17.291.0,19.446.1,21.138.0,33.126.0,39.171.0,42.170.0"}
P.entries["npc:anastasia-hartwell"] = {n="Anastasia Cuorfosco",s="Nel Magic Quarter di Sepulcra, Anastasia Cuorfosco addestra i maghi dei Reietti e dell'Orda nelle arti arcane. Guida gli incantatori nei loro studi e dirige ricerche magiche e attività sul campo in tutta Lordaeron e oltre.",h="Nel Magic Quarter di Sepulcra, Anastasia Cuorfosco addestra i maghi dei Reietti e dell'Orda nelle arti arcane.",kw={"anastasia","balnir","deino","reietti","cuorfosco","lordaeron","mago","magic quarter","tabetha","istruttore","sepulcra"},ang={["class:Mage"]="Come mago, puoi apprendere gradi superiori degli incantesimi da Anastasia Cuorfosco a Sepulcra. Guida i maghi dell'Orda di passaggio e affida loro incarichi importanti.",["faction:Horde"]="Come membro dell'Orda, puoi vedere Anastasia collegare il retaggio arcano di Lordaeron alle più ampie attività magiche dell'Orda attraverso istruttori come Deino a Orgrimmar.",["race:Undead"]="Come non morto, vedi le tradizioni arcane di Dalaran e Lordaeron sopravvivere tra i Reietti, nonostante la tragedia della non morte."},sec={{t="Maestria Arcana tra le Rovine",b="Nel Magic Quarter di Sepulcra, Anastasia Cuorfosco insegna ai maghi dei Reietti e dell'Orda a incanalare le energie arcane. Sebbene Lordaeron sia caduta in rovina, gli incantatori un tempo umani come Anastasia preservano le loro tradizioni accademiche nella non morte. Esige disciplina nella pratica della magia. Gli incantesimi lanciati senza cautela possono consumare gli inesperti."},{t="Ricerche sul Campo e Reliquie",b="Anastasia invia gli allievi promettenti sul campo, oltre a insegnare loro gli incantesimi. Alla Cascina dei Balnir, nelle Radure di Tirisfal orientali, i maghi raccolgono dragolose per scoprire quanto si sia diffusa la piaga. Nell'Apothecarium, visitano la bottega dell'alchimista Algernon per catturare le creature invisibili di pura magia responsabili di uno strano fenomeno. I suoi incarichi li mettono di fronte ai pericoli della magia, persino all'interno della loro città."},{t="Alleati dell'Arte",b="I contatti di Anastasia si estendono oltre Tirisfal. Man mano che gli incantatori dell'Orda diventano più abili, si coordina con istruttori in terre lontane, tra cui Deino a Orgrimmar. Indirizza anche gli allievi più esperti verso maestri solitari come Tabetha, nelle paludi di Acquemorte. La sua guida mantiene i maghi dei Reietti in contatto con le più ampie attività magiche dell'Orda."}},faq={{q="Chi è Anastasia Cuorfosco?",a="Anastasia Cuorfosco addestra i maghi dei Reietti nel Magic Quarter di Sepulcra. Insegna incantesimi e assegna incarichi per recuperare manufatti arcani e reagenti in tutta Lordaeron.",al={"anastasia cuorfosco","chi è anastasia","cuorfosco sepulcra"}},{q="Dove posso trovare Anastasia Cuorfosco?",a="Puoi trovare Anastasia Cuorfosco nel Magic Quarter di Sepulcra, tra incantatori e istruttori sotto le volte sotterranee della città.",al={"posizione di anastasia cuorfosco","dove si trova anastasia cuorfosco","posizione istruttore dei maghi sepulcra"}},{q="Cosa dice Anastasia a chi non è un mago?",a="Anastasia avverte i visitatori che non sono maghi di guardarsi dalla magia durante i loro viaggi. Brucia facilmente gli inesperti.",al={"anastasia dialoghi","anastasia dialogo","consigli di cuorfosco"}},{q="Quali missioni offre Anastasia Cuorfosco?",a="Anastasia assegna ai maghi incarichi di addestramento, tra cui raccogliere dragolose alla Cascina dei Balnir e indagare su un fenomeno magico nella bottega di un alchimista nell'Apothecarium. Li indirizza anche a lavorare con insegnanti lontani come Deino a Orgrimmar e Tabetha ad Acquemorte.",al={"missioni di anastasia","compiti di cuorfosco","missioni dei maghi sepulcra"}},{q="Anastasia Cuorfosco è imparentata con gli altri Hartwell a Tirisfal?",a="Anastasia condivide il cognome con Andrew Hartwell e Geoffrey Hartwell, ma il loro legame di parentela non è confermato.",al={"famiglia cuorfosco","andrew hartwell","geoffrey hartwell"}},{q="Perché Anastasia invia i maghi alla Cascina dei Balnir?",a="Anastasia chiede ai maghi di raccogliere Dragolose di Balnir per misurare la diffusione della piaga nelle Radure di Tirisfal e inviare i fiori agli speziali.",al={"missione cascina dei balnir","perché cascina dei balnir","cuorfosco balnir"}}},fx={["686de903"]={q="Da che parte sta Anastasia Cuorfosco?",a="Anastasia Cuorfosco è fermamente dalla parte dei Reietti e dell'Orda. Di stanza nelle profondità del Quartiere della Magia di Sepulcra, serve Lady Sylvanas Ventolesto preparando i maghi appena risorti a padroneggiare le arti arcane in difesa del loro regno nascente.",al={"fazione di anastasia cuorfosco","chi serve anastasia cuorfosco","lealtà di anastasia cuorfosco"}},bc0bb7e5={q="Perché Anastasia Cuorfosco è qui?",a="Risiede nel Quartiere della Magia di Sepulcra per addestrare gli aspiranti praticanti dei Reietti e dell'Orda nelle arti arcane. Guida gli incantatori alle prime armi, mettendo in guardia i novizi dai pericoli della magia e affidando ai maghi capaci missioni cruciali in tutta Lordaeron e oltre.",al={"perché anastasia cuorfosco è a sepulcra","che cosa fa qui anastasia cuorfosco","ruolo di anastasia cuorfosco"}},["18e123e6"]={q="Che cosa vuole Anastasia Cuorfosco?",a="Vuole assicurarsi che i praticanti delle arti arcane siano disciplinati, capaci e prudenti, ricordando spesso agli estranei che il potere incontrollato brucia chi non è addestrato. Con incarichi rigorosi e indagini magiche, lavora per rafforzare le capacità arcane dei Reietti.",al={"obiettivi di anastasia cuorfosco","quali sono le motivazioni di anastasia cuorfosco"}}},fp="18,218,27.341.0,25.418.0,19.358.0,26.169.0,36.155.0,37.102.0,42.291.0,61.116.0,54.141.0"}
P.entries["npc:andron-gant"] = {n="Andron Gant",s="Nell'Apothecarium, Andron Gant organizza incarichi e recuperi di reliquie per gli studiosi locali. Il solitario Reietto è spesso ubriaco e lascia raramente Sepulcra.",h="Nell'Apothecarium, Andron Gant organizza incarichi e recuperi di reliquie per gli studiosi locali.",kw={"andron gant","apothecarium","astor hadren","deathstalkers","jediga","tavoletta di markri","varimathras"},ang={["class:Rogue"]="Come ladro Reietto, avanzando tra i ranghi dei Deathstalkers impari che i corridoi di Sepulcra richiedono tanta vigilanza quanto i suoi confini.",["race:Undead"]="Come Undead, potresti conoscere Gant come una presenza abituale nell'Apothecarium: un Reietto ubriaco che lascia raramente la città e procura strani incarichi per i suoi maghi."},sec={{t="Un recluso che biascica",b="Andron Gant se ne sta nell'Apothecarium, tra i suoi miasmi nocivi, e si avventura di rado oltre le mura di pietra di Sepulcra. Sembra poco più di uno studioso ubriaco. Eppure, a volte i maghi locali gli fanno inviare corrieri verso lidi lontani alla ricerca di oscure reliquie, tra cui la Tavoletta di Markri."},{t="Smascherato dai Deathstalkers",b="La rete di spionaggio di Sepulcra ha scoperto i loschi affari di Gant. La Lega dei Tagliagole ha inviato Astor Hadren a ritirare un registro di dati compromessi, ma alcuni aspiranti agenti Deathstalker hanno intercettato il corriere. Un agente ha preso il posto di Hadren e ha ingannato Gant, facendosi consegnare il registro incriminante senza destare sospetti. Il registro ha fornito a Sire Varimathras la prova definitiva del tradimento di Gant ai danni dei Reietti."}},faq={{q="Dove posso trovare Andron Gant?",a="Andron Gant si trova nei livelli inferiori del quartiere dell'Apothecarium, all'interno di Sepulcra.",al={"posizione di andron gant","dove si trova andron gant","posizione gant sepulcra"}},{q="Perché Andron Gant è interessato alle tavolette di Azshara?",a="Gant organizza i pagamenti per alcuni maghi di Sepulcra e invia cercatori di rottami e contatti come Jediga a recuperare antiche reliquie dalle rovine di Azshara.",al={"andron gant azshara","tavoletta di markri andron gant","perché gant vuole le tavolette"}},{q="Perché i Deathstalkers indagano su Andron Gant?",a="I Deathstalkers indagano sugli affari di Gant con i suoi contatti esterni e cercano informazioni sui suoi incarichi di ricerca.",al={"indagine su gant","contatti di andron gant","per chi lavora andron gant"}},{q="Chi dirige le indagini su Andron Gant?",a="I Deathstalkers indagano su Gant per conto di Sire Varimathras, alla ricerca di informazioni sui suoi contatti e sulle sue ricerche.",al={"chi indaga su andron gant","deathstalkers andron gant","varimathras andron gant"}}},fx={["1e42df39"]={q="Chi è Andron Gant?",a="Andron Gant è un Reietto che frequenta l'Apothecarium di Sepulcra. A prima vista, sembra poco più che un ubriacone abituale che di rado si allontana dalla capitale; fa da intermediario per strani incarichi accademici, come procurare antiche tavolette per i maghi locali.",al={"chi è andron gant","storia di andron gant","chi è gant"}},["24992602"]={q="Da che parte sta Andron Gant?",a="Anche se vive tra i Reietti a Sepulcra, Gant lavora segretamente come informatore del Sindacato. Raccoglie informazioni dalla capitale e passa registri riservati ai messaggeri del Sindacato, diventando così un traditore nell'ombra del regno della Signora Oscura.",al={"andron gant è leale","chi serve andron gant","lealtà di andron gant"}},e54869d5={q="Che cosa vuole Andron Gant?",a="In pubblico, Gant passa il tempo a bere e a fare da intermediario per oggetti insoliti, per esempio pagando gli avventurieri perché recuperino reliquie come la Tavoletta di Markri ad Azshara per i maghi di Sepulcra. In segreto, il suo obiettivo principale è raccogliere registri riservati e informazioni da vendere al Sindacato.",al={"che cosa vuole andron","motivazioni di andron gant","obiettivi di andron gant"}},["1151765b"]={q="Perché Andron Gant si trova a Sepulcra?",a="Gant resta appartato nell'Apothecarium, fingendosi uno studioso e intermediario innocuo e ubriacone. Sepulcra gli offre la copertura ideale per raccogliere informazioni senza dare nell'occhio e mantenere un canale di comunicazione segreto con i cospiratori all'esterno.",al={"perché andron gant è qui","perché andron è a sepulcra","andron gant e l'apothecarium"}}},fp="11,165,18.283.0,29.401.1,29.96.0,49.152.0,49.121.1,47.119.1"}
P.entries["npc:anduin-wrynn"] = {n="Anduin Wrynn",s="Il trono di Roccavento è affidato al decenne Anduin Wrynn mentre suo padre, Re Varian Wrynn, è scomparso. Il Gran Signore Bolvar Domadraghi e la corte reale si fanno carico del governo.",h="Il trono di Roccavento è affidato al decenne Anduin Wrynn mentre suo padre, Re Varian Wrynn, è scomparso.",kw={"anduin","bolvar","re bambino","prestor","principe","roccavento","sala del trono","wrynn"},ang={["faction:Alliance"]="Per i cittadini e i soldati dell'Alleanza, Re Anduin è un simbolo innocente della capacità del regno di resistere. Molti temono che la sua giovane età esponga il trono agli intrighi di corte.",["race:Human"]="Per il popolo di Roccavento, il re bambino mantiene viva la dinastia Wrynn mentre suo padre, Varian, è scomparso."},sec={{t="Un ragazzo sul trono",b="Anduin Wrynn è nato nella pace dopo la Seconda Guerra. Il suo nome onora suo nonno, Re Llane, e Sir Anduin Lothar, il leggendario cavaliere. Quando Re Varian Wrynn scomparve durante il viaggio verso un vertice diplomatico a Theramore, Anduin fu incoronato per mantenere stabile il regno. Intelligente e compassionevole, ha ancora solo dieci anni e poca voce in capitolo negli affari di stato. Il Gran Signore Bolvar Domadraghi e la consigliera reale Dama Katrana Prestor si dividono il compito di governare il regno."},{t="Una pedina a corte",b="Anduin dimora nel Forte di Roccavento mentre la tensione a corte cresce. Il Gran Signore Bolvar veglia sulle difese del regno e si adopera per mantenerlo unito. Dama Katrana Prestor impone i suoi consigli alla corte e ostacola l'invio di truppe agli insediamenti umani periferici. Anduin avverte quanto sia diventata fragile la sua corte e sente la mancanza del padre. Per ora, nobili con propri disegni e guardiani circondano il giovane re."}},faq={{q="Perché un bambino governa Roccavento?",a="Re Varian Wrynn scomparve in circostanze misteriose mentre navigava verso un vertice diplomatico a Theramore. Per evitare una crisi di successione e preservare l'ordine in tutto il regno, il decenne Principe Anduin fu incoronato re, e il Gran Signore Bolvar Domadraghi fu nominato reggente per governare al suo posto.",al={"perché anduin è re","dov'è varian","chi è il re bambino"}},{q="Chi governa davvero il regno in questo momento?",a="Il Gran Signore Bolvar Domadraghi è il reggente di Roccavento. Comanda gli eserciti del regno e detiene il potere esecutivo finché Anduin non raggiungerà la maggiore età. Dama Katrana Prestor è un'alta consigliera la cui influenza si estende in profondità nella corte reale e nella House of Nobles.",al={"chi governa roccavento","chi è al comando","reggente di roccavento"}},{q="Da chi prende il nome Anduin?",a="Il nome di Anduin onora due eroi della storia di Roccavento: suo nonno, il defunto Re Llane Wrynn, e Sir Anduin Lothar, il Lion of Azeroth che guidò l'Alleanza durante la First War e la Seconda Guerra.",al={"origine del nome anduin","da chi prende il nome anduin","perché si chiama anduin"}},{q="Dove si trova Anduin nella città?",a="Re Anduin siede sul trono reale nella sala del trono del Forte di Roccavento. Il Gran Signore Bolvar Domadraghi e Dama Katrana Prestor sono accanto a lui.",al={"dov'è anduin","posizione di anduin","posizione di anduin wrynn"}}},fp="12,178,19.463.0,19.407.0,32.292.1,40.249.0,26.199.0,36.147.0"}
P.entries["npc:apothecary-helbrim"] = {n="Speziale Helbrim",s="A Crocevia, lo Speziale Helbrim raccoglie reagenti sconosciuti per la Società degli Speziali Reali. Inviato a Kalimdor, studia le Savane per conto dei Reietti.",h="A Crocevia, lo Speziale Helbrim raccoglie reagenti sconosciuti per la Società degli Speziali Reali.",kw={"speziale","savane","crocevia","spore fungine","helbrim","società degli speziali reali","zamah"},ang={["faction:Horde"]="Helbrim lavora accanto a guardie orchesche e viandanti tauren, ma il suo zelo nel raccogliere spore e tossine inquieta persino i suoi alleati.",["race:Undead"]="In quanto Reietto, puoi vedere come il tuo popolo contribuisce all'Orda a Kalimdor. Helbrim raccoglie campioni nelle terre selvagge per le ricerche della Società."},sec={{t="Uno speziale nella polvere",b="Lo Speziale Helbrim lavora sotto il sole a Crocevia, lontano dalla sede della Società degli Speziali Reali a Sepulcra. Inviato oltre il Grande Mare fino a Kalimdor, cerca nelle Savane piante, funghi e altri campioni naturali utili.\n\nHelbrim dipende dai viaggiatori per ricevere campioni, comprese le Spore Fungine locali. Collabora anche con Apothecary Zamah a Picco del Tuono. Grazie al suo lavoro, gli alchimisti dei Reietti estendono la loro influenza oltre i confini devastati di Lordaeron."}},faq={{q="Chi è lo Speziale Helbrim?",a="Helbrim è un alchimista dei Reietti e un agente della Società degli Speziali Reali. A Crocevia, raccoglie e studia reagenti naturali provenienti da tutte le Savane.",al={"chi è helbrim","storia di helbrim","speziale di crocevia"}},{q="Perché uno speziale dei Reietti è di stanza nelle Savane?",a="La Società degli Speziali Reali cerca nuovi composti, tossine e reagenti per le sue ricerche. Helbrim è stato inviato nel centro di Kalimdor per studiare campioni locali, comprese Spore Fungine diverse da quelle delle terre di Lordaeron segnate dalla peste.",al={"perché è a crocevia","cosa fa helbrim qui","perché i reietti sono nelle savane"}},{q="Cosa fa con le spore fungine che gli portano i giocatori?",a="Helbrim studia la tossicità, il valore medicinale e le altre proprietà delle Spore Fungine. Prepara campioni che i corrieri porteranno ad Apothecary Zamah a Picco del Tuono per ulteriori esperimenti.",al={"spore fungine helbrim","a cosa servono le spore","missione spore fungine"}},{q="Con chi collabora Helbrim?",a="Helbrim risponde alla Società degli Speziali Reali di Sepulcra. A Kalimdor, collabora con Apothecary Zamah alle Pozze delle Visioni a Picco del Tuono e talvolta tratta affari tramite intermediari goblin come Wharfmaster Dizzywig a Porto Paranco.",al={"alleati di helbrim","a chi risponde helbrim"}}},fx={d7b2fd88={q="Da che parte sta lo Speziale Helbrim?",a="Helbrim è un membro dei Reietti e risponde direttamente allo Speziale Reale di Sepulcra. Fa parte del popolo di Lady Sylvanas Ventolesto e si schiera con l'Orda, anche se la Società persegue spesso i propri obiettivi alchemici segreti persino nei territori alleati come The Barrens.",al={"fazione di helbrim","chi serve helbrim","helbrim fa parte dell'orda"}}},fp="18,158,22.462.0,26.158.0,54.231.0,57.190.0,27.244.0"}
P.entries["npc:apothecary-johaan"] = {n="Speziale Johaan",s="A Brill, lo Speziale Johaan lavora a una piaga per i Reietti. La Società degli Speziali Reali e Dama Sylvanas lo hanno incaricato di condurre esperimenti letali sulle piante e sugli animali locali.",h="A Brill, lo Speziale Johaan lavora a una piaga per i Reietti.",kw={"speziale","brill","johaan","piaga","società degli speziali reali","selva pinargento","tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, puoi vedere come gli intrugli letali di Johaan proteggano la sua presenza nei Regni Orientali. Orchi e tauren potrebbero esitare di fronte alle piaghe alchemiche.",["race:Undead"]="Come non morto, appartieni alla causa dei Reietti che la ricerca di Johaan serve. Sviluppa armi destinate a garantire una patria permanente, libera dal Flagello e dalle minacce dei vivi."},sec={{t="Un servitore della Società",b="A Brill, lo Speziale Johaan lavora apertamente per la neonata Società degli Speziali Reali. Come i suoi colleghi in tutta Lordaeron, segue ordini diretti per creare armi biologiche e alchemiche. I Reietti sperano che queste armi possano garantire il loro fragile futuro sia contro i vivi sia contro il Flagello."},{t="Preparare la New Plague",b="Lo Speziale Johaan dirige le prime prove sul campo della New Plague della Società. Dalla fauna corrotta e dalle fattorie contaminate di Tirisfal ricava Sangue di Segugio Oscuro, scaglie di murloc, veleno di ragno e zucche rubate. Sperimenta le miscele su soggetti viventi e ne misura la potenza. Poi invia i risultati a sud, a Selva Pinargento."}},faq={{q="Chi è lo Speziale Johaan?",a="Lo Speziale Johaan conduce ricerche alchemiche a Brill per la Società degli Speziali Reali. Incarica i giovani campioni dei Reietti di raccogliere reagenti ripugnanti in tutte le Radure di Tirisfal.",al={"speziale johaan","chi è johaan","johaan brill"}},{q="Dove posso trovare lo Speziale Johaan?",a="Puoi trovare lo Speziale Johaan all'aperto a Brill, vicino alla forca e alle attrezzature alchemiche. La cittadina si trova poco a nord di Sepulcra, nelle Radure di Tirisfal.",al={"posizione di johaan","dove si trova johaan","trova johaan"}},{q="A cosa sta lavorando Johaan?",a="Johaan sta sviluppando i primi ceppi della New Plague. Sperimenta agenti biologici ed estratti velenosi provenienti dai campi e dalle bestie contaminate di Tirisfal.",al={"esperimenti di johaan","cosa fa johaan","piaga di johaan"}},{q="Cosa fa con i campioni della piaga?",a="Dopo aver mescolato i campioni e averne valutato la letalità, Johaan invia corrieri agli speziali alleati a Selva Pinargento.",al={"consegna a selva pinargento","dove vanno i campioni della piaga"}},{q="A quale organizzazione appartiene Johaan?",a="Johaan appartiene alla Società degli Speziali Reali, la gilda alchemica che serve Dama Sylvanas Ventolesto e i Reietti a Sepulcra.",al={"fazione di johaan","per chi lavora johaan"}},{q="Perché è interessato alle fattorie locali?",a="Le fattorie umane come la Cascina dei Solliden e i campi vicini producono zucche che Johaan usa come reagenti grezzi per tossine sperimentali.",al={"fields of grief johaan","perché mandarmi alle fattorie"}}},fx={c51cf856={q="Da che parte sta lo Speziale Johaan?",a="Johaan serve Lady Sylvanas Ventolesto e i Reietti come membro della Società degli Speziali Reali. Di stanza a Brill, lavora per conto di Sepulcra allo sviluppo di armi chimiche e pestilenze che proteggano il loro territorio sia dal Flagello sia dai viventi.",al={"fazione di johaan","chi serve johaan","lealtà dello speziale johaan"}},["90913b50"]={q="Perché lo Speziale Johaan si trova nelle Radure di Tirisfal?",a="Johaan è di stanza a Brill per svolgere ricerche sul campo e raccogliere ingredienti locali in tutte le Radure di Tirisfal. La vicinanza alla flora contaminata, alla fauna selvatica e agli insediamenti umani contesi gli permette di procurarsi reagenti per gli esperimenti e di condurre test direttamente sui soggetti, lontano dai laboratori principali di Sepulcra.",al={"perché johaan è qui","perché lo speziale johaan è a brill","scopo di johaan a tirisfal"}}},fp="17,174,24.302.0,22.330.1,25.163.0,35.153.0,26.146.0,40.118.0,40.140.0,40.136.0"}
P.entries["npc:apothecary-renferrel"] = {n="Speziale Renferrel",s="A Mausolea, lo Speziale Renferrel studia la fauna corrotta e le minacce dei non morti della Selva Pinargento. Fa progredire l'alchimia dei Reietti, mentre i viaggiatori gli portano reagenti volatili e lo aiutano a indagare sui resti del Flagello.",h="A Mausolea, lo Speziale Renferrel studia la fauna corrotta e le minacce dei non morti della Selva Pinargento.",kw={"speziale","ricetta per la morte","renferrel","rot hide","società degli speziali reali","mausolea","selva pinargento","thule ravenclaw"},ang={["faction:Horde"]="Come membro dell'Orda, potresti trovare raccapriccianti gli esperimenti biologici di Renferrel. La sua raccolta di informazioni sul Flagello aiuta a proteggere i territori dell'Orda dalle incursioni da nord.",["race:Undead"]="Come non morto, conosci la spietata determinazione dei Reietti a sopravvivere. Renferrel trasforma la flora e la fauna autoctone di Lordaeron in armi per garantire un futuro ai non morti liberati."},sec={{t="L'Alchimista di Mausolea",b="A Mausolea, Renferrel dirige le ricerche sul campo per la Società degli Speziali Reali nella Selva Pinargento. I grandi laboratori e gli alti vertici della società si trovano a Sepulcra, mentre lui lavora sul campo. Raccoglie campioni biologici autoctoni, raffina potenti intrugli e studia la cupa ecologia lungo il confine occidentale di Lordaeron."},{t="Indagini su Rot Hide e Flagello",b="Renferrel esamina gli gnoll Rot Hide e i non morti fuori controllo nella Selva Pinargento. I campioni di sangue e tessuti lo aiutano a studiare gli effetti persistenti della piaga e le forze negromantiche che vincolano i mostri locali. Le sue indagini lo portano a scontrarsi con Thule Ravenclaw, un potente negromante del Flagello vicino alle rovine dell'Isola di Fenris."}},faq={{q="Chi è lo Speziale Renferrel?",a="Lo Speziale Renferrel conduce ricerche sul campo per la Società degli Speziali Reali da Mausolea, il principale avamposto dei Reietti nella Selva Pinargento. Studia le bestie locali, le varianti della piaga e le forze nemiche per preparare intrugli e mettere al sicuro la regione per la regina Sylvanas.",al={"renferrel","chi è renferrel","speziale renferrel storia"}},{q="Cosa ricerca Renferrel nella Selva Pinargento?",a="Renferrel sviluppa nuove piaghe e miscele velenose, note nel complesso come una 'Recipe for Death'. Chiede ai viaggiatori di raccogliere cuori di orsi grizzly, icore degli gnoll Rot Hide e altri componenti biologici per sperimentare e perfezionare intrugli letali.",al={"ricerche di renferrel","esperimenti di renferrel","ricetta per la morte"}},{q="Qual è il suo legame con gli gnoll Rot Hide?",a="Renferrel studia l'icore corrotto degli gnoll Rot Hide. I primi esperimenti rilevano magia stregonesca e negromantica, così invia un campione a Bethor Scheggiafredda, a Sepulcra, per ulteriori studi.",al={"icore di pellemarcia","rot hide origins","gnoll selva pinargento"}},{q="Perché Renferrel prende di mira Thule Ravenclaw?",a="Renferrel indaga sulla magia che anima gli gnoll Rot Hide e chiede aiuto a Bethor Scheggiafredda per identificarne la fonte. La sua indagine lo conduce verso le minacce sull'Isola di Fenris.",al={"missione thule ravenclaw","chi è thule ravenclaw","negromante forte fenris"}},{q="Dove invia gli avventurieri Renferrel dopo la Selva Pinargento?",a="Una volta completate le prime ricerche e affrontate le minacce locali, Renferrel invia i viaggiatori esperti a sud-est, verso le Alture di Colletorto. Questo collega gli sforzi di frontiera di Mausolea alle più ampie operazioni dei Reietti a Lordaeron.",al={"dopo mausolea","consegna a colletorto","viaggio verso colletorto"}},{q="Cos'è la Società degli Speziali Reali?",a="La Società degli Speziali Reali è il ramo scientifico e alchemico dei Reietti, fondato sotto la guida di Dama Sylvanas Ventolesto. Con sede a Sepulcra, i suoi ricercatori sviluppano veleni, cercano di resistere alla decomposizione naturale e creano una piaga capace di annientare il Flagello.",al={"società degli speziali reali","ras","speziali dei reietti"}}},fx={["703d1213"]={q="Da che parte sta lo Speziale Renferrel?",a="Lo Speziale Renferrel serve i Reietti e Lady Sylvanas Ventolesto come membro giurato della Società degli Speziali Reali. Sotto il vessillo più ampio dell'Orda, la sua lealtà va agli ordini alchemici di Sepulcra, e dedica i suoi sforzi a garantire la sopravvivenza e la supremazia dei Reietti contro nemici comuni come il Flagello e i viventi.",al={"fazione di renferrel","chi serve renferrel","lo speziale renferrel fa parte dell'orda"}},dbc0ae2b={q="Perché lo Speziale Renferrel si trova qui, nella Selva Pinargento?",a="Di stanza a Mausolea, Renferrel conduce importanti ricerche alchemiche sul campo per la Società degli Speziali Reali. La Selva Pinargento gli offre accesso a bestie feroci, pericolose attività del Flagello e minacce locali contaminate come i gnoll Pellemarcia, tutti soggetti preziosi per raccogliere ingredienti potenti e preparare nuove tossine.",al={"perché renferrel è a mausolea","perché renferrel si trova qui","perché lo speziale renferrel è qui"}}},fp="20,211,25.338.0,34.315.1,28.268.0,43.241.0,46.187.0,42.180.1,55.223.0,37.260.0"}
P.entries["npc:apothecary-zinge"] = {n="Speziale Zinge",s="Sotto le Rovine di Lordaeron, la Speziale Zinge studia campioni per i Reietti. Il suo lavoro la porta anche a inviare materiali di ricerca attraverso le terre dell'Orda.",h="Sotto le Rovine di Lordaeron, la Speziale Zinge studia campioni per i Reietti.",kw={"apothecarium","speziale zinge","crocevia","helbrim","lo speziale reale","campioni","sepulcra","zinge"},ang={["faction:Horde"]="Come membro dell'Orda, fai affidamento su rotte di rifornimento aperte e corrieri fidati che attraversano il mare tra Kalimdor e i Regni Orientali. Queste rotte mantengono rifornite le tue prime linee.",["race:Undead"]="Come Reietto, puoi vedere ricercatori come Zinge promuovere l'indipendenza scientifica del tuo popolo. Lavorano instancabilmente a soluzioni volte a garantire la sopravvivenza e la supremazia dei Reietti."},sec={{t="Al servizio della Società",b="Nell'Apothecarium sotto Sepulcra, la Speziale Zinge serve i Reietti. Lavora sotto la guida del Maestro Speziale Faranell, cercando composti chimici e biologici che possano favorire i loro obiettivi. Le sue ricerche la mettono in contatto con ricercatori sul campo ed esploratori ben oltre le Radure di Tirisfal, persino nei remoti avamposti di Kalimdor."},{t="Esperimenti intercontinentali",b="La Speziale Zinge si affida a corrieri e avventurieri per trasportare materiali di prova attraverso il mare. Scrive regolarmente allo Speziale Helbrim al Crocevia, nelle Savane. Le sue spedizioni includono Campioni di Cuore di Lupo tossici provenienti dalla Selva Pinargento, affinché lui possa studiare gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor."}},faq={{q="Dove si trova la Speziale Zinge?",a="La Speziale Zinge lavora nell'Apothecarium, il quartiere alchemico nel livello sudorientale di Sepulcra.",al={"posizione di zinge","dove si trova lo speziale zinge","posto dello speziale zinge"}},{q="A quale organizzazione appartiene?",a="La Speziale Zinge appartiene alla Società dello Speziale Reale. I suoi alchimisti Reietti creano intrugli, pestilenze e antidoti al servizio di Dama Sylvanas Ventolesto.",al={"fazione di zinge","per chi lavora zinge"}},{q="Perché le servono campioni dalle Savane?",a="I campioni viaggiano dalla Selva Pinargento fino allo Speziale Helbrim al Crocevia. Zinge affida agli avventurieri cuori di lupo tossici da portare al collega, che studia gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor.",al={"perché campioni dalle savane","campione di helbrim","zinge consegna savane"}}},fx={["55fc7dbb"]={q="Chi è lo Speziale Zinge?",a="Lo Speziale Zinge è un'alchimista Reietta e membro attiva della Società degli Speziali Reali, che ha sede a Sepulcra. Dedita a far progredire le ricerche e le formule del suo ordine, coordina le ricerche sul campo, invia campioni di tossine ai colleghi in terre lontane come The Barrens e mantiene stretti rapporti con amici come Fenstad Argyle.",al={"chi è zinge","storia dello speziale zinge","chi è lo speziale zinge"}},b56b8970={q="Da che parte sta lo Speziale Zinge?",a="Zinge serve i Reietti e la Società degli Speziali Reali, schierandosi direttamente con Lady Sylvanas Ventolesto e, di conseguenza, con l'Orda. La sua lealtà va senza esitazioni alle ricerche di Sepulcra e aiuta tutti gli avventurieri dell'Orda disposti a contribuire ai suoi esperimenti.",al={"fazione di zinge","chi serve zinge","lealtà dello speziale zinge"}},d8143764={q="Perché lo Speziale Zinge è coinvolto in The Barrens?",a="Anche se Zinge è di stanza nell'Apothecarium di Sepulcra, fa trasportare campioni tossici di cuore di lupo dalla Selva Pinargento al suo collega, lo Speziale Helbrim, al Crocevia. Helbrim studia gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor.",al={"perché zinge è interessata a the barrens","legame di zinge con the barrens","perché inviare campioni a the barrens"}}},fp="16,143,25.322.0,29.304.0,36.104.0,37.164.0,43.207.0"}
P.entries["npc:aramis-hammerhand"] = {n="Aramis Hammerhand",s="Nella cappella di Albamorta, Aramis Hammerhand insegna ai Reietti appena risorti a combattere con la Sacra Luce. Possono invocarne il potere, ma questo brucia le loro carni decomposte ed esige una ferrea disciplina.",h="Nella cappella di Albamorta, Aramis Hammerhand insegna ai Reietti appena risorti a combattere con la Sacra...",kw={"aramis","cappella","albamorta","reietti","hammerhand","luce","paladino","tirisfal","istruttore"},ang={["class:Paladin"]="Se sei un paladino dei Reietti, Aramis è il tuo primo mentore. Ti guida attraverso il dolore e la disciplina spirituale necessari per usare la Sacra Luce in un corpo non morto.",["race:Undead"]="Se sei un viaggiatore non morto, puoi vedere in Aramis che la non morte non deve necessariamente spezzare la tradizione guerriera sacra di Lordaeron, benché questa via comporti grandi sofferenze."},sec={{t="Un faro ad Albamorta",b="Nella cappella di Albamorta, Aramis Hammerhand guida i Reietti ancora legati alla fede che professavano in vita. Prima che il Flagello travolgesse il nord, molti abitanti di Lordaeron risposero alla chiamata della Mano d'Argento. Aramis sopravvisse alla caduta di Lordaeron, poi risorse nella non morte. Conservò gli insegnamenti marziali e spirituali della sua vita precedente, e ora guida altri che non intendono rinunciare alla propria devozione."},{t="Il tormento della Sacra Luce",b="Per i Reietti, incanalare la Sacra Luce richiede una ferrea volontà. Il suo potere brucia le carni necrotiche e risveglia nervi morti da tempo, provocando un dolore straziante. Aramis insegna ai nuovi paladini che avere fede significa sopportare questo tormento. Chiede loro di affrontare il costo fisico e spirituale dell'uso di una forza opposta alla loro natura di non morti."}},faq={{q="Chi è Aramis Hammerhand?",a="Aramis Hammerhand addestra i paladini dei Reietti nella cappella di Albamorta, nelle Radure di Tirisfal. Guida coloro che, appena risorti, cercano di combattere con il potere sacro.",al={"storia di aramis","chi è hammerhand","istruttore dei paladini di albamorta"}},{q="I Reietti possono davvero usare la Sacra Luce?",a="Sì. I Reietti possono invocare la Sacra Luce grazie alla forza di volontà e alla convinzione. Il suo potere radioso brucia e corrode le loro carni putrefatte anche mentre li cura o li rafforza.",al={"i non morti possono essere paladini","come usano la luce i non morti","reietti luce"}},{q="Dove posso trovare Aramis Hammerhand?",a="Aramis Hammerhand si trova nella cappella di Albamorta, l'insediamento iniziale dei Reietti nelle Radure di Tirisfal.",al={"dove si trova aramis","posizione di hammerhand","istruttore dei paladini albamorta"}},{q="Quali missioni offre Aramis Hammerhand?",a="Aramis offre ai paladini appena risorti un addestramento specifico per la loro classe, che comprende A Difficult Path, Rediscovering the Light, Luce nell'Oscurità, Coming to Terms e Continue Your Training.",al={"missioni di aramis","missioni dei paladini di albamorta"}},{q="Perché un istruttore dei paladini lavora per i Reietti?",a="Prima della piaga, Lordaeron era la culla dei Cavalieri della Mano d'Argento. Molti Reietti appena liberati ricordano i propri giuramenti e restano fedeli alla loro sacra vocazione nonostante la condizione di non morti.",al={"perché esistono paladini reietti","reietti mano d'argento"}},{q="Usare la Luce cura i non morti normalmente?",a="La Luce può risanare i corpi dei non morti e conferire forza in combattimento, ma usarla provoca un dolore straziante. Risveglia i loro sensi e fa percepire loro la putrefazione dei propri corpi.",al={"la luce fa male ai non morti","storia della luce che cura i non morti"}}},fx={["63e97215"]={q="Da che parte sta Aramis Hammerhand?",a="Aramis Hammerhand è fermamente dalla parte dei Reietti. Pur abbracciando la disciplina di un paladino e insegnando ai non morti appena risorti a brandire la Luce Sacra, la sua lealtà appartiene alla regina Sylvanas Ventolesto e al regno che sta forgiando nelle rovine di Lordaeron.",al={"lealtà di aramis hammerhand","chi serve aramis","fazione di aramis hammerhand"}},c81bf44f={q="Perché Aramis Hammerhand si trova ad Albamorta?",a="Troverai Aramis nella cappella in rovina di Albamorta, dove accoglie i Reietti appena risvegliati. Attende coloro che sono appena sfuggiti alla presa del Flagello e che in vita avevano pronunciato voti sacri, guidandoli attraverso l'agonia e la disciplina necessarie a riaccendere il loro potere sacro nella non morte.",al={"perché aramis è ad albamorta","perché aramis hammerhand si trova ad albamorta","che cosa ha portato aramis qui"}}},fp="17,196,22.379.0,27.317.0,25.133.0,47.173.0,35.108.0,41.185.0,50.190.0,55.163.0"}
P.entries["npc:arcanist-doan"] = {n="Arcanista Doan",s="Nel Monastero Scarlatto, l'Arcanista Doan sorveglia l'Ateneo e i suoi archivi. Maestro mago umano, mette la sua letale maestria arcana al servizio della Crociata Scarlatta.",h="Nel Monastero Scarlatto, l'Arcanista Doan sorveglia l'Ateneo e i suoi archivi.",kw={"arcanista","ateneo","detonazione","doan","biblioteca","chiave scarlatta","monastero scarlatto"},ang={["class:Mage"]="Come mago, puoi osservare la maestria di Doan nelle difese arcane nella bolla protettiva che evoca.",["class:Paladin"]="Come paladino, incontri uno dei rari arcanisti che godono della fiducia della Crociata Scarlatta, un ordine che antepone la Luce a ogni altro potere.",["faction:Alliance"]="Come combattente dell'Alleanza, vedi come lo zelo della Crociata Scarlatta vincoli persino un maestro dell'arcano alla sua violenta paranoia.",["faction:Horde"]="Come membro dell'Orda, affronti un pericoloso comandante scarlatto la cui biblioteca custodisce informazioni vitali e chiavi per i santuari più interni della Crociata."},sec={{t="Custode dell'Ateneo",b="La Crociata Scarlatta confida nella furia marziale e nel fervore sacro. Doan crede che il potere arcano sia vitale per scacciare il Flagello da Lordaeron. Nelle profondità della biblioteca del Monastero, ne custodisce il sapere e sorveglia la Chiave Scarlatta. Quella chiave protegge i santuari della Crociata in tutti i regni settentrionali."}},faq={{q="Perché c'è un mago nella Crociata Scarlatta?",a="La Crociata Scarlatta è governata da paladini e sacerdoti zelanti. Doan crede che la padronanza della magia arcana sia essenziale per liberare Lordaeron dal Flagello.",al={"perché doan è un mago","mago della crociata","magia di doan"}},{q="Qual è il legame dell'Arcanista Doan con Brandicenere?",a="Doan non ha alcun legame noto con Brandicenere. Sorveglia la biblioteca del Monastero Scarlatto e la Chiave Scarlatta.",al={"doan brandicenere","doan ha creato brandicenere","cristallo di brandicenere"}},{q="Cosa sorveglia Doan nella Biblioteca?",a="Doan custodisce i libri e i documenti storici dell'Ateneo. Una cassetta dietro di lui contiene la Chiave Scarlatta, che apre i cancelli chiusi delle ali Armory e Cathedral del Monastero.",al={"cosa rilascia doan","chiave scarlatta","perché uccidere doan"}},{q="Quale magia usa Doan in combattimento?",a="Doan può lanciare Arcane Bubble, che lo rende invulnerabile mentre canalizza un potente incantesimo Detonation che riempie la stanza. Può anche silenziare gli incantatori in un'area e trasformare chi lo minaccia in pecore.",al={"incantesimi di doan","abilità di doan","bolla dell'arcanista doan"}},{q="Dove ha combattuto Doan durante la Terza Guerra?",a="Non sono documentate imprese di Doan durante la Third War. Oggi sorveglia l'Ateneo del Monastero Scarlatto e la Chiave Scarlatta.",al={"storia bellica di doan","dov'era doan"}},{q="Doan nasconde dei segreti personali?",a="Doan serve la Crociata Scarlatta come arcanista. Nessun documento parla delle sue relazioni sentimentali private.",al={"lore di doan"}}},fx={["979d2c44"]={q="Chi è l'Arcanista Doan?",a="L'Arcanista Doan è un mago umano e uno dei più potenti praticanti delle arti arcane al servizio della Crociata Scarlatta. Risiede nelle profondità dell'Ateneo della Biblioteca del Monastero Scarlatto, dove custodisce gli archivi dell'ordine e la Chiave Scarlatta, e brandisce una devastante magia arcana in difesa del santuario sacro dell'ordine.",al={"chi è doan","storia dell'arcanista doan","doan e il monastero scarlatto"}},["46f867c9"]={q="Che cosa vuole l'Arcanista Doan?",a="Doan è guidato dalla convinzione che la magia arcana sia l'unico vero modo per epurare completamente Lordaeron dal Flagello. Mentre i suoi confratelli della Crociata Scarlatta si affidano quasi interamente allo zelo della Luce Sacra, Doan ritiene che il potere arcano allo stato puro e lo studio siano necessari per contenere ed estirpare una volta per tutte la piaga dei non morti.",al={"obiettivi di doan","che cosa vuole doan","motivazioni dell'arcanista doan"}},["88b26aa6"]={q="Perché Doan è temuto?",a="Doan è temuto perché è uno dei maghi più formidabili di Lordaeron. In battaglia si avvolge in una Bolla Arcana quasi impenetrabile per lanciare incantesimi di Detonazione cataclismici, capaci di incenerire interi gruppi di intrusi in un istante.",al={"perché doan è temuto","quanto è potente doan","reputazione di doan"}}},fp="13,157,23.277.0,37.150.0,53.110.0,36.177.0,35.201.0,42.122.0,38.101.0"}
P.entries["npc:archaeologist-flagongut"] = {n="Archeologo Granrutto",s="A Porto di Menethil, l'Archeologo Granrutto mantiene i contatti con i ricercatori sul campo oltre il Grande Mare. Lo studioso nanico della Lega degli Esploratori alloggia alla Locanda Acquefonde, lungo il viaggio verso il Whelgar Excavation Site.",h="A Porto di Menethil, l'Archeologo Granrutto mantiene i contatti con i ricercatori sul campo oltre il Grande...",kw={"archeologo","locanda acquefonde","lega degli esploratori","granrutto","porto di menethil","errasogni","whelgar"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come Granrutto colleghi le terre degli elfi della notte di Rivafosca alle roccaforti orientali dell'Alleanza a Khaz Modan.",["race:Dwarf"]="Come nano, puoi vedere fin dove arriva la Lega degli Esploratori nel lavoro di Granrutto in una locanda sul mare, dove studia i segreti dei Titan."},sec={{t="Uno studioso in porto",b="L'Archeologo Granrutto riposa con un boccale in mano alla Locanda Acquefonde a Porto di Menethil. Come molti membri della Lega degli Esploratori di Forgiardente, ha attraversato Khaz Modan verso ovest per contribuire alle scoperte vicino al Whelgar Excavation Site nelle Paludi Grigie. Lontano dalle alte sale della biblioteca, mantiene i contatti con i ricercatori sul campo, studiando reliquie perdute e rapporti giunti attraverso il Grande Mare da spedizioni lontane."},{t="Legami con il campo",b="La curiosità nanica si spinge oltre un solo continente. Il Capo Archeologo Baffogrigio a Darnassus invia a Granrutto un Fossile Misterioso dissotterrato a Rivafosca dal distratto Prospettore Errasogni. Granrutto è stupito. Un tempo portò un fossile simile alla conferenza annuale della Lega degli Esploratori a Forgiardente, convinto che fosse possibile sprigionarne in qualche modo il potere."}},faq={{q="Chi è l'Archeologo Granrutto?",a="Granrutto è un ricercatore nanico della Lega degli Esploratori e alloggia alla Locanda Acquefonde a Porto di Menethil. Lì esamina i rapporti degli scavi e mantiene i contatti con i siti di scavo.",al={"chi è granrutto","png granrutto","storia archeologo granrutto"}},{q="Perché Granrutto si trova alla Locanda Acquefonde?",a="Granrutto è giunto a Porto di Menethil durante il viaggio verso il Whelgar Excavation Site nelle Paludi Grigie. Mentre si trova in porto, usa la locanda come base per la posta, i manufatti in arrivo e la corrispondenza dall'estero.",al={"perché granrutto si trova a menethil","posizione granrutto","cosa fa granrutto qui"}},{q="Qual è il legame tra Granrutto e Rivafosca?",a="Il Capo Archeologo Baffogrigio a Darnassus invia a Granrutto il Fossile Misterioso del Prospettore Errasogni proveniente da Rivafosca. Somiglia a un fossile che Granrutto portò a una conferenza della Lega degli Esploratori, e lui crede che questi fossili racchiudano un potere che si possa sprigionare.",al={"legame tra granrutto e rivafosca","perché una missione di rivafosca nelle paludi grigie"}},{q="A quale organizzazione appartiene?",a="Granrutto appartiene alla Lega degli Esploratori, la società reale di Re Magni Barbabronzea. La Lega cerca le antiche origini, le reliquie e la storia della razza nanica in tutta Azeroth.",al={"fazione granrutto","granrutto lega degli esploratori"}}},fx={c473457f={q="Da che parte sta l'Archeologo Granrutto?",a="L'Archeologo Granrutto è alleato di Forgiardente e dell'Alleanza. In quanto agente della Lega degli Esploratori nanica, è fedele alla sua gente e alla missione accademica di riportare alla luce e catalogare antichi reperti in tutto il mondo conosciuto.",al={"fazione di granrutto","per chi lavora granrutto","lealtà di granrutto"}},af05d80a={q="Che cosa vuole l'Archeologo Granrutto?",a="Granrutto vuole svelare i segreti dei suoi fossili. Sulla strada per gli Scavi di Whelgar, alcuni raptor hanno inghiottito la Pietra di Relu, il reperto che considera fondamentale, e ha bisogno di aiuto per recuperarla insieme al fossile originale, ora in possesso di Prospettore Whelgar, così da poterli studiare accanto al fossile di Remtravel di Rivafosca.",al={"obiettivo di granrutto","di cosa ha bisogno granrutto","perché parlare con granrutto"}}},fp="23,226,17.406.0,17.354.0,31.184.0,41.198.0,40.252.0,36.169.0"}
P.entries["npc:archaeologist-hollee"] = {n="Archaeologist Hollee",s="Ad Auberdine, l'Archaeologist Hollee segue le ricerche dei nani in tutta Rivafosca. Le antiche rovine attirano sulla costa gli studiosi di Forgiardente, e Hollee mantiene i contatti con i prospettori in cerca di reliquie e insolite formazioni geologiche.",h="Ad Auberdine, l'Archaeologist Hollee segue le ricerche dei nani in tutta Rivafosca.",kw={"archaeologist hollee","auberdine","rivafosca","lega degli esploratori","forgiardente","prospettore errasogni","the absent minded prospector","guai a rivafosca"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere nel lavoro di Hollee una collaborazione tra i Regni Orientali e gli elfi della notte, con Auberdine come base per studiare il passato di Kalimdor.",["race:Dwarf"]="Come nano, vedere una compatriota oltre il mare, nei boschi nebbiosi di Rivafosca, ti ricorda l'impulso di Forgiardente a scoprire la storia antica."},sec={{t="Una studiosa nanica nelle terre dei Kaldorei",b="L'Archaeologist Hollee lavora ad Auberdine, tra gli elfi della notte che sorvegliano e popolano Rivafosca. È un punto di contatto regionale per i topografi e le squadre di spedizione che attraversano le terre selvagge. La Lega degli Esploratori invia i propri membri oltre il mare per scoprire tracce di storia antica, e le rovine di Rivafosca offrono loro un terreno di studio."},{t="Tenere d'occhio Errasogni",b="Il Prospettore Errasogni è uno dei ricercatori sul campo di cui Hollee segue le attività. Deve svolgere importanti rilevamenti lungo la costa selvaggia, ma spesso si allontana dal lavoro e non fa rapporto nei tempi previsti. Hollee chiede ai viaggiatori di passaggio ad Auberdine di trovarlo, recuperare i dati mancanti dei rilevamenti e proteggere le ricerche dalla fauna locale e da altre minacce."}},faq={{q="Chi è l'Archaeologist Hollee?",a="L'Archaeologist Hollee è una nana di Auberdine che conduce e supervisiona ricerche sul campo per le attività archeologiche dei nani sulla costa occidentale di Kalimdor.",al={"chi è hollee","hollee rivafosca","nano ad auberdine"}},{q="Dove si può trovare Hollee?",a="Hollee si trova ad Auberdine, la cittadina portuale sulla costa occidentale di Rivafosca.",al={"posizione di hollee","dove si trova archaeologist hollee"}},{q="Perché i nani conducono ricerche a Rivafosca?",a="Dopo la Third War, i legami più stretti tra Forgiardente e gli elfi della notte hanno portato i ricercatori nani a Kalimdor. Studiano antiche reliquie, formazioni geologiche e storia sepolta che potrebbero far luce sulle origini dei nani.",al={"perché i nani sono a rivafosca","forgiardente a kalimdor"}},{q="Per quale problema ha bisogno di aiuto?",a="Hollee è preoccupata per il Prospettore Errasogni, un topografo distratto che si è avventurato nella parte meridionale di Rivafosca senza riferire le proprie scoperte.",al={"missioni di hollee","missione absent minded prospector"}},{q="Qual è il rapporto tra Hollee e il Prospettore Errasogni?",a="Hollee e il Prospettore Errasogni sono colleghi nelle attività di scavo e rilevamento a Rivafosca. Errasogni studia le rovine sul campo, mentre Hollee coordina i rapporti e parla con i viaggiatori ad Auberdine.",al={"chi è errasogni","errasogni e hollee"}},{q="Hollee appartiene alla Lega degli Esploratori?",a="Hollee rappresenta le spedizioni archeologiche e di prospezione dei nani alleate con Forgiardente. Queste spedizioni sono generalmente organizzate dalla Lega degli Esploratori, che opera dai Regni Orientali.",al={"lega degli esploratori hollee","fazione di hollee"}}},fp="20,221,35.323.0,25.349.1,28.149.0,26.85.0,49.221.0,37.145.0,65.200.0,44.203.0"}
P.entries["npc:archbishop-benedictus"] = {n="Arcivescovo Benedictus",s="A Roccavento, l'Arcivescovo Benedictus guida la Church of the Sacra Luce dalla Cathedral of Light. Guida i fedeli e l'Alleanza in tempi incerti.",h="A Roccavento, l'Arcivescovo Benedictus guida la Church of the Sacra Luce dalla Cathedral of Light.",kw={"alonsus faol","arcivescovo","benedictus","cathedral of light","chiesa della sacra luce","occhio di paleth","sacerdote","roccavento"},ang={["class:Priest"]="Come sacerdote, fai riferimento all'Arcivescovo Benedictus, che sovrintende all'addestramento, alle dottrine e ai voti di tutti i sacerdoti dell'Alleanza come capo della Church of the Sacra Luce.",["faction:Alliance"]="Come membro dell'Alleanza, puoi rivolgerti all'Arcivescovo Benedictus per una guida morale e per offrire conforto spirituale ai rifugiati. Guida anche paladini e comandanti di alto rango."},sec={{t="Pastore della Sacra Luce",b="L'Arcivescovo Benedictus guida la Church of the Sacra Luce dopo la morte del suo mentore, l'Arcivescovo Alonsus Faol. Ha visto la Prima e la Seconda Guerra devastare i regni e ha contribuito a supervisionare la costruzione della Cathedral of Light a Roccavento. Lì ha giurato di sostenere le virtù della fede.\n\nDopo la caduta di Lordaeron e l'ascesa del Flagello durante la Terza Guerra, i regni umani si sono rivolti a Benedictus come guida spirituale. Dalla cattedrale, consiglia la corte reale e addestra i sacerdoti appena iniziati. Dirige anche crociate sacre contro i non morti e le forze demoniache che minacciano Azeroth."},{t="Una Lanterna della Speranza",b="In tutta l'Alleanza, la gente considera l'Arcivescovo Benedictus un patriarca gentile, saggio e benevolo. Offre speranza al popolo e raduna eroi contro minacce oscure, tra cui Amnennar the Coldbringer a Kalimdor. Aiuta anche a purificare le reliquie maledette portate da avventurieri devoti."}},faq={{q="Chi è l'Arcivescovo Benedictus?",a="L'Arcivescovo Benedictus guida la Church of the Sacra Luce ed è la massima autorità religiosa della Grand Alleanza. Dalla Cathedral of Light a Roccavento, guida i fedeli e consiglia i capi del regno.",al={"benedictus","arcivescovo roccavento","capo della chiesa della sacra luce"}},{q="Qual è la sua relazione con Alonsus Faol?",a="L'Arcivescovo Benedictus era il principale allievo dell'Arcivescovo Alonsus Faol, fondatore dei Knights of the Mano d'Argento. Dopo la morte di Faol, Benedictus ha assunto la guida della Chiesa e ha proseguito l'opera del suo mentore.",al={"allievo di faol","alonsus faol benedictus"}},{q="Quali compiti supervisiona Benedictus per gli avventurieri?",a="L'Arcivescovo Benedictus dirige gli eroi dell'Alleanza contro il Flagello, anche in spedizioni nei Sotterranei di Lamaspina per uccidere il lich Amnennar the Coldbringer. Usa anche il potere sacro per purificare manufatti corrotti come l'Occhio di Paleth Maledetto.",al={"missioni di benedictus","cosa fa l'arcivescovo benedictus"}},{q="Qual è la sua posizione sui non morti?",a="L'Arcivescovo Benedictus invoca per i Reietti una morte rapida e definitiva. Il suo seguace Commander Karl Philips afferma che l'Arcivescovo chiede soltanto che i loro cuori vengano riportati e bruciati nella Cathedral of Light.",al={"benedictus reietti","opinioni di benedictus sul flagello"}}},fx={["40ad9930"]={q="Da che parte sta l'Arcivescovo Benedictus?",a="L'Arcivescovo Benedictus è fermamente al fianco della Grande Alleanza e della Chiesa della Luce Sacra. Risiede nella Cathedral of Light di Roccavento e fa da guida spirituale ai fedeli umani e nani, guidando i sacerdoti del regno e offrendo consiglio in assenza di Re Varian Wrynn.",al={"fazione dell'arcivescovo benedictus","benedictus è dell'alleanza","chi serve benedictus"}},ae63c6cb={q="Che cosa vuole l'Arcivescovo Benedictus?",a="Benedictus vuole preservare e diffondere le virtù della Luce Sacra in un mondo lacerato. Dopo la devastante caduta di Lordaeron per mano del Flagello, si impegna a proteggere i fedeli, formare una nuova generazione di sacerdoti e sradicare la corruzione oscura ovunque minacci l'Alleanza.",al={"obiettivo di benedictus","cosa cerca di fare benedictus","motivazione di benedictus"}},["5f68afea"]={q="Perché l'Arcivescovo Benedictus è famoso?",a="Benedictus è rinomato come guida suprema della Chiesa della Luce Sacra. Dopo aver studiato direttamente con il venerato Arcivescovo Alonsus Faol e aver contribuito a supervisionare la costruzione della magnifica Cathedral of Light di Roccavento, è venerato in tutti i Regni Orientali come esempio di pia saggezza e salda guida.",al={"perché benedictus è noto","benedictus è famoso","reputazione di benedictus"}}},fp="21,169,26.598.0,16.287.0,29.226.0,41.211.0,51.240.0,33.221.0"}
P.entries["npc:archmage-ansirem-runeweaver"] = {n="Arcimago Ansirem Tessiruna",s="Alla Cittadella Violacea, l'Arcimago Ansirem Tessiruna supervisiona le attività del Kirin Tor durante la ricostruzione di Dalaran. Mago umano di alto rango nel Consiglio dei Sei, è sopravvissuto alla distruzione della città per mano del Flagello. Sua figlia ribelle è fuggita a Baia del Bottino per diventare una piratessa.",h="Alla Cittadella Violacea, l'Arcimago Ansirem Tessiruna supervisiona le attività del Kirin Tor durante la...",kw={"ansirem","baia del bottino","catelyn","consiglio dei sei","dalaran","cittadella viola","kirin tor","granbottino","tessiruna"},ang={["class:Mage"]="Come mago, puoi rivolgerti ad Ansirem, stimato membro del Consiglio dei Sei, per ricevere una guida nello studio rigoroso delle arti arcane.",["faction:Alliance"]="Come membro dell'Alleanza, condividi gli interessi di Ansirem, un esponente del Kirin Tor che opera a Lordaeron. Gli incantatori umani lottano per riconquistare le proprie terre dai resti del Flagello."},sec={{t="Un pilastro del Kirin Tor",b="Ansirem Tessiruna ha contribuito a difendere Dalaran per decenni. Siede nel Consiglio dei Sei, che governa il Kirin Tor. È sopravvissuto quando Arthas Menethil e il Flagello hanno marciato sulla città ed è stato evocato Archimonde. Dopo la caduta di Dalaran, Ansirem ha partecipato agli sforzi per ricostruirla. Lo scudo protettivo è stato rimosso in anticipo e ora opera dalla Cittadella Violacea."},{t="Interessi lontani",b="I legami di Ansirem si estendono oltre le Montagne d'Alterac. Sua figlia ribelle, Catelyn, è fuggita a Baia del Bottino per diventare una piratessa, portando con sé un antico pugnale troll trovato da lui durante alcune ricerche a Stranglethorn. Lì Ansirem ha avuto a che fare con il Barone Granbottino. Ha anche studiato le antichità troll e mantiene aperti canali diplomatici con regni lontani."}},faq={{q="Chi è l'Arcimago Ansirem Tessiruna?",a="Ansirem è un abile mago umano e uno dei sei arcimaghi che governano il Kirin Tor nel Consiglio dei Sei. Dopo aver difeso Dalaran per decenni, ora supervisiona le attività attorno alla città ricostruita e al suo perimetro arcano.",al={"chi è ansirem","storia di ansirem tessiruna","chi è l'arcimago"}},{q="Cosa è successo a sua figlia?",a="La figlia ribelle di Ansirem, Catelyn, è fuggita a Baia del Bottino per diventare una piratessa, dove è conosciuta come Catelyn la Lama. Ha portato con sé un antico pugnale troll che Ansirem aveva trovato durante alcune ricerche a Stranglethorn.",al={"figlia di ansirem","catelyn la lama","catelyn tessiruna"}},{q="Qual è il suo ruolo a Dalaran?",a="Ansirem è una figura di spicco del Kirin Tor nella Cittadella Violacea. Coordina la ricerca, la difesa magica e le comunicazioni con gli alleati durante la ricostruzione di Dalaran dopo la distruzione della Terza Guerra.",al={"perché ansirem si trova ad alterac","ansirem dalaran","cosa ci fa qui"}},{q="Ansirem ha combattuto nella Terza Guerra?",a="Sì. Ansirem ha contribuito a difendere Dalaran per decenni ed è sopravvissuto all'assedio del Flagello. Arthas ha protetto Kel'Thuzad mentre evocava Archimonde. Ansirem è sopravvissuto alla distruzione della città e ora contribuisce a ricostruirla.",al={"ansirem flagello","ansirem ha combattuto contro arthas"}}},fp="27,255,25.359.0,19.339.0,35.214.0,30.206.0,28.190.0,35.204.0"}
P.entries["npc:archmage-malin"] = {n="Arcimago Malin",s="Fuori dal Santuario della Magia a Roccavento, l'Arcimago Malin dirige gli affari arcani della città. Un tempo allievo dell'Archmage Trelane, ora coordina agenti alla ricerca di manufatti magici e reagenti rari in tutti i Regni Orientali.",h="Fuori dal Santuario della Magia a Roccavento, l'Arcimago Malin dirige gli affari arcani della città.",kw={"altopiani d'arathi","arcimago malin","kryten","quartiere dei maghi","malin","skuerto","roccavento","trelane","santuario della magia"},ang={["class:Mage"]="Come mago dell'Alleanza in visita al Santuario della Magia, vedi Malin collegare gli studi accademici di Roccavento ai pericoli del recupero di reliquie perdute nelle terre selvagge.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, sai che gli agenti di Malin ad Arathi cercano potenti manufatti prima che la Lega dei Tagliagole, gli ogre Boulderfist o l'Orda se ne impadroniscano."},sec={{t="Guardiano del Santuario della Magia",b="Nel Quartiere dei Maghi, l'Arcimago Malin sovrintende ai praticanti dell'arcano di Roccavento dalla base del Santuario della Magia. Ha appreso la magia sotto la guida dell'Archmage Trelane e ora protegge l'eredità dispersa del suo antico maestro. Gli accoliti studiano all'interno della torre. Malin vigila sulle questioni del regno che richiedono una supervisione magica."},{t="Occhi negli Altopiani",b="A nord, tra le pericolose rovine degli Altopiani d'Arathi, i fidati collaboratori dell'Arcimago Malin cercano i beni perduti di Trelane e delicati componenti per incantesimi. Skuerto e l'Apprendista Kryten svolgono questo compito. Dalla capitale, Malin coordina i loro sforzi e si affida ad abili viaggiatori dell'Alleanza per portare istruzioni, provviste e informazioni in territorio ostile."}},faq={{q="Chi è l'Arcimago Malin?",a="L'Arcimago Malin è un mago umano di alto rango a Roccavento. Fuori dal Santuario della Magia, nel Quartiere dei Maghi, sovrintende alle ricerche, invia apprendisti sul campo e contribuisce a mantenere l'ordine tra i praticanti di magia della capitale.",al={"storia dell'arcimago malin","chi è malin","malin roccavento"}},{q="Qual è il legame di Malin con l'Archmage Trelane?",a="L'Archmage Trelane è stato maestro e mentore dell'Arcimago Malin. Malin rimane fedele al suo antico maestro e coordina le operazioni negli Altopiani d'Arathi per recuperare i beni e le reliquie magiche di Trelane.",al={"malin trelane","chi era il maestro di malin","legame con l'arcimago trelane"}},{q="Perché Malin invia avventurieri negli Altopiani d'Arathi?",a="L'Arcimago Malin invia viaggiatori negli Altopiani d'Arathi per raggiungere i suoi agenti, Skuerto e l'Apprendista Kryten. Il viaggio è pericoloso e comunicare è difficile, così i viaggiatori trasportano richieste, scorte magiche e istruzioni per recuperare i manufatti di Trelane.",al={"missione richiesta di malin","perché arathi","missione di skuerto"}},{q="Dove si trova l'Arcimago Malin?",a="Puoi trovare l'Arcimago Malin fuori dall'ingresso del Santuario della Magia, alla base della torre nel Quartiere dei Maghi di Roccavento. Da lì, tiene d'occhio le rampe che conducono alla sala dei portali del santuario.",al={"dove si trova malin","posizione dell'arcimago malin","mappa di malin"}}},fx={deac5a59={q="Da che parte sta l'Arcimago Malin?",a="L'Arcimago Malin è fedele all'Alleanza e presta servizio a Roccavento. Situato in posizione di rilievo davanti al Santuario della Magia, nel Quartiere dei Maghi, collabora strettamente con altri maghi umani e si affida ad agenti fidati e avventurieri dell'Alleanza per svolgere le sue richieste nei Regni Orientali.",al={"malin è dell'alleanza","fazione di malin","chi serve malin"}},["77b45b55"]={q="Perché l'Arcimago Malin si trova a Roccavento?",a="L'Arcimago Malin si trova davanti al Santuario della Magia per coordinare le attività magiche e supervisionare le operazioni lontano dalla capitale. Pur restando a Roccavento, invia agenti come Skuerto e Apprendista Kryten in regioni remote e pericolose come gli Altopiani d'Arathi, chiedendo ai viaggiatori capaci di passaggio in città di aiutarli.",al={"perché malin è a roccavento","scopo di malin al santuario della magia","perché malin è fuori dal santuario"}}},fp="14,230,31.318.0,21.374.0,22.228.0,47.193.0,56.265.0,34.198.0"}
P.entries["npc:archmage-xylem"] = {n="Arcimago Xylem",s="Ad Azshara settentrionale, l'Arcimago Xylem vive appartato dal mondo. Conduce ricerche arcane in una torre isolata e riceve solo chi può aiutarlo nei suoi studi o compiere le sue vendette.",h="Ad Azshara settentrionale, l'Arcimago Xylem vive appartato dal mondo.",kw={"arcano","arcimago","azshara","morphaz","sanath lim-yo","torre","xylem"},ang={["class:Mage"]="Come mago, puoi riconoscere la suprema padronanza delle arti arcane di Xylem. La sua ricerca del potere magico nel completo isolamento suscita una particolare inquietudine.",["faction:Horde"]="Pur essendo umano, Xylem è disposto a trattare con i campioni dell'Orda che possono aiutarlo nei suoi studi.",["race:Human"]="Come umano, puoi vedere come Xylem si sia lasciato alle spalle la società umana. Vive indisturbato in cima alle alture selvagge di Azshara."},sec={{t="Un solitario sopra la costa",b="L'Arcimago Xylem vive in una guglia appartata sopra la costa elfica in rovina di Azshara settentrionale. Nessuna strada o sentiero raggiunge il suo santuario. Il suo servitore Sanath Lim-yo trasporta magicamente in cima alle scogliere i visitatori autorizzati.\n\nIn tutta Kalimdor, Xylem è noto per la sua profonda eccentricità e avvicinarlo è considerato pericoloso. Persino gli altri studiosi lo trattano con cautela. Si comporta diversamente da quasi ogni altro mago umano."},{t="Un rancore contro Morphaz",b="L'Arcimago Xylem nutre un feroce rancore verso lo stormo dei draghi verdi, soprattutto verso il draco Morphaz. Un tempo il drago inghiottì per intero uno degli apprendisti di Xylem, insieme a un frammento arcano di immenso potere.\n\nXylem non piange l'apprendista. Resta deciso a dare la caccia a Morphaz e a recuperare il prezioso manufatto dal ventre del drago."}},faq={{q="Come si raggiunge la torre dell'Arcimago Xylem?",a="Nessun sentiero percorribile a piedi raggiunge la torre dell'Arcimago Xylem, in cima a una scogliera di Azshara settentrionale. Trova il suo servitore, Sanath Lim-yo, vicino alla base delle scogliere. Può trasportarti magicamente ai piedi della torre.",al={"arrivare da xylem","raggiungere la torre di xylem","teletrasportarsi da xylem","posizione di xylem"}},{q="Chi è l'Arcimago Xylem?",a="Ad Azshara settentrionale, l'Arcimago Xylem vive in una torre isolata e conduce pericolosi esperimenti arcani lontano dalla civiltà. L'eccentrico arcimago umano vive appartato dal mondo.",al={"chi è xylem","storia dell'arcimago xylem","passato di xylem"}},{q="Perché Xylem vuole la morte del drago Morphaz?",a="Morphaz inghiottì per intero uno degli apprendisti dell'Arcimago Xylem, insieme a un frammento di immenso potere arcano. Xylem vuole la morte del draco verde per poter recuperare la reliquia dal suo stomaco.",al={"xylem morphaz","perché uccidere morphaz","frammento di morphaz"}},{q="Perché si dice che Xylem sia pericoloso?",a="Jediga e altri contatti locali avvertono che l'Arcimago Xylem è imprevedibile, distaccato e decisamente strano rispetto agli altri umani.",al={"xylem è pericoloso","xylem pazzo","personalità di xylem"}},{q="Xylem appartiene all'Alleanza o al Kirin Tor?",a="L'Arcimago Xylem vive da eremita indipendente. Non serve nell'esercito dell'Alleanza e tratta con qualsiasi avventuriero disposto a eseguire i suoi ordini, a qualunque fazione appartenga.",al={"fazione di xylem","xylem appartiene all'alleanza","xylem kirin tor"}}},fp="14,184,25.381.0,24.334.1,40.186.0,22.185.0,44.183.0,37.131.0,51.171.0"}
P.entries["npc:argent-guard-manados"] = {n="Guardia d'Argento Manados",s="A Darnassus, la Guardia d'Argento Manados vigila sulla corruzione in tutta Kalimdor. Serve l'Alba d'Argento e chiede aiuto contro il Martello del Crepuscolo sotto le onde di Valtetra.",h="A Darnassus, la Guardia d'Argento Manados vigila sulla corruzione in tutta Kalimdor.",kw={"alba d'argento","guardia d'argento manados","abissi di fondocupo","terrazza degli artigiani","darnassus","manados","twilight falls"},ang={["faction:Alliance"]="Come campione dell'Alleanza in visita a Darnassus, puoi rivolgerti a Manados per trovare un legame tra le lontane crociate a Lordaeron e la crescente minaccia dei cultisti a Kalimdor settentrionale.",["race:NightElf"]="Come elfo della notte, puoi vedere in Manados che il dovere va oltre il Circolo Cenariano e le Sentinels. Alcuni elfi della notte servono ordini neutrali come l'Alba d'Argento per preservare Azeroth."},sec={{t="Una Sentinella dell'Alba",b="La Guardia d'Argento Manados veglia per conto dell'Alba d'Argento a Darnassus. Gran parte dell'ordine difende Lordaeron dal Flagello, mentre lui si trova tra gli artigiani e i commercianti della Terrazza degli Artigiani. Da lì, sorveglia le minacce all'equilibrio di Kalimdor settentrionale. Gli giunge notizia che il Martello del Crepuscolo ha stabilito una presenza sotto le onde di Valtetra. Così chiama a raccolta eroi capaci per colpire gli Abissi di Fondocupo e recuperare i manufatti dell'oscura devozione del culto."}},faq={{q="Chi è la Guardia d'Argento Manados?",a="Manados è un elfo della notte dell'Alba d'Argento, di stanza a Darnassus. Sorveglia Kalimdor alla ricerca di culti oscuri e corruzione ultraterrena, mentre l'ordine si concentra sul Flagello nei Regni Orientali.",al={"chi è manados","ruolo guardia d'argento manados","manados darnassus"}},{q="Dove posso trovare la Guardia d'Argento Manados?",a="Puoi trovare Manados a Darnassus, nella Terrazza degli Artigiani. Veglia sulla città e si coordina con gli avventurieri locali.",al={"posizione di manados","dove si trova la guardia d'argento manados","manados terrazza degli artigiani"}},{q="Quali missioni assegna la Guardia d'Argento Manados?",a="Manados offre la missione Twilight Falls. Manda gli avventurieri negli Abissi di Fondocupo, a Valtetra, per recuperare i Twilight Pendants dai cultisti al loro interno.",al={"missioni di manados","twilight falls chi dà la missione","missione alba d'argento abissi di fondocupo"}},{q="Perché l'Alba d'Argento è interessata agli Abissi di Fondocupo?",a="L'Alba d'Argento vigila sulle forze maligne che minacciano Azeroth. Il Martello del Crepuscolo è comparso nelle rovine sommerse di Valtetra, dove il culto venera entità antiche e corrotte. L'ordine non può ignorare quel pericolo.",al={"perché l'alba d'argento si interessa ad abissi di fondocupo","alba d'argento culto del crepuscolo"}}},fx={df5dd966={q="Da che parte sta la Guardia d'Argento Manados?",a="La Guardia d'Argento Manados presta servizio nell'Alba d'Argento, un ordine indipendente dedito a sradicare il male e proteggere Azeroth dalla corruzione oscura. Sebbene sia un elfo della notte di stanza nella capitale Darnassus, la sua principale fedeltà va alla crociata globale dell'Alba, più che al normale comando dell'Alleanza.",al={"fazione di manados","chi serve manados","manados è dell'alleanza"}},f4cc0234={q="Che cosa vuole la Guardia d'Argento Manados?",a="Manados vuole fermare i rituali oscuri che stanno prendendo piede lungo la costa di Valtetra. Recluta avventurieri capaci per esplorare gli Abissi di Fondocupo e colpire i cultisti del Martello del Crepuscolo, che hanno profanato l'antico santuario degli elfi della notte.",al={"che cosa cerca manados","obiettivi di manados","perché manda agli abissi di fondocupo"}}},fp="20,180,22.469.0,28.193.0,38.136.0,43.143.0,55.218.0"}
P.entries["npc:argos-nightwhisper"] = {n="Argos Soffianotte",s="Nel Parco di Roccavento, Argos Soffianotte indirizza i viaggiatori dell'Alleanza verso Rivafosca. Suo fratello Gershala studia la corruzione che si diffonde laggiù.",h="Nel Parco di Roccavento, Argos Soffianotte indirizza i viaggiatori dell'Alleanza verso Rivafosca.",kw={"argos","auberdine","corruzione all'estero","darnassus","kaldorei","soffianotte","parco","roccavento"},ang={["faction:Alliance"]="Come eroe dell'Alleanza, puoi rivolgerti ad Argos come punto di contatto tra i Regni Orientali e Kalimdor. Incoraggia i giovani eroi ad attraversare il mare e ad aiutare gli elfi della notte.",["race:NightElf"]="Come kaldorei lontano da Kalimdor, potresti trovare in Argos un volto familiare. Indirizza i viaggiatori verso suo fratello a Rivafosca e le minacce che mettono in pericolo la loro patria."},sec={{t="Un Kaldorei nella Capitale Umana",b="Argos Soffianotte vive tra gli elfi della notte riuniti nel Parco di Roccavento. I suoi quieti boschetti ricordano loro le foreste ancestrali dei kaldorei. Come altri della sua stirpe nel regno umano, Argos aiuta a mantenere i contatti tra i nuovi alleati sulle due sponde del Grande Mare. Le notizie che giungono da oltreoceano lo preoccupano. Esorta i campioni più capaci dell'Alleanza a recarsi ad Auberdine, a Rivafosca, dove suo fratello Gershala ha bisogno di aiuto contro la corruzione dilagante."}},faq={{q="Chi è Argos Soffianotte?",a="Argos Soffianotte è un elfo della notte che vive a Roccavento. Rappresenta Darnassus nella capitale orientale dell'Alleanza e indirizza i viaggiatori verso un imbarco per Kalimdor.",al={"argos soffianotte","chi è argos","argos roccavento"}},{q="Dove si trova Argos Soffianotte?",a="Puoi trovare Argos nel Parco, il quartiere verde di Roccavento dove si radunano gli elfi della notte in visita.",al={"posizione di argos","dove si trova argos","trova argos soffianotte"}},{q="Cosa chiede di fare Argos agli avventurieri?",a="Argos chiede agli avventurieri esperti di recarsi ad Auberdine, a Rivafosca. Suo fratello Gershala ha bisogno di aiuto per studiare la corruzione che si diffonde nella regione.",al={"missione corruzione all'estero","missione di argos","perché andare a darnassus"}},{q="Argos è imparentato con altri Soffianotte?",a="Sì. Argos è il fratello di Gershala Soffianotte, uno studioso elfo della notte che si trova ad Auberdine, a Rivafosca. È per questo che Argos manda i viaggiatori laggiù.",al={"famiglia soffianotte","parenti di argos"}}},fx={["50b5b885"]={q="Da che parte sta Argos Soffianotte?",a="Argos Soffianotte è fermamente al fianco dell'Alleanza e dei suoi conterranei kaldorei. Elfo della notte residente tra gli emissari e i viaggiatori del Parco di Roccavento, resta fedele a Darnassus e assiste i viaggiatori e gli eroi impegnati a difendere e favorire il benessere dell'Alleanza.",al={"fazione di argos soffianotte","argos è dell'alleanza","chi serve argos"}},e48f5556={q="Perché Argos Soffianotte si trova a Roccavento?",a="Argos si trova nel Parco, il rigoglioso santuario riservato agli elfi della notte a Roccavento. Come molti dei suoi conterranei nella capitale umana, fa da emissario e punto di contatto tra Darnassus e i Regni Orientali, cercando campioni capaci di aiutare i kaldorei nelle questioni che li riguardano all'estero.",al={"perché argos è a roccavento","perché argos soffianotte è qui","che cosa fa argos a roccavento"}}},fp="18,144,31.434.0,26.165.0,38.98.0,38.152.0,40.139.0"}
P.entries["npc:arugal"] = {n="Arugal",s="Nel Forte di Zannascura, Arugal comanda i worgen che evocò contro il Flagello. La follia e il dolore hanno reso l'ex mago di Dalaran il loro autoproclamato padre, e il suo potere minaccia la Selva Pinargento.",h="Nel Forte di Zannascura, Arugal comanda i worgen che evocò contro il Flagello.",kw={"arugal","kirin tor","rovonero","zannascura","argenius","selva pinargento","ur","worgen"},ang={["class:Mage"]="Arugal mostra il pericolo delle evocazioni avventate. Le ricerche del Kirin Tor si trasformarono in un incubo incontrollabile.",["faction:Horde"]="I worgen di Arugal infestano la strada a sud di Mausolea. Lady Sylvanas ha ordinato la sua esecuzione per mettere al sicuro la Selva Pinargento per i Reietti.",["race:Undead"]="Le bestie di Arugal hanno ucciso diversi Deathstalker e speziali. La Royal Apothecary Society ha bisogno che si ponga fine alla sua follia."},sec={{t="Un'evocazione disperata",b="Prima della caduta di Lordaeron, Arugal serviva nel Kirin Tor. Alcuni suoi pari, tra cui Dalar Tessalba, lo definivano un ciarlatano che nascondeva le sue deboli arti magiche dietro ninnoli incantati. Quando il Flagello dilagò nel nord durante la Terza Guerra, Arugal cercò un'arma per fermare i non morti. Attinse alle ricerche del defunto mago di Dalaran Ur e squarciò il velo tra i reami per evocare i worgen.\n\nLe bestie fameliche fecero strage tra le schiere del Flagello, ma nessuno riuscì a contenerne la ferocia. Ben presto, la loro fame si rivolse contro mortali innocenti."},{t="Caduta nella follia",b="I worgen massacrarono le schiere del Flagello, poi attaccarono i maghi che li avevano evocati. Assediarono la dimora ancestrale del Barone Argenius e conquistarono il forte con artigli e zanne. Argenius e i suoi servitori morirono nel massacro. Il senso di colpa spezzò la mente di Arugal, che tuttavia rimase con la sua creazione. Dichiarò che le bestie erano la sua prole e ribattezzò la fortezza Forte di Zannascura.\n\nLì, Arugal presidia i bastioni, circondato da vittime spettrali e fedeli branchi di segugi."},{t="Il flagello della Selva Pinargento",b="Dal Forte di Zannascura, il potere di Arugal si estende sulle campagne. La sua stregoneria oscura avvolge Rovonero, dove gli abitanti vivono sotto una maledizione notturna. Inoltre, riempie l'Abisso di Elem di fameliche bestie Moonrage.\n\nI Reietti vedono in lui una minaccia intollerabile. I Deathstalker e gli speziali di Sylvanas Ventolesto tramano l'esecuzione di Arugal per mettere al sicuro i confini del loro regno nascente."}},faq={{q="Chi è Arugal?",a="Arugal è un ex arcimago umano del Kirin Tor. Durante la Terza Guerra, evocò i worgen per combattere il Flagello. Sopraffatto da ciò che aveva fatto, si ritirò nel Forte di Zannascura e ora guida branchi di worgen come loro autoproclamato padre.",al={"chi è arugal","storia di arugal","storia boss zannascura"}},{q="Perché Arugal ha evocato i worgen?",a="Durante la Terza Guerra, il Flagello minacciava di travolgere il nord di Lordaeron. In cerca di un'arma contro i non morti, Arugal attinse alle ricerche extraplanari del mago di Dalaran Ur. Credeva che le bestie selvagge potessero distruggere il Flagello, ma ne perse il controllo dopo averle evocate.",al={"perché i worgen","perché evocare le bestie","movente worgen arugal"}},{q="Dove risiede Arugal in questo momento?",a="Arugal ha la sua tana in cima al Forte di Zannascura, un'antica fortezza che domina Rovonero, nella parte meridionale della Selva Pinargento. Fenrus, il suo mostruoso lupo da compagnia, lo protegge insieme a worgen fedeli e spiriti inquieti.",al={"dov'è arugal","posizione di arugal","trovare arugal"}},{q="Cosa è successo al Barone Argenius?",a="Il Barone Argenius governava la fortezza e il villaggio di Rovonero. Quando i worgen di Arugal assediarono il castello, Argenius e la sua corte furono massacrati. I loro fantasmi tormentati infestano le sale del forte.",al={"destino barone argenius","chi possedeva zannascura","storia del forte"}},{q="Perché i Reietti vogliono la morte di Arugal?",a="I branchi di Arugal terrorizzano la Selva Pinargento, attaccando gli esploratori dei Reietti, tendendo imboscate alle pattuglie e infettando i servitori della Royal Apothecary Society. Sylvanas Ventolesto considera il folle arcimago una minaccia diretta alla sicurezza e all'espansione dei confini di Sepulcra.",al={"reietti contro arugal","missione arugal must die","perché uccidere arugal"}},{q="Qual è la maledizione su Rovonero?",a="Gli incantesimi di Arugal hanno assoggettato gli abitanti umani di Rovonero alla maledizione dei worgen. Alla luce del giorno, gli abitanti del villaggio appaiono umani. Al calare della notte, diventano bestie feroci vincolate a difendere il territorio di Arugal.",al={"maledizione di rovonero","perché gli abitanti di rovonero sono lupi","rovonero arugal"}}},fx={c709d248={q="Da che parte sta l'Arcimago Arugal?",a="Arugal non serve né l'Alleanza né l'Orda. Un tempo membro del Kirin Tor di Dalaran, ha reciso ogni legame dopo essere impazzito. Oggi guida il suo branco ferino nel Forte di Zannascura, considera i worgen i suoi veri figli e respinge con violenza sia gli emissari del Kirin Tor sia i Reietti.",al={"fazione di arugal","chi serve arugal","arugal è dell'orda o dell'alleanza"}},["5a0ecd53"]={q="Che cosa vuole l'Arcimago Arugal?",a="Consumanto dal senso di colpa e dalla follia dopo aver scatenato i worgen sul mondo, Arugal ora vuole proteggere, comandare e ampliare il suo branco. Usa la magia incantata per piegare le bestie al suo volere e diffonde la maledizione dei worgen per tutta la Selva Pinargento, così da creare la sua oscura famiglia e massacrare chiunque osi invadere il suo dominio.",al={"obiettivo di arugal","cosa cerca di fare arugal","motivazione di arugal"}},["127eccbf"]={q="Perché l'Arcimago Arugal si trova nel Forte di Zannascura?",a="Dopo che i worgen evocati sfuggirono al controllo, assalirono la fortezza del Barone Argenius sopra Rovonero. Impazzito per la catastrofe che aveva provocato, Arugal adottò le feroci bestie come figli, prese possesso del forte in rovina e lo ribattezzò Zannascura per governare il suo branco in un dominio isolato.",al={"perché arugal è qui","perché arugal è andato a zannascura","come ha ottenuto arugal il forte di zannascura"}},["760497b6"]={q="Perché l'Arcimago Arugal è temuto?",a="Arugal è famigerato in tutta Lordaeron per aver attinto alle ricerche proibite di Ur e aver scatenato i feroci worgen sul mondo. La maledizione che ha evocato non si è limitata a uccidere il Flagello: ha infettato le terre vicine, trasformato pacifici abitanti dei villaggi in bestie assetate di sangue e ridotto un'intera regione a un incubo sotto il suo instabile dominio magico.",al={"perché arugal è famoso","reputazione di arugal","perché arugal è pericoloso"}}},fp="6,206,19.527.0,17.463.0,25.398.1,14.242.0,33.280.0,35.225.0,35.197.0,37.264.0,38.207.0"}
P.entries["npc:ashlan-stonesmirk"] = {n="Ashlan Pietroscura"}
P.entries["npc:asterion"] = {n="Asterion",s="A Bashal'aran, Asterion resta vincolato a un sigillo di pietra di luna. L'antico Eletto un tempo serviva il governatore Athrikus Narassin, e ora il suo spirito attende tra le rovine di essere liberato.",h="A Bashal'aran, Asterion resta vincolato a un sigillo di pietra di luna.",kw={"ameth'aran","asterion","athrikus","bashal'aran","rivafosca","highborne","pietra di luna","narassin","satiro"},ang={["class:Mage"]="In vita, Asterion era celebrato per la sua padronanza delle arti arcane e la sua abilità nel combattimento fisico. La sua storia offre uno scorcio delle antiche arti magiche dei Kaldorei.",["faction:Alliance"]="Asterion è uno dei rari spiriti degli Eletti disposti a fidarsi degli avventurieri dell'Alleanza e ad aiutarli. Cerca il loro aiuto per spezzare la prigionia che dura da diecimila anni.",["race:NightElf"]="Asterion è una tragica vestigia di un'epoca precedente al Grangorgo. La sua storia mostra le crudeli lotte di potere tra gli Eletti prima che Azshara invitasse la Legione Infuocata nelle loro terre."},sec={{t="Un servitore dell'antico splendore",b="Prima del Grande Grangorgo, Bashal'aran e Ameth'aran erano città gemelle benedette dalla regina Azshara. Lei nominò Athrikus Narassin loro governatore, e Asterion fu il suo braccio destro. Rinomato per il combattimento fisico e la stregoneria arcana, Asterion viveva tra la gente di Bashal'aran. Viaggiava spesso tra le città gemelle per provvedere alle necessità dei loro abitanti."},{t="La prigione di pietra di luna",b="Per ragioni perdute nel tempo, Asterion cadde in disgrazia presso Athrikus Narassin. Il suo signore creò un potente sigillo di pietra di luna, una gabbia magica senza via di scampo destinata a confinarlo a Bashal'aran. I secoli di prigionia inflissero ad Asterion grandi tormenti. Nemmeno la morte gli offrì la libertà: il suo spirito rimase vincolato al santuario in rovina dopo che il mondo si squarciò e i demoni invasero l'insediamento."},{t="Vendetta dalla tomba",b="Vili satiri e grell vagano per Bashal'aran, nutrendosi del suo potere arcano residuo, ma evitano il santuario dove permane il fantasma di Asterion. Un avventuriero dell'Alleanza può sottrarre ai satiri il sigillo di pietra di luna e frantumarlo ad Ameth'aran, spezzando finalmente le catene spettrali di Asterion. La libertà non porta pace. Con Athrikus Narassin ancora in vita, Asterion si lascia alle spalle diecimila anni di disperazione e si volge alla vendetta."}},faq={{q="Chi è Asterion?",a="Asterion è il fantasma di un antico Eletto presso le rovine di Bashal'aran, a Rivafosca. Prima del Grangorgo, era un abile mago e il secondo in comando del governatore Athrikus Narassin.",al={"storia di asterion","chi è il fantasma a bashal'aran","fantasma elfo rivafosca"}},{q="Perché Asterion è imprigionato?",a="Athrikus Narassin vincolò Asterion con un sigillo magico di pietra di luna. Le ragioni del loro dissidio sono ignote, ma il potente incantesimo trattenne lo spirito di Asterion per millenni, anche dopo la morte.",al={"perché asterion è intrappolato","prigione di asterion","perché athrikus ha intrappolato asterion"}},{q="Perché i satiri di Bashal'aran non lo attaccano?",a="Satiri e grell si nutrono delle energie arcane residue di Bashal'aran, ma si tengono lontani dal santuario dove Asterion è vincolato. I satiri possiedono il sigillo di pietra di luna che lo tiene prigioniero, anziché interferire con il suo spirito.",al={"i satiri attaccano asterion","perché i demoni lasciano in pace asterion"}},{q="Dove viveva Asterion in vita?",a="Asterion viveva tra la gente di Bashal'aran. Viaggiava spesso verso sud fino alla sua città gemella, Ameth'aran, per occuparsi degli affari civici al servizio del governatore della regina Azshara.",al={"casa di asterion","da dove veniva asterion"}},{q="Cosa succede dopo averlo liberato?",a="Asterion spera che spezzare il sigillo di pietra di luna ponga fine alla prigionia che si è protratta oltre la sua morte. Ciò che segue è narrato nel passaggio nascosto.",al={"cosa succede ad asterion","asterion trova la pace","vendetta di asterion"}},{q="Asterion è ostile ai moderni elfi della notte?",a="No. Sebbene Asterion sia un antico Eletto della corte della regina Azshara, è pacifico nei confronti dei viaggiatori dell'Alleanza e cerca il loro aiuto per spezzare la sua antica prigionia magica.",al={"asterion è amichevole","asterion alleanza"}}},fx={["0f52734c"]={q="Che cosa vuole Asterion?",a="Asterion vuole essere liberato dall'antica prigione magica che tiene intrappolato il suo spirito da diecimila anni. Athrikus Narassin lo legò a Bashal'aran con un sigillo di pietra lunare, condannandolo a soffrire anche dopo la morte fisica. Ha un disperato bisogno che tu recuperi questo sigillo dai satiri e lo distrugga ad Ameth'aran, ponendo fine al suo lungo tormento e permettendogli di rivolgere i suoi pensieri alla vendetta contro il suo antico padrone.",al={"obiettivo di asterion","di cosa ha bisogno asterion","motivazioni di asterion"}},["98a0ebe3"]={q="A chi è legato Asterion?",a="In tempi antichi, Asterion era al diretto servizio di Athrikus Narassin, il signore degli Alti Nobili incaricato dalla regina Azshara di governare Ameth'aran e Bashal'aran. Come secondo in comando, si occupava delle necessità di entrambi gli insediamenti. Nonostante la sua lealtà, Athrikus usò la sua arte oscura per imprigionare Asterion in una prigione arcana di pietra lunare, per ragioni ormai perdute nella storia, trasformando il loro antico legame in un retaggio di tradimento.",al={"padrone di asterion","chi ha imprigionato asterion","athrikus narassin e asterion"}}},fp="8,175,29.355.0,20.384.0,24.410.1,16.187.0,27.195.0,47.230.0,32.158.0,32.150.1,42.171.0"}
P.entries["npc:athridas-bearmantle"] = {n="Athridas Orsomanto",s="A Dolanaar, Athridas Orsomanto chiama i giovani avventurieri a difendere l'insediamento e le terre selvagge circostanti. Il druido elfo della notte li manda a indagare sulla corruzione che colpisce la fauna locale e i vicini furbolg Gnarlpine.",h="A Dolanaar, Athridas Orsomanto chiama i giovani avventurieri a difendere l'insediamento e le terre selvagge...",kw={"athridas","orsomanto","dolanaar","furbolg","gnarlpine","kaldorei","elfo della notte","teldrassil"},ang={["class:Druid"]="Gli sforzi di Athridas Orsomanto contro i Gnarlpine corrotti e la sua premura per le antiche reliquie riguardano l'equilibrio della natura che i druidi hanno giurato di ristabilire.",["race:NightElf"]="Ai giovani Kaldorei che lasciano Vallombra, Athridas Orsomanto mostra le difficoltà della loro nuova dimora, già minacciata dall'interno."},sec={{t="Guardiano di Dolanaar",b="Athridas Orsomanto aiuta a difendere gli Elfi della Notte che arrivano a Dolanaar da Vallombra. Teldrassil, l'Albero del Mondo appena cresciuto, mostra segni innaturali di decadimento e agitazione. Così Athridas organizza le ricognizioni locali e protegge la cittadina dalle minacce provenienti dalle terre selvagge circostanti."},{t="L'afflizione dei furbolg",b="Athridas Orsomanto è preoccupato per i vicini furbolg Gnarlpine. Un tempo vicini pacifici, i membri della tribù sono caduti preda di una follia e di una corruzione dilaganti. La contaminazione avvelena i loro sciamani e capitribù, spingendoli alla violenza contro i Kaldorei. Athridas chiama a raccolta campioni volenterosi per contenere il pericolo e indagare sulla corruzione più profonda che mette radici nelle terre selvagge."}},faq={{q="Chi è Athridas Orsomanto?",a="Athridas Orsomanto aiuta a difendere Dolanaar su Teldrassil. Organizza la difesa dell'insediamento e chiama gli avventurieri ad affrontare le minacce che si aggirano tra i rami dell'Albero del Mondo.",al={"chi è athridas","storia di athridas orsomanto","athridas dolanaar"}},{q="Dove posso trovare Athridas Orsomanto?",a="Trovi Athridas Orsomanto a Dolanaar, la prima cittadina importante che gli avventurieri elfi della notte raggiungono dopo aver lasciato Vallombra, su Teldrassil.",al={"posizione di athridas","dove si trova athridas","trovare athridas orsomanto"}},{q="Su quali minacce si concentra Athridas?",a="Athridas Orsomanto si concentra sugli aggressivi furbolg Gnarlpine, che la corruzione ha spinto ad attaccare. Incarica i viaggiatori di respingere i loro assalti, indagare sulla loro follia e recuperare reliquie vitali.",al={"missioni di athridas","cosa vuole athridas","compiti di athridas orsomanto"}},{q="Perché i furbolg Gnarlpine stanno attaccando Dolanaar?",a="La tribù Gnarlpine è caduta preda di una corruzione innaturale che si diffonde attraverso Teldrassil. Ha fatto impazzire i suoi sciamani e guerrieri, colmandoli di ostilità verso gli Elfi della Notte.",al={"perché i gnarlpine sono impazziti","corruzione dei gnarlpine","ostilità dei furbolg teldrassil"}},{q="Che ruolo ha Athridas nella messa in sicurezza di Teldrassil?",a="Athridas Orsomanto organizza una prima difesa contro la corruzione che colpisce le bestie e i furbolg di Teldrassil. Si adopera per impedire che il pericolo travolga Dolanaar.",al={"ruolo di athridas","importanza di athridas"}}},fx={["04c7b610"]={q="Da che parte sta Athridas Orsomanto?",a="Athridas è fermamente al fianco degli Elfi della Notte di Darnassus e dell'Alleanza. Di stanza a Dolanaar, dedica i suoi sforzi a proteggere la sua gente e a mantenere l'ordine in tutta Teldrassil, contrastando la corruzione dilagante.",al={"fazione di athridas","al servizio di athridas","lealtà di athridas orsomanto"}},aae97259={q="Che cosa vuole Athridas Orsomanto?",a="Athridas vuole purificare la piaga improvvisa che avvelena la fauna selvatica di Teldrassil e placare la furia che sta sopraffacendo i furbolg Zannatorta locali. Si affida a viaggiatori capaci perché indaghino sulla corruzione, recuperino reliquie sacre e neutralizzino i pericolosi furbolg ribelli che minacciano Dolanaar.",al={"obiettivo di athridas","che cosa cerca di fare athridas","motivazioni di athridas orsomanto"}},["7a39a622"]={q="Perché Athridas Orsomanto si trova qui a Dolanaar?",a="Dolanaar è il primo insediamento importante che i viaggiatori incontrano dopo Vallombra, perciò è il centro da cui gestire le crisi locali. Athridas è di stanza qui per coordinare le difese, sorvegliare le foreste inquiete e mandare gli avventurieri contro le minacce sempre più gravi nei boschi.",al={"perché athridas è a dolanaar","incarico di athridas","motivo della presenza di athridas"}}},fp="19,209,20.270.0,22.368.0,27.179.0,37.126.0,36.208.0,50.171.0,52.160.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="\"Zia\" Bernice Pietradura",s="Nella tenuta degli Stonefield, nella Foresta di Elwynn centro-meridionale, la “Zia” Bernice Pietradura veglia sul vicinato. Rimasta vedova a causa delle campagne militari del regno, vive accanto a Ma Pietradura ed è nota in tutta la valle per i suoi Pasticci di Carne di Cinghiale. Nutre ancora profondi sospetti verso la famiglia rivale dei Maclure.",h="Nella tenuta degli Stonefield, nella Foresta di Elwynn centro-meridionale, la “Zia” Bernice Pietradura veglia...",kw={"zia","bernice","elwynn","goldtooth","maclure","collana","pasticcio di carne di cinghiale","stonefield"},ang={["profession:Cooking"]="Il Pasticcio di Carne di Cinghiale di Bernice è famoso in tutta la Foresta di Elwynn come piatto tipico della sostanziosa cucina umana di frontiera.",["race:Human"]="Come umana, Bernice incarna la tenacia della gente delle campagne di Roccavento, portando avanti la vita quotidiana e l'orgoglio familiare dopo la morte del marito nelle guerre del regno."},sec={{t="Una vita di privazioni",b="La guerra ha portato via il marito di Bernice durante le campagne militari del Regno di Roccavento. Ora vive con i suoi parenti nella tenuta di famiglia. Lì aiuta Ma Pietradura a gestire le faccende quotidiane della fattoria, sfama la famiglia e manda avanti la casa. I suoi Pasticci di Carne di Cinghiale l'hanno resa famosa in tutta la valle."},{t="La faida e la collana scomparsa",b="L'antico rancore tra gli Stonefield e i Maclure è profondamente radicato in Bernice. Quando la sua preziosa collana di famiglia è scomparsa, ha sospettato che il giovane Billy Maclure l'avesse presa. Eppure recuperare la collana si rivela più complicato che rimediare allo scherzo di un vicino. Billy giura di non averla rubata, ma quasi ammette di averla fatta cadere vicino alla Miniera Antrocupo. Lì ha visto Goldtooth, il coboldo dal dente d'oro, afferrarla e portarla nella sua tana."}},faq={{q="Chi è zia Bernice Stonefield?",a="La “Zia” Bernice Pietradura è un'anziana della famiglia Stonefield che vive alla Fattoria dei Pietradura, nella Foresta di Elwynn meridionale. Rimasta vedova a causa delle guerre del regno, si occupa della fattoria con Ma Pietradura ed è nota per i suoi Pasticci di Carne di Cinghiale.",al={"chi è zia bernice","storia di bernice stonefield","zia stonefield"}},{q="Che cosa è successo al marito di zia Bernice?",a="Il marito di Bernice è caduto durante una campagna militare combattuta per il Regno di Roccavento, lasciandola vedova.",al={"marito di zia bernice","con chi era sposata bernice","vedova stonefield"}},{q="Per che cosa è famosa zia Bernice?",a="Bernice è nota nelle campagne circostanti per i suoi Pasticci di Carne di Cinghiale, di cui persino i vicini dispettosi cercano di contrattare una fetta.",al={"pasticcio di bernice stonefield","pasticcio di carne di cinghiale elwynn"}},{q="Perché zia Bernice è arrabbiata con Billy Maclure?",a="Bernice sospetta che Billy Maclure abbia preso la sua amata collana di famiglia, inasprendo l'annosa faida tra gli Stonefield e i Maclure.",al={"faida billy maclure","ladro della collana di bernice","perché bernice odia billy"}},{q="Billy Maclure ha davvero rubato la collana?",a="Billy giura di non aver rubato la collana di Bernice, anche se quasi ammette di averla fatta cadere vicino alla Miniera Antrocupo. Dice che Goldtooth, il coboldo dal dente d'oro, l'ha raccolta e portata nella sua tana.",al={"billy ha rubato la collana","chi ha la collana degli stonefield","collana di goldtooth"}},{q="Dove si trova zia Bernice?",a="Bernice si trova all'esterno dell'edificio principale della Fattoria dei Pietradura, a sud della strada tra Borgodoro e le Marche Occidentali, accanto a Ma Pietradura.",al={"posizione di zia bernice","dove si trova bernice stonefield"}}},fx={["0a2ddc6d"]={q="Da che parte sta \"Zia\" Bernice Stonefield?",a="Zia Bernice è una leale suddita del Regno di Roccavento e un membro orgoglioso della famiglia Pietradura. Sta fermamente dalla parte dei suoi parenti nella loro annosa e aspra faida con i vicini Maclure, e ha poca pazienza per chiunque porti quel nome.",al={"fazione di zia bernice","chi sostiene bernice","alleanza di bernice pietradura"}},["0e5ea09d"]={q="Che cosa vuole \"Zia\" Bernice Stonefield?",a="Zia Bernice vuole soprattutto riavere la sua preziosa collana di famiglia, scomparsa e motivo per cui ha iniziato a sospettare del giovane Billy Maclure. Per risolvere il mistero e recuperare il cimelio, è disposta a preparare una delle sue famose torte con pancetta di maiale per indurlo a dire la verità.",al={"di cosa ha bisogno zia bernice","obiettivo di zia bernice","motivo della missione di bernice pietradura"}},f6bb7867={q="Perché \"Zia\" Bernice Stonefield si trova qui?",a="La Fattoria dei Pietradura è la casa di zia Bernice. Dopo aver perso il marito in una delle campagne militari di Roccavento, è rimasta nella tenuta di famiglia nella Foresta di Elwynn con Ma Pietradura e il resto del clan, occupandosi delle faccende domestiche e della vita alla fattoria.",al={"perché bernice è alla fattoria","motivo della posizione di bernice pietradura","che cosa porta zia bernice qui"}},["21972eac"]={q="A chi è legata \"Zia\" Bernice Stonefield?",a="È un'anziana matriarca del clan Pietradura e vive accanto a Ma Pietradura nella loro fattoria di Elwynn. La sua famiglia è coinvolta in un'aspra rivalità con i vicini Maclure, che condiziona quasi tutti i suoi rapporti con i loro parenti.",al={"famiglia di zia bernice","parenti di bernice pietradura","a chi è imparentata zia bernice"}}},fp="27,319,18.302.0,33.438.1,33.237.0,42.109.0,34.129.0,47.141.0,46.196.1,32.139.0"}
P.entries["npc:austil-de-mon"] = {n="Austil de Mon",s="A Brill, Austil de Mon insegna ai Reietti appena risorti a combattere per la Dama Oscura. Addestra i guerrieri alla Taverna dell'Impiccato.",h="A Brill, Austil de Mon insegna ai Reietti appena risorti a combattere per la Dama Oscura.",kw={"austil de mon","brill","guerriero dei reietti","taverna dell'impiccato","radure di tirisfal","istruttore dei guerrieri"},ang={["class:Warrior"]="Come guerriero dei Reietti in partenza da Albamorta, puoi rivolgerti ad Austil de Mon come mentore per ricevere consigli e un addestramento formale nelle abilità nelle Radure di Tirisfal.",["race:Undead"]="Come non morto appena risorto, puoi addestrarti con Austil de Mon per diventare un combattente di prima linea pronto a difendere Lordaeron dal Flagello e dalla Crociata Scarlatta."},sec={{t="Un veterano alla Taverna dell'Impiccato",b="A Brill, Austil de Mon addestra i guerrieri dei Reietti alla Taverna dell'Impiccato. Chi lascia Albamorta lo trova tra i suoi primi istruttori. Un tempo i vivi bevevano e riposavano nella locanda. Ora Austil insegna ai non morti da poco liberati la disciplina marziale e a combattere contro i nemici che circondano il regno."}},faq={{q="Chi è Austil de Mon?",a="Austil de Mon addestra i guerrieri dei Reietti a Brill, nelle Radure di Tirisfal.",al={"austil de mon","austil","chi è austil"}},{q="Dove posso trovare Austil de Mon?",a="Puoi trovare Austil de Mon nella Taverna dell'Impiccato a Brill, nelle Radure di Tirisfal, poco a nord di Sepulcra.",al={"posizione austil de mon","dove si trova austil","mappa austil de mon"}},{q="Qual è il suo ruolo a Brill?",a="Austil insegna ai guerrieri alle prime armi tecniche di combattimento, posture e abilità marziali. Il suo addestramento rafforza le forze militari dei Reietti contro le minacce locali.",al={"cosa fa austil","istruttore austil","ruolo di austil"}}},fx={["00da3c5d"]={q="Da che parte sta Austil de Mon?",a="Austil de Mon è leale ai Reietti e alla Signora Oscura, la regina Sylvanas Ventolesto. Fa parte del nascente regno di non morti sorto dalle rovine di Lordaeron e serve al fianco dei suoi fratelli nell'Orda, mettendo la sua esperienza marziale al servizio dei nuovi guerrieri Reietti che combattono per difendere le Radure di Tirisfal dal Flagello e dalla Crociata Scarlatta.",al={"fazione di austil de mon","lealtà di austil de mon","al servizio di austil"}},d899e308={q="Che cosa vuole Austil de Mon?",a="Austil de Mon vuole rafforzare le linee militari dei Reietti contro i numerosi nemici di Lordaeron. Addestrando i guerrieri appena risvegliati alla Taverna dell'Impiccato, si assicura che chi impugna le armi sotto la Signora Oscura abbia la disciplina e la tecnica necessarie per sopravvivere sia al Flagello implacabile sia ai fanatici della Crociata Scarlatta.",al={"obiettivo di austil de mon","che cosa vuole austil","scopo di austil de mon"}},aed6134f={q="Perché Austil de Mon si trova a Brill?",a="Austil è di stanza alla Taverna dell'Impiccato a Brill per accogliere e addestrare i combattenti che arrivano da Albamorta. Poiché Brill è il principale avamposto e centro logistico delle Radure di Tirisfal settentrionali, addestratori come Austil sono essenziali per trasformare i non morti appena risorti in combattenti capaci prima che si addentrino nei territori contesi.",al={"perché austil è a brill","perché austil de mon è qui","motivo della posizione di austil de mon"}}},fp="13,123,25.300.0,21.65.0,31.105.0,32.153.0"}
P.entries["npc:ayanna-everstride"] = {n="Ayanna Granpasso",s="Ad Aldrassil, Ayanna Granpasso guida i giovani kaldorei sulla via del cacciatore. Insegna il tiro, il tracciamento e la sopravvivenza sotto l'Albero del Mondo.",h="Ad Aldrassil, Ayanna Granpasso guida i giovani kaldorei sulla via del cacciatore.",kw={"aldrassil","ayanna","granpasso","istruttore dei cacciatori","elfo della notte","vallombra","teldrassil"},ang={["class:Hunter"]="Come cacciatore che muove i primi passi a Vallombra, puoi rivolgerti ad Ayanna Granpasso per le prime lezioni sull'uso delle armi, sul tracciamento e sulla sopravvivenza nella natura selvaggia.",["race:NightElf"]="Come elfo della notte, trovi Ayanna nelle sacre cavità di Aldrassil. Prepara le reclute inesperte a difendere la foresta circostante dalla corruzione che avanza e a contribuire alla protezione del giovane Albero del Mondo."},sec={{t="Una mentore a Vallombra",b="A Vallombra, Ayanna Granpasso addestra i cacciatori kaldorei appena risvegliati all'interno di Aldrassil. Per gli elfi della notte, i cacciatori custodiscono le foreste sacre. Il loro compito va oltre il piazzare trappole o il tirare da lontano. Ayanna insegna ai giovani cacciatori le prime tecniche marziali, il combattimento a distanza e come sopravvivere nei pericolosi boschi di Teldrassil."}},faq={{q="Chi è Ayanna Granpasso?",a="Ayanna Granpasso addestra i cacciatori elfi della notte alle prime armi ad Aldrassil, a Vallombra, su Teldrassil. Insegna le basi del combattimento e della sopravvivenza nella natura selvaggia.",al={"ayanna granpasso","chi è ayanna","istruttore dei cacciatori di aldrassil"}},{q="Dove posso trovare Ayanna Granpasso?",a="Puoi trovare Ayanna Granpasso all'interno di Aldrassil, l'insediamento ricavato in un enorme albero cavo a Vallombra, nel cuore di Teldrassil.",al={"posizione di ayanna","dove si trova ayanna","trovare ayanna granpasso"}},{q="Quali missioni coinvolgono Ayanna Granpasso?",a="L'addestramento iniziale porta i nuovi cacciatori elfi della notte da Ayanna. I loro primi istruttori possono consegnare loro un Sigillo Intagliato, e Ayanna insegna poi le basi agli aspiranti guardaboschi.",al={"missioni di ayanna","missione sigillo intagliato","personaggio che assegna missioni ayanna"}}},fx={["881ffa5e"]={q="Da che parte sta Ayanna Granpasso?",a="Ayanna è fermamente al fianco degli Elfi della Notte di Darnassus e dell'Alleanza. Di stanza a Vallombra, all'interno di Aldrassil, guida i nuovi Elfi della Notte a entrare in comunione con la natura, restando fedele alla sua gente e alla difesa di Teldrassil.",al={"fazione di ayanna granpasso","al servizio di ayanna granpasso","alleanza di ayanna granpasso"}},e6b7d676={q="Che cosa vuole Ayanna Granpasso?",a="Ayanna si dedica a guidare i cacciatori alle prime armi. Vuole assicurarsi che i giovani Elfi della Notte imparino a seguire le tracce, a tirare con precisione e a sopravvivere in armonia con la natura prima di avventurarsi nel mondo.",al={"obiettivo di ayanna granpasso","che cosa vuole ayanna","scopo di ayanna granpasso"}},bbb0d24a={q="Perché Ayanna Granpasso si trova qui a Vallombra?",a="Ayanna vive ad Aldrassil e fa da addestratrice per cacciatori. Mentre i giovani Elfi della Notte si risvegliano nel riparato boschetto di Vallombra, lei prepara chi sceglie la via del cacciatore, insegnandogli le abilità essenziali e fornendogli armi e istruzioni.",al={"perché ayanna è ad aldrassil","perché ayanna granpasso è qui","ruolo di ayanna granpasso a vallombra"}}},fp="17,149,22.318.0,25.147.0,35.128.0,38.174.0"}
P.entries["npc:ayessa-dawnsinger"] = {n="Ayessa Dawnsinger",s="A Valanaar, su Zephras Isle, Ayessa Dawnsinger guida gli Skyborne alleati dell'Orda. Guida i Windshapers tra le loro prove e le vicende politiche.",h="A Valanaar, su Zephras Isle, Ayessa Dawnsinger guida gli Skyborne alleati dell'Orda.",kw={"ayessa","dawnsinger","orda","skyborne","valanaar","windshapers","zephras"},ang={["faction:Horde"]="Per l'Orda, Ayessa Dawnsinger è un'importante alleata tra gli Skyborne e un punto di contatto su Zephras Isle.",["race:Skyborne"]="Come Skyborne, puoi vedere in Ayessa Dawnsinger il cammino di chi si schiera con l'Orda per assicurarsi un futuro."},sec={{t="Guida dei The Windshapers",b="Da Valanaar, su Zephras Isle, Ayessa Dawnsinger guida i Windshapers, gli Skyborne alleati dell'Orda. Dirige i loro sforzi in tutta l'isola mentre affrontano minacce esterne e divisioni interne. Li guida tra le alleanze a Kalimdor e oltre, con in gioco la loro sopravvivenza."},{t="La lotta per Zephras",b="Ayessa Dawnsinger invia campioni fidati a risolvere i conflitti su Zephras Isle. Affrontano costrutti ribelli e figure ostili come Lorthuna mentre gli Skyborne affrontano il proprio destino. Tra lotte politiche e scontri fisici, Ayessa guida i Windshapers e mantiene il rispetto per la loro voce e la loro forza all'interno dell'Orda."}},faq={{q="Chi è Ayessa Dawnsinger?",a="Ayessa Dawnsinger guida i Windshapers, gli Skyborne alleati dell'Orda su Zephras Isle.",al={"storia di ayessa","chi è ayessa","origini di ayessa dawnsinger"}},{q="Dove si trova Ayessa Dawnsinger?",a="Ayessa Dawnsinger si trova a Valanaar, su Zephras Isle.",al={"dove si trova ayessa","posizione di ayessa","mappa di ayessa dawnsinger"}},{q="Cosa sono i The Windshapers?",a="I Windshapers sono la fazione degli Skyborne alleata dell'Orda. Ayessa Dawnsinger li guida da Valanaar.",al={"fazione dei the windshapers","chi sono i the windshapers"}},{q="Qual è il ruolo di Ayessa nelle missioni locali?",a="Ayessa Dawnsinger affida incarichi legati alla difesa dell'isola, tra cui indagare sui costrutti ribelli, affrontare Lorthuna e plasmare il futuro di Zephras.",al={"missioni di ayessa","serie di missioni di ayessa"}}},fx={["53a49c44"]={q="Da che parte sta Ayessa Dawnsinger?",a="Ayessa Dawnsinger è fermamente schierata con l'Orda. In quanto guida dei Windshapers, dirige la fazione degli Skyborne alleata dell'Orda, stanziata a Valanaar, sull'isola di Zephras, e mobilita i campioni dell'Orda per la sua causa.",al={"fazione di ayessa dawnsinger","ayessa è dell'orda o dell'alleanza","lealtà di ayessa"}},e31c8ea2={q="A chi è legata Ayessa Dawnsinger?",a="Ayessa Dawnsinger è direttamente legata ai Windshapers, la fazione degli Skyborne dell'Orda che guida. Di stanza a Valanaar, coordina le loro operazioni e organizza la resistenza contro i nemici locali in tutta l'isola di Zephras.",al={"legami di fazione di ayessa dawnsinger","legami di ayessa","con chi collabora ayessa"}}},fp="17,142,25.301.0,24.318.1,25.84.0,37.59.0,25.109.0,38.155.0"}
P.entries["npc:azar-stronghammer"] = {n="Azar Martelduro",s="Alla Distilleria Birratuono di Kharanos, Azar Martelduro guida i nuovi paladini nani nella Sacra Luce. Dopo il loro addestramento, invia le reclute promettenti a Forgiardente perché proseguano la loro istruzione.",h="Alla Distilleria Birratuono di Kharanos, Azar Martelduro guida i nuovi paladini nani nella Sacra Luce.",kw={"azar","distilleria","dun morogh","kharanos","paladino","martelduro","thunderbrew","tome of divinity","istruttore"},ang={["class:Paladin"]="Se inizi il tuo cammino come paladino nano a Dun Morogh, puoi imparare da Azar prima che ti indirizzi a Forgiardente per ottenere il sacro Tome of Divinity.",["race:Dwarf"]="Azar mostra come i nani di Khaz Modan abbracciano la Sacra Luce. Per te, la devozione alla sacra giustizia si accompagna al calore del focolare e a un boccale di Thunderbrew."},sec={{t="Una guida nel freddo",b="Azar Martelduro guida i paladini nani appena iniziati sui gelidi pendii di Dun Morogh. Gli umani sono spesso associati alle grandi cattedrali, eppure i nani di Khaz Modan hanno abbracciato la Sacra Luce. Avendo padroneggiato i propri voti marziali e spirituali, Azar aiuta i novizi a trovare la propria strada. Quando una recluta dimostra dedizione e maturità spirituale, la manda lungo il sentiero montano verso Forgiardente, dove campioni veterani come Tiza Battiforgia possono istruirla ulteriormente."}},faq={{q="Chi è Azar Martelduro?",a="Azar Martelduro addestra i paladini nani alla Distilleria Birratuono di Kharanos. Li guida nelle prime fasi dell'addestramento, poi invia le reclute promettenti a Forgiardente per proseguire gli studi.",al={"chi è azar","ruolo di azar martelduro","istruttore dei paladini di kharanos"}},{q="Dove si può trovare Azar Martelduro?",a="Puoi trovare Azar Martelduro all'interno della Distilleria Birratuono a Kharanos, tra le colline innevate di Dun Morogh.",al={"posizione di azar martelduro","dove si trova azar","trova azar martelduro"}},{q="Quale addestramento fornisce ai giovani paladini?",a="Azar insegna ai novizi le arti marziali e gli incantesimi di base dei paladini. Quando un apprendista è pronto per le prove del Tome of Divinity e i suoi sacri riti di resurrezione, lo indirizza da Tiza Battiforgia a Forgiardente.",al={"cosa fa azar","missione di azar","missioni del paladino azar"}},{q="Perché un istruttore dei paladini si trova in una distilleria?",a="La Distilleria Birratuono riunisce i difensori e i mentori di Kharanos. La vita dei nani unisce doveri civici e convivialità a bevande robuste, e la distilleria è il cuore della vita sociale e della difesa del villaggio.",al={"perché un paladino è nella distilleria","paladino nel bar","istruttore della distilleria"}}},fx={["38fe723c"]={q="Da che parte sta Azar Martelduro?",a="Azar Martelduro è fermamente al fianco del Regno di Forgiardente e dell'Alleanza. Paladino nano esperto, è leale al suo popolo, a Re Magni Barbabronzea e ai sacri precetti della Luce.",al={"fazione di azar martelduro","lealtà di azar martelduro","per chi combatte azar"}},["56baf4f4"]={q="Che cosa vuole Azar Martelduro?",a="Dopo aver completato un lungo addestramento nella Luce, Azar vuole guidare la prossima generazione di paladini nani. Sorveglia gli apprendisti promettenti a Dun Morogh e si assicura che siano pronti prima di mandarli da addestratori esperti come Tiza Battiforgia a Forgiardente.",al={"obiettivi di azar martelduro","che cosa cerca di fare azar","scopo di azar martelduro"}},["132f6bb2"]={q="A chi è legato Azar Martelduro?",a="Azar mantiene stretti legami con gli altri paladini nani e collabora in particolare con Tiza Battiforgia nella Hall of Mysteries di Forgiardente per favorire la formazione degli iniziati più promettenti.",al={"legami di azar martelduro","alleati di azar martelduro","chi conosce azar"}}},fp="17,194,19.463.0,25.197.0,37.114.0,48.214.0,51.220.0"}
P.entries["npc:azuregos"] = {n="Azuregos",s="Lungo la costa di Azshara, Azuregos veglia sulle reliquie degli Eletti. Malygos gli ha affidato il loro grande potere magico, anche se preferirebbe studiare in pace e scacciare chiunque disturbi la sua veglia.",h="Lungo la costa di Azshara, Azuregos veglia sulle reliquie degli Eletti.",kw={"azshara","azuregos","baia delle tempeste","drago blu","eldarath","malygos","frammento di scettro","sabbie mutevoli"},ang={["class:Mage"]="Come Mago, puoi vedere in Azuregos un agente dello stormo blu, dedito a padroneggiare e regolamentare la magia arcana. Considera gli incantatori mortali bambini sconsiderati che giocano con forze al di là della loro comprensione.",["race:NightElf"]="Come Elfo della Notte, puoi trovare Azuregos tra le rovine devastate di Eldarath, intento a vegliare sulle stregonerie degli Eletti che quasi lacerarono Kalimdor durante il Grangorgo."},sec={{t="Il Custode di Eldarath",b="Azuregos vaga tra le spiagge e le rupi attorno a Eldarath, le antiche rovine di cui ha fatto il proprio santuario. Reliquie risalenti a prima del Grande Grangorgo giacciono ancora lungo queste coste devastate. Come servitore di Malygos, tiene i loro potenti artefatti lontani dai mortali incauti.\n\nAzuregos non si nasconde in una caverna buia. Pattuglia apertamente la regione e si proclama signore di ogni magia che vi si trova. Il suo umorismo è spesso sardonico, ma difende ferocemente i tesori di Azshara dagli avventurieri in cerca di fama o bottino."},{t="Un custode riluttante",b="Dopo la Guerra delle Sabbie Mutevoli, Azuregos ricevette il Frammento di Scettro Blu, parte della chiave necessaria a infrangere la barriera del Vallo dello Scarabeo. Cercatori di tesori e aspiranti eroi vennero a cercarlo, procurandogli continui grattacapi.\n\nAlla fine, l'astuto drago si liberò del frammento senza tanti complimenti. Lo diede in pasto a Maws, un pesciolino potenziato. Chiunque cerchi il frammento deve ora dragare i fondali invece di infastidire Azuregos."}},faq={{q="Chi è Azuregos?",a="Azuregos pattuglia le rovine di Azshara per ordine di Malygos. Eccentrico e arguto, il drago blu annienta i mortali che interrompono i suoi studi magici o bramano i tesori di Eldarath.",al={"storia di azuregos","chi è il drago blu ad azshara","storia passata di azuregos"}},{q="Perché Azuregos si trova ad Azshara?",a="Azuregos studia e custodisce i potenti artefatti arcani che gli antichi Eletti lasciarono dopo il Grande Grangorgo. Protegge le rovine di Eldarath dai saccheggiatori sconsiderati in cerca di magia pericolosa.",al={"perché azuregos si trova qui","cosa fa azuregos ad azshara","scopo di azuregos"}},{q="Qual è il suo legame con il Vallo dello Scarabeo?",a="Azuregos ricevette il Frammento di Scettro Blu, parte della chiave che può riaprire il Vallo dello Scarabeo. Per sapere che fine abbia fatto il frammento, parla con il drago.",al={"frammento dello scettro di azuregos","azuregos sabbie mutevoli","frammento delle sabbie mutevoli"}},{q="Perché il suo spirito appare ad Azshara?",a="Spirit of Azuregos appare ad Azshara vicino al drago vivente e parla con i viaggiatori. Nessuno spiega come lo spirito e il drago possano esistere l'uno accanto all'altro.",al={"spirito di azuregos","fantasma di azuregos","perché azuregos è un fantasma"}}},fp="8,193,24.484.0,21.428.1,16.178.0,27.199.0,42.148.1,38.153.0"}
P.entries["npc:bailiff-conacher"] = {n="Bailiff Conacher",s="Nel Lakeshire Town Hall, Bailiff Conacher fa rispettare la legge di Roccavento agli ordini del Magistrato Solomon. Con Redridge sotto assedio, si affida ai viaggiatori per dare esecuzione ai decreti locali.",h="Nel Lakeshire Town Hall, Bailiff Conacher fa rispettare la legge di Roccavento agli ordini del Magistrato...",kw={"ufficiale giudiziario","conacher","borgolago","morganth","crestarossa","shadowhide","solomon","municipio"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi vedere fin dove arriva la legge di Roccavento in una cittadina di confine lasciata in gran parte a cavarsela da sola."},sec={{t="Giustizia a Borgolago",b="Bailiff Conacher lavora con il Magistrato Solomon nel Lakeshire Town Hall per far rispettare la legge nelle Montagne Crestarossa. Gli orchi Roccianera e gli gnoll locali assediano la cittadina, lasciando Conacher senza normali procedure civiche né guarnigioni reali. Così emana decreti che autorizzano i viaggiatori di passaggio a eseguire condanne a morte in nome del regno."},{t="Applicare la Solomon's Law",b="Quando il mago oscuro Morganth si impadronì della Torre di Ilgalar, piegò al proprio volere gli gnoll Shadowhide della zona. La Corte di Borgolago giudicò le bestie colpevoli di alto tradimento. La legge di Roccavento condanna a morte chi aiuta un fuggiasco e criminale. In virtù della Solomon's Law, Conacher manda i viaggiatori tra i crinali a cercare gli gnoll Shadowhide e riportarne i ciondoli come prova che la legge della corona è stata applicata."}},faq={{q="Chi è Bailiff Conacher?",a="Bailiff Conacher serve la Corte di Borgolago e aiuta il Magistrato Solomon a far rispettare l'autorità civile e la legge di Roccavento nelle Montagne Crestarossa.",al={"ruolo di bailiff conacher","chi è conacher","storia di conacher"}},{q="Dove si trova Bailiff Conacher?",a="Puoi trovare Bailiff Conacher all'interno del Lakeshire Town Hall, sul lato nord del ponte nelle Montagne Crestarossa.",al={"posizione di bailiff conacher","dove si trova conacher","conacher crestarossa"}},{q="Che cos'è la Solomon's Law?",a="La Solomon's Law applica la legge di Roccavento per decreto del Magistrato Solomon. Aiutare criminali noti come lo stregone rinnegato Morganth comporta la pena di morte, rendendo gli gnoll Shadowhide suoi alleati passibili di esecuzione.",al={"cos'è la solomon's law","solomon's law gnoll","legge shadowhide"}},{q="Perché Conacher chiede i ciondoli Shadowhide?",a="I ciondoli dimostrano che uno gnoll Shadowhide è stato ucciso in esecuzione della condanna emessa da Borgolago contro chi aiuta Morganth.",al={"perché raccogliere pendenti","scopo dei pendenti shadowhide"}}},fx={["8124ae86"]={q="Perché Bailiff Conacher si trova qui a Lakeshire?",a="Conacher è di stanza al Lakeshire Town Hall in qualità di balivo della città. Collaborando con il Magistrato Solomon, contribuisce ad amministrare la giustizia locale e a organizzare la difesa civile in un periodo in cui Roccavento non può inviare rinforzi nella regione.",al={"perché conacher è a redridge","conacher municipio di lakeshire"}},df8ac9aa={q="A chi è legato Bailiff Conacher?",a="Conacher lavora direttamente alle dipendenze del Magistrato Solomon, nell'ambito della Corte di Lakeshire. Collabora a stretto contatto con i funzionari della città e le guardie locali per mantenere l'ordine nell'insediamento e respingere gli invasori esterni.",al={"alleati di conacher","con chi lavora conacher"}},["6ce891cc"]={q="Da che parte sta Bailiff Conacher?",a="Bailiff Conacher serve l'Alleanza e risponde direttamente al Magistrato Solomon nella città di Borgolago. In qualità di funzionario del tribunale di Crestagrana, il suo dovere è far rispettare le leggi di Roccavento e proteggere gli abitanti dalle minacce incombenti.",al={"lealtà di conacher","al servizio di conacher","conacher è dell'alleanza"}},["5d999432"]={q="Che cosa vuole Bailiff Conacher?",a="Conacher vuole far rispettare le leggi di Borgolago e proteggere Crestagrana. Poiché il mago rinnegato Morganth ha arruolato i gnoll Manto d'Ombra locali, il balivo recluta avventurieri capaci per punire i gnoll e arginare l'influenza del mago oscuro.",al={"obiettivo di conacher","di cosa ha bisogno bailiff conacher"}}},fp="16,166,20.336.0,22.404.0,24.143.0,36.116.0,22.210.0,46.121.0"}
P.entries["npc:bailor-stonehand"] = {n="Bailor Mandipietra",s="A Thelsamar, Bailor Mandipietra attende carichi di minerale rubati dagli ogre Mo'grosh. L'abile fabbro nanico crea una lega speciale per armamenti di fattura magistrale e un tempo insegnò al fabbro d'armi umano Jordan Stilwell.",h="A Thelsamar, Bailor Mandipietra attende carichi di minerale rubati dagli ogre Mo'grosh.",kw={"bailor mandipietra","jordan stilwell","loch modan","mo'grosh","fabbro","thelsamar","pugno di verigan"},ang={["class:Paladin"]="Come paladino, segui un'arte che Bailor insegnò a Jordan Stilwell. La formula della sua lega speciale viene usata per creare il sacro martello Pugno di Verigan.",["profession:Blacksmithing"]="Come fabbro, puoi osservare la ricerca di Bailor di metalli rari e resistenti. Le sue leghe speciali sono note in tutta Khaz Modan."},sec={{t="Maestro della Forgia",b="Bailor Mandipietra si occupa della forgia di Thelsamar. La sua conoscenza dei minerali e delle leghe speciali si estende oltre Khaz Modan. Insegnò a Jordan Stilwell le basi della metallurgia e condivise formule per armamenti benedetti da paladino come il Pugno di Verigan."},{t="Imboscata degli Ogre",b="Gli ogre Mo'grosh delle colline a nord-est di Thelsamar hanno rubato carichi di minerale destinati alla forgia di Bailor. Senza la materia prima, non può produrre le sue leghe rare. Ha bisogno di viaggiatori e alleati che recuperino le scorte dagli accampamenti degli ogre."}},faq={{q="Chi è Bailor Mandipietra?",a="Bailor Mandipietra è un veterano fabbro nanico di Thelsamar, a Loch Modan. Fonde leghe di metalli rari e insegnò a Jordan Stilwell l'arte di forgiare armi.",al={"bailor mandipietra","chi è bailor","fabbro di thelsamar"}},{q="Qual è il legame di Bailor con Jordan Stilwell?",a="Bailor insegnò a Jordan Stilwell, un fabbro umano nei pressi di Forgiardente, a lavorare il minerale raffinato. Gli insegnò anche a produrre una lega speciale usata per creare il sacro martello da guerra Pugno di Verigan.",al={"bailor e jordan","maestro di jordan stilwell","fabbro del pugno di verigan"}},{q="Cosa è successo al minerale di Bailor?",a="Gli ogre Mo'grosh delle alture nordorientali di Loch Modan hanno intercettato e rubato il carico di minerale grezzo di Bailor. Non ha materiali per le sue lavorazioni specializzate dei metalli.",al={"carico di minerale di bailor","chi ha rubato il minerale di bailor","carico degli ogre"}},{q="Dove si trova Bailor Mandipietra?",a="Bailor si trova vicino al centro di Thelsamar, la principale cittadina nanica lungo la strada principale di Loch Modan.",al={"posizione di bailor","dove si trova bailor mandipietra","bailor thelsamar"}}},fx={["0eb0f83a"]={q="Da che parte sta Bailor Mandipietra?",a="Bailor Mandipietra è saldamente schierato con Forgiardente e l'Alleanza. Vive tra i suoi simili a Thelsamar e mette la sua arte al servizio della comunità nanica locale; aiuta anche gli avventurieri dell'Alleanza di passaggio, in particolare i paladini in cerca della sua competenza metallurgica, a difendere il regno dalle minacce ostili.",al={"fazione di bailor mandipietra","bailor è dell'alleanza","da che parte sta bailor"}},a41b979c={q="Cosa vuole Bailor Mandipietra?",a="Bailor vuole dedicarsi indisturbato al suo mestiere di fabbro, ma la sua preoccupazione principale è recuperare le preziose materie prime. Dopo che gli ogri Mo'grosh hanno razziato e rubato il suo ultimo carico di minerale, cerca viaggiatori capaci che siano disposti a inoltrarsi nel territorio degli ogri per recuperare i rifornimenti perduti.",al={"cosa vuole bailor","obiettivo di bailor mandipietra","motivazioni di bailor"}},["346dae44"]={q="Perché Bailor Mandipietra si trova a Thelsamar?",a="Bailor vive a Thelsamar per gestire la sua fucina e rifornire l'insediamento con pregiati manufatti in metallo nanici. Vicina alle miniere e al terreno impervio di Loch Modan, la città è un avamposto ideale per un fabbro esperto, anche se le occasionali incursioni degli ogri locali complicano le sue forniture.",al={"perché bailor è qui","perché bailor è a loch modan","perché bailor è a thelsamar"}}},fp="16,212,19.252.0,11.237.0,24.153.0,47.164.0,30.150.0,36.101.0"}
P.entries["npc:baine-bloodhoof"] = {n="Baine Zoccolo Sanguinario",s="Al Villaggio di Zoccolo Sanguinario, Baine Zoccolo Sanguinario protegge il suo popolo e Mulgore. Cairne governa da Picco del Tuono, mentre Baine dirige la difesa del villaggio contro gli gnoll e le minacce esterne.",h="Al Villaggio di Zoccolo Sanguinario, Baine Zoccolo Sanguinario protegge il suo popolo e Mulgore.",kw={"baine","zoccolo sanguinario","villaggio di zoccolo sanguinario","cairne","centauro","khiragg","mulgore","palemane","rexxar","picco del tuono"},ang={["class:Shaman"]="Baine mette gli spiriti al primo posto. Invia i viaggiatori a fermare le macchine dei nani e i minatori sconsiderati prima che i loro scavi feriscano ulteriormente gli spiriti della terra.",["faction:Horde"]="Baine porta una saggezza pacata e una forza guerriera discreta nell'Orda di Thrall, guidando chi attraversa il centro di Mulgore.",["race:Tauren"]="Baine porta avanti l'onorevole stirpe dell'High Chieftain Cairne e la speranza delle giovani tribù riunite nelle pianure di Mulgore."},sec={{t="Figlio dell'High Chieftain",b="Baine Zoccolo Sanguinario è cresciuto viaggiando con il suo popolo nomade come figlio di Cairne. Si stabilirono nelle praterie di Mulgore, dove i clan dei centauri restavano una minaccia. Dopo la Terza Guerra, la banda da guerra di Khiragg catturò Baine, e il dolore quasi impedì a Cairne di guidare i nuovi insediamenti. Rexxar liberò Baine, risollevando lo spirito di Cairne. Poi i tauren si schierarono con l'Orda di Thrall contro gli invasori di Kul Tiras e consolidarono la loro presenza sul continente."},{t="Guardiano del Villaggio di Zoccolo Sanguinario",b="Baine vive tra la sua gente al Villaggio di Zoccolo Sanguinario, lontano dagli altopiani della capitale. Mentre Cairne invecchia, Baine assume maggiori responsabilità verso il suo popolo e rappresenta la nuova generazione di guide dei tauren. Dirige i guerrieri e gli alleati in visita contro gli gnoll Palemane che minacciano i confini. Sorveglia anche le influenze esterne che minacciano l'equilibrio naturale di Mulgore."},{t="Difendere l'Earth Mother",b="Baine affronta invasori che si curano ben poco dell'equilibrio spirituale. A Mulgore orientale, i goblin della S.P.R. & Co. scavano nel paesaggio sacro. I cercatori nani di Bael Modan scavano nel suolo ancestrale presso gli Scavi di Bael'dun. Baine esorta a una risposta ferma ma misurata: avvertire i minatori e distruggere le loro attrezzature invece di precipitarsi in inutili spargimenti di sangue. Dice che i loro scavi violenti feriscono gli spiriti della terra, ma i minatori si rifiutano di ascoltare."}},faq={{q="Chi è Baine Zoccolo Sanguinario?",a="Baine Zoccolo Sanguinario è l'unico figlio di Cairne Zoccolo Sanguinario. Sovrintende alla difesa e agli affari tribali nel Villaggio di Zoccolo Sanguinario, dirigendo i guerrieri locali e proteggendo Mulgore mentre Cairne governa da Picco del Tuono.",al={"storia di baine","chi è baine","figlio di cairne"}},{q="Dove si trova Baine in questo momento?",a="Baine si trova nel Villaggio di Zoccolo Sanguinario, nel centro di Mulgore, poco a sud di Picco del Tuono. Vicino al centro del villaggio, organizza gli incarichi per gli avventurieri appena arrivati.",al={"posizione di baine","dove si trova baine","luogo di baine zoccolo sanguinario"}},{q="Come è stato salvato Baine dai centauri?",a="Dopo la Terza Guerra, Khiragg catturò Baine, lasciando Cairne in preda a una disperazione debilitante. Rexxar cercò l'aiuto degli esuli di Bovan Windtotem e seguì le tracce dei centauri fino al loro accampamento. Uccise i carcerieri di Baine e lo riportò sano e salvo da suo padre.",al={"baine rapito","rexxar salva baine","baine catturato"}},{q="Quali problemi gestisce Baine nel Villaggio di Zoccolo Sanguinario?",a="Baine coordina gli sforzi contro gli gnoll Palemane che tormentano le mandrie locali. Sorveglia anche gli intrusi stranieri, tra cui i goblin della S.P.R. & Co. e gli scavatori nani dell'Alleanza che sconvolgono la terra.",al={"missioni di baine","cosa fa baine","problemi del villaggio di zoccolo sanguinario"}},{q="Qual è la posizione di Baine riguardo agli scavi dei nani di Bael'dun?",a="Baine crede che gli scavi violenti dei minatori di Bael'dun feriscano gli spiriti della terra e profanino il suolo. Invia i viaggiatori a impadronirsi dei loro attrezzi e distruggerli, sperando di spaventare i minatori e allontanarli, mostrando loro che sventrare la terra non conduce alla conoscenza.",al={"baine nani","estrazione mineraria bael dun","scavi dei nani mulgore"}},{q="Baine succederà a Cairne come Gran Capo?",a="Come figlio di Cairne, Baine assume un ruolo maggiore nella guida dei tauren mentre suo padre invecchia. Molti lo considerano l'erede naturale delle tribù unite.",al={"baine diventa capo","futuro gran capo","erede di cairne"}}},fx={["59aa4b20"]={q="Da che parte sta Baine Zoccolo Sanguinario?",a="Baine è interamente devoto al popolo tauren e all'Orda. Figlio dell'Alto Capo Cairne Zoccolo Sanguinario, è leale alla sua tribù di Mulgore e alla più ampia alleanza stretta con gli orchi di Thrall e i troll Lanciascura.",al={"fazione di baine zoccolo sanguinario","baine è dell'orda","lealtà di baine"}},["9cbf1856"]={q="Cosa vuole Baine Zoccolo Sanguinario?",a="Baine vuole difendere Mulgore e proteggere la pacifica terra natale che suo padre ha conquistato per il loro popolo. Al momento intende respingere gli aggressivi gnoll Crinenera, indagare sulle attività della S.P.R. & Co. a est e scacciare i minatori nanici che deturpano la terra sacra agli Scavi di Bael'dun.",al={"obiettivi di baine zoccolo sanguinario","obiettivo di baine","cosa vuole baine"}},["1590aad3"]={q="A chi è legato Baine Zoccolo Sanguinario?",a="Baine è il figlio dell'Alto Capo Cairne Zoccolo Sanguinario. Oltre ai legami familiari, è legato da una duratura gratitudine a Rexxar, campione dell'Orda che lo salvò dalla prigionia quando i predoni centauri minacciarono la sua vita.",al={"famiglia di baine","a chi è imparentato baine","legami di baine"}}},fp="15,181,25.445.0,29.369.0,26.453.0,23.195.0,35.149.0,39.247.0,53.198.0,55.252.0,44.149.0"}
P.entries["npc:balir-frosthammer"] = {n="Balir Gelmartello",s="Nella Valle Crestafredda, Balir Gelmartello raduna le reclute mentre i trogg Rockjaw avanzano nelle terre dei nani.",h="Nella Valle Crestafredda, Balir Gelmartello raduna le reclute mentre i trogg Rockjaw avanzano nelle terre dei...",kw={"a new threat","balir gelmartello","valle crestafredda","dun morogh","trogg rockjaw","tannok gelmartello"},ang={["faction:Alliance"]="Come recluta dell'Alleanza, ti addestri a Khaz Modan, mentre Balir si adopera per mantenere la Valle Crestafredda sicura come base operativa.",["race:Dwarf"]="Come nano, puoi aiutare Balir Gelmartello a difendere la tua patria dalle minacce che emergono dal sottosuolo. Il suo appello ti offre una delle prime occasioni per proteggere Dun Morogh."},sec={{t="Difendere la Valle Crestafredda",b="Balir Gelmartello chiama le nuove reclute a difendere la Valle Crestafredda. I novizi nani e gnomi vi trovano da tempo sicurezza e addestramento. Ma i disordini nel sottosuolo hanno spinto in superficie i violenti trogg Rockjaw. Balir è tra i primi a dare l'allarme, esortando le reclute a sfoltirne le fila prima che si addentrino ulteriormente a Dun Morogh."},{t="Parente dei Gelmartello",b="Balir Gelmartello condivide il cognome con Tannok Gelmartello di Kharanos. I due potrebbero appartenere alla stessa famiglia, i cui membri sono al fianco di Forgiardente. Contribuiscono a mantenere sicuri i freddi valichi montani per viaggiatori, minatori e montanari, mentre le minacce aumentano in tutta la regione."}},faq={{q="Chi è Balir Gelmartello?",a="Balir Gelmartello sorveglia la Valle Crestafredda a Dun Morogh. Chiede alle reclute appena arrivate di sfoltire le fila dei trogg Rockjaw ostili che minacciano le difese della valle.",al={"chi e balir gelmartello","chi e balir"}},{q="Perché Balir è preoccupato per i trogg?",a="Di recente, i trogg Rockjaw sono emersi in forze, seminando scompiglio nella Valle Crestafredda e attaccando gli insediamenti dei nani. Balir vede un pericolo crescente che va arginato sul nascere.",al={"perche i trogg","problema trogg crestafredda"}},{q="Balir è imparentato con Tannok Gelmartello?",a="È possibile. Balir condivide il cognome Gelmartello con Tannok Gelmartello di Kharanos, il che suggerisce un legame di parentela, anche se non è confermato.",al={"parente di tannok","famiglia gelmartello"}}},fx={c02dfef8={q="Da che parte sta Balir Gelmartello?",a="Balir è saldamente schierato con Forgiardente e l'Alleanza. Di stanza nella Valle Crestafredda, veglia sulla sicurezza della patria nanica e collabora con altri montanari e reclute per proteggere Dun Morogh dalle nuove minacce.",al={"fazione di balir gelmartello","chi serve balir","balir è dell'alleanza"}},["14c400d2"]={q="Cosa vuole Balir Gelmartello?",a="Balir vuole respingere i trogg Mascelladura che hanno iniziato a infestare la valle. Molto preoccupato per la loro improvvisa comparsa e aggressività, arruola avventurieri capaci per eliminare gli invasori prima che travolgano Crestafredda.",al={"motivazioni di balir gelmartello","di cosa ha bisogno balir","perché balir ha bisogno di aiuto"}}},fp="17,99,24.334.0,23.263.0,25.156.0,40.168.0,39.142.0"}
P.entries["npc:balthule-shadowstrike"] = {n="Balthule Ombrafuria",s="Vicino alla Torre di Althalaxx, Balthule Ombrafuria sorveglia la parte settentrionale di Rivafosca. Fa da esploratore per Delgren the Purifier, osservando chi pratica le arti oscure nelle antiche rovine elfiche.",h="Vicino alla Torre di Althalaxx, Balthule Ombrafuria sorveglia la parte settentrionale di Rivafosca.",kw={"althalaxx","balthule","cultisti","rivafosca","delgren","mathystra","purificatore","esploratore","ombrafuria"},ang={["class:Rogue"]="Come ladro, conosci la pazienza e la vigilanza necessarie per operare nel cuore del territorio nemico, sotto il naso di pericolosi incantatori. Balthule dimostra queste qualità nel suo ruolo di esploratore elfico.",["faction:Alliance"]="Come membro dell'Alleanza inviato a nord da Auberdine, puoi trovare in Balthule un contatto sul campo contro i cultisti oscuri attorno alla Torre di Althalaxx.",["race:NightElf"]="Come elfo della notte, potresti considerare un oltraggio la profanazione delle antiche rovine di Kalimdor da parte dei cultisti. Balthule cerca di vendicare questo affronto prima che la corruzione si diffonda ulteriormente nelle tue terre."},sec={{t="Un esploratore nell'ombra",b="A ovest della Torre di Althalaxx, Balthule Ombrafuria veglia da solo. Spiriti irrequieti infestano la parte settentrionale di Rivafosca, e rovine avvolte nell'ombra costellano la costa. Eppure la torre rappresenta un pericolo particolare. Sotto la guida di Delgren the Purifier, Balthule sorveglia gli incantatori oscuri che sono entrati nelle antiche rovine degli Eletti."},{t="Smascherare la setta",b="Gli stregoni e i cultisti della Torre di Althalaxx praticano magie proibite. Raccolgono manufatti e anime dalle rovine vicine. Balthule chiede ai campioni dell'Alleanza di passaggio di colpire i loro capi. Cerca anche pergamene e talismani che rivelino la portata dei loro tentativi di evocazione."}},faq={{q="Chi è Balthule Ombrafuria?",a="Balthule Ombrafuria esplora la parte settentrionale di Rivafosca per Delgren the Purifier. Sorveglia i cultisti del luogo.",al={"chi è balthule","ruolo di balthule","npc balthule ombrafuria"}},{q="Dove si trova Balthule Ombrafuria?",a="Balthule Ombrafuria si trova poco a ovest della Torre di Althalaxx, nella parte settentrionale di Rivafosca, vicino alla costa.",al={"dove si trova balthule","posizione di balthule","trova balthule ombrafuria"}},{q="Qual è la sua missione presso la Torre di Althalaxx?",a="Balthule è stato inviato a spiare gli incantatori oscuri e i cultisti della Torre di Althalaxx. Raccoglie informazioni e coordina gli attacchi contro i loro rituali.",al={"perché balthule si trova qui","cosa vuole balthule","png delle missioni di althalaxx"}},{q="Chi è Delgren the Purifier?",a="Delgren the Purifier è un paladino umano presso l'Accampamento di Maestra, a Valtetra. Coordina la campagna contro le forze oscure nella parte settentrionale di Rivafosca, con Balthule a fargli da occhi e orecchie sul campo.",al={"chi è delgren","superiore di balthule","legame con delgren"}},{q="Che tipo di nemici occupa la Torre di Althalaxx?",a="Cultisti oscuri e stregoni occupano la Torre di Althalaxx e i terreni circostanti, insieme a servitori demoniaci o d'ombra evocati. Cercano di usare l'antico potere degli Eletti per fini sinistri.",al={"chi c'è nella torre","nemici di althalaxx","cultisti della torre di althalaxx"}},{q="Perché l'Alleanza si interessa a queste rovine?",a="La Torre di Althalaxx è un'antica struttura elfica. La stregoneria maligna e l'attività demoniaca così vicine alle terre elfiche minacciano Rivafosca e gli elfi della notte di Darnassus.",al={"perché occuparsi della torre","presenza dell'alleanza a rivafosca"}}},fx={d382c05d={q="Da che parte sta Balthule Ombrafuria?",a="Balthule serve l'Alleanza e i suoi compagni Elfi della Notte. Lavora direttamente come esploratore e agente per Delgren the Purifier, sorvegliando le minacce che emergono nella parte settentrionale di Darkshore.",al={"fazione di balthule","chi serve balthule","balthule è dell'alleanza"}},["67352a1e"]={q="Cosa vuole Balthule Ombrafuria?",a="Balthule vuole scoprire i rituali oscuri che si svolgono nella Torre di Althalaxx. Spiando i cultisti che occupano la rovina, cerca di raccogliere informazioni sufficienti perché Delgren the Purifier possa purificare la corruzione che si sta radicando lungo la costa.",al={"cosa vuole balthule","obiettivo di balthule","cosa cerca di fare balthule"}},d4776665={q="Perché Balthule Ombrafuria si trova qui?",a="Sentinel Elissa Starbreeze di Auberdine ha mandato Balthule a sorvegliare l'esterno della Torre di Althalaxx. Nascosto nelle vicinanze, ha il compito di osservare gli occupanti ostili e reclutare viaggiatori capaci di sventare i loro piani oscuri.",al={"perché balthule è a darkshore","perché balthule è qui","cosa ha portato balthule qui"}}},fp="21,179,22.310.0,19.294.1,29.104.0,39.103.0,46.160.0,28.190.0,51.182.0,46.160.0"}
P.entries["npc:barithras-moonshade"] = {n="Barithras Ombraluna",s="Ad Auberdine, Barithras Ombraluna cerca viaggiatori che raccolgano piante rare nelle ombrose terre selvagge di Rivafosca.",h="Ad Auberdine, Barithras Ombraluna cerca viaggiatori che raccolgano piante rare nelle ombrose terre selvagge...",kw={"auberdine","barithras","cave mushrooms","rivafosca","cappella mortifera","ombraluna","onu"},ang={["profession:Herbalism"]="Grazie alla tua affinità con la vita vegetale, potresti apprezzare l'interesse di Barithras per gli insoliti funghi delle caverne di Rivafosca.",["race:NightElf"]="Come Elfo della Notte, puoi aiutare i tuoi simili ad Auberdine a proteggere Rivafosca sorvegliandone le piante e mantenendo i legami con antichi guardiani della foresta come Onu."},sec={{t="Residente di Auberdine",b="Barithras Ombraluna veglia su Auberdine e aiuta gli Elfi della Notte a studiare Rivafosca e a prendersene cura. Invia i viaggiatori nelle caverne vicine per raccogliere funghi da studiare e utilizzare, tra cui la Cappella Mortifera."},{t="Legami con gli Antichi",b="Barithras guida anche i viaggiatori più capaci verso sud per incontrare Onu. L'antico si adopera per risanare il suolo contaminato di Rivafosca e placare i suoi irrequieti spiriti della natura."}},faq={{q="Chi è Barithras Ombraluna?",a="Ad Auberdine, Barithras Ombraluna chiede ai viaggiatori di indagare sulle piante locali e contattare i guardiani della regione.",al={"chi è barithras","barithras ombraluna","chi è questo elfo della notte"}},{q="Dove posso trovare Barithras Ombraluna?",a="Puoi trovare Barithras Ombraluna ad Auberdine, l'insediamento portuale sulla costa di Rivafosca.",al={"posizione di barithras","dove si trova barithras","posizione di barithras ombraluna"}},{q="Quali compiti assegna Barithras?",a="Barithras invia i viaggiatori nelle caverne vicine per raccogliere funghi, tra cui la Cappella Mortifera, poi li indirizza a sud per incontrare Onu.",al={"missioni di barithras","quali missioni offre barithras","missione cave mushrooms"}},{q="Barithras è imparentato con gli altri Ombraluna?",a="Non si conoscono parenti di Barithras, quindi ogni legame con altri Elfi della Notte di nome Ombraluna è ignoto.",al={"famiglia ombraluna","altri ombraluna","barithras è imparentato con la sentinella ombraluna"}}},fx={["1a832bfc"]={q="Da che parte sta Barithras Ombraluna?",a="Barithras Ombraluna è saldamente schierato con gli Elfi della Notte di Auberdine e con la più ampia Alleanza. Di stanza a Darkshore, si prende cura del benessere dell'insediamento e aiuta i viaggiatori che si impegnano a proteggere la natura circostante.",al={"fazione di barithras ombraluna","chi serve barithras","barithras e l'alleanza"}},e41cf5ef={q="Cosa vuole Barithras Ombraluna?",a="Barithras cerca aiuto per le questioni locali di Darkshore: incarica avventurieri capaci di raccogliere risorse come i funghi delle caverne e li indirizza poi a consultare antichi alleati come Onu nei boschetti a sud.",al={"obiettivo di barithras ombraluna","di cosa ha bisogno barithras","missioni di barithras ombraluna"}}},fp="19,106,21.203.0,20.152.0,27.113.0,37.90.0,31.129.0,45.99.0"}
P.entries["npc:barkeep-daniels"] = {n="Daniels l'Oste",s="Alla Lakeshire Inn, Daniels l'Oste continua a servire da bere mentre i predoni infestano le strade. Guardie cittadine, pescatori e viaggiatori vi trovano accoglienza, anche se le scorte scarseggiano.",h="Alla Lakeshire Inn, Daniels l'Oste continua a servire da bere mentre i predoni infestano le strade.",kw={"daniels l'oste","barista","daniels","dry times","lakeshire inn","locandiere crestarossa"},ang={["faction:Alliance"]="Per l'Alleanza, mantenere alto il morale a Borgolago è importante. L'insediamento è il martoriato baluardo del regno contro la Fortezza Roccianera a nord."},sec={{t="Tenere alto il morale a Borgolago",b="Vicino al ponte, Daniels l'Oste versa da bere e accoglie i visitatori alla Lakeshire Inn. Gli gnoll e gli orchi Roccianera fanno pressione su Borgolago da mesi, e i suoi difensori si rifugiano nella taverna dopo cupe pattuglie. Le incursioni e le strade interrotte hanno sconvolto il commercio in tutta la regione. Con i liquori che scarseggiano proprio quando la cittadina ha bisogno di buonumore, Daniels accoglie i viaggiatori disposti a recuperare carichi da insediamenti più sicuri."}},faq={{q="Chi è Daniels l'Oste?",a="Daniels l'Oste si occupa del bancone della Lakeshire Inn e serve gli abitanti, i viaggiatori e la guardia cittadina.",al={"daniels crestarossa","oste borgolago","chi è daniels"}},{q="Perché sta esaurendo le bevande?",a="Le incursioni degli orchi Roccianera e degli gnoll hanno bloccato le carovane e le vie commerciali dirette alle Montagne Crestarossa. Le consegne si sono fermate, mentre i difensori sotto pressione consumano le scorte di alcolici, lasciando Daniels in difficoltà con i rifornimenti.",al={"perché senza alcol","storia missione dry times","perché niente alcol"}},{q="Per cosa ha bisogno di aiuto?",a="Daniels ha bisogno di viaggiatori che portino altri liquori da fuori Redridge, così che la locanda possa continuare a servire i suoi avventori.",al={"missione daniels l'oste","cosa vuole","commissione daniels"}}},fx={["2f43c9bf"]={q="Da che parte sta Daniels l'Oste?",a="Daniels l'Oste è un leale cittadino dell'Alleanza e una presenza fissa a Lakeshire. Serve la gente del posto, i visitatori e i difensori di stanza in città dal bancone del Lakeshire Inn, restando saldamente al fianco del regno di Roccavento di fronte alla crescente minaccia dei Roccianera.",al={"fazione di daniels l'oste","daniels l'oste è dell'alleanza","lealtà di daniels a redridge"}}},fp="15,182,33.405.0,23.107.0,32.215.0,28.108.0"}
P.entries["npc:baron-aquanis"] = {n="Barone Aquanis",s="Nelle Moonshrine Ruins allagate degli Abissi di Fondocupo, il Barone Aquanis emerge dalle profondità quando la Fathom Stone viene disturbata. I cultisti del Martello del Crepuscolo occupano le rovine, e l'Earthen Ring sospetta che il barone sia stato corrotto.",h="Nelle Moonshrine Ruins allagate degli Abissi di Fondocupo, il Barone Aquanis emerge dalle profondità quando...",kw={"aquanis","barone aquanis","abissi di fondocupo","the earthen ring","nucleo profondo","fathom stone","je'neu sancrea","moonshrine ruins","martello del crepuscolo","elementale dell'acqua"},ang={["class:Shaman"]="Per uno sciamano dell'Earthen Ring, il Barone Aquanis è un tragico esempio di perversione elementale. I suoi resti contaminati potrebbero offrire indizi su come purificare gli spiriti corrotti.",["faction:Horde"]="Je'neu Sancrea collabora con l'Orda sulla costa di Valtetra. Il Nucleo Profondo recuperato dai suoi aiutanti dell'Orda serve a mostrare cosa sta facendo il Martello del Crepuscolo agli elementi del luogo."},sec={{t="Guardiano della Fathom Stone",b="Sotto le sale allagate delle Moonshrine Ruins giace la Fathom Stone, circondata dai cultisti del Martello del Crepuscolo. Al suo interno si trova un Nucleo Profondo. Se letto correttamente, il congegno rivela la storia dell'attività elementale nelle vicinanze. Je'neu Sancrea dell'Earthen Ring invia avventurieri dell'Orda a recuperarlo. Disturba la pietra, e il Barone Aquanis emergerà dalle profondità."},{t="Corruzione delle Profondità",b="L'Earthen Ring considera da tempo il Barone Aquanis una potenza elementale corrotta. Quando viene distrutto, lascia un Globo d'Acqua Strano. La sfera impenetrabile contiene acqua putrida che si agita al suo interno e sembra avergli fornito energia. Je'neu Sancrea crede che possa rivelare cosa abbia corrotto il barone e in che modo. Il Martello del Crepuscolo potrebbe esserne responsabile, dice, ma vuole delle prove."}},faq={{q="Dove posso trovare il Barone Aquanis?",a="Il Barone Aquanis dimora nelle Moonshrine Ruins allagate, nelle profondità degli Abissi di Fondocupo. Emerge quando qualcuno disturba la Fathom Stone sommersa, come fanno gli avventurieri dell'Orda recuperando il suo Nucleo Profondo per Je'neu Sancrea.",al={"posizione di aquanis","dove si trova il barone aquanis","come far apparire il barone aquanis"}},{q="Cos'è il Globo d'Acqua Strano?",a="Il Globo d'Acqua Strano viene lasciato dal Barone Aquanis quando viene distrutto. La sfera impenetrabile contiene acqua putrida che si agita al suo interno e sembra aver alimentato la sua energia elementale. Je'neu Sancrea dell'Earthen Ring vuole studiarla per trovare prove di cosa abbia corrotto il barone e in che modo.",al={"globo d'acqua strano","globo di aquanis","a cosa serve il globo d'acqua"}},{q="Perché l'Earthen Ring si interessa al Barone Aquanis?",a="L'Earthen Ring veglia sull'equilibrio degli elementi. Je'neu Sancrea e i suoi compagni considerano da tempo il Barone Aquanis una potenza elementale corrotta. Poiché il Martello del Crepuscolo occupa le Moonshrine Ruins, temono che il culto stia costringendo gli elementi ad agire contro l'Orda. I resti del barone e il Nucleo Profondo potrebbero rivelare cosa sta facendo il culto.",al={"perché interessa al the earthen ring","je'neu sancrea aquanis"}},{q="Cos'è il Nucleo Profondo?",a="Il Nucleo Profondo è un manufatto elementale custodito nella Fathom Stone sommersa. Uno sciamano esperto può leggerlo per conoscere la storia dell'attività elementale nella regione. Potrebbe anche svelare i rituali oscuri del Martello del Crepuscolo nelle rovine.",al={"storia del nucleo profondo","cosa fa il nucleo profondo"}},{q="Il Barone Aquanis è alleato del Martello del Crepuscolo?",a="Per quanto se ne sa, il Barone Aquanis è un elementale corrotto, non un servitore consenziente. I cultisti del Martello del Crepuscolo nelle Moonshrine Ruins sono i sospettati più ovvi. Je'neu Sancrea dice che il loro coinvolgimento non lo sorprenderebbe, ma vuole delle prove prima di affermarlo con certezza.",al={"aquanis è del martello del crepuscolo","setta aquanis"}},{q="L'Alleanza ha affari da sbrigare con il Barone Aquanis?",a="Non direttamente. Je'neu Sancrea è uno sciamano dell'Earthen Ring che collabora con l'Orda sulla costa di Valtetra, e si occupa della Fathom Stone e del Barone Aquanis. Invia avventurieri dell'Orda a recuperare il Nucleo Profondo. Gli esploratori dell'Alleanza negli Abissi di Fondocupo hanno altri incarichi da svolgere.",al={"l'alleanza può combattere aquanis","missione aquanis alleanza"}}},fp="13,234,28.355.0,24.370.1,31.220.0,32.264.0,52.357.0,24.231.0,51.276.0,51.276.0"}
P.entries["npc:baron-revilgaz"] = {n="Barone Granbottino",s="Dall'alto balcone di Baia del Bottino, il Barone Granbottino tiene in pugno il porto e i suoi commerci. Guida i Blackwater Raiders per conto del Cartello degli Spargifumo, mantenendo il porto aperto all'Alleanza e all'Orda mentre tutela i propri interessi. Assolda chi sorvegli i rivali e cerchi antiche reliquie nella giungla.",h="Dall'alto balcone di Baia del Bottino, il Barone Granbottino tiene in pugno il porto e i suoi commerci.",kw={"predoni degli acquanera","bucanieri velerosse","baia del bottino","lago nazferiti","revilgaz","taverna del lupo di mare","corno marino","cartello degli spargifumo","pietra delle maree"},ang={["class:Rogue"]="Come ladro, potresti scoprire che Granbottino apprezza ladri, spie e opportunisti. Assolda ladri per furti rischiosi, sabotaggi contro cartelli rivali e il recupero segreto di rari manufatti della giungla.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi risalire alle origini di Baia del Bottino tra le rovine di Baia degli Acquanera, un'enclave di Roccavento precedente alla Prima Guerra. Granbottino collabora con studiosi e bibliotecari umani a Roccavento quando le antiche conoscenze possono fruttare un profitto.",["profession:Engineering"]="Come ingegnere, troverai Granbottino coinvolto nelle rivalità dell'ingegneria goblin. Ricorre a mezzi sleali per ottenere progetti avanzati e regolatori di carburante dalla S.P.R. & Co."},sec={{t="Signore di Baia del Bottino",b="Dalla Taverna del Lupo di Mare, il Barone Granbottino osserva i moli di Baia del Bottino con il Contrammiraglio Corno Marino, suo fidato consigliere tauren, al fianco. Tagliaborse, mercanti e corsari rispondono tutti al suo pugno di ferro. Baia degli Acquanera nacque come insediamento umano, ma i troll la sopraffecero prima della Prima Guerra. I goblin presero possesso del porto e lo fortificarono, facendone il fulcro commerciale dei Blackwater Raiders.\n\nGranbottino mantiene Baia del Bottino ufficialmente aperta ai viaggiatori dell'Alleanza e dell'Orda. Impone la neutralità all'interno del porto affinché il commercio possa proseguire."},{t="Una tela di ambizioni",b="Quando le guerre altrove su Azeroth rallentarono gli affari, Granbottino trovò un modo per richiamare le folle a Baia del Bottino. La scoperta del tastyfish gliene diede i mezzi: creò la Stranglethorn Fishing Extravaganza. In tutta la Valle di Rovotorto, tiene d'occhio rivali e minacce.\n\nAssolda chi compia sabotaggi contro la S.P.R. & Co. presso il Lago Nazferiti. Sorveglia anche la spedizione di caccia di Nesingwary e gli accampamenti militari umani ribelli a nord. Mantiene attivi i rapporti commerciali con Monte Sparachiodi e Pozzik alla Pista dei Miraggi."},{t="La Pietra delle Maree",b="Oltre il porto, Granbottino cerca ricchezze e poteri antichi. Si vocifera di un'isola infestata al largo della costa, e lui invia avventurieri a cercare la leggendaria Pietra delle Maree. Consultano antichi tomi nella biblioteca di Roccavento e studiano residui elementali con l'Arcimago Ansirem Tessiruna. Poi recuperano un antico pugnale troll dai Bucanieri Velerosse.\n\nIl pugnale spezza la protezione dell'altare costiero. Granbottino spezza una letale maledizione elementale e si appropria della reliquia inestimabile per custodirla nei propri forzieri."}},faq={{q="Chi è il Barone Granbottino?",a="Il Barone Granbottino guida Baia del Bottino e i Blackwater Raiders per conto del Cartello degli Spargifumo. L'avidità e una diplomazia pragmatica guidano il suo governo del porto dei pirati.",al={"chi è revilgaz","storia di revilgaz","boss di baia del bottino","leader di baia del bottino"}},{q="Dove si trova il Barone Granbottino?",a="Il Barone Granbottino si trova sul balcone più alto della Taverna del Lupo di Mare a Baia del Bottino. Il Contrammiraglio Corno Marino, suo fidato consigliere, gli sta accanto mentre osserva la baia.",al={"dove si trova revilgaz","posizione di revilgaz","come trovare revilgaz"}},{q="Qual è il rapporto di Granbottino con i Bucanieri Velerosse?",a="I Bucanieri Velerosse sono acerrimi nemici di Granbottino. Rifiutano le regole del Cartello degli Spargifumo e assaltano le navi mercantili di Baia del Bottino. I loro capi complottano per uccidere Granbottino e Corno Marino.",al={"revilgaz bucanieri velerosse","bucanieri velerosse contro revilgaz","perché odiare i bucanieri velerosse"}},{q="Qual è l'interesse di Granbottino nella Pista dei Miraggi?",a="Granbottino sostiene la scuderia goblin di Pozzik contro gli gnomi nelle Distese Salate. Invia avventurieri a rubare i progetti riservati del regolatore di carburante della S.P.R. & Co. presso il Lago Nazferiti e a portarli alla pista.",al={"revilgaz corse","revilgaz distese salate","revilgaz pozzik"}},{q="Che cos'è la Stranglethorn Fishing Extravaganza?",a="La Stranglethorn Fishing Extravaganza è una gara di pesca settimanale lungo la costa di Stranglethorn. Quando le guerre altrove su Azeroth rallentarono il commercio, Granbottino sostenne il pescatore Riggle Bassbait e trasformò la pesca locale del tastyfish in un torneo per risollevare l'economia di Baia del Bottino.",al={"storia del torneo di pesca","chi ha iniziato la gara di pesca","pesce gustoso revilgaz"}},{q="Che cos'è la Pietra delle Maree?",a="La Pietra delle Maree è un'antica pietra maledetta nascosta presso la Scogliera Infame. Granbottino ne scopre la leggenda nei documenti di Roccavento e assolda l'Arcimago Ansirem Tessiruna, studioso di Dalaran, per aiutare gli avventurieri a spezzarne le protezioni elementali e impadronirsene.",al={"missione pietra delle maree","pietra della scogliera infame","altare delle maree"}}},fp="14,298,19.536.0,17.507.0,22.504.1,22.151.0,34.166.0,62.180.0,47.229.0,47.262.0,31.238.1"}
P.entries["npc:baron-silverlaine"] = {n="Barone Argenius",s="Nella Sala del Consiglio sopra Rovonero, lo spirito del Barone Argenius indugia ancora. Governava Silverlaine Keep finché l'Arcimago Arugal non scatenò i worgen sulla regione, e questi lo massacrarono.",h="Nella Sala del Consiglio sopra Rovonero, lo spirito del Barone Argenius indugia ancora.",kw={"arugal","barone","fantasma","sala del consiglio","forte","rovonero","zannascura","argenius","worgen"},ang={["class:Mage"]="Per un mago, il destino di Argenius è un monito contro la magia sconsiderata. L'Arcimago Arugal usò incautamente l'arte dell'evocazione, distruggendo vite innocenti e lasciando cicatrici durature.",["race:Human"]="Per un umano, il destino di Argenius segna la caduta del potere nobiliare umano ai confini di Gilneas. La sua fortezza cadde per la magia sconsiderata di un mago formatosi a Dalaran.",["race:Undead"]="Per un Reietto che attraversa Silverpine, lo spettro di Argenius è un'altra vestigia dell'antica aristocrazia da eliminare prima di spezzare il dominio di Arugal sulla fortezza."},sec={{t="La caduta di Silverlaine Keep",b="Il Barone Argenius governava una tenuta nobiliare sulle colline meridionali di Silverpine. La sua fortezza proteggeva le terre circostanti e le manteneva al sicuro. Poi l'Arcimago Arugal evocò i worgen per combattere il Flagello dilagante e li scatenò sulla regione. Le bestie feroci erano incontrollabili. Presero d'assalto la roccaforte, sopraffecero le guardie e massacrarono il barone."},{t="Uno spettro tormentato",b="Il Barone Argenius rimane vincolato all'antica Sala del Consiglio della fortezza. Il suo fantasma irrequieto vaga tra i tavoli da pranzo distrutti dove un tempo banchettava. Il signore maledetto attacca gli intrusi che entrano nella sua antica dimora."}},faq={{q="Chi era il Barone Argenius?",a="Il Barone Argenius governava Silverlaine Keep, una fortezza sopra Rovonero. I worgen invasero la fortezza e lo uccisero.",al={"storia del barone argenius","chi è argenius","chi regnava su zannascura"}},{q="Perché infesta il Forte di Zannascura?",a="L'Arcimago Arugal scatenò i worgen sulla dimora di Argenius, e questi lo massacrarono. Maledetto nella morte, il suo fantasma rimane vincolato alla sala da pranzo della fortezza e non può trovare pace.",al={"perché argenius è un fantasma","argenius è morto","spirito di argenius"}},{q="Perché Argenius attacca gli intrusi?",a="Lo spirito maledetto di Argenius rimane nella sua antica dimora. Lì attacca gli intrusi nella Sala del Consiglio.",al={"perché argenius attacca","fantasma di argenius","argenius intrusi"}},{q="Dove si trova all'interno del forte?",a="Il Barone Argenius infesta la Sala del Consiglio, un tempo la sontuosa sala da pranzo della fortezza. Fu devastata quando la sua tenuta cadde.",al={"dove si trova argenius","posizione del barone argenius","sala da pranzo di argenius"}},{q="Come si chiamava il Forte di Zannascura prima dell'attacco dei worgen?",a="Prima dell'attacco dei worgen, la fortezza si chiamava Silverlaine Keep, dal nome della nobile famiglia del barone. La famiglia la governava prima che Arugal ne prendesse il controllo.",al={"nome originale di zannascura","storia di forte silverlaine","vecchio nome di zannascura"}},{q="Qualcuno della famiglia di Argenius è sopravvissuto?",a="Nessun resoconto dice se qualcuno della famiglia di Argenius sia sopravvissuto. I resoconti narrano dell'assalto dei worgen e del fantasma del barone, ma non dicono nulla sul resto della sua casa.",al={"famiglia di argenius","la famiglia di argenius è sopravvissuta","eredi di argenius"}}},fx={["1b1b3783"]={q="Da che parte sta il Barone Argenius?",a="Il Barone Argenius combatte solo per sé stesso e per i tragici ricordi della sua tenuta in rovina. Fu ucciso quando l'arcimago Arugal scatenò i feroci worgen sul castello, ma la morte ha deformato la sua mente spettrale. Vincolato da una crudele maledizione, aggredisce senza distinzione tutti i vivi che si introducono nella sua sala da pranzo.",al={"fazione del barone argenius","per chi combatte argenius","il barone argenius è alleato di arugal"}},["5d3ddd3d"]={q="Cosa vuole il Barone Argenius?",a="Intrappolato come fantasma vendicativo, il Barone Argenius vuole solo scacciare o massacrare chiunque osi invadere la sua dimora. Tormentato dalla sua morte violenta, il suo spirito si avventa con furia implacabile su chi disturba le antiche sale della sua fortezza.",al={"cosa vuole argenius","obiettivo del barone argenius","perché argenius attacca"}},["02c6a3ca"]={q="A chi è legato il Barone Argenius?",a="Il tragico destino del Barone Argenius è legato all'arcimago Arugal. Quando Arugal evocò i worgen extradimensionali per combattere il Flagello, le bestie divennero feroci e assediarono la fortezza di Argenius. Arugal si impadronì della fortezza e la ribattezzò Forte di Zannascura; ancora oggi il fantasma vendicativo del Barone vi infesta i corridoi.",al={"legami di argenius","a chi è legato argenius","barone argenius e arugal"}}},fp="17,191,28.360.0,19.208.0,26.120.0,35.170.0,40.104.0,34.113.0,57.141.0,43.176.0"}
P.entries["npc:baros-alexston"] = {n="Baros Alexston",s="Nel Municipio di Roccavento, Baros Alexston cura la capitale che contribuì a ricostruire. Un tempo era legato a Edwin VanCleef nella Gilda degli Scalpellini, ma rimase fedele alla corona quando la gilda si divise.",h="Nel Municipio di Roccavento, Baros Alexston cura la capitale che contribuì a ricostruire.",kw={"alexston","architetto","baros","piazza della cattedrale","municipio","defias","cascina","scalpellini","lettera mai spedita","vancleef"},ang={["class:Rogue"]="Come ladro a Roccavento, tramite Baros hai un legame con il Maestro Mathias Shaw e l'SI:7. Devono un favore all'architetto, pur mantenendo la cosa riservata, nonostante i suoi passati legami con VanCleef.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere il doloroso compromesso che divise la Gilda degli Scalpellini. I suoi artigiani avevano dedicato la vita alla ricostruzione della capitale.",["race:Human"]="Come umano delle Marche Occidentali, potresti conoscere il cognome Baros per via della Cascina degli Alexston, ormai in rovina. Ora ladri e gnoll la infestano."},sec={{t="Dalla cascina al patibolo",b="Baros crebbe nella Cascina degli Alexston, tra le ondulate praterie delle Marche Occidentali. Quando era giovane, alcuni ladri invasero e incendiarono la casa della sua famiglia. Prima della fuga, suo padre nascose i preziosi cimeli di famiglia in vari punti dei terreni circostanti.\n\nIn seguito, Baros si recò nella capitale e si unì alla Gilda degli Scalpellini. Per anni lavorò al fianco del Gran Maestro Edwin VanCleef, facendo risorgere Roccavento dalle ceneri della Prima Guerra."},{t="Un'amara separazione",b="Quando la ricostruzione di Roccavento terminò, la Casa dei Nobili rifiutò di versare il pagamento promesso. Seguirono furiose proteste, la Gilda degli Scalpellini si sciolse e rivolte mortali riempirono le strade. Edwin VanCleef guidò gli artigiani non pagati in esilio, dove formarono la Fratellanza dei Defias.\n\nI nobili offrirono a Baros la carica di Architetto Cittadino a condizione che rinnegasse l'insurrezione. Contrario alla deriva della gilda verso il banditismo violento, accettò. La scelta aprì una profonda e dolorosa frattura tra lui e i suoi ex compagni."},{t="Il fantasma nelle Miniere della Morte",b="Baros supervisiona la manutenzione della capitale dalla sua scrivania nel Municipio. Mathias Shaw dell'SI:7 gli deve un favore, tenuto riservato.\n\nDopo la caduta di VanCleef nelle profondità delle Miniere della Morte, sul cadavere del capo dei Defias rimase una lettera mai spedita indirizzata a Baros. La lettera ricorda un legame spezzato dalla politica, dal tradimento e dal sangue versato sulle fondamenta di Roccavento."}},faq={{q="Dove posso trovare Baros Alexston?",a="Puoi trovare Baros Alexston nel Municipio di Roccavento, sul lato nord di Piazza della Cattedrale, a Roccavento.",al={"posizione di baros alexston","dove si trova baros alexston","baros roccavento"}},{q="Qual è il ruolo di Baros Alexston a Roccavento?",a="In qualità di Primo Architetto, Baros supervisiona le costruzioni, la manutenzione e la pianificazione architettonica di Roccavento.",al={"lavoro di baros","titolo di baros","cosa fa baros"}},{q="Come fa Baros a conoscere Edwin VanCleef?",a="Baros ed Edwin VanCleef erano stretti colleghi nella Gilda degli Scalpellini. Lavorarono fianco a fianco per ricostruire Roccavento dopo la Prima Guerra. Quando la Casa dei Nobili rifiutò di pagare i lavoratori, VanCleef guidò una ribellione, mentre Baros rimase e divenne Architetto Cittadino.",al={"baros e vancleef","baros conosceva edwin","baros scalpellini"}},{q="Perché Baros non si è unito alla Fratellanza dei Defias?",a="Baros si oppose alla svolta della gilda verso la rivolta violenta. I nobili gli offrirono la carica di Architetto Cittadino a condizione che rifiutasse di seguire VanCleef, e Baros accettò.",al={"perché baros è rimasto","separazione tra baros e i defias","perché baros ha tradito gli scalpellini"}},{q="Cos'è la lettera mai spedita trovata su Edwin VanCleef?",a="Dopo la morte di Edwin VanCleef nelle Miniere della Morte, sul suo corpo fu trovata una lettera mai spedita indirizzata a Baros Alexston. Parla del rancore persistente e del passato irrisolto tra gli ex artigiani.",al={"missione lettera mai spedita","lettera mai spedita di vancleef","lettera a baros"}},{q="Qual è il legame di Baros Alexston con le Marche Occidentali?",a="Baros crebbe nella Cascina degli Alexston, nelle Marche Occidentali. Dopo che alcuni ladri la incendiarono, la sua famiglia fuggì. Recluta avventurieri per recuperare i suoi oggetti d'infanzia, tra cui la sua prima bussola.",al={"cascina degli alexston","baros marche occidentali","infanzia di baros"}}},fx={["47ce41c7"]={q="Perché Baros Alexston si trova al municipio di Roccavento?",a="Baros Alexston lavora al municipio di Piazza della Cattedrale come architetto capo di Roccavento. Quando la Gilda degli Scalpellini si ribellò per i salari non pagati, Baros rifiutò di unirsi alla rivolta violenta di Edwin VanCleef. In cambio della sua lealtà e della rottura ideologica con la gilda, la corona gli offrì la carica ufficiale di architetto della città, con il compito di supervisionare le opere pubbliche e i progetti edilizi del regno.",al={"perché baros alexston è qui","perché baros alexston è al municipio","cosa fa baros a roccavento"}},["8a4dbaf4"]={q="Che cosa vuole Baros Alexston?",a="Baros cerca di servire con onore la città di Roccavento, affrontando al contempo i fantasmi del suo passato. Sul piano personale, desidera recuperare i cimeli di famiglia perduti, come la sua prima bussola, nascosta prima che i ladri dessero fuoco alla fattoria della sua infanzia nelle Marche Occidentali. Sul piano politico, è profondamente preoccupato di smascherare i tradimenti in città e porre fine alla violenta campagna della Fratellanza dei Defias.",al={"motivazioni di baros alexston","che cosa vuole baros","obiettivi di baros"}}},fp="14,189,34.402.0,24.486.1,27.341.1,32.112.0,43.104.0,35.263.1,45.150.1,50.198.1,48.185.0"}
P.entries["npc:bartleby"] = {n="Bartleby",s="Alla Taverna del Porco Urlante, Bartleby beve e attacca briga nella Città Vecchia di Roccavento. La sua ostinata presa sulla birra ne fa una prova per gli aspiranti guerrieri, che devono affrontarlo in una rissa da taverna.",h="Alla Taverna del Porco Urlante, Bartleby beve e attacca briga nella Città Vecchia di Roccavento.",kw={"bartleby","rissa","burlguard","ubriaco","boccale","città vecchia","taverna del porco urlante","taverna","guerriero"},ang={["class:Warrior"]="Come giovane guerriero a Roccavento, ricordi il tuo duello con Bartleby. Sottrarre il boccale all'ostinato ubriacone è una prova memorabile di combattimento corpo a corpo.",["race:Human"]="Come umano, vedi il lato duro e operaio della Città Vecchia di Roccavento, dove le dispute locali si risolvono tra sgabelli rovesciati anziché per decreto reale."},sec={{t="Un habitué della Taverna del Porco Urlante",b="Bartleby trascorre le giornate alla Taverna del Porco Urlante, nella Città Vecchia di Roccavento. La sua clientela è più rozza di quella delle birrerie di Piazza della Cattedrale. Si aggrappa al suo boccale preferito, beve birra a buon mercato, cova rancori e attacca briga con chiunque lo disturbi."},{t="Il rito di passaggio di un guerriero",b="Gli istruttori dei guerrieri di Roccavento usano Bartleby come prova pratica. Harry Burlguard manda i combattenti alle prime armi a cercarlo e a sottrargli il boccale. Scambiano pugni a mani nude con l'attaccabrighe ubriaco, dimostrando di avere la grinta necessaria per affrontare un avversario indisciplinato nel corpo a corpo."}},faq={{q="Chi è Bartleby?",a="Bartleby è un avventore turbolento della Taverna del Porco Urlante, nella Città Vecchia di Roccavento. Si ubriaca fradicio e si rifiuta di cedere il boccale senza una scazzottata.",al={"storia di bartleby","chi è bartleby","bartleby roccavento"}},{q="Dove posso trovare Bartleby?",a="Puoi trovare Bartleby intento a bere al pianterreno della Taverna del Porco Urlante, nella Città Vecchia di Roccavento.",al={"posizione di bartleby","dove si trova bartleby","bartleby taverna del porco urlante"}},{q="Perché i guerrieri devono combattere contro di lui?",a="Harry Burlguard, un istruttore dei guerrieri di Città Vecchia, manda le giovani reclute da Bartleby per metterne alla prova le capacità di combattimento. Sottrargli il boccale con la forza dimostra che sanno affrontare una rissa improvvisa e un avversario ostico.",al={"perché sconfiggere bartleby","missione guerriero bartleby","scopo di bartleby"}},{q="Cosa succede quando lo affronti?",a="Quando qualcuno lo sfida per il boccale, Bartleby beve una pozione per aumentare la propria resistenza e diventa ostile. Combatte a mani nude nella taverna finché non viene costretto alla resa.",al={"combattere bartleby","missione beat bartleby","rissa con bartleby"}},{q="Bartleby appartiene a qualche fazione od organizzazione?",a="Bartleby è un civile di Roccavento e un ubriacone abituale. Non ha legami noti con la Fratellanza dei Defias o con la guardia cittadina.",al={"bartleby è dei defias","fazione di bartleby","bartleby alliance"}},{q="Perché non si limita a consegnare il suo boccale?",a="Bartleby è bellicoso, ubriaco fradicio e ostinato. Considera un insulto ogni richiesta della sua birra o del suo boccale e preferisce risolvere le questioni a pugni piuttosto che rinunciare all'alcol.",al={"boccale di bartleby","boccale di birra di bartleby","perché battersi per il boccale"}}},fx={["59ff692a"]={q="Perché Bartleby si trova nella Città Vecchia?",a="Bartleby passa le giornate ad affogare i dispiaceri nell'alcol alla Taverna del Porco Urlante. Nella Città Vecchia non ha grandi ambizioni né incarichi: resta nei pressi del bancone, sorseggia la sua birra e custodisce la sua preziosa caraffa da chiunque osi infastidirlo.",al={"perché bartleby è alla taverna del porco urlante","perché bartleby si trova qui","perché bartleby è a roccavento"}}},fp="8,194,32.256.0,27.267.0,16.166.0,26.105.0,34.193.0,35.159.0,52.126.0,36.184.0"}
P.entries["npc:bashana-runetotem"] = {n="Bashana Totem Runico",s="Sull'Altura degli Anziani di Picco del Tuono, Bashana Totem Runico studia le piante e la corruzione. Figlia dell'Arcidruido Hamuul Totem Runico, aiuta il Circolo Cenariano.",h="Sull'Altura degli Anziani di Picco del Tuono, Bashana Totem Runico studia le piante e la corruzione.",kw={"bashana","abissi di fondocupo","circolo cenariano","altura degli anziani","hamuul","morrowgrain","totem runico","picco del tuono"},ang={["class:Druid"]="Come druida tauren che apprende sotto la guida di Hamuul, Bashana mostra il lavoro sul campo necessario per comprendere i mutamenti dell'ecologia di Kalimdor.",["faction:Horde"]="Come membro dell'Orda, puoi rivolgerti a Bashana per mettere in contatto il Circolo Cenariano di Picco del Tuono con i campioni che combattono le minacce dei cultisti."},sec={{t="Una Figlia del Circolo",b="Bashana Totem Runico porta avanti l'eredità druidica di suo padre, l'Arcidruido Hamuul Totem Runico, sull'Altura degli Anziani di Picco del Tuono. Mentre lui guida i druidi tauren e consiglia Cairne Zoccolo Sanguinario, lei studia piante insolite e minacce in tutta la regione. Fornisce ai viaggiatori strumenti come sacche sempreverdi per coltivare piante misteriose, tra cui il morrowgrain. Coordina anche gli sforzi dell'Orda contro la corruzione che si diffonde da luoghi come gli Abissi di Fondocupo."}},faq={{q="Chi è Bashana Totem Runico?",a="Bashana Totem Runico è una druida tauren e ricercatrice sull'Altura degli Anziani di Picco del Tuono. È figlia dell'Arcidruido Hamuul Totem Runico e studia piante insolite per il Circolo Cenariano. Organizza anche gli interventi contro le minacce alla natura in tutta Kalimdor.",al={"chi è bashana","storia di bashana","chi è bashana totem runico"}},{q="Quali ricerche conduce con il morrowgrain?",a="Bashana chiede agli avventurieri dell'Orda di coltivare e raccogliere morrowgrain usando pacchetti di semi e terriccio. Il Circolo Cenariano studia le proprietà insolite di quest'erba e il suo legame con altri misteri botanici in tutta Kalimdor.",al={"ricerca su morrowgrain","cosa fa bashana con morrowgrain","perché morrowgrain"}},{q="Qual è il suo legame con gli Abissi di Fondocupo?",a="Bashana riceve un rapporto e delle prove dagli avventurieri inviati da Argent Guard Thaelrid ad affrontare i cultisti degli Abissi di Fondocupo. Li ricompensa per il loro aiuto contro la corruzione che minaccia Valtetra.",al={"bashana abissi di fondocupo","missione blackfathom villainy","perché bfd"}},{q="Dove si può trovare?",a="Bashana si trova sull'Altura degli Anziani a Picco del Tuono, vicino ai padiglioni druidici. L'altopiano è dedicato agli sciamani, ai druidi e agli anziani spirituali della città.",al={"dove si trova bashana totem runico","posizione di bashana","come trovare bashana"}}},fx={["2d6e22c9"]={q="Da che parte sta Bashana Totem Runico?",a="Bashana è devota sia all'Orda sia al Circolo Cenariano. Druida tauren che opera da Picco del Tuono, lavora per aiutare il suo popolo e l'Orda nel suo insieme, restando fedele ai principi dei druidi cenariani, che difendono la natura e studiano i misteri e la corruzione che affliggono Kalimdor.",al={"fazione di bashana totem runico","chi serve bashana","bashana è dell'orda o del circolo cenariano"}},["10189cb7"]={q="A chi è legata Bashana Totem Runico?",a="Bashana è la figlia dell'Arcidruido Hamuul Totem Runico, il venerabile capo dei druidi tauren di Picco del Tuono. Sotto la sua guida, conduce importanti ricerche per conto del Circolo Cenariano e aiuta a guidare i nuovi campioni che desiderano sostenere il lavoro dei druidi.",al={"famiglia di bashana totem runico","con chi è imparentata bashana","bashana è la figlia di hamuul"}}},fp="17,151,24.442.0,25.250.0,48.219.0,44.194.0,23.151.0"}
P.entries["npc:bath-rah-the-windwatcher"] = {n="Bath'rah il Guardiavento",s="Vicino alla Gola di Ventofreddo, Bath'rah il Guardiavento studia i venti del nord sulle Montagne d'Alterac. Lontano dalla sua patria tropicale, lo sciamano troll della giungla cerca campioni abbastanza forti da plasmare la tempesta in armi.",h="Vicino alla Gola di Ventofreddo, Bath'rah il Guardiavento studia i venti del nord sulle Montagne d'Alterac.",kw={"alterac","bath'rah","ventofreddo","cyclonian","elementale","sciamano","whirlwind","the windwatcher"},ang={["class:Shaman"]="Da maestro degli elementi, Bath'rah condivide un profondo legame spirituale con gli sciamani che cercano una comunione più stretta con gli spiriti della terra, dell'acqua e dell'aria.",["class:Warrior"]="I combattenti veterani conoscono Bath'rah perché li guida nelle prove per forgiare le armi Whirlwind con l'essenza di Cyclonian, l'elementale del vento."},sec={{t="L'eremita delle vette",b="Bath'rah il Guardiavento vive appartato tra le fredde rovine delle Montagne d'Alterac. I troll della giungla abitano solitamente tra foreste e coste calde, lontano da queste vette. Sciamano e artigiano esperto, ascolta il vento e comunica con gli spiriti della natura. Intende vincolare violente tempeste ad armi destinate a chi è abbastanza forte da impugnarle."},{t="Signore di Cyclonian",b="Cyclonian è un mostruoso elementale del vento tra le vette attorno a Bath'rah. Bath'rah non può sconfiggerlo da solo, quindi chiede a guerrieri e sciamani esperti di raccogliere essenze elementali esotiche ed evocare la creatura. Quando Cyclonian viene ucciso, Bath'rah ne reclama il cuore elementale. Lo usa per creare armi leggendarie di pura tempesta, rinomate in tutta Azeroth."}},faq={{q="Chi è Bath'rah il Guardiavento?",a="Bath'rah è uno sciamano troll della giungla e un armaiolo che vive isolato tra le rovine vicino alla Gola di Ventofreddo, sulle Montagne d'Alterac. Aiuta avventurieri esperti a incanalare il potere elementale nelle armi.",al={"identità di bath'rah","chi è bath'rah","storia di the windwatcher"}},{q="Perché un troll della giungla vive ad Alterac?",a="Bath'rah vive da eremita vicino alla Gola di Ventofreddo, studiando il potere elementale e aiutando avventurieri capaci a forgiare armi. Il motivo per cui ha lasciato la sua patria non è noto.",al={"perché bath'rah si trova ad alterac","troll nelle montagne d'alterac"}},{q="Cos'è Cyclonian?",a="Cyclonian è un enorme e violento elementale del vento che infesta le rovine attorno al rifugio di Bath'rah. A Bath'rah serve il suo nucleo per forgiare armi infuse di vento elementale.",al={"chi è cyclonian","cosa evoca bath'rah"}},{q="Perché i guerrieri lo cercano?",a="Guerrieri da ogni parte del mondo si recano da Bath'rah perché sa come forgiare le armi Whirlwind. Sotto la sua guida, sconfiggere Cyclonian permette di ottenere armi infuse di venti ululanti.",al={"missione del guerriero di bath'rah","tizio dell'ascia whirlwind"}},{q="Bath'rah aiuta solo i membri dell'Orda?",a="Bath'rah vive da eremita solitario, lontano dalla politica delle grandi fazioni. Si dedica all'artigianato elementale e aiuta guerrieri e sciamani capaci che rispettano gli spiriti e contribuiscono al suo lavoro con gli elementi.",al={"bath'rah è ostile","bathrah alleanza"}}},fx={["4f68ea16"]={q="Che cosa vuole Bath'rah il Guardiavento?",a="Bath'rah cerca un campione degno, capace di affrontare e sconfiggere Cyclonian, un elementale furioso che dimora vicino al suo accampamento. Desidera il cuore della creatura, nella speranza di sfruttarne la grezza energia primordiale per forgiare un'arma straordinaria e dotata di immenso potere.",al={"che cosa vuole bath'rah","che cosa vuole bathrah","obiettivo di bathrah"}}},fp="24,220,19.329.0,19.342.1,32.196.0,40.172.0,18.164.0,29.182.0,45.191.0"}
P.entries["npc:bazil-thredd"] = {n="Bazil Thredd"}
P.entries["npc:bazzalan"] = {n="Bazzalan",s="Sotto Orgrimmar, Bazzalan dirige le attività della setta della Lama Rovente nel Baratro di Fiamma Furente. Ne condivide il comando con Jergosh l'Invocatore.",h="Sotto Orgrimmar, Bazzalan dirige le attività della setta della Lama Rovente nel Baratro di Fiamma Furente.",kw={"bazzalan","cultista","jergosh","orgrimmar","baratro di fiamma furente","rfc","satiro","lama rovente"},ang={["class:Rogue"]="Come Ladro, potresti trovare particolarmente interessanti la furtività, i colpi feroci e le lame intrise di veleno di Bazzalan.",["faction:Horde"]="Bazzalan e la sua setta minacciano dal basso la roccaforte di Thrall, e l'Orda vuole eliminarli.",["race:Orc"]="Come Orco, sai quanto duramente il tuo popolo abbia lottato per sfuggire alla manipolazione demoniaca. Un satiro che dirige dei cultisti sotto la loro stessa città è un oltraggio."},sec={{t="Un Serpente Sotto la Città",b="Bazzalan comanda le forze sul campo della Lama Rovente nelle caverne di lava sotto Orgrimmar. Mentre Thrall si adopera per fondare la nuova patria degli Orchi a Durotar, il satiro ladro percorre le tortuose caverne con due lame, rapido e letale."},{t="Guida della Setta e Inganno",b="Da una sporgenza vulcanica sopra la camera centrale, Bazzalan sorveglia le guardie della setta. Sotto di lui, Jergosh l'Invocatore celebra rituali demoniaci. Come tutti i satiri, Bazzalan riserva la sua lealtà più profonda ai padroni demoniaci. Usa veleno, colpi rapidi e furtività contro gli esploratori dell'Orda che si avventurano vicino alla base operativa della setta."}},faq={{q="Chi è Bazzalan?",a="Bazzalan è un satiro ladro che condivide il comando della setta della Lama Rovente nel Baratro di Fiamma Furente, sotto Orgrimmar.",al={"storia di bazzalan","chi è bazzalan","boss satiro rfc"}},{q="Dove si può trovare Bazzalan nel Baratro di Fiamma Furente?",a="Bazzalan si nasconde sulle sporgenze superiori del Baratro di Fiamma Furente, sopra Jergosh l'Invocatore. Rampe buie scavate nelle pareti della caverna conducono fino a lui.",al={"posizione di bazzalan","dove si trova bazzalan","trova bazzalan"}},{q="Cosa ci fa un satiro sotto Orgrimmar?",a="Bazzalan serve la Lama Rovente, una setta demoniaca che cerca di minare l'Orda dall'interno. I satiri sono vincolati a poteri demoniaci e spesso fungono da istigatori e assassini per consigli oscuri.",al={"perché c'è un satiro a orgrimmar","perché bazzalan si trova a rfc"}},{q="Quali abilità usa Bazzalan in combattimento?",a="Bazzalan colpisce rapidamente con armi da mischia e usa Sinister Strike. A volte infligge agli avversari un lieve veleno debilitante.",al={"abilità di bazzalan","attacchi di bazzalan","come combatte bazzalan"}},{q="Qual è la sua relazione con Jergosh l'Invocatore?",a="Bazzalan e Jergosh condividono il comando della Lama Rovente nel Baratro di Fiamma Furente. Jergosh si occupa delle invocazioni ed evoca forze oscure, mentre Bazzalan dirige le operazioni militari e furtive della setta.",al={"jergosh e bazzalan","bazzalan è imparentato con jergosh"}},{q="Perché l'Orda vuole la morte di Bazzalan?",a="La presenza di Bazzalan nelle profondità sotto la capitale espone l'Orda a una minaccia demoniaca. I capi dell'Orda inviano avventurieri nel Baratro di Fiamma Furente per eliminarlo prima che il complotto della Lama Rovente metta in pericolo la città.",al={"taglia su bazzalan","respingi l'invasione bazzalan"}}},fx={["9fcb4f3a"]={q="Da che parte sta Bazzalan?",a="Bazzalan serve i padroni demoniaci che si celano dietro al Concilio dell'Ombra. Operando al fianco di Jergosh l'Invocatore, comanda i cultisti della Lama Rovente nascosti sotto Orgrimmar e agisce in segreto contro l'Orda e la sicurezza della città sovrastante.",al={"chi serve bazzalan","fazione di bazzalan","lealtà di bazzalan"}}},fp="8,135,26.242.0,26.327.0,16.110.0,46.128.0,40.194.0,43.134.0,48.195.0,38.205.0"}
P.entries["npc:beldin-steelgrill"] = {n="Beldin Grigliafredda",s="Allo Scalo di Grigliafredda, a Dun Morogh, Beldin Grigliafredda mantiene in funzione le macchine da guerra dei nani. In tutta Khaz Modan è rinomato come maestro tecnico e ripara macchine d'assedio e carri corazzati grazie a una fornitura costante di attrezzi specializzati.",h="Allo Scalo di Grigliafredda, a Dun Morogh, Beldin Grigliafredda mantiene in funzione le macchine da guerra...",kw={"beldin grigliafredda","dun morogh","forgiardente","kharanos","meccanico","macchina d'assedio","carro a vapore","grigliafredda"},ang={["profession:Engineering"]="Da ingegnere, puoi vedere all'opera l'arte nanica della costruzione di veicoli nel piazzale di Beldin, dove si svolge la manutenzione delle formidabili macchine da guerra dell'Alleanza.",["race:Dwarf"]="Da nano, puoi ammirare la maestria industriale di Forgiardente nel piazzale di Beldin, dove l'abilità nanica spazia dagli attrezzi manuali all'artiglieria d'assedio."},sec={{t="Signore della Bestia Cingolata",b="Poco oltre Kharanos, lungo la strada, lo Scalo di Grigliafredda collauda e revisiona carri a vapore e macchine d'assedio. Il lavoro su metallo e caldaie rombanti mette a dura prova chiavi pesanti, tronchesi e strumenti di precisione. Beldin ha costantemente bisogno di ricambi e tiene occupati i fabbri locali per rifornire il suo banco da lavoro."}},faq={{q="Chi è Beldin Grigliafredda?",a="Beldin Grigliafredda gestisce lo Scalo di Grigliafredda a Dun Morogh in qualità di proprietario e maestro tecnico. In tutta Khaz Modan è celebre per la manutenzione delle macchine d'assedio e dei carri da guerra dei nani.",al={"beldin grigliafredda","chi è beldin","meccanico di carri dun morogh"}},{q="Cosa succede allo Scalo di Grigliafredda?",a="Poco a nord-est di Kharanos, lo Scalo di Grigliafredda è un piazzale dove l'Alleanza collauda e mantiene carri a vapore e pesanti macchine meccanizzate.",al={"scalo di grigliafredda","cos'è lo scalo di grigliafredda","scopo dello scalo"}},{q="Perché Beldin consuma così tanti attrezzi?",a="Il lavoro di Beldin su corazze pesanti, ingranaggi complessi e caldaie a vapore consuma rapidamente gli attrezzi specializzati. I fabbri dei dintorni soddisfano i suoi esigenti ordini e mantengono rifornito il suo banco da lavoro.",al={"perché ha bisogno di attrezzi","attrezzi di grigliafredda","attrezzi per grigliafredda"}}},fx={c08b01c8={q="Da che parte sta Beldin Grigliafredda?",a="Beldin è fedele al clan Barbabronzea di Forgiardente e sostiene saldamente l'Alleanza. Lavorando poco fuori Kharanos, equipaggia l'esercito dei nani e le forze di difesa locali con pesanti armature meccanizzate e macchine d'assedio.",al={"fazione di beldin grigliafredda","chi serve beldin","beldin grigliafredda è dell'alleanza"}},["940fd3ae"]={q="Perché Beldin Grigliafredda è famoso?",a="Beldin è rinomato in tutto Dun Morogh come il miglior tecnico di macchine d'assedio ancora in vita. La sua maestria nelle macchine da guerra e nella meccanica pesante gli ha procurato una reputazione senza pari tra gli ingegneri nani, ma lo rende anche notoriamente esigente con gli artigiani locali.",al={"reputazione di beldin grigliafredda","perché beldin è famoso","miglior tecnico di macchine d'assedio"}}},fp="17,234,27.289.0,25.181.0,35.138.0,41.172.0"}
P.entries["npc:bethor-iceshard"] = {n="Bethor Scheggiafredda",s="A Sepulcra, Bethor Scheggiafredda dirige i praticanti delle arti arcane e dell'ombra del Magic Quarter. Detiene autorità nel regno di Sylvanas, ma il suo passato resta segnato da antiche amicizie.",h="A Sepulcra, Bethor Scheggiafredda dirige i praticanti delle arti arcane e dell'ombra del Magic Quarter.",kw={"bethor scheggiafredda","reietti","gunther arcanus","magic quarter","prodigal lich","temple of the damned","thule ravenclaw","sepulcra"},ang={["class:Mage"]="Come mago dei Reietti, puoi vedere in Bethor Scheggiafredda come le arti arcane perdurino nella non morte.",["faction:Horde"]="Come membro dell'Orda, trai beneficio dalla magia offensiva di Bethor Scheggiafredda e dai suoi sforzi contro la negromanzia, che proteggono la presenza dell'Orda in tutta Lordaeron.",["race:Undead"]="Come Non Morto, potresti conoscere il dolore di perdere amici e casa a causa del Flagello, per poi affrontare i vecchi alleati come nemici."},sec={{t="Signore del Magic Quarter",b="Dal Temple of the Damned di Sepulcra, Bethor Scheggiafredda dirige i praticanti delle arti arcane e dell'ombra. La sua mente acuta e la sua gelida determinazione suscitano rispetto e timore. La sua autorità politica e magica si estende ai magistrati di tutta Lordaeron. Invia agenti dei Reietti alla ricerca di preziosi grimori e anomalie arcane, e contro potenze rivali che minacciano il dominio di Sepulcra."},{t="Vecchi amici e agrodolci ricongiungimenti",b="Bethor Scheggiafredda cerca potenti incantatori non morti a Tirisfal e Silverpine. Invia agenti per scoprire se i praticanti rinnegati servano il Re dei Lich o possano unirsi ai Reietti. Al Lago di Acqualucente, trova Gunther Arcanus intento a risvegliare i morti e cerca pazientemente di portare il vecchio amico tra i seguaci di Dama Sylvanas. Thule Ravenclaw non riceve la stessa pietà. Il suo tradimento volontario ha condannato la loro fratellanza."},{t="Legami di apprendistato",b="Prima che la Terza Guerra devastasse Lordaeron, Bethor Scheggiafredda studiava magia come apprendista mortale al fianco di Gunther Arcanus e Thule Ravenclaw. I tre erano compagni affiatati e intrecciarono le loro bacchette da addestramento per suggellare il loro legame. Poi il Flagello travolse il regno con la morte e la magia oscura. Thule cedette volontariamente la propria anima al Re dei Lich. Gunther perì e risorse su un'isola isolata nel Lago di Acqualucente. Anche Bethor cadde, poi si liberò e divenne un Reietto."}},faq={{q="Chi è Bethor Scheggiafredda?",a="Bethor Scheggiafredda dirige i praticanti delle arti arcane e dell'ombra presso il Temple of the Damned, nel Magic Quarter di Sepulcra. Guida la ricerca magica, raccoglie informazioni sui praticanti rinnegati e sovrintende alle operazioni arcane segrete per la Dark Lady.",al={"bethor scheggiafredda","chi è bethor","storia di bethor"}},{q="Dove si trova Bethor Scheggiafredda?",a="Bethor Scheggiafredda risiede all'interno del Temple of the Damned, nel Magic Quarter di Sepulcra.",al={"dove si trova bethor","posizione di bethor","trova bethor scheggiafredda"}},{q="Qual è la storia di Bethor con Gunther Arcanus?",a="Bethor Scheggiafredda e Gunther Arcanus erano amici intimi e compagni di apprendistato magico a Lordaeron. Entrambi morirono durante l'invasione del Flagello, poi si liberarono dal controllo del Re dei Lich. Bethor fece in modo che Gunther si unisse ai Reietti.",al={"gunther e bethor","amicizia con gunther arcanus","come conosce bethor gunther"}},{q="Chi era Thule Ravenclaw per Bethor?",a="Thule Ravenclaw era il terzo membro della cerchia di apprendisti di Bethor Scheggiafredda e Gunther Arcanus. Durante l'invasione del Flagello, offrì volontariamente la propria anima al Re dei Lich e divenne un odiato negromante che viveva sull'Isola di Fenris.",al={"legame con thule ravenclaw","thule e bethor","bethor ravenclaw"}},{q="Qual è la storia dietro la bacchetta di Bethor?",a="Da giovani apprendisti, Bethor Scheggiafredda, Gunther Arcanus e Thule Ravenclaw intrecciarono le loro bacchette da addestramento in segno di eterna amicizia. Quel ricordo intrecciato lega i tre incantatori ormai divisi al loro passato mortale.",al={"bacchetta intrecciata","wand to bethor","bacchetta da apprendista di bethor"}},{q="Quale ruolo svolge Bethor nella società dei Reietti?",a="Bethor Scheggiafredda è una delle principali autorità arcane di Sepulcra. Guida maghi e stregoni appena risorti, dirige la raccolta di informazioni sui negromanti rinnegati e ha autorità sui funzionari regionali dei Reietti, come il Magistrato Sevren.",al={"ruolo di bethor","cosa fa bethor","autorità di bethor"}}},fx={["31504eb7"]={q="Da che parte sta Bethor Scheggiafredda?",a="Bethor è completamente devoto a Lady Sylvanas Ventolesto e ai Reietti. Dal suo sanctum nel Quartiere della Magia di Sepulcra, esercita una notevole autorità nella gerarchia dei Reietti, dirige gli incantatori arcani e mobilita risorse contro il Flagello e le altre minacce al suo popolo.",al={"fazione di bethor scheggiafredda","lealtà di bethor scheggiafredda","chi serve bethor"}},["14082dd0"]={q="Che cosa vuole Bethor Scheggiafredda?",a="Bethor desidera rafforzare il potere arcano dei Reietti e proteggere il loro giovane regno. Questo comporta reclutare alla causa dei Reietti incantatori dotati come il suo ex amico Gunther Arcanus, affrontando senza pietà il Flagello e chiedendo conto a traditori come Thule Ravenclaw di aver venduto l'anima al Re dei Lich.",al={"obiettivi di bethor scheggiafredda","che cosa vuole bethor","motivazioni di bethor scheggiafredda"}},["50a70545"]={q="Perché Bethor Scheggiafredda si trova a Sepulcra?",a="Bethor presiede al Tempio dei Dannati nel Quartiere della Magia di Sepulcra e guida i maghi e gli stregoni dei Reietti. È qui per coordinare gli affari arcani, guidare gli incantatori promettenti e organizzare le iniziative strategiche in tutta Lordaeron, dal cuore della capitale.",al={"perché bethor è a sepulcra","luogo e storia di bethor scheggiafredda","perché bethor si trova qui"}}},fp="15,178,27.367.0,36.401.1,23.480.1,23.247.0,35.89.0,46.231.1,34.226.1,39.225.0,47.234.0"}
P.entries["npc:billy-maclure"] = {n="Billy Maclure",s="Alle Vigne dei Maclure, gli scherzi di Billy Maclure creano scompiglio tra due fattorie vicine. Il ragazzino umano schiva le faccende e partecipa alla faida tra la sua famiglia e i Pietradura, ma i dolci appena sfornati possono convincerlo ad aiutare.",h="Alle Vigne dei Maclure, gli scherzi di Billy Maclure creano scompiglio tra due fattorie vicine.",kw={"bernice stonefield","billy maclure","miniera antrocupo","dented'oro","collana perduta","vigne dei maclure","pasticcio di carne di cinghiale","stonefield"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza appena arrivato dalla Contea del Nord, aiutare Billy con i suoi scherzi ti fa conoscere i pericoli della Miniera Antrocupo.",["profession:Cooking"]="Da cuoco, puoi vedere come il Pasticcio di Carne di Cinghiale di zia Bernice aiuti a risolvere dispute locali e ottenere confessioni dai reticenti ragazzini delle fattorie.",["race:Human"]="Da umano, nelle disavventure di Billy puoi vedere i litigi quotidiani della campagna di Elwynn. Le faide tra fattorie e le marachelle infantili continuano tra i tumulti politici di Roccavento."},sec={{t="Un ragazzo alle vigne",b="Billy Maclure trascorre le giornate fuori dal fienile delle Vigne dei Maclure, vicino al contadino Gerard Tiller. Cresce tra i filari della Foresta di Elwynn meridionale, sottraendosi spesso alle faccende per scorrazzare nei prati. I Maclure e i Pietradura sono ostili da tempo. Billy trasforma la loro faida in un'occasione per scherzi e piccoli furti."},{t="La collana rubata",b="Billy Maclure ha rubato la preziosa collana di famiglia di zia Bernice Stonefield. Gli è sfuggita di mano mentre correva vicino alla Miniera Antrocupo. Goldtooth, un coboldo enorme e feroce, ha afferrato la collana ed è scomparso nelle gallerie della miniera. Billy teme i coboldi e l'ira degli anziani vicini, quindi esita a confessare. Il Pasticcio di Carne di Cinghiale caldo di zia Bernice può convincerlo a dire la verità."}},faq={{q="Chi è Billy Maclure?",a="Billy Maclure è un ragazzino umano che vive alle Vigne dei Maclure, nella Foresta di Elwynn. Schiva il lavoro nei campi, fa scherzi e esaspera i vicini Pietradura.",al={"chi è billy","storia di billy maclure","ragazzo maclure"}},{q="Dove si può trovare Billy Maclure?",a="Billy aspetta fuori dal fienile principale delle Vigne dei Maclure, nella Foresta di Elwynn meridionale, a est della Fattoria dei Pietradura.",al={"posizione di billy maclure","dove si trova billy","trova billy maclure"}},{q="Cosa ha fatto Billy a zia Bernice?",a="Billy ha rubato la collana di famiglia di zia Bernice Stonefield durante la faida tra le loro famiglie.",al={"collana di bernice","cosa ha rubato billy","collana rubata elwynn"}},{q="Cosa è successo alla collana rubata da Billy?",a="Billy ha perso la collana vicino alla Miniera Antrocupo. Goldtooth l'ha raccolta e portata nella miniera.",al={"dov'è la collana","collana perduta elwynn","chi ha la collana di bernice"}},{q="Come si convince Billy a confessare cosa è successo alla collana?",a="Offri a Billy un Pasticcio di Carne di Cinghiale appena sfornato da zia Bernice. Il suo appetito può convincerlo a confessare.",al={"pasticcio per billy","come corrompere billy","corrompere billy maclure"}},{q="Chi è Goldtooth?",a="Goldtooth è un capocoboldo eccezionalmente grande e feroce che si trova nella Miniera Antrocupo. Ha preso la collana di zia Bernice vicino all'ingresso della miniera e la custodisce nelle gallerie.",al={"chi è dented'oro","storia di dented'oro","coboldo di antrocupo"}}},fx={["324ac528"]={q="Da che parte sta Billy Maclure?",a="Billy è un membro leale della famiglia Maclure nella Foresta di Elwynn e sostiene fermamente il Regno di Roccavento e l'Alleanza. La sua famiglia è coinvolta in un'aspra faida di lunga data con i vicini Pietradura, ma Billy è ancora soltanto un ragazzino, stretto tra i rancori familiari e il proprio appetito.",al={"fazione di billy maclure","da che parte sta billy","chi sostiene billy"}},c9c2f9db={q="Che cosa vuole Billy Maclure?",a="Billy non vuole granché, se non evitare guai e soddisfare il proprio appetito. Più di ogni altra cosa, desidera le famose torte di pancetta di maiale di zia Bernice Pietradura, nonostante l'accesa rivalità tra le loro famiglie. È persino disposto a confessare le sue marachelle, se qualcuno gli porta una delle sue torte appena sfornate e saporite.",al={"che cosa vuole billy","che cosa desidera billy maclure","cibo preferito di billy maclure"}},f69aaa51={q="Perché Billy Maclure si trova qui?",a="Billy vive alle Vigne dei Maclure, la casa e fonte di sostentamento della sua famiglia nella Foresta di Elwynn. Passa le giornate a bighellonare fuori dal fienile, vicino a Gerard Tiller, a sbrigare commissioni e a giocare nei dintorni, quando non sgattaiola verso la vicina fattoria dei Pietradura.",al={"perché billy maclure si trova qui","perché billy è alle vigne dei maclure","che cosa fa billy qui"}},["275e906f"]={q="A chi è legato Billy Maclure?",a="Billy fa parte della famiglia di contadini Maclure e vive alle vigne con i suoi parenti e lavoratori come Gerard Tiller. Con le sue marachelle è anche strettamente coinvolto con la famiglia rivale dei Pietradura, in particolare con zia Bernice Pietradura, a cui ha rubato la collana più preziosa e di cui ama in segreto i dolci.",al={"famiglia di billy maclure","con chi è imparentato billy maclure","legami di billy maclure"}}},fp="13,221,22.344.0,19.383.1,21.152.0,33.106.0,36.97.0,42.97.1,62.101.1,17.166.1"}
P.entries["npc:bingles-blastenheimer"] = {n="Bingles Scoppiamicce",s="Sulla riva sudorientale di Loch Modan, Bingles Scoppiamicce attende accanto al relitto della sua Macchina Volante. Bloccato tra trogg e bestie, l'aviatore gnomico ha bisogno di recuperare i suoi attrezzi e componenti.",h="Sulla riva sudorientale di Loch Modan, Bingles Scoppiamicce attende accanto al relitto della sua Macchina...",kw={"bingles","scoppiamicce","gnomo","girocottero","loch modan","pilota"},ang={["profession:Engineering"]="Come ingegnere, sai quanto sia un problema perdere chiavi personalizzate e congegni per colpa dei trogg dopo un volo finito male.",["race:Gnome"]="Come gnomo, condividi il desiderio di Bingles di portare le invenzioni gnomiche nei cieli, anche quando un guasto meccanico causa un brusco atterraggio."},sec={{t="Un atterraggio brusco",b="Bingles Scoppiamicce ha preso il volo con il suo velivolo personalizzato, ma l'atterraggio è andato male. Il suo girocottero ha subito un guasto e si è schiantato sulla riva sudorientale di Loch Modan. Bingles è sopravvissuto, ma la macchina è andata in pezzi. Lontano da Forgiardente, rimane vicino al relitto, in guardia contro crocolischi affamati e trogg ostili. I trogg di un'isola vicina gli hanno rubato gli attrezzi e gli esplosivi Blastencapper, così chiede ai viaggiatori di passaggio di recuperarli."}},faq={{q="Chi è Bingles Scoppiamicce?",a="Bingles Scoppiamicce è un pilota e inventore gnomico, rimasto bloccato dopo lo schianto della sua Macchina Volante sulla riva sudorientale di Loch Modan.",al={"chi è bingles","storia di bingles scoppiamicce","chi è lo gnomo vicino al lago"}},{q="Cosa è successo alla sua Macchina Volante?",a="Bingles si è schiantato con il suo girocottero nel Loch. I trogg di un'isola vicina lo hanno attaccato e gli hanno rubato gli attrezzi e gli esplosivi Blastencapper.",al={"perché bingles si è schiantato","girocottero di bingles","cosa è successo all'aereo di bingles"}},{q="Perché Bingles non è tornato in città?",a="Bingles è bloccato senza il suo girocottero, e i trogg di un'isola vicina gli hanno rubato gli attrezzi e gli esplosivi Blastencapper. Vuole recuperarli per il movimento che mira a riconquistare Gnomeregan, così attende accanto al relitto che qualcuno glieli riporti.",al={"perché bingles è bloccato","perché restare vicino al lago"}},{q="Dove finisce Bingles dopo che il suo velivolo viene riparato?",a="Bingles rimane al Punto d'Impatto sulla riva sudorientale del Loch, in attesa che i viaggiatori recuperino le sue provviste scomparse.",al={"dove va bingles","rifugio di bingles"}}},fx={["1e141199"]={q="Da che parte sta Bingles Scoppiamicce?",a="Bingles è uno gnomo leale, schierato con Gnomeregan e l'Alleanza. Conta sui viaggiatori dell'Alleanza per recuperare il suo equipaggiamento perduto e sopravvivere nelle terre selvagge del Loch Modan.",al={"fazione di bingles scoppiamicce","bingles è dell'alleanza","per chi lavora bინგles"}},["89c66e03"]={q="Perché Bingles Scoppiamicce si trova qui?",a="Bingles stava sorvolando il Loch Modan sul suo adorato girocottero quando si è verificato un disastro. La sua Macchina Volante si è schiantata sulle rive del lago, lasciandolo bloccato e isolato tra le bestie pericolose e i trogg ostili che infestano le terre selvagge.",al={"perché bინგles è nel loch modan","come è arrivato qui bინგles","incidente di bინგles scoppiamicce"}}},fp="21,191,15.438.0,29.134.0,36.136.0,36.233.0,51.124.1"}
P.entries["npc:bink"] = {n="Bink",s="Nella Hall of Mysteries di Forgiardente, Bink insegna agli aspiranti maghi le arti arcane. La sua mente brillante aiuta gli studenti promettenti a trovare maghi in tutta l'Alleanza.",h="Nella Hall of Mysteries di Forgiardente, Bink insegna agli aspiranti maghi le arti arcane.",kw={"andromath","bink","gnomo","hall of mysteries","forgiardente","istruttore dei maghi","guardia mistica","tabetha"},ang={["class:Mage"]="Come mago dell'Alleanza a Forgiardente, puoi imparare da Bink e seguire le sue indicazioni per raggiungere potenti mentori in tutta Azeroth.",["race:Gnome"]="Come gnomo, condividi con Bink la ricerca della maestria arcana tra gli esuli che hanno trovato rifugio nelle sale dei loro alleati nani."},sec={{t="Un Faro nella Hall of Mysteries",b="Nella Hall of Mysteries di Forgiardente, Bink insegna la via del mago. Lavora tra gli studiosi, i sacerdoti e gli arcanisti riuniti nella Guardia Mistica. Come molti gnomi scacciati da Gnomeregan, ha trovato casa nella roccaforte montana dei nani. La sua mente acuta e la sua abilità nelle arti arcane guidano chi apprende la magia.\n\nBink conosce maghi in tutti i Regni Orientali e a Kalimdor. Indirizza gli apprendisti promettenti verso mentori come High Sorcerer Andromath a Roccavento e Tabetha ad Acquemorte."}},faq={{q="Chi è Bink?",a="Bink addestra i maghi gnomi dell'Alleanza nella Hall of Mysteries di Forgiardente. Insegna l'arte degli incantesimi arcani e guida i maghi nel loro percorso di crescita.",al={"bink lore","chi è bink","bink forgiardente"}},{q="Dove posso trovare Bink?",a="Puoi trovare Bink nella Hall of Mysteries, nell'ala occidentale della Guardia Mistica di Forgiardente.",al={"posizione di bink","dove si trova bink","trova bink"}},{q="Quali missioni coinvolgono Bink?",a="La missione Speak with Bink indirizza i maghi in formazione da Bink. Lei li manda a studiare con esperti come High Sorcerer Andromath nel Santuario della Magia di Roccavento o la maga eremita Tabetha ad Acquemorte.",al={"missioni di bink","missione speak with bink"}},{q="Cosa dice Bink a chi non è un mago?",a="Se non pratichi le arti arcane, Bink ti consiglia allegramente: «Fa' amicizia con un mago! Abbiamo un trucco o due nella manica, noi...»",al={"dialoghi di bink","dialogo di bink"}}},fx={cf09b30e={q="Da che parte sta Bink?",a="Bink sostiene saldamente l'Alleanza e gli Esuli di Gnomeregan accolti a Forgiardente. Lavora nella Hall of Mysteries insieme ad altri studiosi e stregoni, mettendo i suoi talenti magici al servizio degli alleati e istruendo nuovi maghi promettenti che combattono sotto il vessillo dell'Alleanza.",al={"fazione di bink","chi serve bink","bink è dell'alleanza o dell'orda"}},d0de8b26={q="Perché Bink si trova nella Hall of Mysteries?",a="Bink vive nella Hall of Mysteries di Forgiardente e fa da maestra ai maghi gnomi. Dopo la caduta di Gnomeregan, gli gnomi sfollati trovarono rifugio presso i nani Barbabronzea; Bink mette la sua competenza arcana a disposizione di chi aspira a diventare mago e assegna agli allievi incarichi importanti per la comunità arcana.",al={"perché bink si trova qui","che cosa fa bink a forgiardente","perché bink è a forgiardente"}}},fp="4,152,33.505.0,12.130.0,22.91.0,25.210.0,32.126.0"}
P.entries["npc:bishop-delavey"] = {n="Vescovo DeLavey",s="Nel Forte di Roccavento, il Vescovo DeLavey ascolta le preoccupazioni sussurrate a corte. Rappresenta la Chiesa della Sacra Luce nella Petitioner's Chamber, dove si incontrano questioni di fede e di stato.",h="Nel Forte di Roccavento, il Vescovo DeLavey ascolta le preoccupazioni sussurrate a corte.",kw={"vescovo delavey","delavey","elling trias","sacra luce","jorgen","diplomatico scomparso","petitioner's chamber","forte di roccavento"},ang={["class:Priest"]="Come sacerdote, puoi vedere quanto la Chiesa della Sacra Luce sia coinvolta nella politica di Roccavento, dove la fede incontra l'arte di governo e gli affari segreti.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come l'indagine discreta di DeLavey protegga la fragile pace tra Roccavento e Theramore, l'avamposto di Dama Jaina Marefiero."},sec={{t="Un vescovo a corte",b="Il Vescovo DeLavey consiglia la corte di Roccavento dall'interno del forte. Mentre l'Arcivescovo Benedictus si occupa della Cathedral of Light, DeLavey vive tra nobili e postulanti. Offre consiglio spirituale mentre si confronta con la politica del regno. Dalla sua posizione a corte, ascolta voci sussurrate e delicate rimostranze prima che raggiungano il Gran Signore Bolvar Domadraghi o il giovane Re Anduin."},{t="Un'indagine delicata",b="Un diplomatico scomparso ha coinvolto il Vescovo DeLavey in un'indagine segreta. Il diplomatico era stato inviato a incontrare Dama Jaina Marefiero a Theramore, ma non è mai arrivato. Per evitare il panico, la corte tiene segreta la scomparsa. Sospettando della Fratellanza dei Defias, DeLavey aggira i consueti canali delle guardie. Si affida a contatti privati e avventurieri discreti, tra cui il pescatore Jorgen, per raggiungere informatori segreti come Elling Trias."}},faq={{q="Dove si trova il Vescovo DeLavey?",a="Puoi trovare il Vescovo DeLavey nella Petitioner's Chamber all'interno del Forte di Roccavento, accanto all'ingresso principale dove i sudditi si radunano per presentare petizioni alla corte reale.",al={"posizione di delavey","dove si trova il vescovo delavey","delavey forte"}},{q="Qual è il suo ruolo nel Forte di Roccavento?",a="Il Vescovo DeLavey rappresenta la Chiesa della Sacra Luce alla corte reale di Roccavento. Gestisce gli affari della Chiesa, consiglia la nobiltà e si occupa con discrezione di questioni delicate per il regno.",al={"ruolo di delavey","chi è il vescovo delavey","cosa fa delavey"}},{q="Perché sta indagando sul diplomatico scomparso?",a="Il diplomatico è svanito mentre era in viaggio per incontrare Dama Jaina Marefiero a Theramore. Il Vescovo DeLavey sospetta un'interferenza dei Defias e indaga attraverso canali fidati per evitare che la crisi allarmi la popolazione.",al={"diplomatico scomparso delavey","perché delavey si occupa del diplomatico"}},{q="In che modo DeLavey è collegato a Elling Trias?",a="Il Vescovo DeLavey trasmette messaggi a Elling Trias tramite intermediari, tra cui il pescatore Jorgen. Trias è un maestro casaro che raccoglie segretamente informazioni per l'SI:7.",al={"delavey e trias","contatto si:7 di delavey"}}},fx={["9f3cf19d"]={q="Chi è il Vescovo DeLavey?",a="Il Vescovo DeLavey è un alto prelato umano della Chiesa della Luce Sacra, assegnato al Forte di Roccavento. In qualità di emissario ufficiale della Chiesa presso la corte reale, si occupa delle questioni clericali e amministrative tra la nobiltà e la reggenza.",al={"chi è delavey","identità del vescovo delavey","chi è il vescovo delavey"}},["8f5e30a8"]={q="Da che parte sta il Vescovo DeLavey?",a="DeLavey è pienamente leale alla Chiesa della Luce Sacra e alla Grande Alleanza di Roccavento. Agisce direttamente nell'interesse del regno, cercando di proteggere la corona e di districare in segreto le minacce al regno prima che il panico si diffonda per le strade.",al={"fazione di delavey","il vescovo delavey è dell'alleanza","chi serve il vescovo delavey"}},["663bbb38"]={q="Che cosa vuole il Vescovo DeLavey?",a="DeLavey vuole scoprire la verità dietro la scomparsa di un diplomatico di Roccavento di vitale importanza, inviato a Theramore. Poiché la notizia della scomparsa potrebbe destabilizzare la corte, intende indagare con discrezione tramite terze parti fidate e canali di intelligence riservati.",al={"cosa cerca di fare delavey","obiettivi del vescovo delavey","cosa vuole delavey"}},["44aea1e7"]={q="Perché il Vescovo DeLavey si trova nel Forte di Roccavento?",a="DeLavey risiede nella Petitioner's Chamber per rappresentare la Chiesa della Luce Sacra davanti al Gran Signore Bolvar Domadraghi e alla corte reale. Da questa posizione, consiglia la corona sugli affari della Chiesa e resta vicino alle manovre politiche del regno.",al={"perché delavey è nel forte","perché il vescovo delavey è qui","delavey nella petitioner's chamber"}}},fp="14,183,17.380.0,18.424.1,34.156.0,35.187.0,45.212.0,41.174.1"}
P.entries["npc:blanchy"] = {n="Blanchy",s="Vicino alla Cascina dei Jansen, Blanchy riposa accanto al carro dei Ciglioarcuato nelle Marche Occidentali. La docile giumenta attraversa quelle campagne travagliate insieme a Theodore e Verna Ciglioarcuato.",h="Vicino alla Cascina dei Jansen, Blanchy riposa accanto al carro dei Ciglioarcuato nelle Marche Occidentali.",kw={"blanchy","furlbrow","cascina dei jansen","avena","vecchia blanchy","verna ciglioarcuato","marche occidentali"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza diretto a sud dalla Foresta di Elwynn verso le Marche Occidentali, potresti aiutare a nutrire la Vecchia Blanchy tra i tuoi primi gesti di gentilezza verso i rifugiati locali in difficoltà."},sec={{t="Una fedele bracciante",b="Prima di trainare il carro dei Ciglioarcuato attraverso le Marche Occidentali, Blanchy lavorava nella loro fattoria nel granaio di Roccavento. Era docile e nota per il suo buon comportamento. Anni di duro lavoro l'hanno logorata, e il viaggio per allontanarsi dai poderi in difficoltà l'ha lasciata esausta. Eppure il suo appetito resta robusto. Verna offre la preziosa coperta e la sacca per la biada di Blanchy ai viaggiatori che portano nutrienti manciate d'avena dai campi vicini."}},faq={{q="A chi appartiene Blanchy?",a="Theodore e Verna Ciglioarcuato sono i proprietari di Blanchy e viaggiano attraverso le Marche Occidentali. È il loro cavallo da tiro e la loro amata compagna.",al={"proprietario di blanchy","a chi appartiene blanchy","cavallo dei furlbrow"}},{q="Da dove proviene originariamente Blanchy?",a="Nessun documento indica dove sia nata Blanchy. Per quanto ne sappia la gente delle Marche Occidentali, appartiene da molto tempo ai Ciglioarcuato e lavorava nella loro fattoria finché la famiglia non ha dovuto mettersi in viaggio.",al={"origini di blanchy","da dove viene blanchy","giovane blanchy"}},{q="Perché Verna Ciglioarcuato ha bisogno di avena per Blanchy?",a="Anni di lavoro e il lungo viaggio lungo le pericolose strade delle Marche Occidentali hanno sfinito la Vecchia Blanchy. Verna chiede ai viaggiatori di raccogliere i sacchi d'avena rimasti nei terreni agricoli vicini per far recuperare le forze alla giumenta.",al={"avena per blanchy","perche nutrire blanchy","cavallo dei furlbrow stanco"}},{q="Dove si può trovare Blanchy?",a="La Vecchia Blanchy si trova attaccata accanto al carro dei Ciglioarcuato lungo la strada principale vicino alla Cascina dei Jansen, nella parte settentrionale delle Marche Occidentali.",al={"posizione di blanchy","dove si trova la vecchia blanchy","mappa di blanchy"}}},fp="7,170,19.436.0,17.122.0,39.180.0,46.211.0,27.116.0"}
P.entries["npc:blind-hunter"] = {n="Cacciatore Cieco",s="Nelle profondità delle Gallerie di Lamaspina, il Cacciatore Cieco si annida oltre i comuni pipistrelli. Questo pallido pipistrello albino si aggira nel ridotto dei verrospini, lontano dagli ingressi delle caverne.",h="Nelle profondità delle Gallerie di Lamaspina, il Cacciatore Cieco si annida oltre i comuni pipistrelli.",kw={"pipistrello albino","cacciatore cieco","pipistrello di kraul","bestia di kraul","pipistrello raro","gallerie di lamaspina"},ang={["class:Hunter"]="Come maestro delle bestie che attraversa le Savane, potresti apprezzare il Cacciatore Cieco come rara bestia albina da addomesticare o come fonte di archi sotterranei di pregiata fattura."},sec={{t="Profondità delle Gallerie",b="Le Gallerie di Lamaspina serpeggiano tra rovi e oscure caverne sotterranee. I comuni pipistrelli si annidano più vicino alla superficie, dove una debole luce filtra dall'esterno. Il Cacciatore Cieco predilige gli anfratti più remoti e bui del groviglio. La sua pelle pallida e lo sguardo lattiginoso potrebbero derivare da generazioni trascorse lontano dalla luce naturale del sole."},{t="Una preda rara",b="Si ritiene che il Cacciatore Cieco abbia perso gran parte della vista ordinaria, se non tutta. Studiosi ed esploratori credono che rintracci le prede nell'oscurità grazie a un udito acuto e all'ecolocalizzazione. Si mostra raramente, cacciando solo di tanto in tanto tra i fitti rovi. Per chi esplora le caverne, avvistare questa bestia fantasma è un evento raro."}},faq={{q="Cos'è il Cacciatore Cieco?",a="Il Cacciatore Cieco è un raro pipistrello albino nei cunicoli più profondi e bui delle Gallerie di Lamaspina. Il colore pallido e le abitudini elusive lo distinguono dai comuni pipistrelli che vivono più vicino all'ingresso.",al={"chi è il cacciatore cieco","cos'è il cacciatore cieco","pipistrello cacciatore cieco"}},{q="Dove appare il Cacciatore Cieco?",a="Il Cacciatore Cieco si annida lungo i sentieri interni e ombrosi delle Gallerie di Lamaspina, oltre il punto in cui svanisce la luce del giorno proveniente dall'esterno.",al={"posizione del cacciatore cieco","dove trovare il cacciatore cieco","generazione del cacciatore cieco"}},{q="Il Cacciatore Cieco è davvero cieco?",a="Naturalisti e avventurieri sospettano che il Cacciatore Cieco sia privo della vista, dati i suoi occhi lattiginosi e la dimora nelle caverne profonde. Resta un abile cacciatore, guidato da un udito acuto e dall'ecolocalizzazione.",al={"è cieco","il cacciatore cieco ci vede"}},{q="I cacciatori possono addomesticare il Cacciatore Cieco?",a="Sì. I maestri delle bestie capaci di gestire i predatori alati possono addomesticare il Cacciatore Cieco, un caratteristico compagno pallido per chi ha la pazienza di trovarlo.",al={"posso addomesticare il cacciatore cieco","cacciatore cieco addomesticabile","famiglio cacciatore cieco"}},{q="Perché il Cacciatore Cieco è bianco?",a="Il Cacciatore Cieco è un pipistrello albino. La sua colorazione potrebbe essersi sviluppata nell'oscurità perpetua, lontano dal sole, a differenza dei pipistrelli che si avventurano vicino all'imboccatura della caverna.",al={"perché è albino","perché il cacciatore cieco è bianco","pipistrello albino"}},{q="In che cosa differisce dai normali pipistrelli delle Gallerie?",a="I comuni pipistrelli delle Gallerie hanno la tipica colorazione scura e vivono più vicino all'ingresso, dove arriva ancora la luce. Il Cacciatore Cieco è pallido, schivo e adattato ai cunicoli profondi.",al={"differenza pipistrello di kraul","pipistrello di kraul contro cacciatore cieco"}}},fx={["7be10a10"]={q="Da che parte sta il Cacciatore Cieco?",a="Il Cacciatore Cieco è una bestia selvaggia che non è alleata né con i quilboar di Lamaspina né con alcuna potenza esterna. È un predatore dominante delle caverne nerissime delle Gallerie di Lamaspina, sopravvive soltanto grazie all'istinto animale e considera potenziali prede tutti gli intrusi.",al={"fazione del cacciatore cieco","il cacciatore cieco è con i quilboar","da che parte sta il cacciatore cieco"}},["5a3f492c"]={q="Che cosa vuole il Cacciatore Cieco?",a="Essendo una creatura sotterranea indomita, il Cacciatore Cieco non nutre ambizioni politiche né malizia. Caccia semplicemente per nutrirsi e difende il suo territorio di caccia isolato, nelle caverne più profonde e buie delle Gallerie, da chiunque sia tanto sfortunato da imbattersi nella sua tana.",al={"motivazioni del cacciatore cieco","obiettivi del cacciatore cieco","cosa vuole il cacciatore cieco"}},["66c6306f"]={q="Perché il Cacciatore Cieco si trova qui?",a="A differenza dei comuni pipistrelli delle Gallerie, che svolazzano vicino all'ingresso dove filtra la luce del sole, il Cacciatore Cieco vive nelle profondità più remote e nerissime delle Gallerie di Lamaspina. Avendo vissuto nell'oscurità perpetua, prospera nei recessi molto più in basso, dove non ha mai visto la luce.",al={"perché il cacciatore cieco è a lamaspina","perché si trova lì il cacciatore cieco","perché il cacciatore cieco è qui"}}},fp="12,170,19.305.0,13.302.0,25.175.0,35.123.0,35.171.0,34.142.0,30.153.0,43.171.0"}
P.entries["npc:blind-mary"] = {n="Mary la Cieca",s="In una fattoria in rovina a sud-est di Borgoscuro, Mary la Cieca vaga come una banshee tormentata. Un tempo donna bella e vanitosa, fu uccisa quando i non morti invasero Boscovespro e risorse in una forma che non poteva sopportare.",h="In una fattoria in rovina a sud-est di Borgoscuro, Mary la Cieca vaga come una banshee tormentata.",kw={"banshee","mary la cieca","borgoscuro","boscovespro","capelli spettrali","ritrovo","specchio","spettro"},ang={["class:Priest"]="Come sacerdote, puoi vedere in Mary un'anima privata di ogni legame da un trauma atroce, intrappolata tra la vita e la dannazione dal dolore e dalla vanità.",["faction:Alliance"]="Come difensore dell'Alleanza, puoi vedere nel destino di Mary quanto profondamente la maledizione di Boscovespro abbia devastato la gente comune del luogo.",["profession:Tailoring"]="Come sarto, potresti cercare esseri spettrali come Mary per ottenere il Filo di Capelli Spettrali, un materiale delicato tessuto da resti eterei."},sec={{t="Una tragica vanità",b="Prima che le ombre calassero su Boscovespro, Mary era nota per la sua bellezza. Ne andava molto fiera e raramente si separava dal suo prezioso specchio. Quando i non morti invasero la regione, Mary e molti dei suoi vicini furono uccisi. Il suo spirito non trovò riposo nella terra. Divenne una banshee eterea, condannata a vagare nel regno dei mortali in una forma spaventosa e traslucida."},{t="Accecata dalla disperazione",b="Dolore, orrore e furia sopraffecero Mary quando si risvegliò tra i non morti. Incapace di sopportare il proprio mostruoso riflesso, si cavò gli occhi a mani nude. Gettò via il suo amato specchio e fluttuò per la sua dimora abbandonata, cieca e piangente. Poteva aggrapparsi soltanto ai flebili ricordi della vita mortale che aveva perduto."}},faq={{q="Chi è Mary la Cieca?",a="Mary la Cieca infesta una fattoria in rovina a sud-est di Borgoscuro sotto forma di banshee. Era una bella donna del posto, uccisa quando Boscovespro sprofondò nell'oscurità e risorta come spirito non morto.",al={"chi è mary la cieca","storia di mary la cieca","mary la cieca boscovespro"}},{q="Perché viene chiamata Mary la Cieca?",a="Il dolore e la disperazione per la sua forma di banshee resero insopportabile a Mary il proprio riflesso, così si cavò gli occhi.",al={"perché è cieca","come ha perso gli occhi mary la cieca","occhi di mary la cieca"}},{q="Dove dimora Mary la Cieca?",a="Mary la Cieca dimora in una fattoria fatiscente chiamata Blind Mary's Haunt, a sud-est di Borgoscuro, nella parte orientale di Boscovespro.",al={"posizione di mary la cieca","dove si trova mary la cieca","ritrovo di mary la cieca"}},{q="Mary la Cieca è ostile verso i viaggiatori viventi?",a="Mary la Cieca non attacca i viaggiatori a vista. A differenza dei ghoul e degli scheletri aggressivi nei boschi circostanti, rimane prigioniera del lutto. Chi si avvicina alla sua dimora in rovina può parlarle.",al={"mary la cieca è ostile","mary la cieca attacca","si può parlare con mary la cieca"}},{q="Cosa è successo allo specchio di Mary?",a="Dopo essersi cavata gli occhi per l'orrore della propria forma spettrale, Mary gettò via il suo prezioso specchio. È ancora disperso da qualche parte nelle terre infestate di Boscovespro.",al={"specchio di mary","specchio di mary la cieca","cosa è successo al suo specchio"}},{q="Perché gli avventurieri cercano Mary la Cieca?",a="Viaggiatori e artigiani locali fanno visita a Mary mentre svolgono incarichi nei dintorni di Borgoscuro. Alcuni cercano il suo vecchio specchio per il dispositivo di osservazione delle stelle di Viktori Prism'antras; altri portano il Pettine Spettrale di Dama Eva per raccogliere capelli spettrali destinati a un filo speciale.",al={"missioni di mary la cieca","perché visitare mary la cieca","serie di missioni di mary la cieca"}}},fx={d3776a58={q="Da che parte sta Mary la Cieca?",a="Mary la Cieca non appartiene ad alcun esercito o fazione. Sebbene sia una banshee nata dalla tragedia di Boscovespro, non marcia con il Flagello né combatte contro i vivi. Prigioniera del suo tormento solitario, resta neutrale nei confronti degli avventurieri di passaggio e si rivolge a chiunque sia disposto ad ascoltare il suo dolore o a restituirle i ricordi della sua vita passata.",al={"mary la cieca è dell'alleanza o dell'orda","fazione di mary la cieca","da che parte sta mary"}},["45d21972"]={q="Che cosa vuole Mary la Cieca?",a="Mary anela alla bellezza che ha perduto e non sopporta di essere vista. Un tempo portava sempre con sé uno specchio e ne parla ancora a chi glielo chiede, ma quando qualcuno le porta un pettine, questo le ricorda soltanto ciò che è diventata e lei lo manda via.",al={"cosa vuole mary","cosa cerca mary la cieca","desideri di mary la cieca"}},["5b1d02ea"]={q="Perché Mary la Cieca si trova qui?",a="Mary la Cieca infesta una fattoria abbandonata poco a sud-est di Borgoscuro, perché è lì che ha trovato una tragica fine. Uccisa dai non morti erranti che invadono Boscovespro, si è ridestata come banshee in lacrime, legata dal dolore e dalla follia alle rovine della sua antica casa.",al={"perché mary la cieca è a boscovespro","perché mary la cieca infesta la fattoria","storia del luogo di mary la cieca"}}},fp="10,213,15.376.0,18.335.0,18.177.0,29.110.0,28.116.0,42.201.0,38.156.0,39.241.0"}
P.entries["npc:bloodmage-drazial"] = {n="Mago del Sangue Drazial",s="Al passo settentrionale, il Mago del Sangue Drazial studia le Terre Devastate con sua sorella Lynnore. Esaminano le bestie locali e preparano intrugli per i viaggiatori più resistenti.",h="Al passo settentrionale, il Mago del Sangue Drazial studia le Terre Devastate con sua sorella Lynnore.",kw={"cinghiale devastato","terre devastate","mago del sangue","intrugli","drazial","lynnore","scorpok","ghignazanna"},ang={["class:Mage"]="Da mago, puoi vedere come le arti di Drazial si discostino dalla magia tradizionale del Kirin Tor. Usa la magia del sangue e reagenti biologici per creare potenziamenti arcani."},sec={{t="Studi alchemici nelle distese rosse",b="Vicino al passo settentrionale tra la Palude del Dolore e le Terre Devastate, il Mago del Sangue Drazial studia una strana magia. Lui e sua sorella Lynnore attingono potere da questa terra inospitale attraverso la magia del sangue. Molti alti elfi rifiutano queste arti proibite o piangono la sorte di Quel'Thalas.\n\nScorpok, ghignazanna e cinghiali devastati prosperano con un vigore innaturale. Drazial e Lynnore credono che l'apertura del Portale Oscuro abbia liberato l'energia che li ha trasformati. Raccolgono organi e tessuti delle bestie, poi preparano intrugli volatili che conferiscono grande forza, agilità e resistenza."},{t="Un fornitore indipendente",b="Drazial opera separatamente dalle fazioni di stanza nelle Terre Devastate. Non serve né l'Alleanza né l'Orda. Offre invece la sua abilità alchemica a chiunque sia abbastanza resistente da attraversare le terre desolate e raccogliere i suoi ingredienti. I viaggiatori portano organi dei predatori locali, e i suoi calderoni continuano a ribollire."}},faq={{q="Chi è il Mago del Sangue Drazial?",a="Vicino all'ingresso settentrionale delle Terre Devastate, il Mago del Sangue Drazial studia la fauna locale e prepara reagenti alchemici. È un mago elfo del sangue che lavora con sua sorella Lynnore, usando parti di bestie corrotte.",al={"chi è drazial","storia di drazial","png mago del sangue drazial"}},{q="Perché Drazial raccoglie parti di animali?",a="Le creature delle Terre Devastate si sono adattate a un terreno corrotto e carico di magia. Drazial usa organi ricchi di potere di cinghiali, iene, scorpioni e basilischi per preparare elisir che rafforzano il corpo di un guerriero.",al={"perché drazial vuole polmoni di cinghiale","oggetti di missione di drazial","organi animali di drazial"}},{q="Drazial lavora per l'Alleanza o per l'Orda?",a="Drazial è neutrale nei confronti di entrambe le fazioni. Lui e Lynnore non prendono parte alla guerra tra Roccavento e l'Orda. Trattano con qualsiasi viaggiatore disposto a fornire il necessario per le loro ricerche magiche e alchemiche.",al={"fazione di drazial","drazial è dell'orda o dell'alleanza","l'alleanza può parlare con drazial"}},{q="Chi è l'altro elfo del sangue accampato con lui?",a="La Maga del Sangue Lynnore è l'elfa del sangue accampata accanto a Drazial, ed è sua sorella. Insieme praticano la magia del sangue e preparano diversi intrugli usando le bestie che vagano per le Terre Devastate.",al={"compagna di drazial","chi è con drazial","lynnore"}}},fp="17,160,36.553.0,23.307.0,25.207.0,39.203.0,48.197.0,43.182.0"}
P.entries["npc:bloodmage-lynnore"] = {n="Maga del Sangue Lynnore",s="Vicino all'ingresso settentrionale delle Terre Devastate, la Maga del Sangue Lynnore studia il potere racchiuso nelle bestie locali. Si accampa con suo fratello Drazial e prepara pozioni con i loro organi.",h="Vicino all'ingresso settentrionale delle Terre Devastate, la Maga del Sangue Lynnore studia il potere...",kw={"terre devastate","magia del sangue","maga del sangue lynnore","composto di corteccia cerebrale","cicca alla trippa","lynnore"},ang={["class:Mage"]="Come mago attratto da forme di magia non convenzionali, puoi guardare al raro e controverso percorso arcano di Lynnore. Manipola l'essenza vitale invece delle consuete energie delle linee di faglia.",["faction:Horde"]="Come viaggiatore dell'Orda, puoi commerciare con Lynnore nelle Terre Devastate. Offre preparati unici a chiunque, di entrambe le fazioni, le porti gli ingredienti grezzi."},sec={{t="Maestra della Magia del Sangue",b="Vicino all'ingresso settentrionale delle Terre Devastate, la Maga del Sangue Lynnore studia la magia del sangue con suo fratello Drazial. Pochi elfi nei Regni Orientali praticano quest'arte proibita. La terra è aspra e corruttrice, eppure Lynnore cerca energie arcane e vitali nelle bestie autoctone. I viaggiatori le portano cervelli e ventrigli degli animali locali. Ne distilla elisir che potenziano intelletto e spirito."}},faq={{q="Chi è la Maga del Sangue Lynnore?",a="La Maga del Sangue Lynnore è un'elfa del sangue che pratica la magia del sangue, accampata vicino all'ingresso settentrionale delle Terre Devastate. I viaggiatori le portano parti di bestie per ottenere potenti preparati che potenziano le loro capacità.",al={"chi è lynnore","storia della maga del sangue lynnore","lynnore terre devastate"}},{q="Dove si trova la Maga del Sangue Lynnore?",a="Lynnore si accampa con suo fratello, il Mago del Sangue Drazial, vicino all'ingresso settentrionale delle Terre Devastate. Il loro accampamento si trova dove il valico dalla Palude del Dolore sbocca sulle distese desolate.",al={"posizione di lynnore","dove si trova lynnore","come trovare la maga del sangue lynnore"}},{q="Quali intrugli prepara?",a="Lynnore prepara rari tonici con parti della fauna locale, tra cui cervelli di basilisco, ventrigli di avvoltoio e guance di snickerfang. Il suo Composto di Corteccia Cerebrale e la sua Cicca alla Trippa potenziano intelletto e spirito a lungo.",al={"potenziamenti di lynnore","consumabili delle terre devastate","composto di corteccia cerebrale"}}},fp="17,172,21.401.0,25.180.0,37.173.0,31.205.0"}
P.entries["npc:bloodmage-thalnos"] = {n="Mago del Sangue Thalnos",s="Nel Cimitero del Monastero Scarlatto, il Mago del Sangue Thalnos infesta le tombe, assetato di vendetta. La piaga della non morte lo ha reclamato, e lui rimane nelle profondità dei terreni sacri della Crociata.",h="Nel Cimitero del Monastero Scarlatto, il Mago del Sangue Thalnos infesta le tombe, assetato di vendetta.",kw={"mago del sangue","cimitero","monastero scarlatto","scheletro","thalnos"},ang={["class:Mage"]="Come mago, vedi in Thalnos come la piaga possa trasformare un incantatore dotato in un essere vendicativo che brandisce ancora il fuoco e l'ombra.",["class:Priest"]="Come sacerdote, vedi in Thalnos tra le tombe un segno inquietante: lo zelo della Crociata non ha tenuto l'oscurità lontana dal suo suolo sacro.",["faction:Horde"]="Come membro dell'Orda, puoi vedere in Thalnos ciò a cui i Reietti sono sfuggiti: un mago non morto la cui unica volontà rimasta è la vendetta, in agguato nel cuore del monastero della Crociata Scarlatta."},sec={{t="Un Mago Risorto nella Morte",b="Nessun registro rivela chi fosse Thalnos in vita. La piaga della non morte lo ha reclamato, ed è risorto come uno scheletro avvizzito. Eppure, si aggrappa ancora alla magia del fuoco e alla maestria arcana. Grida vendetta e reclama altre anime."},{t="Il Signore del Cimitero",b="Dall'angolo più profondo delle tombe nel cortile del monastero, Thalnos comanda apparizioni e servitori non morti barcollanti. Attacca chiunque disturbi il suo dominio. Sotto le sacre sale della Crociata, la sua presenza è un'amara contraddizione. Incarna l'orrore che hanno giurato di sradicare."}},faq={{q="Chi è il Mago del Sangue Thalnos?",a="Il Mago del Sangue Thalnos infesta il Cimitero del Monastero Scarlatto come incantatore scheletrico. Nessun registro rivela chi fosse in vita; la piaga della non morte lo ha reclamato, ed è risorto come mago non morto assetato di vendetta.",al={"chi è thalnos","storia di thalnos","informazioni sul mago del sangue thalnos"}},{q="Perché uno scheletro non morto è tollerato nel Monastero Scarlatto?",a="La Crociata giustizia i non morti a vista, eppure Thalnos rimane all'estremità più lontana del Cimitero, tra cripte risorte e spiriti. Si aggira nel suo dominio corrotto anziché camminare liberamente tra i crociati viventi.",al={"perché thalnos si trova nel monastero","perché la crociata scarlatta tiene thalnos","mago non morto della crociata scarlatta"}},{q="Quali poteri possiede Thalnos?",a="Thalnos padroneggia incantesimi di fuoco e Shadow Magic. Evoca anche spiriti vendicativi e morti che camminano per sopraffare gli intrusi nel Cimitero.",al={"incantesimi di thalnos","magia del mago del sangue thalnos","cosa fa thalnos"}},{q="Thalnos era un elfo del sangue?",a="La stirpe mortale di Thalnos è incerta. Il solo titolo di Mago del Sangue non dimostra che fosse un elfo del sangue.",al={"thalnos è un elfo alto","razza di thalnos","che razza era thalnos"}},{q="Chi vuole la morte di Thalnos?",a="Thalnos è ostile agli intrusi nel Cimitero del monastero. Per quest'epoca non è attestato alcun incarico specifico per ucciderlo.",al={"missione di thalnos","chi vuole la morte di thalnos","il lato oscuro della luce thalnos"}}},fx={ee50c387={q="Da che parte sta il Mago del Sangue Thalnos?",a="Thalnos non serve nessuno. Dopo aver ceduto alla piaga della non morte, è diventato una creatura mossa interamente dalla vendetta e dal potere empio. Ora è uno scheletro non morto e difende ferocemente il proprio dominio nel cimitero del monastero, comandando apparizioni e creature zombificate per massacrare ogni intruso vivente che incroci il suo cammino.",al={"fazione di thalnos","chi serve thalnos","thalnos fa parte della crociata scarlatta"}},fb23ba27={q="Che cosa vuole il Mago del Sangue Thalnos?",a="Reso folle dalla non morte, Thalnos desidera poco più di una vendetta empia. Legato al cimitero del monastero, il vendicativo mago scheletrico comanda apparizioni irrequiete e cadaveri rianimati per annientare chiunque osi entrare nel suo territorio maledetto.",al={"cosa vuole thalnos","obiettivo di thalnos","motivazioni di thalnos"}},["39b55bcf"]={q="Perché il Mago del Sangue Thalnos è temuto?",a="Thalnos è un potente incantatore non morto che domina il cimitero del monastero, scagliando fuoco e ombra contro gli intrusi e gridando vendetta e invocando altre anime. Il fatto che una creatura simile si aggiri tra i defunti della Crociata Scarlatta la rende ancora più inquietante.",al={"perché thalnos è temuto","cosa ha reso famoso thalnos","reputazione del mago del sangue thalnos"}}},fp="17,185,21.206.0,23.285.0,25.208.0,59.210.0,31.140.0,24.108.0,23.125.0"}
P.entries["npc:bluff-runner-windstrider"] = {n="Corridore del Picco Passo Fulgido",s="Sugli altopiani di Picco del Tuono, il Corridore del Picco Passo Fulgido porta messaggi urgenti attraverso la città. Indirizza i viaggiatori dell'Orda verso frontiere lontane, tra cui Valtetra, Feralas e le Terre Infette.",h="Sugli altopiani di Picco del Tuono, il Corridore del Picco Passo Fulgido porta messaggi urgenti attraverso la...",kw={"valtetra","corridore del picco","accampamento mojache","messaggero","mulgore","picco del tuono","passo fulgido"},ang={["faction:Horde"]="Come membro dell'Orda, puoi portare notizie da Mulgore ai fronti dove l'Orda combatte per le risorse e la sopravvivenza.",["race:Tauren"]="Come tauren, puoi seguire la tradizione dei corridori, mantenendo i contatti tra le tribù e gli anziani del centro senza macchinari o reti postali straniere."},sec={{t="Un messaggero sui rilievi",b="Il Corridore del Picco Passo Fulgido porta messaggi attraverso gli alti pianori di Picco del Tuono. Le sue rapide corse tengono informati i capi e i visitatori della città. Percorre a passo di corsa ponti di corda e sentieri, annunciando notizie e portando dispacci. Quando gli avamposti lontani hanno bisogno di rinforzi, Passo Fulgido esorta i campioni di passaggio a portare notizie e rispondere alla chiamata alle armi."},{t="Chiamate alla frontiera",b="Il Corridore del Picco Passo Fulgido invia messaggi ben oltre Mulgore. Indirizza i viaggiatori a nord per unirsi alla grande caccia di Senani Cuore Tonante presso l'Avamposto di Troncorotto, a Valtetra. Indica agli esploratori esperti la via verso sud, fino all'Accampamento Mojache a Feralas, e reca gravi avvertimenti sulla persistente minaccia dei non morti nelle Terre Infette Occidentali. I suoi dispacci legano il cuore tribale di Mulgore ai più ampi conflitti dell'Orda."}},faq={{q="Chi è il Corridore del Picco Passo Fulgido?",a="Il Corridore del Picco Passo Fulgido porta messaggi attraverso Picco del Tuono. Diffonde notizie ed esorta i viaggiatori più capaci dell'Orda a sostenere campagne urgenti in tutta Azeroth.",al={"png passo fulgido","corridore del picco","chi e passo fulgido"}},{q="Dove posso trovare il Corridore del Picco Passo Fulgido?",a="Il Corridore del Picco Passo Fulgido percorre a passo di corsa i ponti e le terrazze di Picco del Tuono. Spesso compie un circuito tra l'altopiano centrale e le alture vicine.",al={"posizione di passo fulgido","dove si trova il corridore del picco","trova passo fulgido"}},{q="Quali missioni offre Passo Fulgido?",a="Il Corridore del Picco Passo Fulgido indirizza i viaggiatori verso regioni lontane. I suoi appelli riguardano la caccia di Valtetra, la fondazione dell'Accampamento Mojache a Feralas e le chiamate alle armi nelle Terre Infette.",al={"missioni di passo fulgido","cosa assegna","compiti del corridore del picco"}},{q="Perché viene chiamato 'Corridore del Picco'?",a="Gli aspri altopiani, le pareti scoscese e i ponti sospesi di Picco del Tuono possono rendere gli spostamenti in sella difficoltosi o lenti. Corridori come Passo Fulgido portano messaggi attraverso la città a piedi.",al={"cos e un corridore del picco","titolo di corridore del picco"}}},fx={e05bd34a={q="Da che parte sta il Corridore del Picco Passo Fulgido?",a="Il Corridore del Picco Passo Fulgido serve le tribù tauren e l'Orda dall'alto del Picco del Tuono. In qualità di corriere e messaggero ufficiale, agisce per conto degli anziani e dei capi tribù: consegna notizie fondamentali, raduna i guerrieri e mantiene i contatti con gli avamposti lontani di Kalimdor e oltre.",al={"fazione di passofulgido","lealtà del corridore del picco passofulgido","chi serve passofulgido"}},b3137841={q="Perché il Corridore del Picco Passo Fulgido si trova qui?",a="Passo Fulgido percorre i rilievi del Picco del Tuono per diffondere notizie urgenti tra viaggiatori e difensori. Una città estesa su ampi altopiani ha bisogno di corrieri a piedi veloci che trasmettano gli annunci tra capi e avventurieri, affinché le notizie raggiungano chi è pronto a rispondere all'appello degli insediamenti lontani.",al={"perché passofulgido è al picco del tuono","scopo di passofulgido al picco del tuono","cosa fa qui passofulgido"}},["7698149f"]={q="Che cosa vuole il Corridore del Picco Passo Fulgido?",a="Passo Fulgido cerca avventurieri capaci e disposti a spingersi ben oltre Mulgore. Consegnando convocazioni, notizie e appelli alle armi, spera di guidare gli eroi emergenti verso frontiere dove l'Orda ha bisogno di aiuto, indirizzandoli verso importanti territori di caccia e avamposti sotto assedio in tutta Azeroth.",al={"di cosa ha bisogno passofulgido","motivazioni del corridore del picco passofulgido","perché passofulgido assegna missioni"}}},fp="24,194,24.348.0,21.382.0,32.155.0,42.138.0,35.183.0,34.168.0"}
P.entries["npc:bolvar-fordragon"] = {n="Bolvar Fordragon",s="Nel Forte di Roccavento, Bolvar Fordragon regge la corona e gli eserciti mentre Re Varian è scomparso. Come Reggente e Comandante Supremo delle forze armate di Roccavento, affianca il giovane Re Anduin e lotta per tenere unito il regno. I disordini interni crescono, mentre i consigli di Dama Katrana Prestor ritardano spesso le sue decisioni militari.",h="Nel Forte di Roccavento, Bolvar Fordragon regge la corona e gli eserciti mentre Re Varian è scomparso.",kw={"anduin wrynn","bolvar","fordragon","gran signore","katrana prestor","reggente","forte di roccavento"},ang={["class:Paladin"]="Come paladino, Bolvar incarna l'ideale marziale dell'Alleanza: devozione alla Luce e incrollabile senso del dovere verso il suo popolo, anche mentre gli intrighi politici si moltiplicano.",["faction:Alliance"]="Come Comandante Supremo di Roccavento, Bolvar guida le forze armate umane e bilancia la risposta alle ribellioni locali con gli impegni più ampi dell'Alleanza."},sec={{t="Reggente del Regno",b="Re Varian scomparve durante il viaggio verso un vertice di pace sull'Isola di Theramore, lasciando Roccavento nello scompiglio. Il principe Anduin, di dieci anni, fu incoronato per garantire la continuità, e il Gran Signore Bolvar Domadraghi assunse il governo come Reggente.\n\nVenerato paladino devoto alla corona, Bolvar affronta ora un regno sotto pressione. Le truppe di Roccavento sono disperse tra le Marche Occidentali, Redridge e Boscovespro, senza forze sufficienti. Dama Katrana Prestor sminuisce le sue preoccupazioni e gli impedisce ripetutamente di inviare truppe reali nelle cittadine di frontiera."},{t="Una tela di inganni",b="I magistrati cittadini e i marescialli di frontiera implorano rinforzi contro la Fratellanza dei Defias e gli orchi Roccianera. Dama Prestor influenza discretamente i decreti reali e sminuisce ogni rapporto di pericolo. Bolvar rispetta i consigli della nobiltà, quindi esita ad agire senza prove inconfutabili. Inconsapevolmente, lascia la corona incapace di agire.\n\nQuando giungono prove convincenti, il Reggente accantona le consuetudini di corte. Gli avvertimenti degli investigatori a Theramore o le notizie di ufficiali scomparsi sul campo possono spingerlo a rivolgersi ad avventurieri indipendenti."}},faq={{q="Perché Bolvar governa al posto di Re Varian?",a="Re Varian Wrynn scomparve in circostanze sospette mentre navigava verso un vertice diplomatico sull'Isola di Theramore. Suo figlio Anduin, di dieci anni, fu incoronato per preservare l'ordine politico. Il Gran Signore Bolvar Domadraghi divenne Reggente, assumendo il governo del regno e il comando dei suoi eserciti finché Varian non sarà ritrovato.",al={"dov'è il re","perché bolvar è al comando","chi è il reggente"}},{q="Perché Bolvar non invia soldati ad aiutare Redridge o le Marche Occidentali?",a="Gli eserciti permanenti di Roccavento sono al limite delle proprie forze, impegnati a difendere i territori centrali e i confini. Dama Katrana Prestor, principale consigliera di Bolvar, mette ripetutamente in dubbio i rapporti da luoghi come Borgolago, li definisce esagerati e sconsiglia l'invio di forze reali. In assenza di prove militari, Bolvar affida invece l'incarico di intervenire ad avventurieri indipendenti.",al={"perché niente esercito di roccavento","perché bolvar non manda aiuto","truppe di borgolago"}},{q="Qual è il rapporto di Bolvar con Dama Katrana Prestor?",a="Dama Katrana Prestor è la principale consigliera reale del trono di Roccavento. Bolvar rispetta il suo giudizio politico e la sua conoscenza degli affari nobiliari, ma lei esorta continuamente alla cautela e gli consiglia di ignorare i rapporti su draghi, orchi e complotti dei Defias.",al={"bolvar e prestor","chi è dama prestor per bolvar"}},{q="Qual è il legame di Bolvar con il giovane Principe Anduin?",a="Bolvar non è imparentato con Anduin, ma è il suo strenuo protettore, tutore e mentore. Sta accanto al trono di Anduin nel Forte di Roccavento, proteggendolo dagli intrighi di corte e mantenendo al sicuro la dinastia Wrynn fino al ritorno di Varian.",al={"anduin e bolvar","bolvar è il padre di anduin"}}},fx={["634d3c0f"]={q="Chi è il Gran Signore Bolvar Domadraghi?",a="Il Gran Signore Bolvar Domadraghi è un paladino venerato e il reggente di Roccavento. In qualità di comandante supremo delle forze militari del regno, governa per conto del giovane Re Anduin Wrynn dopo la misteriosa scomparsa di Re Varian Wrynn. Noto per il suo spirito nobile e il suo onore, porta il tremendo fardello di mantenere l'ordine e difendere il regno durante uno dei periodi più vulnerabili di Roccavento.",al={"chi è bolvar","identità di bolvar","chi è il gran signore bolvar"}},["946cb7aa"]={q="Da che parte sta Bolvar Fordragon?",a="Bolvar è interamente devoto al Regno di Roccavento e all'Alleanza. La sua lealtà va innanzitutto alla Casa Wrynn: protegge con fervore il giovane Principe Anduin e lavora per difendere i territori del regno, nonostante i gravi disordini politici e le guarnigioni decimate.",al={"lealtà di bolvar","di quale fazione fa parte bolvar","fazione di bolvar"}},["309206e7"]={q="Che cosa vuole Bolvar Fordragon?",a="Soprattutto, Bolvar vuole mantenere la stabilità di Roccavento, scoprire che fine abbia fatto il Re Varian scomparso e proteggere il giovane Anduin Wrynn da chi vorrebbe approfittarsi della sua giovane età. Si adopera per affrontare le crescenti minacce della Fratellanza dei Defias e degli orchi Roccia Nera, cercando di bilanciare la difesa dei territori periferici come Redridge e le Marche Occidentali con i consigli della corte reale.",al={"obiettivi di bolvar","cosa cerca di fare bolvar","motivazione di bolvar"}},e6552818={q="Perché Bolvar Fordragon è famoso?",a="Bolvar è noto come paladino dotato di straordinaria determinazione, valore e incrollabile fermezza morale. In qualità di Gran Signore, reggente e comandante supremo delle forze di Roccavento, la sua guida e il suo onore incrollabile ne hanno fatto uno dei più rispettati strateghi militari e paladini dell'intera Alleanza.",al={"perché bolvar è famoso","reputazione di bolvar","bolvar è rinomato"}}},fp="16,333,19.514.0,15.531.1,44.297.0,60.355.0,56.256.0,51.248.0"}
P.entries["npc:braelyn-firehand"] = {n="Braelyn Ardimano",s="Al Rifugio Roccia del Sole, Braelyn Ardimano vive tra le file dell'Orda e coinvolge i viaggiatori in una campagna contro gli elfi della notte del Picco di Petrartiglio.",h="Al Rifugio Roccia del Sole, Braelyn Ardimano vive tra le file dell'Orda e coinvolge i viaggiatori in una...",kw={"braelyn","cenarius","ardimano","alti nobili","ordanus","petrartiglio","rifugio roccia del sole"},ang={["class:Druid"]="Come druido, sai che il massacro dei figli di Cenarius e il saccheggio di Talon Den sono crimini contro l'equilibrio della natura.",["class:Mage"]="Come mago, potresti riconoscere ciò di cui parla Braelyn quando menziona energie geomantiche e ostruzioni mistiche. Si rivolge a chi comprende la magia arcana che scorre nella terra.",["faction:Horde"]="Come membro dell'Orda, puoi trovare Braelyn intenta ad assoldare viandanti per colpire gli elfi della notte. I loro scontri territoriali a Kalimdor coprono i suoi scopi più nascosti."},sec={{t="Un'ospite improbabile",b="Braelyn Ardimano è una maga elfica, eppure vive apertamente tra le logge dei tauren e le tende degli orchi. Gli sciamani e i capoclan del rifugio la tollerano, apparentemente ignari delle sue vere alleanze. Si definisce un'osservatrice della magia della regione e assolda mercenari dell'Orda di passaggio per incarichi pericolosi tra i dirupi."},{t="Un rancore contro il boschetto",b="Braelyn Ardimano manda i suoi alleati contro i druidi elfi della notte e la sacra prole di Cenarius al Picco di Petrartiglio. Sostiene che i druidi soffochino le linee geomantiche e ostacolino il potere arcano su tutte le vette. Il suo rancore è personale: ricorda il Custode Ordanus come un arrogante, convinto di essere superiore persino agli Alti Nobili. Paga i viaggiatori dell'Orda perché gli diano la caccia e le riportino la sua testa."},{t="Legami con Jaedenar",b="L'odio di Braelyn Ardimano serve gli scopi della setta del Concilio dell'Ombra a Jaedenar, a Vilbosco. Esorta i campioni dell'Orda a uccidere gli elfi della notte e i custodi che proteggono le vette sacre, spianando la strada a poteri più oscuri e mascherando i propri legami dietro schermaglie di frontiera."}},faq={{q="Chi è Braelyn Ardimano?",a="Braelyn Ardimano è una maga elfica che vive al Rifugio Roccia del Sole, nelle Vette di Petrartiglio. Pur essendo circondata dall'Orda, porta avanti una campagna arcana contro gli elfi della notte che proteggono il Picco di Petrartiglio.",al={"chi è braelyn","storia di braelyn ardimano","elfa al rifugio roccia del sole"}},{q="Perché un'elfa si trova al Rifugio Roccia del Sole?",a="Il Rifugio Roccia del Sole è un accampamento di frontiera isolato che tollera Braelyn. Sfrutta il costante passaggio di guerrieri dell'Orda per assoldare combattenti contro gli elfi della notte senza destare subito sospetti nei capi dell'accampamento.",al={"perché è con l'orda","perché braelyn si trova a roccia del sole","elfa del sangue a petrartiglio"}},{q="Cosa vuole che venga fatto al Picco di Petrartiglio?",a="Braelyn chiede ai viaggiatori di attaccare i druidi e i figli di Cenarius al Picco di Petrartiglio, sostenendo che ostacolino il flusso della magia. La caccia al Custode Ordanus la porta al Rifugio di Legnovivo, a Valtetra.",al={"obiettivi delle missioni di braelyn","perché uccidere ordanus","compiti di braelyn ardimano"}},{q="Qual è la sua storia con il Custode Ordanus?",a="Braelyn afferma di aver conosciuto personalmente il Custode Ordanus in un lontano passato. Prova un profondo rancore per la sua immensa arroganza e sostiene che si considerasse superiore persino agli antichi Alti Nobili.",al={"braelyn e ordanus","come conosce ordanus","storia di ordanus"}},{q="Cosa sostiene di star ricercando Braelyn Ardimano?",a="Braelyn sostiene che i druidi e i figli di Cenarius al Picco di Petrartiglio limitino il flusso della magia. Vuole eliminarli per poter attingere a quel potere.",al={"vera fazione di braelyn","braelyn concilio dell'ombra","per chi lavora"}},{q="Braelyn è una maga o una strega?",a="Braelyn pratica la magia arcana e combatte con Fireballs.",al={"classe di braelyn","braelyn è un'eccelsa strega","incantesimi di braelyn ardimano"}}},fx={deec6fbf={q="A chi è legata Braelyn Ardimano?",a="Braelyn serve un padrone a Jaedenar ed è legata al Concilio dell'Ombra. Recluta viaggiatori dell'Orda per attaccare gli Elfi della Notte e i figli di Cenarius.",al={"legami di braelyn ardimano","con chi è affiliata braelyn ardimano","alleati di braelyn ardimano"}}},fp="16,139,17.314.0,26.380.1,16.270.1,24.202.0,42.208.0,43.203.0,40.184.0,51.148.2,31.57.2"}
P.entries["npc:braenna-flintcrag"] = {n="Braenna Selcenera",s="Nella Guardia Mistica di Forgiardente, Braenna Selcenera insegna le vie della Sacra Luce. Addestra i sacerdoti nelle arti curative e nella disciplina spirituale, e comunica ai sacerdoti Elfi della Notte in visita quando sono richiamati al Temple of the Moon a Darnassus.",h="Nella Guardia Mistica di Forgiardente, Braenna Selcenera insegna le vie della Sacra Luce.",kw={"braenna selcenera","hall of mysteries","sacra luce","forgiardente","guardia mistica","istruttore dei sacerdoti","returning home"},ang={["class:Priest"]="Come sacerdote dell'Alleanza, puoi imparare incantesimi essenziali e studiare la Luce con Braenna Selcenera a Forgiardente.",["race:Dwarf"]="Come nano, puoi vedere la devozione di Forgiardente alla Sacra Luce nell'opera di Braenna Selcenera, accanto alle tradizioni marziali della città."},sec={{t="Una guida nella Hall of Mysteries",b="Braenna Selcenera addestra i sacerdoti nella Hall of Mysteries. Lì, nella Guardia Mistica di Forgiardente, insegna agli accoliti nani a curare e a innalzare protezioni difensive con la Sacra Luce. Le sue lezioni li preparano a un mondo pericoloso. Attraverso questo lavoro, si prende cura dei bisogni spirituali di Khaz Modan, in una città rinomata per le sue fucine e i suoi guerrieri."}},faq={{q="Chi è Braenna Selcenera?",a="Braenna Selcenera addestra i sacerdoti nella Hall of Mysteries di Forgiardente. Insegna preghiere sacre, incantesimi e disciplina spirituale.",al={"braenna selcenera","chi è braenna","istruttrice dei sacerdoti braenna"}},{q="Dove posso trovare Braenna Selcenera?",a="Braenna Selcenera si trova nella Hall of Mysteries, all'interno della Guardia Mistica di Forgiardente.",al={"dove si trova braenna","posizione di braenna selcenera","trovare braenna selcenera"}},{q="Quali servizi offre ai viaggiatori?",a="Braenna Selcenera addestra i sacerdoti dell'Alleanza e li fa avanzare di grado. Comunica inoltre ai sacerdoti Elfi della Notte in visita quando sono richiamati al Temple of the Moon a Darnassus.",al={"servizi di braenna","cosa fa braenna","braenna può addestrarmi"}},{q="È imparentata con qualcun altro a Khaz Modan?",a="Braenna Selcenera condivide il cognome con Thulman Flintcrag. Il nome suggerisce un legame con un'illustre stirpe nanica di Khaz Modan.",al={"famiglia selcenera","parente di thulman selcenera","parenti di braenna selcenera"}}},fx={d5abdbfc={q="Da che parte sta Braenna Selcenera?",a="Braenna è devota all'Alleanza e al regno nanico di Forgiardente. Opera nella Hall of Mysteries insieme ad altri studiosi, mistici e praticanti della fede; serve il suo popolo e l'Alleanza nel suo insieme attraverso gli insegnamenti e la disciplina spirituale della Luce Sacra.",al={"fazione di braenna selcenera","chi serve braenna","braenna selcenera e alleanza"}},["787cf3cf"]={q="Che cosa vuole Braenna Selcenera?",a="Braenna si dedica a guidare e preparare i discepoli fedeli nei misteri della Luce Sacra. Trascorre il suo tempo ad addestrare aspiranti sacerdoti nani a Forgiardente, assicurandosi che abbiano la forza spirituale e le abilità sacre necessarie per aiutare la loro comunità e proteggere l'Alleanza.",al={"che cosa vuole braenna","obiettivo di braenna selcenera","scopo di braenna selcenera"}},["19ad6f1b"]={q="Perché Braenna Selcenera è qui?",a="Braenna risiede nella Hall of Mysteries, nella Guardia Mistica di Forgiardente, che funge da santuario sacro della capitale per lo studio divino e la pratica magica. Al fianco degli altri mentori, è sempre pronta ad assistere e istruire i sacerdoti che attraversano la città montana o vi prestano servizio.",al={"perché braenna è qui","perché braenna è a forgiardente","motivo della presenza di braenna selcenera"}}},fp="17,240,32.337.0,25.126.0,35.78.0,44.175.0,44.135.0"}
P.entries["npc:brainwashed-noble"] = {n="Nobile Condizionato",s="Nelle profondità delle caverne fuori dalle Miniere della Morte, il Nobile Condizionato resta nelle mani dei Defias. Un incantamento lo ha privato della volontà, e ora sorveglia il loro rifugio al fianco di servitori non morti anziché percorrere i grandiosi saloni di Roccavento.",h="Nelle profondità delle caverne fuori dalle Miniere della Morte, il Nobile Condizionato resta nelle mani dei...",kw={"nobile condizionato","miniere della morte","fratellanza dei defias","house of nobles","rivoluna","roccavento","marche occidentali"},ang={["class:Mage"]="Da mago, puoi riconoscere i bastoni magici e gli espedienti arcani del Nobile Condizionato, come Polymorph. Suggeriscono che abbia ricevuto un'istruzione magica formale nella capitale prima che la sua mente venisse spezzata.",["race:Human"]="Da umano, vedere un pari del regno ridotto a una sentinella senza volontà sotto le Marche Occidentali ti mostra quanto sia profondo il rancore della Fratellanza dei Defias verso l'élite al potere a Roccavento."},sec={{t="Una pedina della Fratellanza",b="Il Nobile Condizionato vaga per i passaggi che conducono alle Miniere della Morte, tra banditi e cadaveri putrescenti. I suoi abiti aristocratici suggeriscono un legame con la House of Nobles di Roccavento, forse come membro effettivo o rampollo. Edwin VanCleef lo ha fatto prigioniero. I Defias hanno preferito un incantamento al riscatto e gli hanno piegato la mente, trasformandolo in una guardia incantatrice per il loro santuario. Il loro odio per i nobili che si rifiutarono di pagarli dopo la ricostruzione di Roccavento arriva fin nelle caverne sotto le Marche Occidentali."}},faq={{q="Chi è il Nobile Condizionato?",a="Il Nobile Condizionato è un aristocratico umano che si ritiene appartenga alla House of Nobles di Roccavento. La Fratellanza dei Defias lo ha catturato e soggiogato con la magia nelle profondità delle caverne delle Miniere della Morte.",al={"chi è il nobile condizionato","cos'è il nobile condizionato","nobile nelle miniere della morte"}},{q="Perché un nobile di Roccavento si trova all'interno delle caverne delle Miniere della Morte?",a="La Fratellanza dei Defias nutre un profondo rancore verso l'aristocrazia di Roccavento per i debiti rimasti insoluti dopo la ricostruzione della città. Un nobile prigioniero offre loro servigi magici e un mezzo per vendicarsi personalmente.",al={"perché si trova nelle miniere della morte","perché il nobile è nelle caverne"}},{q="Dove si trova il Nobile Condizionato?",a="Il Nobile Condizionato vaga nei cunicoli delle caverne di Rivoluna che conducono verso l'ingresso delle Miniere della Morte, tra passaggi abitati da non morti scheletrici.",al={"posizione del nobile condizionato","dove compare"}},{q="Come è stato condizionato?",a="Nessuno sa quale incantatore gli abbia condizionato la mente. Gli incantatori rinnegati e gli ammaliatori tra i Defias nelle Marche Occidentali possono piegare la mente di un prigioniero con la stregoneria.",al={"chi lo ha condizionato","come viene controllato"}}},fx={["7d2ae820"]={q="Da che parte sta il Nobile Condizionato?",a="Serve la Fratellanza dei Defias, anche se non per sua scelta. Privato della propria volontà, questo aristocratico prigioniero ora sorveglia la rete di gallerie che conduce alla roccaforte di Edwin VanCleef, rivolgendo le sue arti arcane contro chiunque si addentri nel territorio dei fuorilegge.",al={"da che parte sta il nobile condizionato","per chi combatte il nobile condizionato","il nobile condizionato è un defias"}},["0b33d704"]={q="A chi è legato il Nobile Condizionato?",a="In passato era legato alla Casa dei Nobili di Roccavento, l'aristocrazia al potere che attualmente governa sotto l'autorità del Gran Signore Bolvar Domadraghi. Nel suo stato attuale, però, è completamente asservito a Edwin VanCleef e ai cospiratori Defias che lo tengono al guinzaglio nelle profondità delle miniere di Rivoluna.",al={"legami del nobile condizionato","chi controlla il nobile condizionato","fazione del nobile condizionato"}}},fp="17,224,25.460.1,29.181.0,52.204.1,41.143.1,23.151.0"}
P.entries["npc:brandur-ironhammer"] = {n="Brandur Fermartello",s="A Forgiardente, Brandur Fermartello addestra i giovani paladini nella Sacra Luce e li invia in tutta l'Alleanza.",h="A Forgiardente, Brandur Fermartello addestra i giovani paladini nella Sacra Luce e li invia in tutta...",kw={"brandur","hall of mysteries","forgiardente","fermartello","guardia mistica","paladino","tiza battiforgia","tome of divinity","istruttore"},ang={["class:Paladin"]="Come paladino nano o dell'Alleanza, puoi apprendere abilità marziali e sigilli sacri da Brandur a Forgiardente, poi seguire le sue indicazioni verso prove sacre avanzate.",["race:Dwarf"]="Come nano, condividi la tradizione di Khaz Modan dei paladini che a Forgiardente uniscono l'acciaio delle armi alla venerazione per la Sacra Luce."},sec={{t="Una guida nella Guardia Mistica",b="Nella Hall of Mysteries, Brandur Fermartello insegna ai paladini novizi le vie della Sacra Luce. Insieme a Tiza Battiforgia, guida i giovani campioni nani attraverso le prove del Tome of Divinity. Tiza ha parlato apertamente dei difetti di Brandur. Lui si impegna a dominare la propria invidia e a mantenere la purezza interiore richiesta a un guerriero della Luce."},{t="In contatto con la Mano d'Argento",b="Brandur collega Forgiardente alla più ampia confraternita dell'Alleanza. Gli iniziati umani che giungono alla montagna vengono inviati a sud, da Duthorian Rall nella Cathedral of Light. I paladini esperti si recano su campi di battaglia come l'Accampamento di Ventofreddo nelle Terre Infette Occidentali. I crociati veterani vengono indirizzati da Ser Grayson Spezzaombra per le impegnative prove del destriero da guerra."}},faq={{q="Dove si trova Brandur Fermartello?",a="Brandur Fermartello si trova nella Hall of Mysteries, nella Guardia Mistica sul lato settentrionale di Forgiardente.",al={"posizione di brandur fermartello","trova brandur fermartello","dove si trova brandur"}},{q="Quale ruolo svolge Brandur Fermartello per i paladini?",a="Brandur Fermartello addestra i nuovi paladini, guida gli iniziati attraverso il Tome of Divinity e indirizza i paladini esperti verso prove avanzate in tutta l'Alleanza.",al={"brandur istruttore dei paladini","cosa fa brandur","scopo di brandur"}},{q="Chi è la collega di Brandur nella Hall of Mysteries?",a="Brandur lavora al fianco di Tiza Battiforgia, un'altra istruttrice dei paladini nana nella Hall of Mysteries. Tiza gli ha fatto notare la sua gelosia e Brandur si impegna a superarla.",al={"compagna di brandur","chi lavora con brandur","relazione con tiza battiforgia"}},{q="Perché Brandur invia i paladini a Roccavento?",a="Brandur invia i paladini umani che si addestrano a Forgiardente da Duthorian Rall o Ser Grayson Spezzaombra nella Cathedral of Light di Roccavento per i riti formali del loro regno.",al={"missione di roccavento di brandur","perché andare da duthorian rall","brandur paladini umani"}},{q="Brandur ha legami con la lotta contro il Flagello?",a="Sì. Brandur trasmette le richieste urgenti di Commander Ashlam Valorfist e invia paladini di comprovata purezza e valore a sostenere la crociata dell'Alleanza all'Accampamento di Ventofreddo, al confine con le Terre Infette Occidentali.",al={"brandur terre infette","accampamento di ventofreddo brandur","ashlam valorfist brandur"}}},fx={ce9b1d9f={q="Chi è Brandur Fermartello?",a="Brandur Fermartello è un addestratore di paladini nani che presta servizio nella Hall of Mysteries, nella Guardia Mistica di Forgiardente. Devoto alla Luce Sacra, guida i paladini emergenti nell'arte del combattimento, nella fede e nella virtù, indirizzando iniziati nani e alleati umani verso le prove e i maestri necessari per affinare la loro sacra vocazione.",al={"brandur fermartello","chi è brandur","storia di brandur"}},d07784b0={q="Da che parte sta Brandur Fermartello?",a="Brandur è profondamente leale al Regno di Forgiardente e alla Grande Alleanza. Serve i paladini della Luce Sacra, collaborando a stretto contatto con gli altri difensori di Roccavento e trasmettendo le richieste di rinforzi ai comandanti dell'Alleanza impegnati sui fronti contro il Flagello.",al={"fazione di brandur fermartello","chi serve brandur","brandur e alleanza"}},cf78f4b8={q="Che cosa vuole Brandur Fermartello?",a="Brandur vuole far crescere una nuova generazione di paladini capaci e virtuosi, che protegga l'Alleanza e combatta le tenebre che minacciano Azeroth. A livello personale, cerca di superare i propri difetti: ha giurato alla collega Tiza Battiforgia che avrebbe cercato di vincere la sua persistente gelosia.",al={"obiettivo di brandur","che cosa vuole brandur","scopo di brandur"}},["65b7f94c"]={q="Perché Brandur Fermartello si trova a Forgiardente?",a="Presta servizio nella Hall of Mysteries come guida e istruttore per i guerrieri sacri della capitale nanica. Qui insegna discipline marziali e spirituali, mette alla prova i novizi e si coordina con i mentori di tutta l'Alleanza per assicurarsi che i cavalieri della Luce siano pronti alla battaglia.",al={"perché brandur è qui","brandur nella hall of mysteries","perché brandur è a forgiardente"}}},fp="18,108,26.330.0,26.354.0,36.98.0,52.156.0,47.168.0,49.177.0,63.204.0"}
P.entries["npc:brann-bronzebeard"] = {n="Brann Barbabronzea",s="Nel sud di Silitus, i compagni di Brann Barbabronzea attendono notizie della sua ultima spedizione. Il fratello minore di Re Magni e Muradin è famoso in tutta Azeroth come esploratore, archeologo e capo fondatore della Lega degli Esploratori. La ricerca di rovine dei titani e di storia antica lo ha condotto nel cuore delle letali distese.",h="Nel sud di Silitus, i compagni di Brann Barbabronzea attendono notizie della sua ultima spedizione.",kw={"ahn'qiraj","brann","barbabronzea","lega degli esploratori","frankal","glibb","natalia mar'alith","rutgar","vallo dello scarabeo","silitus"},ang={["faction:Alliance"]="Come membro dell'Alleanza, benefici delle conoscenze e degli archivi raccolti dalle spedizioni di Brann Barbabronzea. La sua abitudine di sparire senza lasciare traccia esaspera spesso i governanti di Forgiardente.",["race:Dwarf"]="Come nano, puoi cogliere la passione di Brann Barbabronzea per la scoperta delle radici dell'eredità titanica del suo popolo. È il fratello minore di Re Magni."},sec={{t="Un vagabondo reale",b="Brann Barbabronzea scelse le terre selvagge mentre suo fratello maggiore Magni governava Forgiardente e Muradin prestava servizio in prima linea. Veterano della Seconda Guerra, Brann rivolse le sue forze al passato dimenticato quando giunse la pace. Come capo della Lega degli Esploratori, cartografò i Regni Orientali, dalla Foresta di Elwynn alle giungle di Zul'gurub. Poi attraversò il Grande Mare per indagare i misteri dell'antica Kalimdor."},{t="Guai a Silitus",b="I rapporti del Circolo Cenariano parlavano dell'Antico Dio C'Thun e dello sciame dormiente dei qiraji. Attirarono Brann a sud, a Silitus, dove fondò l'Accampamento di Barbabronzea con Rutgar Stilaglifi e Frankal Stonebridge.\n\nLa sacerdotessa Natalia Mar'alith era impazzita a causa degli orrori che sussurravano nelle Sabbie Mutevoli. Fece irruzione nel loro accampamento e pretese che Brann li riconducesse nell'Alveare Regal. Brann rifiutò, e lei attaccò. Lui, la sua squadra e la sua scimmia da compagnia Glibb riuscirono a respingerla a stento."},{t="Oltre il Vallo dello Scarabeo",b="Brann Barbabronzea puntò al regno sigillato dietro il Vallo dello Scarabeo. Trovò un tunnel nascosto sotto l'antica barriera ed entrò da solo. Prima di partire, affidò Glibb alla spedizione con rigorosi ordini scritti: cibo in abbondanza, acqua e abbracci affettuosi.\n\nRutgar Stilaglifi e Frankal Stonebridge rimangono nel sud di Silitus. Attendono notizie di Brann dall'interno degli alveari silitidi."}},faq={{q="Chi è Brann Barbabronzea?",a="Brann Barbabronzea è il fratello minore di Re Magni Barbabronzea di Forgiardente, nonché cofondatore e forza trainante della Lega degli Esploratori dei nani. Archeologo e cartografo rinomato, percorre le frontiere più pericolose di Azeroth alla ricerca di manufatti dei titani e civiltà perdute.",al={"chi è brann","storia di brann","storia di brann barbabronzea"}},{q="Dove si trova Brann Barbabronzea in questo momento?",a="Le tracce di Brann Barbabronzea conducono a Silitus, dove Rutgar Stilaglifi e Frankal Stonebridge presidiano l'Accampamento di Barbabronzea. Potrebbero sapere qualcosa della sua ultima spedizione.",al={"posizione di brann","dove trovare brann","dove si trova brann a silitus"}},{q="Cosa è successo al suo accampamento a Silitus?",a="Rutgar Stilaglifi e Frankal Stonebridge hanno notizie preoccupanti sulla spedizione di Brann Barbabronzea. Parla con loro per scoprire cosa è successo all'accampamento.",al={"cosa è successo all'accampamento di barbabronzea","chi ha attaccato l'accampamento di brann","attacco di natalia a brann"}},{q="Chi è Glibb?",a="Glibb è la scimmia da compagnia di Brann Barbabronzea. Si trova con gli esploratori all'Accampamento di Barbabronzea, a Silitus.",al={"scimmia glibb","scimmia di brann","famiglio di brann"}},{q="Brann ha combattuto nella Seconda Guerra?",a="Sì. Brann Barbabronzea è un veterano della Seconda Guerra. In tempo di pace, rivolse le sue forze alla scoperta del passato dimenticato.",al={"brann seconda guerra","brann era nell'esercito dell'alleanza","guerra di brann e muradin"}},{q="Perché Brann è interessato a Silitus?",a="I rapporti del Circolo Cenariano sull'Antico Dio C'Thun e sullo sciame dormiente dei qiraji attirarono Brann Barbabronzea a Silitus. Il suo interesse per la storia dei titani lo spinse a cercare un passaggio oltre il Vallo dello Scarabeo sigillato e a esaminare le rovine di persona.",al={"perché brann è andato a silitus","scopo di brann a silitus","brann c'thun"}}},fp="17,330,16.414.0,19.475.1,22.402.1,25.291.0,37.165.0,38.152.0,13.115.0,34.129.0,36.240.0"}
P.entries["npc:branstock-khalder"] = {n="Branstock Khalder",s="A Forgiamara, nella Valle Crestafredda, Branstock Khalder guida i sacerdoti nani nella Sacra Luce e tiene d'occhio la minaccia dei trogg oltre l'avamposto.",h="A Forgiamara, nella Valle Crestafredda, Branstock Khalder guida i sacerdoti nani nella Sacra Luce e tiene...",kw={"forgiamara","branstock","crestafredda","dun morogh","khalder","luce","sacerdote","istruttore"},ang={["class:Priest"]="Come sacerdote, incontri Branstock Khalder, la tua prima guida spirituale. Ti insegna una prima runa sacra e ti introduce alle arti curative e difensive della Sacra Luce.",["race:Dwarf"]="Come nano, trovi in Branstock una devozione concreta alla Luce e la tenacia per resistere al freddo e alla minaccia dei trogg."},sec={{t="Una guida a Crestafredda",b="A Forgiamara, Branstock Khalder insegna ai sacerdoti novizi le prime preghiere e rune sacre. Li guida nella Luce mentre i trogg minacciano i montanari del posto. Quando un novizio ha imparato abbastanza, Branstock lo manda a Kharanos attraverso il Passo Crestafredda. Lì può ricevere ulteriore guida dal suo superiore, Padre Maxan Anvol."}},faq={{q="Chi è Branstock Khalder?",a="A Forgiamara, nella Valle Crestafredda, Branstock Khalder istruisce i giovani sacerdoti nani nella Sacra Luce e li consiglia nelle avversità della valle.",al={"storia di branstock","chi è branstock","istruttore dei sacerdoti di forgiamara"}},{q="Dove invia i suoi allievi Branstock in seguito?",a="Branstock manda i giovani sacerdoti a Kharanos attraverso il Passo Crestafredda per ricevere ulteriore guida dal suo superiore, Padre Maxan Anvol.",al={"dove andare dopo branstock","prossima missione di branstock","percorso del sacerdote da forgiamara"}},{q="Cosa preoccupa Branstock nella Valle Crestafredda?",a="Branstock è preoccupato per la crescente minaccia dei trogg nella Valle Crestafredda e per il pericolo che rappresenta per i montanari del posto.",al={"problemi di forgiamara","preoccupazioni di branstock","minaccia trogg a crestafredda"}},{q="Cosa dice a chi non è un sacerdote?",a="Branstock ti consiglia di non voltare mai le spalle alla Luce. Un giorno la fede potrebbe salvarti la vita.",al={"citazione di branstock","dialogo di branstock"}}},fx={ac45145a={q="Da che parte sta Branstock Khalder?",a="Branstock è fermamente al fianco di Forgiardente e dell'Alleanza. Come sacerdote della Luce Sacra, si dedica a formare i giovani sacerdoti nani e a proteggere la Valle Crestafredda dalle minacce esterne.",al={"fazione di branstock khalder","chi serve branstock khalder","lealtà di branstock khalder"}},["48c1936a"]={q="Che cosa vuole Branstock Khalder?",a="Branstock vuole istruire i giovani accoliti nelle vie della Luce Sacra e assicurarsi che abbiano la forza necessaria per sopravvivere fuori da Forgiamara. Vuole anche che la minaccia locale dei trogg venga sconfitta prima che travolga completamente la Valle Crestafredda.",al={"obiettivi di branstock khalder","che cosa vuole branstock","scopo di branstock khalder"}},["0b38c258"]={q="Perché Branstock Khalder si trova nella Valle Crestafredda?",a="Branstock presta servizio a Forgiamara per accogliere i sacerdoti appena risvegliati e addestrarli nelle preghiere fondamentali e nelle discipline sacre. Da questo tranquillo avamposto prepara i giovani iniziati prima di indirizzarli a Kharanos.",al={"perché branstock khalder è qui","scopo di branstock a forgiamara","perché branstock è a forgiamara"}},["15965ad4"]={q="A chi è legato Branstock Khalder?",a="Branstock è al servizio del sacerdote Maxan Anvol, suo superiore, che si trova più a valle, a Kharanos. Collabora inoltre a stretto contatto con difensori locali come Sten Braccioforte per individuare i candidati promettenti tra le nuove reclute.",al={"legami di branstock khalder","a chi fa rapporto branstock","superiore di branstock khalder"}}},fp="17,140,27.331.0,25.149.0,44.124.0,54.120.0,32.93.0"}
P.entries["npc:brave-moonhorn"] = {n="Guerriero Corno Lunare",s="Al confine meridionale delle Savane, il Guerriero Corno Lunare sorveglia il Grande Ascensore che scende a Millepicchi. Dall'alto, avverte i viaggiatori dei pericoli che li attendono.",h="Al confine meridionale delle Savane, il Guerriero Corno Lunare sorveglia il Grande Ascensore che scende a...",kw={"guerriero corno lunare","centauri","cliffwatcher longhorn","presidio di ventolibero","grande ascensore","totem truce","millepicchi"},ang={["faction:Horde"]="Corno Lunare guida i nuovi arrivati dell'Orda nel canyon verso la sicurezza e le alture fortificate del Presidio di Ventolibero.",["race:Tauren"]="In quanto tauren, potresti riconoscere nella diffidenza di Corno Lunare verso i Totem Truce un riflesso della sfiducia tra le tribù tradizionali di Cairne Zoccolo Sanguinario e i riservati Totem Truce."},sec={{t="Sentinella dell'Ascensore",b="Il Guerriero Corno Lunare sorveglia il confine tra le pianure settentrionali e le terre dei canyon. Dall'alto di Millepicchi, scruta il fondo del canyon in cerca di minacce, soprattutto clan di centauri ostili. I viaggiatori lo incontrano spesso prima di scendere tra le guglie. Li avverte dei pericoli prima che mettano piede sulle imponenti piattaforme del Grande Ascensore."},{t="Ombre inquietanti",b="Il Guerriero Corno Lunare diffida dei tauren Totem Truce. Dice agli alleati dell'Orda in viaggio di tenersi a distanza, perché la tribù si comporta in modo incostante e sospetto nei dintorni di Millepicchi. Per contribuire alla difesa della regione, invia corrieri al Presidio di Ventolibero con avvertimenti per Cliffwatcher Longhorn."}},faq={{q="Chi è il Guerriero Corno Lunare?",a="Il Guerriero Corno Lunare è un guerriero ed esploratore tauren che sorveglia l'accesso al Grande Ascensore tra le Savane e Millepicchi. Tiene d'occhio le attività nemiche e avverte i viaggiatori di passaggio dei pericoli nelle vicinanze.",al={"ruolo di guerriero corno lunare","chi è corno lunare","guardia tauren dell'ascensore"}},{q="Perché Corno Lunare mette in guardia contro i Totem Truce?",a="Corno Lunare mette in guardia dai Totem Truce perché si comportano in modo strano e imprevedibile nel canyon circostante. Pur facendo parte della comunità tauren, la loro chiusura aggressiva li rende inaffidabili agli occhi delle guardie che mantengono l'ordine lungo il sentiero.",al={"avvertimento sui totem truce","perché evitare i totem truce","corno lunare totem truce"}},{q="Quale messaggio vuole che venga recapitato al Presidio di Ventolibero?",a="Corno Lunare vuole che si sparga la voce sull'aumento delle attività dei centauri a Millepicchi. Chiede a fidati messaggeri dell'Orda di recapitare l'avvertimento a Cliffwatcher Longhorn al Presidio di Ventolibero.",al={"messaggio per il presidio di ventolibero","qual è il messaggio di corno lunare","storia di message to freewind post"}},{q="Dove si trova il Guerriero Corno Lunare?",a="Il Guerriero Corno Lunare si trova vicino al margine dell'altopiano in cima al Grande Ascensore, sul confine tra le Savane e Millepicchi.",al={"dove si trova corno lunare","posizione di guerriero corno lunare","guardia del grande ascensore"}}},fx={["9347caaf"]={q="Da che parte sta il Guerriero Corno Lunare?",a="Il Guerriero Corno Lunare serve Picco del Tuono e l'Orda. Di stanza in cima al Grande Ascensore tra The Barrens e Millepicchi, sorveglia il confine e indica agli avventurieri dell'Orda in viaggio come raggiungere in sicurezza il canyon sottostante.",al={"il guerriero corno lunare è dell'orda","fazione del guerriero corno lunare","chi serve corno lunare"}},ff589928={q="Perché il Guerriero Corno Lunare è di stanza al Grande Ascensore?",a="Corno Lunare è appostato sul precipizio dei Millepicchi per sorvegliare la discesa e tenere d'occhio i pericoli nelle vicinanze. Da questo punto panoramico controlla l'aggressività dei centauri e gli spostamenti inquietanti del clan Totem Truce, assicurandosi che i viaggiatori in discesa nel canyon siano avvertiti come si deve.",al={"perché corno lunare è qui","che cosa fa corno lunare all'ascensore","perché il guerriero corno lunare è al grande ascensore"}},["4ac94a87"]={q="A chi è legato il Guerriero Corno Lunare?",a="Corno Lunare risponde ai capi tauren di Picco del Tuono e collabora a stretto contatto con Cliffwatcher Longhorn al Presidio di Ventolibero. Quando si agitano pericoli lungo i percorsi del canyon, è da Longhorn, il comandante, che riceve istruzioni e a cui trasmette i suoi rapporti di ricognizione.",al={"alleati di corno lunare","a chi fa rapporto corno lunare","legami del guerriero corno lunare"}}},fp="14,148,20.330.0,14.281.0,22.203.0,45.239.0,53.177.0,32.133.0"}
P.entries["npc:brewmaster-drohn"] = {n="Mastro Birraio Drohn",s="Sulla collina sopra Porto Paranco, il Mastro Birraio Drohn coltiva l'arte della birrificazione. L'orco vive appena sopra il porto e usa metodi legati al pandaren errante Chen Stormstout. I viaggiatori che trovano barili abbandonati in tutta Kalimdor vengono indirizzati al portico di Drohn.",h="Sulla collina sopra Porto Paranco, il Mastro Birraio Drohn coltiva l'arte della birrificazione.",kw={"savane","mastro birraio","chen stormstout","drohn","porto paranco","birra dei trogg"},ang={["faction:Alliance"]="Se sei un avventuriero dell'Alleanza, sappi che Steamwheedle protegge Drohn a Porto Paranco. Attaccalo e le autorità goblin locali ti si rivolteranno contro.",["profession:Cooking"]="Se pratichi la cucina, Drohn combina flora e fauna rare per creare bevande pregiate nel deserto.",["race:Orc"]="Come orco, potresti vedere nella birrificazione di Drohn un modo per trasformare la pace a Durotar e nelle Savane in un mestiere. Molti guerrieri costruirono fortezze dopo aver seguito Thrall a Kalimdor."},sec={{t="Un maestro del mestiere a Porto Paranco",b="Il Mastro Birraio Drohn produce birra nella sua casa sulla collina sopra i moli goblin di Porto Paranco. L'orco ha scelto la birrificazione al posto del combattimento e vive nel rifugio neutrale fondato dal Cartello degli Spargifumo di Sparachiodi. Molti orchi prediligono grog grezzo o semplici liquori. Drohn lavora invece con ingredienti rari, sapori equilibrati e metodi poco praticati tra i suoi simili."},{t="Il legame con i pandaren",b="Il Mastro Birraio Drohn ha imparato a produrre birra da un mentore che ha studiato sotto Chen Stormstout. Il pandaren errante combatté al fianco di Rexxar e dell'Orda durante la fondazione di Durotar. Chen ha anche insegnato a Drohn a preparare la Birra dei Trogg. Quando i viaggiatori trovano i barili abbandonati di Chen nelle terre selvagge, Drohn è l'esperto locale che sa identificarne gli ingredienti e ricreare le potenti birre del girovago."}},faq={{q="Chi è il Mastro Birraio Drohn?",a="Il Mastro Birraio Drohn produce birra a Porto Paranco, nelle Savane. L'orco è noto per le sue birre esotiche e i legami con le tradizioni birrarie del pandaren errante Chen Stormstout.",al={"storia di drohn","chi è drohn","mastro birraio di porto paranco"}},{q="Come fa Drohn a conoscere Chen Stormstout?",a="Drohn ha imparato da un mentore a cui Chen Stormstout aveva insegnato a preparare la Birra Triplo Malto. Chen ha anche insegnato a Drohn a preparare la Birra dei Trogg.",al={"legame con chen","come conosce chen","drohn e chen"}},{q="Cosa devo fare se trovo il Barile Vuoto di Chen?",a="Porta il Barile Vuoto di Chen al Mastro Birraio Drohn a Porto Paranco. Riconosce il lavoro di Chen e ti manda a cercare i rari ingredienti locali necessari per ricreare la birra.",al={"chen's empty keg","trovato barile vuoto","missione del barile"}},{q="Il Mastro Birraio Drohn è schierato con l'Orda?",a="Sì. Drohn è un orco dell'Orda, anche se vive e produce birra a Porto Paranco, un porto goblin neutrale. Attaccarlo danneggia la reputazione di un avventuriero dell'Alleanza presso Porto Paranco e il Cartello degli Spargifumo.",al={"drohn è dell'orda","drohn è neutrale","fazione di drohn"}},{q="Che tipo di bevande prepara Drohn?",a="Drohn produce birre potenti, tra cui la Birra dei Trogg e la Birra Triplo Malto, che prende il nome da Chen Stormstout. Richiedono zanne, ghiandole e altre parti di bestie che si trovano in tutte le Savane.",al={"ricette di drohn","birre della distilleria di drohn"}},{q="Dove si trova esattamente Drohn?",a="Trovi Drohn fuori dalla sua casa sulla collina che domina Porto Paranco, poco a nordovest dei moli principali, nelle Savane.",al={"posizione di drohn","dove si trova drohn","trova mastro birraio drohn"}}},fx={["2bb5b883"]={q="Che cosa vuole Mastro Birraio Drohn?",a="Drohn si dedica a perfezionare la sua arte e a mettere a punto ricette esotiche e potenti. Quando i viaggiatori trovano i fusti vuoti lasciati da Chen Triplo Malto, il pandaren errante, Drohn cerca ingredienti rari nelle Savane, come zanne di leone della savana, reni di plainstrider e un corno di sauro del tuono, per ricreare le birre leggendarie e onorare le tradizioni brassicole che gli sono state tramandate.",al={"che cosa vuole drohn","obiettivi di drohn","perché aiutare drohn"}},e385fb6c={q="Perché Mastro Birraio Drohn si trova a Porto Paranco?",a="Drohn gestisce la sua distilleria alla periferia di Porto Paranco, sfruttando appieno il vivace porto dei goblin. La neutralità della città e il suo intenso commercio portano viaggiatori, rifornimenti esotici e clienti curiosi da ogni parte di Azeroth fin sulla sua soglia, offrendogli sia un mercato ricettivo per la sua birra sia accesso alle terre selvagge delle Savane, dove procurarsi gli ingredienti.",al={"perché drohn è qui","perché drohn è a porto paranco","motivo della presenza di drohn"}}},fp="16,250,32.335.0,23.374.0,24.161.0,36.127.0,44.162.0,43.191.0,36.170.0,31.110.0"}
P.entries["npc:brewmeister-bilger"] = {n="Mastro Birraio Bilger",s="Nella cantina della locanda di Riva del Sud, il Mastro Birraio Bilger attende consegne da terre lontane. Il nano ebbro trascorre le ore degustando liquori forti.",h="Nella cantina della locanda di Riva del Sud, il Mastro Birraio Bilger attende consegne da terre lontane.",kw={"bilger","mastro birraio bilger","alture di colletorto","cantina della locanda","mackreel","riva del sud"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi trovare Bilger nella cantina della locanda di Riva del Sud. È uno dei nani che vivono tra gli umani di questa città assediata.",["race:Dwarf"]="Come nano, puoi vedere quanto sia vivo l'amore di Bilger per gli alcolici forti in una città portuale umana lontana da Forgiardente."},sec={{t="Vita nella cantina",b="Sotto la locanda di Riva del Sud, il Mastro Birraio Bilger fa avanti e indietro per la cantina con il singhiozzo. Cerca le bevande più forti che Azeroth possa offrire."},{t="Un gusto per le importazioni potenti",b="Anche intontito dall'alcol, il Mastro Birraio Bilger sa valutare i liquori. Predilige i corposi distillati nanici e i liquori forti del sud. Le produzioni speciali lo deliziano, come il distillato che Foggy MacKreel gli invia dal Viadotto di Thandol."}},faq={{q="Dove posso trovare il Mastro Birraio Bilger?",a="Trovi il Mastro Birraio Bilger nella cantina sotto la locanda di Riva del Sud, la città portuale dell'Alleanza nelle Alture di Colletorto.",al={"posizione di bilger","dove si trova bilger","nano cantina riva del sud"}},{q="Quali missioni coinvolgono il Mastro Birraio Bilger?",a="Il Mastro Birraio Bilger riceve liquori rari dalle Paludi Grigie, tra cui distillati forti come il Torcibudella di MacKreel, spediti a nord verso Riva del Sud.",al={"missione bilger","missione torcibudella di mackreel"}}},fx={["5541902b"]={q="Perché Mastro Birraio Bilger si trova qui?",a="Bilger ha fatto della cantina della locanda di Riva del Sud la propria casa e trascorre le giornate tra le botti, in compagnia dei suoi liquori forti e del distillato clandestino che gli devono amici come Foggy MacKreel.",al={"perché bilger è a riva del sud","che cosa fa bilger qui","perché mastro birraio bilger è qui"}},["0436bf77"]={q="Chi è Mastro Birraio Bilger?",a="Mastro Birraio Bilger è un birraio nano che trascorre le giornate a bere nella cantina della locanda di Riva del Sud, singhiozzando dopo aver bevuto superalcolici e aspettando il distillato clandestino che gli devono amici come Foggy MacKreel.",al={"chi è bilger","identità di mastro birraio bilger","chi è mastro birraio bilger"}},["29798063"]={q="Da che parte sta Mastro Birraio Bilger?",a="Bilger è schierato con l'Alleanza e con la città di Riva del Sud. Nano di Forgiardente, vive tranquillamente tra gli abitanti del luogo, anche se preferisce la quieta compagnia delle botti in cantina ai doveri civici.",al={"fazione di bilger","bilger è dell'alleanza","da che parte sta bilger"}}},fp="18,150,18.123.0,26.214.0,36.115.0,39.142.0"}
P.entries["npc:brine"] = {n="Brine",s="A Blackthorn Ridge, Brine guida gli iniziati sciamani verso gli spiriti dell'acqua. Insegna loro a entrare in comunione con le maree e a guadagnarsi il Totem dell'Acqua.",h="A Blackthorn Ridge, Brine guida gli iniziati sciamani verso gli spiriti dell'acqua.",kw={"savane","blackthorn ridge","brine","call of water","sciamano","mulino di tarren","totem dell'acqua"},ang={["class:Shaman"]="Brine ti guida attraverso prove di resistenza e di spirito prima che tu possa entrare in comunione con l'acqua e ottenere il tuo Totem dell'Acqua.",["faction:Horde"]="Veterana delle guerre a Colletorto, Brine serve l'Orda tramandando alle nuove generazioni il retaggio spirituale degli elementi."},sec={{t="L'Eremita della Cresta",b="Brine vive su una collina nella parte settentrionale di Blackthorn Ridge, lontano dagli avamposti commerciali delle Savane. Benché sia circondata da aride savane, ha dedicato la vita a comprendere l'acqua. Gli sciamani di tutta l'Orda cercano la sua saggezza dopo aver padroneggiato la terra e il fuoco. Insegna che l'acqua richiede pazienza e capacità di vedere le cose in prospettiva, qualità che pochi comprendono a fondo quanto lei."},{t="Ricordi dei Regni Orientali",b="In gioventù, Brine marciò con i suoi compagni orchi attraverso le Alture di Colletorto e combatté contro gli insediamenti umani. Durante la campagna, giunse a Mulino di Tarren e trovò un umile pozzo alimentato da fresca acqua sorgiva. Quel pozzo le rimase impresso nella memoria come un segno di vita in mezzo alla devastazione. Rafforzò una lezione che aveva imparato da bambina: anche nel dolore più cupo, si può ancora trovare un piccolo segno di speranza."},{t="Call of Water",b="Brine mette alla prova gli aspiranti sciamani con pellegrinaggi per raccogliere gocce d'acqua pura da fonti diverse. Le sue prove insegnano che l'acqua può essere dolce eppure inflessibile. Nei suoi rituali, gli sciamani entrano in comunione con gli spiriti elementali e legano l'essenza ristoratrice dell'acqua al proprio focus totemico."}},faq={{q="Chi è Brine?",a="Brine è un'esperta sciamana orca che vive sola su una collina nella parte settentrionale di Blackthorn Ridge, nelle Savane Meridionali. Guida gli iniziati che cercano la comunione con gli spiriti dell'acqua.",al={"storia di brine","chi è brine","orco a blackthorn ridge"}},{q="Perché una sciamana dell'acqua vive in un deserto?",a="Le Savane sono aride, ma la solitudine permette a Brine di entrare in profonda comunione con gli elementi, lontano dal frastuono degli insediamenti.",al={"perché nelle savane","perché brine vive nel deserto"}},{q="Qual è il legame di Brine con Mulino di Tarren?",a="Anni fa, Brine combatté al fianco dei guerrieri dell'Orda nelle Alture di Colletorto ed entrò a Mulino di Tarren. Lì trovò un piccolo pozzo di pura acqua sorgiva, un segno duraturo di vita e speranza tra le rovine della guerra.",al={"pozzo di mulino di tarren","brine colletorto","passato di brine"}},{q="Qual è il ruolo di Brine nell'addestramento degli sciamani?",a="Brine guida gli iniziati attraverso le fasi delle prove di Call of Water. Li manda a raccogliere acqua pura da fonti diverse e insegna loro umiltà e tenacia prima che acquisiscano la comprensione necessaria per il Totem dell'Acqua.",al={"missione sciamano brine","come ottenere il totem dell'acqua","call of water brine"}},{q="Dove si trova esattamente Brine?",a="Brine vive in cima a un'altura scoscesa nella parte settentrionale di Blackthorn Ridge, nelle Savane Meridionali, appena a nord delle Gallerie di Lamaspina.",al={"posizione di brine","dove si trova brine","trovare brine nelle savane"}},{q="Quale filosofia guida i suoi insegnamenti?",a="Brine insegna che anche nel dolore e nella sofferenza si possono trovare speranza e rinnovamento. L'acqua rappresenta la vita e la perseveranza nelle prove più dure.",al={"filosofia di brine","insegnamenti dell'acqua"}}},fx={["452ad9e3"]={q="Da che parte sta Brine?",a="Brine è fedele all'Orda e condivide la sua profonda saggezza spirituale con gli aspiranti sciamani dell'Orda che cercano di padroneggiare gli elementi. Anche se vive in isolamento tra le colline delle Savane Meridionali, lontano da una fortezza brulicante di vita, è una guida fondamentale per le tradizioni sciamaniche coltivate nel nuovo regno di Thrall.",al={"fazione di brine","brine è dell'orda","chi serve brine"}},a90c6b58={q="Che cosa vuole Brine?",a="Brine vuole guidare gli aspiranti sciamani verso la comprensione della duplice natura dell'acqua: la sua limpidezza serena, fonte di vita, e la sua furia, una forza inarrestabile. Invece di limitarsi a trasmettere il proprio potere, si aspetta che i viandanti affrontino rigorosi pellegrinaggi verso fonti di Acqua Pura sparse per Kalimdor e i Regni Orientali, per imparare la resilienza e la comunione con gli spiriti elementali.",al={"obiettivo di brine","che cosa fa brine","perché aiutare gli sciamani"}}},fp="5,150,19.350.0,32.405.0,17.266.1,13.174.0,41.120.0,42.205.0,45.222.0,31.114.0,37.135.0"}
P.entries["npc:brock-stoneseeker"] = {n="Brock Scrutarocce",s="A Thelsamar, Brock Scrutarocce insegna l'estrazione mineraria ai cercatori alle prime armi. Nella sua School of Mining and Surveying, li addestra a individuare ed estrarre minerali e metalli grezzi.",h="A Thelsamar, Brock Scrutarocce insegna l'estrazione mineraria ai cercatori alle prime armi.",kw={"brock scrutarocce","loch modan","istruttore di estrazione","scuola di estrazione","thelsamar"},ang={["profession:Mining"]="Come minatore a Loch Modan, puoi trovare Brock Scrutarocce a Thelsamar per iniziare o proseguire il tuo addestramento nell'estrazione e nella fusione dei minerali della regione.",["race:Dwarf"]="Come nano di Khaz Modan, erediti una tradizione fondata sulla pietra e sul metallo. Istruttori come Brock contribuiscono a mantenere vive le tradizioni artigianali di Forgiardente."},sec={{t="Maestro di Estrazione e Perizia Mineraria",b="A Thelsamar, Brock Scrutarocce istruisce i minatori nella sua School of Mining and Surveying. Le colline di Loch Modan custodiscono ricchi filoni minerari, e ai minatori servono una mano salda sul piccone e un occhio attento alla roccia. Brock insegna loro a trovare minerali, estrarre metalli grezzi e rilevare giacimenti sotterranei. Le sue lezioni aiutano gli artigiani dell'Alleanza a rifornire le fucine di Forgiardente."}},faq={{q="Chi è Brock Scrutarocce?",a="Brock Scrutarocce addestra i minatori a Thelsamar, a Loch Modan. Nella sua School of Mining and Surveying, insegna agli artigiani a estrarre minerali e rilevare giacimenti minerari.",al={"brock scrutarocce","chi è brock","brock thelsamar"}},{q="Dove si trova Brock Scrutarocce?",a="Brock Scrutarocce si trova a Thelsamar, il principale centro abitato nanico di Loch Modan. Gestisce la sua scuola mineraria vicino agli artigiani locali.",al={"dove si trova brock","posizione brock scrutarocce","mappa brock"}},{q="Quale professione insegna Brock?",a="Brock Scrutarocce insegna Estrazione. Mostra ai viaggiatori come raccogliere pietra grezza, rame e altri minerali per principianti che si trovano nelle campagne di Khaz Modan.",al={"cosa insegna brock","tipo di istruttore brock","istruttore di estrazione thelsamar"}},{q="Che cos'è la Brock's School of Mining and Surveying?",a="La Brock's School of Mining and Surveying è una scuola di formazione a Thelsamar. Brock insegna ai cercatori a estrarre minerali in sicurezza e a interpretare i filoni sotterranei tra le montagne.",al={"scuola di brock","scuola di estrazione thelsamar"}}},fx={["38215f8d"]={q="Da che parte sta Brock Scrutarocce?",a="Brock Scrutarocce è fermamente schierato con i nani di Forgiardente e la Gran Alleanza. Operando dal tranquillo insediamento di Thelsamar, a Loch Modan, serve gli alpinisti e i viandanti di Khaz Modan, formando abili minatori che esplorano le aspre colline della patria dei nani.",al={"fazione di brock scrutarocce","brock scrutarocce è dell'alleanza","chi serve brock scrutarocce"}},["53fa3834"]={q="Perché Brock Scrutarocce si trova qui?",a="Brock vive a Thelsamar per dirigere la Scuola di estrazione mineraria e rilevamento di Brock. Le scogliere e le montagne che circondano Loch Modan sono ricche di pietra grezza e filoni minerari, il che rende il luogo ideale per istruire gli aspiranti minatori e mandarli a esplorare le rupi circostanti.",al={"perché brock scrutarocce è a thelsamar","perché brock è qui","perché brock è andato a loch modan"}},["7d1f98e6"]={q="Che cosa vuole Brock Scrutarocce?",a="Brock vuole insegnare ai nuovi arrivati l'essenziale arte nanica dell'estrazione mineraria e rendere onore agli allievi più devoti della sua scuola. Vuole assicurarsi che i cercatori partano ben equipaggiati verso le aspre terre selvagge di Khaz Modan, per trovare ricchi filoni di minerale e rilevare il territorio.",al={"che cosa vuole brock scrutarocce","obiettivi di brock scrutarocce","che cosa vuole brock"}}},fp="17,162,30.348.0,25.165.0,37.133.0,33.149.0,47.179.0"}
P.entries["npc:bromos-grummner"] = {n="Bromos Grummner",s="A Forgiamara, Bromos Grummner guida i giovani paladini nani nella Sacra Luce e li accoglie nella sua disciplina. Insegna loro una fede incrollabile e il legame tra nani e umani nei Cavalieri della Mano d'Argento.",h="A Forgiamara, Bromos Grummner guida i giovani paladini nani nella Sacra Luce e li accoglie nella sua...",kw={"forgiamara","bromos","crestafredda","dun morogh","grummner","paladino","mano d'argento","istruttore"},ang={["class:Paladin"]="Come paladino nano, puoi rivolgerti a Bromos come tuo primo mentore spirituale. Ti introduce ai sacri doveri della Mano d'Argento.",["race:Dwarf"]="Come nano, segui una lunga tradizione di devozione alla Luce e combatti al fianco dei tuoi alleati umani."},sec={{t="Un faro a Crestafredda",b="A Forgiamara, Bromos insegna ai giovani paladini i riti di battaglia e le sacre invocazioni. Eppure non parla solo di combattimento. I Cavalieri della Mano d'Argento uniscono Forgiardente e i regni umani dell'Alleanza in un comune e giusto proposito."}},faq={{q="Chi è Bromos Grummner?",a="Bromos Grummner addestra i nuovi paladini nani a Forgiamara, nella Valle Crestafredda, a Dun Morogh. Offre loro addestramento di base, incantesimi e guida spirituale.",al={"chi è bromos","storia di bromos grummner","istruttore dei paladini di forgiamara"}},{q="Quale ordine rappresenta Bromos?",a="Bromos rappresenta i Cavalieri della Mano d'Argento. Insegna il legame tra umani e nani, forgiato sotto lo stendardo del sacro ordine.",al={"bromos mano d'argento","bromos appartiene alla mano d'argento"}},{q="Cosa insegna alle nuove reclute?",a="Bromos insegna ai nuovi paladini le arti del combattimento di base e gli incantesimi divini. Assegna agli iniziati le prime prove, affinché dimostrino la loro devozione alla Luce e la loro preparazione a proteggere Dun Morogh.",al={"missioni di bromos","cosa fa bromos grummner"}}},fx={["73c3e4de"]={q="Da che parte sta Bromos Grummner?",a="Bromos è fermamente schierato con Forgiardente e la Gran Alleanza. Devoto membro dei Cavalieri della Mano d'Argento, attribuisce un enorme valore al duraturo legame tra nani e umani e crede che la loro fede condivisa nella Luce Sacra sia fondamentale per mantenere uniti i loro regni.",al={"fazione di bromos grummner","bromos è dell'alleanza","per chi combatte bromos"}},["830a5136"]={q="Perché Bromos Grummner si trova nella Valle Crestafredda?",a="Bromos è di stanza a Forgiamara per istruire i paladini nani novizi che rispondono al richiamo della Luce Sacra. Tra il freddo incalzante e le minacce dei trogg locali, si assicura che ogni aspirante difensore impari a usare le proprie abilità marziali e le benedizioni della giustizia al servizio del proprio popolo.",al={"perché bromos è a forgiamara","scopo di bromos grummner","che cosa fa bromos qui"}},["33b2371f"]={q="Che cosa vuole Bromos Grummner?",a="Bromos vuole formare una generazione di paladini nani disciplinata e inflessibile. Mira a instillare nei suoi allievi non solo la padronanza dei poteri sacri della Luce, ma anche una profonda dedizione alla sacra alleanza tra nani e umani nella Mano d'Argento.",al={"che cosa vuole bromos","obiettivi di bromos","motivazione di bromos"}}},fp="15,215,21.238.0,23.157.0,33.137.0,32.179.0"}
P.entries["npc:brother-joshua"] = {n="Fratello Joshua",s="Nella Cathedral of Light di Roccavento, il Fratello Joshua guida chi viene ad apprendere le vie della Sacra Luce. Addestra i sacerdoti novizi a curare le ferite e rafforzare i propri alleati.",h="Nella Cathedral of Light di Roccavento, il Fratello Joshua guida chi viene ad apprendere le vie della Sacra...",kw={"fratello joshua","cathedral of light","sacra luce","sacerdote umano","istruttore dei sacerdoti","roccavento"},ang={["class:Priest"]="Come sacerdote, puoi studiare la Sacra Luce con il Fratello Joshua a Roccavento. Man mano che progredisci, ti insegna nuove preghiere e discipline.",["faction:Alliance"]="Come membro dell'Alleanza, puoi trovare Joshua nella Cathedral of Light di Roccavento, nel cuore del tuo regno."},sec={{t="Un mentore nella cattedrale",b="Il Fratello Joshua attende vicino all'altare principale nella Cathedral of Light di Roccavento. Come sacerdote della Chiesa della Luce Sacra, insegna ai nuovi servitori della fede a curare, erigere protezioni e concentrarsi per entrare in comunione con la Luce. I giovani sacerdoti umani che iniziano il loro servizio per l'Alleanza trovano in lui una delle loro prime guide."}},faq={{q="Chi è il Fratello Joshua?",a="Il Fratello Joshua è un sacerdote umano e un istruttore della Chiesa della Luce Sacra. Nella Cathedral of Light di Roccavento, insegna agli aspiranti sacerdoti i loro incantesimi, rituali e doveri sacri.",al={"chi è fratello joshua","ruolo di fratello joshua","joshua sacerdote"}},{q="Dove posso trovare il Fratello Joshua?",a="Il Fratello Joshua attende vicino all'altare maggiore, verso il fondo della Cathedral of Light, in Piazza della Cattedrale a Roccavento.",al={"posizione di fratello joshua","dove si trova fratello joshua","dove si trova joshua"}},{q="Quali servizi offre?",a="Il Fratello Joshua insegna ai sacerdoti nuovi gradi di incantesimi divini e di guarigione. Può anche reimpostare i loro talenti spirituali.",al={"cosa fa joshua","addestramento di fratello joshua","joshua può addestrarmi"}}},fx={cce3d5dc={q="Da che parte sta Fratello Joshua?",a="Fratello Joshua serve la Chiesa della Luce Sacra ed è fermamente schierato con la Gran Alleanza. Devoto agli insegnamenti della Luce, presta servizio sotto gli archi della Cathedral of Light di Roccavento, offrendo guida e sostegno spirituali ai suoi concittadini e ai viaggiatori dell'Alleanza.",al={"fedeltà di fratello joshua","fazione di fratello joshua","chi serve fratello joshua"}},["2e9120b0"]={q="Che cosa vuole Fratello Joshua?",a="Fratello Joshua vuole diffondere i principi della Luce Sacra e guidare gli accoliti promettenti nella loro sacra vocazione. Dedica le proprie giornate ad addestrare i sacerdoti novizi, ad approfondire la loro comunione con la Luce e ad assicurarsi che i fedeli di Roccavento restino saldi nei momenti difficili.",al={"obiettivo di fratello joshua","che cosa cerca di fare fratello joshua","scopo di fratello joshua"}},["2e708272"]={q="Perché Fratello Joshua si trova qui?",a="Di stanza nella Cathedral of Light di Roccavento, Fratello Joshua svolge i propri doveri presso l'altare in qualità di istruttore ordinato del sacerdozio. Da questa sede di autorità spirituale, fa da mentore a chi è chiamato a vestire l'abito sacerdotale e offre aiuto ai visitatori in cerca della saggezza della Luce.",al={"perché fratello joshua è a roccavento","perché fratello joshua è nella cattedrale","motivo della presenza di fratello joshua"}},["5cfd3f6a"]={q="A chi è legato Fratello Joshua?",a="Fratello Joshua è legato al clero della Chiesa della Luce Sacra e collabora con i sacerdoti e i paladini che prestano servizio nella Cathedral of Light. In virtù dei suoi doveri clericali, mantiene rapporti anche con altre organizzazioni, come il Circolo Cenariano, quando il dovere richiede aiuto reciproco.",al={"legami di fratello joshua","chiesa di fratello joshua","a chi risponde fratello joshua"}}},fp="14,177,25.338.0,22.182.0,32.122.0,28.117.0"}
P.entries["npc:brother-kristoff"] = {n="Fratello Kristoff",s="In Piazza della Cattedrale, Fratello Kristoff predica ai piedi della statua di Uther. Il sacerdote umano cerca libri pratici per i suoi sermoni sulla forza spirituale.",h="In Piazza della Cattedrale, Fratello Kristoff predica ai piedi della statua di Uther.",kw={"fratello kristoff","cathedral of light","piazza della cattedrale","fortitudine","kristoff","stresses of iron","statua di uther"},ang={["class:Priest"]="Come sacerdote, potresti apprezzare l'approccio concreto di Fratello Kristoff alla liturgia. Attinge alle arti pratiche per insegnare i misteri più profondi della forza interiore.",["profession:Blacksmithing"]="Come fabbro, potresti trovare divertente che un chierico della Luce ricorra a libri sulle sollecitazioni del ferro e sulla metallurgia per insegnare la resilienza al clero."},sec={{t="Un predicatore accanto alla statua",b="Fratello Kristoff serve la Chiesa della Sacra Luce in Piazza della Cattedrale, ai piedi della statua di Uther the Lightbringer. Opera tra i cittadini e i pellegrini che attraversano la piazza, anziché all'interno della Cathedral of Light.\n\nPer sermoni come quello sulla Fortitudine dello Spirito, ricorre a paragoni terreni. In The Stresses of Iron trova un modo per spiegare come l'anima resista alle pressioni. Insegna che la determinazione interiore donata dalla Sacra Luce è come la resistenza temprata del metallo lavorato."}},faq={{q="Chi è Fratello Kristoff?",a="Fratello Kristoff è un sacerdote umano e uno studioso della Chiesa della Sacra Luce. Opera all'aperto in Piazza della Cattedrale a Roccavento, vicino alla grande statua di Uther the Lightbringer.",al={"storia di fratello kristoff","chi è kristoff","kristoff roccavento"}},{q="Cosa fa Fratello Kristoff in Piazza della Cattedrale?",a="Fratello Kristoff prepara sermoni sulla Luce e sulla fede. Sta lavorando a un sermone sulla Fortitudine dello Spirito e cerca libri di metallurgia per spiegare la resilienza spirituale.",al={"scopo di kristoff","ruolo di kristoff","perché fratello kristoff si trova all'aperto"}},{q="Perché Fratello Kristoff ha bisogno di un libro sul ferro?",a="Fratello Kristoff cerca The Stresses of Iron per il suo sermone sulla forza d'animo. Usa il ferro sottoposto a sollecitazioni per mostrare come la devozione alla Sacra Luce rafforzi lo spirito mortale contro le avversità.",al={"the stresses of iron","libro speaking of fortitude","perché kristoff vuole la metallurgia"}}},fx={["610da828"]={q="Da che parte sta Fratello Kristoff?",a="Fratello Kristoff serve la Chiesa della Luce Sacra e l'Alleanza. In quanto membro del sacerdozio, è devoto alla Luce Sacra e alla guida spirituale del popolo di Roccavento, prestando fedelmente servizio all'ombra della Cathedral of Light.",al={"fazione di fratello kristoff","chi serve fratello kristoff","fratello kristoff è dell'alleanza"}},["8237c000"]={q="A chi è legato Fratello Kristoff?",a="Fratello Kristoff fa parte del clero della Chiesa della Luce Sacra e ha sede nella Cathedral of Light di Roccavento. Collabora con gli altri sacerdoti e paladini in Piazza della Cattedrale per occuparsi dei bisogni spirituali dei cittadini e dei difensori del regno.",al={"legami di fratello kristoff","chiesa di fratello kristoff","con chi è affiliato fratello kristoff"}}},fp="16,144,24.495.0,24.179.0,50.180.0,49.186.0"}
P.entries["npc:brother-neals"] = {n="Fratello Neals",s="All'Abbazia della Contea del Nord, Fratello Neals mantiene rifornite le scorte di cibo e bevande. Supervisiona le spedizioni e assaggia il vino del vigneto locale.",h="All'Abbazia della Contea del Nord, Fratello Neals mantiene rifornite le scorte di cibo e bevande.",kw={"fratello neals","foresta di elwynn","bollettino dell'uva","abbazia della contea del nord","valle della contea del nord","vigneto","vino"},ang={["profession:Cooking"]="Occupandosi delle provviste e degli alcolici del monastero, Fratello Neals svolge un ruolo legato alle arti culinarie."},sec={{t="Custode della Cantina",b="Dalle sue stanze nella parte alta del campanile, Fratello Neals controlla i registri delle spedizioni d'uva dalle Vigne della Contea del Nord. Le frequenti degustazioni gli permettono di verificare ogni annata. Tiene anche traccia delle consegne dai campi della valle, mantenendo rifornite le scorte dell'abbazia."}},faq={{q="Chi è Fratello Neals?",a="Fratello Neals gestisce le scorte di cibo, bevande e vino dell'Abbazia della Contea del Nord per il clero e le reclute della valle.",al={"fratello neals","neals","chi è neals"}},{q="Dove si trova Fratello Neals?",a="Fratello Neals alloggia nella stanza più alta dell'Abbazia della Contea del Nord. Sali le scale di pietra all'interno della sala principale per raggiungere la sua tranquilla camera vicino alla cima della torre.",al={"dove si trova fratello neals","posizione di fratello neals","trova neals"}},{q="Qual è il suo ruolo per quanto riguarda il vigneto?",a="Fratello Neals tiene traccia dei raccolti d'uva e delle spedizioni di vino dalla vicina Northshire Vineyard. Assaggia il vino dell'annata e tiene i registri.",al={"missione bollettino dell'uva","vino di neals","cosa fa neals"}}},fx={["340be3c1"]={q="Da che parte sta Fratello Neals?",a="Fratello Neals è un membro leale della Confraternita della Contea del Nord e serve l'Abbazia della Contea del Nord e la Gran Alleanza di Roccavento. Svolge pacificamente i propri doveri clericali tra le mura dell'abbazia.",al={"fazione di fratello neals","chi serve fratello neals","fratello neals è dell'alleanza"}},["0d7c1646"]={q="Che cosa vuole Fratello Neals?",a="Fratello Neals deve tenere una contabilità accurata delle provviste della Contea del Nord, in particolare delle scorte di vino provenienti dal vigneto locale. Vuole che gli vengano portati direttamente nei suoi alloggi le forniture e i registri, come il Bollettino dell'Uva, così da poter gestire le scorte e gustare un generoso assaggio del vino d'annata dell'abbazia.",al={"bollettino dell'uva di fratello neals","di che cosa ha bisogno fratello neals"}},bb6478cd={q="Perché Fratello Neals si trova qui?",a="In quanto fratello dell'abbazia, Neals risiede nella tranquilla torre superiore dell'Abbazia della Contea del Nord, dove sorveglia le scorte di cibo e bevande della comunità. La sua posizione lo tiene vicino alle riserve della cantina e ai documenti contabili necessari per sostenere il clero e le nuove reclute.",al={"perché fratello neals è nella torre","perché fratello neals è alla contea del nord"}}},fp="13,140,20.243.0,21.117.0,33.161.0,40.137.0"}
P.entries["npc:brother-sarno"] = {n="Fratello Sarno",s="Alla Cathedral of Light di Roccavento, Fratello Sarno accoglie visitatori e fedeli. Invia anche i viaggiatori dell'Alleanza a Forgiardente, dove Tinkmaster Overspark ha bisogno di aiuto per riconquistare Gnomeregan.",h="Alla Cathedral of Light di Roccavento, Fratello Sarno accoglie visitatori e fedeli.",kw={"fratello sarno","cathedral of light","chiesa della sacra luce","roccavento","techbot","tinkmaster overspark"},ang={["class:Priest"]="Come sacerdote, puoi vedere Fratello Sarno accogliere i visitatori a Roccavento. Incarna l'ospitalità e la dolce grazia della Sacra Luce.",["race:Gnome"]="Sebbene Fratello Sarno presti servizio in un luogo di culto umano, indirizza i viaggiatori volenterosi verso Forgiardente per aiutare Gnomeregan a riprendersi."},sec={{t="Una voce accogliente nella Cattedrale",b="Pellegrini e viaggiatori incontrano per primo Fratello Sarno, appena oltre l'ingresso principale della cattedrale. Confratello della Chiesa della Sacra Luce, accoglie chi cerca preghiera, conforto o guida. I suoi modi gentili mettono a proprio agio i visitatori nella vita quotidiana della cattedrale."},{t="Legami con Forgiardente",b="Fratello Sarno aiuta l'Alleanza anche oltre le mura della cattedrale. Quando seppe che Tinkmaster Overspark, a Forgiardente, aveva bisogno di aiuto con la sua invenzione ribelle, Techbot, a Gnomeregan, Sarno indirizzò viaggiatori capaci verso Dun Morogh. Il suo aiuto sostiene gli gnomi sfollati dalla loro patria."}},faq={{q="Dove posso trovare Fratello Sarno?",a="Fratello Sarno si trova appena oltre l'ingresso principale della Cathedral of Light, in Piazza della Cattedrale a Roccavento, a sinistra delle porte.",al={"posizione di sarno","dove si trova fratello sarno","accoglienza cattedrale"}},{q="Cosa fa Fratello Sarno?",a="Fratello Sarno accoglie visitatori e fedeli alla Cathedral of Light. Indirizza anche i viaggiatori da Tinkmaster Overspark a Forgiardente per aiutare a risolvere i problemi di Gnomeregan.",al={"ruolo di fratello sarno","cosa fa sarno"}},{q="Perché un sacerdote di Roccavento invia persone a Gnomeregan?",a="Al clero giunse voce che Tinkmaster Overspark aveva bisogno di aiuto per recuperare tecnologie fuori controllo come Techbot. Fratello Sarno indirizzò campioni capaci verso Forgiardente perché prestassero aiuto.",al={"missione gnomeregan sarno","perché sarno si preoccupa degli gnomi"}},{q="Appartiene a qualche ordine specifico?",a="Fratello Sarno è un membro ordinato della Chiesa della Sacra Luce. Presta servizio agli ordini dei prelati della cattedrale e dell'Arcivescovo Benedictus a Roccavento.",al={"fazione sarno","ordine di fratello sarno"}}},fx={["3cc89cc1"]={q="Che cosa vuole Fratello Sarno?",a="Oltre ad accogliere i fedeli nella Cathedral of Light, Fratello Sarno tiene d'occhio gli avventurieri dell'Alleanza più capaci. Indirizza i viaggiatori volenterosi a Forgiardente, dove possono aiutare Tinkmaster Overspark con una problematica creazione meccanica di nome Techbot, nel cuore della città in rovina di Gnomeregan.",al={"che cosa vuole fratello sarno","obiettivi di fratello sarno","motivazioni di fratello sarno"}},["222a0285"]={q="Perché Fratello Sarno si trova nella Cathedral?",a="Fratello Sarno si trova vicino all'ingresso principale della Cathedral of Light per accogliere fedeli, pellegrini e viaggiatori stanchi in cerca di conforto. Da questo posto, resta anche in ascolto di problemi lontani e mette in contatto gli eroi di passaggio con gli alleati che hanno bisogno di aiuto.",al={"perché fratello sarno è qui","perché sarno si trova nella cattedrale","motivo della posizione di fratello sarno"}},["61335d44"]={q="Chi è Fratello Sarno?",a="Fratello Sarno è un sacerdote umano della Chiesa della Luce Sacra, di stanza nella grandiosa Cathedral of Light di Roccavento. Situato appena oltre l'ingresso principale, sulla sinistra, accoglie cordialmente i visitatori e i pellegrini che entrano nel santuario.",al={"chi è fratello sarno","identità di fratello sarno","chi è sarno"}},["52c947c9"]={q="Da che parte sta Fratello Sarno?",a="Fratello Sarno è un devoto servitore della Chiesa della Luce Sacra e un membro leale della Gran Alleanza. Sostiene i cittadini di Roccavento e mantiene stretti rapporti di collaborazione con gli alleati dell'Alleanza, tra cui gli gnomi e i nani di Khaz Modan.",al={"fazione di fratello sarno","fedeltà di fratello sarno","chi serve fratello sarno"}}},fp="13,200,34.263.0,17.285.0,31.139.0,27.173.0,54.175.0,37.153.0"}
P.entries["npc:brother-wilhelm"] = {n="Fratello Wilhelm",s="Dietro la fucina di Borgodoro, Fratello Wilhelm guida i giovani paladini nella foresta più vasta. Arrivano dall'Abbazia della Contea del Nord per muovere i primi passi a Elwynn.",h="Dietro la fucina di Borgodoro, Fratello Wilhelm guida i giovani paladini nella foresta più vasta.",kw={"fratello wilhelm","brotherhood of northshire","foresta di elwynn","borgodoro","sacra luce","istruttore dei paladini","tome of divinity"},ang={["class:Paladin"]="Come paladino, trovi in Fratello Wilhelm il tuo primo mentore dopo aver lasciato la Valle della Contea del Nord. Guida la tua crescita e ti apre la strada per padroneggiare il Tome of Divinity.",["race:Human"]="Come umano, vedi in Fratello Wilhelm la fede della Church of the Sacra Luce, che difende il cuore di Elwynn."},sec={{t="Una guida a Borgodoro",b="Fratello Wilhelm addestra i nuovi paladini dietro la fucina di Borgodoro. La Valle della Contea del Nord protegge chi inizia il proprio cammino nella Luce, ma molti cercano la sua guida quando si addentrano nella foresta più vasta. Insegna loro i sacri doveri mentre lasciano l'abbazia. Poi assumono il compito di proteggere il regno."},{t="Il cammino del tomo",b="Fratello Wilhelm indirizza gli aspiranti paladini verso il Tome of Divinity. Il suo rito insegna agli iniziati il peso del sacrificio e il potere della redenzione divina. Attraverso le prove, mettono alla prova la propria devozione e imparano a brandire la Luce. Possono resuscitare i compagni caduti e difendere la giustizia in tutto il Regno di Roccavento."}},faq={{q="Dove posso trovare Fratello Wilhelm?",a="Fratello Wilhelm si trova dietro la bottega del fabbro del villaggio a Borgodoro, nella Foresta di Elwynn. Lì addestra e guida gli aspiranti paladini.",al={"posizione di wilhelm","dove si trova fratello wilhelm","trovare fratello wilhelm"}},{q="Quali servizi offre Fratello Wilhelm?",a="Fratello Wilhelm insegna ai giovani paladini nuovi incantesimi, benedizioni marziali e tecniche sacre mentre attraversano la Foresta di Elwynn.",al={"cosa fa wilhelm","istruttore dei paladini borgodoro","fratello wilhelm istruttore"}},{q="Fratello Wilhelm fa parte della Brotherhood of Northshire?",a="Il titolo di Fratello Wilhelm e la vicinanza all'Abbazia della Contea del Nord suggeriscono legami con la Brotherhood of Northshire. Da Borgodoro, serve la Church of the Sacra Luce e il Regno di Roccavento.",al={"wilhelm fa parte della brotherhood of northshire","fazione di wilhelm","chi serve fratello wilhelm"}},{q="Qual è il suo ruolo nella missione del Tome of Divinity?",a="Fratello Wilhelm indirizza i paladini umani cresciuti in potere verso il Tome of Divinity e le sue prove. Queste prove conducono alla sacra benedizione della resurrezione.",al={"tome of divinity wilhelm","missione di resurrezione wilhelm","missione paladino borgodoro"}}},fx={["0af03050"]={q="Chi è Fratello Wilhelm?",a="Fratello Wilhelm è un mentore umano dei paladini di stanza a Borgodoro. Devoto alla Luce Sacra e alla difesa del regno, offre guida e addestramento ai paladini alle prime armi che si avventurano oltre la Valle della Contea del Nord, nelle regioni più ampie della Foresta di Elwynn.",al={"chi è fratello wilhelm","identità di fratello wilhelm","chi è wilhelm"}},cccf7116={q="Da che parte sta Fratello Wilhelm?",a="Fratello Wilhelm è fermamente schierato con l'Alleanza e il Regno di Roccavento. Serve gli ordini sacri della Luce e si dedica a rafforzare i paladini del regno contro i conflitti interni e le minacce regionali.",al={"chi serve fratello wilhelm","fazione di wilhelm","fratello wilhelm e l'alleanza"}},["3fb91c50"]={q="Perché Fratello Wilhelm si trova a Borgodoro?",a="Di stanza dietro la fucina di Borgodoro, Fratello Wilhelm fa da istruttore ai giovani paladini che hanno lasciato da poco l'Abbazia della Contea del Nord. Rimane nella Foresta di Elwynn per seguire la loro costante crescita e la loro preparazione spirituale mentre si preparano a entrare in servizio attivo.",al={"perché fratello wilhelm è qui","fratello wilhelm a borgodoro","perché wilhelm si trova a elwynn"}}},fp="15,156,20.304.0,20.318.0,33.134.0,43.127.0,57.189.0,47.163.0"}
P.entries["npc:bruegal-ironknuckle"] = {n="Bruegal Noccaferro",s="Nelle Segrete di Roccavento, Bruegal Noccaferro si aggira per i corridoi durante una rivolta aperta. Il pericoloso nano è un potente attaccabrighe, e chiunque cerchi di ristabilire l'ordine potrebbe dover affrontare i suoi pugni.",h="Nelle Segrete di Roccavento, Bruegal Noccaferro si aggira per i corridoi durante una rivolta aperta.",kw={"attaccabrighe","bruegal noccaferro","nano","detenuto","noccaferro","prigioniero","raro","segrete di roccavento","roccavento"},ang={["class:Warrior"]="Come guerriero, puoi vedere nella tenacia e nei pugni pesanti di Noccaferro la forza bruta che resta quando disciplina e onore vengono meno.",["faction:Alliance"]="Come campione dell'Alleanza, puoi aiutare la guardia cittadina di Roccavento a reprimere furfanti come Noccaferro. Minacciano di trasformare il cuore della capitale in una fortezza dell'anarchia.",["race:Dwarf"]="Come nano, potresti trovare sconcertante vedere un tuo robusto simile tra i tagliaborse e i furfanti di Roccavento. Persino i figli di Forgiardente possono finire in esilio e vivere da fuorilegge."},sec={{t="Un detenuto pericoloso",b="Bruegal Noccaferro si aggira per le Segrete di Roccavento durante la rivolta aperta al loro interno. Il nano è noto per la sua forza brutale nelle risse. Molti dei tagliagole più instabili della città hanno preso il controllo dei blocchi di celle sotterranei, e Bruegal è tra loro. Lascia la sua cella e vaga per i corridoi, pronto a pestare chiunque cerchi di sedare la rivolta."},{t="Fuorilegge ribelle",b="Bruegal Noccaferro è tra i furfanti e i fuorilegge rinchiusi nelle profondità sotto Roccavento. La Fratellanza dei Defias e i suoi capi dirigono gran parte della rivolta, mentre detenuti come Bruegal mostrano che la prigione ospita criminali provenienti da tutti i regni orientali. Nessun documento qui indica quali crimini lo abbiano condotto lì. La sua tenace resistenza lo rende sfuggente e uno dei detenuti solitari più letali nei corridoi."}},faq={{q="Chi è Bruegal Noccaferro?",a="Bruegal Noccaferro è un potente detenuto nano nelle Segrete di Roccavento. Durante la sommossa in corso, vaga per i corridoi della prigione ed è difficile da trovare.",al={"chi è bruegal","storia di noccaferro","prigioniero nano delle segrete"}},{q="Bruegal Noccaferro fa parte della Fratellanza dei Defias?",a="Bruegal Noccaferro è un prigioniero nano nelle Segrete di Roccavento. La sua precisa affiliazione è sconosciuta.",al={"bruegal fa parte dei defias","nano dei defias segrete"}},{q="Perché è imprigionato nelle Segrete?",a="Nessun mandato pubblico riporta le accuse che hanno condotto Bruegal Noccaferro nelle Segrete di Roccavento. Il suo temperamento violento e la sua fama di attaccabrighe suggeriscono gravi violazioni delle leggi di Roccavento.",al={"perché bruegal è rinchiuso","crimine di bruegal"}},{q="Dove si trova all'interno delle Segrete?",a="Bruegal Noccaferro vaga per i passaggi interni e i crocevia delle Segrete di Roccavento invece di restare in una cella. Potrebbe cogliere di sorpresa chi cerca di eliminare i rivoltosi.",al={"apparizione di bruegal","dove si trova bruegal","mostro raro delle segrete"}},{q="È sempre presente nella prigione?",a="No. Bruegal Noccaferro compare solo sporadicamente durante i disordini. In altri momenti è rinchiuso o lontano dagli sguardi.",al={"bruegal può non apparire","perché non riesco a trovare bruegal"}},{q="Cosa lo rende degno di nota tra i prigionieri?",a="Bruegal Noccaferro è noto per la sua temibile abilità nel combattimento. Si dice anche che nasconda alle guardie preziosa merce di contrabbando ed equipaggiamento, il che lo rende una preda ambita per chi osa affrontarlo.",al={"perché si cerca bruegal","rilevanza di bruegal"}}},fp="19,184,19.330.0,13.394.0,27.153.0,54.94.0,37.181.0,42.152.0,35.119.0,43.186.0"}
P.entries["npc:cain-firesong"] = {n="Cain Cantafuoco",s="Alla Taverna dell'Impiccato di Brill, Cain Cantafuoco guida i maghi Reietti nello studio dell'arcano. Li addestra nelle Radure di Tirisfal, poi invia gli allievi più esperti a Sepulcra per approfondire gli studi.",h="Alla Taverna dell'Impiccato di Brill, Cain Cantafuoco guida i maghi Reietti nello studio dell'arcano.",kw={"anastasia cuorfosco","arcano","brill","cain cantafuoco","taverna dell'impiccato","istruttore dei maghi","radure di tirisfal"},ang={["class:Mage"]="Come mago dei Reietti che muove i primi passi da Albamorta, puoi apprendere l'arcano da Cain Cantafuoco nelle Radure di Tirisfal, poi proseguire gli studi a Sepulcra.",["race:Undead"]="Come Non Morto, puoi usare le tradizioni arcane di coloro che un tempo erano maghi umani come arma al servizio dei Reietti."},sec={{t="Un praticante a Brill",b="Cain Cantafuoco insegna le arti arcane a Brill, dove i maghi Reietti iniziano i loro studi. Molti incantatori Reietti prediligono l'ombra o la negromanzia, ma Cain resta fedele all'arcano. Fa da mentore ai maghi che muovono i primi passi da Albamorta. Le guardie di morte indirizzano i visitatori al pianerottolo del piano superiore della Taverna dell'Impiccato, dove si trova Cain. Scherzano dicendo che è arrivato troppo tardi per trovare una stanza."},{t="Guidare i nuovi talenti",b="Quando gli allievi superano gli studi iniziali nelle Radure di Tirisfal, Cain indirizza i più capaci verso nuovi insegnamenti. Li manda da Anastasia Cuorfosco, una maestra di stregoneria che vive nel Magic Quarter di Sepulcra."}},faq={{q="Chi è Cain Cantafuoco?",a="Cain Cantafuoco addestra i maghi Reietti a Brill, nelle Radure di Tirisfal. Insegna incantesimi arcani e invia gli allievi più esperti a proseguire gli studi a Sepulcra.",al={"chi è cain cantafuoco","storia di cain cantafuoco","cain cantafuoco brill"}},{q="Dove alloggia Cain Cantafuoco a Brill?",a="Cain Cantafuoco si trova sul pianerottolo del piano superiore della Taverna dell'Impiccato di Brill. Le guardie di morte locali scherzano dicendo che è arrivato troppo tardi per trovare una stanza.",al={"dove si trova cain cantafuoco","posizione di cain cantafuoco","stanza taverna cain"}},{q="Dove invia i maghi Cain dopo il loro addestramento iniziale?",a="Cain invia i maghi che progrediscono sotto la sua guida nel Magic Quarter di Sepulcra. Lì, Anastasia Cuorfosco prosegue la loro istruzione.",al={"missione cain cantafuoco","a chi invia i maghi cain","speak with anastasia"}}},fx={["265be98f"]={q="Da che parte sta Cain Cantafuoco?",a="Cain Cantafuoco è fermamente schierato con i Reietti e l'Orda. Di stanza a Brill, serve la Signora Oscura istruendo i non morti appena risorti nelle arti arcane, così che gli incantatori Reietti abbiano la potenza magica necessaria per difendere le Radure di Tirisfal e far prosperare il regno di Sepulcra.",al={"fazione di cain cantafuoco","lealtà di cain cantafuoco","chi serve cain cantafuoco"}},["5ce3d117"]={q="Che cosa vuole Cain Cantafuoco?",a="Cain vuole affinare la disciplina arcana dei maghi Reietti alle prime armi prima di mandarli dai maestri addestratori di Sepulcra.",al={"obiettivo di cain cantafuoco","che cosa fa cain cantafuoco","scopo di cain cantafuoco"}},f96c1f09={q="Perché Cain Cantafuoco si trova qui?",a="Cain è di stanza a Brill per istruire i giovani maghi che emergono da Albamorta. Lo trovi sul pianerottolo al piano superiore della Taverna dell'Impiccato.",al={"perché cain cantafuoco si trova a brill","motivo della posizione di cain cantafuoco","perché cain cantafuoco è qui"}}},fp="13,186,23.375.0,18.199.0,21.162.0,39.154.0,56.141.0"}
P.entries["npc:cairne-bloodhoof"] = {n="Cairne Zoccolo Sanguinario",s="A Picco del Tuono, Cairne Zoccolo Sanguinario guida le tribù tauren unite. L'High Chieftain legò il loro destino all'Orda di Thrall dopo che gli orchi le aiutarono a sfuggire all'estinzione per mano dei centauri.",h="A Picco del Tuono, Cairne Zoccolo Sanguinario guida le tribù tauren unite.",kw={"baine","zoccolo sanguinario","cairne","centauri","gran capo","mulgore","thrall","picco del tuono"},ang={["faction:Horde"]="Come membro dell'Orda, condividi la sua causa con Cairne. È uno dei padri fondatori dell'Orda a Kalimdor e un pilastro di onore, saggezza e potenza militare.",["race:Tauren"]="Come tauren, conosci Cairne come il salvatore del tuo popolo. Unì le tribù disperse, respinse i centauri e guidò la costruzione di Picco del Tuono."},sec={{t="Una nazione a Mulgore",b="Cairne Zoccolo Sanguinario condusse i tauren da una vita di fughe a una dimora a Mulgore. Per generazioni, i predoni centauri diedero la caccia alle tribù nelle Savane, spingendole verso l'estinzione. Quando Thrall e i suoi orchi raggiunsero Kalimdor, Cairne riconobbe in loro una rara nobiltà.\n\nThrall offrì protezione e una scorta alla disperata carovana di Cairne attraverso le pianure. In cambio, Cairne li guidò dall'Oracolo al Picco di Petrartiglio. I tauren si stabilirono sugli imponenti altopiani di Picco del Tuono, dove Cairne unì le tribù e diede loro una dimora permanente."},{t="Giuramento all'Orda",b="Cairne Zoccolo Sanguinario combatté al fianco dell'Orda di Thrall e degli umani di Jaina Marefiero contro la Legione Infuocata durante la Terza Guerra. Riconoscente a Thrall, Cairne aveva seguito gli orchi al Picco di Petrartiglio. Quando l'Ammiraglio Daelin Proudmoore invase Durotar, Cairne riprese le armi al fianco di Rexxar. Suo figlio Baine, che era stato catturato, era stato tratto in salvo. Ora tra gli anziani più rispettati dell'Orda, Cairne rimane il più fidato confidente di Thrall. Offre consigli pacati contro gli sconsiderati incitamenti alla guerra."}},faq={{q="Chi è Cairne Zoccolo Sanguinario?",a="Cairne Zoccolo Sanguinario guida le tribù tauren unite come High Chieftain, capo della tribù Bloodhoof e sovrano di Picco del Tuono. Guerriero antichissimo, condusse i tauren dall'esilio nomade a una patria sicura.",al={"chi è cairne","leader tauren","gran capo"}},{q="Perché i tauren sono alleati degli orchi?",a="Durante la Terza Guerra, le scorrerie delle tribù centaure spinsero i tauren verso l'estinzione. Thrall e i suoi orchi appena arrivati respinsero i predoni e scortarono la grande carovana di Cairne fino a Mulgore. In segno di gratitudine, Cairne giurò la lealtà e la forza del suo popolo all'Orda di Thrall.",al={"perché i tauren si uniscono all'orda","amicizia tra cairne e thrall","alleanza tra tauren e orchi"}},{q="Dove risiede Cairne?",a="Cairne risiede a Picco del Tuono, la città costruita sugli alti altopiani di Mulgore. Governa al fianco dei capi delle tribù tauren riunite.",al={"dove si trova cairne","posizione di cairne","trova cairne zoccolo sanguinario"}},{q="Chi è Baine Zoccolo Sanguinario per Cairne?",a="Baine è l'amato figlio ed erede di Cairne. Quando i predoni centauri rapirono Baine, Cairne cadde in un profondo dolore e rifiutò di combattere finché Rexxar e i suoi compagni non ritrovarono Baine e lo riportarono a casa sano e salvo.",al={"figlio di cairne","baine è figlio di cairne","parentela baine zoccolo sanguinario"}}},fx={d2aba303={q="Che cosa vuole Cairne Zoccolo Sanguinario?",a="Cairne desidera pace e prosperità durature per il suo popolo. Per anni, i tauren nomadi hanno rischiato l'estinzione per mano delle tribù di centauri predoni. Dopo aver unito le tribù sulle alte mesas di Mulgore, ora si dedica a mettere al sicuro la loro patria ancestrale, proteggere le loro pacifiche tradizioni spirituali e restare al fianco dei suoi alleati dell'Orda contro chiunque minacci Kalimdor.",al={"obiettivi di cairne","che cosa vuole cairne","ambizioni di cairne"}},["665f60ad"]={q="Perché Cairne Zoccolo Sanguinario si trova a Picco del Tuono?",a="In qualità di Gran Capo delle tribù tauren unite, Cairne governa il suo popolo dalla capitale, Picco del Tuono. Fondò l'insediamento sulle imponenti mesas di Mulgore per proteggere i tauren dai centauri predoni, e rimane qui per governare le tribù, consigliare gli sciamani e coordinare la difesa insieme ai suoi alleati dell'Orda.",al={"perché cairne si trova a picco del tuono","perché cairne è qui","motivo della posizione di cairne zoccolo sanguinario"}},a87d4b70={q="Perché Cairne Zoccolo Sanguinario è famoso?",a="Cairne è venerato come guerriero senza pari e leader lungimirante che ha unito le tribù tauren disperse. Famoso in tutta Kalimdor per la sua immensa forza e la sua saggezza maturata con l'esperienza, ha avuto un ruolo cruciale nella sconfitta della Legione Infuocata sul Monte Hyjal e nella fondazione dell'Orda moderna insieme a Thrall.",al={"reputazione di cairne zoccolo sanguinario","cairne zoccolo sanguinario è famoso","perché cairne è rispettato"}}},fp="16,186,19.536.0,19.485.0,24.210.0,40.277.0,25.136.0,33.200.0"}
P.entries["npc:calor"] = {n="Calor",s="A Borgoscuro, Calor dirige la lotta contro i worgen che si aggirano per Boscovespro. Sotto la guida di Jonathan Carevin, aiuta la Carevin Family a cacciare le bestie che minacciano le foreste.",h="A Borgoscuro, Calor dirige la lotta contro i worgen che si aggirano per Boscovespro.",kw={"calor","carevin","borgoscuro","boscovespro","jonathan carevin","the night watch","frutteto marcescente","worgen"},ang={["class:Hunter"]="Come cacciatore, puoi collaborare con Calor per rintracciare e abbattere le bestie selvagge che minacciano l'ordine naturale della foresta.",["faction:Alliance"]="Come campione dell'Alleanza, puoi aiutare Calor a difendere gli abitanti isolati di Borgoscuro nei boschi tenebrosi."},sec={{t="Un lealista nell'ombra",b="A Borgoscuro, Calor aiuta la Carevin Family a combattere gli orrori che incombono sulla cittadina. Opera sotto la guida di Jonathan Carevin, uno dei difensori di Borgoscuro. Insieme cercano di annientare le minacce soprannaturali prima che gli abitanti rimasti vengano massacrati."},{t="La minaccia dei worgen",b="Calor invia combattenti contro i worgen che si aggirano per Boscovespro, soprattutto nei pressi del Frutteto Marcescente. Questi uomini lupo sono più pericolosi delle bestie comuni. Massacrano tanto i viaggiatori quanto le pattuglie. Per questo Calor cerca combattenti capaci di sfoltirne i ranghi e indagare sulle loro origini, nella speranza di arginare i loro attacchi."}},faq={{q="Chi è Calor?",a="Calor vive a Borgoscuro e sostiene la Carevin Family. Contribuisce alla difesa della cittadina inviando combattenti contro le gravi minacce che incombono su Boscovespro.",al={"calor borgoscuro","chi è calor","calor boscovespro"}},{q="Dove si può trovare Calor?",a="Calor si trova a Borgoscuro, la cittadina dell'Alleanza nelle foreste di Boscovespro.",al={"dove si trova calor","posizione di calor","coordinate di calor"}},{q="Qual è il rapporto di Calor con Jonathan Carevin?",a="Calor sostiene la Carevin Family e segue le direttive di Jonathan Carevin nella lotta contro i mostri della foresta.",al={"calor e carevin","per chi lavora calor","the carevin family calor"}},{q="Quali nemici ti fa combattere Calor?",a="Calor invia combattenti a caccia di worgen nei boschi, soprattutto nei pressi del Frutteto Marcescente.",al={"missioni di calor","cosa vuole calor","missioni dei worgen calor"}},{q="Perché la minaccia dei worgen è così urgente a Boscovespro?",a="I worgen sono predatori feroci che attaccano a vista qualsiasi cosa. Senza abbattimenti regolari, potrebbero sopraffare le esigue difese di Borgoscuro. Calor coordina gli sforzi al fianco della Night Watch.",al={"perché uccidere i worgen boscovespro","minaccia dei worgen boscovespro"}},{q="Calor è un membro di The Night Watch?",a="No. Calor ha perso fiducia nella Night Watch per quella che considerava una mancanza di vigilanza. Si è unito a Jonathan Carevin e sostiene la lotta della Carevin Family contro i worgen.",al={"calor the night watch","calor fa parte dei the night watch"}}},fx={e997a1f9={q="Che cosa vuole Calor?",a="Calor è determinato a sterminare i worgen che infestano Boscovespro. Agendo direttamente agli ordini di Jonathan Carevin, recluta avventurieri capaci per dare la caccia alle bestie feroci in agguato in luoghi come il Frutteto Marcescente e fermare il diffondersi della loro corruzione oscura prima che travolga Borgoscuro.",al={"obiettivo di calor","che cosa fa calor","che cosa vuole calor"}},f0ff266f={q="Perché Calor si trova a Borgoscuro?",a="Calor è di stanza a Borgoscuro per aiutare la famiglia Carevin nella sua crociata contro le bestie dei boschi. Da questa città assediata coordina le attività di ricognizione e di caccia contro i feroci branchi di worgen che si aggirano nei boschetti e nei frutteti abbandonati circostanti.",al={"perché calor è qui","perché calor si trova a borgoscuro","perché calor si trova a boscovespro"}}},fp="5,164,25.248.0,17.314.0,13.139.0,25.78.0,51.119.0,39.86.0,47.188.0,37.162.0"}
P.entries["npc:calvin-montague"] = {n="Calvin Montague",s="Al cancello di Albamorta, Calvin Montague intercetta i Reietti appena risvegliati in uscita e inganna i passanti per farsi sbrigare delle commissioni.",h="Al cancello di Albamorta, Calvin Montague intercetta i Reietti appena risvegliati in uscita e inganna i...",kw={"a rogue's deal","calvin montague","truffatore","albamorta","ladro dei reietti","montague","radure di tirisfal"},ang={["class:Rogue"]="Come ladro dei Reietti, puoi riconoscere nel tentativo di Calvin Montague di manipolare gli inesperti un raggiro da quattro soldi di un altro tagliaborse.",["race:Undead"]="Come uno dei non morti appena risorti che lasciano Albamorta, potresti imparare presto che non tutti i sudditi di Sylvanas cercano solidarietà."},sec={{t="Un truffatore al cancello",b="Calvin Montague attende oltre i cancelli di Albamorta, dove la strada conduce nelle Radure di Tirisfal. Cerca di convincere gli avventurieri di passaggio a recapitare le sue lettere con false promesse. Non vuole né occuparsi della propria corrispondenza né pagare un equo compenso a un corriere. Altri non morti di spicco di nome Montague gestiscono attività bancarie a Sepulcra. Calvin segue una strada meno rispettabile, affidandosi a piccoli raggiri e inganni."},{t="Il piano di un ladro",b="Calvin Montague offre ai viaggiatori un messaggio sigillato da recapitare per suo conto. Chi ha un ingegno acuto o esperienza nella malavita può intuire l'inganno dietro le sue parole. I non morti appena risorti potrebbero essere ancora in cerca di uno scopo tra le desolate rovine di Tirisfal. L'offerta di Calvin mostra quanto possa essere rara la fiducia al servizio della Dama Oscura."}},faq={{q="Chi è Calvin Montague?",a="Calvin Montague è un ladro dei Reietti che attende vicino al cancello d'uscita di Albamorta, nelle Radure di Tirisfal. Cerca di ingannare i non morti appena risorti per farsi sbrigare una commissione senza pagarli.",al={"calvin montague","chi è calvin montague","calvin albamorta"}},{q="Cosa vuole Calvin dagli avventurieri?",a="Calvin Montague cerca di convincere i viaggiatori di passaggio a recapitare una lettera con falsi pretesti. Spera che le sue belle parole gli procurino un servizio di consegna gratuito.",al={"missione calvin montague","lettera calvin","cosa vuole calvin"}},{q="Calvin Montague è imparentato con i banchieri di Sepulcra?",a="Calvin condivide il cognome con Ophelia, Mortimer, William e Randolph Montague, illustri banchieri di Sepulcra. Non è stato confermato alcun legame di parentela.",al={"famiglia montague","banchieri montague sepulcra","calvin imparentato con i banchieri"}},{q="Dove si trova Calvin Montague?",a="Calvin Montague attende lungo la strada appena fuori dal cancello settentrionale in legno di Albamorta, dove può intercettare gli avventurieri diretti nelle Radure di Tirisfal.",al={"posizione calvin","dove si trova calvin montague","trova calvin montague"}}},fx={["9e392640"]={q="Da che parte sta Calvin Montague?",a="Calvin è un furfante Reietto indipendente, che pensa soprattutto a se stesso. Anche se vive nelle terre dei Reietti e ha a che fare con i loro viaggiatori, i suoi intrighi e loschi affari dimostrano che serve il proprio tornaconto, non una causa nobile o gli interessi dello Stato.",al={"fazione di calvin montague","chi serve calvin montague","calvin montague è un reietto"}},["0598d792"]={q="Perché Calvin Montague è di stanza fuori da Albamorta?",a="Calvin si apposta proprio lungo la strada che esce da Albamorta per approfittarsi dei non morti appena risvegliati. I Reietti appena risorti che si avventurano nelle più vaste Radure di Tirisfal sono facili prede per un furfante opportunista che vuole convincere qualcuno a fare il suo lavoro di corriere gratis.",al={"perché calvin montague è qui","posizione di calvin montague ad albamorta","perché calvin si trova all'uscita di albamorta"}}},fp="15,137,21.411.0,16.292.1,23.167.0,40.149.0,52.152.0,35.149.0"}
P.entries["npc:canaga-earthcaller"] = {n="Invocatore della Terra Canaga",s="Nella Valle delle Sfide, l'Invocatore della Terra Canaga guida i nuovi sciamani dell'Orda verso gli spiriti della terra e i loro primi totem.",h="Nella Valle delle Sfide, l'Invocatore della Terra Canaga guida i nuovi sciamani dell'Orda verso gli spiriti...",kw={"call of earth","canaga","puntascura","durotar","earth sapta","invocatore della terra","sciamano","valle delle sfide"},ang={["class:Shaman"]="Come sciamano, incontri Canaga come tua prima guida spirituale a Durotar. Prepara l'Earth Sapta affinché tu possa comunicare con gli elementi e ottenere il tuo Earth Totem.",["race:Orc"]="Come orco, trovi Canaga al lavoro al fianco degli istruttori orcheschi nella valle. Aiuta i giovani orchi a legare i loro spiriti all'aspra terra della loro nuova patria.",["race:Troll"]="Come troll, trovi Canaga tra le figure di spicco dei Puntascura nella Valle delle Sfide. Guida i giovani sciamani troll mentre iniziano il loro cammino con gli spiriti."},sec={{t="Voce della Terra",b="Dalle alture rosse della Valle delle Sfide, l'Invocatore della Terra Canaga guida i troll Puntascura e gli orchi che intraprendono il cammino sciamanico. Insegna loro a placare la mente e ad ascoltare i brontolii di Kalimdor. Poi preparano l'Earth Sapta per comunicare con gli spiriti."},{t="Il Primo Totem",b="Canaga manda ogni novizio a raccogliere reagenti sacri e a raggiungere la locale Roccia dello Spirito a Durotar. Lì bevono l'Earth Sapta e vedono con i propri occhi gli spiriti elementali. Sotto la sua guida, ottengono il loro Earth Totem."}},faq={{q="Chi è l'Invocatore della Terra Canaga?",a="L'Invocatore della Terra Canaga è uno sciamano troll Puntascura che guida i giovani sciamani nella Valle delle Sfide mentre muovono i primi passi nell'Orda.",al={"lore di canaga","chi è canaga","png invocatore della terra canaga"}},{q="Cosa insegna Canaga ai giovani sciamani?",a="Canaga guida gli sciamani dell'Orda attraverso la serie di rituali di Call of Earth a Durotar. Prepara l'Earth Sapta affinché gli iniziati possano percepire lo spirito elementale della terra locale e parlargli mentre cercano il loro primo totem.",al={"missione sciamano durotar","call of earth durotar","missioni di canaga"}},{q="Che cos'è l'Earth Sapta che Canaga prepara?",a="L'Earth Sapta è una bevanda spirituale che Canaga prepara con reagenti della regione. Gli sciamani la bevono per aprire i sensi agli spiriti nascosti della terra e parlare con le manifestazioni elementali.",al={"che cos'è l'earth sapta","lore sapta"}},{q="Perché un troll addestra sciamani in un banco di prova orchesco?",a="Dopo la Third War, la tribù Puntascura strinse un forte legame con l'Orda di Thrall e si stabilì accanto agli orchi a Durotar. Ora gli sciamani e i guerrieri troll si addestrano al fianco dei giovani orchi nella Valle delle Sfide.",al={"perché un troll nella valle delle sfide","puntascura nella valle delle sfide"}},{q="Dove si trova l'Invocatore della Terra Canaga?",a="Canaga siede su altopiani rocciosi che dominano i sentieri orientali della Valle delle Sfide, appena a sud del principale centro di addestramento.",al={"posizione di canaga","dove si trova canaga"}}},fx={["9fbe2a10"]={q="Da che parte sta Invocatore della Terra Canaga?",a="Canaga serve l'Orda e guida i giovani sciamani sia dei troll Lanciascura sia degli orchi. Di stanza nella Valle delle Sfide, aiuta i giovani iniziati a stabilire il loro primo legame con gli spiriti elementali di Durotar, per conto del regno appena fondato dal Capoguerra Thrall.",al={"fazione di invocatore della terra canaga","canaga appartiene all'orda","chi serve canaga"}},["911868d9"]={q="Che cosa vuole Invocatore della Terra Canaga?",a="Canaga vuole assicurarsi che gli sciamani alle prime armi entrino in sintonia con gli spiriti della terra. Mette alla prova gli iniziati speranzosi chiedendo loro di raccogliere reagenti sacri, bere l'Earth Sapta e comunicare direttamente con le manifestazioni elementali locali.",al={"che cosa vuole canaga","obiettivo di invocatore della terra canaga","scopo di canaga"}},f7883336={q="A chi è legato Invocatore della Terra Canaga?",a="Canaga appartiene alla tribù Lanciascura e collabora direttamente con gli insegnanti sciamani degli orchi nella Valle delle Sfide, guidando giovani troll e orchi nel Call of Earth.",al={"legami di invocatore della terra canaga","con chi lavora canaga","alleati di canaga"}}},fp="18,118,17.265.0,15.217.0,26.141.0,37.205.0,40.181.0,60.200.0,38.116.0"}
P.entries["npc:captain-danuvin"] = {n="Capitano Danuvin",s="A Guardiacolle, il Capitano Danuvin raduna i difensori delle Marche Occidentali. Dirige volontari e reclute della People's Militia perché pattuglino le strade e respingano Gnoll e fuorilegge. I suoi ordini proteggono le linee di rifornimento e i terreni agricoli dalle mani nemiche.",h="A Guardiacolle, il Capitano Danuvin raduna i difensori delle Marche Occidentali.",kw={"capitano danuvin","danuvin","gryan stoutmantle","patrolling westfall","peoples militia","fiumezampa","guardiacolle","marche occidentali"},ang={["class:Warrior"]="Come guerriero, puoi mettere la tua disciplina e la tua forza al servizio della lotta contro i branchi di Gnoll e contribuire a sgomberare la strada principale.",["faction:Alliance"]="Il Capitano Danuvin è una delle poche figure militari che mantengono l'ordine nelle Marche Occidentali nonostante l'incuria della corona. Come recluta dell'Alleanza, puoi contribuire a difendere il regno.",["race:Human"]="Come umano, puoi aiutare il Capitano Danuvin a difendere la tua terra natale e a proteggere il granaio di Roccavento da predoni e bestie."},sec={{t="Difendere il Colle",b="Il Capitano Danuvin dirige le pattuglie dalla torre fortificata di Guardiacolle. La guarnigione regolare di Roccavento si è ritirata, lasciando deboli le difese delle Marche Occidentali. Per questo si affida a viaggiatori, braccianti e combattenti volontari per mantenere un po' d'ordine nelle pianure."},{t="Pattugliare la Frontiera",b="Il Capitano Danuvin sorveglia le strade e le terre aperte attorno a Guardiacolle. Gli Gnoll Riverpaw compiono incursioni vicino agli avamposti centrali, così invia pattuglie per sfoltire i loro branchi e mettere in sicurezza il perimetro. I suoi ordini impediscono a predoni e opportunisti di circondare l'accampamento."}},faq={{q="Dove posso trovare il Capitano Danuvin?",a="Puoi trovare il Capitano Danuvin a Guardiacolle, l'avamposto dell'Alleanza nel cuore delle Marche Occidentali. Di solito si trova vicino alla torre fortificata che domina la strada.",al={"posizione di danuvin","dove si trova il capitano danuvin","danuvin marche occidentali"}},{q="Quale fazione rappresenta il Capitano Danuvin?",a="Il Capitano Danuvin serve l'Alleanza e sostiene i difensori locali delle Marche Occidentali. Collabora strettamente con Gryan Stoutmantle e la People's Militia.",al={"fazione di danuvin","chi serve danuvin"}},{q="Quali compiti assegna agli avventurieri?",a="Il Capitano Danuvin incarica le reclute di pattugliare le pianure e respingere gli Gnoll Riverpaw che avanzano verso Guardiacolle.",al={"missioni di danuvin","cosa vuole il capitano danuvin","missione patrolling westfall"}},{q="Perché Danuvin si affida a volontari invece che all'esercito di Roccavento?",a="Roccavento ha lasciato le Marche Occidentali senza truppe di guarnigione. Il Capitano Danuvin e i capi di Guardiacolle si affidano a mercenari e reclute della milizia.",al={"perché niente esercito di roccavento","perché la milizia","guarnigione di roccavento marche occidentali"}},{q="Danuvin ha legami al di fuori delle Marche Occidentali?",a="Il Capitano Danuvin è legato alle Marche Occidentali, la sua terra natale. Ha giurato di restare al fianco dei cittadini rimasti, perciò concentra i suoi sforzi sulle pianure e sulle strade attorno a Guardiacolle.",al={"danuvin crestarossa","legami di danuvin"}},{q="Qual è il suo ruolo rispetto a Gryan Stoutmantle?",a="Gryan Stoutmantle guida la People's Militia e coordina la difesa complessiva delle Marche Occidentali. Il Capitano Danuvin si occupa delle tattiche sul campo, delle pattuglie stradali e della minaccia degli Gnoll vicino alla base.",al={"stoutmantle vs danuvin","danuvin è al comando"}}},fp="15,238,16.246.0,23.254.0,33.149.0,44.142.0,42.112.0,67.143.0,50.163.0,47.171.0"}
P.entries["npc:captain-grayson"] = {n="Capitano Grayson",s="Al Faro delle Marche Occidentali, il Capitano Grayson veglia sulla luce che gli venne meno. La sua nave si schiantò contro la costa buia, e ora tiene accesa la fiamma perché altri marinai non subiscano la sua stessa sorte.",h="Al Faro delle Marche Occidentali, il Capitano Grayson veglia sulla luce che gli venne meno.",kw={"capitano grayson","pirata fantasma","grayson","faro","vecchio occhiobuio","marche occidentali","faro delle marche occidentali"},ang={["class:Paladin"]="Come paladino, puoi onorare il tuo sacro dovere di difendere gli indifesi e respingere i sanguinari murloc aiutando Grayson, sebbene sia uno spirito non morto.",["class:Priest"]="Come sacerdote, puoi offrire conforto all'anima inquieta di Grayson. Il senso di colpa e il dolore tengono il suo spirito ancorato al mondo dopo aver visto morire una famiglia innocente.",["faction:Alliance"]="Con la Fratellanza dei Defias che soffoca le Marche Occidentali e Roccavento che trascura i propri confini, i viaggiatori dell'Alleanza devono rispondere all'appello di Grayson e mantenere accesa la fiamma del faro."},sec={{t="Una vita spezzata dagli scogli",b="Un tempo il Capitano Grayson solcava i mari meridionali dei Regni Orientali al comando di una nave. Una notte, il fuoco del faro si spense mentre il suo vascello si avvicinava alle secche frastagliate delle Marche Occidentali. La nave si schiantò contro gli scogli e Grayson morì con essa. Si risvegliò come un fantasma legato al mondo terreno, vincolato alla costa."},{t="Tragedia al faro",b="Dopo la morte, il Capitano Grayson si recò al Faro delle Marche Occidentali, sperando di scoprire cosa lo attendesse oltre la vita. Lì vide il Vecchio Occhiobuio, un famigerato murloc, scacciare il guardiano e la sua famiglia. I coraggiosi guardiani tornarono per riaccendere la fiamma. Ma il Vecchio Occhiobuio radunò i murloc dei dintorni e guidò un secondo, brutale massacro. Grayson poté solo guardare mentre la famiglia veniva trucidata."},{t="Una veglia spettrale",b="Con i guardiani morti e le Marche Occidentali in rovina per l'incuria, il Capitano Grayson porta sulle spalle spettrali il solenne fardello del faro. Chiede ai viaggiatori di passaggio di raccogliere combustibile per la grande fiamma. Cerca anche vendetta per la famiglia trucidata: dare la caccia al Vecchio Occhiobuio e respingere i murloc della costa."}},faq={{q="Chi è il Capitano Grayson?",a="Il Capitano Grayson è il fantasma di un pirata umano al Faro delle Marche Occidentali. La sua nave si schiantò contro la costa quando la luce del faro si spense, e ora tiene accesa la fiamma per proteggere i marinai di passaggio.",al={"identità di grayson","chi è il pirata fantasma","fantasma del faro"}},{q="Come è morto il Capitano Grayson?",a="Il Capitano Grayson morì quando il suo vascello pirata si schiantò contro gli insidiosi scogli lungo la costa delle Marche Occidentali. Quella notte il faro era spento, lasciando lui e il suo equipaggio senza alcun preavviso mentre la nave andava in pezzi.",al={"morte di grayson","come è diventato un fantasma grayson","cosa ha ucciso il capitano grayson"}},{q="Cosa è successo al vero guardiano del faro?",a="I murloc della costa attaccarono il guardiano e la sua famiglia. La coraggiosa famiglia sfuggì al primo assalto e tornò per riaccendere il faro, ma il Vecchio Occhiobuio organizzò un secondo attacco e li massacrò sotto gli occhi di Grayson.",al={"dov'è il guardiano del faro","cosa è successo ai guardiani","famiglia del faro"}},{q="Chi è il Vecchio Occhiobuio?",a="Il Vecchio Occhiobuio è un capotribù murloc astuto e feroce sulla costa delle Marche Occidentali. Guidò l'attacco che uccise la famiglia del guardiano del faro e minaccia chiunque cerchi di mantenerne accesa la fiamma.",al={"storia di occhiobuio","vecchio occhiobuio","capo dei murloc marche occidentali"}},{q="Perché Grayson vuole che il faro resti acceso?",a="Grayson annegò quando la costa era immersa nel buio più totale e considera mantenere acceso il faro il suo solenne dovere dopo la morte. Vuole risparmiare agli altri marinai la stessa sorte sulle secche.",al={"motivazione di grayson","perché accendere il faro"}},{q="Il Capitano Grayson è ostile verso gli avventurieri?",a="No. Sebbene in vita fosse un pirata, Grayson non nutre rancore verso i vivi. Ha assistito a troppi massacri e cerca pace e aiuto per tenere accesa la fiamma.",al={"grayson è amichevole","grayson ostile"}}},fx={["8f770f95"]={q="Da che parte sta il Capitano Grayson?",a="Il Capitano Grayson non serve alcun regno mortale. Un tempo era un capitano pirata in vita e resta neutrale nei confronti dei viaggiatori vivi; tuttavia, chiede aiuto ai viaggiatori disposti a mettere in sicurezza la costa. Da morto, la sua vera lealtà non va a Roccavento né a una marina, ma al Faro delle Marche Occidentali e al passaggio sicuro dei marinai.",al={"fazione del capitano grayson","grayson è dell'alleanza o dell'orda","chi serve grayson"}},["2ee261a8"]={q="Perché il Capitano Grayson si trova al faro?",a="Grayson fu attirato al faro dopo che la sua nave si schiantò contro la costa delle Marche Occidentali, perché il suo lume era spento. Vincolato al mondo dei mortali come spirito, si recò qui e assistette impotente al massacro della famiglia del guardiano del faro per mano del Vecchio Occhiobuio e dei suoi murloc. Con i guardiani morti, Grayson decise di restare e proteggere lui stesso il faro.",al={"perché il capitano grayson è qui","perché grayson è arrivato al faro delle marche occidentali","che cosa ha portato grayson al faro"}}},fp="15,183,29.290.0,21.372.0,15.310.0,23.171.0,28.203.0,44.217.0,20.193.0,46.176.0,42.160.0"}
P.entries["npc:captain-greenskin"] = {n="Capitano Pelleverde",s="Nell'insenatura delle Miniere della Morte, il Capitano Pelleverde prepara una nave da guerra per Edwin VanCleef. Il pirata goblin ne dirige la ciurma e la costruzione per la Fratellanza dei Defias, preparando il juggernaut corazzato a salpare contro Roccavento.",h="Nell'insenatura delle Miniere della Morte, il Capitano Pelleverde prepara una nave da guerra per Edwin...",kw={"capitano pelleverde","miniere della morte","pirata goblin","pelleverde","juggernaut","ser torello","vancleef"},ang={["class:Rogue"]="Come ladro, trovi Pelleverde a capo della pirateria dei Defias, ben protetto da corsari e bruti sul ponte della nave da guerra.",["faction:Alliance"]="Per l'Alleanza, il Capitano Pelleverde è al comando della minaccia navale della ribellione dei Defias. Se il suo juggernaut raggiunge la costa, le coste indifese delle Marche Occidentali e di Roccavento sono in pericolo diretto."},sec={{t="Il signore del Juggernaut",b="Il Capitano Pelleverde percorre il ponte principale del juggernaut in costruzione nell'insenatura delle Miniere della Morte. Marinaio goblin di grande esperienza, si è unito alla cerchia ristretta di Edwin VanCleef per trasformare una caverna sotterranea in un bacino di carenaggio per una nave da guerra."},{t="La ciurma di un pirata",b="Il Capitano Pelleverde comanda tagliagole, non scalpellini o banditi. La sua ciurma comprende Ser Torello, il suo temibile primo ufficiale tauren, e Capitan Dolcetto, il murloc cuoco di bordo. Insieme, presidiano le passerelle e il ponte superiore, sorvegliando l'accesso alla cabina privata di VanCleef in cima al ponte di comando."}},faq={{q="Chi è il Capitano Pelleverde?",a="Il Capitano Pelleverde è un capitano pirata goblin assoldato da Edwin VanCleef per sovrintendere alla nave da guerra segreta della Fratellanza dei Defias nelle Miniere della Morte, dal completamento al suo impiego.",al={"storia di pelleverde","chi è pelleverde","capitano pelleverde"}},{q="Da dove veniva Pelleverde prima di unirsi ai Defias?",a="Nessun documento racconta dove navigasse Pelleverde prima di entrare al soldo di VanCleef. Comanda il juggernaut dei Defias e la sua ciurma nelle Miniere della Morte.",al={"origine di pelleverde","da dove viene pelleverde","pelleverde baia del bottino"}},{q="Chi serve sotto il Capitano Pelleverde?",a="Pelleverde comanda Ser Torello, il suo primo ufficiale tauren, Capitan Dolcetto, il cuoco murloc, e i pirati Defias che pattugliano il ponte della nave corazzata.",al={"ciurma di pelleverde","primo ufficiale","scagnozzi di pelleverde"}},{q="Qual è lo scopo di Pelleverde nelle Miniere della Morte?",a="Pelleverde deve rendere l'imponente nave da guerra corazzata idonea alla navigazione e pronta a salpare dall'insenatura sotterranea verso il Great Sea, contro Roccavento.",al={"cosa fa pelleverde","perché pelleverde si trova qui"}},{q="Dove si trova il Capitano Pelleverde?",a="Il Capitano Pelleverde percorre il ponte principale del grande juggernaut ancorato nell'ultima caverna delle Miniere della Morte. Sorveglia l'accesso a Edwin VanCleef.",al={"posizione di pelleverde","dove si trova il capitano pelleverde"}},{q="Il Capitano Pelleverde fa parte della Fratellanza dei Defias o è un mercenario?",a="Il Capitano Pelleverde è un capitano pirata mercenario al servizio diretto di Edwin VanCleef. Comanda le forze navali che sostengono il complotto della Fratellanza dei Defias.",al={"pelleverde fa parte dei defias","fazione di pelleverde"}}},fx={["9c1c4117"]={q="Perché il Capitano Pelleverde si trova qui?",a="Il Capitano Pelleverde fu assoldato da Edwin VanCleef per supervisionare la costruzione e comandare l'enorme colosso della Fratellanza dei Defias. Si trova ancora a bordo della nave, nel cuore della baia delle Miniere della Morte, dove dirige il suo equipaggio di pirati e si assicura che la nave da guerra venga completata e armata.",al={"perché pelleverde è nelle miniere della morte","capitano pelleverde perché è qui","scopo di pelleverde nelle miniere della morte"}},["6bcae29e"]={q="Che cosa vuole il Capitano Pelleverde?",a="Come capitano goblin mercenario, Pelleverde è in cerca di profitto e del brivido del comando navale. Intende completare la costruzione della colossale nave corazzata nella baia delle Miniere della Morte e salpare con essa nel Grande Mare, al servizio dei piani di Edwin VanCleef contro Roccavento.",al={"obiettivo di pelleverde","che cosa vuole il capitano pelleverde","motivazioni di pelleverde"}},["433e5911"]={q="Perché il Capitano Pelleverde è temuto?",a="Il Capitano Pelleverde comanda l'equipaggio di pirati del colosso di Edwin VanCleef, affiancato da razziatori brutali come il suo primo ufficiale tauren, Ser Torello. Si aggira sul ponte con una lama possente e arpioni avvelenati, frapponendosi tra gli intrusi e VanCleef in persona.",al={"perché pelleverde è temuto","reputazione del capitano pelleverde","pelleverde è famoso"}}},fp="17,219,24.224.0,15.276.0,25.175.0,56.135.0,35.128.0,45.140.0,37.144.0,67.155.0"}
P.entries["npc:captain-rugelfuss"] = {n="Capitano Granchiasso",s="Al cancello meridionale di Loch Modan, il Capitano Granchiasso affronta un'improvvisa rivolta dei trogg. Il severo nano organizza la difesa del confine.",h="Al cancello meridionale di Loch Modan, il Capitano Granchiasso affronta un'improvvisa rivolta dei trogg.",kw={"capitano granchiasso","guardia di forgiardente","loch modan","fuciliere di montagna","granchiasso","minaccia trogg","valle dei re"},ang={["class:Warrior"]="Come guerriero, puoi riconoscere l'approccio diretto di Granchiasso: sgomberare la prima linea con lama e scudo.",["faction:Alliance"]="Come viaggiatore dell'Alleanza, sai quanto conta proteggere le terre patrie dalle incursioni selvagge mentre gli eserciti combattono altrove.",["race:Dwarf"]="Come nano, puoi vedere la determinazione di Forgiardente nella difesa dei valichi montani ancestrali che il Capitano Granchiasso conduce contro i nemici del sottosuolo."},sec={{t="Difesa del Cancello Meridionale",b="Dalla Valle dei Re, il Capitano Granchiasso sorveglia l'accesso meridionale a Loch Modan. Le forze di Forgiardente sono disperse in tutto il mondo, quindi ufficiali veterani come lui ne difendono i territori patrii. Mette da parte il cerimoniale militare e si concentra sul pericolo al confine."},{t="L'incursione dei trogg",b="I trogg si riversano negli altopiani da antiche caverne. Hanno sopraffatto le pattuglie naniche più isolate e stabilito avamposti fortificati nelle vicinanze. Granchiasso chiede a viaggiatori capaci di sfoltire i loro ranghi e respingerli lontano dalla strada, difendendo le terre del Re."},{t="Ricognizione in prima linea",b="I fucilieri di montagna di Granchiasso vigilano oltre il cancello. Esplorano continuamente gli accampamenti dei trogg."}},faq={{q="Chi è il Capitano Granchiasso?",a="All'accesso meridionale di Loch Modan, nella Valle dei Re, il Capitano Granchiasso comanda le difese di Forgiardente. Protegge la frontiera dalla rivolta dei trogg.",al={"storia capitano granchiasso","chi è granchiasso","granchiasso loch modan"}},{q="Dove si trova il Capitano Granchiasso?",a="Puoi trovare il Capitano Granchiasso vicino al cancello meridionale nella Valle dei Re. Sorveglia il valico meridionale che da Loch Modan conduce a Dun Morogh.",al={"dove si trova granchiasso","posizione capitano granchiasso"}},{q="Perché il Capitano Granchiasso è preoccupato per i trogg?",a="Una recente rivolta dei trogg minaccia gli insediamenti nanici e le linee di rifornimento. I trogg hanno raggiunto l'accesso meridionale e attaccato le pattuglie di Forgiardente, mettendo a rischio il territorio del Re.",al={"perché combattere i trogg","minaccia trogg loch modan"}},{q="Perché Granchiasso respinge le formalità militari?",a="Granchiasso mette da parte il cerimoniale perché lo considera una distrazione mentre le terre del Re sono sotto attacco. Vuole azioni concrete al confine.",al={"personalità di granchiasso","razza at ease"}}},fx={["506fbcb9"]={q="Da che parte sta il Capitano Granchiasso?",a="Il Capitano Granchiasso è fermamente al fianco di Forgiardente e della Grande Alleanza. Ufficiale incaricato di difendere gli accessi meridionali di Loch Modan, ha giurato di proteggere le terre dei nani e sostenere l'autorità di Re Magni Barbabronzea contro le minacce esterne.",al={"fazione del capitano granchiasso","chi serve granchiasso","granchiasso è dell'alleanza"}},["8c27dafb"]={q="Che cosa vuole il Capitano Granchiasso?",a="Granchiasso vuole reprimere la rivolta dei trogg che minaccia la Valle dei Re e le terre del Re. Si affida ai viaggiatori di passaggio perché decimino le schiere di trogg invasori e respingano le creature lontano dalle strade di Loch Modan.",al={"di cosa ha bisogno granchiasso","obiettivo di granchiasso","che cosa cerca di fare granchiasso"}},["0fa68497"]={q="Perché il Capitano Granchiasso è di stanza nella Valle dei Re?",a="Granchiasso è assegnato alla frontiera meridionale di Loch Modan per sorvegliare il passo che conduce a Dun Morogh. Con i trogg che infestano le valli circostanti, è essenziale mantenere una presenza militare nanica organizzata per presidiare la strada e coordinare la difesa delle terre del Re.",al={"perché il capitano granchiasso è qui","perché granchiasso è al cancello meridionale","incarico di granchiasso"}}},fp="17,134,25.270.0,19.263.0,24.96.1,25.159.0,37.137.0,48.184.0,50.144.0"}
P.entries["npc:captain-shatterskull"] = {n="Capitano Spaccateschi",s="All'Accampamento Mor'shan, il Capitano Spaccateschi dirige la difesa del confine settentrionale dell'Orda. Esperto comandante orco, organizza la lotta contro le forze degli Elfi della Notte nei pressi della Forra dei Cantaguerra.",h="All'Accampamento Mor'shan, il Capitano Spaccateschi dirige la difesa del confine settentrionale dell'Orda.",kw={"savane","capitano spaccateschi","kadrak","accampamento mor'shan","capitano orco","spaccateschi","alargentea","cantaguerra"},ang={["faction:Horde"]="Per i guerrieri dell'Orda provenienti dalle Savane Meridionali, il Capitano Spaccateschi presidia la frontiera settentrionale contro le incursioni degli Elfi della Notte da Valtetra.",["race:Orc"]="Come orco, puoi vedere nella difesa delle terre duramente conquistate dall'Orda, guidata dal Capitano Spaccateschi, un riflesso dello spirito guerriero del tuo popolo. Altri considerano gli orchi degli invasori."},sec={{t="Guardiano del Confine Settentrionale",b="All'Accampamento Mor'shan, il Capitano Spaccateschi protegge l'avamposto dell'Orda ai margini di Valtetra. Collabora con altri ufficiali come Kadrak contro le sentinelle degli Elfi della Notte e le forze Alargentea che cercano di riconquistare le terre di confine. La lotta per il legname e le antiche terre di Valtetra tiene la frontiera delle Savane sotto costante minaccia."}},faq={{q="Chi è il Capitano Spaccateschi?",a="All'Accampamento Mor'shan, il Capitano Spaccateschi comanda la difesa dell'Orda contro le forze degli Elfi della Notte. È un esperto comandante orco.",al={"identità di spaccateschi","chi è il capitano spaccateschi","png spaccateschi"}},{q="Dove si trova il Capitano Spaccateschi?",a="Puoi trovare il Capitano Spaccateschi all'Accampamento Mor'shan, al margine settentrionale delle Savane, prima di Valtetra.",al={"posizione di spaccateschi","dove si trova il capitano spaccateschi","accampamento mor'shan spaccateschi"}},{q="Qual è il suo ruolo all'Accampamento Mor'shan?",a="All'Accampamento Mor'shan, il Capitano Spaccateschi comanda la difesa della frontiera settentrionale dell'Orda. Raduna i guerrieri contro le Sentinelle Alargentea dell'Alleanza.",al={"cosa fa spaccateschi","ruolo di spaccateschi","comandante di mor'shan"}},{q="Con chi collabora il Capitano Spaccateschi?",a="Il Capitano Spaccateschi collabora con ufficiali in prima linea come Kadrak. Insieme, coordinano la difesa e il reclutamento per le schermaglie di confine.",al={"alleati di spaccateschi","kadrak e spaccateschi"}}},fx={["4e979652"]={q="Da che parte sta il Capitano Spaccateschi?",a="Il Capitano Spaccateschi serve l'Orda con feroce lealtà. Di stanza all'Accampamento Mor'shan, sulla tesa frontiera tra The Barrens e Valtetra, è un baluardo contro gli Elfi della Notte e l'Alleanza, e organizza le forze per difendere gli interessi dell'Orda nella regione.",al={"fazione del capitano spaccateschi","chi serve spaccateschi","spaccateschi è dell'orda o dell'alleanza"}},["3a9b17d5"]={q="Che cosa vuole il Capitano Spaccateschi?",a="Spaccateschi punta ad assumere il pieno controllo del conteso confine settentrionale. Ordina ai campioni dell'Orda di fermare l'avanzata delle Sentinelle Alargentea da Valtetra, esigendo sacrifici militari e onori di guerra per assicurarsi che i bastioni di Mor'shan restino impenetrabili ai nemici.",al={"obiettivi del capitano spaccateschi","di cosa ha bisogno spaccateschi","perché spaccateschi vuole uccidere le sentinelle alargentea"}},["0393c0a4"]={q="Perché il Capitano Spaccateschi si trova qui?",a="È di stanza all'Accampamento Mor'shan per supervisionare le difese dell'Orda in prima linea contro gli Elfi della Notte. Poiché il confine con Valtetra è un focolaio di scontri territoriali, Spaccateschi è stato assegnato qui per coordinare i rinforzi e respingere le incursioni dell'Alleanza.",al={"perché spaccateschi è a mor'shan","incarico del capitano spaccateschi","perché il capitano spaccateschi è a the barrens"}}},fp="20,189,31.333.0,28.130.0,40.110.0,39.163.0,40.144.0"}
P.entries["npc:captain-stoutfist"] = {n="Capitano Pugnoforte",s="A Porto di Menethil, il Capitano Pugnoforte guida la difesa contro gli attacchi dei Fauce del Drago. L'ufficiale nano coordina la guarnigione e i suoi contrattacchi per impedire che il porto dell'Alleanza cada.",h="A Porto di Menethil, il Capitano Pugnoforte guida la difesa contro gli attacchi dei Fauce del Drago.",kw={"capitano pugnoforte","fauce del drago","dun algaz","nano","forgiardente","porto di menethil","nek'rosh","paludi grigie"},ang={["class:Warrior"]="Come guerriero, troverai in Pugnoforte uno stratega schietto che predilige gli attacchi audaci alle caute opere di fortificazione. Invia i guerrieri a distruggere l'artiglieria nemica ed eliminarne i comandanti.",["faction:Alliance"]="Il Capitano Pugnoforte difende uno dei più importanti centri marittimi dell'Alleanza e mantiene aperte le rotte navali tra Khaz Modan, Roccavento e gli avamposti lontani.",["race:Dwarf"]="Come nano, puoi riconoscere la determinazione militare di Forgiardente in Pugnoforte, incaricato di proteggere infrastrutture vitali nelle terre basse, molto al di sotto delle vette montane."},sec={{t="Difensore di Menethil",b="Porto di Menethil è il principale porto in acque profonde che collega Forgiardente e Roccavento alle Paludi Grigie e al mare aperto. Il Capitano Pugnoforte comanda la difesa della cittadina e protegge i moli, gli abitanti e la guarnigione dai pericoli circostanti. Gli Acquitrini Selvaggi sono pericolosi, ma la minaccia maggiore è un'avanzata organizzata di orchi rinnegati."},{t="La minaccia dei Fauce del Drago",b="Il clan Fauce del Drago occupa roccaforti nelle Paludi Grigie sin dalla Seconda Guerra e ora avanza verso le strade e i passi montani della regione. Gli orchi si infiltrano a Dun Algaz, minacciando la via terrestre che collega Loch Modan, Forgiardente e Porto di Menethil. Pugnoforte ha troppo poche truppe, quindi si affida ai volontari dell'Alleanza inviati dal Fuciliere Valstag Boccaferro per respingerli."},{t="Colpire Nek'rosh",b="Il Capitano Pugnoforte guida una campagna contro gli accampamenti degli orchi invece di attendere un assedio. Ordina alle forze alleate di catturare i War Banners vicino agli Scavi di Whelgar, sabotare le catapulte dei Fauce del Drago che si preparano all'attacco e uccidere Nek'rosh Skullcrusher, lo spietato capoclan locale. Pugnoforte cerca di spezzare l'offensiva degli orchi prima che Porto di Menethil venga travolto."}},faq={{q="Chi è il Capitano Pugnoforte?",a="Il Capitano Pugnoforte comanda le forze naniche che difendono Porto di Menethil. Organizza le difese della guarnigione, valuta le minacce in tutta la regione e recluta volontari per respingere i nemici che minacciano il porto.",al={"capitano pugnoforte","pugnoforte menethil","capitano menethil"}},{q="Dove si trova il Capitano Pugnoforte?",a="Il Capitano Pugnoforte è di stanza a Porto di Menethil, il principale centro dell'Alleanza sulla costa occidentale delle Paludi Grigie.",al={"posizione pugnoforte","dove si trova il capitano pugnoforte","trova pugnoforte"}},{q="Perché il Capitano Pugnoforte ha bisogno di aiuto esterno?",a="La guarnigione locale deve coprire tutte le Paludi Grigie con forze insufficienti. Gli orchi Fauce del Drago hanno occupato i passi montani di Dun Algaz e avanzano verso la cittadina, lasciando Pugnoforte senza truppe sufficienti per contrattaccare e difendere il porto contemporaneamente.",al={"perché pugnoforte ha bisogno di aiuto","problemi di difesa di menethil"}},{q="Chi è Nek'rosh Skullcrusher?",a="Nek'rosh Skullcrusher guida gli orchi Fauce del Drago che operano nelle Paludi Grigie. Il Capitano Pugnoforte ordina di ucciderlo per compromettere il coordinamento degli orchi e proteggere Porto di Menethil da un assalto su vasta scala.",al={"chi è nekrosh","nekrosh skullcrusher","capo fauce del drago paludi grigie"}},{q="In che modo Dun Algaz si collega alla missione del Capitano Pugnoforte?",a="Dun Algaz è il passo montano di vitale importanza che collega Loch Modan e Forgiardente alle Paludi Grigie. Quando gli orchi Fauce del Drago avanzarono nel passo, il Fuciliere Valstag Boccaferro avvertì che Menethil era in pericolo e inviò avventurieri ad aiutare il Capitano Pugnoforte a rafforzare le difese del porto.",al={"dun algaz pugnoforte","collegamento gola di algaz"}},{q="Quale minaccia rappresentano le catapulte dei Fauce del Drago?",a="Le catapulte dei Fauce del Drago potrebbero martellare le fortificazioni di Porto di Menethil durante un assedio diretto. Pugnoforte ordina ai campioni di sabotarle prima che arrivino a distanza di tiro.",al={"catapulte mossa di nekrosh","catapulte fauce del drago"}}},fx={["40162abd"]={q="Da che parte sta il Capitano Pugnoforte?",a="Il Capitano Pugnoforte serve l'Alleanza e il regno nanico di Forgiardente. Di stanza a Porto di Menethil, comanda la guarnigione della città per proteggere questo porto vitale e i viaggiatori che si spostano tra le Paludi e le montagne di Khaz Modan.",al={"fazione del capitano pugnoforte","pugnoforte è dell'alleanza","chi serve pugnoforte"}},["31290b24"]={q="Che cosa vuole il Capitano Pugnoforte?",a="Il Capitano Pugnoforte vuole eliminare una volta per tutte la minaccia degli orchi Fauce del Drago in avanzata. Vuole sottrarre i loro stendardi di guerra all'accampamento Fauce del Drago, bruciare le catapulte costruite da Nek'rosh per assediare Porto di Menethil e vedere ucciso il loro capoclan, Nek'rosh Spaccateschi, così da mettere al sicuro Porto di Menethil.",al={"obiettivi del capitano pugnoforte","di cosa ha bisogno pugnoforte","obiettivo di pugnoforte"}},["6891235c"]={q="Perché il Capitano Pugnoforte è a Porto di Menethil?",a="Il Capitano Pugnoforte è di stanza a Porto di Menethil con l'incarico di difendere il porto. Poiché gli orchi ostili Fauce del Drago hanno bloccato gli strategici passi montani di Dun Algaz, è rimasto qui per radunare soldati e mercenari a protezione del porto.",al={"perché pugnoforte è nelle paludi","ruolo del capitano pugnoforte a menethil","perché pugnoforte è qui"}},["2b51270f"]={q="Con chi è legato il Capitano Pugnoforte?",a="Il Capitano Pugnoforte coordina le operazioni con gli altri difensori dell'Alleanza a Khaz Modan e riceve rinforzi inviati da Valstag Boccaferro. Comanda la guarnigione del Forte di Menethil e si affida ai campioni dell'Alleanza di passaggio per portare la battaglia direttamente al clan Fauce del Drago.",al={"alleati del capitano pugnoforte","con chi collabora il capitano pugnoforte","contatti del capitano pugnoforte"}}},fp="17,190,20.332.0,20.365.0,20.371.1,25.212.0,35.110.0,45.226.0,29.193.0,58.260.0,44.163.0"}
P.entries["npc:captain-thalo-thas-brightsun"] = {n="Capitano Thalo'thas Chiarosole",s="Ai moli di Porto Paranco, il Capitano Thalo'thas Chiarosole si mostra cordiale con i viaggiatori dell'Alleanza. Serve il Cartello degli Spargifumo e nutre risentimento verso le forze di Theramore alla Fortezza dei Custodi del Nord perché fanno fuoco sulle sue navi.",h="Ai moli di Porto Paranco, il Capitano Thalo'thas Chiarosole si mostra cordiale con i viaggiatori...",kw={"savane","chiarosole","fortezza dei custodi del nord","porto paranco","cartello degli spargifumo","thalo'dan privateers","thalo'thas chiarosole"},ang={["faction:Alliance"]="Chiarosole ti parla cordialmente in porto, ma le forze di Theramore della Fortezza dei Custodi del Nord lo hanno spinto a cospirare in segreto con i tuoi nemici.",["faction:Horde"]="Chiarosole dà all'Orda un motivo per colpire la Fortezza dei Custodi del Nord e mettere fuori uso l'artiglieria navale dell'Alleanza lungo la costa centrale di Kalimdor."},sec={{t="Corsaro di Porto Paranco",b="Dai moli di Porto Paranco, il Capitano Thalo'thas Chiarosole guida i Thalo'dan Privateers sotto lo stendardo del Cartello degli Spargifumo. Porto Paranco accoglie mercanti di ogni bandiera che portino denaro, anche se commerciare lungo la costa delle Savane comporta dei pericoli. La Fortezza dei Custodi del Nord si trova poco a sud del porto e i suoi cannoni pesanti minacciano le rotte marittime neutrali. Chiarosole rimane cordiale con i viaggiatori in visita, ma gli attacchi della guarnigione alla sua flotta hanno messo a dura prova la sua pazienza."},{t="Una guerra privata con i Custodi del Nord",b="Chiarosole non può inviare la sua flotta contro la Fortezza dei Custodi del Nord senza mettere in pericolo la neutralità di Porto Paranco. Si rivolge invece a capaci mercenari dell'Orda per regolare i conti. I loro attacchi mirano a mettere a tacere i cannoni e a liberare i membri del suo equipaggio fatti prigionieri. Impiegando ausiliari dell'Orda, Chiarosole protegge i suoi interessi marittimi senza provocare ritorsioni dirette dell'Alleanza contro il cartello né entrare apertamente nel conflitto."}},faq={{q="Chi è il Capitano Thalo'thas Chiarosole?",a="Da Porto Paranco, il Capitano Thalo'thas Chiarosole comanda i Thalo'dan Privateers al servizio del Cartello degli Spargifumo.",al={"thalothas brightsun","chi è chiarosole","capitano di porto paranco"}},{q="Perché è adirato con la Fortezza dei Custodi del Nord?",a="Le forze dell'Alleanza della Fortezza dei Custodi del Nord hanno ripetutamente cannoneggiato le navi mercantili di Chiarosole e imprigionato i suoi marinai, ostacolando il commercio lungo la costa.",al={"perché attaccare la fortezza dei custodi del nord","problema chiarosole custodi del nord","perché odia l'alleanza"}},{q="Perché assolda solo membri dell'Orda per attaccare Northwatch?",a="Chiarosole mantiene un atteggiamento diplomatico verso i viaggiatori dell'Alleanza a Porto Paranco, ma non può chiedere ai fedeli dell'Alleanza di attaccare la propria roccaforte. L'Orda ha motivo di indebolire l'avamposto militare di Theramore.",al={"l'alleanza può fare la sua missione","perché solo l'orda","chiarosole missioni alleanza"}},{q="Appartiene all'Alleanza o all'Orda?",a="Chiarosole non appartiene a nessuna delle due fazioni. La sua lealtà va al Cartello degli Spargifumo e ai suoi corsari, anche se gli attuali rancori allineano i suoi interessi a quelli dell'Orda.",al={"fazione chiarosole","chiarosole è dell'orda","chiarosole è neutrale"}}},fx={["30395239"]={q="Perché il Capitano Thalo'thas Chiarosole è a Porto Paranco?",a="Il Capitano Chiarosole usa il porto neutrale di Porto Paranco come rifugio sicuro e base operativa per il suo equipaggio, i Corsari Thalo'dan. Operare sotto la protezione del Cartello degli Spargifumo gli permette di commerciare, riparare le sue navi e reclutare rinforzi lungo le rotte mercantili di The Barrens.",al={"perché chiarosole è qui","perché il capitano thalo'thas è a porto paranco","thalo'thas perché è a porto paranco"}},["8eff1400"]={q="Con chi è legato il Capitano Thalo'thas Chiarosole?",a="Chiarosole comanda il suo equipaggio, noto come i Corsari Thalo'dan, e opera in stretta collaborazione con il Cartello degli Spargifumo di Porto Paranco. Pur mantenendo la neutralità nei confronti dei visitatori dell'Alleanza in città, il suo feroce rancore verso la Fortezza dei Custodi del Nord lo ha spinto a cercare l'aiuto dei combattenti dell'Orda.",al={"affiliazioni di chiarosole","per chi lavora thalo'thas","alleati di thalo'thas chiarosole"}}},fp="28,209,20.444.0,29.402.0,36.115.0,35.163.0,53.193.0,44.180.0"}
P.entries["npc:captured-mountaineer"] = {n="Montanaro Catturato",s="Sotto Brill, un montanaro di Forgiardente catturato è tenuto prigioniero sotto la Taverna dell'Impiccato. I Reietti lo tengono legato per gli esperimenti della Società degli Speziali Reali.",h="Sotto Brill, un montanaro di Forgiardente catturato è tenuto prigioniero sotto la Taverna dell'Impiccato.",kw={"a new plague","speziale johaan","seminterrato di brill","montanaro catturato","prigioniero nano","taverna dell'impiccato","esploratore di forgiardente"},ang={["race:Dwarf"]="Da nano, vedere un fratello di Forgiardente in gabbia sotto una taverna dei Reietti e sottoposto a esperimenti alchemici ti rivela la loro ostilità verso i viventi.",["race:Undead"]="Da Reietto, vedi i prigionieri viventi dell'Alleanza usati dalla Società degli Speziali Reali nel tentativo di perfezionare una piaga contro il Flagello e i viventi."},sec={{t="Un prigioniero nella cantina",b="Un montanaro di Forgiardente è tenuto prigioniero sotto la Taverna dell'Impiccato a Brill, lontano da Khaz Modan. Gli avventori bevono al piano di sopra mentre la Società degli Speziali Reali prova i suoi intrugli su di lui. Lo Speziale Johaan e i suoi colleghi mettono alla prova la piaga che stanno sviluppando su prigionieri viventi dell'Alleanza. Studiano con quanta rapidità e sofferenza le tossine uccidano."}},faq={{q="Chi è il Montanaro Catturato?",a="È un esploratore dell'Alleanza proveniente da Forgiardente, tenuto prigioniero dai Reietti nel seminterrato della Taverna dell'Impiccato a Brill.",al={"chi è questo nano","nano nella taverna di brill","nano prigioniero"}},{q="Perché i Reietti lo tengono in vita nel seminterrato?",a="La Società degli Speziali Reali lo tiene in vita come cavia. Speziali come Johaan gli somministrano miscele sperimentali per studiarne gli effetti sui nani viventi.",al={"perché tenerlo in vita","perché si trova nella taverna","cosa stanno facendo al nano"}},{q="Cosa gli succede durante i test?",a="Gli speziali lo costringono a ingoiare intrugli mentre sviluppano una nuova piaga. Una miscela letale lo uccide, rivelando i progressi della tossina.",al={"il nano muore","cosa succede in a new plague"}},{q="Chi altri interagisce con lui quaggiù?",a="I Deathguard tengono i montanari catturati nella cantina della taverna finché non potranno occuparsene. Anche gli speziali vi si recano per condurre esperimenti.",al={"chi parla con il nano","renee lauer"}}},fx={["5cefef25"]={q="Da che parte sta il Montanaro Catturato?",a="Appartiene a Forgiardente e alla Grande Alleanza. I montanari nani pattugliano di solito i passi montani di Khaz Modan e i confini contesi, quindi è nemico giurato dei Reietti e dell'Orda.",al={"fazione del montanaro catturato","montanaro catturato dell'alleanza o dell'orda","da che parte sta il montanaro"}},d7cdb16d={q="Che cosa vuole il Montanaro Catturato?",a="Incatena in una cantina umida, la sua speranza principale è sopravvivere e fuggire. Purtroppo per lui, la Società degli Speziali Reali non lo considera un prigioniero di guerra da riscattare, ma una materia prima per perfezionare la loro mortale Nuova Piaga.",al={"che cosa vuole il montanaro catturato","obiettivo del montanaro catturato","desideri del montanaro catturato"}}},fp="20,162,24.332.0,32.113.0,55.164.0,37.139.1,38.145.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="Zelota Scarlatto Catturato",s="Sotto la Taverna dell'Impiccato a Brill, uno Zelota Scarlatto è tenuto prigioniero. Gli speziali dei Reietti lo usano per sperimentare intrugli per la Royal Apothecary Society.",h="Sotto la Taverna dell'Impiccato a Brill, uno Zelota Scarlatto è tenuto prigioniero.",kw={"speziale johaan","brill","zelota scarlatto catturato","taverna dell'impiccato","prigioniero","crociata scarlatta","radure di tirisfal"},ang={["class:Priest"]="Gli zeloti scarlatti rivendicano la Sacra Luce come propria. Eppure la fede incrollabile di questo prigioniero non offre alcuna difesa contro la prigionia imposta dai Reietti.",["race:Undead"]="Per i Reietti di Brill, questo fanatico incatenato rappresenta i crociati che cercano di sterminarli. Lo usano come materiale di sperimentazione per uno speziale."},sec={{t="Un prigioniero risentito a Brill",b="Sotto la Taverna dell'Impiccato, uno zelota della Crociata Scarlatta siede incatenato e ribelle. Mantiene salda la fede e chiama abomini i non morti che lo circondano. Invoca la Luce affinché lo protegga dai suoi carcerieri.\n\nI Reietti lo tengono prigioniero per lo Speziale Johaan. Essendo un umano vivente, è prezioso per lo speziale, che sperimenta la letalità di piaghe e tossine sperimentali in fase di sviluppo."}},faq={{q="Perché uno Zelota Scarlatto è tenuto in vita a Brill?",a="I Reietti lo tengono prigioniero sotto la Taverna dell'Impiccato come cavia umana vivente. La Royal Apothecary Society sta sviluppando i veleni e gli agenti chimici sperimentati su di lui.",al={"perché lo zelota scarlatto è catturato","perché tenere in vita lo zelota","chi è lo zelota nella cantina di brill"}},{q="Dove posso trovare questo prigioniero?",a="È rinchiuso nella cantina sotto la Taverna dell'Impiccato, nel centro di Brill, nelle Radure di Tirisfal.",al={"dove si trova lo zelota scarlatto catturato","posizione dello zelota scarlatto","zelota a brill"}},{q="Come reagisce ai Reietti che lo circondano?",a="Durante la prigionia mantiene un atteggiamento di fanatica sfida. Invoca la Luce affinché lo protegga dai suoi carcerieri non morti e giura che la Crociata Scarlatta libererà Azeroth dalla loro presenza.",al={"cosa dice lo zelota","dialoghi dello zelota","renee lauer e lo zelota"}}},fx={e526a97b={q="Chi è lo Zelota Scarlatto Catturato?",a="È un soldato umano catturato, appartenente alla fanatica Crociata Scarlatta. Imprigionato nella buia cantina sotto la Taverna dell'Impiccato a Brill, è sottoposto contro la sua volontà agli interrogatori, alle provocazioni e agli esperimenti alchemici dei Reietti.",al={"chi è lo zelota scarlatto catturato","chi è lo zelota nel seminterrato","prigioniero scarlatto a brill"}},["7dde551c"]={q="Da che parte sta lo Zelota Scarlatto Catturato?",a="È ferocemente leale alla Crociata Scarlatta, un ordine intransigente che si dedica a sterminare tutti i non morti. Anche incatenato e circondato dai suoi carcerieri Reietti, rifiuta di abiurare la sua fedeltà, sputando sfide e bollando i Reietti come abomini contro natura.",al={"fazione dello zelota scarlatto catturato","da che parte sta lo zelota","lealtà dello zelota"}},["69888ecc"]={q="Che cosa vuole lo Zelota Scarlatto Catturato?",a="Sopra ogni cosa, vuole la completa distruzione dei Reietti e del Flagello. Prigioniero e impotente, non desidera altro che vedere la Crociata radere al suolo Sepulcra e purgare da Lordaeron quelli che considera mostri blasfemi.",al={"obiettivo dello zelota","che cosa vuole il prigioniero","motivazioni dello zelota catturato"}},aafac6db={q="A chi è legato il Zelota Scarlatto Catturato?",a="È legato alla Crociata Scarlatta e risponde ai suoi comandanti, che combattono in tutte le Radure di Tirisfal. Sul posto è sorvegliato da vicino dallo Speziale Johaan e dagli avventori della Taverna dell'Impiccato, che lo trattano come un prigioniero nemico e una cavia per esperimenti alchemici.",al={"legami del zelota catturato","a chi risponde il zelota"}}},fp="23,155,25.375.0,44.179.0,30.96.0,45.162.0"}
P.entries["npc:carendin-halgar"] = {n="Carendin Halgar",s="Nel Magic Quarter di Sepulcra, Carendin Halgar insegna ai Reietti le arti oscure. I suoi allievi imparano a vincolare demoni della Distorsione Fatua, tra cui Voidwalkers e Succubi.",h="Nel Magic Quarter di Sepulcra, Carendin Halgar insegna ai Reietti le arti oscure.",kw={"carendin halgar","creature of the void","reietti","halgar","magic quarter","succube","the binding","istruttore","sepulcra","voidwalker","negromante"},ang={["class:Warlock"]="Come stregone, puoi imparare da Carendin Halgar a Lordaeron mentre ti guida attraverso prove per vincolare Voidwalkers e Succubi.",["faction:Horde"]="Come membro dell'Orda, puoi rivolgerti a Carendin Halgar per l'addestramento da stregone nelle terre orientali e il coordinamento con i praticanti oscuri oltremare, a Kalimdor.",["race:Undead"]="Come non morto, potresti riconoscere in Carendin Halgar lo spirito dei Reietti. Tratta i demoni come strumenti da piegare e sfruttare, senza pietà né esitazione."},sec={{t="Maestro delle Arti Oscure",b="Carendin Halgar addestra gli stregoni nel Magic Quarter di Sepulcra. Esige concentrazione e obbedienza e tollera a malapena il fallimento, l'esitazione o la debolezza. I suoi allievi vanno oltre le semplici formule magiche per evocare demoni e manipolare anime. Sotto la sua guida, imparano come i Reietti assoggettano i demoni."},{t="Sottomettere la Distorsione",b="Carendin Halgar insegna agli stregoni a vincolare demoni pericolosi alla propria volontà. Invia i suoi allievi per tutta Lordaeron e oltre, a raccogliere antiche rune, pietre runiche ed essenza mortale pura per i cerchi di evocazione. Le sue lezioni riguardano le creature del vuoto e le Succubi. Uno stregone deve vincolare un demone prima di comandarlo, affinché la creatura non divori il proprio padrone."}},faq={{q="Dove si trova Carendin Halgar?",a="Carendin Halgar si trova nel Magic Quarter di Sepulcra, tra i praticanti della magia vile e della Shadow Magic.",al={"posizione di carendin halgar","posizione istruttore stregoni sepulcra","dov'è halgar"}},{q="Che ruolo svolge Carendin Halgar per i negromanti?",a="Carendin Halgar istruisce gli stregoni dell'Orda nei rituali per evocare e vincolare demoni, tra cui Voidwalkers e Succubi.",al={"cosa fa carendin","scopo di halgar","missioni di carendin"}},{q="Com'è la personalità di Carendin Halgar?",a="Carendin Halgar è schietto ed esigente, con poca pazienza. Si aspetta risultati rapidi e disprezza le perdite di tempo e le scuse.",al={"temperamento di halgar","carendin è gentile","storia di carendin halgar"}},{q="Perché Carendin richiede cuori puri per i rituali di evocazione?",a="Durante le lezioni sull'evocazione di una succube, Spike il Giocatore, assistente di Carendin Halgar, invia gli accoliti a procurarsi i cuori incontaminati dei puri. La loro innocenza ed essenza attirano il demone in un cerchio di vincolo.",al={"scopo dei cuori puri","evocazione del succube carendin","perché i cuori puri"}},{q="Carendin Halgar interagisce con gli stregoni al di fuori di Sepulcra?",a="Sì. Carendin Halgar invia gli allievi promettenti da Strahad Farsan nelle Savane per proseguire gli studi.",al={"legami di carendin","halgar orgrimmar","gan'rul bloodeye carendin"}},{q="Da chi invia i negromanti esperti Carendin?",a="Carendin Halgar invia gli accoliti che padroneggiano i demoni di base a cercare ulteriori insegnamenti, anche presso l'eccentrico evocatore Strahad Farsan nelle Savane.",al={"seeking strahad","da chi ti manda carendin","prossimo mentore di halgar"}}},fx={["3b100529"]={q="Chi è Carendin Halgar?",a="Carendin Halgar è un rinomato addestratore di stregoni Reietti che risiede nel Magic Quarter di Sepulcra. Noto per il suo carattere severo e impaziente, istruisce gli aspiranti praticanti nelle arti oscure dell'evocazione e del vincolare entità demoniache alla propria volontà.",al={"chi è carendin halgar","storia di carendin halgar","chi è halgar"}},b7e57faa={q="Da che parte sta Carendin Halgar?",a="Carendin è fedele ai Reietti e all'Orda. Opera alla luce del sole da Sepulcra e dedica le sue conoscenze oscure a rafforzare la potenza magica dei seguaci di Sylvanas contro i nemici comuni in tutto Lordaeron.",al={"fazione di carendin halgar","chi serve carendin","carendin è fedele a sylvanas"}},ba046d55={q="Che cosa vuole Carendin Halgar?",a="Carendin vuole forgiare stregoni disciplinati e capaci, in grado di comandare i demoni senza esitazione né debolezza. Esige una rigorosa osservanza dei rituali di vincolo e mette a dura prova i suoi studenti per assicurarsi che controllino i servitori evocati, invece di diventarne vittime.",al={"che cosa vuole carendin","motivazioni di carendin halgar","obiettivi di carendin halgar"}},ea246188={q="Perché Carendin Halgar si trova qui?",a="È di stanza nel Magic Quarter di Sepulcra per istruire gli aspiranti stregoni Reietti. Sotto le rovine della Città Capitale, sovrintende alle pericolose evocazioni necessarie a vincolare al proprio servizio servitori più potenti della Distorsione Fatua.",al={"perché carendin si trova a sepulcra","perché carendin halgar è qui","motivo della posizione di carendin halgar"}},["743d4acc"]={q="A chi è legato Carendin Halgar?",a="L'assistente di Carendin è Spike il Giocatore. Inoltre, manda gli studenti dal summoner Strahad Farsan nelle Savane per ricevere ulteriori insegnamenti.",al={"alleati di carendin halgar","legami di carendin halgar","con chi collabora carendin"}}},fp="15,176,23.311.0,22.344.1,35.107.0,49.122.0,43.124.0,60.203.0,66.105.0,48.159.0"}
P.entries["npc:caretaker-folsom"] = {n="Curato Folsom",s="Lungo i Canali di Roccavento, vicino al Parco, il Curato Folsom veglia su ciò che resta di una nobile casata. Un tempo serviva la tenuta dei Flintridge e ora vende ciò che è sopravvissuto alla sua fine sanguinosa.",h="Lungo i Canali di Roccavento, vicino al Parco, il Curato Folsom veglia su ciò che resta di una nobile casata.",kw={"canali","curato folsom","flintridge","folsom","mistmantle","parco","stalvan","roccavento"},ang={["faction:Alliance"]="Come investigatore dell'Alleanza sulle tracce del più famigerato assassino di Boscovespro, puoi rivolgerti a Folsom, testimone vivente degli ultimi giorni della casata Flintridge."},sec={{t="Una casata in rovina",b="Folsom seguì le orme del padre, entrando al servizio della tenuta dei Flintridge. La famiglia fu massacrata e il maniero rimase abbandonato. I fondi rimasti finirono per esaurirsi. Lasciato a vegliare su ciò che restava, Folsom ora manda all'asta i cimeli e i beni superstiti della famiglia."},{t="Legami con un racconto oscuro",b="Gli investigatori che ripercorrono la sanguinosa storia di Stalvan Mistmantle vengono spesso indirizzati da Folsom lungo i camminamenti dei canali di Roccavento. Il dolore lo opprime ed è riluttante a parlare. Custodisce beni e documenti superstiti dei Flintridge che rivelano l'inquietante declino di Stalvan e la sua successiva scomparsa tra le ombre di Boscovespro."}},faq={{q="Chi è il Curato Folsom?",a="Il Curato Folsom si occupa di ciò che resta della tenuta dei Flintridge a Roccavento. Dopo il massacro che uccise l'intera famiglia, gli fu affidata la custodia delle proprietà rimaste.",al={"folsom","chi è folsom","storia del curato folsom"}},{q="Dove posso trovare il Curato Folsom?",a="Puoi trovare il Curato Folsom lungo i camminamenti in pietra dei Canali di Roccavento, vicino all'ingresso del Parco.",al={"dove si trova il curato folsom","posizione di folsom","curato folsom roccavento"}},{q="Cosa è successo alla famiglia Flintridge?",a="La famiglia Flintridge fu massacrata nella propria tenuta anni fa. Senza più eredi che potessero reclamarlo, il maniero fu chiuso e i suoi fondi finirono per esaurirsi.",al={"omicidio flintridge","cosa è successo ai flintridge","chi ha ucciso i flintridge"}},{q="Perché Folsom sta vendendo all'asta i cimeli di famiglia?",a="I fondi rimasti della famiglia Flintridge finirono per esaurirsi. Folsom ora manda all'asta ciò che resta dei beni della tenuta.",al={"perché l'asta","asta flintridge","asta folsom"}},{q="Qual è il suo ruolo in The Legend of Stalvan?",a="Folsom aiuta chi ricostruisce la tragedia di Stalvan Mistmantle condividendo effetti personali superstiti e indizi provenienti dal maniero dei Flintridge.",al={"folsom missione stalvan","the legend of stalvan folsom"}}},fx={["2b9b56eb"]={q="Da che parte sta il Curato Folsom?",a="Il Curato Folsom è un suddito fedele di Roccavento e un servitore devoto della tragica famiglia Flintridge. Non nutre rancore né ha alleanze politiche segrete; trascorre le sue giornate accanto ai canali della città, cercando soltanto di onorare la memoria e le ultime volontà della famiglia che lui e suo padre hanno servito fedelmente.",al={"fazione del curato folsom","chi serve folsom","lealtà di folsom"}},bbc99921={q="Perché il Curato Folsom si trova qui?",a="Trovi il Curato Folsom accanto ai canali di Roccavento perché i fondi della famiglia Flintridge sono ormai del tutto esauriti. Costretto a sistemare il patrimonio dopo la violenta fine della famiglia, è rimasto nella capitale per occuparsi dell'inventario e della vendita all'asta dei cimeli di famiglia sopravvissuti.",al={"perché folsom si trova a roccavento","perché il curato folsom è qui","che cosa ha portato folsom qui"}},["8f9af06f"]={q="A chi è legato il Curato Folsom?",a="Folsom è legato per sangue e servizio alla nobile casata dei Flintridge. Suo padre ricopriva il ruolo di curato prima di lui, e Folsom ha dedicato la vita alla cura della loro casa, finché Stalvan Mistmantle non portò rovina e massacri all'intera famiglia.",al={"legami di folsom","a chi è legato folsom","curato folsom e flintridge"}}},fp="16,184,16.277.0,19.321.1,24.182.0,34.112.0,39.152.1,43.129.0,42.139.0"}
P.entries["npc:carolai-anise"] = {n="Carolai Anise",s="A Brill, Carolai Anise insegna l'alchimia mentre i suoi esperimenti inquietano le guardie.",h="A Brill, Carolai Anise insegna l'alchimia mentre i suoi esperimenti inquietano le guardie.",kw={"alchimia","speziale","brill","carolai anise","istruttrice dei reietti","radure di tirisfal"},ang={["profession:Herbalism"]="Come raccoglitore a Tirisfal, puoi portare a Carolai peacebloom, silverleaf ed earthroot da raffinare in potenti miscele.",["race:Undead"]="Come Reietto appena liberato che impara a maneggiare i reagenti, puoi apprendere i fondamenti dell'alchimia da Carolai nelle Radure di Tirisfal."},sec={{t="Un'arte volatile",b="Carolai Anise insegna agli alchimisti novizi a Brill e si dedica ai suoi strani intrugli. Molti ricercatori dei Reietti operano sotto il cupo mandato della Società dei Farmacisti Reali. Gli esperimenti imprevedibili e le storte fumanti di Carolai sono ben noti, e le Guardie della Morte che sorvegliano Brill brontolano apertamente che sembra decisa a far saltare in aria la propria casa."}},faq={{q="Chi è Carolai Anise?",a="A Brill, Carolai Anise insegna agli aspiranti alchimisti dei Reietti a preparare pozioni, elisir e oli. È un'istruttrice di alchimia non morta nelle Radure di Tirisfal.",al={"carolai anise","alchimista di brill","chi è carolai"}},{q="Dove posso trovarla?",a="Carolai lavora con i suoi strumenti alchemici all'interno di un edificio a Brill, il principale insediamento dei Reietti nella parte centrale delle Radure di Tirisfal.",al={"dove si trova carolai anise","posizione di carolai anise","dove si trova l'istruttore di alchimia di brill"}},{q="Perché le Guardie della Morte si lamentano di lei?",a="Le Guardie della Morte si lamentano che gli esperimenti instabili di Carolai potrebbero causare un incidente. Tra scherzi e preoccupazioni, dicono che prima o poi potrebbe far saltare in aria tutta la casa.",al={"guardie della morte su carolai","far saltare in aria la casa","pericolo carolai anise"}}},fx={d66f68b4={q="Da che parte sta Carolai Anise?",a="È fedele ai Reietti e alla Dama Oscura Sylvanas Ventolesto. Opera alla luce del sole nell'insediamento di Brill e serve la comunità dei Reietti nel suo complesso, insegnando le basi della distillazione e della preparazione di bevande agli altri non morti e ai viaggiatori dell'Orda.",al={"fazione di carolai anise","carolai anise è una reietta","chi serve carolai anise"}},dbcf2ddc={q="Che cosa vuole Carolai Anise?",a="Carolai è assorbita dai suoi studi alchemici e dai suoi esperimenti volatili. Insegna il suo mestiere agli apprendisti, ma sembra decisa a proseguire con le sue spericolate miscele ribollenti, tanto che la guardia locale teme che i suoi esperimenti possano radere al suolo il suo laboratorio.",al={"motivazione di carolai anise","che cosa fa carolai anise","obiettivo di carolai anise"}},["917b8b51"]={q="Perché Carolai Anise si trova a Brill?",a="Vive a Brill per insegnare l'alchimia ai Reietti appena risvegliati e ai viaggiatori dell'Orda che emergono da Albamorta. Le Radure di Tirisfal le offrono tranquillità e materie prime in abbondanza per dedicarsi alle sue miscele e spingere la sua arte volatile fino a pericolosi estremi.",al={"perché carolai anise si trova a brill","perché carolai anise è nelle radure di tirisfal","perché carolai anise è qui"}}},fp="13,79,16.336.0,21.138.0,21.121.0,42.153.0"}
P.entries["npc:cazul"] = {n="Cazul",s="Nella Spelonca delle Ombre, Cazul guida i giovani stregoni verso il dominio sui demoni. Sebbene cieco e antichissimo, mantiene vive le antiche tradizioni degli stregoni orcheschi.",h="Nella Spelonca delle Ombre, Cazul guida i giovani stregoni verso il dominio sui demoni.",kw={"blind cazul","cazul","spelonca delle ombre","demonologia","orgrimmar","ombranube","stregone"},ang={["class:Warlock"]="Come stregone dell'Orda, puoi cercare la guida di Cazul nella Spelonca delle Ombre quando vuoi vincolare poteri più profondi della Distorsione Fatua.",["race:Orc"]="Come orco, puoi vedere in Cazul la presenza duratura della magia oscura tra la tua gente. Pratica la sua arte lontano dagli occhi vigili della guardia d'onore di Thrall."},sec={{t="Occhi nell'Oscurità",b="Sotto Orgrimmar, Cazul attende nella Spelonca delle Ombre per consigliare gli stregoni emergenti. Sebbene cieco, percepisce le correnti della Distorsione Fatua e sente i sussurri dei demoni. Chi cerca di padroneggiare la propria arte e vincolare servitori più pericolosi viene spesso indirizzato a lui. Il suo potere arcano perdura."}},faq={{q="Chi è Cazul?",a="Cazul è un anziano stregone orco cieco che vive nella Spelonca delle Ombre, sotto Orgrimmar. Consiglia gli aspiranti stregoni nelle arti della magia oscura e della demonologia.",al={"chi è cazul","storia di cazul","png blind cazul"}},{q="Perché Cazul è cieco?",a="Nessuna testimonianza spiega perché Cazul sia cieco.",al={"perché cazul è cieco","come ha perso la vista cazul"}},{q="Che ruolo ha Cazul per gli stregoni?",a="Cazul guida gli stregoni che perfezionano la propria arte, soprattutto quelli che imparano a evocare e vincolare una succube.",al={"missioni di cazul","cosa insegna cazul","missione dello stregone cazul"}}},fx={["9bd6f5fc"]={q="Da che parte sta Cazul?",a="Cazul è schierato con l'Orda e vive nell'enclave sotterranea e ombrosa di Orgrimmar. Qui, nella città del Capoguerra, i praticanti delle arti oscure operano sotto una sorveglianza diffidente, ma lui condivide pacificamente le sue conoscenze antiche con i praticanti dell'Orda che lo cercano.",al={"fazione di cazul","cazul è dell'orda","lealtà di cazul"}},f5d7dff7={q="Perché Cazul si trova nella Spelonca delle Ombre?",a="La Spelonca delle Ombre è il quartiere designato in cui i praticanti della magia oscura di Orgrimmar svolgono i loro studi lontano dagli occhi del pubblico. Cazul vi rimane per insegnare e consigliare gli stregoni in cerca di conoscenze antiche e di maestria sulle creature evocate.",al={"perché cazul è qui","cazul, orgrimmar e la spelonca","perché cazul si trova nella spelonca delle ombre"}}},fp="5,146,16.282.0,13.148.0,19.35.0,39.101.0"}
P.entries["npc:cerellean-whiteclaw"] = {n="Cerellean Manobianca",s="Vicino ai moli e alla locanda di Auberdine, Cerellean Manobianca piange il suo amore perduto. Il ricordo del Grangorgo lo tormenta ancora, e desidera dare pace allo spirito inquieto di Anaya.",h="Vicino ai moli e alla locanda di Auberdine, Cerellean Manobianca piange il suo amore perduto.",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean manobianca","rivafosca","for love eternal","fantasma","frattura"},ang={["class:Druid"]="Come druido, condividi il lungo sonno in cui Cerellean sprofondò al fianco di Malfurion Grantempesta. Il Sogno di Smeraldo non riuscì a lenire il dolore del suo cuore per l'amore terreno perduto.",["race:NightElf"]="Come Elfo della Notte, sai che il dolore di Cerellean riflette le cicatrici profonde e durature lasciate sui kaldorei dalla Guerra degli Antichi e dal Great Sundering."},sec={{t="Un amore fatto a pezzi",b="Prima della Guerra degli Antichi, Cerellean Manobianca condivideva la propria vita con Anaya Dawnrunner. Diecimila anni fa, l'invasione demoniaca devastò l'antica Kalimdor. Anaya morì quando la sua città, Ameth'aran, fu travolta dalla distruzione. Straziato dal dolore, Cerellean seguì Malfurion Grantempesta nel lungo sonno druidico.\n\nIl Sogno di Smeraldo gli offrì ben poco sollievo dai suoi ricordi. Millenni dopo, Cerellean si risvegliò e vagò per Rivafosca in preda al dolore. Lì trovò il fantasma di Anaya ancora legato alle pietre su cui era caduta."},{t="Una richiesta di liberazione",b="Cerellean desidera dare pace ad Anaya, ma non trova la forza di abbattere la sua ombra tormentata. Chiede quindi ai viaggiatori di passaggio di dirigersi a sud, alle rovine infestate di Ameth'aran, dare pace al suo spirito e recuperare il suo ciondolo.\n\nUna volta liberata, l'ombra di Anaya fa una breve visita a Cerellean sui moli di Auberdine. Gli assicura che il suo amore perdura e promette che un giorno si riuniranno nell'aldilà."}},faq={{q="Chi è Cerellean Manobianca?",a="Vicino ai moli e alla locanda di Auberdine, a Rivafosca, Cerellean Manobianca piange Anaya Dawnrunner. Morì durante la Guerra degli Antichi, diecimila anni fa.",al={"chi è cerellean","cerellean manobianca","elfo dei moli di auberdine"}},{q="Chi era Anaya Dawnrunner?",a="Anaya Dawnrunner condivideva la propria vita con Cerellean Manobianca nell'antica città di Ameth'aran. Morì quando la città fu distrutta durante la Guerra degli Antichi, e il suo spirito tormentato rimase tra le rovine per migliaia di anni.",al={"anaya dawnrunner","l'amore di cerellean","amante di cerellean"}},{q="Perché Cerellean non dona la pace allo spirito di Anaya di persona?",a="Cerellean è troppo straziato dal dolore per affrontare e distruggere di persona il fantasma di Anaya. Chiede ai viaggiatori compassionevoli di concedere al suo spirito la liberazione definitiva.",al={"perché cerellean non combatte anaya","perché serve un avventuriero"}},{q="Dove si trovano le rovine di Ameth'aran?",a="Le rovine di Ameth'aran si trovano nella parte meridionale di Rivafosca, a est della strada principale. I fantasmi degli antichi kaldorei morti durante il Great Sundering infestano la zona.",al={"dove si trova ameth'aran","posizione di anaya","dove si trova anaya"}}},fx={["20d93eae"]={q="Da che parte sta Cerellean Manobianca?",a="Cerellean è un cittadino kaldorei schierato con gli elfi della notte e l'Alleanza. Se ne sta tranquillo ad Auberdine, assorbito dal proprio dolore anziché da ambizioni politiche o militari, e cerca aiuto da qualsiasi viaggiatore sia disposto ad assisterlo.",al={"fazione di cerellean manobianca","chi serve cerellean","cerellean è dell'alleanza o dell'orda"}},f9b8a3f3={q="Che cosa vuole Cerellean Manobianca?",a="Cerellean vuole donare pace eterna allo spirito del suo amore perduto, Anaya Dawnrunner. Tormentato dalla vista del suo fantasma, vincolato alle rovine di Ameth'aran, cerca qualcuno abbastanza forte da distruggerne la forma spettrale e riportargli il suo pendente, liberandola dalla sua antica agonia.",al={"obiettivo di cerellean","di che cosa ha bisogno cerellean","obiettivo della missione di cerellean manobianca"}},["838b08c5"]={q="Perché Cerellean Manobianca si trova a Rivafosca?",a="Dopo essersi risvegliato da millenni trascorsi nel Sogno di Smeraldo insieme a Malfurion Grantempesta, Cerellean vagò per Kalimdor in preda al dolore. La sua sofferenza lo ricondusse verso le rovine di Ameth'aran, dove Anaya perì; ora indugia vicino ai moli di Auberdine, incapace di andare avanti.",al={"perché cerellean si trova ad auberdine","motivo della posizione di cerellean manobianca","perché cerellean è qui"}}},fp="19,176,19.508.0,18.387.1,27.155.0,25.235.0,57.143.0,34.152.0"}
P.entries["npc:charlga-razorflank"] = {n="Charlga Fiancospino"}
P.entries["npc:chef-breanna"] = {n="Chef Breanna",s="A Borgolago, Chef Breanna sfama i soldati di Roccavento che sorvegliano le Montagne Crestarossa. Dirige le cucine della cittadina, usando sostanziosi ingredienti locali per aiutare i difensori a resistere.",h="A Borgolago, Chef Breanna sfama i soldati di Roccavento che sorvegliano le Montagne Crestarossa.",kw={"breanna","chef breanna","cuoca","guarnigione","goulash","borgolago","redridge goulash"},ang={["faction:Alliance"]="Chef Breanna sfama i soldati che difendono il ponte e il perimetro di Borgolago. Senza i suoi piatti, la guarnigione sotto pressione potrebbe stancarsi rapidamente mentre orchi e gnoll continuano le loro incessanti incursioni.",["profession:Cooking"]="Il Redridge Goulash di Breanna trasforma ragni, condor e goretusk delle terre selvagge circostanti in un pasto sostanzioso per un avamposto militare."},sec={{t="Sfamare i difensori di Borgolago",b="Chef Breanna gestisce un ristorante nella zona nordoccidentale di Borgolago con le sue assistenti, Crystal Boughman e Gretchen Vogel. Sfama l'intero battaglione locale, le cui forze sono essenziali mentre orchi Roccianera, gnoll e murloc assediano la cittadina. La guarnigione di Roccavento è a corto di personale, quindi ogni pasto conta. La sua specialità, il Redridge Goulash, usa selvaggina e bestie delle alture circostanti per sfamare le guardie esauste."}},faq={{q="Chi è Chef Breanna?",a="Chef Breanna dirige le cucine nella zona nordoccidentale di Borgolago. Sfama i soldati di Roccavento che difendono le Montagne Crestarossa.",al={"chef breanna","breanna borgolago","chi è breanna"}},{q="In cosa le serve aiuto a Chef Breanna?",a="Chef Breanna ha bisogno di carne di selvaggina locale per il Redridge Goulash, preparato per la guarnigione. Nei dintorni di Borgolago puoi raccogliere Carne Tigliosa di Condor, musi di goretusk e Carne Croccante di Ragno.",al={"missione di breanna","ingredienti del redridge goulash","cosa vuole"}},{q="Chi lavora con Chef Breanna?",a="Crystal Boughman e Gretchen Vogel lavorano con Chef Breanna nel suo ristorante. Aiutano a gestirlo e si occupano degli abitanti e dei soldati affamati.",al={"aiutanti di breanna","crystal boughman","gretchen vogel"}}},fx={["33f751f4"]={q="Da che parte sta Chef Breanna?",a="Chef Breanna è fedele all'Alleanza e al Regno di Roccavento. Gestisce la sua cucina a Borgolago ed è direttamente responsabile dei rifornimenti per il battaglione locale di Roccavento, di stanza a difesa della città e dei confini circostanti.",al={"fazione di chef breanna","chi serve breanna","chef breanna è dell'alleanza"}},f2dfd1fc={q="Perché Chef Breanna si trova a Borgolago?",a="Breanna gestisce il ristorante cittadino nel nord-ovest di Borgolago. Il suo compito principale è tenere rifocillati e pronti al dovere i soldati locali di Roccavento, mentre le minacce che circondano Collevento si fanno sempre più pressanti; per sostentare la guarnigione si affida a ingredienti freschi del posto.",al={"perché breanna è a collerosso","perché chef breanna è a borgolago","scopo di breanna a borgolago"}}},fp="12,189,29.413.0,20.129.0,38.171.0,28.146.0"}
P.entries["npc:chef-grual"] = {n="Chef Grual",s="A Borgoscuro, Chef Grual tiene in funzione la cucina della Taverna del Corvo Scarlatto. Sfama i Night Watch e i viaggiatori stanchi, anche se alcuni ingredienti fanno sollevare qualche sopracciglio.",h="A Borgoscuro, Chef Grual tiene in funzione la cucina della Taverna del Corvo Scarlatto.",kw={"chef grual","tortini di granchio","borgoscuro","boscovespro","grual","jitters il teso","taverna del corvo scarlatto","kebab di lupo"},ang={["faction:Alliance"]="Alla Taverna del Corvo Scarlatto a Borgoscuro, Grual sfama i difensori dell'Alleanza nonostante la scarsità di carovane di rifornimenti regolari da Roccavento.",["profession:Cooking"]="Grual mostra come un cuoco in una regione isolata sfrutti la fauna locale, che cammini o zampetti tra gli alberi.",["race:Human"]="Come molti degli abitanti rimasti a Borgoscuro, Grual affronta gli orrori dei boschi avvolti nell'ombra con cupa e ostinata tenacia e abilità pratica."},sec={{t="Cucinare sotto assedio",b="Il cuoco di Borgoscuro lavora con scarse provviste. Briganti, lupi e non morti infestano le strade dalle Marche Occidentali e da Roccavento, quindi è difficile trovare rifornimenti freschi. Grual si arrangia con ciò che offre la natura selvaggia. Cucina fianchi di lupo e carne recuperata dagli avventurieri locali, usando qualunque cosa arrivi nella sua cucina."},{t="Ingredienti segreti",b="Chef Grual è noto per il Tortino di Granchio Scuro e i Seasoned Wolf Kabobs. Boscovespro si trova lontano dalla costa, così prepara i suoi tortini di granchio con le zampe appiccicose dei Venom Web Spiders locali. Che i clienti sappiano cosa stanno mangiando o preferiscano non chiedere, Grual tiene in funzione la cucina senza scusarsi."}},faq={{q="Chi è Chef Grual?",a="Chef Grual cucina alla Taverna del Corvo Scarlatto a Borgoscuro. Prepara pasti per i difensori della cittadina, i viaggiatori e i rifugiati che si nascondono dai pericoli di Boscovespro.",al={"chef grual","grual borgoscuro","cuoco di borgoscuro"}},{q="Dove posso trovare Chef Grual?",a="Chef Grual lavora nel retrobottega e nella cucina della Taverna del Corvo Scarlatto, nel centro di Borgoscuro, lungo il lato meridionale della strada principale.",al={"posizione di grual","dove si trova chef grual","trovare chef grual"}},{q="Di cosa è fatto davvero il Tortino di Granchio Scuro?",a="Il Tortino di Granchio Scuro contiene zampe appiccicose dei Venom Web Spiders che infestano le foreste circostanti. Grual le trita e ne ricava tortini che imitano il sapore dei frutti di mare.",al={"ingredienti dei tortini di granchio","tortini di granchio con ragni","cosa contiene il tortino di granchio scuro"}},{q="Quali missioni offre Chef Grual?",a="Chef Grual chiede ai viaggiatori di raccogliere fianchi di lupo per i suoi Seasoned Wolf Kabobs e zampe di ragno per il Tortino di Granchio Scuro. Prepara anche il Tortino di Granchio Scuro per Jitters il Teso, un uomo affamato che si nasconde a Boscovespro.",al={"missioni di grual","ricette di chef grual"}},{q="Perché nutre Jitters il Teso?",a="Jitters il Teso si nasconde da settimane in una cittadina fantasma di Boscovespro, nutrendosi di larve ed erbacce. Affamato e desideroso di un pasto decente, manda i viaggiatori da Grual a prendere il Tortino di Granchio Scuro.",al={"cibo per jitters","lo stomaco brontolante di jitters grual"}},{q="Grual è affiliato a The Night Watch?",a="Chef Grual è un cuoco civile, non una guardia. La sua cucina sfama i Night Watch e la milizia locale mentre affrontano un assedio costante.",al={"grual the night watch","grual combatte"}}},fx={ccc14f35={q="Da che parte sta Chef Grual?",a="Chef Grual è fermamente dalla parte degli abitanti di Borgoscuro e dell'Alleanza. Mentre la città rimane isolata e infestata dalle ombre, Grual tiene acceso il focolare della Taverna del Corvo Scarlatto, preparando pasti per gli abitanti del posto, i viaggiatori stanchi e i difensori della città.",al={"fazione di chef grual","chi serve chef grual","chef grual è dell'alleanza"}},["3ac222da"]={q="Che cosa vuole Chef Grual?",a="Grual vuole mantenere ben fornita la Taverna del Corvo Scarlatto nonostante la situazione pericolosa di Boscovespro. Con le rotte commerciali interrotte e il bestiame fresco scarso, si affida ai viaggiatori avventurosi per procurarsi ingredienti locali insoliti, come carne di lupo e zampe viscide di ragno, con cui sfamare gli affamati avventori della città.",al={"di cosa ha bisogno chef grual","ingredienti di chef grual","obiettivo di chef grual"}},["91c4d31a"]={q="Perché Chef Grual si trova qui?",a="Grual è il cuoco residente di Borgoscuro e lavora alla Taverna del Corvo Scarlatto. Mentre molti sono fuggiti dall'oscurità che avanza su Boscovespro, Grual è rimasto a gestire la cucina e a fare la sua parte per aiutare l'insediamento isolato a sopravvivere.",al={"perché chef grual è a boscovespro","perché grual resta a borgoscuro","ruolo di chef grual"}}},fp="10,160,19.305.0,18.290.1,18.158.0,28.137.0,43.148.1,34.197.1,25.157.0,41.128.0"}
P.entries["npc:chef-jessen"] = {n="Chef Jessen",s="A Riva del Sud, Chef Jessen sfama la cittadina mentre le tensioni ai confini restano alte. La sua bisque di tartaruga è famosa.",h="A Riva del Sud, Chef Jessen sfama la cittadina mentre le tensioni ai confini restano alte.",kw={"chef jessen","cucina","alture di colletorto","jessen","lago lordamere","snapjaw","riva del sud","bisque di tartaruga"},ang={["faction:Alliance"]="A Riva del Sud, Chef Jessen contribuisce a sfamare i soldati dell'Alleanza e gli avventurieri che mantengono la linea difensiva contro le minacce da nord.",["profession:Cooking"]="Se sei un cuoco di passaggio a Colletorto, puoi chiedere a Chef Jessen la ricetta della sua bisque di tartaruga. È un pasto sostanzioso per viaggiatori temprati."},sec={{t="Un cuoco a Riva del Sud",b="Chef Jessen fornisce carne e provviste a Riva del Sud, nella parte meridionale delle Alture di Colletorto. Gli abitanti e i soldati dell'Alleanza di passaggio contano sulle sue provviste, ed è un abile cuoco.\n\nPrima che la piaga e la guerra sconvolgessero Lordaeron settentrionale, Chef Jessen viaggiava spesso verso nord, oltre Dalaran, fino alle rive del Lago Lordamere. Lì raccoglieva carne dalle tartarughe snapjaw autoctone per la sua Soothing Turtle Bisque. I viaggiatori che aiutano a raccoglierne gli ingredienti possono imparare la ricetta da lui."}},faq={{q="Chi è Chef Jessen?",a="Chef Jessen è un macellaio e cuoco umano di Riva del Sud, nelle Alture di Colletorto. Vende carne e condivide ricette locali con i viaggiatori che sostengono l'Alleanza.",al={"jessen","chef jessen riva del sud","chi è jessen"}},{q="Qual è il piatto famoso di Chef Jessen?",a="Chef Jessen è famoso per la sua Soothing Turtle Bisque. In passato raccoglieva carne di tartaruga snapjaw nei pressi del Lago Lordamere, a nord oltre Dalaran, per preparare quel brodo sostanzioso.",al={"ricetta bisque di tartaruga","specialità di jessen","soothing turtle bisque"}},{q="Perché Chef Jessen chiede aiuto ai viaggiatori?",a="Raccogliere carne di tartaruga snapjaw attorno al Lago Lordamere è diventato pericoloso a causa dell'instabilità della regione e della vicina presenza dei Reietti. Chef Jessen conta su viaggiatori capaci per raccogliere la carne per la sua bisque.",al={"missione di jessen","missione carne di tartaruga"}},{q="Chef Jessen vende qualcosa di insolito?",a="Chef Jessen vende carne agli abitanti di Riva del Sud. Insegna la ricetta della sua Soothing Turtle Bisque ai cuochi che aiutano a raccogliere carne di tartaruga snapjaw.",al={"specialità di jessen","venditore di cibo jessen"}}},fx={["4b3f98b6"]={q="Da che parte sta Chef Jessen?",a="Chef Jessen è fedele all'Alleanza. Vive e lavora a Riva del Sud, il principale rifugio umano e baluardo dell'Alleanza lungo la costa meridionale delle Alture di Colletorto, e prepara da mangiare per gli abitanti del posto e i viaggiatori che lottano per tenere la posizione a Lordaeron.",al={"chef jessen è dell'alleanza o dell'orda","chef jessen è dell'alleanza","fazione di chef jessen"}},["73d1d0ab"]={q="Perché Chef Jessen si trova a Riva del Sud?",a="Chef Jessen lavora come macellaio e cuoco a Riva del Sud. Un tempo viaggiava oltre Dalaran fino al Lago Lordamere per cacciare personalmente le chele-morso, ma ormai preferisce restare al sicuro in città e affidarsi ai passanti avventurosi per procurarsi ingredienti freschi.",al={"perché chef jessen è a riva del sud","perché chef jessen è qui","cosa ha portato chef jessen a colletorto"}}},fp="11,106,20.464.0,19.162.0,34.167.0,44.203.0,39.135.0"}
P.entries["npc:chief-archaeologist-greywhisker"] = {n="Capo Archeologo Baffogrigio",s="All'esterno del Temple of the Moon a Darnassus, il Capo Archeologo Baffogrigio raccoglie rapporti dalla costa. Il nano di Forgiardente coordina le ricerche della Lega degli Esploratori e tiene d'occhio i colleghi a Rivafosca.",h="All'esterno del Temple of the Moon a Darnassus, il Capo Archeologo Baffogrigio raccoglie rapporti dalla costa.",kw={"agamaggan","capo archeologo","rivafosca","darnassus","lega degli esploratori","baffogrigio","forgiardente","tarelvir","temple of the moon"},ang={["faction:Alliance"]="Come membro dell'Alleanza, Baffogrigio mantiene i contatti tra la Lega degli Esploratori di Forgiardente e le spedizioni in tutta Kalimdor settentrionale.",["race:Dwarf"]="Da nano, vedere uno dei principali studiosi di Forgiardente all'esterno del Temple of the Moon ti ricorda l'impulso del tuo popolo a scoprire la storia antica in tutta Kalimdor.",["race:NightElf"]="Per te che sei un elfo della notte, Baffogrigio porta nella tua città la nuova alleanza dei Regni Orientali. Parla con gli studiosi all'esterno del tempio di Elune del passato del continente."},sec={{t="Uno studioso nano a Darnassus",b="Il Capo Archeologo Baffogrigio lavora lontano dalla sua casa a Forgiardente, all'esterno del Temple of the Moon a Darnassus. La Lega degli Esploratori lo ha inviato oltre il mare, a Kalimdor, per svolgere ricerche sul campo. Parla con studiosi elfi della notte come Tarelvir e cerca di conoscere queste antiche terre. A Forgiardente, le sue lezioni trattavano antiche conoscenze ed esseri primordiali, tra cui l'Antico Dio Agamaggan. Ora spera di scoprire cosa custodiscano le terre ancestrali degli elfi della notte."},{t="Occhi su Rivafosca",b="Baffogrigio supervisiona gli scavi dei nani a Kalimdor e segue le spedizioni che esplorano le antiche rovine costiere. Per raggiungere i prospettori oltre il mare, a Rivafosca, si affida ai viaggiatori perché portino i suoi messaggi. La ricerca sul campo in terre inesplorate è pericolosa. Attende con ansia notizie dai siti di scavo e spera che i suoi colleghi siano al sicuro tra le rovine."}},faq={{q="Chi è il Capo Archeologo Baffogrigio?",a="Il Capo Archeologo Baffogrigio è uno studioso nano di Forgiardente e un rappresentante della Lega degli Esploratori. All'esterno del Temple of the Moon a Darnassus, coordina le ricerche della Lega a Kalimdor settentrionale e parla con studiosi elfi della notte.",al={"chi è baffogrigio","storia di baffogrigio","capo archeologo"}},{q="Cosa ci fa un nano di Forgiardente a Darnassus?",a="La Lega degli Esploratori ha inviato Baffogrigio oltre il mare per riportare alla luce la storia dimenticata e antichi manufatti. Stringe contatti con gli studiosi nella capitale degli elfi della notte e supervisiona le spedizioni dei nani lungo le antiche coste di Kalimdor.",al={"perché un nano è a darnassus","nano temple of the moon"}},{q="Qual è il suo legame con Agamaggan?",a="A Forgiardente, Baffogrigio teneva lezioni di storia antica, parlando anche dell'Antico Dio Agamaggan, un cinghiale gigante. I suoi insegnamenti hanno ispirato prospettori più giovani come Lonebrow a studiare le leggende sulle bestie antiche.",al={"baffogrigio agamaggan","lezioni su agamaggan"}},{q="Con chi sta parlando Baffogrigio all'esterno del tempio?",a="All'esterno del Temple of the Moon a Darnassus, Baffogrigio parla con Tarelvir, uno studioso elfo della notte. Si scambiano idee e coordinano le ricerche storiche tra i loro popoli.",al={"baffogrigio tarelvir","chi c'è con baffogrigio"}},{q="Quali problemi sta affrontando a Rivafosca?",a="I colleghi ricercatori nani di Baffogrigio stanno scavando tra le antiche rovine di Rivafosca, ma le spedizioni isolate sono difficili da raggiungere. Cerca corrieri che controllino come stanno i prospettori distratti e recuperino i loro diari di ricerca.",al={"baffogrigio rivafosca","prospettori rivafosca"}},{q="A quale fazione appartiene Baffogrigio?",a="Baffogrigio appartiene alla Lega degli Esploratori, un'organizzazione archeologica di Forgiardente dedita alla scoperta delle origini dei nani e della storia antica. La Lega è schierata con l'Alleanza.",al={"fazione di baffogrigio","lega degli esploratori darnassus"}}},fp="31,217,30.450.0,17.348.0,39.253.0,46.224.0,36.195.0,49.177.0,45.220.0,41.187.0"}
P.entries["npc:chief-engineer-hinderweir-vii"] = {n="Capo Ingegnere Hinderweir VII",s="In cima alla Diga di Pietrasalda, il Capo Ingegnere Hinderweir VII sorveglia i suoi meccanismi e le sue difese. Il nano veterano mantiene in buono stato la grande struttura e i suoi macchinari mentre gravi pericoli la minacciano.",h="In cima alla Diga di Pietrasalda, il Capo Ingegnere Hinderweir VII sorveglia i suoi meccanismi e le sue...",kw={"a dark threat looms","nano","ingegnere","hinderweir","loch modan","sabotaggio","diga di pietrasalda"},ang={["faction:Alliance"]="Come membro dell'Alleanza, non puoi permettere che la diga ceda. La sua distruzione interromperebbe le rotte di rifornimento e devasterebbe le terre alleate a nord di Loch Modan.",["profession:Engineering"]="Come ingegnere, puoi apprezzare gli imponenti macchinari della diga, dove l'architettura civile incontra il controllo meccanico.",["race:Dwarf"]="Come nano, puoi comprendere il solenne dovere di Hinderweir: proteggere le più grandi opere in pietra di Khaz Modan dalla malvagità esterna."},sec={{t="Il Signore della Diga",b="Il Capo Ingegnere Hinderweir VII si occupa della Diga di Pietrasalda, le cui opere in pietra trattengono le acque di Loch Modan. Lungo la sommità, sorveglia i canali e le paratoie. Controlla anche le sollecitazioni causate dagli elementi e dai pericoli locali. I meccanismi della diga richiedono cure costanti."},{t="Sabotaggio e sovversione",b="Il Capo Ingegnere Hinderweir VII scopre alla diga tracce di un sabotaggio pianificato. Una breccia potrebbe inondare le pianure e distruggere le delicate infrastrutture di Khaz Modan. Perciò chiama fidati avventurieri dell'Alleanza a indagare sul complotto, disinnescare gli esplosivi nascosti e fermare la minaccia prima che la pietra ceda."}},faq={{q="Chi è il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII si occupa della manutenzione e della difesa della Diga di Pietrasalda, nella parte settentrionale di Loch Modan.",al={"hinderweir","capo ingegnere","ingegnere della diga"}},{q="Dove posso trovare il Capo Ingegnere Hinderweir VII?",a="Puoi trovare il Capo Ingegnere Hinderweir VII sul camminamento in cima alla Diga di Pietrasalda. La diga attraversa il margine settentrionale di Loch Modan, vicino al confine con le Paludi Grigie.",al={"posizione di hinderweir","dove si trova hinderweir","trovare hinderweir"}},{q="Cos'è la Diga di Pietrasalda?",a="La Diga di Pietrasalda è una grande struttura nanica che trattiene le acque di Loch Modan. Impedisce che si riversino con violenza nelle paludi più a valle, a nord.",al={"cos'è la diga","scopo della diga di pietrasalda","perché la diga è importante"}},{q="Di quali minacce si preoccupa Hinderweir?",a="Il Capo Ingegnere Hinderweir VII indaga su un sabotaggio alla diga. Ha trovato tracce di oscuri complotti e ordigni esplosivi collocati per spaccarne le fondamenta.",al={"minacce alla diga","a dark threat looms","chi vuole distruggere la diga"}},{q="Perché il suo nome include \"VII\"?",a="VII è il numero romano che indica sette. Nessun documento spiega perché compaia nel nome di Hinderweir.",al={"nome di hinderweir","perché il settimo","significato di hinderweir vii"}},{q="Quali missioni offre il Capo Ingegnere Hinderweir?",a="Il Capo Ingegnere Hinderweir VII offre la serie di missioni chiamata 'A Dark Threat Looms'. La serie manda gli avventurieri a indagare sulle manomissioni e a proteggere la Diga di Pietrasalda dalla distruzione.",al={"missioni di hinderweir","missioni alla diga","missione a dark threat looms"}}},fx={["35f113ec"]={q="Da che parte sta il Capo Ingegnere Hinderweir VII?",a="Il Capo Ingegnere Hinderweir VII è un fiero nano fedele a Forgiardente e all'Alleanza. Di stanza alla Diga di Pietrasalda, a Loch Modan, il suo compito principale è proteggere una delle più grandi meraviglie ingegneristiche del regno nanico da ogni minaccia esterna.",al={"fazione di hinderweir","hinderweir è dell'alleanza","chi serve hinderweir"}},["3db73bdf"]={q="Che cosa vuole il Capo Ingegnere Hinderweir VII?",a="Hinderweir vuole garantire l'assoluta integrità e difesa della Diga di Pietrasalda. Sospettando un sabotaggio e un complotto ai danni dell'imponente struttura, cerca avventurieri affidabili che indaghino sulle attività sospette nelle vicinanze e neutralizzino ogni minaccia oscura prima che una catastrofe colpisca Loch Modan.",al={"obiettivo di hinderweir","cosa vuole il capo ingegnere hinderweir","motivazioni di hinderweir"}},["53bdb0ce"]={q="Perché il Capo Ingegnere Hinderweir VII si trova qui?",a="In qualità di ingegnere capo responsabile della Diga di Pietrasalda, Hinderweir è di stanza proprio sulla massiccia struttura per supervisionarne il funzionamento e la sicurezza. Rimane vigile sul posto per occuparsi dei problemi strutturali e affrontare i pericoli imminenti che minacciano il lago.",al={"perché hinderweir è alla diga","perché il capo ingegnere hinderweir è qui","scopo di hinderweir a loch modan"}}},fp="29,202,17.275.0,23.300.1,37.92.0,47.150.0,29.162.0,41.152.0,32.91.0,49.173.0"}
P.entries["npc:chief-hawkwind"] = {n="Capo Vento Agile",s="A Campo Narache, Capo Vento Agile prepara i giovani Shu'halo alla vita oltre la Mesa Nuvola Rossa. Guida i loro riti tradizionali a Mulgore e insegna l'umiltà, il rispetto per la terra e la forza necessaria a proteggere la loro gente.",h="A Campo Narache, Capo Vento Agile prepara i giovani Shu'halo alla vita oltre la Mesa Nuvola Rossa.",kw={"a humble task","bristleback","campo narache","capo vento agile","mulgore","mesa nuvola rossa","rite of strength","rites of the earthmother","capotribù tauren"},ang={["faction:Horde"]="Come membro dell'Orda, ti unisci ai nuovi prodi tauren, che gli insegnamenti di Vento Agile hanno reso abili guerrieri e incantatori, nonché alleati saldi e onorevoli.",["race:Tauren"]="Come tauren, apprendi da Capo Vento Agile i valori fondamentali degli Shu'halo: il rispetto per l'Earthmother, la lealtà verso la tua tribù e l'umiltà nella forza."},sec={{t="Capotribù della Mesa",b="A Campo Narache, Capo Vento Agile prepara i giovani tauren alla vita oltre la Mesa Nuvola Rossa. Cacciatori, sciamani, druidi e guerrieri alle prime armi affrontano gli antichi Rites of the Earthmother sulla mesa. Vento Agile sovrintende alle loro usanze e insegna a ogni giovane il senso del dovere e la resistenza prima che lasci quel luogo sicuro."},{t="Guidare i riti",b="Capo Vento Agile comincia dall'umiltà, non dalla gloria marziale. Invia gli iniziati ad attingere acqua pulita di sorgente e a svolgere semplici faccende, insegnando il rispetto per la natura e gli anziani. Una volta dimostrata la loro umiltà, i prodi affrontano prove di abilità marziale. Le prove saggiano la loro determinazione contro gli aggressivi verrospino Bristleback che invadono le pianure ancestrali."},{t="Difendere Campo Narache",b="Il pericolo incombe su Campo Narache. La tribù Bristleback si fa sempre più audace lungo il perimetro della Mesa Nuvola Rossa. Vento Agile coordina la difesa dell'insediamento e invia i prodi appena messisi alla prova a contenere gli assalti dei verrospino e proteggere il sacro Cortile d'Addestramento."}},faq={{q="Chi è Capo Vento Agile?",a="Capo Vento Agile guida Campo Narache sulla Mesa Nuvola Rossa. Sovrintende alle questioni tribali e fa da mentore ai giovani tauren che si preparano ad avventurarsi nel vasto mondo di Mulgore e Kalimdor.",al={"hawkwind","storia di capo vento agile","chi è il capo di campo narache"}},{q="Cosa sono i Rites of the Earthmother?",a="I Rites of the Earthmother sono prove sacre che i giovani tauren affrontano al raggiungimento dell'età adulta. Anziani come Capo Vento Agile guidano i riti, che mettono alla prova l'umiltà, la forza, il coraggio e i legami spirituali con la terra e gli antenati.",al={"riti tauren","rites of the earthmother","cosa sono i riti"}},{q="Perché Capo Vento Agile ti fa prendere prima l'acqua?",a="Capo Vento Agile ti manda ad attingere acqua per insegnarti che il servizio e il rispetto per la comunità contano quanto la forza marziale. Attingere acqua fresca per gli anziani della tribù insegna pazienza e umiltà prima che gli iniziati affrontino la battaglia.",al={"a humble task","perché raccogliere l'acqua","missione dell'acqua di vento agile"}},{q="Quale minaccia sta affrontando Campo Narache?",a="I verrospino ostili della tribù Bristleback, provenienti dalle colline attorno alla Mesa Nuvola Rossa, mantengono Campo Narache sotto pressione. Capo Vento Agile organizza la difesa della mesa e invia gli iniziati a sfoltire le loro file.",al={"minacce a campo narache","chi sta attaccando campo narache","verrospino campo narache"}},{q="Dove manda gli avventurieri Capo Vento Agile dopo?",a="Quando un giovane prode completa i riti preliminari sulla mesa, Capo Vento Agile lo invia nelle valli di Mulgore. Il giovane raggiunge il Villaggio di Zoccolo Sanguinario per trovare il Capo Baine Zoccolo Sanguinario, figlio di Cairne, e proseguire i Rites of the Earthmother.",al={"dove andare dopo vento agile","dopo campo narache","lasciare mesa nuvola rossa"}},{q="Capo Vento Agile è imparentato con Madre Anziana Vento Agile?",a="Sì. Madre Anziana Vento Agile è la madre di Capo Vento Agile. La loro famiglia ha radici profonde e una lunga tradizione di guida tra i tauren della Mesa Nuvola Rossa.",al={"parentela madre anziana vento agile","famiglia vento agile","chi è madre anziana vento agile"}}},fx={c01d188d={q="Da che parte sta il Capo Vento Agile?",a="Il Capo Vento Agile è leale ai suoi compagni tauren e all'Orda. In quanto capo tribù di stanza alla Mesa Nuvola Rossa, lavora direttamente per guidare e rafforzare le nuove generazioni di difensori tauren, preparandoli a servire sia il proprio popolo sia l'Orda in generale.",al={"fazione del capo vento agile","vento agile è dell'orda o dell'alleanza","chi serve il capo vento agile"}},e0733ded={q="Che cosa vuole il Capo Vento Agile?",a="Vento Agile vuole proteggere Campo Narache e assicurarsi che i giovani tauren siano messi alla prova a fondo prima di avventurarsi per Kalimdor. Sovrintende ai sacri Rites of the Earthmother e mette alla prova la tua umiltà e la tua forza contro l'avanzata dei suini Spinavile, affinché tu possa servire il tuo popolo con onore.",al={"qual è l'obiettivo del capo vento agile","scopo del capo vento agile","cosa vuole vento agile"}},d395b627={q="Perché il Capo Vento Agile si trova a Campo Narache?",a="Il Capo Vento Agile vive a Campo Narache per occuparsi delle questioni tribali locali e guidare i giovani avventurieri nelle loro prime prove. Dall'alto della mesa sorveglia il Cortile d'Addestramento e organizza la difesa contro gli aggressivi suini Spinavile, che tormentano continuamente il campo.",al={"perché il capo vento agile è qui","perché vento agile è a campo narache","perché il capo vento agile si trova qui"}}},fp="14,217,21.298.0,17.351.0,22.254.0,22.164.0,38.223.0,51.222.0,35.181.0,48.236.0,50.150.0"}
P.entries["npc:christoph-jeffcoat"] = {n="Christoph Jeffcoat",s="A Mulino di Tarren, Christoph Jeffcoat rifornisce i Reietti di merci per il commercio e i viaggi. Le sue merci servono artigiani e viaggiatori nelle Alture di Colletorto, dove l'Alleanza e la Lega dei Tagliagole si contendono il territorio.",h="A Mulino di Tarren, Christoph Jeffcoat rifornisce i Reietti di merci per il commercio e i viaggi.",kw={"christoph jeffcoat","mercante dei reietti","colletorto","spezie lenitive","mulino di tarren","forniture commerciali","mercante di forniture"},ang={["faction:Horde"]="Come campione dell'Orda impegnato nelle campagne delle Alture di Colletorto, puoi trovare materiali per l'artigianato e attrezzi comuni nella bottega di Christoph Jeffcoat a Mulino di Tarren.",["profession:Cooking"]="Come cuoco a Colletorto, puoi comprare spezie lenitive da Christoph Jeffcoat. Portagli carne di snapjaw e ti insegnerà la sua ricetta della bisque di tartaruga."},sec={{t="Un mercante in prima linea",b="A Mulino di Tarren, Christoph Jeffcoat rifornisce la roccaforte dei Reietti di ciò che serve ai suoi abitanti. Vende reagenti, attrezzi, fili e spezie a soldati e artigiani di passaggio. Tra le sue merci si trovano spezie per la bisque di tartaruga, schemi rari e fiale alchemiche. Le forze dell'Orda che attraversano il sud di Lordaeron contano su queste scorte per affrontare Riva del Sud e i pericoli della regione."}},faq={{q="Dove posso trovare Christoph Jeffcoat?",a="Puoi trovare Christoph Jeffcoat a Mulino di Tarren, la principale roccaforte dei Reietti e dell'Orda nelle Alture di Colletorto settentrionali.",al={"posizione di christoph jeffcoat","dove si trova jeffcoat","mercante di forniture a mulino di tarren"}},{q="Che genere di merci vende?",a="Vende fili da sartoria, martelli da fabbro, fondenti, fiale alchemiche e spezie da cucina, tra cui spezie lenitive e spezie piccanti. Offre anche alcune ricette selezionate.",al={"cosa vende jeffcoat","mercanzie di christoph jeffcoat","oggetti di jeffcoat"}},{q="Perché è importante per i cuochi locali?",a="Jeffcoat vende spezie lenitive per la bisque di tartaruga e insegna la ricetta ai cuochi dell'Orda che gli portano carne di tartaruga degli snapjaws.",al={"venditore spezie lenitive colletorto","ingredienti bisque di tartaruga","cucina di jeffcoat"}}},fx={["36cd3db3"]={q="Chi è Christoph Jeffcoat?",a="Christoph Jeffcoat è un mercante non morto di stanza a Mulino di Tarren, nelle Alture di Colletorto. Serve i Reietti fornendo merci, materie prime e componenti per la creazione agli avventurieri, agli artigiani e ai difensori che tengono la linea del fronte dell'Orda nella regione.",al={"chi è christoph jeffcoat","identità di christoph jeffcoat","chi è jeffcoat"}},["1470d19f"]={q="Da che parte sta Christoph Jeffcoat?",a="Christoph Jeffcoat è fermamente fedele ai Reietti e all'Orda. Di stanza nell'avamposto conteso di Mulino di Tarren, serve direttamente gli avventurieri e i campioni dell'Orda che combattono le forze dell'Alleanza provenienti dalla vicina Riva del Sud.",al={"fazione di christoph jeffcoat","christoph jeffcoat è dell'orda","chi serve christoph jeffcoat"}},["7ff6f152"]={q="Perché Christoph Jeffcoat si trova a Mulino di Tarren?",a="Poiché Mulino di Tarren funge da caposaldo settentrionale delle operazioni dell'Orda nelle Alture di Colletorto, artigiani e combattenti restano spesso a corto di beni di prima necessità. Christoph Jeffcoat è di stanza qui per assicurarsi che merci, fiale, fili e spezie siano sempre disponibili a chi difende l'avamposto.",al={"perché christoph è a mulino di tarren","perché christoph jeffcoat è qui","perché jeffcoat è a colletorto"}}},fp="18,207,29.374.0,36.119.0,33.167.0,36.140.0"}
P.entries["npc:chronormu"] = {n="Chronormu",s="Nelle Terre Infette Occidentali, Chronormu lavora per risanare i fili danneggiati del tempo. I mortali la conoscono come Cromie, un drago di bronzo che spesso lavora al loro fianco.",h="Nelle Terre Infette Occidentali, Chronormu lavora per risanare i fili danneggiati del tempo.",kw={"andorhal","drago di bronzo","cromie","chronormu","nozdormu","sembianza"},ang={["class:Mage"]="Come mago che studia la cronomanzia, potresti trovare affascinanti, e sbalorditive nella loro portata, la disinvoltura con cui Chronormu domina il tempo e le sacche temporali localizzate.",["race:Gnome"]="Come gnomo, potresti incontrare Chronormu nelle vesti di Cromie, una figura allegra le cui piccole sembianze celano un drago di bronzo."},sec={{t="Un drago in minuscole sembianze",b="I mortali conoscono Chronormu come Cromie, una gnoma eccentrica e allegra. Appartiene allo stormo dei draghi di bronzo ed è al servizio di Nozdormu, il Senza Tempo. I titani incaricarono i draghi di bronzo di custodire la storia e correggere le perturbazioni nelle vie temporali. Nelle sue sembianze di gnoma, Chronormu cammina tra i mortali come una compagna alla mano e ottimista."},{t="Custode delle Terre Infette",b="Tra i resti in rovina di Lordaeron, Chronormu veglia sulle devastate Terre Infette Occidentali. La caduta del regno e la diffusione del Flagello lacerarono la storia della regione, lasciando anomalie temporali e vestigia intrappolate. Da luoghi come le Ruins of Andorhal, lavora con discrezione insieme agli avventurieri mortali per risanare le linee temporali aggrovigliate e indagare sulle perturbazioni. Solo quando è necessario rivela tutta la maestosità dello stormo dei draghi."}},faq={{q="Cromie è davvero una gnoma?",a="No. Cromie è la forma mortale di Chronormu; lei è un drago di bronzo. I draghi di bronzo assumono forme mortali per camminare tra le razze più giovani senza suscitare timori o sospetti eccessivi.",al={"cromie è una gnoma","vera forma di cromie","chi è cromie"}},{q="Perché Cromie ha due nomi?",a="Chronormu è il suo vero nome di drago di bronzo. Tra i mortali, usa il nome più breve Cromie nelle sue sembianze di gnoma.",al={"genere del nome chronormu","perché cromie si chiama chronormu","genere di chronormu"}},{q="Cosa fa Cromie nelle Terre Infette Occidentali?",a="La devastazione di Lordaeron per mano del Flagello sconvolse la storia e le vie temporali. Dalle rovine, Cromie indaga sulle anomalie temporali, annulla le perturbazioni della storia e recluta avventurieri fidati per riparare i fili danneggiati del tempo.",al={"cosa fa qui cromie","perché cromie si trova ad andorhal","cromie terre infette occidentali"}},{q="Chi è lo stormo dei draghi di bronzo?",a="Guidato da Nozdormu, il Dragon Aspect, lo stormo dei draghi di bronzo ricevette dai titani il potere sulle vie del tempo. I suoi membri proteggono quelle vie e intervengono quando il tempo viene alterato o corrotto, affinché la storia segua il corso previsto.",al={"draghi di bronzo","cos'è lo stormo di bronzo","stormo di nozdormu"}}},fp="9,149,23.333.0,26.430.0,26.166.0,32.115.0,49.234.0,32.234.0"}
P.entries["npc:clarice-foster"] = {n="Clarice Foster",s="Nelle Pozze delle Visioni, Clarice Foster dimora tra veggenti e mistici tauren. Lontana da Lordaeron, la donna Reietta trascorre le sue giornate in contemplazione sotto le alture di Mulgore.",h="Nelle Pozze delle Visioni, Clarice Foster dimora tra veggenti e mistici tauren.",kw={"clarice foster","reietti","pozze delle visioni","altura degli spiriti","picco del tuono","finché morte non ci separi"},ang={["race:Tauren"]="Come tauren, vedi Clarice Foster accolta nelle sacre Pozze delle Visioni sotto l'Altura degli Spiriti. La sua presenza mostra la disponibilità del tuo popolo a ospitare nuovi membri insoliti dell'Orda.",["race:Undead"]="Per te che sei un Reietto, Clarice Foster riflette i legami del tuo popolo con gli alleati tauren di Kalimdor, lontano dal suolo contaminato di Tirisfal e Silverpine."},sec={{t="Una Reietta nelle Pozze delle Visioni",b="La maggior parte dei Reietti rimane a Lordaeron, ricostruendo il proprio regno sotto Sepulcra. Clarice Foster ha raggiunto Kalimdor e il cuore delle terre dei tauren. Vive nelle cavernose Pozze delle Visioni sotto l'altopiano di Picco del Tuono. Lì dimora tra speziali Reietti e sciamani tauren che studiano i misteri spirituali ed elementali della terra."}},faq={{q="Chi è Clarice Foster?",a="Clarice Foster è una donna Reietta che dimora nelle Pozze delle Visioni sotto Picco del Tuono. Inviata tra i tauren di Mulgore, è una dei pochi visitatori non morti che vivono con loro.",al={"chi è clarice","clarice foster png","storia di clarice foster"}},{q="Dove posso trovare Clarice Foster?",a="Puoi trovare Clarice Foster nelle Pozze delle Visioni, un complesso di caverne sotto l'Altura degli Spiriti a Picco del Tuono.",al={"posizione di clarice foster","dove si trova clarice foster","trova clarice foster"}},{q="Quali missioni offre?",a="Clarice Foster offre Until Death Do Us Part. Amareggiata perché il defunto marito l'ha lasciata per combattere i non morti ed è morto, manda i viaggiatori a deporre il suo pendente sulla sua tomba a Mausolea, nella Selva Pinargento.",al={"missioni di clarice foster","missione finché morte non ci separi"}}},fx={["4e89059e"]={q="Da che parte sta Clarice Foster?",a="Clarice Foster è schierata con i Reietti e con l'Orda in generale. Anche se i suoi incarichi la tengono lontana da Lordaeron, nelle sotterranee Pozze delle Visioni a Picco del Tuono, resta fedele alla Regina Sylvanas e alla causa dei Reietti.",al={"fazione di clarice foster","alleanza di clarice foster","chi serve clarice foster"}}},fp="14,180,33.346.0,22.185.0,32.104.0,27.203.0"}
P.entries["npc:clerk-daltry"] = {n="Cancelliere Daltry",s="Nel Darkshire Town Hall, il Cancelliere Daltry custodisce i registri del villaggio e ne esplora il passato. Si occupa di registri contabili e libri anagrafici, anche se gli archivi non sono più aggiornati e vengono spesso trascurati.",h="Nel Darkshire Town Hall, il Cancelliere Daltry custodisce i registri del villaggio e ne esplora il passato.",kw={"carevin","cancelliere daltry","borgoscuro","boscovespro","registri contabili","mistmantle","registri","stalvan","municipio"},ang={["faction:Alliance"]="Come investigatore dell'Alleanza, puoi rivolgerti al Cancelliere Daltry per documenti perduti da tempo e vecchi casi, tra i sinistri misteri di Boscovespro.",["race:Human"]="Come umano, puoi contare su Daltry per preservare ciò che resta della storia di Grand Hamlet prima che l'oscurità calasse sui boschi."},sec={{t="Archivista Cittadino",b="Il Cancelliere Daltry custodisce i registri di Borgoscuro mentre bestie, orrori non morti e tenebre soprannaturali incombono sulla città. Lavora nel Darkshire Town Hall con Ser Ello Serranero e il consiglio locale. I suoi registri conservano la storia della città, gli elenchi delle proprietà e i dati del censimento. Dopo che la catastrofe ha sconvolto la regione, questi documenti restano tra i pochi legami con i giorni prima che Grand Hamlet cadesse nell'ombra."},{t="La Traccia Cartacea",b="Da quando Borgoscuro è rimasta isolata dalla regolare amministrazione di Roccavento, i registri del Cancelliere Daltry ne hanno risentito. I documenti scompaiono, i registri non vengono aggiornati e le carte comunali vengono spesso smarrite o danneggiate. Chi indaga su vecchi casi o cerca gli abitanti si rivolge a lui per chiedere aiuto. Le risposte potrebbero trovarsi in appunti trascurati o in carte perdute nei boschi."},{t="Leggenda di Stalvan",b="Il Cancelliere Daltry consulta gli archivi di Borgoscuro quando gli investigatori seguono la leggenda familiare di Stalvan Mistmantle. Le annotazioni nei suoi registri sull'ex maestro di scuola sono frammentarie, così manda chi indaga in giro per la città e nelle fattorie dimenticate del regno. Spetta a loro ricomporre la tragica e sanguinosa verità."}},faq={{q="Dove si trova il Cancelliere Daltry?",a="Il Cancelliere Daltry lavora nel Darkshire Town Hall, nel villaggio centrale di Borgoscuro, a Boscovespro. Custodisce i registri comunali tra i funzionari cittadini e i membri del consiglio.",al={"posizione cancelliere daltry","dove si trova daltry","posizione cancelliere borgoscuro"}},{q="Qual è il lavoro del Cancelliere Daltry a Borgoscuro?",a="Il Cancelliere Daltry custodisce i documenti, gli elenchi cittadini e i registri legali di Borgoscuro. Aiuta chi cerca documenti sugli antichi abitanti, sulle rivendicazioni fondiarie o sulla storia della città.",al={"cosa fa daltry","ruolo daltry","chi e il cancelliere daltry"}},{q="Perché i suoi registri sono incompleti?",a="I registri del Cancelliere Daltry sono incompleti perché Boscovespro ha subito anni di isolamento, corruzione magica e violenti tumulti. Con i nemici della Night Watch che minacciano la sopravvivenza, l'aggiornamento dei registri è stato spesso trascurato.",al={"perche i registri di daltry non sono aggiornati","registri obsoleti boscovespro","registri mancanti daltry"}},{q="A quali serie di missioni partecipa o dà inizio il Cancelliere Daltry?",a="Il Cancelliere Daltry aiuta gli investigatori a seguire la storia di Stalvan Mistmantle e a ricostruirne il passato. Collabora anche a indagini come «The Carevin Family» e «The Shadowy Search Continues».",al={"missioni daltry","quali missioni da daltry","serie di missioni cancelliere daltry"}},{q="Chi invia gli investigatori dal Cancelliere Daltry?",a="Dama Eva manda chi segue il mistero di Stalvan dal Cancelliere Daltry, al Municipio. Anche i viaggiatori in cerca di Velinde Starsong sono stati indirizzati a lui. Quando i suoi registri non offrono più risposte, Daltry manda chi indaga altrove, per esempio alla locanda per chiedere di uno sconosciuto.",al={"chi manda persone da daltry","contatti daltry"}},{q="I giocatori dell'Orda possono parlare con il Cancelliere Daltry?",a="No. Il Cancelliere Daltry serve l'Alleanza e la Night Watch protegge Borgoscuro e il suo municipio dagli avventurieri dell'Orda.",al={"daltry è amichevole con l'orda","l'orda può parlare con daltry"}}},fx={["7e4b683b"]={q="Dalla parte di chi sta il Cancelliere Daltry?",a="Daltry è fermamente dalla parte dell'Alleanza e della comunità di Borgoscuro. In qualità di funzionario del Municipio, serve l'autorità civile locale e aiuta viaggiatori e investigatori che cercano di fare luce sui problemi della città o di trovare persone scomparse.",al={"daltry è dell'alleanza","fazione di daltry","lealtà del cancelliere daltry"}},["3b37b748"]={q="Che cosa vuole il Cancelliere Daltry?",a="Il Cancelliere Daltry vuole mantenere in ordine gli archivi e aiutare gli investigatori che indagano sugli oscuri misteri che avvolgono Boscovespro. Spesso aiuta i viaggiatori a consultare i registri cittadini, gli alberi genealogici e i vecchi documenti per rintracciare cittadini scomparsi come Stalvan Mistmantle, anche se i suoi archivi sono tutt'altro che completi.",al={"cosa vuole daltry","obiettivo del cancelliere daltry","motivo di daltry"}},["7e737b61"]={q="Perché il Cancelliere Daltry si trova qui?",a="Daltry è rimasto a Borgoscuro per svolgere i suoi doveri municipali all'interno del Municipio. Nonostante le foreste si facciano sempre più cupe e i pericoli minaccino di continuo l'insediamento, la comunità ha ancora bisogno di un funzionario che conservi atti, lettere e i nomi di chi vive nella regione.",al={"perché daltry è a borgoscuro","perché il cancelliere daltry è qui","motivo di daltry al municipio"}},["063859f4"]={q="Chi è il Cancelliere Daltry?",a="Il Cancelliere Daltry è un burocrate umano di stanza nel Darkshire Town Hall a Boscovespro. Ha il compito di conservare gli archivi civici, i dati del censimento e le genealogie degli abitanti della città, fungendo da archivista residente per un insediamento isolato, infestato dalle ombre e da un passato dimenticato.",al={"chi è daltry","chi è il cancelliere daltry","cancelliere daltry a borgoscuro"}}},fp="12,205,18.396.0,15.344.0,21.310.1,30.168.0,40.171.0,31.237.0,58.205.0,40.255.0,42.119.0"}
P.entries["npc:cliffwatcher-longhorn"] = {n="Cliffwatcher Longhorn",s="Al Presidio di Ventolibero, Cliffwatcher Longhorn veglia sulla roccaforte isolata dell'Orda a Millepicchi. Ne dirige la difesa contro i centauri Galak e tiene d'occhio le attività della tribù Totem Truce.",h="Al Presidio di Ventolibero, Cliffwatcher Longhorn veglia sulla roccaforte isolata dell'Orda a Millepicchi.",kw={"arnak grimtotem","guerriero corno lunare","cliffwatcher longhorn","presidio di ventolibero","galak","totem truce","nataka corno lungo","millepicchi"},ang={["faction:Horde"]="Come membro dell'Orda, fai affidamento sul Presidio di Ventolibero per contribuire a proteggere le linee di rifornimento attraverso il Kalimdor meridionale. Longhorn si adopera per mantenere la precaria posizione dell'Orda nel cuore del territorio dei centauri ostili.",["race:Tauren"]="Come tauren, puoi riconoscere in Longhorn lo spirito di frontiera degli Shu'halo. Veglia sulle mese sacre contese, mentre affronta aspre tensioni irrisolte con la tribù Totem Truce."},sec={{t="Guardiano dei Pinnacoli",b="Cliffwatcher Longhorn protegge il Presidio di Ventolibero, un insediamento isolato in cima alle guglie rocciose di Millepicchi. Sovrintende alla sicurezza quotidiana e raccoglie i rapporti degli esploratori sul fondo del canyon e sui crinali vicini. Forze ostili si radunano attorno al presidio, e la sua guida salda ne coordina le difese."},{t="L'Ostilità dei Centauri e gli Intrighi dei Totem Truce",b="I centauri Galak mettono alla prova il perimetro del Presidio di Ventolibero dal canyon sottostante. Cliffwatcher Longhorn invia avventurieri per respingerli e ridurne il numero.\n\nLa sua preoccupazione per i tauren Totem Truce è ancora più profonda. Il loro accampamento segreto si trova vicino al presidio, e Longhorn diffida di loro. Organizza ricognizioni per impadronirsi dei loro appunti nascosti, che rivelano tradimenti all'interno della tribù e i crimini violenti di Arnak Grimtotem."}},faq={{q="Chi è Cliffwatcher Longhorn?",a="Cliffwatcher Longhorn comanda il Presidio di Ventolibero, l'avamposto dell'Orda a Millepicchi. Organizza le ricognizioni, le pattuglie difensive e gli interventi contro le minacce nelle vicinanze.",al={"informazioni su cliffwatcher longhorn","chi è longhorn","capo del presidio di ventolibero"}},{q="Dove posso trovare Cliffwatcher Longhorn?",a="Cliffwatcher Longhorn si trova in cima alla mesa principale del Presidio di Ventolibero, a Millepicchi. Prendi l'ascensore dal fondo del canyon, poi attraversa i ponti di legno.",al={"posizione di cliffwatcher longhorn","dove si trova longhorn"}},{q="Perché Longhorn è preoccupato per i centauri?",a="Esploratori come il Guerriero Corno Lunare riferiscono un netto aumento dell'ostilità dei centauri Galak. Longhorn ordina attacchi per pacificare il clan e impedirgli di travolgere le difese lungo gli accessi al Presidio di Ventolibero.",al={"perché uccidere i centauri","storia di pacify the centaur","minaccia centauri millepicchi"}},{q="Qual è il suo interesse per la tribù Totem Truce?",a="I Totem Truce vivono tra le file dell'Orda, ma agiscono in segreto e con malizia. Longhorn sospetta qualcosa di losco, così incarica gli avventurieri di sottrarre i loro appunti nascosti e scoprire cosa stiano tramando.",al={"longhorn totem truce","motivo di grimtotem spying"}},{q="Chi è Arnak Grimtotem e perché Longhorn lo cerca?",a="Arnak Grimtotem ha compiuto un violento attacco contro gli abitanti del Presidio di Ventolibero. Longhorn mette una taglia su di lui affinché Arnak risponda del suo tradimento davanti alla giustizia.",al={"ricercato arnak grimtotem","storia taglia arnak"}},{q="Cliffwatcher Longhorn ha una famiglia?",a="Sì. Il fratello di Cliffwatcher Longhorn, Nataka Corno Lungo, è di stanza molto più a ovest, al Presidio delle Ombre in Desolanda. Il dovere lascia a Cliffwatcher poco tempo per scrivergli.",al={"fratello di longhorn","nataka corno lungo fratello"}}},fx={["8c33620b"]={q="Dalla parte di chi sta Cliffwatcher Longhorn?",a="Cliffwatcher Longhorn è fermamente dalla parte dell'Orda e delle tribù tauren che rispondono a To Thunder Bluff. Di stanza al Presidio di Ventolibero, coordina la difesa dell'insediamento e si affida ai campioni dell'Orda per proteggere le strade del canyon sottostante dalle aggressive tribù di centauri e dalla sovversiva tribù dei Totem Truce.",al={"fazione di cliffwatcher longhorn","longhorn è dell'orda o dell'alleanza","chi serve longhorn"}},d26a5d43={q="Che cosa vuole Cliffwatcher Longhorn?",a="Longhorn vuole mantenere la sicurezza e l'ordine in tutti i Millepicchi. Vuole vendicarsi delle ostili bande di centauri Galak che molestano i viaggiatori, scoprire quali complotti stia tramando la tribù locale dei Totem Truce e assicurare rapidamente alla giustizia minacce ribelli come Arnak Grimtotem.",al={"cosa vuole longhorn","obiettivo di longhorn","motivazioni di cliffwatcher longhorn"}},e12f4ee3={q="Perché Cliffwatcher Longhorn si trova qui?",a="Longhorn è di stanza al Presidio di Ventolibero, dove è uno dei principali sorveglianti e difensori. Da questa mesa svettante controlla le segnalazioni provenienti dal fondo del canyon, dirige gli esploratori dell'Orda e organizza la risposta alle pericolose tribù di centauri e ai subdoli Totem Truce che circondano l'avamposto.",al={"perché longhorn è al presidio di ventolibero","perché cliffwatcher longhorn è a millepicchi","ruolo di longhorn al presidio di ventolibero"}}},fp="21,200,21.302.0,40.414.1,29.155.0,39.148.0,44.185.0,44.190.0,54.150.0,43.171.0"}
P.entries["npc:coleman-farthing"] = {n="Coleman Farthing",s="Alla Taverna dell'Impiccato di Brill, Coleman Farthing nutre ancora un odio nato ai Mulini degli Agamand. Serviva la ricca dinastia degli Agamand a Tirisfal settentrionale. Lui e gli altri braccianti morirono difendendo la tenuta dei loro padroni dal Flagello. Ora che è un Reietto, Coleman cerca vendetta contro i suoi antichi padroni.",h="Alla Taverna dell'Impiccato di Brill, Coleman Farthing nutre ancora un odio nato ai Mulini degli Agamand.",kw={"agamand heirlooms","mulini degli agamand","brill","coleman farthing","deaths in the family","taverna dell'impiccato","lordaeron","radure di tirisfal"},ang={["class:Warrior"]="Coleman indirizza gli aspiranti guerrieri verso la Cripta degli Agamand per depredare le armi avite di una casata aristocratica decaduta e armarsi per le guerre future.",["race:Undead"]="Per i Reietti, Coleman incarna il risentimento che molti popolani nutrono verso l'antica nobiltà di Lordaeron. L'arroganza e l'orgoglio dei nobili spesso affrettarono la morte dei loro sudditi durante la piaga."},sec={{t="Un servitore amareggiato",b="Prima della Terza Guerra, Coleman Farthing lavorava ai Mulini degli Agamand, la più grande attività molitoria e agricola delle Radure di Tirisfal. Quando il Flagello dilagò per Lordaeron, l'aristocratica famiglia Agamand si rifiutò di abbandonare le proprie preziose terre. Esortò la servitù e i braccianti a prendere le armi, promettendo di difendere i poderi dall'orda di non morti. Coleman e i suoi compagni di lavoro si fidarono dei loro padroni e rimasero. Morirono tutti, fino all'ultimo."},{t="Vendetta dalla tomba",b="Risorto nella non morte, Coleman Farthing si liberò dal controllo del Flagello e si unì ai Reietti, ma il suo odio per gli Agamand rimase. Incolpa l'avidità e l'orgoglio dei suoi antichi padroni di aver attirato i loro servitori in un'impossibile ultima resistenza, quanto incolpa il Flagello. Da una taverna di Brill, manda i campioni dell'Orda ai mulini contaminati per uccidere gli Agamand risorti e depredare la cripta di famiglia delle armi avite. Intende privarli anche dell'ultimo briciolo di onore."}},faq={{q="Dove si trova Coleman Farthing?",a="Coleman Farthing trascorre le sue giornate nella Taverna dell'Impiccato di Brill, nella parte centrale delle Radure di Tirisfal.",al={"posizione di coleman farthing","dove si trova coleman farthing","coleman farthing brill"}},{q="Perché Coleman odia così tanto la famiglia Agamand?",a="Quando il Flagello invase Lordaeron, i patriarchi degli Agamand persuasero i loro lavoratori, tra cui Coleman, a restare e difendere i mulini anziché fuggire. Tutti i lavoratori furono massacrati. Coleman considera il loro appello alle armi un'arrogante manipolazione che lo condusse alla morte.",al={"perché coleman odia gli agamand","motivazione di coleman farthing","rancore dei mulini degli agamand"}},{q="Cosa è successo ai Mulini degli Agamand?",a="Il Flagello travolse la vasta tenuta. I suoi mulini a vento giacciono in rovina, infestati. I membri della famiglia Agamand e i loro lavoratori uccisi vagano per i campi contaminati come non morti privi di senno e ostili, sotto il dominio del Lich King.",al={"cosa è successo ai mulini degli agamand","storia dei mulini degli agamand","chi possiede i mulini degli agamand"}},{q="Quali compiti affida Coleman agli avventurieri?",a="Coleman manda gli avventurieri a nord, ai Mulini degli Agamand, per sfoltire i non morti erranti, uccidere i membri risorti della stirpe e recuperarne i resti da profanare. Li manda anche a depredare la Cripta degli Agamand delle armi degli antenati.",al={"missioni di coleman farthing","missioni agamand brill"}},{q="Perché Coleman vuole le armi di famiglia degli Agamand?",a="Coleman vede nelle armi ancestrali degli Agamand i simboli del vano orgoglio che condusse alla morte i suoi compagni di lavoro. Manda guerrieri a depredarne la cripta di famiglia, privando la dinastia del suo onore e impiegando concretamente le armi contro i loro nemici.",al={"storia della missione agamand heirlooms","perché rubare le armi degli agamand"}},{q="Coleman Farthing è imparentato con il Vescovo Farthing?",a="Coleman Farthing e il Vescovo Farthing condividono il cognome e le radici nel caduto Kingdom of Lordaeron, ma nessuna testimonianza confermata ne attesta i legami familiari.",al={"parentela con il vescovo farthing","famiglia di coleman farthing"}}},fx={["54a8df22"]={q="Chi è Coleman Farthing?",a="Coleman Farthing è un Reietto che vive nella Taverna dell'Impiccato di Brill. Quando era in vita, lavorava come bracciante per la ricca famiglia Agamand nei suoi mulini nella parte occidentale delle Radure di Tirisfal. Quando il Flagello invase Lordaeron, i suoi padroni convinsero lui e gli altri lavoratori a combattere invece di fuggire. I mulini furono travolti e tutti i presenti vennero massacrati. Ora, rianimato con la volontà libera sotto l'egida della Signora Oscura, Coleman è divorato dal rancore verso la famiglia che lo condusse a una morte orribile.",al={"chi è coleman farthing","storia di coleman farthing","chi è coleman"}},["3d5d2be6"]={q="Dalla parte di chi sta Coleman Farthing?",a="Coleman Farthing è fermamente dalla parte dei Reietti e dell'Orda. Vive tra i suoi fratelli non morti a Brill, al sicuro dal Flagello privo di senno che infesta le rovine della sua vita passata. Sostiene la lotta dei Reietti per assicurarsi le Radure di Tirisfal, ma il suo interesse è soprattutto personale: indirizza gli avventurieri di passaggio affinché regolino i suoi vecchi conti con i padroni che lo condannarono.",al={"fazione di coleman farthing","coleman è dell'orda","chi serve coleman"}},ac8a2a0f={q="Che cosa vuole Coleman Farthing?",a="Coleman vuole vendicarsi senza pietà della famiglia Agamand. Vuole vedere distrutti i resti rianimati dei suoi ex padroni, Gregor, Nissa, Thurman e Devlin, e poterli calpestare. Oltre a volerli morti, vuole che la loro cripta ancestrale venga saccheggiata delle preziose armi di famiglia, privando l'orgogliosa dinastia della sua dignità, del suo lignaggio e della sua ultima dimora.",al={"cosa vuole coleman","obiettivo di coleman farthing","obiettivi di coleman"}},["3e94941c"]={q="Perché Coleman Farthing si trova a Brill?",a="Coleman si trattiene alla Taverna dell'Impiccato di Brill perché è il principale punto di ritrovo per i non morti appena risorti e i viaggiatori dell'Orda diretti a nord. Non avendo la forza marziale per assaltare da solo i Mulini degli Agamand invasi, aspetta tra i viaggiatori e recluta guerrieri e incantatori capaci che marcino verso nord-ovest e compiano la sua vendetta.",al={"perché coleman è a brill","perché coleman è alla taverna dell'impiccato","coleman farthing a brill"}}},fp="16,301,16.449.0,24.446.0,36.97.0,49.275.0,35.218.0,44.244.0,51.265.0,47.153.0"}
P.entries["npc:collin-mauren"] = {n="Collin Mauren",s="Nel Quartiere dei Maghi di Roccavento, Collin Mauren studia la magia pratica e crea incantesimi utili con reagenti naturali. Prepara anche pergamene arcane per Gaxim Scoppiarame, suo amico gnomo e compagno di esplorazioni.",h="Nel Quartiere dei Maghi di Roccavento, Collin Mauren studia la magia pratica e crea incantesimi utili con...",kw={"basilisco","collin mauren","dust devil","gaxim scoppiarame","quartiere dei maghi","petrartiglio","roccavento","marche occidentali"},ang={["class:Mage"]="Come mago, puoi osservare l'approccio sperimentale di Collin alla creazione degli incantesimi. Usa reagenti come detriti elementali e scaglie di basilisco per intessere magie utili.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come Collin fornisca agli avventurieri magie utili per comunicare e commerciare in tutta la fazione, dalle Marche Occidentali a Kalimdor.",["race:Human"]="Come umano, condividi una città con Collin. I suoi tranquilli studi nel Quartiere dei Maghi di Roccavento rispecchiano gli interessi eruditi dei maghi umani."},sec={{t="Studioso dell'Arcano",b="Nel Quartiere dei Maghi di Roccavento, Collin Mauren studia come la magia possa risolvere problemi pratici. Elabora formule arcane con anomalie naturali e componenti grezzi raccolti in tutta Azeroth. Le loro proprietà lo aiutano a creare pergamene e reagenti utili per amici e viaggiatori."},{t="Aiutare Gaxim Scoppiarame",b="Collin Mauren aiuta il suo amico Gaxim Scoppiarame a far esplodere a distanza gli esplosivi NG-5. Gaxim, uno gnomo inventore, aveva bisogno di un innesco a distanza, così Collin ha ideato un incantesimo di comunicazione per una pergamena. Per imprimervi l'incantesimo, Collin usa i detriti degli imprevedibili Dust Devils delle Marche Occidentali. Ora attende notizie sull'esito del piano di Gaxim."},{t="Studi esotici a Petrartiglio",b="Gli studi di Collin Mauren si estendono da Roccavento, oltre il Grande Mare, fino alle Vette di Petrartiglio di Kalimdor. Cerca scaglie dei basilischi della regione, le cui pelli resistenti lo interessano come materiali per nuovi incantesimi. I viaggiatori diretti a Kalimdor ricevono spesso le sue richieste di queste pelli rare. Le scaglie lo aiutano a studiare come l'anatomia delle creature primordiali possa stabilizzare incantamenti complessi."}},faq={{q="Dove si trova Collin Mauren?",a="Collin Mauren si trova nel Quartiere dei Maghi di Roccavento, tra le torri e le botteghe frequentate dagli studiosi di magia arcana della capitale.",al={"posizione di collin mauren","dove si trova collin mauren","collin mauren roccavento"}},{q="In quale tipo di magia è specializzato Collin?",a="Collin è specializzato in incantamenti applicati e incantesimi di utilità. Sperimenta con componenti naturali come detriti elementali e scaglie di bestie per creare pergamene, tra cui un incantesimo di comunicazione per gli esplosivi a distanza di Gaxim. Crea anche altri incantamenti unici.",al={"ricerche di collin mauren","cosa fa collin mauren","magia di collin mauren"}},{q="Chi è Gaxim Scoppiarame e come è legato a Collin?",a="Gaxim Scoppiarame è uno gnomo inventore avventuroso e amico di Collin. Quando Gaxim ha avuto bisogno di far detonare i suoi esplosivi a distanza, Collin gli ha preparato una pergamena con un incantesimo di comunicazione.",al={"amico di gaxim scoppiarame","collin e gaxim","chi è gaxim scoppiarame"}},{q="Perché Collin ha bisogno dei detriti elementali delle Marche Occidentali?",a="A Collin servono i detriti di uno dei Dust Devils delle Marche Occidentali per imprimere un incantesimo di comunicazione su una pergamena. A Gaxim Scoppiarame serve quell'incantesimo per far esplodere a distanza i suoi esplosivi NG-5.",al={"missione devils in westfall","perché dust devil","missione dust devil delle marche occidentali"}},{q="Perché Collin è interessato alle Vette di Petrartiglio?",a="Collin studia le proprietà magiche delle scaglie dei basilischi delle Vette di Petrartiglio, a Kalimdor. Usa le loro pelli robuste e naturalmente resistenti come base per nuovi incantesimi.",al={"basilischi di petrartiglio","retrieval for mauren","scaglie di petrartiglio collin"}},{q="Collin è alleato del Kirin Tor?",a="Collin vive nel Quartiere dei Maghi e segue tradizioni diffuse tra i maghi dell'Alleanza. Lavora soprattutto come ricercatore indipendente e creatore di reagenti, più che come rappresentante attivo di Dalaran.",al={"collin fa parte del kirin tor","collin mauren dalaran","quartiere dei maghi collin"}}},fx={f243f9d9={q="Chi è Collin Mauren?",a="Collin Mauren è un mago umano che vive nel Quartiere dei Maghi di Roccavento. Ricercatore erudito e creatore di incantesimi, sperimenta formule arcane e pergamene incantate, usando componenti rare provenienti da terre lontane per creare pergamene magiche destinate ai suoi colleghi e agli avventurieri di passaggio.",al={"chi è collin","storia di collin mauren","chi è mauren"}},b186ecef={q="Perché Collin Mauren si trova a Roccavento?",a="Collin vive nel Quartiere dei Maghi di Roccavento, circondato dalle biblioteche, dalle accademie e dagli altri praticanti delle arti arcane della città. Da questo vivace rifugio può condurre i suoi esperimenti in pace e procurarsi reagenti esotici portati dagli avventurieri di passaggio nella capitale.",al={"perché collin è qui","perché collin mauren è a roccavento","cosa fa collin a roccavento"}},["8e195ded"]={q="Che cosa vuole Collin Mauren?",a="Collin cerca reagenti mistici rari per perfezionare la sua arte magica. Che si tratti di procurarsi detriti elementali dai diavoletti di polvere delle Marche Occidentali per creare pergamene speciali per inviare messaggi al suo amico Gaxim Scoppiarame, o di trovare scaglie di basilisco nelle Vette di Petrartiglio, è guidato dalla curiosità arcana e dalle richieste di viaggiatori curiosi.",al={"motivazione di collin mauren","cosa vuole collin","cosa cerca collin"}}},fp="13,203,21.269.0,23.321.0,28.375.0,33.126.0,45.257.0,59.178.0,52.180.0,53.181.0,37.204.0"}
P.entries["npc:colonel-kurzen"] = {n="Colonnello Kurzen",s="Nella Valle di Rovotorto settentrionale, gli ex soldati del Colonnello Kurzen cercano di porre fine al suo dominio. Un tempo godeva della fiducia di Roccavento, ma ora comanda una milizia ribelle da un insediamento fortificato.",h="Nella Valle di Rovotorto settentrionale, gli ex soldati del Colonnello Kurzen cercano di porre fine al suo...",kw={"colonnello kurzen","conrad kurzen","doren","kurzen","insediamento di kurzen","campo dei ribelli","scorte","valle di rovotorto"},ang={["class:Warrior"]="Come guerriero, puoi vedere come la forza militare disciplinata possa essere distorta quando si perdono volontà e onore.",["faction:Alliance"]="Per l'Alleanza, la caduta di Kurzen è un grave scandalo militare e una tragica perdita di truppe di Roccavento. Il comando dell'Alleanza e i lealisti locali hanno autorizzato la sua uccisione.",["race:Human"]="Come umano di Roccavento, puoi ricordare Kurzen come un comandante rispettato. La sua caduta nella tirannia mostra i pericoli della giungla."},sec={{t="Una caduta in disgrazia",b="Il Colonnello Conrad Kurzen un tempo serviva Roccavento come ufficiale capace e onorevole. I capi del regno gli affidarono un'unità di spedizione inviata a sud, nella Valle di Rovotorto. Nel cuore della giungla, il suo comportamento divenne instabile e megalomane. Rivendicò quelle terre selvagge come proprie e rinnegò la sua fedeltà a Roccavento."},{t="La ribellione",b="Il cambiamento di Kurzen divise i suoi soldati. Alcuni lo seguirono con cieca lealtà o fanatismo, mentre altri inorridirono di fronte alla sua follia e brutalità. Quando Emerine Junis respinse le sue avances, la gettò nella prigione dell'insediamento. Il Tenente Doren guidò i soldati che si separarono da lui e fondarono il Campo dei Ribelli lungo la strada settentrionale. Ora combattono le forze scatenate di Kurzen per fermarle."},{t="L'orco dietro le quinte",b="Mai'Zoth, un mago ogre del clan Mosh'ogg, usò la stregoneria oscura per impossessarsi della mente del Colonnello Kurzen. Non furono la febbre della giungla e lo sfinimento a causare la follia di Kurzen. Mai'Zoth trasformò un disciplinato distaccamento di Roccavento in pedine violente. Attraverso il colonnello, l'ogre cercava di ottenere il controllo della regione senza una guerra aperta."}},faq={{q="Perché il Colonnello Kurzen si è ribellato a Roccavento?",a="Durante la spedizione nella Valle di Rovotorto, Kurzen divenne instabile e megalomane, poi rinnegò la sua fedeltà a Roccavento. I suoi ex soldati al Campo dei Ribelli cercano ancora la causa della sua follia.",al={"perché kurzen è malvagio","cosa è successo a kurzen","storia di kurzen"}},{q="Dove si trova il Colonnello Kurzen?",a="Il Colonnello Kurzen comanda la sua milizia dall'Insediamento di Kurzen, sulle colline della Valle di Rovotorto settentrionale. Vive nell'edificio fortificato Stockpile, sul retro dell'accampamento.",al={"dove trovare kurzen","posizione di kurzen","insediamento del colonnello kurzen"}},{q="Chi sono i ribelli al Campo dei Ribelli?",a="I ribelli sono ex soldati al comando di Kurzen che si rifiutarono di seguirlo nella sua follia. Il Tenente Doren li guida dal Campo dei Ribelli, vicino al confine settentrionale. Combattono per porre fine all'esercito ribelle di Kurzen e restano fedeli a Roccavento.",al={"storia del campo dei ribelli","chi è il tenente doren","perché campo dei ribelli"}},{q="Chi è Emerine Junis?",a="Emerine Junis era assegnata alla spedizione e respinse le avances di Kurzen. Mentre la sua crudeltà e i suoi deliri crescevano, lui la rinchiuse nelle gabbie della prigione dell'insediamento.",al={"emerine junis","prigioniero di kurzen"}},{q="Kurzen agisce da solo nella giungla?",a="No. Kurzen comanda i mercenari, i soldati e i combattenti della giungla umani che gli rimasero fedeli dopo la partenza dei ribelli per il Campo dei Ribelli.",al={"per chi lavora kurzen","alleati di kurzen"}},{q="Cosa succede se il Colonnello Kurzen viene ucciso?",a="Il Tenente Doren chiede agli avventurieri dell'Alleanza di portargli la testa di Kurzen come prova della sua morte. Vuole che spezzino la catena di comando della milizia e ripristinino l'onore dell'Esercito di Roccavento.",al={"fine missione di kurzen","testa di kurzen doren"}}},fp="14,169,17.315.0,13.369.0,27.304.2,46.193.2,32.179.0,37.227.0,21.156.0,37.134.2,40.181.1"}
P.entries["npc:commander-mar-alith"] = {n="Comandante Mar'alith",s="Alla Fortezza Cenariana, il Comandante Mar'alith resiste ai pericoli di Silitus. Guida la lotta contro gli sciami di silitidi e i cultisti del Martello del Crepuscolo, mentre il dolore per la moglie scomparsa grava su di lui.",h="Alla Fortezza Cenariana, il Comandante Mar'alith resiste ai pericoli di Silitus.",kw={"circolo cenariano","fortezza cenariana","comandante mar'alith","alveare ashi","alveare regal","alveare zora","mar'alith","natalia mar'alith","silitus"},ang={["class:Warrior"]="Come guerriero, conosci i compiti di chi comanda sul campo di battaglia. Mar'alith dirige i combattimenti in armatura pesante e porta un imponente falcione tra i mistici e i custodi della natura dell'insediamento.",["race:NightElf"]="Come Elfo della Notte, condividi la dedizione delle sentinelle e dei guerrieri alla difesa di Kalimdor al fianco dei druidi, anche a caro prezzo personale."},sec={{t="Comandante della fortezza",b="Alla Fortezza Cenariana, il Comandante Mar'alith difende la roccaforte del Circolo Cenariano nel deserto. I druidi studiano le antiche anomalie ecologiche e cosmiche di Silitus, mentre lui dirige le operazioni di guerra. Le sue forze colpiscono gli alveari dei silitidi: l'Alveare Ashi, l'Alveare Zora e l'Alveare Regal. Impediscono che le incursioni travolgano il caposaldo centrale della spedizione."},{t="Dolore nel deserto",b="Il portamento austero del Comandante Mar'alith non riesce a nascondere il suo dolore. La sua amata moglie, Natalia Mar'alith, si è avventurata nelle Sabbie Mutevoli per un incarico del Circolo e non ha fatto ritorno. Resta fedele al proprio dovere verso la spedizione cenariana, pur desiderando ardentemente notizie su ciò che le è accaduto nelle distese desolate."},{t="Un tragico destino",b="Natalia Mar'alith ha ceduto alla follia tra i sussurri del deserto. Poi un cristallo qiraji le ha fatto il lavaggio del cervello, costringendola a servire C'Thun. La verità lascia il Comandante Mar'alith profondamente scosso. Anche con il cuore spezzato, dirige la difesa di Silitus contro gli orrori del sottosuolo."}},faq={{q="Chi è il Comandante Mar'alith?",a="Il Comandante Mar'alith comanda le forze militari del Circolo Cenariano alla Fortezza Cenariana. Organizza le ricognizioni, le difese e gli attacchi contro gli alveari dei silitidi in tutta Silitus.",al={"mar'alith","chi è il comandante mar'alith","comandante elfo della notte silitus"}},{q="Dove si trova il Comandante Mar'alith?",a="Il Comandante Mar'alith si trova all'interno della Fortezza Cenariana, il principale insediamento neutrale del Circolo Cenariano tra le sabbie di Silitus.",al={"posizione di mar'alith","dove si trova mar'alith"}},{q="Cosa è successo a sua moglie, Natalia?",a="Natalia Mar'alith è scomparsa nel deserto durante una spedizione e non ha più fatto ritorno. Seguire le sue tracce attraverso Silitus rivela cosa le è accaduto.",al={"dov'è natalia","cara natalia","destino di natalia mar'alith"}},{q="Perché Mar'alith sembra distratto?",a="Il dolore e l'ansia per la moglie scomparsa e per il suo destino gravano sul Comandante Mar'alith. Ciononostante, dirige la difesa della fortezza.",al={"perché mar'alith è distratto","mar'alith si comporta in modo strano"}},{q="Quali compiti affida il Comandante Mar'alith agli avventurieri?",a="Il Comandante Mar'alith invia campioni contro i silitidi nell'Alveare Ashi, nell'Alveare Zora e nell'Alveare Regal. Li manda anche contro il Martello del Crepuscolo e chiede loro di indagare sul destino di sua moglie.",al={"missioni di mar'alith","quali missioni assegna mar'alith"}},{q="Il Comandante Mar'alith è un druido?",a="No. Il Comandante Mar'alith è una sentinella in armatura e un comandante guerriero. Dirige la difesa militare e le tattiche della spedizione anziché ricorrere alla magia druidica.",al={"mar'alith è un druido","classe di mar'alith"}}},fp="19,209,21.347.0,19.289.0,13.259.1,27.171.0,39.126.0,35.148.1,38.127.0,58.188.0,31.162.0"}
P.entries["npc:commander-springvale"] = {n="Comandante Primavalle"}
P.entries["npc:cookie"] = {n="Capitan Dolcetto",s="Sotto la corazzata nelle Miniere della Morte, Capitan Dolcetto bada ai calderoni dell'equipaggio. Murloc della Fratellanza dei Defias, cucina agli ordini del Capitano Pelleverde e di Edwin VanCleef. Nel bacino di carenaggio sotterraneo, la sua postazione è l'unica che un visitatore può evitare.",h="Sotto la corazzata nelle Miniere della Morte, Capitan Dolcetto bada ai calderoni dell'equipaggio.",kw={"capitano pelleverde","cuoco","capitan dolcetto","miniere della morte","defias","edwin vancleef","baia della corazzata","corazzata","murloc"},ang={["class:Rogue"]="La rete di furfanti di VanCleef si affida a risorse strane e poco convenzionali. Capitan Dolcetto è una bizzarra sorpresa nella catena di rifornimento della Fratellanza.",["faction:Alliance"]="Gli esploratori di Roccavento potrebbero sorprendersi nel trovare murloc tra i ranghi dirigenti dei Defias, oltre che lungo le coste esterne delle Marche Occidentali.",["profession:Cooking"]="Un murloc come capocuoco a bordo di una corazzata di fuorilegge rivela gli standard disperati e poco raffinati della cucina pirata."},sec={{t="Lo chef della Fratellanza",b="Capitan Dolcetto cucina sotto i ponti della corazzata nella Baia della Corazzata. Nessun incursore umano o ingegnere goblin svolge questo compito; se ne occupa il murloc solitario. Nessuno sa come abbia ottenuto l'incarico. L'equipaggio può dubitare della cucina di un murloc, ma i pirati raramente scelgono i pasti con cura. Nei bassifondi di Rivoluna, un pasto è un pasto."},{t="Un infuso amaro",b="Capitan Dolcetto pattuglia i corsi d'acqua e le rive attorno all'ammiraglia pirata. Combatte con utensili da cucina e scaglia intrugli acidi. Pur vivendo lontano dalle tipiche tribù di murloc, difende il suo calderone con forza selvaggia, scagliando miscugli caustici contro gli intrusi sui moli. La sua postazione si trova lontano dalle passerelle principali, così molti di coloro che assaltano la baia passano oltre la sua cucina. Capitan Dolcetto è l'unico sorvegliante a bordo della corazzata dei Defias che si può evitare."}},faq={{q="Perché un murloc lavora come cuoco per i Defias?",a="Nessun documento spiega come Capitan Dolcetto sia giunto a prestare servizio a bordo della corazzata. I fuorilegge dei Defias e i carpentieri navali goblin accettano la situazione perché gli equipaggi pirata prendono il cibo dove lo trovano, qualunque sia la specie del cuoco.",al={"perché murloc cuoco","perché capitan dolcetto è sulla nave","storia capitan dolcetto defias"}},{q="Dove si trova Capitan Dolcetto nelle Miniere della Morte?",a="Capitan Dolcetto si trova nella Baia della Corazzata, proprio alla fine delle Miniere della Morte. Pattuglia le acque poco profonde e i moli vicino alla poppa della gigantesca corazzata di legno, appena oltre la rampa sorvegliata da Ser Torello.",al={"dove si trova capitan dolcetto","posizione capitan dolcetto miniere della morte","trovare capitan dolcetto"}},{q="È necessario affrontare Capitan Dolcetto per completare le Miniere della Morte?",a="No, Capitan Dolcetto è l'unico boss opzionale delle Miniere della Morte. I visitatori possono salire a bordo della nave e affrontare il Capitano Pelleverde ed Edwin VanCleef senza disturbare il cuoco che pattuglia la riva.",al={"capitan dolcetto è opzionale","bisogna uccidere capitan dolcetto","saltare capitan dolcetto"}},{q="Capitan Dolcetto appartiene a una tribù specifica di murloc?",a="Capitan Dolcetto non è legato ad alcuna tribù locale conosciuta di murloc, comprese quelle lungo la costa delle Marche Occidentali. Vive e lavora tra i fuorilegge e le canaglie della Fratellanza dei Defias.",al={"a quale tribù appartiene capitan dolcetto","tribù murloc capitan dolcetto"}},{q="Quali armi o attacchi usa Capitan Dolcetto?",a="Capitan Dolcetto combatte a distanza ravvicinata con utensili da cucina e scaglia spruzzi caustici di acido contro gli aggressori, ustionandoli con pericolosi miscugli culinari.",al={"abilità capitan dolcetto","come combatte capitan dolcetto","attacchi capitan dolcetto"}},{q="A chi risponde Capitan Dolcetto sulla corazzata?",a="Capitan Dolcetto presta servizio nella flotta della Fratellanza dei Defias sotto il comando del Capitano Pelleverde e, in ultima istanza, risponde a Edwin VanCleef.",al={"capitan dolcetto boss","chi comanda capitan dolcetto","capitan dolcetto pelleverde vancleef"}}},fx={f44f954f={q="Chi è Capitan Dolcetto?",a="Capitan Dolcetto è un murloc d'élite che fa da cuoco a bordo del colossale vascello corazzato di Edwin VanCleef, nelle profondità delle Miniere della Morte. A differenza della maggior parte dei murloc ferali che si incontrano lungo le coste delle Marche Occidentali, Dolcetto ha trovato un'insolita dimora tra i fuorilegge umani e prepara nel suo calderone pietanze discutibili per l'equipaggio di pirati della Fratellanza dei Defias.",al={"chi è capitan dolcetto","identità di capitan dolcetto","chi è il cuoco murloc"}},c6e0c482={q="Dalla parte di chi sta Capitan Dolcetto?",a="Capitan Dolcetto è leale alla Fratellanza dei Defias. Di stanza sul colossale vascello insieme al Capitano Pelleverde e a Edwin VanCleef, serve direttamente i pirati fuorilegge e difenderà con ferocia la nave da ogni intruso dell'Alleanza che tenti di ostacolare la ribellione di VanCleef.",al={"lealtà di capitan dolcetto","capitan dolcetto è un defias","di quale fazione è capitan dolcetto"}}},fp="6,241,22.321.0,13.434.0,49.210.0,43.188.0,43.188.0,46.180.0,40.148.0,44.130.0"}
P.entries["npc:corithras-moonrage"] = {n="Corithras Lunafuria"}
P.entries["npc:councilman-millstipe"] = {n="Membro del Concilio Mills",s="A Borgoscuro, il Membro del Concilio Mills vuole giustizia per la gente di Boscovespro. Vive nel Municipio mentre nel concilio cresce il risentimento verso il dominio di Roccavento.",h="A Borgoscuro, il Membro del Concilio Mills vuole giustizia per la gente di Boscovespro.",kw={"membro del concilio mills","borgoscuro","dextren ward","boscovespro","house of nobles","mills","morbent fel","segrete di roccavento"},ang={["class:Rogue"]="A un ladro disposto a entrare nelle Segrete di Roccavento, strettamente sorvegliate, e a compiere un'esecuzione politica non autorizzata, Mills offre un incarico contro la House of Nobles.",["faction:Alliance"]="Mills mostra la frattura tra la nobiltà di Roccavento, al riparo dai pericoli, e i disperati insediamenti di frontiera di Boscovespro. Questi insediamenti ricevono pochi aiuti e subiscono pesanti ingerenze da parte della capitale."},sec={{t="Giustizia negata da Roccavento",b="Non morti e bestie feroci minacciano Borgoscuro, mentre il suo concilio lotta con la burocrazia di Roccavento. Il Membro del Concilio Mills condivide il crescente risentimento della città verso la corona. Il profanatore di tombe Dextren Ward è stato sorpreso a vendere cadaveri appena riesumati al negromante Morbent Fel. I capi di Borgoscuro hanno condannato Ward a morte, ma la House of Nobles di Roccavento ha commutato la pena e lo ha rinchiuso nelle Segrete di Roccavento."},{t="Un messaggio ai nobili",b="Il Membro del Concilio Mills ritiene che i politici di Roccavento abbiano accantonato la sicurezza e la giustizia di Boscovespro. In segreto, incarica degli avventurieri di uccidere Dextren Ward nella sua cella nelle Segrete di Roccavento. L'ordine sfida la House of Nobles. Se Roccavento non proteggerà la gente di Boscovespro, Mills ritiene che debba farsi giustizia da sola."}},faq={{q="Dove si può trovare il Membro del Concilio Mills?",a="Il Membro del Concilio Mills si trova all'interno del Municipio di Borgoscuro, nella parte orientale di Boscovespro.",al={"posizione di mills","dove si trova mills","trova il membro del concilio mills"}},{q="Perché Mills vuole la morte di Dextren Ward?",a="Dextren Ward riesumava i morti di Boscovespro e li vendeva al negromante Morbent Fel. Lord Ebonlocke lo ha condannato alla decapitazione, ma la House of Nobles di Roccavento lo ha risparmiato e mandato nelle Segrete di Roccavento.",al={"perché uccidere dextren ward","mills dextren ward","crimine di ward"}},{q="Qual è il motivo di risentimento di Mills verso Roccavento?",a="Mills ritiene che Roccavento abbia abbandonato Boscovespro, pur interferendo con la giustizia locale. La House of Nobles ha annullato la condanna a morte emessa da Borgoscuro per Dextren Ward, lasciando l'insediamento con la sensazione di essere ignorato e indifeso di fronte al trono.",al={"perché arrabbiato con roccavento","house of nobles borgoscuro","politica di mills"}},{q="Mills ha parenti conosciuti?",a="Non si conoscono familiari del Membro del Concilio Mills.",al={"parenti di mills","dorothea millstipe","famiglia di mills"}}},fx={["926d4bb5"]={q="Da che parte sta il Membro del Concilio Mills?",a="Mills è fedele agli abitanti di Borgoscuro e al Concilio di Boscovespro. Sebbene faccia ufficialmente parte della Grande Alleanza, nutre un profondo risentimento verso la corrotta Casata dei Nobili di Roccavento e difende con fermezza la sua comunità locale dai burocrati lontani che si rifiutano di inviare aiuti.",al={"fazione di millstipe","millstipe è dell'alleanza","a chi è fedele millstipe"}},["78c3778b"]={q="Che cosa vuole il Membro del Concilio Mills?",a="Mills vuole giustizia di frontiera per Boscovespro e intende lanciare un messaggio inequivocabile alla Casata dei Nobili. Indignato perché i nobili hanno risparmiato il tombarolo Dextren Ward dalla pena capitale, Mills pretende che Ward venga ucciso nelle Segrete di Roccavento, per dimostrare che Boscovespro non tollererà le ingerenze corrotte di Roccavento.",al={"obiettivo di millstipe","che cosa vuole millstipe","obiettivo del membro del concilio millstipe"}},["7f6b4a90"]={q="Perché il Membro del Concilio Mills è qui?",a="Mills resta nel municipio di Borgoscuro per adempiere ai suoi doveri civici in seno al consiglio. Da qui affronta i pericoli sempre più gravi di Boscovespro, coordina l'amministrazione locale e recluta campioni indipendenti affinché eseguano le sentenze che i magistrati di Roccavento si rifiutano di applicare.",al={"perché millstipe è a boscovespro","perché millstipe è qui","cosa fa millstipe a borgoscuro"}},["2e4c6610"]={q="Chi è il Membro del Concilio Mills?",a="Il Membro del Concilio Mills è un membro di spicco del concilio che governa Borgoscuro, a Boscovespro. Frustrato dall'abbandono di Roccavento e dalle ingerenze burocratiche, opera nel Municipio per proteggere la sua popolazione assediata e si oppone con fermezza ai nobili lontani che minano la giustizia di frontiera di Boscovespro.",al={"chi è millstipe","membro del concilio mills","chi è il membro del concilio millstipe"}}},fp="20,148,27.433.0,23.327.1,40.84.0,42.199.0,45.239.0,37.43.0"}
P.entries["npc:count-remington-ridgewell"] = {n="Conte Remington Crestafonda",s="Nel Forte di Roccavento, il Conte Remington Crestafonda dedica le sue ricchezze a una collezione da aristocratico. Umano della House of Nobles, raccoglie manufatti rari, cimeli e opere d'arte.",h="Nel Forte di Roccavento, il Conte Remington Crestafonda dedica le sue ricchezze a una collezione da...",kw={"house of nobles","mayara brightwing","museo","diadema di perenolde","petitioner's chamber","remington crestafonda","crestafonda","forte di roccavento"},ang={["faction:Alliance"]="Come mercenario dell'Alleanza, potresti trovare nel Conte Crestafonda un mecenate generoso. Paga bene per le reliquie recuperate dai regni settentrionali caduti e dalle città naniche perdute.",["race:Human"]="Come umano, puoi vedere quanto la House of Nobles di Roccavento apprezzi il prestigio culturale e il collezionismo d'arte, anche nell'instabilità politica del regno."},sec={{t="Un intenditore di antichità",b="Il Conte Remington Crestafonda distoglie l'attenzione dalle campagne militari e dalle rivolte locali per rivolgerla al passato. Il museo della sua famiglia custodisce gioielli e manufatti, e lui spende le sue ricchezze in reliquie di civiltà e casate decadute di tutta Azeroth. Per riempire la sua galleria, finanzia avventurieri e invia agenti sul campo, come Mayara Brightwing, in rovine pericolose. Le loro ricerche spaziano dalle ridotte montane di Alterac alle distese vulcaniche delle Steppe Ardenti."}},faq={{q="Chi è il Conte Remington Crestafonda?",a="Il Conte Remington Crestafonda è un nobile umano e collezionista di antichità nella Petitioner's Chamber del Forte di Roccavento. Spende il patrimonio di famiglia in reliquie, gioielli e opere d'arte provenienti da tutto il mondo.",al={"chi è remington crestafonda","remington crestafonda","conte crestafonda"}},{q="Quali manufatti cerca il Conte Crestafonda?",a="Crestafonda cerca cimeli perduti per il suo museo, tra cui il Diadema di Perenolde dalle rovine di Alterac e antichi tesori dei Nani Ferroscuro dalle Rovine di Thaurissan.",al={"missioni di crestafonda","missione diadema di perenolde","cosa vuole"}},{q="Chi è Mayara Brightwing?",a="Mayara Brightwing è un'agente al servizio del Conte Crestafonda. Il conte l'ha inviata nelle Steppe Ardenti per cercare antichità nelle antiche Rovine di Thaurissan.",al={"collegamento con mayara brightwing","chi è mayara"}},{q="Dove si trova il Conte Remington Crestafonda?",a="Il Conte Remington Crestafonda si trova nella Petitioner's Chamber, all'interno del Forte di Roccavento. Vi si radunano nobili e dignitari che cercano un'udienza presso la corte reale.",al={"dove si trova il conte crestafonda","posizione di crestafonda","nobile della petitioner's chamber"}}},fx={["7bd2f97e"]={q="Da che parte sta il Conte Remington Crestafonda?",a="Il Conte Crestafonda è un nobile fedele del Regno di Roccavento e un membro della Casata dei Nobili. È fermamente al fianco dell'Alleanza e gestisce i suoi impegni mondani e i suoi affari privati direttamente dal Forte Reale.",al={"fazione del conte crestafonda","lealtà di crestafonda","a chi è fedele crestafonda"}},ecd2a567={q="Perché il Conte Remington Crestafonda è al Forte di Roccavento?",a="In quanto aristocratico influente e membro della Casata dei Nobili, il Conte Crestafonda partecipa alle udienze di corte nella Petitioner's Chamber del Forte di Roccavento. Qui mantiene alto il prestigio della sua famiglia, si occupa degli affari di corte e assolda avventurieri audaci per recuperare preziose reliquie in tutta Azeroth.",al={"perché crestafonda è qui","perché il conte crestafonda è al forte di roccavento","crestafonda nella petitioner's chamber"}}},fp="25,174,28.437.0,33.194.0,41.170.0,25.155.0,45.167.0"}
P.entries["npc:crane-operator-bigglefuzz"] = {n="Operatore della Gru Chiavecurva",s="Sui moli di Porto Paranco, l'Operatore della Gru Chiavecurva si affanna a recuperare il carico caduto da una gru. Cerca una bottiglia rubata prima che i suoi superiori scoprano la perdita.",h="Sui moli di Porto Paranco, l'Operatore della Gru Chiavecurva si affanna a recuperare il carico caduto da una...",kw={"chiavecurva","carico","operatore della gru","moli","mad magglish","porto","porto paranco","spargifumo"},ang={["class:Rogue"]="Come ladro, sai quanto in fretta un furfante come Mad Magglish possa sfruttare la confusione sui moli per sottrarre merce di contrabbando inestimabile sotto il naso di un goblin.",["profession:Engineering"]="Come ingegnere, sai che sovraccaricare le attrezzature di sollevamento e le gru degli Spargifumo causa la maggior parte degli incidenti industriali lungo le coste di Kalimdor."},sec={{t="Incidente sui Moli",b="L'Operatore della Gru Chiavecurva si affretta a sgomberare i rottami sparsi sui moli di Porto Paranco. Come molti scaricatori goblin, ha preferito la velocità alla sicurezza. Mentre sollevava un carico eccessivo da una nave mercantile, la sua gru ha ceduto e le casse si sono schiantate sui moli. Alcuni furfanti hanno approfittato della confusione per arraffare le merci. Ora deve recuperare il carico più prezioso prima che Sparachiodi o i capitani di porto locali gli decurtino la paga."},{t="Il Porto Rubato",b="La perdita più grave è stata una cassa di raro vino di Porto invecchiato novantanove anni. Prima che Chiavecurva potesse mettere al sicuro il carico caduto, Mad Magglish, uno sfuggente vagabondo, ha rubato una bottiglia e si è nascosto. Chiavecurva potrebbe dover rispondere della perdita di qualcosa di insostituibile."}},faq={{q="Chi è l'Operatore della Gru Chiavecurva?",a="L'Operatore della Gru Chiavecurva carica e scarica merci dalle navi sui moli di Porto Paranco per il Cartello degli Spargifumo.",al={"chi è chiavecurva","operatore della gru","chiavecurva porto paranco"}},{q="Cosa ha causato l'incidente ai moli?",a="Chiavecurva ha sovraccaricato la sua gru mentre sollevava delle merci. Il macchinario ha ceduto, spargendo il carico sul molo.",al={"perché la gru ha fatto cadere il carico","incidente al molo di porto paranco","incidente con la gru"}},{q="Chi ha derubato Chiavecurva?",a="Mad Magglish ha approfittato della confusione causata dal carico caduto, ha rubato una preziosa bottiglia di vino di Porto invecchiato novantanove anni ed è sgattaiolato via.",al={"chi ha preso il porto","mad magglish carico","chi ha derubato chiavecurva"}},{q="Perché Chiavecurva è così preoccupato per la bottiglia rubata?",a="Il vino di Porto invecchiato novantanove anni è straordinariamente raro e costoso. Perderlo per negligenza potrebbe comportare pesanti sanzioni pecuniarie o conseguenze peggiori da parte dei capi del Cartello degli Spargifumo.",al={"perché a chiavecurva importa del vino","motivo dei problemi ai moli"}}},fx={acbd2274={q="Da che parte sta l'Operatore della Gru Chiavecurva?",a="Chiavecurva lavora per il Cartello degli Spargifumo dal porto neutrale di Porto Paranco. Come la maggior parte dei goblin della città, la sua lealtà principale va ai suoi affari e ai suoi datori di lavoro, non all'Orda o all'Alleanza; accoglie chiunque sia disposto a fare affari o a rimediare a un errore costoso.",al={"fazione di chiavecurva","per chi lavora chiavecurva","schieramento dell'operatore della gru chiavecurva"}},e72c0e10={q="Che cosa vuole l'Operatore della Gru Chiavecurva?",a="Chiavecurva vuole che qualcuno recuperi la bottiglia di Porto di 99 Anni scomparsa quando il suo carico si è sparso per tutti i moli. Un goblin di nome Mad Magglish si è impossessato di quella rara annata e Chiavecurva è disperato: deve recuperarla prima che i suoi superiori scoprano l'incidente.",al={"di cosa ha bisogno chiavecurva","obiettivo di chiavecurva","cosa vuole che tu faccia chiavecurva"}},d46df1e8={q="Perché l'Operatore della Gru Chiavecurva è qui?",a="Chiavecurva è di stanza ai moli di Porto Paranco, dove manovra la pesante gru di carico e trasferisce le merci dalle navi mercantili alla riva. Purtroppo, nel tentativo di sollevare troppo carico tutto in una volta, ha danneggiato la gru e sparso le merci del porto per tutta la banchina.",al={"perché chiavecurva è a porto paranco","scopo di chiavecurva a porto paranco","perché chiavecurva è ai moli"}},eaf0ddf2={q="Con chi è legato l'Operatore della Gru Chiavecurva?",a="Chiavecurva è legato al Cartello degli Spargifumo e fa parte del personale portuale di Porto Paranco. Le sue preoccupazioni attuali lo collegano direttamente al ladro Mad Magglish, che ha rubato liquori di valore dal carico disperso.",al={"legami di chiavecurva","con chi è affiliato chiavecurva","chiavecurva e il cartello"}}},fp="25,166,19.401.0,15.241.0,33.101.0,38.112.0,26.134.0,53.182.0"}
P.entries["npc:craven-drok"] = {n="Craven Drok",s="Nella Spelonca delle Ombre, Craven Drok cerca viaggiatori per una questione delicata. Vuole che riflettano su come l'Alleanza vede l'Orda.",h="Nella Spelonca delle Ombre, Craven Drok cerca viaggiatori per una questione delicata.",kw={"alliance relations","spelonca delle ombre","craven drok","orgrimmar"},ang={["class:Rogue"]="Se sei un ladro, potresti trovare familiare la Spelonca delle Ombre, dove chi agisce di nascosto si raduna e stringe contatti come Drok.",["race:Orc"]="Se sei un orco, potresti vedere l'abitudine di Craven Drok di acquattarsi nella Spelonca delle Ombre come un affronto all'onore e al coraggio che il tuo popolo tiene in gran conto."},sec={{t="Un'ombra furtiva nell'oscurità",b="Craven Drok frequenta i sentieri tortuosi sotto Orgrimmar, lontano dai suoi viali soleggiati. La Spelonca delle Ombre attira stregoni, ladri e gente che pratica mestieri meno onorevoli. Drok rimane nascosto e assolda passanti per incarichi discreti. Uno riguarda la reputazione dell'Orda presso l'Alleanza."}},faq={{q="Dove posso trovare Craven Drok?",a="Craven Drok vaga per i sentieri sotterranei della Spelonca delle Ombre, sotto le arterie principali di Orgrimmar.",al={"posizione di craven drok","dove si trova craven drok","posizione di drok a orgrimmar"}},{q="Perché è chiamato \\\"Craven\\\"?",a="Craven Drok si guadagna il suo nome aggirandosi furtivo nelle caverne buie e tenendo la testa bassa. Assolda altri per svolgere compiti che preferirebbe evitare, contravvenendo agli ideali orcheschi di coraggio e gloria marziale.",al={"perché è vile","nome di craven drok","craven drok è un codardo"}},{q="Qual è il suo coinvolgimento con l'Alleanza?",a="Craven Drok dà inizio ad Alliance Relations lodando la saggezza di Thrall e la sua conoscenza delle usanze umane. Manda i viaggiatori da Keldran, che si adopera affinché l'Alleanza non creda erroneamente che l'Orda abbia stretto patti con la Legione Infuocata.",al={"craven drok alleanza","alliance relations drok"}},{q="Da chi invia i viaggiatori Craven Drok?",a="Craven Drok manda i viaggiatori da Keldran, uno studioso di magia la cui catapecchia si trova vicino all'uscita occidentale di Orgrimmar. Con la benedizione del Capoguerra, Keldran si adopera affinché l'Orda non venga scambiata per un'alleata della Legione Infuocata.",al={"chi è keldran","contatti di drok"}}},fx={bb25e48e={q="Chi è Craven Drok?",a="Craven Drok è un orco che si aggira nella caverna sotterranea nota come Spelonca delle Ombre, sotto Orgrimmar. Si nasconde tra gli stregoni, i furfanti e gli incantatori delle ombre della città e affida incarichi clandestini agli avventurieri disposti a occuparsi di questioni riguardanti l'Alleanza.",al={"chi è drok","storia di craven drok","chi è craven drok"}},ff4e4871={q="Perché Craven Drok si trova nella Spelonca delle Ombre?",a="La Spelonca delle Ombre offre riservatezza, lontano dagli occhi vigili della guardia d'onore di Thrall, che si trova ai piani superiori. Craven Drok si aggira qui sotto, dove gli intrighi e le questioni delicate riguardanti i servizi segreti dell'Orda e i rapporti con l'Alleanza possono essere trattati con discrezione.",al={"perché craven drok è qui","perché craven drok è nella spelonca delle ombre","motivo della presenza di craven drok"}}},fp="11,133,24.285.0,29.105.0,26.188.0,42.229.0,39.223.0"}
P.entries["npc:cyrus-therepentous"] = {n="Cyrus Therepentous",s="A Roccia Infranta, Cyrus Therepentous mette alla prova i mortali che entrano nella sua tana. Cerca superstiti abbastanza forti da servire lo Stormo dei Draghi Neri.",h="A Roccia Infranta, Cyrus Therepentous mette alla prova i mortali che entrano nella sua tana.",kw={"stormo dei draghi neri","steppe ardenti","cyrus therepentous","dragonspawn","roccia infranta","assaggio di fiamma"},sec={{t="Il Signore di Roccia Infranta",b="Dalla sua caverna a Roccia Infranta, Cyrus Therepentous sorveglia i dirupi vulcanici delle Steppe Ardenti. Disprezza i viaggiatori mortali e chiama sciocco chiunque disturbi la sua tana. Eppure non abbatte ogni intruso. Scatena invece contro di loro i suoi servitori in una prova mortale. Chi sopravvive alle fiamme potrebbe rivelarsi utile allo Stormo dei Draghi Neri."}},faq={{q="Chi è Cyrus Therepentous?",a="Cyrus Therepentous è un intelligente dragonspawn nero al servizio dello Stormo dei Draghi Neri. Mette alla prova i mortali che entrano nella sua caverna a Roccia Infranta, nelle Steppe Ardenti.",al={"cyrus therepentous","chi è cyrus","dragonspawn di roccia infranta"}},{q="Dove si trova Cyrus Therepentous?",a="Cyrus Therepentous dimora nelle profondità di una caverna a Roccia Infranta, nella parte nordorientale delle Steppe Ardenti.",al={"posizione di cyrus","dove si trova cyrus therepentous","caverna di cyrus"}},{q="Perché Cyrus non attacca a vista gli avventurieri?",a="Cyrus Therepentous medita di divorare gli intrusi, ma prima verifica se potrebbero rivelarsi utili. Li sottopone a prove mortali e li fa affrontare ai suoi servitori, risparmiando chi dimostra il proprio valore.",al={"perché cyrus è amichevole","perché cyrus non mi uccide","parlare con cyrus"}}},fp="18,146,26.357.0,26.165.0,38.94.0,46.186.0"}
P.entries["npc:dalar-dawnweaver"] = {n="Dalar Tessalba",s="A Mausolea, Dalar Tessalba rivolge il suo sapere arcano contro i nemici dei Reietti. Era un arcimago di Dalaran, ucciso quando il Flagello distrusse la città, poi liberato dal controllo del Lich King. Ora studia la persistente presenza di Dalaran e cerca di porre fine alla follia dell'arcimago Arugal.",h="A Mausolea, Dalar Tessalba rivolge il suo sapere arcano contro i nemici dei Reietti.",kw={"arcimago","arugal","dalar","dalaran","tessalba","reietti","kirin tor","mausolea","selva pinargento"},ang={["class:Mage"]="Come mago dei Reietti, puoi vedere in Dalar un oscuro riflesso dell'antica grandezza di Dalaran. La sua formazione nei Kirin Tor è ora al servizio della Dark Lady.",["faction:Horde"]="A Mausolea, Dalar contribuisce a proteggere la frontiera occidentale dell'Orda. Coordina gli attacchi contro i worgen del Forte di Zannascura e le enclavi ostili dei Kirin Tor.",["race:Undead"]="Come non morto, puoi vedere Dalar riconquistare la propria autonomia come membro dei Reietti. Rivolge le conoscenze acquisite in vita contro ciò che resta di Dalaran e i maghi rinnegati che minacciano la sovranità dei Reietti."},sec={{t="Un arcimago caduto",b="Dalar Tessalba ricopriva un tempo un alto rango tra i Kirin Tor. Percorreva i corridoi della Cittadella Violacea quando Dalaran era all'apice della maestria arcana. Il Flagello saccheggiò la città per preparare l'evocazione di Archimonde, e Dalar vi morì.\n\nRianimato come servo senza volontà del Lich King, Dalar si liberò insieme a Dama Sylvanas Ventolesto quando la presa del Flagello si allentò. Ora, a Mausolea, conserva l'intelletto acuto di un arcimago e lo dedica alla protezione del regno dei Reietti."},{t="Occhi puntati su Mulino d'Ambra e Zannascura",b="Dalar dirige la strategia arcana di Mausolea contro i molti pericoli che minacciano la Selva Pinargento. A sud, i maghi di Dalaran occupano Mulino d'Ambra, dedicandosi ad attività che intende scoprire e ostacolare. Più vicino, worgen ferali si aggirano nei boschi attorno al Forte di Zannascura.\n\nDalar conosce bene il suo ex collega, l'arcimago Arugal. Dirige con attenzione gli sforzi per fermare le creazioni bestiali di Arugal prima che invadano la regione."}},faq={{q="Chi è Dalar Tessalba?",a="Dalar Tessalba è un mago dei Reietti a Mausolea, nella Selva Pinargento. Un tempo arcimago dei Kirin Tor a Dalaran, morì durante la Third War e fu rianimato dal Flagello. Si liberò dal controllo del Lich King e si unì alla Dark Lady.",al={"chi è dalar","storia di dalar tessalba","origini di dalar"}},{q="Cosa gli è successo durante la Terza Guerra?",a="Durante la Third War, Dalar si trovava a Dalaran quando Arthas Menethil e il Flagello la invasero per recuperare il Libro di Medivh. Morì durante l'assalto, mentre Kel’Thuzad evocava Archimonde su Azeroth. Il Flagello lo rianimò come servitore, e tale rimase finché Sylvanas non lo liberò.",al={"come è morto dalar","morte di dalar","dalar terza guerra"}},{q="Perché Dalar è di stanza a Mausolea?",a="Dalar è l'autorità locale dei Reietti in materia di magia arcana nella Selva Pinargento. Conosce le forze dei Kirin Tor che occupano Mulino d'Ambra e il suo ex pari, l'arcimago Arugal, ed è quindi nella posizione ideale per contrastare entrambe le minacce.",al={"perché dalar si trova a mausolea","ruolo di dalar a selva pinargento"}},{q="Qual è il legame di Dalar con l'Arcimago Arugal?",a="Dalar e l'arcimago Arugal erano entrambi maghi dei Kirin Tor a Dalaran prima della sua caduta. Dalar comprende il tragico corso e il pericolo mortale degli esperimenti di evocazione di Arugal nel Forte di Zannascura. Invia avventurieri a raccogliere reliquie della follia di Arugal e infine esige la morte del mago folle.",al={"dalar e arugal","dalar conosceva arugal"}},{q="Cosa vuole Dalar dai superstiti di Dalaran?",a="Dalar sorveglia la sua antica patria e le forze superstiti dei Kirin Tor a Mulino d'Ambra. Incarica degli agenti di intercettarne i messaggi e studiarne le intenzioni, affinché non possano minacciare i Reietti a Silverpine.",al={"dalar e dalaran","dalar mulino d'ambra"}},{q="Dalar è alleato del Kirin Tor?",a="No. Dalar era un tempo un arcimago tra i Kirin Tor, ma ora la sua lealtà va ai Reietti e all'Orda. Si oppone attivamente alle forze superstiti dei Kirin Tor nella Selva Pinargento.",al={"dalar fa parte del kirin tor","dalar è leale a dalaran"}}},fp="16,303,17.484.0,32.416.0,24.249.0,42.253.0,40.204.0,46.294.0,45.208.0,36.183.0"}
P.entries["npc:daphne-stilwell"] = {n="Daphne Stilwell",s="Sulle scogliere delle Marche Occidentali, Daphne Stilwell veglia sul suo frutteto e sulla sua casa. Lei e suo marito Jordan sono fuggiti dal nord e ora aiutano la Chiesa della Sacra Luce, difendendo le loro terre dai fuorilegge dei dintorni.",h="Sulle scogliere delle Marche Occidentali, Daphne Stilwell veglia sul suo frutteto e sulla sua casa.",kw={"daphne stilwell","fratellanza dei defias","jordan stilwell","rivalunga","frutteto","rovonero","forte di zannascura","tomo del valore","marche occidentali"},ang={["class:Paladin"]="Come paladino, dimostri la tua dedizione alla protezione degli innocenti difendendo Daphne Stilwell dai predoni Defias durante le prove del Tomo del Valore.",["faction:Alliance"]="Come membro dell'Alleanza, condividi il fardello della famiglia Stilwell, rifugiati del nord che servono ancora l'Alleanza e la Chiesa della Sacra Luce tra i pericoli delle Marche Occidentali."},sec={{t="Una vita sulle scogliere",b="A ovest di Rivoluna e dell'uscita delle Miniere della Morte, Daphne Stilwell cura una fattoria e un meleto sulle scogliere. Rivalunga si estende più in basso, mentre le rotte dei grifoni verso la Valle di Rovotorto passano alte nel cielo. La fattoria può sembrare tranquilla da entrambe le prospettive, ma banditi e sciacalli si aggirano nei dintorni. Daphne lavora tra gli alberi e veglia sulle sue terre isolate."},{t="Rifugiati del nord",b="Prima di giungere nelle Marche Occidentali, Daphne e suo marito Jordan vivevano vicino a Rovonero, a Lordaeron. Lavoravano in quello che oggi è il Forte di Zannascura. L'oscurità e la catastrofe li spinsero a sud insieme a migliaia di altri rifugiati umani. Nei pressi di Roccavento, la rinomata abilità artigianale di Jordan e la presenza costante di Daphne li avvicinarono alla Chiesa della Sacra Luce. Sostengono la Chiesa e forniscono armi sacre ai paladini della Mano d'Argento."},{t="Difendere la fattoria",b="Daphne Stilwell affronta la minaccia della Fratellanza dei Defias nei pressi delle Miniere della Morte. Jordan viaggia o lavora ad armi sacre fuori dalla capitale, lasciandola spesso sola a occuparsi della loro casa sulla costa. Quando i briganti assalirono la fattoria per vendetta o per saccheggiarla, Daphne prese le armi al fianco degli aspiranti paladini inviati dalla Cattedrale. Si dimostrò agguerrita e capace in battaglia."}},faq={{q="Chi è Daphne Stilwell?",a="Daphne Stilwell si occupa di una fattoria isolata che domina Rivalunga, nelle Marche Occidentali. È sposata con il celebre fabbro Jordan Stilwell, e insieme sono fuggiti dai regni settentrionali devastati.",al={"chi è daphne","informazioni su daphne stilwell","moglie di stilwell"}},{q="Da dove viene Daphne?",a="Daphne viveva al nord, vicino a Rovonero, e lavorava in quello che oggi è il Forte di Zannascura. Una catastrofe spinse lei e Jordan a sud, nelle terre sotto l'influenza di Roccavento.",al={"origine di daphne","da dove viene daphne","daphne è gilneana"}},{q="Perché la sua fattoria viene attaccata dalla Fratellanza dei Defias?",a="La fattoria di Daphne domina le acque meridionali delle Marche Occidentali dalle scogliere sopra i tunnel d'uscita delle Miniere della Morte. La vicinanza alla roccaforte dei Defias la rende un bersaglio per i fuorilegge in cerca di provviste o intenzionati a eliminare gli impiccioni.",al={"perché i defias attaccano daphne","attacco alla fattoria dei defias","banditi della fattoria stilwell"}},{q="Qual è il legame di Daphne con i paladini?",a="Jordan aiuta la Chiesa della Sacra Luce forgiando armi consacrate. Durante le prove del Tomo del Valore, i paladini della Mano d'Argento vengono inviati nelle Marche Occidentali per proteggere Daphne dai banditi.",al={"missione del paladino daphne","tomo del valore daphne","perché i paladini visitano daphne"}},{q="Daphne sa difendersi?",a="Sì. Quando i Defias attaccano il suo frutteto, Daphne impugna un'arma e combatte al fianco dei paladini che difendono la fattoria.",al={"daphne combatte","daphne è una guerriera"}},{q="Come si raggiunge la sua fattoria?",a="La fattoria di Daphne sorge sulle scogliere sudoccidentali delle Marche Occidentali, a sudovest di Rivoluna, vicino all'uscita delle Miniere della Morte nella cala segreta, e domina Rivalunga.",al={"dov'è la fattoria di daphne","come arrivare alla fattoria stilwell","posizione di daphne stilwell"}}},fx={fe5dc862={q="Da che parte sta Daphne Stilwell?",a="Daphne Stilwell è schierata con l'Alleanza ed è profondamente fedele alla Chiesa della Sacra Luce. Insieme al marito Jordan, da tempo presta aiuto ai paladini di Roccavento, offrendo rifugio e sostegno ai giovani difensori della Luce che raggiungono la loro fattoria isolata.",al={"fazione di daphne stilwell","daphne stilwell è dell'alleanza","a chi è fedele daphne stilwell"}},["5fa85e8c"]={q="Che cosa vuole Daphne Stilwell?",a="Daphne desidera solo occuparsi del suo meleto e vivere in pace con il marito Jordan. Tuttavia, la Fratellanza dei Defias si aggira sulle scogliere delle Marche Occidentali e minaccia la sua casa, perciò si affida ai paladini di passaggio per tenere a bada i banditi.",al={"di cosa ha bisogno daphne stilwell","obiettivo di daphne stilwell","motivazioni di daphne stilwell"}},["57f727ad"]={q="Perché Daphne Stilwell è qui?",a="Daphne si è stabilita su questo promontorio isolato che domina Rivalunga dopo essere fuggita con il marito dal Forte di Zannascura, nella Selva Pinargento. Quando l'oscurità e la follia hanno travolto la loro dimora settentrionale, si sono diretti a sud, nel regno di Roccavento, per costruirsi una vita tranquilla, lontano dal flagello, dedicandosi all'agricoltura.",al={"perché daphne è nelle marche occidentali","perché daphne stilwell è alla fattoria","perché daphne ha lasciato zannascura"}}},fp="15,208,20.344.0,21.442.0,18.356.1,23.186.0,27.166.0,51.220.1,40.185.0,26.121.0,31.150.0"}
P.entries["npc:darcy-parker"] = {n="Darcy",s="Alla Lakeshire Inn, Darcy nutre i difensori della città e tiene alto il morale. Serve bevande e pasti caldi, con un occhio di riguardo per la Guardia Parker.",h="Alla Lakeshire Inn, Darcy nutre i difensori della città e tiene alto il morale.",kw={"darcy","guardia parker","borgolago","lakeshire inn","martie jainrose","crestarossa","cameriera"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, trovi Darcy tra la gente comune di Borgolago. Tiene alto il morale e riempie le pance mentre la città attende aiuti da Roccavento."},sec={{t="Un volto amico alla locanda",b="Darcy gestisce il bancone della Lakeshire Inn per lunghe giornate e notti. I miliziani di Borgolago vengono a mangiare e bere mentre gnoll e orchi Roccianera tengono la città sotto pressione. Si prende cura anche delle guardie di stanza in città. I viaggiatori portano pasti caldi e svolgono piccole commissioni di cortesia per i difensori di stanza lungo i confini."},{t="Amore al posto di guardia",b="Vicino a Tre Cammini, la Guardia Parker pattuglia le strade e Darcy si assicura che abbia il pranzo. Pensa che lavori troppo a stomaco vuoto, così manda spesso dei viaggiatori a portargli un pasto. Darcy tiene d'occhio Martie Jainrose. Crede che Martie sia gelosa e competa con lei per i favori di Parker, mentre tutti loro lavorano per difendere Borgolago."}},faq={{q="Chi è Darcy?",a="Darcy è una cameriera umana che lavora alla Lakeshire Inn, nelle Montagne Crestarossa. Prepara il cibo per i difensori della città e chiede ai viaggiatori di passaggio di consegnare i pasti alle guardie in servizio.",al={"chi è darcy","darcy parker png","cameriera di borgolago"}},{q="Qual è il rapporto tra Darcy e la Guardia Parker?",a="Darcy è molto affezionata alla Guardia Parker. Gli prepara pranzi freschi e li affida ai viaggiatori mentre lui pattuglia le strade vicino a Tre Cammini.",al={"darcy e guardia parker","guardia parker darcy","chi piace a darcy"}},{q="Perché Darcy è sospettosa nei confronti di Martie Jainrose?",a="Darcy pensa che Martie Jainrose sia gelosa e la considera una rivale in amore per le attenzioni della Guardia Parker.",al={"darcy e martie","martie jainrose","rivale di darcy"}},{q="Dove si trova Darcy?",a="Puoi trovare Darcy intenta a servire i clienti alla Lakeshire Inn di Borgolago, presso la riva settentrionale del Lago Placido, a Crestarossa.",al={"posizione di darcy","dove si trova darcy","trova darcy"}}},fx={e14c1e0c={q="Da che parte sta Darcy?",a="Darcy è fermamente schierata con la Grande Alleanza e con la gente del posto delle Montagne Crestarossa. Come cameriera del Lakeshire Inn, dedica le sue giornate ad accudire i difensori della città, preparare i pasti e offrire ospitalità agli abitanti e agli avventurieri dell'Alleanza di passaggio.",al={"fazione di darcy","darcy è dell'alleanza","a chi è fedele darcy"}},b7996d79={q="Che cosa vuole Darcy?",a="Darcy vuole assicurarsi che le guardie locali abbiano da mangiare e siano accudite, ma sogna anche una storia d'amore. È particolarmente infatuata della Guardia Parker, di stanza sulla strada, e si dà da fare per preparargli e mandargli pranzi caldi, preoccupandosi al contempo di possibili rivali come Martie Jainrose.",al={"di cosa ha bisogno darcy","obiettivo di darcy","motivo della missione di darcy"}},["4cbadea5"]={q="Perché Darcy è a Borgolago?",a="Darcy vive e lavora a Borgolago come cameriera della locanda locale. Mentre la città è costantemente minacciata da orchi e gnoll, qualcuno deve pur tenere aperta la locanda e servire pasti caldi ai soldati stanchi e ai viaggiatori che arrivano attraversando il grande ponte.",al={"perché darcy è qui","ruolo di darcy a borgolago","darcy al lakeshire inn"}}},fp="5,146,26.320.0,25.334.0,13.185.0,47.142.0,43.102.0,25.117.0"}
P.entries["npc:dark-cleric-beryl"] = {n="Chierico Oscuro Beryl",s="A Brill, il Chierico Oscuro Beryl guida i sacerdoti non morti appena risvegliati nell'uso della Shadow Magic. Dalla Taverna dell'Impiccato, li aiuta ad affrontare la loro empia esistenza sotto la Dama Oscura.",h="A Brill, il Chierico Oscuro Beryl guida i sacerdoti non morti appena risvegliati nell'uso della Shadow Magic.",kw={"beryl","brill","chierico oscuro beryl","sacerdote dei reietti","taverna dell'impiccato","istruttore dei sacerdoti","radure di tirisfal"},ang={["class:Priest"]="Come sacerdote dei Reietti nelle Radure di Tirisfal, puoi rivolgerti a Beryl a Brill per una guida nella Shadow Magic e nell'arduo passaggio al potere empio.",["race:Undead"]="Come non morto, puoi vedere in Beryl come i Reietti si adattano alla loro condizione maledetta. Abbandonano la cieca devozione delle antiche fedi di Lordaeron per una resilienza pragmatica legata alle ombre."},sec={{t="Una guida nelle ombre",b="Al piano superiore della Taverna dell'Impiccato di Brill, il Chierico Oscuro Beryl addestra i nuovi sacerdoti dei Reietti. Insegna che il potere di un sacerdote proviene dall'oscurità e dall'ombra, ma per padroneggiare l'oscurità occorre conoscere anche la Luce. Sotto la sua guida, i sacerdoti appena risorti si volgono all'ombra e alle arti oscure. Le loro prime prove comprendono la creazione dei loro Garments of Darkness e la dimostrazione della loro dedizione a questo cammino."}},faq={{q="Chi è il Chierico Oscuro Beryl?",a="Al piano superiore della Taverna dell'Impiccato di Brill, il Chierico Oscuro Beryl addestra i sacerdoti dei Reietti. Aiuta i nuovi risorti ad ampliare le loro conoscenze magiche e ad abbracciare le ombre.",al={"ruolo di beryl","chi è beryl","storia del chierico beryl"}},{q="Dove posso trovare il Chierico Oscuro Beryl?",a="Il Chierico Oscuro Beryl si trova al piano superiore della Taverna dell'Impiccato a Brill, nelle Radure di Tirisfal.",al={"posizione di beryl","dove si trova beryl","trovare il chierico oscuro beryl"}},{q="Perché i sacerdoti dei Reietti usano il titolo di Chierico Oscuro?",a="I sacerdoti dei Reietti che abbandonano i dogmi tradizionali della Sacra Luce, o li bilanciano con discipline più oscure, assumono il titolo di Chierico Oscuro. Il loro ordine insegna che i Reietti sono stati forgiati nella corruzione e che l'oscurità è la loro dimora. Un sacerdote deve imparare a usare con discernimento sia la luce sia l'oscurità.",al={"cos'è un chierico oscuro","chierici oscuri dei reietti","perché chierico oscuro"}},{q="Quali missioni offre Beryl?",a="Beryl guida le prime fasi dell'addestramento dei sacerdoti dei Reietti, comprese In Favor of Darkness e Garments of Darkness. Queste insegnano ai giovani accoliti ad aiutare i propri alleati e a indossare paramenti adatti all'ombra.",al={"missioni di beryl","missioni del chierico oscuro beryl"}}},fx={["4c1b78a6"]={q="Da che parte sta il Chierico Oscuro Beryl?",a="Beryl è fedele ai Reietti e alla Signora Oscura, la Regina Sylvanas Ventolesto. Dalla sua base a Brill, serve gli interessi di Sepulcra e dell'Orda istruendo i non morti appena risvegliati che sentono il richiamo del sacerdozio e aiutandoli a padroneggiare le ombre e la disciplina al servizio del loro popolo.",al={"fazione di beryl","a chi è fedele beryl","schieramento di beryl"}},fd6d5379={q="Perché il Chierico Oscuro Beryl è a Brill?",a="Beryl è di stanza alla Taverna dell'Impiccato, a Brill, per guidare i giovani sacerdoti Reietti che arrivano da Albamorta. Quando i novizi si avventurano nelle Radure di Tirisfal, fornisce loro l'addestramento e le vesti necessari per sopravvivere al Flagello, alla Crociata Scarlatta e agli altri pericoli che minacciano Lordaeron.",al={"perché beryl è a brill","perché beryl è qui","beryl alla taverna dell'impiccato"}},["6191615e"]={q="Che cosa vuole il Chierico Oscuro Beryl?",a="Beryl vuole assicurarsi che i sacerdoti novizi dei Reietti siano adeguatamente equipaggiati e disciplinati nella loro arte. Chiede ai praticanti di comprendere la loro oscura vocazione, ne mette alla prova la preparazione e fornisce loro le vesti adatte a incanalare i poteri delle ombre e della volontà incrollabile.",al={"qual è l'obiettivo di beryl","che cosa vuole beryl","motivazioni di beryl"}}},fp="17,179,22.394.0,25.158.0,35.90.0,50.305.0,29.185.0"}
P.entries["npc:dark-iron-ambassador"] = {n="Ambasciatore Ferroscuro",s="Nelle profondità di Gnomeregan, l'Ambasciatore Ferroscuro si aggira tra le sale in rovina come inviato del suo clan. Perché il clan sia giunto nella capitale gnomesca caduta resta poco chiaro.",h="Nelle profondità di Gnomeregan, l'Ambasciatore Ferroscuro si aggira tra le sale in rovina come inviato del...",kw={"cospirazione","ambasciatore ferroscuro","clan ferroscuro","gnomeregan","super trivella","thaurissan","termospin"},ang={["faction:Alliance"]="Come membro dell'Alleanza, hai motivo di indagare sulla presenza dei Ferroscuro a Gnomeregan.",["race:Dwarf"]="Come nano, potresti notare che il nano Ferroscuro nella città gnomesca in rovina attira l'attenzione degli alleati di Forgiardente.",["race:Gnome"]="Come gnomo, potresti trovare inquietante la presenza dell'emissario Ferroscuro a Gnomeregan. La sua presenza solleva interrogativi per gli investigatori gnomi."},sec={{t="Un inviato oscuro",b="Nelle sale irradiate di Gnomeregan, l'Ambasciatore Ferroscuro parla a nome del suo clan. Lo scopo della sua missione è sconosciuto."},{t="Cospirazioni nel profondo",b="Investigatori e goblin sospettano che i Ferroscuro siano coinvolti nei problemi di Gnomeregan e nella sua misteriosa super trivella. Per ora, questi sospetti restano teorie. La presenza dell'ambasciatore non dimostra chi abbia causato la caduta della città né quali termini siano stati eventualmente concordati."}},faq={{q="Chi è l'Ambasciatore Ferroscuro?",a="L'Ambasciatore Ferroscuro è un emissario del suo clan all'interno di Gnomeregan. La sua precisa missione diplomatica è sconosciuta.",al={"chi è questo nano","identità dell'ambasciatore ferroscuro","cos'è l'ambasciatore ferroscuro"}},{q="Perché un nano Ferroscuro si trova all'interno di Gnomeregan?",a="Il suo scopo è poco chiaro. La sua presenza dimostra che il clan Ferroscuro nutre interesse per Gnomeregan.",al={"perché i ferroscuro sono a gnomeregan","cosa fa qui","scopo del nano ferroscuro"}},{q="I Ferroscuro hanno contribuito a causare la caduta di Gnomeregan?",a="Nessuno lo sa. Gli investigatori sospettano dei Ferroscuro, ma le loro teorie non dimostrano chi abbia causato il disastro.",al={"i ferroscuro hanno causato l'invasione dei trogg","complotto dei ferroscuro","thaurissan ha aiutato termospin"}},{q="Da dove viene l'ambasciatore?",a="Appartiene al clan Ferroscuro, governato dall'Imperatore Dagran Thaurissan.",al={"da dove viene l'ambasciatore","chi lo ha mandato","per chi lavora"}},{q="È alleato con il Mekgeniere Termospin?",a="Si sospetta un'alleanza, ma la sua sola presenza non conferma alcun accordo.",al={"thermaplugg alleato dei ferroscuro","è con termospin","collaborazione con termospin"}},{q="Dove si può trovare l'Ambasciatore Ferroscuro?",a="L'Ambasciatore Ferroscuro è una presenza rara e sfuggente nei settori d'ingegneria contaminati e nei corridoi delle officine di Gnomeregan.",al={"posizione di comparsa ambasciatore","dove compare","posizione ambasciatore gnomeregan"}}},fx={["694fcc25"]={q="Da che parte sta l'Ambasciatore Ferroscuro?",a="È legato al clan Ferroscuro.",al={"fazione dell'ambasciatore ferroscuro","a chi serve l'ambasciatore","alleanze dell'ambasciatore ferroscuro"}},e7a948f2={q="Che cosa vuole l'Ambasciatore Ferroscuro?",a="La sua missione precisa e i suoi obiettivi a Gnomeregan sono sconosciuti.",al={"obiettivo dell'ambasciatore ferroscuro","perché i ferroscuro sono venuti a gnomeregan","motivazione dell'ambasciatore ferroscuro"}},["388c8a07"]={q="A chi è legato l'Ambasciatore Ferroscuro?",a="Rappresenta il clan Ferroscuro. Si è sospettato un legame con Mekgeniere Termospin, ma la natura di tale legame non è confermata.",al={"legami dell'ambasciatore ferroscuro","a chi risponde l'ambasciatore","imperatore ferroscuro"}}},fp="20,165,15.120.0,24.273.1,32.113.0,43.92.0,53.108.0,36.69.0,40.71.0,44.129.0"}
P.entries["npc:darkmaster-gandling"] = {n="Maestro Oscuro Gandling",s="Sotto Caer Darrow, il Maestro Oscuro Gandling addestra negromanti per il Flagello. Da Scholomance, serve il Cult of the Damned conducendo esperimenti sui vivi e sui morti.",h="Sotto Caer Darrow, il Maestro Oscuro Gandling addestra negromanti per il Flagello.",kw={"caer darrow","cult of the damned","maestro oscuro gandling","gandling","preside","negromante","scholomance"},ang={["class:Mage"]="Come mago, potresti vedere Gandling distorcere le tradizioni accademiche di Dalaran per creare la non morte.",["race:Undead"]="Come non morto, potresti vedere Gandling come un odiato supervisore dell'indottrinamento del Flagello. Sotto Caer Darrow, incatena anime libere a una schiavitù eterna."},sec={{t="Il Dominio del Preside",b="Il Maestro Oscuro Gandling governa Scholomance sotto Caer Darrow. L'accademia addestra aspiranti negromanti per il Flagello. Gandling è un umano vivente del Cult of the Damned. Insieme al lich Ras Frostwhisper, ha commesso atrocità contro prigionieri innocenti catturati nelle terre circostanti. Nelle aule, gli studenti imparano a preparare pestilenze, rianimare i morti e plasmare la carne."},{t="Maestro del Reliquiario",b="Nello Studio del Preside, Gandling comanda le oscure reliquie e gli spiriti intrappolati di Scholomance. Unisce la magia arcana e la Shadow Magic alla negromanzia proibita. Con queste arti, maledice gli intrusi e li scaglia attraverso portali d'ombra nelle stanze sigillate attorno allo studio. Lì affrontano da soli i morti risorti, mentre Gandling si protegge dai danni."}},faq={{q="Chi è il Maestro Oscuro Gandling?",a="Il Maestro Oscuro Gandling dirige Scholomance, dove addestra negromanti al servizio del Lich King. È un umano del Cult of the Damned.",al={"chi è gandling","storia del maestro oscuro gandling","boss di scholomance"}},{q="Gandling è un non morto o un essere umano vivente?",a="Gandling è un umano vivente e mortale, sebbene padroneggi la magia della morte e serva il Flagello. Guida accoliti e cultisti mortali all'interno di Scholomance.",al={"gandling è un non morto","gandling è vivo","razza di gandling"}},{q="Qual è il suo legame con Ras Frostwhisper?",a="Ras Frostwhisper è stato il maestro di Gandling. Il preside umano e il potente lich dirigevano gli oscuri insegnamenti di Scholomance e supervisionavano gli orrori inflitti ad anime innocenti come i Sarkhoffs a Caer Darrow.",al={"frostwhisper gandling","ras frostwhisper insegnante"}},{q="Dove si trova il Maestro Oscuro Gandling?",a="Gandling risiede nello Studio del Preside, nelle profondità di Scholomance. Le catacombe sotto Caer Darrow, nel Lago Darrowmere, conducono fin lì.",al={"posizione di gandling","dove si trova gandling","come trovare gandling"}}},fp="19,176,23.375.0,23.345.0,27.131.0,40.147.0,43.206.0,35.137.0"}
P.entries["npc:darn-talongrip"] = {n="Darn Morsartiglio",s="A Malaka'jin, Darn Morsartiglio sorveglia la frontiera di Stonetalon. L'esploratore orco segue le minacce tra i dirupi e porta notizie tra gli avamposti avanzati e i comandanti dell'Orda.",h="A Malaka'jin, Darn Morsartiglio sorveglia la frontiera di Stonetalon.",kw={"darn morsartiglio","kadrak","malakajin","esploratore orco","stonetalon"},ang={["faction:Horde"]="Darn Morsartiglio sorveglia la salita verso Stonetalon e offre un punto di contatto agli avventurieri dell'Orda appena giunti dalle Savane.",["race:Orc"]="Come Orco, conosci l'aspra frontiera dove Darn monta la guardia tra rocce frastagliate e fauna ostile."},sec={{t="Esploratore di frontiera di Stonetalon",b="Darn Morsartiglio sorveglia le aspre salite che dalle Savane Meridionali conducono a Stonetalon. A Malaka'jin, indirizza le reclute verso i nuovi fronti dell'Orda a Valtetra. I viaggiatori che salgono verso le vette contese possono entrare in contatto con l'Orda attraverso la sua postazione."},{t="Occhi per il comando",b="Da Malaka'jin, Darn invia messaggi e rapporti dal fronte a comandanti come Kadrak, presso la torre di guardia nelle Savane settentrionali. Gli accampamenti sparsi tra le montagne sono sotto costante pressione. Come sentinella e corriere, Darn tiene informata l'avanguardia dell'Orda."}},faq={{q="Chi è Darn Morsartiglio?",a="Darn Morsartiglio svolge ricognizioni per l'Orda da Malaka'jin, nella parte meridionale delle Vette di Petrartiglio.",al={"chi è darn morsartiglio","identità di darn morsartiglio","chi è questo orco"}},{q="Dove si trova Darn Morsartiglio?",a="Puoi trovare Darn Morsartiglio nell'insediamento dei Troll di Malaka'jin, nelle Vette di Petrartiglio.",al={"posizione di darn morsartiglio","dove si trova darn morsartiglio","coordinate di darn morsartiglio"}},{q="Qual è il suo ruolo a Stonetalon?",a="Darn indirizza le reclute da Kadrak nelle Savane settentrionali per contribuire alla difesa degli avamposti dell'Orda a Valtetra.",al={"cosa fa darn morsartiglio","scopo di darn morsartiglio"}},{q="Chi è Kadrak e perché Darn gli invia i viaggiatori?",a="Kadrak comanda l'Orda dalla torre di guardia nelle Savane settentrionali e guida la sua campagna a Valtetra. Darn gli invia reclute per contribuire alla difesa dei nuovi fronti dell'Orda a Valtetra.",al={"chi è kadrak","report to kadrak"}}},fx={b53227de={q="Da che parte sta Darn Morsartiglio?",a="Darn Morsartiglio è saldamente schierato con l'Orda. Operando dalle Vette di Petrartiglio, nei pressi di Malaka'jin, collabora con gli altri orchi per mettere in sicurezza i sentieri impervi e consolidare la presenza dell'Orda in tutta Kalimdor.",al={"fazione di darn morsartiglio","darn morsartiglio è dell'orda","a chi serve darn morsartiglio"}},["3e5a66b7"]={q="Che cosa vuole Darn Morsartiglio?",a="Darn Morsartiglio vuole proteggere la presenza dell'Orda lungo il passo e indirizzare gli avventurieri più capaci dove la loro forza serve di più, in particolare inviando viaggiatori ad aiutare Kadrak nelle urgenti operazioni dell'Orda nei dintorni.",al={"che cosa cerca darn morsartiglio","obiettivi di darn morsartiglio","che cosa vuole darn"}},d56f5cfb={q="Perché Darn Morsartiglio si trova qui, nelle Vette di Petrartiglio?",a="Di stanza nei pressi di Malaka'jin e dei passi circostanti delle Vette di Petrartiglio, Darn Morsartiglio mantiene la presenza di frontiera dell'Orda, sorvegliando le strade montane e assicurandosi che le sentinelle degli avamposti si scambino rapidamente le informazioni.",al={"perché darn morsartiglio è nelle vette di petrartiglio","perché darn è qui","motivo per cui darn morsartiglio si trova nelle vette di petrartiglio"}}},fp="14,168,28.244.0,20.268.0,22.89.0,34.95.0,31.105.0,55.183.0"}
P.entries["npc:darsok-swiftdagger"] = {n="Darsok Dagalesta",s="A Crocevia, Darsok Dagalesta sorveglia i sentieri settentrionali. Il ricognitore orco invia combattenti dell'Orda contro le arpie Witchwing nei Colli Aridi, le cui incursioni minacciano viaggiatori e insediamenti. È anche un vecchio amico del Taumaturgo Jin'zil di Malaka'jin.",h="A Crocevia, Darsok Dagalesta sorveglia i sentieri settentrionali.",kw={"savane","bloodfeather","crocevia","darsok","arpia","jin'zil","serena","dagalesta","thork","witchwing"},ang={["class:Rogue"]="Come ladro, puoi riconoscere la predilezione di Darsok per gli attacchi precisi e letali contro i capi nemici, volti a decapitarli.",["faction:Horde"]="Come viaggiatore dell'Orda, puoi contare sulle prime missioni tattiche di Darsok per contribuire a proteggere le rotte commerciali del crocevia dagli attacchi dall'alto.",["race:Orc"]="Come orco, puoi vedere l'approccio marziale e mirato di Darsok per mettere in sicurezza la pericolosa frontiera di Kalimdor."},sec={{t="Una sentinella a Crocevia",b="Da Crocevia, Darsok Dagalesta sorveglia la boscaglia settentrionale. Le strade tra Durotar, Mulgore e le propaggini settentrionali delle Savane sono minacciate da predoni e centauri. Anche gruppi organizzati di cacciatrici calano dal cielo. L'ira di Darsok è rivolta alle arpie Witchwing. I loro nidi si trovano nei Colli Aridi, a nord-ovest delle Sorgenti Dimenticate, da dove minacciano le carovane dirette a nord."},{t="La guerra contro le Witchwing",b="Darsok invia combattenti nel territorio delle Witchwing, cominciando dalle Harpy Raiders. Poi manda combattenti esperti contro i luogotenenti delle arpie. Infine, li invia contro la loro matriarca, Serena Bloodfeather. Spezzando gradualmente la loro catena di comando, spera di disperdere lo stormo tra i dirupi."},{t="Contatti nella boscaglia",b="Molto a nord-ovest delle Savane, Darsok ha un vecchio amico: il Taumaturgo Jin'zil. Jin'zil è un troll che vive a Malaka'jin nelle Vette di Petrartiglio, la terra da cui provengono le arpie. Darsok gli invia una lettera con notizie sulla campagna contro le arpie. I due amici non hanno contatti da molti anni."}},faq={{q="Dove si trova Darsok Dagalesta?",a="Darsok Dagalesta fa la guardia a Crocevia, l'insediamento centrale dell'Orda nelle Savane. Indirizza i viaggiatori verso le minacce a nord.",al={"posizione di darsok","dove si trova darsok dagalesta","trova darsok","punto in cui si trova darsok dagalesta"}},{q="Perché Darsok dà la caccia alle arpie?",a="Le arpie Witchwing nidificano nei canyon a nord-ovest delle Sorgenti Dimenticate. Minacciano carovane, viaggiatori e ricognitori dell'Orda sui sentieri settentrionali delle Savane.",al={"perché uccidere le arpie","rancore di darsok verso le arpie","arpie witchwing savane"}},{q="Chi è Serena Bloodfeather?",a="Serena Bloodfeather guida le arpie Witchwing dei Colli Aridi. Darsok invia combattenti a ucciderla e a spezzare la catena di comando dello stormo.",al={"serena bloodfeather","capo arpie savane","leader delle witchwing"}},{q="Qual è il legame di Darsok con il Taumaturgo Jin'zil?",a="Il Taumaturgo Jin'zil, un troll che vive a Malaka'jin nelle Vette di Petrartiglio, è un vecchio amico di Darsok. Darsok manda un viaggiatore da Jin'zil con una lettera sulla campagna contro le arpie, le prime notizie che gli invia dopo molti anni.",al={"lettera per jin'zil","darsok e jin'zil","legame con il taumaturgo jin'zil"}},{q="Darsok risponde a Sergra Darkthorn o a Thork?",a="Darsok organizza la sua campagna contro le arpie da Crocevia. Nessuna fonte di Classic identifica Sergra Darkthorn o Thork come suo diretto superiore.",al={"darsok thork","a chi risponde darsok","comando di crocevia"}},{q="Dove nidificano le arpie Witchwing?",a="Le arpie Witchwing nidificano nei Colli Aridi, a nord-ovest delle Sorgenti Dimenticate, nella parte settentrionale delle Savane.",al={"posizione delle witchwing","arpie dei colli aridi","dove trovare arpie savane"}}},fx={c43e4047={q="Chi è Darsok Dagalesta?",a="Darsok Dagalesta è un esploratore e guerriero orco dell'Orda di stanza a Crocevia. Dedito a proteggere The Barrens dalle minacce locali, si è guadagnato una temibile reputazione soprattutto per la sua instancabile campagna contro le arpie Alavelenosa che infestano la regione.",al={"chi è darsok","chi è darsok dagalesta","informazioni su darsok"}},cbab4453={q="Da che parte sta Darsok Dagalesta?",a="Darsok è saldamente schierato con l'Orda. Operando da Crocevia, difende Kalimdor e aiuta l'insediamento neutralizzando le minacce che prendono di mira viaggiatori e carovane commerciali.",al={"fazione di darsok","darsok è dell'orda","lealtà di darsok"}},bc228dd6={q="Che cosa vuole Darsok Dagalesta?",a="Darsok vuole eliminare del tutto la minaccia delle Alavelenosa nella parte settentrionale di The Barrens. Recluta avventurieri capaci per decimare i predoni dello stormo, eliminare i loro luogotenenti sul campo e infine uccidere la loro feroce matriarca, Serena Piumasangue.",al={"obiettivo di darsok","che cosa vuole darsok","perché darsok combatte le arpie"}},aac9a722={q="Perché Darsok Dagalesta si trova qui?",a="Di stanza a Crocevia, Darsok è un'avanguardia fondamentale contro i pericoli che minacciano le rotte commerciali settentrionali. È rimasto qui per tenere d'occhio l'aggressività delle arpie vicine e organizzare le operazioni militari per respingerle dalle terre dell'Orda.",al={"perché darsok è a crocevia","motivo per cui darsok si trova a crocevia","perché darsok è qui"}}},fp="18,266,27.381.0,24.303.1,24.295.0,36.144.0,30.155.0,27.132.0,52.215.0,48.149.0,36.103.0"}
P.entries["npc:daryl-the-youngling"] = {n="Daryl il Giovincello",s="Al Padiglione Lungopasso, Daryl il Giovincello mette alla prova la mira dei viaggiatori contro le bestie di Loch Modan. Il giovane cacciatore umano spera di guadagnarsi un posto tra i veterani tracciatori nani.",h="Al Padiglione Lungopasso, Daryl il Giovincello mette alla prova la mira dei viaggiatori contro le bestie di...",kw={"caccia ai cinghiali","daryl","padiglione lungopasso","cacciatore","vanto del cacciatore","loch modan","giovincello"},ang={["class:Hunter"]="Le sfide di Daryl mettono alla prova la capacità di seguire le tracce, la conoscenza del comportamento delle bestie e l'abilità venatoria dei cacciatori erranti che giungono al Padiglione Lungopasso.",["race:Human"]="Se sei umano, puoi trovare un giovane che impara a cavarsela nelle terre selvagge, nel cuore del territorio nanico. Un cameratismo concreto unisce Forgiardente e i regni umani."},sec={{t="Un umano tra i montanari",b="Montanari, tracciatori ed esperti esploratori nani sorvegliano le terre selvagge di Loch Modan dal Padiglione Lungopasso. Lì Daryl mette alla prova il proprio istinto venatorio confrontandosi con i viaggiatori. Li sfida a cacciare i coriacei cinghiali selvatici e le altre bestie che si aggirano tra i dirupi e le rive del lago."}},faq={{q="Chi è Daryl il Giovincello?",a="Daryl è un giovane cacciatore umano al Padiglione Lungopasso, a Loch Modan. Tra gli esperti tiratori nani del padiglione, sfida i nuovi arrivati a mettere alla prova le proprie abilità nella caccia e nell'inseguimento.",al={"chi è daryl","storia di daryl","chi è daryl il giovincello"}},{q="Dove si trova Daryl?",a="Daryl soggiorna al Padiglione Lungopasso, sulle alture boscose che sovrastano le rive sudorientali di Loch Modan.",al={"posizione di daryl","dove si trova daryl il giovincello","dove trovare daryl"}},{q="Perché viene chiamato \\\"il Giovincello\\\"?",a="I tiratori nani e gli abituali frequentatori del padiglione pattugliano da decenni l'aspro entroterra di Khaz Modan. Al loro confronto, Daryl è giovane e inesperto, ancora intento a costruirsi una solida reputazione come cacciatore.",al={"perché giovincello","soprannome di daryl"}}},fx={e75652fe={q="Da che parte sta Daryl il Giovincello?",a="Daryl è alleato dell'Alleanza e ha allestito il suo campo tra i tiratori scelti nanici di Loch Modan. Di stanza al Padiglione Lungopasso, collabora con gli altri alpinisti e amanti della vita all'aria aperta per mettere in sicurezza le terre selvagge della regione.",al={"fazione di daryl","daryl è dell'alleanza","a chi serve daryl"}},a39b90d4={q="Che cosa vuole Daryl il Giovincello?",a="Daryl non vede l'ora di dimostrare la sua abilità con l'arco e nella vita all'aria aperta. Cerca avventurieri capaci che mettano alla prova le loro abilità di tracciamento e caccia con la fauna locale di Loch Modan; ama l'emozione dell'inseguimento e le sfide della caccia.",al={"che cosa vuole daryl","obiettivi di daryl","missioni di daryl"}},f7496387={q="Perché Daryl il Giovincello si trova al Padiglione Lungopasso?",a="Il Padiglione Lungopasso è un rifugio per i migliori tracciatori e cacciatori di bestie della valle. Daryl trascorre qui il suo tempo affinando le proprie abilità insieme a veterani tiratori scelti nanici e approfittando dell'abbondante selvaggina che popola le colline di Loch Modan.",al={"perché daryl è qui","perché daryl è a loch modan","daryl giovincello padiglione lungopasso"}},d22cfcb5={q="A chi è legato Daryl il Giovincello?",a="Daryl frequenta i cacciatori e i custodi del Padiglione Lungopasso, tra cui Vyrin Swiftwind. Condivide la loro dedizione alla caccia e li aiuta a gestire le bestie selvatiche che si aggirano vicino all'avamposto nanico.",al={"alleati di daryl","daryl al padiglione lungopasso","con chi è daryl"}}},fp="19,178,26.266.0,27.176.0,25.91.0,33.193.0"}
P.entries["npc:dashel-stonefist"] = {n="Dashel Pugnosaldo",s="A Città Vecchia, Dashel Pugnosaldo si fa notare per il temperamento irascibile, le mani pesanti e i legami pericolosi. Il nano chiamato Fist frequenta i vicoli più malfamati di Roccavento, dove gli investigatori sotto copertura lo tengono d'occhio.",h="A Città Vecchia, Dashel Pugnosaldo si fa notare per il temperamento irascibile, le mani pesanti e i legami...",kw={"attaccabrighe","dashel","defias","fist","diplomatico scomparso","città vecchia","pugnosaldo","roccavento"},ang={["class:Rogue"]="Per i ladri che si muovono nella rete criminale di Città Vecchia, Dashel Pugnosaldo mostra quanto un agente possa parlare dopo qualche pugno alla mascella. Affidare segreti delicati alla forza bruta è una pessima scommessa.",["faction:Alliance"]="Dashel Pugnosaldo rivela il marciume nascosto nella capitale di Roccavento. L'influenza della Fratellanza dei Defias si estende oltre le fattorie delle Marche Occidentali, fin dentro la città sovrana.",["race:Dwarf"]="Molti nani di Forgiardente a Roccavento lavorano come rispettati fabbri, montanari o emissari. Pugnosaldo dimostra che un nano può anche cadere nella delinquenza di strada e nel tradimento."},sec={{t="Un attaccabrighe a Città Vecchia",b="Città Vecchia conosce Dashel Pugnosaldo come Fist, un soprannome guadagnato nelle risse di strada. Gli abitanti e le guardie cittadine vedono un nano ubriaco e bellicoso, pronto a sferrare un pugno fuori da una taverna. La sua presenza nel quartiere lo tiene vicino alla malavita di Roccavento. Contrabbandieri, borseggiatori e agitatori politici vi scambiano monete e voci, lontano dagli occhi di Piazza della Cattedrale."},{t="La scomparsa della Diplomatica",b="Un diplomatico scomparso conduce gli investigatori reali sotto copertura da Dashel Pugnosaldo. Voci di tradimento indicano il nano, un contatto di strada della Fratellanza dei Defias all'interno delle mura di Roccavento. Sa del rapimento, ma si rifiuta di parlare finché gli investigatori non lo sottomettono a pugni. Ciò che rivela si addentra nella politica del regno ben oltre un semplice rapimento."}},faq={{q="Chi è Dashel Pugnosaldo?",a="A Città Vecchia, a Roccavento, Dashel Pugnosaldo lavora come tagliagole e informatore nei quartieri più oscuri della capitale. Il nano chiamato Fist ha una reputazione violenta e l'abitudine di azzuffarsi.",al={"chi è dashel","chi è fist","storia di dashel pugnosaldo"}},{q="Dove posso trovare Dashel Pugnosaldo?",a="Puoi trovare Dashel Pugnosaldo all'aperto a Città Vecchia, tra i vicoli secondari vicino ai ritrovi cittadini di ladri e guerrieri.",al={"posizione di dashel","dove si trova dashel pugnosaldo","trova dashel"}},{q="Perché gli investigatori devono combatterlo?",a="Le piste nella ricerca del diplomatico reale scomparso indicano agli investigatori Dashel Pugnosaldo come complice. È estremamente fedele ai suoi loschi datori di lavoro e non rivela ciò che sa finché non viene sconfitto in una rissa a mani nude.",al={"perché attaccare dashel","sottomettere dashel pugnosaldo","combattere dashel"}},{q="Qual è il suo legame con la Fratellanza dei Defias?",a="Dashel Pugnosaldo opera all'interno di Roccavento come agente e messaggero della Fratellanza dei Defias. Coordina i contatti locali e gli sgherri di strada per nascondere i piani della Fratellanza alla City Guard.",al={"dashel appartiene ai defias","dashel pugnosaldo defias","defias a roccavento"}},{q="Chi è il diplomatico scomparso collegato a Dashel?",a="Gli agenti reali indagano sulla vicenda di un diplomatico dal nome sconosciuto, svanito durante il viaggio verso Theramore.",al={"chi è il diplomatico scomparso","serie di missioni the missing diplomat","re varian scomparso"}},{q="Dashel è imparentato con altri nani noti?",a="Non si conoscono parenti di Dashel Pugnosaldo. I suoi legami criminali a Roccavento lo distinguono dalla rispettabile società nanica.",al={"parente telda pugnosaldo","famiglia di dashel pugnosaldo","famiglia pugnosaldo"}}},fx={["06e53778"]={q="Da che parte sta Dashel Pugnosaldo?",a="Dashel Pugnosaldo cammina su una linea pericolosa tra il mondo criminale della Città Vecchia e il tradimento aperto. Si spaccia per un semplice attaccabrighe dei vicoli cittadini, ma le sue alleanze segrete sono con la Fratellanza dei Defias: passa informazioni e contribuisce a coordinare le loro attività sovversive proprio sotto il naso delle guardie di Roccavento.",al={"fazione di dashel pugnosaldo","per chi lavora dashel","dashel è un defias"}},["388c2391"]={q="Perché Dashel Pugnosaldo si trova nella Città Vecchia?",a="Dashel si aggira nella Città Vecchia perché le sue strade affollate e ombrose offrono una copertura ideale per gli affari illeciti. Lontana dalla sorveglianza impeccabile di Piazza della Cattedrale o della corte reale, la Città Vecchia gli permette di mantenere i contatti con cospiratori misteriosi, organizzare accordi nei vicoli e tenere d'occhio i movimenti in città senza attirare prematuramente l'attenzione delle autorità.",al={"perché dashel è a roccavento","perché dashel pugnosaldo si trova qui","che cosa fa dashel nella città vecchia"}},["329088a4"]={q="Perché Dashel Pugnosaldo è conosciuto come Pugno?",a="Gli abitanti del posto e i teppisti della Città Vecchia conoscono Dashel semplicemente come «Pugno», soprannome che si è guadagnato per il suo temperamento notorio e la tendenza a risolvere ogni disputa con la violenza. La sua fama di brutale attaccabrighe dei vicoli è tale che la maggior parte dei cittadini e dei borseggiatori ci pensa due volte prima di provocarlo o ficcare il naso nei suoi affari.",al={"perché dashel è chiamato pugno","soprannome di dashel pugnosaldo","reputazione di dashel"}}},fp="16,209,21.350.0,28.373.1,24.188.0,34.114.0,39.225.1,49.201.1,48.88.2,45.123.0"}
P.entries["npc:david-trias"] = {n="David Trias",s="Ad Albamorta, David Trias insegna ai Reietti appena risvegliati a muoversi senza essere visti e a combattere con una lama. Li prepara a servire la Regina Sylvanas e i Reietti.",h="Ad Albamorta, David Trias insegna ai Reietti appena risvegliati a muoversi senza essere visti e a combattere...",kw={"david trias","albamorta","elling trias","pergamena codificata","reietti","addestratore dei ladri","radure di tirisfal"},ang={["class:Rogue"]="Come ladro dei Reietti, hai in David Trias il tuo primo mentore. Ti aiuta a decifrare pergamene segrete e ti insegna a impugnare una lama con la fredda precisione della non morte.",["race:Undead"]="Come non morto, conosci la cupa realtà dei Reietti: un tempo eri un umano di Lordaeron, ma la piaga ti ha separato dalla tua vita precedente e dalla tua stirpe. Ora servi la Regina Sylvanas."},sec={{t="Una guida dalle ombre",b="Tra le lapidi e le rovine di Albamorta, David Trias addestra i non morti appena risorti. Cerca chi ha un talento per uccidere senza essere visto. Per i Reietti alle prime armi, sopravvivere richiede più della forza delle armi. Serve un colpo preciso sferrato dall'oscurità.\n\nTrias decifra i loro ordini e insegna loro a impugnare i pugnali e a celare i propri movimenti. Mostra loro come usare i propri riflessi rianimati contro i vivi e il Flagello."},{t="Un nome familiare",b="A Roccavento, David Trias condivide il cognome con Elling Trias, un noto mercante di formaggi. Elling mantiene segretamente stretti legami con maestri ladri e capi delle spie. Non è confermato alcun legame familiare tra David ed Elling."}},faq={{q="Chi è David Trias?",a="David Trias addestra i ladri Reietti appena risvegliati ad Albamorta, nelle Radure di Tirisfal. Insegna loro le prime tecniche di combattimento e affida loro i primi incarichi segreti.",al={"david trias","chi è david trias","addestratore dei ladri albamorta"}},{q="Dove posso trovare David Trias?",a="Trovi David Trias ad Albamorta, il villaggio iniziale dei Reietti nelle Radure di Tirisfal. Si trova vicino agli edifici dell'insediamento, dove aiuta i non morti appena risorti.",al={"posizione di david trias","dove si trova david trias","addestratore dei ladri di albamorta"}},{q="David Trias è imparentato con Elling Trias a Roccavento?",a="David Trias condivide il cognome con Elling Trias di Roccavento, ma non è confermato alcun legame familiare.",al={"legame con elling trias","famiglia trias","è imparentato con elling trias"}},{q="Qual è il suo ruolo nell'addestramento dei Reietti?",a="I ladri appena risorti dalla cripta di Albamorta portano a David Trias una pergamena cifrata. Lui decifra le loro istruzioni, insegna loro le prime abilità e li avvia agli incarichi segreti per i Reietti.",al={"missioni di david trias","pergamena codificata","cosa insegna"}}},fx={e2140548={q="Da che parte sta David Trias?",a="David Trias è fedele a Lady Sylvanas Ventolesto e ai Reietti. Di stanza ad Albamorta, dedica la sua non-vita ad addestrare i furfanti appena risorti, aiutandoli a padroneggiare furtività, astuzia e pugnalate alle spalle per difendere il loro libero arbitrio dalla Scourge e dalle minacce dei vivi.",al={"fazione di david trias","a chi serve david trias","lealtà di david trias"}},["2dca586e"]={q="Perché David Trias si trova ad Albamorta?",a="Albamorta è il principale luogo di risveglio per i Reietti appena risorti. David Trias è rimasto qui per valutare i nuovi arrivati portati per la furtività e la discrezione, fornendo loro indicazioni e istruzioni di base prima che si avventurino oltre nelle Radure di Tirisfal.",al={"perché david trias è qui","david trias ad albamorta","che cosa porta david trias ad albamorta"}},["52093a30"]={q="Che cosa vuole David Trias?",a="Trias vuole che i furfanti appena risvegliati si adattino rapidamente alla loro condizione di non morti e diventino agenti efficaci per la Dama Oscura. Si aspetta che tu impari il valore di colpire alle spalle e padroneggi le arti essenziali dei furfanti, così da sopravvivere alle dure lotte che attendono i Reietti.",al={"motivazioni di david trias","di che cosa ha bisogno david trias","obiettivo di david trias"}}},fp="11,160,24.422.0,15.219.1,19.172.0,29.155.0,52.101.0,44.197.0"}
P.entries["npc:dawnwatcher-selgorm"] = {n="Miraurora Selgorm",s="Sulla Terrazza degli Artigiani a Darnassus, il Miraurora Selgorm sorveglia le minacce nel nord di Kalimdor. L'umano serve l'Alba d'Argento come osservatore e ufficiale di collegamento nella capitale degli elfi della notte, seguendo le segnalazioni sulle attività delle sette e sulle forze oscure che si risvegliano nelle vicinanze.",h="Sulla Terrazza degli Artigiani a Darnassus, il Miraurora Selgorm sorveglia le minacce nel nord di Kalimdor.",kw={"alba d'argento","abissi di fondocupo","blackfathom villainy","terrazza degli artigiani","darnassus","miraurora selgorm","martello del crepuscolo"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza che esplora il nord di Kalimdor, puoi rivolgerti a Selgorm come punto di collegamento tra Darnassus e la lotta contro le sinistre sette lungo la costa.",["race:Human"]="Come umano in viaggio tra i rami remoti di Teldrassil, potresti trovare un connazionale al servizio dell'Alba d'Argento."},sec={{t="Occhi nell'Albero del Mondo",b="Il Miraurora Selgorm veglia su Darnassus per conto dell'Alba d'Argento. Sebbene l'ordine combatta il Flagello dei non morti nelle Terre Infette Orientali, la sua vigilanza si estende oltre. Dalla Terrazza degli Artigiani, Selgorm raccoglie rapporti sulle nuove minacce nelle terre selvagge di Kalimdor. L'umano collega gli elfi della notte alla più ampia lotta contro il male antico e cerca viaggiatori dell'Alleanza capaci di colpire cultisti e forze oscure prima che si diffondano."},{t="Un colpo contro l'oscurità",b="Gli Abissi di Fondocupo si trovano sotto la Spiaggia di Zoram a Valtetra, dove la setta del Martello del Crepuscolo e i serpentini naga si sono radunati nelle rovine allagate. Selgorm ricompensa i campioni esperti che vi si avventurano per colpire i capi della setta e recuperare reliquie contaminate. La speranza è di placare le ombre che minacciano le sacre coste di Kalimdor."}},faq={{q="Chi è il Miraurora Selgorm?",a="Il Miraurora Selgorm è un agente umano dell'Alba d'Argento, di stanza a Darnassus per vigilare sul male che si diffonde a Kalimdor.",al={"selgorm","chi è selgorm","storia del miraurora selgorm"}},{q="Dove si trova il Miraurora Selgorm?",a="Il Miraurora Selgorm si trova all'aperto sulla Terrazza degli Artigiani a Darnassus, affacciato sulle botteghe della capitale degli elfi della notte.",al={"posizione di selgorm","dove si trova selgorm","selgorm darnassus"}},{q="Perché un membro dell'Alba d'Argento si trova a Darnassus?",a="L'Alba d'Argento combatte il Flagello a Lordaeron e cerca di estirpare il male ovunque. A Darnassus, Selgorm sorveglia le crescenti attività delle sette, tra cui il Martello del Crepuscolo nel nord di Kalimdor.",al={"alba d'argento a darnassus","perché l'alba d'argento è qui"}},{q="Cosa chiede di fare Selgorm agli avventurieri?",a="Selgorm attende gli eroi dell'Alleanza di ritorno dagli Abissi di Fondocupo a Valtetra con la testa del Signore del Crepuscolo Kelris, capo del Martello del Crepuscolo in quel luogo. Argent Guard Thaelrid, ferito, li esorta a uccidere Kelris e a fermare la diffusione della corruzione della setta.",al={"missione di selgorm","chi assegna la missione blackfathom villainy"}}},fx={["7dd87e6e"]={q="Da che parte sta Miraurora Selgorm?",a="Selgorm è un'agente dell'Alba d'Argento, un ordine neutrale dedito a proteggere Azeroth dalla corruzione e dall'oscurità. Sebbene l'Alba agisca indipendentemente dalle rivalità tra fazioni, Selgorm si è accampata tra gli Elfi della Notte a Darnassus per chiedere aiuto ai campioni dell'Alleanza disposti a colpire i culti malvagi.",al={"fazione di selgorm","chi serve selgorm","selgorm è dell'alleanza"}},["6f2227e4"]={q="A chi fa capo Miraurora Selgorm?",a="Selgorm risponde direttamente all'Alba d'Argento. Sebbene sia di stanza nella capitale degli Elfi della Notte, Darnassus, il suo dovere è legato alla vigilanza globale del suo ordine, non alla leadership dei Kaldorei. Tiene d'occhio le minacce oscure che si annidano lontano dalle principali roccaforti dell'ordine nelle Terre Infette.",al={"selgorm e alba d'argento","con chi collabora selgorm","alleati di selgorm"}}},fp="19,262,22.426.0,25.334.1,27.124.0,39.131.0,52.196.0,40.257.0"}
P.entries["npc:dawnwatcher-shaedlass"] = {n="Miraurora Shaedlass",s="Da Darnassus, Miraurora Shaedlass veglia su Kalimdor per conto dell'Alba d'Argento. Sulla Terrazza degli Artigiani, cerca notizie dei membri dell'ordine inviati in ricognizione in terre ostili.",h="Da Darnassus, Miraurora Shaedlass veglia su Kalimdor per conto dell'Alba d'Argento.",kw={"alba d'argento","abissi di fondocupo","terrazza degli artigiani","darnassus","miraurora","shaedlass","thaelrid"},ang={["faction:Alliance"]="Agli eroi dell'Alleanza a Darnassus, Shaedlass apre una via verso i misteri degli Abissi di Fondocupo e invia esploratori a recuperare un agente oltre le linee nemiche.",["race:NightElf"]="In quanto Elfo della Notte apertamente al servizio dell'Alba d'Argento, Shaedlass collega la politica isolazionista di Teldrassil alla vigilanza dell'ordine contro l'oscurità nel mondo."},sec={{t="Occhi dell'Alba d'Argento",b="L'Alba d'Argento combatte il Flagello nelle Terre Infette Orientali, ma vigila anche oltre Lordaeron. Da Darnassus, Miraurora Shaedlass segue gli interessi dell'ordine in tutta Kalimdor. Dalla sua postazione sulla Terrazza degli Artigiani, segue le spedizioni segrete contro culti oscuri e poteri corruttori che minacciano il resto del mondo."},{t="Un fratello scomparso",b="Argent Guard Thaelrid è scomparso dopo essersi recato a sud per indagare sulle attività di culto negli Abissi di Fondocupo, lungo la costa di Valtetra. Shaedlass teme che il Martello del Crepuscolo o gli orrori acquatici dell'antico tempio elfico possano aver fatto del male al suo compagno. Fa appello ad audaci avventurieri dell'Alleanza perché entrino nelle rovine e scoprano che cosa sia accaduto all'esploratore."}},faq={{q="Chi è Miraurora Shaedlass?",a="Miraurora Shaedlass serve l'Alba d'Argento dalla Terrazza degli Artigiani di Darnassus. Tiene i contatti tra l'ordine e le sue operazioni nel nord di Kalimdor.",al={"chi è shaedlass","storia di miraurora shaedlass","png alba d'argento darnassus"}},{q="Perché un membro dell'Alba d'Argento si trova a Darnassus?",a="L'Alba d'Argento combatte il Flagello a Lordaeron e vigila su Azeroth contro le forze corruttrici del male. A Kalimdor, Shaedlass tiene d'occhio minacce come i culti oscuri.",al={"perché l'alba d'argento è a darnassus","elfo della notte alba d'argento"}},{q="Cosa chiede di fare Shaedlass agli avventurieri?",a="Shaedlass invia gli avventurieri dell'Alleanza nel tempio sommerso degli Abissi di Fondocupo per trovare Argent Guard Thaelrid. Thaelrid si è infiltrato per indagare sul Martello del Crepuscolo e da allora non ha più dato notizie.",al={"missione di shaedlass","missione in search of thaelrid"}},{q="Dove posso trovare Miraurora Shaedlass?",a="Miraurora Shaedlass si trova sulla Terrazza degli Artigiani di Darnassus, vicino ai mercanti e agli artigiani della capitale.",al={"posizione di shaedlass","dove si trova miraurora shaedlass"}}},fx={["87de680c"]={q="Da che parte sta Miraurora Shaedlass?",a="Miraurora Shaedlass serve l'Alba d'Argento, una coalizione neutrale dedita a combattere il male ovunque minacci Azeroth. Sebbene sia un Elfo della Notte che vive nella capitale Darnassus, la sua lealtà principale va all'Alba e non esclusivamente all'Alleanza, permettendogli di concentrarsi su pericoli più ampi come i cultisti e il Flagello.",al={"fazione di shaedlass","chi serve shaedlass","shaedlass è dell'alleanza"}},e7a15b6d={q="A chi fa capo Miraurora Shaedlass?",a="Shaedlass risponde direttamente all'Alba d'Argento. È particolarmente preoccupato per il destino del suo compagno d'ordine, Argent Guard Thaelrid, inviato a indagare sulla vile corruzione che sta mettendo radici negli Abissi di Fondocupo, lungo la costa di Valtetra.",al={"legami di shaedlass","con chi collabora shaedlass","legami di shaedlass con l'alba d'argento"}}},fp="21,174,23.322.0,17.339.1,29.148.0,42.161.0,42.200.0,39.113.0"}
P.entries["npc:dazalar"] = {n="Dazalar",s="A Dolanaar, Dazalar prepara i giovani cacciatori Elfi della Notte alle terre selvagge di Teldrassil. Insegna loro a mantenere salda la mira e a stringere legami con le bestie dei grandi rami.",h="A Dolanaar, Dazalar prepara i giovani cacciatori Elfi della Notte alle terre selvagge di Teldrassil.",kw={"dazalar","dolanaar","cacciatore","elfo della notte","taming the beast","teldrassil","the hunter's path","istruttore"},ang={["class:Hunter"]="Se sei un cacciatore, Dazalar ti guida nelle tue prime prove di dominio delle bestie e nella cura di un compagno animale.",["race:NightElf"]="Come Elfo della Notte, apprendi le tradizioni dei Kaldorei legate alle sentinelle e agli esploratori, e come vivere in equilibrio con i feroci predatori della natura."},sec={{t="L'accampamento di Dolanaar",b="Dopo aver lasciato Vallombra, i giovani cacciatori si addestrano con Dazalar a Dolanaar. I ranger e le sentinelle degli Elfi della Notte pattugliano le terre selvagge, così lui insegna la pazienza e la disciplina necessarie a proteggere il fragile ecosistema di Teldrassil."},{t="Legare con la natura selvaggia",b="Dazalar insegna ai cacciatori ad addomesticare le bestie e a prendersene cura. I Kaldorei cercano un patto con i predatori della foresta, come le sciabole della notte, i gufi e gli strigidi cacciatori. I loro compagni imparano a combattere al loro fianco attraverso il rispetto, non la forza."}},faq={{q="Chi è Dazalar?",a="Dazalar addestra i cacciatori Elfi della Notte a Dolanaar. Insegna loro le tecniche di combattimento e come addomesticare le bestie selvatiche.",al={"chi è dazalar","storia di dazalar","identità di dazalar"}},{q="Dove posso trovare Dazalar?",a="Puoi trovare Dazalar all'aperto a Dolanaar, il centro principale di Teldrassil, poco dopo aver lasciato Vallombra.",al={"posizione di dazalar","dove si trova dazalar","istruttore dei cacciatori di dolanaar"}},{q="Quale addestramento fornisce Dazalar?",a="Dazalar insegna gli attacchi a distanza, l'uso delle trappole e le tecniche di sopravvivenza. Guida i cacciatori alle prime armi attraverso prove per padroneggiare l'arte di addomesticare gli animali selvatici.",al={"cosa insegna dazalar","abilità di dazalar","addestramento cacciatori dazalar"}},{q="Dazalar offre missioni speciali?",a="Sì. Dazalar offre un addestramento per cacciatori che comprende The Hunter's Path, la prova in più fasi Taming the Beast e Training the Beast. Queste prove insegnano ai giovani cacciatori a stringere legami con i compagni animali e a prendersene cura.",al={"missioni di dazalar","missioni dei cacciatori dolanaar","missione taming the beast"}},{q="Perché gli elfi della notte fanno così tanto affidamento sui cacciatori?",a="Gli Elfi della Notte vivono in armonia con le antiche foreste di Kalimdor da millenni. Arcieri ed esploratori costituiscono la spina dorsale dell'esercito delle sentinelle. Usano la furtività, la precisione nel tiro e gli alleati animali per proteggere le loro terre senza turbare la natura.",al={"storia dei cacciatori elfi della notte","perché le sentinelle usano i cacciatori","cacciatori kaldorei"}},{q="Che tipo di bestie invia ad addomesticare Dazalar ai cacciatori?",a="Dazalar manda i cacciatori a cercare le bestie originarie di Teldrassil, tra cui i ragni locali, le sciabole della notte e i rapaci. Le prove mettono alla prova la loro capacità di avvicinare e calmare i predatori selvatici.",al={"quali bestie addomesticare","prova di addomesticamento di dolanaar","addomesticare bestie teldrassil"}}},fx={["0fd37214"]={q="Da che parte sta Dazalar?",a="Dazalar è leale agli Elfi della Notte di Darnassus e serve l'Alleanza. Di stanza a Dolanaar, dedica la sua arte a guidare i giovani cacciatori Kaldorei nella comunione con la natura di Teldrassil, assicurandosi che sappiano difendere il loro popolo e preservare l'equilibrio della loro nuova dimora boschiva.",al={"fazione di dazalar","dazalar è dell'alleanza","chi serve dazalar"}},["5be2ad1d"]={q="Cosa vuole Dazalar?",a="Dazalar mira ad addestrare gli aspiranti cacciatori nelle discipline fondamentali del seguire le tracce, del tiro di precisione e della sopravvivenza nelle terre selvagge. Oltre alle normali abilità di combattimento, vuole assicurarsi che ogni cacciatore Kaldorei padroneggi l'arte di legarsi alle diverse creature native dei rami di Teldrassil, domarle e addestrarle.",al={"qual è l'obiettivo di dazalar","scopo di dazalar","perché dazalar addestra i cacciatori"}},["6e364749"]={q="Perché Dazalar è qui?",a="Dazalar vive a Dolanaar perché l'insediamento è il primo grande rifugio che i giovani Elfi della Notte visitano dopo aver lasciato Vallombra. Trovandosi proprio lungo i sentieri della foresta, può istruire le reclute tra esploratori, sentinelle e ranger prima che si avventurino nelle zone più selvagge di Teldrassil.",al={"perché dazalar è a dolanaar","ruolo di dazalar a teldrassil","motivo della presenza di dazalar"}}},fp="7,146,23.218.0,21.219.0,15.99.0,25.102.0,35.136.0,38.202.0,46.239.0,54.179.0"}
P.entries["npc:deathguard-bartholomew"] = {n="Guardiamorte Bartholomew",s="A Brill, il Guardiamorte Bartholomew veglia sulla cittadina e aiuta i viaggiatori a orientarsi. Contribuisce a mantenere l'ordine tra i difensori Reietti delle Radure di Tirisfal.",h="A Brill, il Guardiamorte Bartholomew veglia sulla cittadina e aiuta i viaggiatori a orientarsi.",kw={"bartholomew","brill","guardiamorte","reietti","guardia","tirisfal"},ang={["faction:Horde"]="Se arrivi da Kalimdor come alleato, puoi chiedere a Bartholomew indicazioni per orientarti tra le strade di Brill avvolte nella nebbia.",["race:Undead"]="Come Reietto appena liberato proveniente da Albamorta, incontri per la prima volta l'esercito permanente di Dama Sylvanas attraverso guardie come Bartholomew a Brill."},sec={{t="Sentinella di Brill",b="Il Guardiamorte Bartholomew monta la guardia a Brill tra le guardie dei Reietti che difendono le Radure di Tirisfal. Proteggono le terre riconquistate dalle forze residue del Flagello, dai fanatici Crociati Scarlatti e da altre minacce al dominio di Dama Sylvanas. Bartholomew guida anche i viaggiatori per la cittadina e contribuisce a mantenere l'ordine tra i risorti di recente."}},faq={{q="Chi è il Guardiamorte Bartholomew?",a="Il Guardiamorte Bartholomew sorveglia Brill, nelle Radure di Tirisfal. Veglia sulla cittadina e guida i viaggiatori verso i luoghi che cercano.",al={"bartholomew","chi è bartholomew","storia della guardiamorte bartholomew"}},{q="Qual è il ruolo delle Guardiamorte?",a="I Guardiamorte costituiscono la principale forza di fanteria e di difesa dei Reietti. Pattugliano Lordaeron, difendono insediamenti come Brill dal Flagello e dalla Crociata Scarlatta e mantengono l'ordine per la Dark Lady.",al={"cosa sono le guardiamorte","fazione delle guardiamorte","guardie dei reietti"}},{q="Il Guardiamorte Bartholomew può dare indicazioni?",a="Sì. Il Guardiamorte Bartholomew fornisce ai viaggiatori indicazioni per raggiungere vari luoghi di Brill, tra cui gli istruttori, la locanda e i mercanti di professioni.",al={"dov'è la locanda","indicazioni per brill","indicazioni della guardia a brill"}}},fx={["73481549"]={q="Da che parte sta Guardiamorte Bartholomew?",a="Guardiamorte Bartholomew serve i Reietti e la Signora Oscura, la regina Sylvanas Ventolesto. Come parte delle forze militari che difendono le Radure di Tirisfal, è leale all'Orda e protegge la cittadina di Brill dal Flagello, dalla Crociata Scarlatta e dagli intrusi dell'Alleanza che sconfinano.",al={"fazione di bartholomew","lealtà di bartholomew","chi serve bartholomew"}},d578d9b4={q="Perché Guardiamorte Bartholomew è qui?",a="Bartholomew è di stanza a Brill come parte della guarnigione locale. Dopo la riconquista delle rovine della cittadina da parte dei Reietti, è rimasto di guardia per mettere in sicurezza l'insediamento, mantenere l'ordine militare e guidare viaggiatori e non morti appena risvegliati che si avventurano nelle Radure di Tirisfal.",al={"perché bartholomew è a brill","dovere di bartholomew","cosa fa qui bartholomew"}},["750c03a9"]={q="Cosa vuole Guardiamorte Bartholomew?",a="Il dovere principale di Bartholomew è mantenere Brill sicura e ordinata per i Reietti. Oltre a sorvegliare la cittadina e dare indicazioni ai viaggiatori in arrivo, si affida ad avventurieri capaci perché lo aiutino ad affrontare le minacce locali e a svolgere compiti militari che garantiscano la fortificazione dell'insediamento.",al={"obiettivi di bartholomew","di cosa ha bisogno bartholomew","motivazione di bartholomew"}},["5978a3f3"]={q="A chi fa capo Guardiamorte Bartholomew?",a="Bartholomew è un soldato giurato dei Guardiamorte, l'esercito permanente e la forza di difesa cittadina dei Reietti. Risponde ai capi locali dei Reietti di stanza a Brill e, in ultima istanza, serve la Città Sotterranea e lady Sylvanas Ventolesto insieme agli altri sentinelle.",al={"alleati di bartholomew","legami di bartholomew","a chi risponde bartholomew"}}},fp="22,159,17.317.0,30.134.0,35.190.0,43.118.0"}
P.entries["npc:deathguard-burgess"] = {n="Guardiamorte Burgess",s="A Brill, il Guardiamorte Burgess veglia sulla cittadina per conto dei Reietti. Sorveglia l'insediamento e indica ai viaggiatori i servizi di cui hanno bisogno.",h="A Brill, il Guardiamorte Burgess veglia sulla cittadina per conto dei Reietti.",kw={"brill","burgess","guardiamorte burgess","reietti","guardia","radure di tirisfal"},ang={["faction:Horde"]="Come alleato dell'Orda in visita da Kalimdor, puoi chiedere a Burgess indicazioni su Brill quando ti servono provviste o un posto per riposare alla locanda.",["race:Undead"]="Come Reietto appena risvegliato che lascia Albamorta, puoi iniziare a orientarti a Lordaeron grazie a guardie come Burgess a Brill."},sec={{t="Un guardiano a Brill",b="A nord di Sepulcra, il Guardiamorte Burgess difende Brill dal Flagello e dalla Crociata Scarlatta. Come gli altri Guardiamorte delle Radure di Tirisfal, indica ai Reietti in arrivo dove trovare artigiani, istruttori di classe e servizi cittadini. La sua vigilanza contribuisce a mantenere attivo questo vulnerabile avamposto."}},faq={{q="Chi è il Guardiamorte Burgess?",a="Il Guardiamorte Burgess sorveglia Brill per conto dei Reietti. Contribuisce a mantenere l'ordine e indica ai visitatori gli istruttori locali e i punti di interesse.",al={"burgess brill","chi è burgess","storia del guardiamorte burgess"}},{q="Quale ruolo svolgono i Guardiamorte a Brill?",a="A Brill, i Guardiamorte proteggono i Reietti dal Flagello e dalla Crociata Scarlatta. Mantengono anche l'ordine pubblico.",al={"cosa sono i guardiamorte","ruolo dei guardiamorte"}},{q="Il Guardiamorte Burgess può fornire indicazioni?",a="Sì. Burgess può indicarti dove trovare istruttori di classe, la locanda locale, maestri delle professioni e altri servizi essenziali a Brill.",al={"indicazioni di burgess","dove andare a brill"}}},fx={ff001a75={q="Da che parte sta Guardiamorte Burgess?",a="Guardiamorte Burgess serve lady Sylvanas Ventolesto e i Reietti, parte del regno nascente con sede nella Città Sotterranea. Di sentinella a Brill, difende la cittadina dalle persistenti minacce del Flagello, dai crociati ostili della Crociata Scarlatta e da chiunque osi minacciare il regno appena conquistato della Signora Oscura.",al={"fazione di burgess","chi serve guardiamorte burgess","burgess è un reietto"}},e5a62f54={q="Cosa vuole Guardiamorte Burgess?",a="Burgess vuole ordine, vigilanza e sicurezza per l'insediamento di Brill. Come membro della guardia cittadina, il suo dovere è sorvegliare le strade, impedire alle minacce ostili di superare i confini dell'insediamento e assicurarsi che i Reietti appena risorti e i visitatori si orientino nelle Radure di Tirisfal.",al={"qual è l'obiettivo di burgess","scopo di burgess","cosa fa guardiamorte burgess"}},a4fa6528={q="Perché Guardiamorte Burgess è qui?",a="Burgess è di stanza a Brill perché è un insediamento cruciale a nord delle rovine della Città Capitale e della Città Sotterranea. Sorvegliare i sentieri che attraversano le Radure di Tirisfal garantisce la sicurezza degli interessi dei Reietti contro i fanatici della Crociata Scarlatta, i non morti senza senno che vagano per le terre selvagge e le bestie che avanzano.",al={"perché burgess è a brill","luogo in cui si trova guardiamorte burgess","perché guardiamorte burgess è di stanza qui"}}},fp="18,141,19.272.0,26.132.0,44.112.0,42.125.0"}
P.entries["npc:deathguard-dillinger"] = {n="Guardiamorte Dillinger",s="Ai margini di Brill, il Guardiamorte Dillinger sorveglia la cittadina e guida i Reietti appena arrivati. Invia le reclute a scacciare i resti del Flagello dalle fattorie e dai mulini vicini.",h="Ai margini di Brill, il Guardiamorte Dillinger sorveglia la cittadina e guida i Reietti appena arrivati.",kw={"a putrid task","brill","guardiamorte","guardiamorte dillinger","dillinger","the mills overrun","radure di tirisfal","ulag the cleaver"},ang={["class:Warrior"]="Come aspirante guerriero dei Reietti, potresti collaborare con Dillinger contro i ghoul e gli orrori scheletrici che si aggirano alla periferia di Brill.",["faction:Horde"]="Come alleato dell'Orda, assisti alla lotta dei Reietti per assicurarsi una posizione stabile nel nord di Lordaeron e alla minaccia del Flagello privo di senno che incombe su Brill.",["race:Undead"]="Come Reietto appena liberato in arrivo da Albamorta, potresti incontrare in Dillinger la tua prima autorità militare. Ti indirizza verso l'addestramento e i tuoi primi incarichi al servizio di Sylvanas."},sec={{t="Sentinella di Brill",b="Il Guardiamorte Dillinger protegge Brill e guida chi arriva da Albamorta. All'ingresso della cittadina, indirizza i non morti appena risvegliati verso la locanda, il Municipio e gli istruttori locali. Sotto il dominio della Dama Oscura, devono imparare a orientarsi in una vita ormai cambiata."},{t="Mettere in sicurezza le Terre di Confine",b="Il Guardiamorte Dillinger invia le reclute capaci a eliminare i servitori del Flagello privi di senno dalle fattorie e dai mulini vicini. Abbattono ghoul putrescenti e riconquistano le strutture infestate. Così facendo, rendono più sicuri i confini di Brill e aiutano i nascenti insediamenti dei Reietti a resistere alla minaccia dei non morti."},{t="Contenere orrori senza cervello",b="Ulag la Mannaia giace sigillato in un mausoleo a nord di Brill. Quando il Flagello dilagò per Tirisfal, i Reietti catturarono Ulag, un agente del Flagello dalla mente libera che rimaneva asservito al Re dei Lich. Ogni tentativo di spezzare quel controllo fallì. Così Dillinger invia un guerriero di comprovato valore a rimuovere il sigillo e distruggere Ulag."}},faq={{q="Dove posso trovare il Guardiamorte Dillinger?",a="Il Guardiamorte Dillinger sorveglia il sentiero che conduce a Brill, alla periferia della cittadina, nella parte centrale delle Radure di Tirisfal.",al={"posizione di dillinger","dove si trova dillinger","coordinate guardiamorte dillinger"}},{q="Qual è il ruolo della Guardiamorte?",a="La Guardiamorte è l'esercito permanente e la forza di polizia dei Reietti. Protegge insediamenti come Brill e Sepulcra dal Flagello, dalla Crociata Scarlatta e dalle altre minacce della regione.",al={"cos'è la guardiamorte","chi sono i guardiamorte","scopo della guardiamorte"}},{q="Quali compiti affida il Guardiamorte Dillinger?",a="Dillinger invia le reclute a uccidere i servitori del Flagello privi di senno nei campi e nei mulini circostanti, recuperare le infrastrutture locali e affrontare gravi minacce come Ulag la Mannaia.",al={"missioni di dillinger","quali missioni offre dillinger"}},{q="Il Guardiamorte Dillinger può fornire indicazioni?",a="Sì. Dillinger può indicarti i servizi essenziali, gli istruttori delle professioni e i maestri di classe in tutta Brill.",al={"indicazioni di dillinger","chiedere aiuto a dillinger"}},{q="Perché i Reietti combattono altri non morti vicino a Brill?",a="I non morti privi di senno di Tirisfal rimangono sotto il controllo del Flagello e del Re dei Lich. I Reietti si sono liberati da quel controllo e devono distruggere questi resti selvaggi per proteggere il proprio territorio.",al={"perché combattere il flagello","non morti contro non morti","ghoul di brill"}},{q="Chi è Ulag la Mannaia?",a="Ulag la Mannaia è un pericoloso orrore del Flagello legato alle tombe vicino a Brill. Dillinger invia le reclute dei Reietti a evocare e distruggere Ulag, mantenendo sicura l'area circostante.",al={"missione di ulag","chi è ulag","ulag the cleaver"}}},fx={["9ba09071"]={q="Chi è Guardiamorte Dillinger?",a="Guardiamorte Dillinger è un soldato Reietto di stanza a difesa dell'insediamento di Brill, nelle Radure di Tirisfal. Come il resto dei Guardiamorte, un tempo era un umano di Lordaeron, caduto vittima della piaga della non morte prima di liberarsi dalla ferrea volontà del Re dei Lich sotto la regina Sylvanas Ventolesto. Ora veglia in prima linea per difendere i Reietti appena risvegliati e proteggere il regno dal Flagello senza senno che si aggira ai confini.",al={"chi è dillinger","storia di guardiamorte dillinger","identità di dillinger"}},e6386dfb={q="Da che parte sta Guardiamorte Dillinger?",a="Dillinger è fieramente leale ai Reietti e alla Regina Banshee, lady Sylvanas Ventolesto. Come guardiano giurato del perimetro esterno della Città Sotterranea, serve l'Orda tenendo testa ai resti del Flagello e a chiunque minacci la sovranità, conquistata a fatica, dei non morti liberi di Lordaeron.",al={"fazione di dillinger","chi serve dillinger","lealtà di dillinger"}},["7c69f447"]={q="Perché Guardiamorte Dillinger è qui?",a="Dillinger è di stanza fuori da Brill per mantenere l'ordine, svolgere il servizio di sentinella e dare indicazioni ai Reietti appena arrivati dalle cripte di Albamorta. Le Radure di Tirisfal pullulano di non morti senza senno, bestie selvagge e intrusi ostili, perciò Guardiamorte esperti come lui sono dislocati agli incroci della cittadina per organizzare le difese e arruolare viaggiatori capaci affinché eliminino le minacce vicine.",al={"perché dillinger è a brill","cosa fa qui dillinger","luogo di servizio di dillinger"}},fe023b9f={q="Cosa vuole Guardiamorte Dillinger?",a="Dillinger vuole liberare le terre intorno a Brill dal Flagello senza senno e dalle mostruosità pericolose. Arruola i nuovi Reietti più promettenti per ridurre il numero dei ghoul in putrefazione che infestano le campagne vicine e debellare le minacce indisciplinate, così che Brill resti una roccaforte sicura per la nazione in espansione della regina Sylvanas.",al={"cosa vuole dillinger","obiettivi di dillinger","scopo di dillinger"}},["394a16a5"]={q="A chi fa capo Guardiamorte Dillinger?",a="Dillinger fa capo direttamente ai Guardiamorte, l'esercito permanente incaricato di proteggere gli insediamenti dei Reietti. Risponde ai comandanti di Brill e ai magistrati della Città Sotterranea, facendo da intermediario in prima linea tra le autorità locali, come il Magistrato Sevren, e gli avventurieri in arrivo che possono eseguire gli ordini militari dei Reietti.",al={"legami di dillinger","a chi risponde dillinger","comando di dillinger"}}},fp="20,161,17.255.0,24.270.0,27.315.1,38.106.0,35.185.0,43.169.0,44.109.0,54.191.0,24.169.0"}
P.entries["npc:deathguard-humbert"] = {n="Guardiamorte Humbert",s="A Mulino di Tarren, il Guardiamorte Humbert sorveglia l'Alleanza in tutta Colletorto. I nani di Dun Garok gli hanno sottratto l'equipaggiamento militare.",h="A Mulino di Tarren, il Guardiamorte Humbert sorveglia l'Alleanza in tutta Colletorto.",kw={"guardiamorte humbert","dun garok","alture di colletorto","humbert","spada di humbert","stormpike","mulino di tarren"},ang={["faction:Horde"]="Recuperare la Spada di Humbert significa colpire il presidio nanico a Colletorto e contribuire a preservare la dignità della guarnigione di Mulino di Tarren.",["race:Undead"]="I soldati Reietti sono tenuti a servire la Dark Lady con vigilanza incrollabile. La disattenzione di Humbert nei confronti dei vivi getta una macchia imbarazzante sui Deathguard."},sec={{t="Una guardia privata del suo acciaio",b="Da un accampamento nascosto, il Guardiamorte Humbert sorveglia Dun Garok per conto della Gran Esecutrice Darthalia. Una mattina si è allontanato per raccogliere legna da ardere. Durante la sua assenza, alcuni esploratori nani di Dun Garok gli hanno sottratto la preziosa spada e altro equipaggiamento. Ora deve recuperare le sue armi e salvare il proprio orgoglio prima che l'alto comando scopra l'accaduto."}},faq={{q="Chi è il Guardiamorte Humbert?",a="A Mulino di Tarren, il Guardiamorte Humbert svolge compiti di guardia e ricognizione. Sorveglia le operazioni dell'Alleanza in tutte le Alture di Colletorto.",al={"storia di humbert","chi è humbert","humbert mulino di tarren"}},{q="Cosa è successo alla spada e all'armatura di Humbert?",a="La Gran Esecutrice Darthalia ha inviato Humbert a sorvegliare Dun Garok da un accampamento nascosto. Una mattina è andato a raccogliere legna da ardere. Al suo ritorno, gli esploratori nani di Dun Garok gli avevano sottratto l'equipaggiamento, compresa la sua preziosa spada.",al={"spada di humbert rubata","chi ha preso l'equipaggiamento di humbert","perché humbert ha bisogno di aiuto"}},{q="Perché Humbert non recupera da solo il suo equipaggiamento?",a="Dun Garok è ben fortificata, con fucilieri e montanari nani disciplinati. Un esploratore solitario fuori dalle sue trincee ha ben poche possibilità. Humbert non può lasciare facilmente il suo posto senza dover rendere conto di come ha perso l'equipaggiamento.",al={"perché humbert non può combattere","humbert dun garok"}}},fx={f61ba0a7={q="Che cosa vuole Guardiamorte Humbert?",a="Humbert vuole recuperare il suo equipaggiamento militare personale, in particolare la sua spada. Gli esploratori nani di Dun Garok gliel'hanno sottratta mentre lui era lontano dal suo accampamento segreto a raccogliere legna da ardere, lasciandolo senza nulla e disperato di trovare qualcuno capace di avventurarsi in territorio nemico per riprenderla.",al={"obiettivo di humbert","di cosa ha bisogno humbert","perché humbert assegna missioni"}},ed7fd663={q="Perché Guardiamorte Humbert è di stanza qui?",a="Humbert è di stanza al Mulino di Tarren per sorvegliare la presenza ostile dell'Alleanza nelle Alture di Colletorto, tenendo d'occhio in particolare le forze naniche asserragliate a Dun Garok. Il suo posto garantisce che l'insediamento dei Reietti sia sempre allertato sui movimenti provenienti da sud.",al={"perché humbert è al mulino di tarren","missione di humbert","che cosa fa humbert qui"}},["9e6e6cc1"]={q="Da che parte sta Guardiamorte Humbert?",a="Guardiamorte Humbert serve i Reietti e, di conseguenza, l'Orda. Come membro dei Guardiamorte, è una sentinella e un soldato giurato alla difesa di Lordaeron e alla volontà della Regina Banshee, lady Sylvanas Ventolesto.",al={"fazione di guardiamorte humbert","lealtà di humbert","chi serve humbert"}}},fp="18,126,29.308.0,26.116.0,43.212.0,50.216.0"}
P.entries["npc:deathguard-linnea"] = {n="Guardiamorte Linnea",s="Da una postazione lungo la strada nel Tirisfal sudorientale, la Guardiamorte Linnea sorveglia le vie tra Brill e i confini orientali. La sua unità vigila sulla Crociata Scarlatta e sul Flagello ancora presenti nelle terre selvagge. A volte i viaggiatori si uniscono alle loro pattuglie.",h="Da una postazione lungo la strada nel Tirisfal sudorientale, la Guardiamorte Linnea sorveglia le vie tra...",kw={"brill","guardiamorte linnea","reietti","magistrato sevren","rear guard patrol","radure di tirisfal"},ang={["faction:Horde"]="Come alleato dei Reietti in viaggio nelle Radure di Tirisfal, puoi aiutare Linnea a proteggere le strade periferiche dalle forze ostili.",["race:Undead"]="Come Reietto appena risorto proveniente da Albamorta, puoi aiutare Linnea a presidiare la stazione di posta e a proteggere i confini del tuo regno."},sec={{t="Una vigilia sul ciglio della strada",b="A sudest di Brill, la Guardiamorte Linnea presidia una postazione fortificata. I Reietti difendono il loro giovane regno dagli infiltrati della Crociata Scarlatta e dal Flagello che ancora si aggira nelle terre selvagge. Linnea e i suoi compagni di guardia pattugliano la strada e condividono i rapporti con il Magistrato Sevren a Brill. La loro vigilanza mantiene sicura la strada orientale verso la Granbarricata."}},faq={{q="Chi è la Guardiamorte Linnea?",a="Linnea presta servizio nelle Guardiemorte, la forza dei Reietti che difende il loro territorio. Presidia una stazione di posta a sudest di Brill, nelle Radure di Tirisfal.",al={"linnea","storia di guardiamorte linnea","chi è linnea"}},{q="Perché ha bisogno di aiuto nel pattugliamento?",a="Le forze dei Reietti sono disperse nelle Radure di Tirisfal e faticano a presidiarle. Linnea conta sui viaggiatori e sui campioni emergenti per eliminare le minacce vicine, mantenendo sicura la strada per messaggeri e corrieri di rifornimenti diretti a Brill o di ritorno da lì.",al={"storia di rear guard patrol","perché aiutare linnea"}}},fp="17,240,23.335.0,25.144.0,34.212.0"}
P.entries["npc:deathguard-samsa"] = {n="Guardiamorte Samsa",s="A Mulino di Tarren, il Guardiamorte Samsa sorveglia la frontiera e invia i viaggiatori contro le minacce vicine.",h="A Mulino di Tarren, il Guardiamorte Samsa sorveglia la frontiera e invia i viaggiatori contro le minacce...",kw={"guardiamorte samsa","reietti","colletorto","samsa","souvenirs of death","mulino di tarren"},ang={["faction:Horde"]="Come viaggiatore dell'Orda nelle Alture di Colletorto, ti affidi a sentinelle come Samsa per coordinare le difese contro le vicine incursioni dell'Alleanza da Riva del Sud.",["race:Undead"]="Come membro dei Reietti, conosci la difesa spietata e pragmatica necessaria per mantenere il confine meridionale di Lordaeron contro i vicini ostili."},sec={{t="Sentinella della Frontiera di Mulino di Tarren",b="Il Guardiamorte Samsa protegge Mulino di Tarren, dove i Reietti mantengono le loro posizioni nelle contese Alture di Colletorto. Le sentinelle dell'Orda subiscono la pressione degli avamposti dell'Alleanza come Riva del Sud e della feroce fauna locale. Samsa sorveglia il perimetro e indirizza abili avventurieri contro i pericoli prima che raggiungano l'insediamento."}},faq={{q="Chi è il Guardiamorte Samsa?",a="Il Guardiamorte Samsa presta servizio nell'esercito dei Reietti a Mulino di Tarren. Protegge la cittadina e invia gli avventurieri di passaggio ad aiutare a mettere la regione al sicuro dai pericoli vicini.",al={"samsa","chi è samsa","ruolo di guardiamorte samsa"}},{q="Dove posso trovare il Guardiamorte Samsa?",a="Trovi il Guardiamorte Samsa a Mulino di Tarren, il principale insediamento dell'Orda nelle Alture di Colletorto settentrionali.",al={"posizione di samsa","dove si trova guardiamorte samsa","posizione guardia mulino di tarren"}},{q="Quali compiti assegna il Guardiamorte Samsa?",a="Samsa invia gli avventurieri nelle terre selvagge di Colletorto. Uno degli incarichi consiste nel raccogliere i teschi degli umani di Colletorto uccisi durante la campagna dell'Orda contro di loro.",al={"missioni di samsa","chi assegna souvenirs of death"}}},fx={["97a7e196"]={q="Da che parte sta Guardiamorte Samsa?",a="Guardiamorte Samsa serve i Reietti e l'Orda. In qualità di guardiamorte di stanza al Mulino di Tarren, agisce sotto l'autorità della regina Sylvanas Ventolesto, sorvegliando i possedimenti dei Reietti nelle Alture di Colletorto e proteggendo la regione dalle minacce vicine.",al={"fazione di guardiamorte samsa","samsa fa parte dell'orda","chi serve samsa"}},fc9d92c7={q="Perché Guardiamorte Samsa è qui, al Mulino di Tarren?",a="Guardiamorte Samsa è di stanza al Mulino di Tarren come parte della presenza militare dei Reietti che protegge l'insediamento. Il Mulino di Tarren è un bastione settentrionale fondamentale nelle Alture di Colletorto e ha bisogno di guardie risolute che sorveglino la città e controllino la fauna pericolosa e i movimenti nemici nelle terre circostanti.",al={"perché samsa è al mulino di tarren","scopo di guardiamorte samsa a colletorto","perché guardiamorte samsa è qui"}}},fp="16,97,30.324.0,24.161.0,34.101.0,42.156.0"}
P.entries["npc:deathguard-simmer"] = {n="Guardiamorte Simmer",s="Ai margini di Albamorta, il Guardiamorte Simmer mette alla prova i Reietti appena risorti. Li manda a ovest a razziare un campo di zucche degli umani pattugliato dalla Crociata Scarlatta per procurare i reagenti necessari agli speziali di Brill.",h="Ai margini di Albamorta, il Guardiamorte Simmer mette alla prova i Reietti appena risorti.",kw={"guardiamorte","guardiamorte simmer","albamorta","radure di tirisfal"},ang={["race:Undead"]="Come non morto, affronti per la prima volta la Crociata Scarlatta nelle missioni di Simmer. Ti manda oltre le cripte di Albamorta a difendere Lordaeron."},sec={{t="Guardiano fuori da Albamorta",b="Il Guardiamorte Simmer presidia il territorio fuori da Albamorta, dove i Reietti difendono il confine tra il loro rifugio e le Radure di Tirisfal. Gli umani viventi si aggirano ancora nella regione. Tra loro ci sono i fanatici della Crociata Scarlatta, che considerano tutti i non morti abomini da epurare con il fuoco e la lama.\n\nSimmer mette alla prova i Reietti appena risorti mandandoli a ovest, alla Cascina dei Solliden. I soldati della Crociata Scarlatta pattugliano la zona da una torre vicina. Le reclute devono rubare dieci zucche e portarle allo Speziale Johaan a Brill."}},faq={{q="Chi è il Guardiamorte Simmer?",a="Il Guardiamorte Simmer presidia il territorio appena fuori da Albamorta, nelle Radure di Tirisfal. Mette alla prova i Reietti appena risorti mandandoli a rubare zucche in una fattoria degli umani pattugliata dalla Crociata Scarlatta.",al={"guardiamorte simmer","chi è simmer","png simmer"}},{q="Dove si trova il Guardiamorte Simmer?",a="Il Guardiamorte Simmer vigila appena fuori da Albamorta, nella parte sudoccidentale delle Radure di Tirisfal. Si trova accanto alla strada che i Reietti appena risorti percorrono uscendo dalle cripte.",al={"posizione guardiamorte simmer","dove si trova simmer","trova guardiamorte simmer"}},{q="Quali minacce combatte il Guardiamorte Simmer?",a="Il Guardiamorte Simmer disprezza gli umani viventi che ancora coltivano le terre di Tirisfal e la Crociata Scarlatta che pattuglia la zona vicina. Manda i Reietti appena risorti a razziare la Cascina dei Solliden in cerca di zucche, dando una lezione a quegli umani e rifornendo gli speziali di Brill.",al={"nemici di simmer","cosa combatte simmer","missioni palizzata scarlatta"}}},fx={["6ef429fd"]={q="Da che parte sta Guardiamorte Simmer?",a="Guardiamorte Simmer serve i Reietti e la Dama Oscura, la regina Sylvanas Ventolesto. Membro giurato della Guardia della Morte, la forza militare permanente di Sepulcra, è dedito a difendere il territorio dei Reietti e a stroncare ogni minaccia al loro neonato regno.",al={"fazione di simmer","chi serve simmer","lealtà di guardiamorte simmer"}},["2af4e555"]={q="Perché Guardiamorte Simmer è qui?",a="Guardiamorte Simmer è di stanza appena fuori da Albamorta e sorveglia la strada che i Reietti appena risorti percorrono per raggiungere le Radure di Tirisfal. Poiché gli umani viventi continuano a coltivare i campi vicini e la Crociata Scarlatta pattuglia dalla sua torre a ovest, mette alla prova i Reietti alle prime armi mandandoli a razziare la Cascina dei Solliden.",al={"perché guardiamorte simmer è qui","tenuta calston di simmer","perché simmer è di stanza qui"}},["08301829"]={q="Che cosa vuole Guardiamorte Simmer?",a="Simmer vuole che i Reietti alle prime armi dimostrino il loro valore alla Dama Oscura. Li manda a rubare zucche dalla fattoria umana a ovest, pattugliata dalla Crociata Scarlatta, per dare una lezione ai vivi e procurare al contempo reagenti indispensabili allo Speziale Johaan a Brill.",al={"di cosa ha bisogno guardiamorte simmer","obiettivi di simmer","che cosa vuole che tu faccia simmer"}},["1e4cdda8"]={q="A chi è legato Guardiamorte Simmer?",a="Simmer appartiene alla Guardia della Morte, i soldati che difendono le terre dei Reietti nelle Radure di Tirisfal. Collabora con lo Speziale Johaan a Brill, mandandogli i Reietti alle prime armi con le zucche rubate alla vicina fattoria umana.",al={"legami di simmer","a chi fa rapporto simmer","legami di guardiamorte simmer"}}},fp="17,197,27.492.0,25.195.0,35.155.0,42.256.0"}
P.entries["npc:deathstalker-faerleia"] = {n="Inseguitrice della Morte Faerleia",s="A Rovonero, l'Inseguitrice della Morte Faerleia agisce contro i capi che lo governano. Dal Municipio, dirige attacchi segreti contro il Consiglio di Rovonero, i burattini che Arugal usa per governare il villaggio.",h="A Rovonero, l'Inseguitrice della Morte Faerleia agisce contro i capi che lo governano.",kw={"imboscata","consiglio","inseguitrice della morte","faerleia","reietti","rovonero","selva pinargento"},ang={["class:Rogue"]="Come Ladro al servizio dei Reietti, puoi prendere esempio dall'abilità di Faerleia sul campo. Si infiltra inosservata nella sede del potere nemico e orchestra imboscate.",["race:Undead"]="Come Non Morto, puoi vedere come Faerleia usa l'infiltrazione e il freddo calcolo per annientare i nemici della Dark Lady senza mobilitare un intero esercito."},sec={{t="Dietro le linee nemiche",b="L'Inseguitrice della Morte Faerleia opera dai piani superiori del Municipio di Rovonero. È al servizio dei Deathstalkers, il ramo segreto di spionaggio e assassinio di Sepulcra, e si è infiltrata nell'isolata enclave umana nella Selva Pinargento meridionale.\n\nIl villaggio nasconde oscuri segreti, tra cui una maledizione che trasforma i suoi abitanti sotto il cielo notturno. Dall'interno dell'insediamento, Faerleia coordina operazioni per destabilizzarlo e chiede agli agenti dell'Orda di eliminare i membri influenti del Consiglio di Rovonero."}},faq={{q="Chi è l'Inseguitrice della Morte Faerleia?",a="Faerleia presta servizio nei Deathstalkers, la divisione di spionaggio e operazioni furtive della regina Sylvanas Ventolesto. Si è infiltrata a Rovonero per condurre una guerra segreta contro i suoi capi.",al={"faerleia","chi è faerleia","inseguitrice della morte faerleia"}},{q="Dove si trova l'Inseguitrice della Morte Faerleia?",a="Faerleia si trova all'interno del Municipio di Rovonero, nella Selva Pinargento meridionale, poco a nord del Muro dei Mantogrigio.",al={"dove si trova faerleia","posizione di faerleia","trovare faerleia"}},{q="Quale missione assegna?",a="Faerleia guida gli avventurieri nella Pyrewood Ambush, un'operazione per assassinare i consiglieri che governano Rovonero e indebolire la resistenza dell'enclave ai Reietti.",al={"missione di faerleia","missione pyrewood ambush"}},{q="Perché i Deathstalkers hanno preso di mira Rovonero?",a="Arugal usa i membri del Consiglio di Rovonero come burattini per tenere sotto controllo gli abitanti maledetti del villaggio. Faerleia crede che, se il consiglio morirà, i figli di Arugal si rivolteranno contro il loro padrone, aiutando i Reietti a conquistare il villaggio e a scacciare Arugal dal Forte di Zannascura.",al={"perché attaccare rovonero","deathstalkers a rovonero"}}},fx={["72e51f96"]={q="Da che parte sta l'Inseguitrice della Morte Faerleia?",a="Faerleia è un'agente degli Inseguitori della Morte, l'ordine di spionaggio e assassinio al servizio di Sylvanas Ventolesto e dei Reietti. La sua lealtà va a Sepulcra e all'Orda, e contribuisce a consolidarne il controllo sulla Selva Pinargento contro le enclavi ostili.",al={"fazione di faerleia","chi serve faerleia","lealtà di faerleia"}},["7830562d"]={q="Che cosa vuole l'Inseguitrice della Morte Faerleia?",a="Vuole distruggere i capi di Rovonero. Nel cuore del territorio nemico, Faerleia coordina un'imboscata contro il Consiglio di Rovonero per spezzare la resistenza organizzata del villaggio ed eliminare la minaccia locale.",al={"che cosa vuole faerleia","obiettivo di faerleia","scopo di faerleia"}},fcf28179={q="Perché l'Inseguitrice della Morte Faerleia si trova a Rovonero?",a="Faerleia è riuscita a superare i difensori di Rovonero e a raggiungere il Municipio stesso. Appostata proprio nel centro del potere, attende il momento di sferrare un colpo decisivo contro i capi del villaggio, all'interno delle loro stesse mura.",al={"perché faerleia è qui","perché faerleia è a rovonero","municipio di faerleia nella selva pinargento"}},e3ddcd8c={q="A chi è legata l'Inseguitrice della Morte Faerleia?",a="Faerleia risponde agli Inseguitori della Morte dei Reietti e, lungo la catena di comando, alla regina Sylvanas Ventolesto. Sul campo fa affidamento su fidati esploratori dell'Orda e su avventurieri abbastanza audaci da infiltrarsi nell'insediamento maledetto e aiutarla a tendere l'imboscata.",al={"legami di faerleia","contatti di faerleia","con chi collabora faerleia"}}},fp="21,205,18.514.1,29.185.0,41.123.0,27.178.0,53.260.0"}
P.entries["npc:deathstalker-lesh"] = {n="Inseguitrice della Morte Lesh",s="Alla Rocca Meridionale, l'Inseguitrice della Morte Lesh studia le fattorie umane nelle Alture di Colletorto. Serve la Gran Esecutrice Darthalia e valuta quando i Reietti debbano colpire.",h="Alla Rocca Meridionale, l'Inseguitrice della Morte Lesh studia le fattorie umane nelle Alture di Colletorto.",kw={"inseguitrice della morte lesh","gran esecutrice darthalia","campi di colletorto","alture di colletorto","rocca meridionale","mulino di tarren","time to strike"},ang={["class:Rogue"]="Come ladro, partecipi alle operazioni segrete che l'Inseguitrice della Morte Lesh svolge per sostenere lo sforzo bellico dell'Orda.",["race:Undead"]="Per te che sei un Reietto, gli esploratori come Lesh contribuiscono a proteggere Lordaeron dalle forze dell'Alleanza che tornano all'offensiva."},sec={{t="Occhi sui Campi",b="Dalla Rocca Meridionale, l'Inseguitrice della Morte Lesh sorveglia i contadini umani e la milizia cittadina nei vicini Campi di Colletorto. La torre sorge lungo la strada meridionale che attraversa le Alture di Colletorto. Lesh appartiene ai Deathstalkers, la rete segreta di esploratori, spie e assassini dei Reietti.\n\nTiene sotto controllo i movimenti e il numero dei nemici per la Gran Esecutrice Darthalia a Mulino di Tarren. Quando il momento è propizio, Lesh invia a Darthalia un messaggio in codice: “Il grido del corvo da occidente ci chiama.” Queste parole segnalano che Colletorto è pronta per l'attacco dei Reietti."}},faq={{q="Chi è l'Inseguitrice della Morte Lesh?",a="Lesh è un'esploratrice dei Reietti alla Rocca Meridionale. Risponde alla Gran Esecutrice Darthalia a Mulino di Tarren e sorveglia le attività umane nei Campi di Colletorto.",al={"inseguitrice della morte lesh","chi è lesh","lesh colletorto"}},{q="Cosa sono i The Deathstalkers?",a="I Deathstalkers servono la regina Sylvanas Ventolesto come esploratori, spie e assassini. Raccolgono informazioni per l'esercito dei Reietti ed eliminano bersagli di grande valore strategico in tutta Lordaeron.",al={"cosa sono i the deathstalkers","ordine dei the deathstalkers","ladri reietti"}},{q="Qual è il ruolo di Lesh alla Rocca Meridionale?",a="Lesh sorveglia i Campi di Colletorto e la cittadina di Colletorto dalla Rocca Meridionale. Quando il momento è propizio, manda un viaggiatore dalla Gran Esecutrice Darthalia a Mulino di Tarren con un messaggio in codice che segnala che Colletorto è pronta per l'attacco.",al={"esploratrice rocca meridionale","missione di lesh","perché lesh si trova qui"}},{q="A chi risponde Lesh?",a="Lesh fa rapporto alla Gran Esecutrice Darthalia, la comandante dei Reietti a Mulino di Tarren. Darthalia sovrintende all'offensiva contro le forze umane a Colletorto.",al={"superiore di lesh","chi comanda lesh","gran esecutrice darthalia"}}},fx={["5ae1cd6e"]={q="Da che parte sta l'Inseguitrice della Morte Lesh?",a="L'Inseguitrice della Morte Lesh è fedele a Sylvanas Ventolesto e ai Reietti e opera come parte delle forze dell'Orda nelle Alture di Colletorto. Di stanza alla Rocca Meridionale come esploratrice, agli ordini del Mulino di Tarren, lavora instancabilmente per assicurare la supremazia dei Reietti nella regione.",al={"fazione dell'inseguitrice della morte lesh","lesh è dell'alleanza o dell'orda","chi serve lesh"}},["024a29bd"]={q="Che cosa vuole l'Inseguitrice della Morte Lesh?",a="Lesh vuole vedere le Alture di Colletorto cadere in mano ai Reietti. Di stanza in prima linea come esploratrice, tiene sotto osservazione la città umana e, al momento giusto, le serve un messaggero veloce che porti il suo segnale cifrato alla Gran Esecutrice Darthalia al Mulino di Tarren, così da dare inizio all'attacco.",al={"che cosa vuole lesh","obiettivo di lesh","scopo dell'inseguitrice della morte lesh"}}},fp="17,165,18.546.0,25.155.0,27.184.0,40.235.0,24.151.0"}
P.entries["npc:deathstalker-rane-yorick"] = {n="Rane Yorick",s="In una fattoria della Selva Pinargento, Rane Yorick e suo fratello Quinn non riescono a raggiungere Mausolea. Inviati a perlustrare le fattorie settentrionali, devono far giungere il loro rapporto al Gran Esecutore Hadrec.",h="In una fattoria della Selva Pinargento, Rane Yorick e suo fratello Quinn non riescono a raggiungere Mausolea.",kw={"deathstalker","erland","reietti","podere di ivar","rane","rogue","esploratore","selva pinargento","yorick"},ang={["class:Rogue"]="Come ladro dei Reietti, vedi il pericoloso lavoro sul campo dei Deathstalkers negli sforzi di Rane Yorick per raccogliere informazioni sotto la pressione nemica.",["faction:Horde"]="Come membro dell'Orda, benefici del lavoro di spionaggio di Rane, che aiuta a mantenere le vie di rifornimento dell'Orda nella Selva Pinargento libere da worgen e imboscate locali.",["race:Undead"]="Come campione dei Reietti, incontri Rane nel suo ruolo di esploratrice che protegge la frontiera della Selva Pinargento da mani ostili."},sec={{t="Occhi nei boschi",b="Dama Sylvanas Ventolesto si affida ai Deathstalkers per sorvegliare tutta Lordaeron. Sono i suoi occhi e le sue orecchie e colpiscono quando il dominio dei Reietti è minacciato. Rane Yorick e suo fratello Quinn sono stati inviati a perlustrare la Selva Pinargento settentrionale. Minacce ferine li hanno accerchiati e la loro missione segreta si è trasformata in una lotta per la sopravvivenza."},{t="Intrappolata al Podere di Ivar",b="Al Podere di Ivar, Rane Yorick si rifugia in una fattoria in rovina con suo fratello Quinn, gravemente dilaniato. I worg si aggirano per i campi che li separano da Mausolea. Eppure Rane resta fedele al suo incarico. Chiede ai viaggiatori dell'Orda di passaggio di raccogliere cuori di worg per una pozione curativa, uccidere Ivar the Foul e recapitare il suo rapporto al comando."}},faq={{q="Chi è Deathstalker Rane Yorick?",a="Rane Yorick presta servizio nei Deathstalkers, l'ordine di ladri dei Reietti che raccoglie informazioni e uccide in segreto. È di stanza in una fattoria in rovina al Podere di Ivar, nella Selva Pinargento.",al={"chi è rane yorick","storia di rane yorick","chi è deathstalker yorick"}},{q="Cosa sono i Deathstalkers?",a="I Deathstalkers sono la gilda segreta di ladri dei Reietti, agli ordini di Dama Sylvanas Ventolesto. Perlustrano, spiano e compiono omicidi mirati in tutta Lordaeron.",al={"cosa sono i deathstalkers","fazione dei deathstalkers","chi sono i deathstalkers"}},{q="Perché è intrappolata in un casolare?",a="Rane e suo fratello Quinn sono stati inviati a perlustrare le fattorie della Selva Pinargento settentrionale. Al Podere di Ivar, il ghoul Ivar the Foul li ha attaccati e ha gravemente dilaniato Quinn. Hanno trovato riparo in una fattoria mentre lui si riprende.",al={"perché rane è intrappolata","casolare del podere di ivar","perché si nasconde"}},{q="Chi è suo fratello?",a="Quinn Yorick è il fratello di Rane e un compagno Deathstalker impegnato nella stessa missione di ricognizione. Ivar the Foul lo ha gravemente dilaniato al Podere di Ivar.",al={"fratello di rane yorick","chi è erland","inseguitore della morte erland"}},{q="Quali minacce stanno monitorando nella Selva Pinargento?",a="Rane e Quinn sono stati inviati a perlustrare le fattorie della Selva Pinargento settentrionale in cerca di minacce al dominio dei Reietti. Hanno trovato più membri del Flagello del previsto, oltre a worg in agguato e al ghoul Ivar the Foul.",al={"cosa stanno esplorando","cosa sta indagando rane"}},{q="A chi riferisce le sue scoperte?",a="Rane riferisce le sue scoperte al Gran Esecutore Hadrec a Mausolea. Hadrec sovrintende all'occupazione della Selva Pinargento da parte dei Reietti.",al={"dove vanno i rapporti","chi è il superiore di rane"}}},fx={bafbf2b7={q="Da che parte sta l'Inseguitrice della Morte Rane Yorick?",a="L'Inseguitrice della Morte Rane Yorick è pienamente fedele ai Reietti e alla Dama Oscura. Membro degli Inseguitori della Morte, l'ordine segreto dei Reietti dedito allo spionaggio e all'assassinio, svolge pericolose missioni di ricognizione in tutta Lordaeron per proteggere il loro regno nascente dai nemici in agguato.",al={"fazione di rane yorick","chi serve rane yorick","rane yorick è una reietta"}},a4a724f9={q="Che cosa vuole l'Inseguitrice della Morte Rane Yorick?",a="Rane vuole completare la sua missione di ricognizione e assicurarsi che i risultati raggiungano il comando dei Reietti. Lei e la sua compagna sono messe alle strette e in difficoltà nella Selva Pinargento; hanno un disperato bisogno di alleati affidabili che le aiutino, neutralizzino i pericoli vicini e trasmettano le loro informazioni al sicuro.",al={"di cosa ha bisogno rane yorick","motivazione di rane yorick","perché rane yorick chiede aiuto"}}},fp="11,177,17.321.0,21.325.1,32.194.0,27.162.0,34.216.0,19.136.0,45.185.0,35.129.0"}
P.entries["npc:deathstalker-vincent"] = {n="Inseguitore della Morte Vincent",s="Nel Forte di Zannascura, Arugal ha ucciso l'Inseguitore della Morte Vincent. L'esploratore dei Reietti era entrato con l'Inseguitore della Morte Adamant per studiare le difese del forte prima che i Reietti potessero attaccare.",h="Nel Forte di Zannascura, Arugal ha ucciso l'Inseguitore della Morte Vincent.",kw={"arugal","inseguitore della morte adamant","inseguitore della morte vincent","forte di zannascura","selva pinargento","vincent","worgen"},ang={["class:Rogue"]="Per un ladro, l'esecuzione di Vincent mostra il pericolo che corrono gli agenti furtivi quando si infiltrano da soli nelle roccaforti nemiche.",["faction:Horde"]="Se fai parte dell'Orda, trovare Vincent conferma i timori dei comandanti dei Reietti a Silverpine. La squadra di ricognizione ha fallito, e il forte deve essere ripulito con la forza."},sec={{t="La fine fatale di un esploratore",b="I Deathstalkers dovevano conoscere la disposizione del Forte di Zannascura prima che i Reietti potessero assaltarlo. Vincent e Adamant superarono furtivamente le barricate ed entrarono nella fortezza. La loro missione fallì. Adamant fu catturato e rinchiuso in una cella delle segrete, mentre Vincent fu portato al cospetto del signore del forte. Vincent si rifiutò di servire Arugal o di sottomettersi a lui. Il mago lo giustiziò, lasciandone il corpo sul pavimento di pietra."},{t="La sfida di Arugal",b="Arugal usò la morte di Vincent per sfidare gli intrusi nel suo forte. Davanti all'esploratore prigioniero, il mago pazzo derise i Reietti e paragonò la loro intrusione ai tentativi falliti dei suoi ex compagni del Kirin Tor. Arugal pretese la lama e i segreti di Vincent per i propri scopi. Vincent rifiutò. Arugal lo abbatté e dichiarò che i suoi resti sarebbero stati un monito per chiunque avesse violato il suo dominio."}},faq={{q="Chi era l'Inseguitore della Morte Vincent?",a="Vincent era un esploratore dei Reietti nei Deathstalkers, il servizio segreto dei Reietti. Lui e l'Inseguitore della Morte Adamant entrarono nel Forte di Zannascura per raccogliere informazioni prima dell'assalto pianificato.",al={"chi è vincent","vincent forte di zannascura","ladro morto zannascura"}},{q="Cosa è successo a Vincent nel Forte di Zannascura?",a="Arugal catturò Vincent durante la ricognizione e lo giustiziò dopo che Vincent si rifiutò di servirlo o di rivelare segreti. Arugal lasciò il corpo di Vincent dove era caduto.",al={"come è morto vincent","perché vincent è morto","chi ha ucciso vincent"}},{q="Dov'è il suo compagno, l'Inseguitore della Morte Adamant?",a="L'Inseguitore della Morte Adamant fu catturato vivo e rinchiuso in una vicina cella delle segrete, sorvegliato da una guardia worgen.",al={"dove si trova adamant","altro inseguitore della morte","posizione di adamant"}},{q="Perché i Deathstalkers sono stati inviati al Forte di Zannascura?",a="La Selva Pinargento è un territorio vitale per Sylvanas e i Reietti, mentre i worgen di Arugal controllano il Forte di Zannascura. Vincent e Adamant furono inviati a studiare la disposizione e le difese della fortezza affinché i Reietti potessero sferrare un attacco efficace.",al={"perché i deathstalker sono a zannascura","missione reietti zannascura"}}},fx={ebb4e7c7={q="Da che parte sta l'Inseguitore della Morte Vincent?",a="Vincent è un agente degli Inseguitori della Morte, l'élite dell'ordine di spionaggio e assassinio al servizio di Sylvanas Ventolesto e dei Reietti. Agisce per conto di Sepulcra, esplorando le roccaforti nemiche ed eliminando le minacce al loro regno nascente.",al={"fazione di vincent","chi serve vincent","lealtà di vincent"}},["1f4e2f05"]={q="Che cosa vuole l'Inseguitore della Morte Vincent?",a="Vincent cercava di raccogliere informazioni di ricognizione essenziali all'interno del Forte di Zannascura, per consentire ai Reietti di sferrare un assalto. Fiero fino alla fine, si è rifiutato di cedere alla richiesta dell'arcimago Arugal di tradire i suoi e giurare fedeltà ad Arugal e al suo misterioso padrone.",al={"che cosa cercava di fare vincent","obiettivo di vincent","scopo di vincent"}}},fp="20,180,19.408.0,17.391.1,29.188.0,44.165.0,43.103.0,51.238.0"}
P.entries["npc:deathwing"] = {n="Alamorte",s="L'ombra di Alamorte raggiunge ancora i luoghi più profondi di Azeroth. Un tempo Neltharion il Custode della Terra, era l'Aspetto Draconico dello stormo dei draghi neri prima che gli Antichi Dei lo conducessero alla follia. Si rivoltò contro gli altri Aspetti e portò fuoco e caos nel mondo. Sconfitto nei pressi di Grim Batol dopo la Seconda Guerra, è ritenuto morto o nascosto.",h="L'ombra di Alamorte raggiunge ancora i luoghi più profondi di Azeroth.",kw={"aspetto","stormo dei draghi neri","alamorte","anima del demone","distruttore","anima del drago","custode della terra","grim batol","neltharion","prestor"},ang={["faction:Alliance"]="I nobili dell'Alleanza rabbrividiscono ancora al pensiero di quanto Lord Daval Prestor sia andato vicino a impadronirsi della corona di Alterac e a rivolgere il Council of Seven Nations contro l'Alleanza dall'interno.",["faction:Horde"]="La Vecchia Orda strinse un patto scellerato con Alamorte durante la Seconda Guerra, usando il clan Fauce del Drago per procurarsi draghi rossi. La nuova Orda cerca di lasciarsi quella macchia alle spalle.",["race:NightElf"]="Come Elfo della Notte, sai che gli anziani Kaldorei ricordano l'improvviso e devastante tradimento di Neltharion diecimila anni fa durante la Guerra degli Antichi. Quell'atrocità spezzò la stirpe dei draghi e segnò il destino del loro antico impero."},sec={{t="La caduta di Neltharion",b="I titani concessero a Neltharion il dominio sulla terra e sulle cripte sotterranee di Azeroth. In quelle profondità, gli Antichi Dei imprigionati gli sussurravano. Durante l'antica Guerra degli Antichi, la loro follia prese il sopravvento. Neltharion ingannò gli altri Aspetti Draconici affinché infondessero parte della loro essenza in un disco dorato chiamato Anima del Drago. Disse che avrebbe fermato la Legione Infuocata, poi rivolse l'arma contro i suoi alleati e scatenò la devastazione."},{t="Il piano del lord umano",b="Dopo la Seconda Guerra, Alamorte tramò per abbattere i regni mortali dall'interno. Assumendo l'identità umana di Lord Daval Prestor, un nobile affascinante, conquistò il favore di Re Terenas Menethil II e dell'alto consiglio dell'Alleanza di Lordaeron.\n\nMirava a impadronirsi del trono vacante di Alterac. A Grim Batol, aiutò anche il clan Fauce del Drago a tenere schiava la Regina Alexstrasza e a raccoglierne le covate. Rhonin distrusse l'Anima del Demone e restituì agli altri Aspetti il potere rubato. Questi scacciarono Alamorte."},{t="La stirpe rimasta indietro",b="La maggior parte dei regni mortali crede che Alamorte sia stato distrutto o scacciato dal mondo per sempre. Lo stormo dei draghi neri rimane un flagello in tutta Azeroth, guidato dalla sua astuta progenie, tra cui sua figlia Onyxia e suo figlio Nefarian. I draghi neri manipolano la politica dei mortali e terrorizzano le terre dai loro covi montani. Le cicatrici dell'antico tradimento dell'Aspetto nero sono profonde. I viaggiatori che attraversano lande rocciose o scendono in profonde gallerie temono ancora che il Grande Drago possa risvegliarsi."}},faq={{q="Chi era originariamente Alamorte?",a="Alamorte era un tempo Neltharion il Custode della Terra, capo dello stormo dei draghi neri. I titani gli conferirono il potere di vegliare sulle terre e sulle montagne di Azeroth. Millenni fa, le profondità della terra lo esposero ai sussurri degli Antichi Dei, che ne corrodessero la sanità mentale.",al={"storia di neltharion","chi è neltharion","origine del custode della terra"}},{q="Cos'era l'Anima del Drago?",a="L'Anima del Drago era un manufatto dorato che Neltharion forgiò durante la Guerra degli Antichi. Ingannò gli altri quattro Aspetti affinché vi infondessero il loro potere, poi ne rivolse la forza apocalittica contro di loro e i difensori mortali. In seguito divenne nota come Anima del Demone.",al={"anima del demone","cos'è l'anima del drago","artefatto di neltharion"}},{q="Chi era Lord Daval Prestor?",a="Lord Daval Prestor era l'identità umana che Alamorte adottò dopo la Seconda Guerra. Usando magie di ammaliamento e inganni di corte, tentò di impadronirsi del trono di Alterac e manipolare l'Alleanza di Lordaeron dall'interno prima che il suo tradimento venisse alla luce.",al={"lord prestor","identità di daval prestor","storia di prestor"}},{q="Qual è il legame di Alamorte con Grim Batol?",a="A Grim Batol, Alamorte consegnò segretamente agli orchi Fauce del Drago l'Anima del Demone, mantenendo Alexstrasza, la regina dei draghi rossi, incatenata e costretta a riprodursi per la guerra. Rhonin in seguito distrusse il manufatto con una delle scaglie di Alamorte. Riacquistati i loro poteri, gli altri Aspetti combatterono Alamorte e lo scacciarono.",al={"alamorte grim batol","cosa è successo a grim batol"}},{q="Chi guida lo stormo dei draghi neri oggi?",a="Con Alamorte assente e presumibilmente morto, i suoi principali discendenti agiscono per conto proprio. Sua figlia Onyxia cova nella sua tana ad Acquemorte, mentre suo figlio Nefarian comanda i draghi neri e sperimenta con il sangue di drago in cima al Massiccio Roccianera.",al={"attuale capo dei draghi neri","chi guida i draghi neri","nefarian e onyxia"}}},fp="9,335,22.435.0,24.501.1,21.469.0,29.242.0,25.265.0,27.246.1,45.288.0,39.250.2"}
P.entries["npc:deino"] = {n="Deino",s="Nella Valle degli Spiriti di Orgrimmar, Deino guida i maghi dell'Orda nei loro studi. Insegna loro a padroneggiare le forze arcane ed elementali, poi invia gli incantatori esperti per Kalimdor a studiare antiche magie e cercare maestri lontani.",h="Nella Valle degli Spiriti di Orgrimmar, Deino guida i maghi dell'Orda nei loro studi.",kw={"deino","laughing sisters","istruttore dei maghi","orgrimmar","tabetha","mago troll","valle degli spiriti","waters of xavian","xavian"},ang={["class:Mage"]="Come mago, puoi apprendere incantesimi e la magia dei portali da Deino a Orgrimmar. Poi puoi studiare a Valtetra e ad Acquemorte.",["faction:Horde"]="Come membro dell'Orda, puoi trovare Deino nel quartiere spirituale di Orgrimmar. Lì addestra gli incantatori della fazione al fianco dei suoi sciamani e stregoni.",["race:Troll"]="Come troll, puoi vedere come i Puntascura uniscono lo studio della magia arcana alle tradizioni della Valle degli Spiriti."},sec={{t="L'arcanista della Valle",b="Deino addestra i maghi dell'Orda su piattaforme rialzate nella Valle degli Spiriti di Orgrimmar. Totem, capanne e acque tranquille circondano il luogo dove insegna. Gli incantatori troll onorano le tradizioni spirituali mentre imparano a padroneggiare l'arcano. Deino segue questo percorso al fianco degli altri istruttori, Enyo e Pephredo."},{t="Svelare misteri arcani",b="Deino invia i maghi promettenti oltre Durotar a studiare i misteri arcani. Nelle terre selvagge e corrotte di Valtetra, raccolgono le Waters of Xavian contaminate e capelli incantati delle Laughing Sisters. Quando l'abilità di un allievo supera ciò che Orgrimmar può insegnargli, Deino lo indirizza verso maestri lontani. Una di loro è Tabetha, una strega eremita nelle paludi di Acquemorte."}},faq={{q="Dove posso trovare Deino?",a="Deino si trova su piattaforme rialzate nella Valle degli Spiriti, nella parte sudoccidentale di Orgrimmar. Al suo fianco ci sono Enyo e Pephredo, anch'essi istruttori dei maghi troll.",al={"posizione di deino","dove si trova deino","deino orgrimmar"}},{q="Cosa insegna Deino?",a="Deino insegna incantesimi arcani, di fuoco e di gelo, la creazione di portali e i gradi essenziali degli incantesimi man mano che i maghi acquisiscono esperienza.",al={"istruttrice deino","quali incantesimi insegna deino"}},{q="Perché Deino invia i maghi a Xavian?",a="Xavian è un'antica città nella parte orientale di Valtetra, ora occupata dai satiri. Si dice che le sue acque racchiudano un grande potere magico. Deino vuole studiarne un campione prelevato ai piedi della cascata più alta.",al={"missione waters of xavian","perché xavian"}},{q="Chi sono gli istruttori che si trovano con Deino?",a="Enyo e Pephredo sono al fianco di Deino. I tre portano i nomi delle sorelle Graeae dell'antico mito e formano il principale circolo di maestri dei maghi troll di Orgrimmar.",al={"chi è enyo","pephredo","maghi troll nella valle degli spiriti"}},{q="Perché Deino invia i maghi ad Acquemorte?",a="Quando un mago diventa più abile, Deino lo invia da Tabetha, una potente eremita umana che vive isolata nel cuore di Acquemorte. Tabetha custodisce segreti arcani specialistici.",al={"deino tabetha","viaggio verso la palude"}},{q="I non troll possono addestrarsi con Deino?",a="Sì. I maghi dell'Orda di qualsiasi razza, compresi troll, orchi e Reietti, possono apprendere incantesimi di classe e ricevere la guida di Deino nella Valle degli Spiriti.",al={"gli orchi possono addestrarsi con deino","addestramento maghi dell'orda"}}},fx={["6ebd5023"]={q="Chi è Deino?",a="Deino è un'addestratrice di maghi troll Lanciascura che vive nella Valle degli Spiriti a Orgrimmar. Anche se lo studio delle arti arcane è raro tra i suoi simili, ha padroneggiato questa disciplina e collabora con gli altri addestratori per guidare i maghi dell'Orda alle prime armi nell'uso responsabile dei loro poteri.",al={"chi è deino","storia di deino","deino maga troll"}},c489d76d={q="Da che parte sta Deino?",a="Deino è fermamente leale alla tribù Lanciascura e all'Orda. Di stanza a Orgrimmar, mette la sua esperienza magica al servizio del potenziamento degli incantatori dell'Orda, affinché possano difendere meglio la loro nuova casa.",al={"lealtà di deino","fazione di deino","deino fa parte dell'orda"}},d9121d13={q="Cosa vuole Deino?",a="Deino vuole assicurarsi che i maghi dell'Orda siano adeguatamente disciplinati e pienamente preparati ai pericoli di Kalimdor. Manda gli incantatori più promettenti in giro per il mondo, alla ricerca di reagenti puri e conoscenze esoteriche presso studiosi lontani, così che possano affinare la propria arte e temprare le proprie capacità arcane.",al={"cosa vuole deino","obiettivo di deino","scopo di deino"}},c3103580={q="Perché Deino si trova a Orgrimmar?",a="Deino risiede nella Valle degli Spiriti per guidare i giovani incantatori troll e dell'Orda. Stabilitasi nel cuore dell'enclave dei Lanciascura a Orgrimmar, offre una fonte affidabile di insegnamenti arcani in una società altrimenti sciamanica e marziale.",al={"perché deino è a orgrimmar","deino nella valle degli spiriti","perché deino è qui"}}},fp="5,229,21.286.0,27.337.0,23.140.0,22.114.0,36.189.0,41.158.0,46.163.0,32.148.0"}
P.entries["npc:delgren-the-purifier"] = {n="Delgren the Purifier",s="All'Accampamento di Maestra, Delgren the Purifier aiuta gli elfi della notte a resistere alla magia demoniaca e alla Shadow Magic sul confine settentrionale di Valtetra. Monta la guardia con Balthule Ombrafuria e Feero Mandiferro.",h="All'Accampamento di Maestra, Delgren the Purifier aiuta gli elfi della notte a resistere alla magia demoniaca...",kw={"althalaxx","alba d'argento","valtetra","balthule ombrafuria","cult of the dark strand","delgren","delgren the purifier","feero mandiferro","accampamento di maestra","torre di althalaxx"},ang={["class:Paladin"]="Come paladino, puoi vedere come la Sacra Luce raggiunga Kalimdor. La crociata di Delgren contro i demoni e la magia oscura si spinge ben oltre i Regni Orientali.",["faction:Alliance"]="Per i viaggiatori dell'Alleanza diretti a sud da Rivafosca, Delgren e i suoi compagni offrono un presidio militare lungo la pericolosa strada di Valtetra.",["race:NightElf"]="Come elfo della notte, potresti diffidare delle fedi straniere. La compagnia di Delgren combatte i culti demoniaci che infestano le antiche rovine."},sec={{t="Un crociato sulla frontiera dei Kaldorei",b="Delgren the Purifier sorveglia la strada che da Auberdine conduce a sud. I paladini umani sono rari nelle antiche foreste di Kalimdor, eppure è giunto a ovest con i guerrieri sacri dell'Alba d'Argento. Sono partiti per aiutare i nuovi alleati elfi della notte dell'Alleanza ad affrontare i demoni e i non morti rimasti dalla Terza Guerra. Ora Delgren sorveglia il confine tra Rivafosca e Valtetra, dove il pericolo raggiunge la strada."},{t="Purificare il Dark Strand",b="Delgren e Balthule Ombrafuria affrontano il Cult of the Dark Strand nei pressi della Torre di Althalaxx, nella parte settentrionale di Rivafosca. I suoi riti oscuri minacciano la frontiera. Delgren invia gli avventurieri nel territorio del culto per abbattere i cultisti e distruggere i loro catalizzatori di evocazione. Li manda anche a caccia degli stregoni che trafficano con l'ombra demoniaca."},{t="Una mente non convenzionale",b="La devozione di Delgren alla Sacra Luce non gli ha impedito di studiare l'intricata politica di Kalimdor. Ha imparato l'orco, suscitando il fastidio e lo sdegno dei suoi superiori conservatori. La lingua lo aiuta a comprendere i nemici e i vicini che condividono questo continente selvaggio, al di là degli insegnamenti del suo ordine."}},faq={{q="Chi è Delgren the Purifier?",a="Delgren è un paladino umano al servizio dell'Alba d'Argento presso l'Accampamento di Maestra, nella parte settentrionale di Valtetra. Aiuta gli elfi della notte contro la corruzione demoniaca, i cultisti e le ombre lasciate dall'invasione della Legion.",al={"chi è delgren","delgren lore","chi è il paladino all'accampamento di maestra"}},{q="Dove posso trovare Delgren?",a="Delgren si trova all'Accampamento di Maestra, un piccolo avamposto degli elfi della notte nel nordovest di Valtetra, appena a sud del sentiero per Rivafosca.",al={"dove si trova delgren","posizione di delgren","coordinate di delgren"}},{q="Perché un paladino umano si trova fino a Valtetra?",a="Delgren ha viaggiato verso ovest con una compagnia di paladini dell'Alba d'Argento per aiutare gli alleati elfi della notte dell'Alleanza. Si adoperano per eliminare i demoni, i non morti rimasti e i culti oscuri che minacciano il nord di Kalimdor.",al={"perché delgren si trova a valtetra","perché ci sono umani a valtetra","missione di delgren"}},{q="Qual è il legame di Delgren con la Torre di Althalaxx?",a="Delgren e i suoi compagni sorvegliano le attività corrotte attorno alla Torre di Althalaxx, nella parte settentrionale di Rivafosca. Invia gli avventurieri a indagare sulle rovine, dare la caccia al Cult of the Dark Strand e porre fine alle sue oscure pratiche di evocazione.",al={"delgren althalaxx","missioni della torre di althalaxx","cult of the dark strand"}},{q="Perché Delgren ha imparato l'orco?",a="Delgren ha imparato l'orco per comprendere meglio Kalimdor e i suoi abitanti. I superiori del suo ordine hanno disapprovato questa scelta.",al={"delgren parla l'orco","lingua orchesca di delgren","delgren lingua orca"}},{q="Con chi lavora Delgren all'Accampamento di Maestra?",a="Delgren opera al fianco di Balthule Ombrafuria e Feero Mandiferro all'Accampamento di Maestra. Insieme sorvegliano le minacce al confine, gestiscono la logistica e combattono i cultisti dell'ombra lungo la frontiera di Valtetra.",al={"compagni di delgren","chi si trova all'accampamento di maestra"}}},fx={["616c1190"]={q="Da che parte sta Delgren the Purifier?",a="Delgren è un paladino umano schierato con l'Alba d'Argento e fedele all'Alleanza. Lui e i suoi compagni paladini hanno attraversato il mare appositamente per aiutare i loro alleati Elfi della Notte a purificare Kalimdor dai mali persistenti.",al={"fazione di delgren","delgren alleanza o orda","a chi presta servizio delgren"}},["30d7c847"]={q="Cosa vuole Delgren the Purifier?",a="Delgren vuole purificare le antiche terre di Valtetra e Rivafosca dalla contaminazione demoniaca e dalla corruzione dei non morti. Il suo obiettivo principale è smantellare il Culto della Riva Oscura e porre fine ai loro rituali oscuri intorno alla Torre di Althalaxx.",al={"obiettivo di delgren","cosa fa delgren","missione di delgren"}}},fp="20,186,35.371.0,23.335.1,18.299.0,28.201.0,25.128.0,52.190.0,55.226.0,29.108.0,45.198.0"}
P.entries["npc:demisette-cloyce"] = {n="Demisette Cloyce",s="Sotto lo Slaughtered Lamb di Roccavento, Demisette Cloyce addestra gli stregoni in segreto. Insegna agli allievi la magia vile e manda quelli pronti a imparare da altri evocatori.",h="Sotto lo Slaughtered Lamb di Roccavento, Demisette Cloyce addestra gli stregoni in segreto.",kw={"cloyce","demisette","quartiere dei maghi","menara squarciavuoto","slaughtered lamb","roccavento","istruttore dei negromanti"},ang={["class:Warlock"]="Da stregone a Roccavento, puoi imparare da Demisette i fondamenti dell'arte degli incantesimi. Ti guida verso la conquista di un destriero vile e il vincolo di sfere demoniache.",["race:Human"]="Da umano, puoi trovare Demisette nei sotterranei di Roccavento. Ha abbandonato la Sacra Luce per il potere demoniaco."},sec={{t="Le cripte del Slaughtered Lamb",b="Gli stregoni si riuniscono nella cantina sotto lo Slaughtered Lamb, nel Quartiere dei Maghi di Roccavento. Le autorità cittadine difendono l'ordine e la Sacra Luce, mentre Demisette Cloyce vive nelle catacombe sottostanti. Lì insegna a chi è disposto a studiare le arti proibite. Avverte che le energie oscure corrompono solo chi non ha la disciplina necessaria per dominarle."},{t="Collegare le congreghe",b="Quando gli stregoni acquisiscono sufficiente padronanza, Demisette li guida oltre Roccavento. Li mette in contatto con evocatori come Menara Squarciavuoto nelle Savane. Lì possono cercare potenti manufatti e imparare a vincolare formidabili destrieri vili."}},faq={{q="Chi è Demisette Cloyce?",a="Demisette Cloyce addestra gli stregoni sotto lo Slaughtered Lamb, nel Quartiere dei Maghi di Roccavento. Insegna l'evocazione demoniaca e gli incantesimi oscuri.",al={"chi è demisette","storia di demisette cloyce","chi è demisette cloyce"}},{q="Perché si nasconde nella cantina di una taverna?",a="Gli stregoni si riuniscono nella cantina sotto lo Slaughtered Lamb, lontano dagli sguardi della gente. È un luogo appartato dove possono dedicarsi alle loro pratiche oscure.",al={"perché si trova nella cantina","perché slaughtered lamb","seminterrato del slaughtered lamb"}},{q="Qual è il suo legame con le Savane?",a="Demisette manda gli stregoni esperti oltre il mare, da Menara Squarciavuoto a Porto Paranco, sulla costa delle Savane. Cercano rituali avanzati, potenti sfere e riti di vincolo.",al={"demisette savane","in search of menara voidrender","legame con menara squarciavuoto"}},{q="Come reagisce con chi non è un negromante?",a="Demisette disprezza gli estranei. Se non segui il cammino dello stregone, ti avverte che l'oscurità non ti accoglie. Poi ti ordina di smettere di parlare e andartene.",al={"dialogo di demisette","parlare con demisette"}}},fx={["9bf7bbcc"]={q="Da che parte sta Demisette Cloyce?",a="Demisette Cloyce è schierata con l'Alleanza e risiede al sicuro a Roccavento. Opera in segreto nelle catacombe sotto The Slaughtered Lamb insieme ad altri stregoni, ma la sua lealtà è rivolta all'istruzione e al potenziamento degli incantatori fedeli a Roccavento, non ai culti nemici o alle Lame Ardenti.",al={"fazione di demisette cloyce","demisette cloyce è dell'alleanza","a chi presta servizio demisette"}},["5142027a"]={q="Cosa vuole Demisette Cloyce?",a="Demisette vuole guidare gli stregoni promettenti nel padroneggiare la pericolosa magia vil senza soccombere alla corruzione. Indirizza gli incantatori verso antichi artefatti e potenti mentori in tutto il mondo, spingendosi persino fino a Kalimdor, convinta che solo discepoli dalla forte volontà possano padroneggiare efficacemente la stregoneria oscura senza andare incontro a una fine prematura e rovinosa.",al={"motivazione di demisette cloyce","obiettivo di demisette cloyce","cosa vuole demisette"}}},fp="16,166,34.342.0,21.235.0,24.137.0,37.139.0,38.175.0,35.171.0"}
P.entries["npc:denalan"] = {n="Denalan",s="Al Lago Al'ameth, Denalan studia le strane piante di Teldrassil e cerca un rimedio alla sua corruzione. Dal suo piccolo appezzamento in riva al lago, chiede ai giovani avventurieri di raccogliere campioni, esaminare i timberling e mettere alla prova il terreno incantato.",h="Al Lago Al'ameth, Denalan studia le strane piante di Teldrassil e cerca un rimedio alla sua corruzione.",kw={"blackmoss","botanica","denalan","erborista","kaldorei","lago al'ameth","oakenscowl","fioriera","teldrassil","timberling"},ang={["class:Druid"]="Come druido, potresti trovare una causa comune negli esperimenti di Denalan in riva al lago. Il suo lavoro aiuta il Circolo Cenariano a rintracciare ed eliminare la corruzione che si diffonde nelle radici di Teldrassil.",["profession:Herbalism"]="Come erborista, segui la tradizione kaldorei dello studio botanico. Raccogliere e coltivare piante selvatiche può rivelare mali più profondi nel mondo naturale.",["race:NightElf"]="Come Elfo della Notte, condividi i primi sforzi dei kaldorei per comprendere i difetti inattesi e le difficoltà di crescita della tua nuova patria, Teldrassil."},sec={{t="Un botanico al Lago Al'ameth",b="Sulla sponda orientale del Lago Al'ameth, Denalan studia le piante che hanno messo radici da quando Teldrassil è stato piantato. Sotto una tenda di stoffa, tiene a portata di mano attrezzi da campo e file di fioriere. Mentre molti kaldorei sorvegliano i pericoli o si dedicano agli alti riti druidici, Denalan dedica le sue giornate all'erboristeria. Ha scelto questo appezzamento al posto dei grandi tumuli di Darnassus per studiare l'insolita flora dell'Albero del Mondo."},{t="Indagare sulle imperfezioni di Teldrassil",b="Denalan indaga sull'agitazione della fauna autoctona di Teldrassil. I timberling, esseri boschivi di legno e germogli solitamente docili, sono diventati più aggressivi. Incanta il terreno per coltivare semi selvatici in cattività e studiare come la corruzione si insinua negli apparati radicali. Tra gli esemplari che esamina ci sono fronde scintillanti, Frutto Brillante e formazioni intrecciate di muschio. Cerca la corruzione che tormenta le fronde della foresta."}},faq={{q="Dove posso trovare Denalan?",a="Trovi Denalan sulla sponda orientale del Lago Al'ameth, nella parte meridionale di Teldrassil, a sud di Dolanaar. Il suo piccolo accampamento sorge vicino all'acqua, con una tenda e aiuole coltivate.",al={"posizione di denalan","dove si trova denalan","mappa di denalan"}},{q="Cosa sta ricercando Denalan nel suo accampamento?",a="Denalan studia le insolite piante di Teldrassil e il comportamento aggressivo degli spiriti boschivi locali. Coltiva semi di timberling in fioriere incantate ed esamina strani esemplari, cercando modi per purificare dalla corruzione l'ecosistema del nuovo Albero del Mondo.",al={"cosa fa denalan","scopo di denalan","perché denalan si trova al lago"}},{q="Perché i timberling attaccano le persone?",a="I timberling sono spiriti della natura simili a piante, originari delle fronde di Teldrassil. Solitamente pacifici, sono diventati violenti e imprevedibili mentre una corruzione innaturale si diffonde nel terreno e nelle radici dell'Albero del Mondo. Denalan ne studia i semi per comprendere il cambiamento.",al={"perché i timberling sono aggressivi","storia dei timberling","timberling corrotti"}},{q="A cosa servono le fioriere di Denalan?",a="Denalan usa aiuole appositamente preparate, riempite di terra incantata, per coltivare semi selvatici e strane talee. Lì può osservare come le piante della foresta reagiscono al terreno purificato, lontano dai contaminanti presenti in natura.",al={"fioriera di denalan","terra di denalan","fioriere di denalan"}},{q="Con chi collabora Denalan?",a="Denalan collabora con Rellian Greenspyre, un druido di Darnassus che condivide il suo interesse per i timberling. Anche un collega di Dolanaar gli invia della Terra Rara da Darnassus.",al={"alleati di denalan","a chi fa rapporto denalan"}},{q="Cos'è il Moss-twined Heart che Denalan esamina?",a="Il Moss-twined Heart è un nucleo vegetale corrotto recuperato da Blackmoss the Fetid, un timberling corrotto di Teldrassil. Denalan lo studia nel terreno incantato per comprendere la malattia innaturale che deforma la vita vegetale dell'isola.",al={"moss twined heart","missione moss-twined heart","cuore di blackmoss"}}},fx={["6481fcca"]={q="Chi è Denalan?",a="Denalan è un rinomato erborista e ricercatore Elfo della Notte che vive sulle rive del Lago Al'ameth. Noto per la sua profonda conoscenza della flora di Kalimdor, dedica la propria arte allo studio della vegetazione di Teldrassil e alla ricerca di rimedi naturali per i problemi ecologici che affliggono l'Albero del Mondo.",al={"chi è denalan","storia di denalan","informazioni su denalan"}},["6f0f42ae"]={q="Da che parte sta Denalan?",a="Denalan è fedele agli Elfi della Notte di Darnassus e alleato dell'Alleanza. Collabora apertamente con gli altri erboristi e druidi Kaldorei, aiutando tutti i viaggiatori che desiderano proteggere Teldrassil dalla corruzione e dai pericoli.",al={"fazione di denalan","denalan è dell'alleanza","a chi presta servizio denalan"}},["11aaa3f4"]={q="Cosa vuole Denalan?",a="Denalan vuole purificare Teldrassil dalla corruzione che si diffonde nel suo suolo e nella fauna selvatica. Raccoglie semi ed esemplari di piante rare nella foresta circostante e usa terra appositamente incantata per favorire una crescita sana e trovare un rimedio per i tronchetti impazziti.",al={"cosa vuole denalan","obiettivo di denalan","scopo di denalan"}},["38f45ee1"]={q="Perché Denalan si trova qui, al Lago Al'ameth?",a="Denalan ha allestito il suo accampamento presso il lago per studiare da vicino la vegetazione nativa di Teldrassil. Le rive offrono un laboratorio all'aperto ideale per le sue fioriere e la terra incantata, e lo collocano vicino all'epicentro della popolazione di tronchetti agitati che vuole comprendere.",al={"perché denalan è qui","perché denalan è al lago al'ameth","scopo dell'accampamento di denalan"}},["3bcd2be5"]={q="Perché Denalan è famoso?",a="Denalan è ampiamente rispettato come celebre erborista tra gli Elfi della Notte. Lo studio per tutta la vita della botanica di Kalimdor e la sua esperienza nella purificazione di semi e terreni contaminati gli hanno procurato la reputazione di una delle massime autorità del regno in materia di botanica.",al={"perché denalan è famoso","fama di denalan come erborista","denalan è conosciuto"}}},fp="7,221,27.392.0,36.404.0,25.168.0,44.258.0,41.253.0,42.212.0,27.165.0,52.232.0"}
P.entries["npc:dendrite-starblaze"] = {n="Dendrite Ardistella",s="A Nottequieta, Dendrite Ardistella guida i druidi che giungono a Radaluna. Come mentore del Circolo Cenariano, accoglie apprendisti elfi della notte e tauren. Tramite lui vengono convocati nel sacro boschetto per padroneggiarne i riti, dalla purificazione dalle tossine alla comunione con le forme della natura.",h="A Nottequieta, Dendrite Ardistella guida i druidi che giungono a Radaluna.",kw={"aquatic form","circolo cenariano","curing the sick","dendrite ardistella","druido","lessons anew","radaluna","elfo della notte","nottequieta"},ang={["class:Druid"]="Quando ti teletrasporti per la prima volta a Radaluna, Dendrite ti guida nella cura delle malattie e nella ricerca della comunione con le forme acquatiche.",["race:NightElf"]="Come iniziato Kaldorei, incontri Dendrite a Nottequieta, dove custodisce i riti tradizionali della tutela della natura e ti accoglie nell'ordine cenariano.",["race:Tauren"]="Come druido Shu'halo di Mulgore, puoi vedere in Dendrite come il legame del Circolo Cenariano vada oltre la faida tra Orda e Alleanza."},sec={{t="Una guida nel sacro rifugio",b="Quando i druidi novizi imparano Teleport: Radaluna, Dendrite è tra i primi ad accoglierli a Nottequieta. Segue la vocazione del Circolo Cenariano al di là dell'Alleanza e dell'Orda. I druidi elfi della notte e tauren trovano fratellanza sotto le fronde del rifugio, dove la tradizione Kaldorei incontra il cammino dei tauren."},{t="Prove della natura selvaggia",b="Dendrite guida gli apprendisti lungo i sentieri più profondi della natura. Li manda a esaminare acque contaminate e a cercare erbe capaci di curare avvelenamenti e pestilenze. Poi sovrintende alle prove acquatiche, mettendo alla prova la loro pazienza e resistenza sott'acqua prima di concedere loro la comunione con le forme acquatiche."}},faq={{q="Chi è Dendrite Ardistella?",a="Dendrite Ardistella è un druido elfo della notte e mentore del Circolo Cenariano a Nottequieta, a Radaluna. Guida i druidi in formazione attraverso riti e addestramenti fondamentali.",al={"dendrite ardistella","chi è dendrite","ardistella radaluna"}},{q="Perché un elfo della notte addestra i tauren dell'Orda?",a="Il Circolo Cenariano si mantiene al di fuori delle divisioni politiche tra Alleanza e Orda. A Radaluna, elfi della notte e tauren praticano insieme le arti druidiche sotto antichi giuramenti di fratellanza, lasciando i conflitti terreni oltre i passi montani.",al={"perché dendrite addestra l'orda","dendrite druido tauren","mentore druido tra fazioni"}},{q="Quali missioni offre Dendrite Ardistella?",a="Dendrite guida i druidi attraverso prove di cura di avvelenamenti e malattie, poi verso la comunione necessaria per la forma acquatica.",al={"missioni di dendrite","elenco missioni di ardistella"}},{q="Dove si trova Dendrite Ardistella?",a="Dendrite si trova a Nottequieta, sulle sponde settentrionali del Lago Elune'ara, a Radaluna.",al={"posizione di dendrite","dove si trova ardistella","mappa di dendrite ardistella"}},{q="Come raggiungono Dendrite per la prima volta i giovani druidi?",a="Gli istruttori delle rispettive razze insegnano ai druidi novizi Teleport: Radaluna intorno al decimo cerchio di addestramento. L'incantesimo li trasporta direttamente a Radaluna, dove Dendrite li attende.",al={"come raggiungere dendrite","missione teletrasporto a radaluna"}},{q="Gli avventurieri non druidi possono interagire con lui?",a="Anche chi non è druido può visitare Nottequieta e parlare con Dendrite. Non offre addestramento, prove o incarichi a chi è estraneo alle tradizioni druidiche del Circolo Cenariano.",al={"dendrite non druidi","un guerriero può parlare con ardistella"}}},fx={["3038adca"]={q="Cosa vuole Dendrite Ardistella?",a="Dendrite guida i druidi alle prime armi lungo il cammino della natura e dell'equilibrio. Attraverso prove che rendono omaggio agli spiriti della natura selvaggia, come entrare in comunione con il Great Bear Spirit e padroneggiare i poteri del veleno e delle acque, si assicura che tutti gli iniziati, qualunque sia la loro origine, apprendano le responsabilità e le antiche discipline del Circolo Cenariano.",al={"obiettivo di dendrite ardistella","cosa vuole dendrite","motivazione di dendrite ardistella"}},ef589fff={q="Perché Dendrite Ardistella si trova a Radaluna?",a="Radaluna è un luogo sacro e neutrale, dove il Circolo Cenariano si riunisce lontano dai conflitti tra le fazioni del mondo. Di stanza a Nottequieta, Dendrite accoglie e guida i druidi alle prime armi convocati al rifugio, impartendo loro le lezioni fondamentali e le prove essenziali per la loro crescita spirituale.",al={"perché dendrite è qui","dove si trova dendrite ardistella a radaluna","perché dendrite è a nottequieta"}},["7aee8496"]={q="A chi è legato Dendrite Ardistella?",a="Dendrite è un emissario e mentore del Circolo Cenariano. Collabora a stretto contatto con i druidi di stirpe sia Elfo della Notte sia tauren, rispondendo al richiamo degli spiriti della natura selvaggia e agli insegnamenti di Cenarius, anziché alle bandiere politiche di Darnassus o dell'Orda.",al={"fazione di dendrite ardistella","dendrite ardistella e il circolo cenariano","a chi presta servizio dendrite"}}},fp="18,270,27.297.0,18.290.0,26.165.0,40.236.0,42.119.0,38.91.0,54.163.0,44.154.0"}
P.entries["npc:deputy-feldon"] = {n="Vicesceriffo Feldon",s="Sulla strada a sud del Gran Ponte di Borgolago, il Vicesceriffo Feldon veglia inquieto mentre gli gnoll avanzano furtivi verso Borgolago.",h="Sulla strada a sud del Gran Ponte di Borgolago, il Vicesceriffo Feldon veglia inquieto mentre gli gnoll...",kw={"ponte","vicesceriffo feldon","feldon","gnoll","guardia","borgolago","crestarossa"},ang={["faction:Alliance"]="Come campione dell'Alleanza, puoi vedere quanto siano sotto pressione i territori periferici di Roccavento. Le guardie locali hanno bisogno dei campioni di passaggio per contribuire a mantenere la pace del re."},sec={{t="Una guardia sul filo del rasoio",b="Il Vicesceriffo Feldon sorveglia la strada a sud del ponte di Borgolago, una via essenziale per il commercio e gli spostamenti. Gli orchi Roccianera premono da nord mentre branchi di gnoll invadono le colline meridionali, mettendo a dura prova la guardia cittadina. Feldon non può abbandonare il suo posto senza indebolire il perimetro di Borgolago. Si affida agli avventurieri di passaggio per respingere gli gnoll prima che isolino la cittadina."}},faq={{q="Chi è il Vicesceriffo Feldon?",a="Il Vicesceriffo Feldon presta servizio nella guardia cittadina di Borgolago. È di stanza subito a sud del ponte, sulla principale strada meridionale delle Montagne Crestarossa.",al={"feldon","chi è feldon","ruolo vicesceriffo feldon"}},{q="Perché il Vicesceriffo Feldon è preoccupato per gli gnoll?",a="Sono stati avvistati accampamenti di gnoll lungo la strada verso la Foresta di Elwynn. Feldon teme che gli gnoll possano spingersi nelle terre degli umani, facendo sì che Borgolago non sia più l'unica cittadina sotto assedio. La guardia non è adeguatamente equipaggiata per affrontarli.",al={"perché gli gnomi","problema gnoll di feldon","encroaching gnolls"}},{q="Perché Feldon non affronta gli gnoll da solo?",a="La guardia di Borgolago è a corto di personale e affronta contemporaneamente orchi e gnoll. Feldon non può lasciare il suo posto al ponte senza lasciare incustodito l'ingresso della cittadina.",al={"perché feldon non combatte","dovere di feldon"}},{q="Dove si trova il Vicesceriffo Feldon?",a="Il Vicesceriffo Feldon sorveglia la strada subito a sud del Gran Ponte di Borgolago, presidiando gli accessi meridionali di Borgolago.",al={"posizione di feldon","dove si trova feldon"}}},fx={["1b9b43bf"]={q="Da che parte sta il Vicesceriffo Feldon?",a="Il Vicesceriffo Feldon è un leale tutore della legge dell'Alleanza e presta servizio nelle Montagne Crestarossa sotto l'autorità della guardia cittadina di Borgolago e del Magistrato Solomon. Protegge i cittadini del regno e mantiene sicure le strade che conducono alla città, tenendo a bada le minacce incombenti.",al={"fazione del vicesceriffo feldon","a chi presta servizio feldon","vicesceriffo feldon è dell'alleanza"}},dc2592f9={q="Perché il Vicesceriffo Feldon è di stanza vicino al ponte?",a="Il Vicesceriffo Feldon è di stanza appena a sud del ponte di Borgolago per sorvegliare gli accessi meridionali. Con i branchi di gnoll che si avvicinano pericolosamente alla città, tiene d'occhio la strada per mantenere aperti i passaggi e reclutare viaggiatori in grado di combattere, così da fermare l'invasione prima che il ponte venga sopraffatto.",al={"perché feldon è qui","perché il vicesceriffo feldon si trova qui","cosa fa qui feldon"}},["5e39d198"]={q="A chi è legato il Vicesceriffo Feldon?",a="Feldon risponde al Magistrato Solomon e alle forze locali di mantenimento della pace incaricate di proteggere Borgolago. Fa parte della ridotta guardia locale che difende le Montagne Crestarossa, in assenza di significativi rinforzi militari da Roccavento.",al={"legami del vicesceriffo feldon","a chi risponde feldon","vicesceriffo feldon sceriffo"}}},fp="13,118,15.375.0,21.133.0,42.219.0,48.151.0,33.121.0"}
P.entries["npc:deputy-rainer"] = {n="Vicesceriffo Rainer",s="Al Presidio Rivombroso, il Vicesceriffo Rainer difende il confine occidentale di Elwynn dalle minacce provenienti dalle Marche Occidentali. L'ufficiale dell'Esercito di Roccavento coordina la difesa locale, anche se i rinforzi non sono arrivati.",h="Al Presidio Rivombroso, il Vicesceriffo Rainer difende il confine occidentale di Elwynn dalle minacce...",kw={"vicesceriffo rainer","foresta di elwynn","gryan stoutmantle","boccalarga","maresciallo dughan","zampafiume","presidio rivombroso","marche occidentali"},ang={["faction:Alliance"]="Come eroe dell'Alleanza, vedi come i presidi periferici di Roccavento si adattano quando il regolare sostegno della corona non li raggiunge."},sec={{t="Difendere il confine occidentale",b="Il Presidio Rivombroso sorveglia il margine occidentale della Foresta di Elwynn, dove la strada prosegue nelle Marche Occidentali. La paralisi politica a Roccavento lascia gran parte dell'esercito all'estero o bloccato dalla burocrazia, e gli avamposti di confine come questo sono a corto di truppe. Il Vicesceriffo Rainer organizza la difesa all'esterno della torre con le poche forze a disposizione.\n\nGli gnoll Zampafiume e i ladri erranti minacciano le strade locali. Rainer dipende dai viaggiatori di passaggio e dagli avventurieri mercenari per mantenere sicuri i sentieri della foresta."},{t="La strada verso le Marche Occidentali",b="Il Vicesceriffo Rainer tiene d'occhio il branco Zampafiume e mette in guardia i viaggiatori da Boccalarga, il famigerato capotribù gnoll. Porta anche notizie delle terre tormentate oltre il fiume. Il caos al confine di Elwynn ha origine nelle campagne senza legge delle Marche Occidentali, quindi invia volontari capaci oltre il confine ad aiutare Gryan Stoutmantle e la People's Militia in difficoltà."}},faq={{q="Chi è il Vicesceriffo Rainer?",a="Il Vicesceriffo Rainer è un ufficiale dell'Esercito di Roccavento di stanza al Presidio Rivombroso, sul margine occidentale della Foresta di Elwynn. Sovrintende alla sicurezza delle strade e assolda avventurieri per combattere le minacce nelle vicinanze.",al={"rainer elwynn","chi e rainer","ufficiale del presidio rivombroso"}},{q="Perché il Presidio Rivombroso è a corto di personale?",a="Gran parte dell'Esercito di Roccavento è schierata altrove, e il disordine politico nella capitale impedisce ai rinforzi regolari di raggiungere le regioni periferiche. Il Maresciallo Dughan, a Borgodoro, deve affidarsi ad avventurieri indipendenti per aiutare Rainer.",al={"perche non ci sono guardie a presidio rivombroso","perche il presidio e in difficolta","presidio rivombroso ha bisogno di aiuto"}},{q="Quali minacce cerca di contrastare Rainer?",a="Rainer cerca di contenere gli gnoll Zampafiume nei boschi a sud del presidio, i ladri erranti e Boccalarga, il famigerato capotribù gnoll che assale i viaggiatori lungo il confine.",al={"quali nemici ci sono vicino a presidio rivombroso","gnoll zampafiume presidio rivombroso","gnoll presidio rivombroso"}},{q="Dove invia gli avventurieri Rainer dopo aver eliminato gli gnoll?",a="Dopo che gli gnoll nei pressi del presidio sono stati respinti, Rainer invia avventurieri esperti oltre il confine occidentale, nelle Marche Occidentali. Lì aiutano Gryan Stoutmantle e la People's Militia a Guardiacolle.",al={"dove andare dopo rainer","missione rainer marche occidentali","dopo presidio rivombroso"}}},fx={b3def1b5={q="A chi fa capo il Vicesceriffo Rainer?",a="Rainer riferisce al Maresciallo Dughan, comandante delle forze di guarnigione a Borgodoro. Collabora anche oltre il confine con Gryan Stoutmantle e la People's Militia nelle Marche Occidentali, indirizzando a ovest i combattenti più esperti per aiutare la loro lotta contro la Fratellanza dei Defias.",al={"a chi fa capo rainer","legami di rainer","a chi riferisce rainer"}},["8453208a"]={q="Da che parte sta il Vicesceriffo Rainer?",a="Rainer è un leale ufficiale dell'esercito di Roccavento, al servizio del Regno di Roccavento e dell'Alleanza. Di stanza al Presidio Rivombroso, risponde al Maresciallo Dughan a Borgodoro e si impegna a proteggere le marche occidentali di Elwynn dal caos incombente.",al={"fazione del vicesceriffo rainer","a chi presta servizio rainer","rainer è dell'alleanza"}},b0214c4a={q="Cosa vuole il Vicesceriffo Rainer?",a="Rainer vuole trovare volontari capaci che difendano il confine occidentale della Foresta di Elwynn. Con l'esercito impegnato su troppi fronti, vuole ridurre il branco aggressivo di gnoll Zampafuriosa a sud, mettere al sicuro le rotte commerciali dai ladri e porre fine alla minaccia di Boccalarga.",al={"cosa vuole rainer","obiettivi del vicesceriffo rainer","cosa chiede rainer"}},["5835f036"]={q="Perché il Vicesceriffo Rainer si trova qui?",a="Rainer è di stanza al Presidio Rivombroso per sorvegliare il confine tra la Foresta di Elwynn e le Marche Occidentali. Mentre bestie e banditi si riversano verso est attraversando il fiume, lui fa la guardia fuori dalla torre di guardia, coordina le pattuglie e recluta viaggiatori per difendere la frontiera.",al={"perché rainer è al presidio rivombroso","perché il vicesceriffo rainer è qui"}}},fp="13,195,26.476.0,20.344.0,21.179.0,38.229.0,41.178.0,61.203.0"}
P.entries["npc:devrak"] = {n="Devrak",s="A Crocevia, Devrak tiene pronti i cavalcavento dell'Orda per i voli attraverso Kalimdor. Trasporta corrieri e rifornimenti tra Durotar, Mulgore, gli avamposti di frontiera e le capitali dell'Orda.",h="A Crocevia, Devrak tiene pronti i cavalcavento dell'Orda per i voli attraverso Kalimdor.",kw={"savane","crocevia","devrak","maestro di volo","orgrimmar","picco del tuono","wind rider","viverna"},ang={["faction:Horde"]="Per gli avventurieri dell'Orda che percorrono Kalimdor, Devrak è un alleato fidato e un collegamento centrale tra i territori di orchi, troll e tauren.",["race:Orc"]="Nel cuore arido delle Savane, Devrak mostra l'abilità di un orco nel lavorare con i cavalcavento di Kalimdor, stringendo legami con le feroci bestie per assicurarsi il dominio dei cieli."},sec={{t="Custode dei posatoi di Crocevia",b="A Crocevia, Devrak accudisce i cavalcavento che collegano i lontani possedimenti dell'Orda. L'avamposto sorge dove si incontrano le principali rotte commerciali di Kalimdor, esposto al sole e vulnerabile a verrospini, centauri ed esploratori dell'Alleanza. Qui i voli rapidi sono essenziali. Devrak affida viaggiatori esperti e messaggeri alle prime armi a cavalcavento addestrati per attraversare la savana e raggiungere le montagne di Mulgore o i canyon di pietra di Durotar."},{t="Rifornimenti per il Capoguerra e il Gran Capo",b="Devrak aiuta a trasportare i rifornimenti dalla frontiera. I cacciatori delle Savane portano carne e pelli, e lui aiuta a inviarle ai fuochi da cucina di Orgrimmar e ai conciatori di Picco del Tuono. Presenta i nuovi corrieri ai maestri di volo dei vari continenti, mantenendo aperta una rotta aerea verso i territori centrali dell'Orda."},{t="Un posatoio letale",b="A Crocevia, Devrak non si limita ad accudire le bestie. Quando l'insediamento viene attaccato, richiama viverne infuriate perché colpiscano gli intrusi con pungiglioni velenosi e artigli. Il suo posatoio è un bersaglio pericoloso per chiunque lo attacchi."}},faq={{q="Qual è il ruolo di Devrak a Crocevia?",a="Devrak è il maestro di volo dell'Orda a Crocevia, nelle Savane. Accudisce i cavalcavento dell'avamposto, offre rotte di volo verso gli insediamenti collegati in tutta Kalimdor e coordina il trasporto di corrieri, soldati e merci.",al={"chi è devrak","cosa fa devrak","lavoro di devrak","maestro di volo di crocevia"}},{q="Dove può portarmi in volo Devrak?",a="Da Crocevia, Devrak ti collega a capitali come Orgrimmar e Picco del Tuono e agli avamposti di frontiera a Valtetra, sulle Vette di Petrartiglio, ad Acquemorte, a Millepicchi e lungo le frontiere meridionali. Devi prima aver parlato con quei maestri di volo.",al={"percorsi di volo di devrak","destinazioni dei voli da crocevia","rotte di volo di crocevia"}},{q="Quali missioni offre Devrak?",a="Devrak aiuta i giovani avventurieri dell'Orda a conoscere la rete di volo, inviandoli con carne fresca da Gryshka a Orgrimmar e con fasci di pelli a Picco del Tuono.",al={"missioni di devrak","missione di volo di crocevia"}},{q="Come si difende Devrak se Crocevia viene attaccata?",a="Quando gli incursori dell'Alleanza o le bestie ostili attaccano Crocevia, Devrak può richiamare viverne infuriate in suo aiuto. Le creature respingono gli assalitori con zanne e artigli.",al={"devrak può combattere","uccidere devrak","difesa di devrak"}},{q="Perché è così importante avere un maestro di volo a Crocevia?",a="Le Savane sono la spina dorsale dei collegamenti di Kalimdor centrale. Con Crocevia che collega Durotar, Mulgore, Valtetra e Stonetalon, il posatoio di Devrak permette all'Orda di spostare rapidamente le truppe e coordinare i rifornimenti senza giorni di viaggio a piedi.",al={"perché il maestro di volo di crocevia è importante","importanza della posizione di crocevia"}},{q="Di quali creature si occupa Devrak?",a="Devrak si occupa dei cavalcavento, chiamati anche viverne. Questi predatori alati e draconici delle vette e degli altopiani di Kalimdor hanno stretto amicizia con l'Orda, diventando affidabili cavalcature volanti sui terreni impervi.",al={"quali cavalcature ha devrak","cavalcature di crocevia"}}},fx={a0427f27={q="Da che parte sta Devrak?",a="Devrak è un orgoglioso membro dell'Orda. Di stanza nel cuore di Kalimdor, al Crocevia, serve il Capoguerra mantenendo aperte le vitali rotte aeree di rifornimento tra i territori degli orchi e dei tauren. Trasporta corrieri, rifornimenti e guerrieri per tutta The Barrens e oltre.",al={"devrak è dell'orda","fazione di devrak","chi serve devrak"}},bd507e24={q="Che cosa vuole Devrak?",a="Devrak si concentra sul mantenimento delle vitali linee di rifornimento dell'Orda nel Kalimdor centrale. Si affida ai viaggiatori perché consegnino beni essenziali, come pelli conciate e carni conservate, a capitali importanti come Orgrimmar e Picco del Tuono, assicurandosi che i cavalcavento dell'insediamento siano sempre pronti e che lo sforzo bellico sia ben sostenuto.",al={"qual è l'obiettivo di devrak","obiettivo di devrak","di cosa ha bisogno devrak"}}},fp="6,198,31.424.0,43.297.0,14.224.0,40.237.0,24.266.0,30.156.0,61.162.0,60.234.0,34.190.0"}
